-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[67110]="你被|cFFFF0000|Hspell:150381|h[劲射]|h|r击杀了。注意在芬里斯施放该技能前跑开！"
D.Strings[67111]="请带上它继续战斗吧，它象征着我对你的感激之情。让它的火焰与你一起将你敌人烧成灰烬吧。"
D.Strings[67112]="我们是唯一能够收集这些碎片并释放它的人。"
D.Strings[67113]="快点干，蠢货！"
D.Strings[67114]="快点挖！"
D.Strings[67115]="我们需要更多的投石！"
D.Strings[67116]="我需要更多的石头，否则我就去报告图格尔。"
D.Strings[67117]="你真没用！"
D.Strings[67118]="快点，否则我还打你！"
D.Strings[67119]="这个很卖力。"
D.Strings[67120]="你在偷懒吗？"
D.Strings[67121]="要是我还有力气战斗该多好……"
D.Strings[67122]="这些该死的食人魔！"
D.Strings[67123]="要不是你，我就死定了。"
D.Strings[67124]="我都已经不抱获救的希望了。"
D.Strings[67125]="感谢你的义举。"
D.Strings[67126]="我还以为死定了呢。"
D.Strings[67127]="你有一颗真正的战士之心！"
D.Strings[67128]="我来攻击他们的侧翼！"
D.Strings[67129]="我来啦，雷神氏族的懦夫们！"
D.Strings[67130]="以斧之名！杀呀！"
D.Strings[67131]="杀光敌人！"
D.Strings[67132]="有两道足迹往北边去了。看起来是一个食人魔带着一个女人，肯定是他的俘虏。"
D.Strings[67133]="哼！你们两个别吵了！"
D.Strings[67134]="感谢你分享的情报，游侠。"
D.Strings[67135]="很好，我们这就出发。联盟会坚定地站在你的人民身后。"
D.Strings[67136]="啊，$n！你来了！"
D.Strings[67137]="射得好！趁他们还没有发起反击，我们快离开这儿。抓紧了！"
D.Strings[67138]="霜狼的白痴，居然来攻击食人魔。 "
D.Strings[67139]="我要把你的脑袋留作纪念，德雷克塔尔。"
D.Strings[67140]="接受耻辱，承认失败吧。我会给你个痛快的。"
D.Strings[67141]="我去仓库那儿侦察一下，好制定出摧毁它的计划。"
D.Strings[67142]="我准备好了，我会从安全的坦克里支援你的。"
D.Strings[67143]="我看到钢铁部落的援军已经在路上了。伊瑞尔正在穿越车站往东北方跑。我们最好快点跟她汇合。"
D.Strings[67144]="让我们看看能不能刺激一下苟克，让他来协助我们。"
D.Strings[67145]="我们解开了你的束缚，并带来了礼物。"
D.Strings[67146]="好的，小家伙们，我们要一起碾碎他们！"
D.Strings[67147]="你的警卫太松懈了，酋长。我在村子里抓住了这些间谍。"
D.Strings[67148]="他们已经迟了。俘虏都被送去痛楚堡垒了。"
D.Strings[67149]="他们的鲜血将召唤出黑暗之星，并使我成为钢铁部落的神！"
D.Strings[67150]="酋长看重的是行动，而非言语，暗影法师。"
D.Strings[67151]="封锁出口！不要让这些德莱尼活着离开！"
D.Strings[67152]="他已经同意了。来吧，$n，让我们骑到苟克背上去。"
D.Strings[67153]="我们有着共同的敌人。我在此谦卑地请求你伸出援手。让我们共同消灭他们。"
D.Strings[67154]="雷神……我让你失望了……"
D.Strings[67155]="苟克，格鲁尔之子，戈隆的王子，我是伊瑞尔，请听我说。"
D.Strings[67156]="我看到了你的未来，贾拉克。它可不太妙。"
D.Strings[67157]="来吧，$n。让我们来说服苟克帮助我们摧毁这个地方。"
D.Strings[67158]="下去解放矿洞？骑上你们的狼跟我来，我知道一条近路。"
D.Strings[67159]="你可以从这里下到矿洞和竞技场，勇士。"
D.Strings[67160]="亲爱的……"
D.Strings[67161]="够了！就让你们这些狡猾的德莱尼暂且留着那座神殿吧。"
D.Strings[67162]="钢铁部落还会回来的！"
D.Strings[67163]="我得到前面去，为反击部队开辟一处集结点。"
D.Strings[67164]="对钢铁部落放尊重点，再加把劲儿，废物。"
D.Strings[67165]="残次品。"
D.Strings[67166]="你的鲜血将带给我黑暗之星的力量。跟我回沙兹古尔吧！"
D.Strings[67167]="把俘虏押到沙兹古尔去。"
D.Strings[67168]="让我们去阻止布莱克松吧！"
D.Strings[67169]="你成功了！阻止我前进的瘟疫已经消散了。现在，我们可以开始着手干扰亡语者布莱克松的仪式了。你准备好之后，就在前头带路吧。"
D.Strings[67170]="仆从们，过来！"
D.Strings[67171]="你们……已经……迟了。亚门纳尔将在我的死亡中获得新生……"
D.Strings[67172]="影月兽人爬上了悬崖！他们在干什么！？"
D.Strings[67173]="影月氏族进攻了？我从没见过他们这么暴戾。我们必须反击！"
D.Strings[67174]="英雄，我知道你有很多疑问，因为你并不属于这个世界。"
D.Strings[67175]="耐奥祖想用这个观星台召唤“黑暗之星”，正是这个暗影生物遮蔽了这片天空。"
D.Strings[67176]="我们无法阻止他。但是，我们或许可以在它降临时净化黑暗。"
D.Strings[67177]="这片山谷里沉眠着六块上古水晶。如果我们能在黑暗降临前激活它们……那就还有希望。"
D.Strings[67178]="这些兽人亵渎了卡拉波的圣洁。他们的攻击到此为止了！"
D.Strings[67179]="愿圣光指引我们的道路！"
D.Strings[67180]="卡拉波万岁！"
D.Strings[67181]="阿瑞菲奥！火力掩护我们！"
D.Strings[67182]="游侠们！搭箭……"
D.Strings[67183]="技师们，破坏那些坦克！"
D.Strings[67184]="如你所愿，先知大人。"
D.Strings[67185]="阿卡玛，塔尔洛！让他们看看德莱尼的力量！"
D.Strings[67186]="燃烧军团无穷无尽！"
D.Strings[67187]="在燃烧军团面前，你们毫无机会！"
D.Strings[67188]="你们逃不出燃烧军团的手心！"
D.Strings[67189]="|TInterface\\Icons\\spell_fire_elementaldevastation.blp:20|t |cFFF00000|Hspell:150678|h[熔岩之核]|h|r 使%s施放了一次|cFFF00000|Hspell:150682|h[熔岩蔽天]|h|r！"
D.Strings[67190]="$n，你跟我来。"
D.Strings[67191]="大地之力……赐予我力量吧！"
D.Strings[67192]="我的身躯……将回归……沼泽……"
D.Strings[67193]="我现在明白你为什么要来德拉诺了，外来者。你不属于这里——但你是怀着高尚的目的而来。"
D.Strings[67194]="我们的道路有着不同的起点和终点，外来者。但它们还会再次交汇。带着纳鲁的祝福前进吧。"
D.Strings[67195]="我要你留在地面吸引那些兽人的注意力，好让我专心寻找罗姆尔。"
D.Strings[67196]="你确定这玩意儿安全吗？"
D.Strings[67197]="好的……看起来还算稳定。现在，只要激活——搞定了！"
D.Strings[67198]="要是你看到哪个炸弹机器人熄火了，只需要狠狠踢上几脚，它们就会重新动起来。"
D.Strings[67199]="我们得行动了。还要多久？"
D.Strings[67200]="给我点时间让我想想！我正在处理碎片呢。"
D.Strings[67201]="黑石氏族的首领很容易辨认。你只要在战场上找身材最魁梧、嗓门最大、长相最丑的兽人就是了。"
D.Strings[67202]="|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t %s的|cFFF00000|Hspell:150734|h[脱缰烈焰]|h|r的威力达到了巅峰！"
D.Strings[67203]="难以置信，我真的被他们击落了。我发誓，要不是罗姆尔一直在我耳边大吼大叫，我们几个小时前就能回到观星台了。"
D.Strings[67204]="我们得激活那块水晶。但我们也不能坐视这些兽人继续建造攻击卡拉波的武器。"
D.Strings[67205]="比起自己的生命，侏儒似乎对他们的发明更感兴趣。但愿那个发明家真能帮上我们的忙吧。"
D.Strings[67206]="我实在无法信任链爆。$b$b他看起来很真诚，他的心中也充满了光明，可有些电线明显是他用泡泡糖黏合起来的。"
D.Strings[67207]="以阿迦玛甘之名，去死吧！"
D.Strings[67208]="伟大的野猪之神，赐予我力量吧！"
D.Strings[67209]="水晶告诉我，今天我们必胜。"
D.Strings[67210]="大地的碎片，刺瞎他们！"
D.Strings[67211]="阿迦玛甘之血，烧死他们！"
D.Strings[67212]="你就这么急着来送死吗？"
D.Strings[67213]="让我们看看，你要怎么抵挡来自扭曲虚空的灼热风暴吧！"
D.Strings[67214]="你们应该感到荣幸，蠢货！你们的鲜血将滋养艾泽拉斯的毁灭者，阿库麦尔！"
D.Strings[67215]="入侵者闯入了沼泽！把他们赶回去！"
D.Strings[67216]="给我盯紧了。如果有人侥幸逃过一劫，你们就得立刻上去干掉他们。"
D.Strings[67217]="我绝不容许失败。"
D.Strings[67218]="散开。我要知道那架飞机上到底是什么人。"
D.Strings[67219]="真差劲，你管这叫焊接？再加把劲。"
D.Strings[67220]="把那边拉紧。我可不希望看到它的轮子在战斗时掉了。"
D.Strings[67221]="给我用点力气。"
D.Strings[67222]="小心点！你得把它焊接到主轴上去。"
D.Strings[67223]="快点挖。"
D.Strings[67224]="卖力点。"
D.Strings[67225]="继续挖，没用的废物！"
D.Strings[67226]="谢谢你们，英雄们！"
D.Strings[67227]="他们想拿我们去喂阿库麦尔那头野兽。地牢深处还有更多的囚犯。求求你们，救救他们！"
D.Strings[67228]="入侵者？！快把囚犯转移走！他们的血肉属于巴赛尔大人。"
D.Strings[67229]="下来吧，英雄们！这水绝对没问题。哈哈哈哈哈哈！！！"
D.Strings[67230]="%s恐惧地逃跑了！"
D.Strings[67231]="我们得回去向维伦报告了。"
D.Strings[67232]="你可以随便挑一架塞林制造的旋翼机返回观星台。"
D.Strings[67233]="我得说，他的发明一开始用起来很恐怖，但最终却是十分欢乐。"
D.Strings[67234]="噢……我就知道你会来的。"
D.Strings[67235]="不！啊啊啊啊……"
D.Strings[67236]="英雄们，快到救赎之地里去，让你们的身躯重焕生机！"
D.Strings[67237]="挖，你这蛆虫！快挖！"
D.Strings[67238]="这辆货车比你们的贱命还要值钱！"
D.Strings[67239]="来，加把劲儿！"
D.Strings[67240]="钢铁部落的战争机器足以倾覆诸国，而你们这些蠢货却连一个雪堆都翻不过去？！"
D.Strings[67241]="给我拼命挖！"
D.Strings[67242]="你的铲子跟影月兽人一样无力！你是想在雪地上画出一个小圈吗？也许还要点几根蜡烛，祈祷轮子能乖乖地自己滚出来？！"
D.Strings[67243]="他们派给我的到底是不是真兽人！"
D.Strings[67244]="百发一中！"
D.Strings[67245]="我的野猪会碾碎你们！"
D.Strings[67246]="刺穿他们！"
D.Strings[67247]="踩死他们！"
D.Strings[67248]="让多罗戈看看，你们这些懦夫是有多喜欢滚烫的石头！"
D.Strings[67249]="让石头碾碎你们吧！"
D.Strings[67250]="我要把石头浸在岩浆里！"
D.Strings[67251]="这些石头很烫哦！"
D.Strings[67252]="石头都热得烧起来啦！"
D.Strings[67253]="你喜欢这块石头吗？！"
D.Strings[67254]="火石越多越好！"
D.Strings[67255]="如果懦夫害怕石头，那懦夫也害怕多罗戈！"
D.Strings[67256]="抓住那家伙！"
D.Strings[67257]="跑吧，小东西！哈哈！"
D.Strings[67258]="%s阴险的笑声在你的脑海中回荡着。"
D.Strings[67259]="抵抗我的魔法是毫无意义的，加摩拉！你很快就会屈服在我的力量之下。然后，我就会把你的怒火倾泻到这些多管闲事的英雄们头上！"
D.Strings[67260]="等等！还不到时候！不……"
D.Strings[67261]="守住那道路障！我不想看到任何一个兽人穿过这些防线。"
D.Strings[67262]="卡拉波是不会陷落的！"
D.Strings[67263]="挡住这些乌合之众。我们要比他们更加坚韧！"
D.Strings[67264]="我们要寸土必争！坚守岗位！"
D.Strings[67265]="我现在感觉好多了。"
D.Strings[67266]="我得回去战斗了。"
D.Strings[67267]="谢谢你，牧师。"
D.Strings[67268]="我还以为自己死定了呢。谢谢你，治疗者。"
D.Strings[67269]="这样就行了。谢谢你。"
D.Strings[67270]="感谢圣光，多亏你来了。你救了我的命。"
D.Strings[67271]="不……萨玛拉！"
D.Strings[67272]="耐奥祖，住手！你想干什么？"
D.Strings[67273]="奴隶们！不想死的都给我打！"
D.Strings[67274]="我们需要一些耳目，游侠可以帮助我们。"
D.Strings[67275]="圣光从不动摇。我们必将获胜！"
D.Strings[67276]="是的……很好。影月谷周围有四块阿肯尼特水晶，那是从我们飞船上落下来的古老残片。"
D.Strings[67277]="我还以为我们永远不会用到它们的力量，但这一天还是来了。拿上我的法杖，为我去收集它们的能量。"
D.Strings[67278]="好了，再给我一点时间……"
D.Strings[67279]="我的技师们花了一年的时间才制造出了为卡拉波的护盾提供能量的那对水晶。$B$B它们的出现是一个无与伦比的成就，而它们的损毁，则是彻头彻尾的浪费。$B$B沉睡在影月谷各处的那四块阿肯尼特水晶是几个世纪前制造的，但它们或许仍然能发挥作用。"
D.Strings[67280]="这里还有敌人。所有人，拿起武器！"
D.Strings[67281]="勇士，解救俘虏或许能拖延耐奥祖的计划，但我们需要全部四块水晶的力量才能挫败他的阴谋。"
D.Strings[67282]="%s重重地叹了一口气。"
D.Strings[67283]="没有光明照不透的黑暗。"
D.Strings[67284]="真正的献祭应是自愿的奉献。艾米的献祭只是一个冷血的契约。它只会引发最糟糕的魔法。真正的献祭源自于灵魂、源自于无私的目标、源自于对他人最纯粹的善意。这种献祭才能够带来奇迹。"
D.Strings[67285]="看看我的力量吧，地狱咆哮酋长。有我的氏族相助，你将百战百胜。"
D.Strings[67286]="伊瑞尔……我最亲爱的姐妹……"
D.Strings[67287]="出来吧，布罗克！"
D.Strings[67288]="强大的吞噬者，来接受这份来自肃霜的祭品吧！"
D.Strings[67289]="嘿，出来吧！"
D.Strings[67290]="出来，我们这儿有食物！"
D.Strings[67291]="肃霜食人魔向你纳贡！出来吧！"
D.Strings[67292]="大虫子！"
D.Strings[67293]="我们总在不断探索。"
D.Strings[67294]="睁大眼睛，保持警惕。危机就潜伏在沼泽之中。"
D.Strings[67295]="你好，$n。先知维伦跟我说过你的事迹。"
D.Strings[67296]="我对影月氏族特别感兴趣。我相信，只要更深入地了解他们的历史，我们就能更好地理解他们。"
D.Strings[67297]="要想打败你的敌人，首先得了解他们。"
D.Strings[67298]="在所有的兽人氏族中，影月氏族似乎是最盛行神秘主义，也最迷信的。"
D.Strings[67299]="影月氏族与我们和平共处了数百年。只是最近，我们发现他们的敌对行为开始多了起来。"
D.Strings[67300]="影月兽人都是强大的施法者。我完全不了解他们的魔法，但这才是最有趣的部分。"
D.Strings[67301]="我对影月兽人的特殊魔法很感兴趣。他们最强大的法术似乎都牵涉到某种鲜血契约，也就是——献祭。"
D.Strings[67302]="只要价钱合适，我什么都能干。"
D.Strings[67303]="我的队伍是这附近最棒的。我们从不失手。"
D.Strings[67304]="我们的斥候遍布整个沼泽和森林。影月兽人的一举一动都在我们的严密监控之下。"
D.Strings[67305]="勇士！专心攻击那个……怪物！我来保护其他人。"
D.Strings[67306]="吞噬者布罗克需要给养！把肃霜食人魔喂给它吃！"
D.Strings[67307]="布罗克从投喂区攫取了%s！"
D.Strings[67308]="英雄们！我需要你们的帮助！"
D.Strings[67309]="你们太迟了！仪式已经开始了。"
D.Strings[67310]="亚门纳尔必将重生！"
D.Strings[67311]="唔——哼——没错，来吧！我要把你们铐起来。"
D.Strings[67312]="蠢货！你们流的血越多，阿库麦尔就越容易崛起！"
D.Strings[67313]="让红龙军团的力量治愈你们的伤口！"
D.Strings[67314]="任何黑暗都阻挡不了生命的缚誓者的力量。"
D.Strings[67315]="我们成功了。我会把这个护命匣藏好的。亚门纳尔再也不能控制野猪人或威胁卡利姆多了。"
D.Strings[67316]="卡拉波不仅是一座神殿，更是一座堡垒。"
D.Strings[67317]="我们之前击退过兽人的攻击，但这支部队的规模之大却是前所未见的。"
D.Strings[67318]="我会死守卡拉波的——哪怕是要我付出生命的代价。"
D.Strings[67319]="你必须击败指挥官沃尔卡。他就在那儿，卡拉波的大门前。"
D.Strings[67320]="那是我的荣幸！守备官们，跟我上战场！"
D.Strings[67321]="我们可以团结起来，阻止亡语者布莱克松的计划。我们必须快一点，仪式就快完成了！"
D.Strings[67322]="<一个孤零零的兽人旅行者躺在雪地里，显然是被饥饿的极地狼杀死的。从他的装备上判断，他是打算在严酷的环境中进行一次长途旅行的。$B$B他的长袍前襟上缝着一个用皮带捆扎的卷轴，一端还晃荡着一个毛茸茸的小饰品。>"
D.Strings[67323]="拿起卷轴。"
D.Strings[67324]="谢谢你能这么快赶来。我恐怕必须请你为卡利姆多再冒一次险。$B$B亚门纳尔的学徒，亡语者布莱克松想将他的主人召回生者的国度！我们必须尽快赶到荆棘螺旋，在仪式完成前击败他。$B$B我们必须齐心协力，只有这样，我们才有可能阻止得了他！"
D.Strings[67325]="我还以为亚门纳尔已经被消灭了。"
D.Strings[67326]="我也以为寒冰之王亚门纳尔已经被消灭；这真是个严重的错误。我到底是有多糊涂，居然忘了巫妖的真正力量是在他们的护命匣里。"
D.Strings[67327]="护命匣？"
D.Strings[67328]="像亚门纳尔这么强大的亡灵法师都会将自己的灵魂储存在一个物理容器里，好让自己通过特定的仪式重生。$B$B我真该搜遍卡利姆多找出亚门纳尔的护命匣，可之前的胜利让我有些自满了。$B$B现在，我们之前的努力恐怕都要白费了。"
D.Strings[67329]="骷髅在源源不断地涌来，瘟疫在洞穴中翻滚。我该怎么阻止仪式？"
D.Strings[67330]="我知道亡语者布莱克松的最新造物，麦什伦。它的每一次呼吸都在喷吐着瘟疫，他还召回了火眼莫德雷斯，让他帮忙召集亡灵。$B$B就连亡首教徒都在帮助布莱克松。他们的魔灵师制造出了一个由獠牙和瘟疫组成的怪物，一头名为阿鲁克斯的巨型蜘蛛。$B$B如果你能击败这些敌人，驱散挡住道路的问题，我们就能爬上荆棘螺旋，击败亡语者布莱克松，并夺回亚门纳尔的护命匣了。"
D.Strings[67331]="<这个兽人在冻死之前，似乎在这里宿营过几天。她的眼中凝结着悲伤，直直地望向西南方的冰原。$B$B她的胸口藏着一封折叠整齐的信件。>"
D.Strings[67332]="拿起信件。"
D.Strings[67333]="你必须阻止他们！他们都疯了！"
D.Strings[67334]="我们绝不能让奥金顿沦陷！"
D.Strings[67335]="谢谢你，陌生人。我欠你一条命。"
D.Strings[67336]="谢谢你。我要回大门那里去了。"
D.Strings[67337]="我还以为自己完蛋了呢。谢谢你！"
D.Strings[67338]="<她到断气前的那一刻，还在等着他。>"
D.Strings[67339]="<他愿意抛弃一切，与她在一起。>"
D.Strings[67340]="%s平静了下来，看来已经做好上战场的准备了。"
D.Strings[67341]="集中精神，杀了它。"
D.Strings[67342]="别让那头畜生离开你的视线。"
D.Strings[67343]="盯住你的猎物……射击！"
D.Strings[67344]="%s在召唤援军！"
D.Strings[67345]="我将……回归大地……"
D.Strings[67346]="摧毁虚空碎片，别让它们与%s融合！"
D.Strings[67347]="你们休想夺走我的荣耀！"
D.Strings[67348]="愤怒的兽人小崽子！"
D.Strings[67349]="你竟敢独自来挑战食人魔。"
D.Strings[67350]="他们会结果了你，小独狼。"
D.Strings[67351]="你的族人会塞满我的奴隶围栏…… "
D.Strings[67352]="你太迟了，蠢货。碎梦者的计划已经接近完成了。"
D.Strings[67353]="我们很快就能让传送门包围整个奥金顿。可惜你无法亲眼见证那一刻了。"
D.Strings[67354]="赫尔默，撕碎他们的灵魂。"
D.Strings[67355]="这伤势很严重。如果能让我烧灼一下，或许可以止血。"
D.Strings[67356]="入侵者还活着？！拦住他们！绝对不能让他们干扰了仪式！"
D.Strings[67357]="剃刀永垂不朽。"
D.Strings[67358]="灵魂指引我的利刃！"
D.Strings[67359]="我们……还没完……"
D.Strings[67360]="伊瑞尔根本就没来过。我担心她出事了。$B$B我不能再失去她了，$n。"
D.Strings[67361]="钢铁部落只是在试探我们。他们还会再来的，而且会带上更多的部队。"
D.Strings[67362]="水晶又出故障了。我们真正需要的是来自塔拉多的高品质水晶。$B$B这些老旧的部件已经没法再凑活了。"
D.Strings[67363]="为了保卫神殿，我们牺牲了上千条生命，而我们的城墙也屹立至今。"
D.Strings[67364]="什么？罗姆尔，你得去搞定它。我会给你派援军的。"
D.Strings[67365]="生命即圣光，圣光即生命。它们可以互相转换并保持守恒。"
D.Strings[67366]="噢，嗨。你需要什么吗？"
D.Strings[67367]="你一定就是塔尔洛说的$r，我们一直在等你。"
D.Strings[67368]="你一定就是那个傲慢的德莱尼人，塔尔洛说的那个$c。$B$B看你这个样子，我们就要有乐子瞧了！"
D.Strings[67369]="我要让你的杂牌军血流成河！"
D.Strings[67370]="快杀死赫尔默的魔血，阻止他再生！"
D.Strings[67371]="没有什么能比兽人更让我痛恨的了，除了黑石兽人！"
D.Strings[67372]="无礼的跳蚤！让你们见识这座堡垒中的力量——"
D.Strings[67373]="戈尔隆德是个严酷的地方。我很高兴你能来，$n。"
D.Strings[67374]="伊瑞尔始终没有出现，她失踪了。$B$B我很担心她，但我更担心玛尔拉德知道了这个坏消息之后的反应。$B$B无论如何，我想我们最好尽快离开这里。"
D.Strings[67375]="我很高兴你能来。我可不想一个人去。"
D.Strings[67376]="他们好像弄来了一个恶心的大家伙。"
D.Strings[67377]="一共有三个食人魔和一个德莱尼；从足迹上看，应该是个女性。幸存者往北方去了。如果有新发现，我会告诉玛尔拉德的。"
D.Strings[67378]="她不让我跟你去。但我可以用自己的魔法投影来帮你……"
D.Strings[67379]="在所有可能出问题的地方里，最有可能的就是卡拉波的护盾。$B$B不，这肯定不是共振参数故障。也不会是阿肯尼特水晶坏了。$B$B肯定就是那个保护着全影月谷最大的德莱尼城市的护盾出了问题！"
D.Strings[67380]="要是我让那个护盾成为卡拉波毁灭的原因，那我就更没脸见人了。$B$B我们必须激活那些阿肯尼特水晶，马上！"
D.Strings[67381]="我得说，其他大技师对如何修复城市护盾完全没有概念。$B$B要是没有了我，他们该怎么办？"
D.Strings[67382]="我妻子总说我应该放松一点。"
D.Strings[67383]="影月谷里的阿肯尼特水晶是在大约三百年前，我们刚来到德拉诺时从飞船残骸上散落下来的。$B$B它们至今仍然能够运转，是德莱尼科技发达的最好明证。"
D.Strings[67384]="我已经尽快赶来了。你找到他们的首领了吗?"
D.Strings[67385]="火炮准备！"
D.Strings[67386]="稳住！"
D.Strings[67387]="稳住，小伙子们！"
D.Strings[67388]="等它上来！"
D.Strings[67389]="就来了！"
D.Strings[67390]="火力全开！"
D.Strings[67391]="狠狠揍他们，小伙子们！"
D.Strings[67392]="把他们送回地狱去！"
D.Strings[67393]="伊格纳乌斯！保护我！"
D.Strings[67394]="|TInterface\\Icons\\spell_arcane_blast:20|t %s正准备对$n施放|cFFFF0000|Hspell:151273|h[奥术射击]|h|r！"
D.Strings[67395]="有了你，拦路的食人魔就少多了。我会保护这些兽人的安全的。"
D.Strings[67396]="他们就交给我吧，我们在外面碰头。"
D.Strings[67397]="高尔考什往东南边的补给仓库去了。"
D.Strings[67398]="什……啊啊啊啊！！"
D.Strings[67399]="呃……啊啊啊！！"
D.Strings[67400]="哇啊啊！"
D.Strings[67401]="我来拿炸药包，你负责战斗。说定了？"
D.Strings[67402]="这具可怕的尸体面部被硬挤出微笑的表情。他的胸甲上写着：“我们总算逗笑他们了……”"
D.Strings[67403]="我们不会再受你们奴役了！"
D.Strings[67404]="我会振作起来，与你并肩作战的！"
D.Strings[67405]="为了不那么悲惨的未来！"
D.Strings[67406]="听从心灵的召唤！"
D.Strings[67407]="好好干！"
D.Strings[67408]="快点干，小矮子！"
D.Strings[67409]="谁都没资格炸毁我的村庄！没有人！卡兹或许可以。但其他人都不行！"
D.Strings[67410]="卡兹呢？"
D.Strings[67411]="放开我，我要跟你们的狼主谈谈。"
D.Strings[67412]="我……感觉……好多了！你做出了正确的选择！现在，我可以去听听你们的狼主有什么话说了。"
D.Strings[67413]="幸存下来的嘲颅兽人应该都在这儿了。我们得把他们弄出去。"
D.Strings[67414]="你去摧毁外墙，我来对付守卫！"
D.Strings[67415]="嗨，你准备好了的话我就宣布比赛开始了。"
D.Strings[67416]="是的，请开始。"
D.Strings[67417]="如果我们不能尽快多杀掉一些鬣蜥人，这些家伙很快就会忘记我们是谁。"
D.Strings[67418]="这世界将陷入火海！"
D.Strings[67419]="大主教，我们得将碎片送到安全的地方。奥金顿已经岌岌可危！"
D.Strings[67420]="暂时满足之后，布罗克喷出了一块大石头。"
D.Strings[67421]="我们坚持不了多久。快行动吧，$n！"
D.Strings[67422]="这具嘲颅兽人的尸体熊熊燃烧着，已经没救了。"
D.Strings[67423]="这个兽人似乎是在进餐时遭到了袭击。"
D.Strings[67424]="你感觉这个兽人在你靠近时还看了你一眼，但他显然已经死了。"
D.Strings[67425]="可悲的软蛋。"
D.Strings[67426]="贾格巴，粉碎他们的意志！"
D.Strings[67427]="阿格姆，瞄准眼睛！"
D.Strings[67428]="大主教……我……看到他们中有一个人往暗影墓穴去了。"
D.Strings[67429]="奥金顿安全了……但只是暂时的。不幸的是，我感觉我们依然任重道远。"
D.Strings[67430]="小心点，$n。如果你发现了那座传送门的踪迹，那么墓穴里一定有着极其邪恶的东西在等着你。"
D.Strings[67431]="包围圈被打破了！来吧，兄弟姐妹们——把这些兽人赶出卡拉波！"
D.Strings[67432]="你们一定要相信我。我们也曾被燃烧军团追杀着跨越虚空。我们是来阻止他们继续扩张的。"
D.Strings[67433]="他们对我们的态度同样如此。我们没时间来搞氏族间的内讧了。"
D.Strings[67434]="嘲颅兽人都是杀手和疯子。杜隆坦，我不建议你这么做。"
D.Strings[67435]="他们或许很疯狂，但他们是唯一熟悉这片蛮荒之地的兽人氏族。我们或许要依赖他们的知识。"
D.Strings[67436]="你该在出发前，再去跟尼娅米谈谈。"
D.Strings[67437]="你最好别把那玩意儿洒在你的衣服上。你也知道，恶魔的血液都是污秽的。"
D.Strings[67438]="这是怎么工作的？"
D.Strings[67439]="笨蛋轮子！快动起来！"
D.Strings[67440]="你要是再不转，我可要打你了！"
D.Strings[67441]="用餐时间！"
D.Strings[67442]="我们把这个兽人献给你，布罗克！"
D.Strings[67443]="来得正是时候！我正愁没有食人魔可杀呢……"
D.Strings[67444]="他们的首领似乎是往暗影墓穴去了，大人。我可以把这个邪教徒的脑袋砍下来了吗？"
D.Strings[67445]="不行，麦拉。我们已经决定放弃那种作风了。让他多活一会儿吧。"
D.Strings[67446]="我的朋友们会缠住你们的。"
D.Strings[67447]="我还需要一点时间，好好招待我的客人们。"
D.Strings[67448]="我特意为那个原祖荆兽留了一手。我要用它来噎死这个恶棍。"
D.Strings[67449]="我要把这些植物人都烧成灰，再把灰洒在肉排上喂给野猪吃，最后再把那头野猪架在火上烤！$b$b现在，我就要动手了。"
D.Strings[67450]="你很容易着火？那你最好多洒点水在身上。否则你会把一切都搞砸的。"
D.Strings[67451]="这就是戈尔隆德。这里的天空、大地和水随时都会燃烧。我们可以擦出第一颗火星了吗？"
D.Strings[67452]="燃气的试炼"
D.Strings[67453]="推动"
D.Strings[67454]="很好，这样就行了。"
D.Strings[67455]="逃跑的机会来了！"
D.Strings[67456]="快跑啊！"
D.Strings[67457]="泥土和石缝里都会流出最黑的水，你可别喝它。"
D.Strings[67458]="戈尔隆德的大地物产丰富。它的地下会喷出气体，你可别把它当成蒸汽了。这鬼东西跟明火可不太对路。"
D.Strings[67459]="原油的试炼。"
D.Strings[67460]="黑石的试炼。"
D.Strings[67461]="戈尔隆德的真正考验：黑石。小心那些会喷火的石头。"
D.Strings[67462]="你必须完成全部三个试炼。现在，你就从中先选一项吧。"
D.Strings[67463]="你学到了什么？"
D.Strings[67464]="要敬畏元素。"
D.Strings[67465]="要小心挑选武器。"
D.Strings[67466]="戈尔隆德很危险。"
D.Strings[67467]="错！你应该明白，戈尔隆德的任何问题都可以用一场大爆炸来解决！"
D.Strings[67468]="今天，卡拉波依然屹立。"
D.Strings[67469]="啊哈哈哈哈！*咳嗽*呵呵。*咳嗽*你们……没打中我。钢铁部落的渣滓！"
D.Strings[67470]="答应我，让我去复仇吧！"
D.Strings[67471]="我要碾碎我的敌人，看着他们在我面前逃散……"
D.Strings[67472]="我怀念风暴之前的清风气息……"
D.Strings[67473]="你不会死的，勇士！"
D.Strings[67474]="让圣光治愈你的伤口！"
D.Strings[67475]="圣光庇护着它的勇士。"
D.Strings[67476]="谢谢你，$n。我们在暮光林地见。"
D.Strings[67477]="等你完成之后，把尸体留下，带上他们的面具，去嘲颅废墟找我。"
D.Strings[67478]="<悄声地>嘿，等等。我可不想进去。我感觉我们的小伙子们恐怕都完了。"
D.Strings[67479]="计划上没有你。"
D.Strings[67480]="太迟了。你们的防御工事完了。"
D.Strings[67481]="很好。一个挑战。"
D.Strings[67482]="更多的附带伤害。"
D.Strings[67483]="你的营地就快完蛋了。"
D.Strings[67484]="无所谓。我们的下一发炮弹会……"
D.Strings[67485]="动起来！你这臭烘烘的畜生！"
D.Strings[67486]="我才不在乎你的搭档是死是活，畜生！我们还有一场战争要打！"
D.Strings[67487]="起来，畜生！你害我在黑石氏族面前丢脸了。"
D.Strings[67488]="进入|cFF00FF00|Hspell: 150665|h[救赎之地]|h|r以打破%s的|cFFFF0000|Hspell:150679|h[灵魂榨取]|h|r"
D.Strings[67489]="快击败伊格纳乌斯以移除戈尔索格的护盾！"
D.Strings[67490]="戈尔索格受到了|cFFFF0000|Hspell:151217|h[元素过载]|h|r的影响！快干掉他！"
D.Strings[67491]="救命啊！谁来救救我！"
D.Strings[67492]="感谢……圣光……我找到你了。"
D.Strings[67493]="泰尔莫……攻击……"
D.Strings[67494]="他们……恶魔……"
D.Strings[67495]="嘲颅兽人！杜隆坦，我们得离开这儿，不要暴露行踪。"
D.Strings[67496]="什么？！谁？是谁干的？"
D.Strings[67497]="告诉我，杂种！沃匹尔上哪儿而去了？"
D.Strings[67498]="你这是在浪费自己的时间……我们已经赢了。"
D.Strings[67499]="这边，$n，拿一些炸药。你只需要把它们放在一架战争机器前面……然后拔腿就跑！"
D.Strings[67500]="我也不清楚自己有什么期待。"
D.Strings[67501]="这些农夫根本不值得对付。"
D.Strings[67502]="谁还敢笑？"
D.Strings[67503]="那门巨灵火炮的破坏力比我们想象的还要大。"
D.Strings[67504]="呃。他们留着这玩意儿干什么？"
D.Strings[67505]="*咳嗽*呵呵……*咳嗽**喘气*"
D.Strings[67506]="肮脏的……*咳嗽*……钢铁部落渣滓！"
D.Strings[67507]="那……*咳嗽*那是什么……*咳嗽*好烫……*喘气*"
D.Strings[67508]="够了，麦拉！我命令你住手。"
D.Strings[67509]="放开他，给他点儿水。圣光的追随者是不能做这种事的。"
D.Strings[67510]="好吧，莉亚德琳。我愿意说……并以此来换取自由。"
D.Strings[67511]="*咳嗽*我……爆炸！*咳嗽*"
D.Strings[67512]="该死的钢铁部落渣滓……*咳嗽*作弊！"
D.Strings[67513]="看看钢铁部落的真正力量吧！"
D.Strings[67514]="钢铁将遮蔽天空！"
D.Strings[67515]="快看！着火了！"
D.Strings[67516]="非常好。那么，你们的营地在哪儿？"
D.Strings[67517]="就在奥金顿的正西方，泰尔莫的北边。"
D.Strings[67518]="那都无所谓。泰尔莫的传送门是有防护的。你们休想找到大师。"
D.Strings[67519]="我可是戈尔隆德最强大的魔荚人。跟紧我。我会保护你的。"
D.Strings[67520]="去死吧，疯子！"
D.Strings[67521]="那你就一起来吧。"
D.Strings[67522]="呵呵！呵呵！哇哈哈！哈哈！哈哈！"
D.Strings[67523]="是否邀请贾格哈里？"
D.Strings[67524]="刺刀时间！"
D.Strings[67525]="士兵们——快来帮我！"
D.Strings[67526]="汉瑟尔，达坎……我们走！让我们去击溃钢铁部落。复仇的时刻到了！"
D.Strings[67527]="呸。你太谨慎了。那我就召集战士自己干！"
D.Strings[67528]="堡垒归我们了！来吧兄弟——我们继续进攻！"
D.Strings[67529]="报告！我发现了一个幸存者！"
D.Strings[67530]="这里还有人活着！"
D.Strings[67531]="我这里有一个活人！"
D.Strings[67532]="帮帮我。我太虚弱了……我需要水。"
D.Strings[67533]="将泥水涂在贾格哈里的叶子上，帮助他恢复元气。"
D.Strings[67534]="是否救助贾格哈里？"
D.Strings[67535]="嗷嗷嗷！"
D.Strings[67536]="不，贾纳尔。我们现在孤立无援，只能固守。"
D.Strings[67537]="莽撞的家伙！"
D.Strings[67538]="明智的选择，$n。我们在车队那儿见！"
D.Strings[67539]="O're atal'sha！为了圣光！"
D.Strings[67540]="我们是不会放弃的！"
D.Strings[67541]="前进！为了卡拉波！"
D.Strings[67542]="我明白了……氏族的祖先是禁止使用虚空魔法的。那耐奥祖为什么要打破这一古老的律法？"
D.Strings[67543]="活活烧死你们！"
D.Strings[67544]="尝尝烈焰的滋味吧！"
D.Strings[67545]="我要点燃你脚下的大地！"
D.Strings[67546]="钢铁部落……会……杀光你们……"
D.Strings[67547]="奥金顿的卫士们，肃清这片区域！"
D.Strings[67548]="先祖的灵魂，解除这片土地的苦难吧！"
D.Strings[67549]="我发誓，我绝不会让我们的灵魂再受到折磨！"
D.Strings[67550]="不要！我不想就这么死掉！！！"
D.Strings[67551]="献祭完成了！赐予我力量吧，阿库麦尔！啊哈哈哈哈！！！"
D.Strings[67552]="我得照看一下这里。我们集结点见。"
D.Strings[67553]="亡棘家族一定会为自己挑衅贾格哈里的举动后悔的！"
D.Strings[67554]="我的盾牌！给我！"
D.Strings[67555]="发现恶魔能量。正在净化。"
D.Strings[67556]="正在处理邪能。待机中。"
D.Strings[67557]="净化模组已激活。"
D.Strings[67558]="目标完成。指示使用者到准备区汇合。完毕。"
D.Strings[67559]="爆炸规模比预期得还要大。黑手一定会很满意的。"
D.Strings[67560]="一发炮弹就能毁灭一个氏族。啊哈哈哈哈。"
D.Strings[67561]="从今往后，嘲颅氏族就再也笑不出来了。"
D.Strings[67562]="巨灵火炮的测试完美成功。我们终于可以全力生产这种武器了。"
D.Strings[67563]="我早就告诉过指挥官应该先开炮。嘲颅氏族这次可怜的垂死挣扎本来是完全可以避免的。"
D.Strings[67564]="事实证明，一旦巨灵火炮可以移动之后，钢铁部落就能够全力打击那些臭烘烘的霜狼废物了。"
D.Strings[67565]="起来，畜生！起来战斗！"
D.Strings[67566]="我是不会纵容你在钢铁部落面前丢我的脸的！"
D.Strings[67567]="拿出点羞耻心来，你这肮脏的畜生！让我们给他们看看，雷神氏族是凭什么在钢铁部落占据一席之地的！"
D.Strings[67568]="食人魔进攻了！"
D.Strings[67569]="他们反攻了！"
D.Strings[67570]="我们还有很多事要做，塔尔洛，先保证部队得到妥善治疗和充分休息吧。"
D.Strings[67571]="呸！该让我的野兽回忆回忆怎么杀人了。"
D.Strings[67572]="看来我的野兽今晚能饱餐一顿了！"
D.Strings[67573]="|cff71d5ff|Hspell:149587|h[比赛完成]|h|r"
D.Strings[67574]="放置共鸣水晶"
D.Strings[67575]="我要用这根棍子狠抽亡棘家族的脸！"
D.Strings[67576]="贾格哈里？快滚，不然我杀了你！"
D.Strings[67577]="他死了？很好！"
D.Strings[67578]="隔离"
D.Strings[67579]="卫兵！别废话了，快开打！"
D.Strings[67580]="试炼完成！"
D.Strings[67581]="试炼失败！"
D.Strings[67582]="你作弊！"
D.Strings[67583]="我来阻止他们！"
D.Strings[67584]="我们会让他们付出代价的！"
D.Strings[67585]="我的奴隶！那都是血槌的财产！"
D.Strings[67586]="贾格哈里？你已经被放逐了。你怎么还敢回来！"
D.Strings[67587]="贾格哈里？你已经被放逐了。你怎么还敢回到我们的土地上来！"
D.Strings[67588]="别害怕。我保护你。"
D.Strings[67589]="亡棘家族死定了！！"
D.Strings[67590]="幸好我在这儿。我保护你。"
D.Strings[67591]="放逐？我让他们看看什么才叫放逐。"
D.Strings[67592]="贾格哈里？你这个小矮子。你以为你真能打败我吗?"
D.Strings[67593]="哇！我抓住他了！你看到了吗？！"
D.Strings[67594]="你们害得苏克没抓到传奇守护螃蟹！苏克要把你们片成鱼片！"
D.Strings[67595]="玛尔拉德比以前更暴躁了。他非常担心伊瑞尔。"
D.Strings[67596]="你看见我的那辆坦克了吗？那是我最棒的作品。"
D.Strings[67597]="汉瑟尔妻子的遭遇太可怕了，所以他才会这么恨兽人。"
D.Strings[67598]="达坎很神秘。德莱尼游侠都是这副德行。"
D.Strings[67599]="很高兴你能来。如果不能摧毁钢铁部落的巨型战争机器，我们就死定了！"
D.Strings[67600]="啊！别伤害我！"
D.Strings[67601]="这不是我的错！是$n逼我这么干的！"
D.Strings[67602]="自从我们的大王死后，棘花部落就四分五裂了。$b$b亡棘家族和他们的团伙驱逐、杀害了所有敢于挑战他们的魔荚人。$b$b他们说亡棘家族是新的首领？他们自称是棘花的新大王？我们走着瞧！"
D.Strings[67603]="我们已经没有立足之地了吗？"
D.Strings[67604]="他们先是抛弃了我们，现在又要来清剿我们。"
D.Strings[67605]="诅咒阿兰卡！"
D.Strings[67606]="唔。我是不是闻到$g古龙水:香水;的味道了？"
D.Strings[67607]="拖住他们！别让他们过去！"
D.Strings[67608]="撤回圣殿去，巴赛尔大人的仪式绝对不能受到干扰！苏克，别让他们过去！"
D.Strings[67609]="苏克要守护者的宝藏！"
D.Strings[67610]="钢铁部落赢了。帮我把这玩意儿解开，我们得离开这儿！放弃村子！"
D.Strings[67611]="噢，求求你，你一定要在多米尼娜献祭掉其他人之前把他们救出来！"
D.Strings[67612]="你准备好之后就跟我来吧。"
D.Strings[67613]="呵呵，这边。这边，呵呵。"
D.Strings[67614]="哇哈哈哈哈呵呵呵呵……这边走。"
D.Strings[67615]="最古老的神器统统属于我们！你无权得到它们！"
D.Strings[67616]="不……棱镜……"
D.Strings[67617]="呸！我讨厌山洞；在这里头，我啥都看不清了。"
D.Strings[67618]="没错。而且这里还充斥着下等种族的臭气。"
D.Strings[67619]="想要逃跑的奴隶只有一个下场。"
D.Strings[67620]="求求你，不要！我再也不跑了！"
D.Strings[67621]="我将是你最可怕的梦魇……"
D.Strings[67622]="嘿！他想要捅我！我早就跟你说了，我们不能相信嘲颅兽人。"
D.Strings[67623]="断肢忘了要保持礼貌。我看见了漂亮兽人。我想看看她会不会跳舞。抱歉抱歉。"
D.Strings[67624]="我是来追杀钢铁部落的。我可以毁掉你们残存的村庄，或许我们也可以互相帮助。"
D.Strings[67625]="用你的生命去保卫沼泽！"
D.Strings[67626]="你证明了对我氏族的忠诚，有做大事的能力。"
D.Strings[67627]="我们对刀塔堡垒的控制很薄弱，我最好的几个战士又跟着我那鲁莽的兄弟走了。 "
D.Strings[67628]="你在与多罗戈一战中展现出的技巧让我记忆犹新。"
D.Strings[67629]="要是你能继续与我们并肩战斗，那将是我的荣幸。"
D.Strings[67630]="所以，这就是他们要找的东西……谢谢你帮我开路。"
D.Strings[67631]="<这个棱镜依然散发着温和的能量。它看起来依然可以使用，但原本以它作为能源的那个古怪机器——可能是某种毁灭性武器，或是某种卑劣的刑具——看来已经完全毁坏了。>"
D.Strings[67632]="摧毁那个邪恶的棱镜！我们不能冒险让它落入他们的手里。"
D.Strings[67633]="阿库麦尔，杀光他们！"
D.Strings[67634]="看看，我的鱼人们给我引来了多么珍贵的宝贝啊。"
D.Strings[67635]="现身吧，阿库麦尔，来享用你的祭品吧！"
D.Strings[67636]="抱歉我骗了你，但我必须利用它来引起你的同情，才能让你去对付凯里克斯。"
D.Strings[67637]="我以为他会把你蒸发掉，结果你却轻松地干掉了他。令人难忘的一战……"
D.Strings[67638]="你成功了。它又开火了！"
D.Strings[67639]="我见过那场爆炸。我亲眼看见的。元素们尖叫着，它们聚合的精华被生生撕裂，转化成毁灭的武器。这种武器就不应该存在！"
D.Strings[67640]="嘲颅氏族同意帮忙了。"
D.Strings[67641]="我很久以前见过嘲颅兽人。在我印象里，他们还要再高大一些。"
D.Strings[67642]="一切都准备好了。"
D.Strings[67643]="东西你都拿到了吗？"
D.Strings[67644]="强大的杜隆坦居然孤身一人下山来了。看来你是活得不耐烦了。"
D.Strings[67645]="铁血意志，非胜即死！"
D.Strings[67646]="让钢铁部落吞噬你。"
D.Strings[67647]="钢铁部落是不可阻挡的！"
D.Strings[67648]="来啊，$r废物。来受死吧！"
D.Strings[67649]="虽然……进入矿洞是你自己的决定，这真的引起了我的兴趣。你想要揭开袭击背后的真相。"
D.Strings[67650]="<咳嗽>需要泥水……在山上……<咳嗽>"
D.Strings[67651]="在临死之前……我恨你……"
D.Strings[67652]="哇……我还是很震惊。$b$b我真的很吃惊。$b$b你到底要不要我帮忙？我很肯定，你会需要的。"
D.Strings[67653]="……轮子……"
D.Strings[67654]="是谁竟敢干扰我的献祭？！杀了他们！"
D.Strings[67655]="我的血肉将归于上古之神……"
D.Strings[67656]="我就知道你们会来找我的。现在，我可以开开心心地砍掉你们的脑袋了！"
D.Strings[67657]="我拖延的这点时间已经足够了……阿库麦尔必将崛起……"
D.Strings[67658]="苏克……想要……守护者……宝藏！"
D.Strings[67659]="啊，这些了不起的勇士们要千里迢迢赶回家去了。"
D.Strings[67660]="没准我们还会再见的，对吧？"
D.Strings[67661]="<呸！>躲得好。"
D.Strings[67662]="我想我最好也来帮忙。你觉得一个又瞎又老的战士还会有用吗？"
D.Strings[67663]="你们还没赢呢，蠢货。现身吧，阿库麦尔！"
D.Strings[67664]="你们太迟了，英雄们，阿库麦尔的召唤仪式已经完成了。"
D.Strings[67665]="不幸的是，你们活不到见证他荣耀的那一刻了。干掉他们！"
D.Strings[67666]="在临死之前，英雄们，请认清这一点：阿库麦尔必将吞噬这个世界！"
D.Strings[67667]="你根本不配被阿库麦尔所吞噬。我们的祭品会把你撕成碎片。"
D.Strings[67668]="我们的先驱，阿库麦尔已经从深渊中现身。你将有幸成为第一个被他吞噬的生物。"
D.Strings[67669]="麦什伦要玩黏糊糊！"
D.Strings[67670]="你弄疼麦什伦了……"
D.Strings[67671]="啪嗒！"
D.Strings[67672]="压碎！"
D.Strings[67673]="你玩完儿了！"
D.Strings[67674]="哈！这只猎物太弱了。"
D.Strings[67675]="苏克钩住你了！"
D.Strings[67676]="这只猎物太丑了，没法吃。"
D.Strings[67677]="拉姆塔斯已经倒下了！我们必须保护长者！"
D.Strings[67678]="先知必将向我们屈膝……"
D.Strings[67679]="指挥官沃尔卡会带领我们走向胜利的……"
D.Strings[67680]="在……格罗玛尔……还有我们的……同胞……"
D.Strings[67681]="我们将一统诸氏族……杀光所有的敌人……"
D.Strings[67682]="别打了！求求你，快住手！别杀我！我投降！"
D.Strings[67683]="我会守护神殿，让它远离伤害。"
D.Strings[67684]="快去吧，$n！我来守住神殿大门！"
D.Strings[67685]="莫克鲁克砸扁你们！"
D.Strings[67686]="我要压扁你们这些小矮子！"
D.Strings[67687]="砸！砸！砸！"
D.Strings[67688]="尝尝这个，小矮子！"
D.Strings[67689]="哈哈，砸扁一个小矮子！"
D.Strings[67690]="小矮子被砸扁了！"
D.Strings[67691]="砸扁一切！"
D.Strings[67692]="我……被……砸扁了？"
D.Strings[67693]="奴隶不干活，统统砸扁！"
D.Strings[67694]="咿咿呀！"
D.Strings[67695]="吱吱！"
D.Strings[67696]="吱吱喳！"
D.Strings[67697]="喳喳吱吱！"
D.Strings[67698]="亚门纳尔即将归来！"
D.Strings[67699]="我们征服卡利姆多的圣战已经开始，谁都无法逃过我们的怒火！"
D.Strings[67700]="你将成为比矿工更好的柴火！"
D.Strings[67701]="啊啊啊啊啊！！！！！！！"
D.Strings[67702]="求你，救救我们！我们好不容易才逃出了暮光之锤的祭坛。"
D.Strings[67703]="鲁特瞪着你思考了一会——然后对着一片火腿打了个响鼻。"
D.Strings[67704]="鲁特边摇尾巴边流口水；要不是它还同时放屁打嗝，这个样子还是挺可爱的。"
D.Strings[67705]="要抚摸鲁特吗？"
D.Strings[67706]="啊！！不……"
D.Strings[67707]="我来做你的护盾！"
D.Strings[67708]="点燃它！为了鲁克玛的荣耀！"
D.Strings[67709]="清除这些异教徒！"
D.Strings[67710]="什么？你说过这个营地很安全的！"
D.Strings[67711]="我这里有很多奴隶可供挑选。事实上，我刚刚抓住了一个泼辣的德莱尼女人，没准你会感兴趣的。"
D.Strings[67712]="我听说你跟那些……你是怎么称呼他们的来着？矮人？那种肮脏的小东西。总之听说你跟他们不怎么对付。如果你有兴趣的话，我们这里也有几个待售的矮人。"
D.Strings[67713]="钢铁部落，铁矮人……真相配。买几个吧。哪怕没什么用，你也可以把他们装填到你们的战争机器里，把他们打回那个棱堡高地里去。"
D.Strings[67714]="皇家奴隶行会始终致力于与钢铁部落的亲密伙伴们发展友好关系。对你们，我可以给出最大的折扣和最好的奴隶。"
D.Strings[67715]="我们也不可避免地注意到了你们的战争机器“样品”。毫无疑问，棱堡高地很快就将不复存在了。我们很高兴能与钢铁部落结为朋友。"
D.Strings[67716]="这么快？我们昨天卖给你们的那批奴隶呢？没关系。我们还有。我们这儿有的是。"
D.Strings[67717]="先是消灭了嘲颅氏族，很快就轮到棱堡高地的这些小矮人了。钢铁部落还真是能征惯战啊。"
D.Strings[67718]="我这里有很多奴隶可供挑选。事实上，我刚刚抓住了一个危险的剑圣，没准你会感兴趣的。他很可怕，可以成为出色的战士。"
D.Strings[67719]="我听说你们跟嘲颅氏族之间的争端已经结束了。如果你有兴趣的话，我们这里也有几个幸存的嘲颅兽人。"
D.Strings[67720]="毫无疑问，钢铁部落肯定会买下我们剩下的那些嘲颅兽人的。哪怕没什么用，你也可以把他们装填到你们的战争机器里，做射击练习。"
D.Strings[67721]="我们也不可避免地注意到了你们的战争机器“样品”。嘲颅村庄的毁灭给我们留下了很深的印象。我们很高兴能与钢铁部落结为朋友。"
D.Strings[67722]="我们还要奴隶！"
D.Strings[67723]="我们这儿多得是买奴隶用的黑石！"
D.Strings[67724]="你的奴隶死得太快了。我们要更好的奴隶，食人魔！"
D.Strings[67725]="你的废话太多了。少说话，多来点奴隶！"
D.Strings[67726]="要不要我们拿巨灵火炮对着你的奴隶围栏来一炮？！"
D.Strings[67727]="你的奴隶价格太高，死得又太快！"
D.Strings[67728]="所有人都会感受到钢铁部落的强大。要是你们的奴隶还没有改观，那食人魔也不例外！"
D.Strings[67729]="你的奴隶全死光了！我干嘛还要买？"
D.Strings[67730]="我相信我们是可以达成互惠互利的协议的。"
D.Strings[67731]="当然，当然，我的朋友。不用担心。"
D.Strings[67732]="不用担心，我的朋友。我们一定会向你们提供最强壮的奴隶的。"
D.Strings[67733]="当然，你说得对，我能干的兽人朋友。你说得太对了。"
D.Strings[67734]="我会加倍努力，解决你们所有疑虑的。"
D.Strings[67735]="钢铁狂潮将吞噬你！"
D.Strings[67736]="奴隶行会非常乐意满足你的要求。"
D.Strings[67737]="我完全同意。你什么时候想来看货，只要知会我一声就行了。"
D.Strings[67738]="不用生气。我们是朋友。我们非常尊重钢铁部落的力量。"
D.Strings[67739]="我那天撵上了一头裂蹄牛。啊哈哈。"
D.Strings[67740]="你修好那个破轮子了没有？"
D.Strings[67741]="你能让那玩意儿跑多快？能超过古魈吗？"
D.Strings[67742]="那是因为那头畜生站着没动。"
D.Strings[67743]="你摆弄好你那张丑脸了没有？"
D.Strings[67744]="我至少让它动起来了，总比你强。"
D.Strings[67745]="这是什么意思？！我可是皇家奴隶行会的高层！"
D.Strings[67746]="谢谢你们，勇敢的英雄们。没有你们的帮助，亚门纳尔就会重返艾泽拉斯，并带来难以言喻的恐怖灾难。$b$b我会把这个危险的神器带回去交给红龙军团的兄弟姐妹们。我们或许能找到摧毁它的方法。$b$b我欠你们一份人情。"
D.Strings[67747]="<钢铁部落的这支斥候小队似乎是在鸦人袭击阿鲁纳时被烧死的。>"
D.Strings[67748]="搜查尸体。"
D.Strings[67749]="稳住，该死的畜生！"
D.Strings[67750]="已经制住它了，你的借口对兽人来说毫无价值！"
D.Strings[67751]="我们要用这家伙把火炮拉出来。快点！"
D.Strings[67752]="你们的骨头也将被扔到这里！燃烧吧！"
D.Strings[67753]="感觉太热了吗？"
D.Strings[67754]="亚门纳尔的大军又多了一个士兵。"
D.Strings[67755]="你将和其他人一同起舞！"
D.Strings[67756]="享受死亡吧，凡人。黑暗之星在召唤！"
D.Strings[67757]="誓死效忠耐奥祖！"
D.Strings[67758]="又有灵魂送上门了！"
D.Strings[67759]="保持……集中……"
D.Strings[67760]="集中你的力量……"
D.Strings[67761]="它……太……强……"
D.Strings[67762]="岩石可没有提起过这个！"
D.Strings[67763]="谁都不准碰贝莎！"
D.Strings[67764]="别碰我的宝贝！"
D.Strings[67765]="不准那么看我的宝贝！不准！"
D.Strings[67766]="把我和……我的贝莎……埋在一起……"
D.Strings[67767]="我将在死后继续侍奉主人！"
D.Strings[67768]="我将回归大地……"
D.Strings[67769]="没错！我的血肉属于阿库麦尔！"
D.Strings[67770]="呃……我们会杀光你们……"
D.Strings[67771]="|cFFF00000斯拉格纳|r出现在熔岩之中！"
D.Strings[67772]="%s吐了一口血水。"
D.Strings[67773]="散开！不留活口！"
D.Strings[67774]="哇哈！我们成功了！真酷！"
D.Strings[67775]="我要回去找我父亲了。我们到那儿再见！"
D.Strings[67776]="圣光在上……它们正在灭绝这里的生命！"
D.Strings[67777]="阴影正在群峰之下滋长……"
D.Strings[67778]="艾斯卡将指引我们获得自由。"
D.Strings[67779]="我不会忘记这一切的。"
D.Strings[67780]="我们已经无处可逃了。"
D.Strings[67781]="卷土重来？我没问题。"
D.Strings[67782]="我想我能关闭它。给我一分钟！"
D.Strings[67783]="伙计，你要找银行吗？你可以沿着道路一直向北走，去奥格瑞玛。那里的守卫会帮助你的。"
D.Strings[67784]="路还长着呢，伙计。银行都在奥格瑞玛城里。沿着大路向北走就是，你不会找错地方的。"
D.Strings[67785]="想搭便车吗？波洛克就在镇子的南端，双足飞龙的边上。"
D.Strings[67786]="旅馆就在通向贫瘠之地的道路北边。格罗斯克会招待你的。"
D.Strings[67787]="想为你那些毛茸茸的动物朋友找个落脚的地儿吗？旅店外面的苏亚米能帮到你。"
D.Strings[67788]="你在找训练师吗，伙计？"
D.Strings[67789]="贾布可以帮你。这几年，他一直在负责新手德鲁伊的训练工作。"
D.Strings[67790]="啊，你在追寻魔法之道吗？安苏瓦能教你。你可以在兵营入口附近找到他。"
D.Strings[67791]="那你应该去找泰金。她大部分时间都呆在兵营里。"
D.Strings[67792]="伙计，你得去找兽人卡普拉克。他就在旅店南边的洞穴里。"
D.Strings[67793]="斯瓦特正在兵营里与元素沟通，就是镇子中央那座大房子。"
D.Strings[67794]="伙计，你居然对那种巫术感兴趣。算了，杜格鲁就在兵营后面。"
D.Strings[67795]="战士训练师，塔绍尔·锯痕就在镇子东边的兵营里。"
D.Strings[67796]="挥起锤子拿起钳，我来敲起这首歌……炉、炉火烧啊烧。"
D.Strings[67797]="你在找什么呢，伙计？"
D.Strings[67798]="手上用力敲，锤子……呃……嗷嗷叫，火星飞得高。"
D.Strings[67799]="臭气全炼掉，臭气全炼掉，铁里空气全跑掉。"
D.Strings[67800]="嘿！你不能进来！"
D.Strings[67801]="这是我的工坊！"
D.Strings[67802]="是谁竟敢打扰我打铁！"
D.Strings[67803]="要找卡普拉克吗？如果你要去找那个家伙，最好先捂紧自己的口袋。"
D.Strings[67804]="你们的土地必将被钢铁狂潮湮没。"
D.Strings[67805]="最近的银行在奥格瑞玛。沿着大路向北，你一定能看见那座雄伟的城门的。"
D.Strings[67806]="我们成功了！但愿我们能尽快净化水源，让庄稼恢复生长。"
D.Strings[67807]="波洛克就在镇子南端的双足飞龙附近。他能送你去想去的地方。"
D.Strings[67808]="格罗斯克和他的旅店就在剃刀岭的西北角。"
D.Strings[67809]="苏亚米就是你要找的人。他就在旅馆外面。"
D.Strings[67810]="贾布训练过很多新手德鲁伊，或许他也能帮到你。"
D.Strings[67811]="你想狩猎更大型的猛兽吗？或许索塔尔能教会你想要的知识。他就在剃刀岭西南角的洞穴里。"
D.Strings[67812]="你在追寻魔法的知识。安苏瓦能教会你很多东西，快去剃刀岭兵营的入口北边找他吧。"
D.Strings[67813]="泰金就在兵营里，就是镇子里最大的那座建筑。"
D.Strings[67814]="你该去找卡普拉克。他就在剃刀岭西南部的洞穴里。你一定要盯紧他，一秒都不能放松。"
D.Strings[67815]="斯瓦特就在剃刀岭东侧的兵营里。"
D.Strings[67816]="杜格鲁·血怒就躲在镇子东侧的兵营后面练习他的巫术呢。"
D.Strings[67817]="如果你想找个人对练，可以去镇子东边的兵营里找塔绍尔·锯痕。"
D.Strings[67818]="愿大地母亲时刻护佑你，旅行者。你想找什么呢？"
D.Strings[67819]="就快成功了。坚持住！"
D.Strings[67820]="阻止他们！把他们变成奴隶！"
D.Strings[67821]="死亡是你唯一的选择。"
D.Strings[67822]="噢耶！到爸爸这儿来，你这个兽人杂种！"
D.Strings[67823]="我诅咒你，矮人！"
D.Strings[67824]="有人吗，快来啊！救命啊！"
D.Strings[67825]="让戈尔隆德的秃鹫吃掉你的骨头吧！"
D.Strings[67826]="你可以用食人魔身上的锁链和手铐捆住他。一想到那个场面，你就觉得充满了诗意。"
D.Strings[67827]="你会为那些难民丢掉性命的，蠢货。"
D.Strings[67828]="嗷！！"
D.Strings[67829]="快躲到阴影里去——有人来了。"
D.Strings[67830]="挡住克莉丝塔萨去路的瘟疫之雾开始消散了。"
D.Strings[67831]="这不安全，斯基克！趁他们还没看见你，快回你的笼子里去！"
D.Strings[67832]="我们的援军应该很快就会到了。快行动！"
D.Strings[67833]="你们必须每半小时向我汇报一次德莱尼人的动向。"
D.Strings[67834]="我们要杀光它们所有人，让这里血流成河。"
D.Strings[67835]="准备！"
D.Strings[67836]="先是钢铁部落摧毁了图雷姆，现在魔荚人也来了。到底还有完没完了？"
D.Strings[67837]="我们很快就会有水了，朋友们。我不会再让你们失望的。"
D.Strings[67838]="请快一点。要是她出了什么意外，我真不知道自己会做出什么事来。"
D.Strings[67839]="奴隶围栏里有一个德莱尼女人，我们昨天刚抓来的。我用她来换我的命行吗？"
D.Strings[67840]="这次是你占了上风，$r。下次你可不会再这么走运了。"
D.Strings[67841]="让我来照顾他吧，$n。其他人更需要你。"
D.Strings[67842]="永远困在黑暗之中……无法……逃脱……"
D.Strings[67843]="耐奥祖已不再听我们的了，他现在只听命于黑暗。"
D.Strings[67844]="你已经蹚过了灵魂之河，陌生人。你最好立刻回头。"
D.Strings[67845]="这里曾是一片祥和之地。永恒的安息之所……"
D.Strings[67846]="离开这里，外来者。它将成为你的葬身之地。"
D.Strings[67847]="我知道你能理解我的！我只想找回我的妻子！"
D.Strings[67848]="我们在那边见。我们要让那个兽人哀嚎！"
D.Strings[67849]="如果可以的话，我想请你帮个忙。如果你能帮忙找到这些东西，我们就能消灭那个怪物了。"
D.Strings[67850]="愿纳鲁保佑我们远离那些追踪我们跨越宇宙的恐怖恶魔。"
D.Strings[67851]="小心点，$r！魔荚人进攻了！"
D.Strings[67852]="马尔考罗克呢？！"
D.Strings[67853]="说！你们的首领在哪儿！"
D.Strings[67854]="我知道你肯定有份！你将为你对我的艾尔莎所做的一切付出代价，兽人！"
D.Strings[67855]="巨灵火炮会……"
D.Strings[67856]="卡舒尔宗母曾给我们讲过伟大的巨人——戈尔隆德的故事。$b$b它是世界有史以来最巨大的野兽。当它陨落时，它的身躯化为大地，脊椎形成山脉，鲜血化为矿石，它那狂野的意志统治着这片土地。$b$b这或许只是个炉边故事，但我能看出它是怎么来的。"
D.Strings[67857]="要想打败钢铁部落，我们就需要超出自身的力量。我希望这片土地能够给出我们想不到的答案。"
D.Strings[67858]="我认识其中的一些兽人。我们必须小心前进。要是让他们发现了我，那一定会有数不清的钢铁部落部队涌来，让我们应接不暇的。"
D.Strings[67859]="安图尔，我还记得你出生的那一天。愿你的灵魂安息。"
D.Strings[67860]="萨图是如此热爱这个世界。老友，愿你与万灵同行。"
D.Strings[67861]="拉尔库拉从没见过他的父母。他的生活一直很艰辛。愿他的灵魂能在奥金顿的殿堂中找到安宁。"
D.Strings[67862]="扎维一直很淘气。他最喜欢对朋友们恶作剧了。大家会记住你的，朋友。"
D.Strings[67863]="啊，萨姆恩。二十年来，他一直暗恋着一个名叫萨莉亚的女孩。他始终没能鼓起勇气去向她表白。"
D.Strings[67864]="他只是我要“质询”的众多兽人中的一个。"
D.Strings[67865]="好了，$n，我已经改写了它的程序。你需要按下这个遥控发射器。大家都做好准备！"
D.Strings[67866]="前方选手数量：0人。你取得了领先！"
D.Strings[67867]="前方选手数量：1人"
D.Strings[67868]="前方选手数量：2人"
D.Strings[67869]="前方选手数量：3人"
D.Strings[67870]="前方选手数量：4人"
D.Strings[67871]="前方选手数量：5人"
D.Strings[67872]="前方选手数量：多于5人"
D.Strings[67873]="剩下的事就交给我吧，勇士。你还是回阿卡玛那儿看看还有什么需要帮忙的吧。"
D.Strings[67874]="吉亚娜女士，她将自己的一生都献给了圣骑士的事业。愿你的灵魂安息。"
D.Strings[67875]="玛姬塔的兄弟们曾经打赌她举不起一头雷象。结果就是他们帮她干了一周的家务活。愿你与圣光同行，我的孩子。"
D.Strings[67876]="在城墙坍塌时，很多人都亲眼看见安娜卡是如何用自己的身体掩护她的战友的。你的事迹将被众人所铭记，姐妹。"
D.Strings[67877]="勇敢的卡缇。据说她向来英勇无畏。她还留下了两个年幼的孩子。"
D.Strings[67878]="阿弗恩，你的父母会为你的英勇而骄傲的。愿你的灵魂安息。"
D.Strings[67879]="马尔库斯，你总是对我笑脸相迎。愿你的灵魂安息。"
D.Strings[67880]="哈弗，你一个月前才刚刚加入守备官部队。愿你的灵魂安息。"
D.Strings[67881]="阿瓦之子，拉克姆。你还是个小孩子时，经常向我要糖吃。愿你的灵魂安息。"
D.Strings[67882]="加鲁尔是我曾经的学徒——娜尔娃的独子。他继承了他母亲的勇气。愿你与万灵同行，孩子。"
D.Strings[67883]="乌马特一直希望能成为一名教师。我们会永远记住你的，愿你与万灵同行。"
D.Strings[67884]="萨库尔早早就展现出了自己的预言天赋。你的牺牲是我们的重大损失。安息吧，我的兄弟。"
D.Strings[67885]="卡姆尔不顾他母亲的反对加入了城防军。你已经光荣地履行了自己的职责，兄弟，安息吧。"
D.Strings[67886]="巴鲁德帮忙建造了卡拉波的城墙。多亏了他的努力，卡拉波的外墙才能屹立至今。愿你与万灵同行。"
D.Strings[67887]="萨杜尔一直坚守在前门，直至援军抵达。愿你与圣光同在，兄弟。"
D.Strings[67888]="海默尔最近刚刚才迎来了自己的长子。他们会记住你的英勇的，兄弟。愿你与圣光同在。"
D.Strings[67889]="吉达追随他父亲的脚步加入了守备官部队。现在，愿你们的灵魂能在奥金顿重聚。"
D.Strings[67890]="布拉达，没有了你的声音，神殿也会感到孤寂。愿你与圣光同在，兄弟。"
D.Strings[67891]="阿姆特有六个兄弟，他们全都光荣地加入了卡拉波的守卫部队。他们会记住你的光荣事迹的，兄弟。"
D.Strings[67892]="提摩尔，一个安静又羞怯的孩子。你在战场上的表现十分英勇。你的事迹将被人们所铭记，孩子。"
D.Strings[67893]="安米特出生于塔拉多的一个农场。他是成年之后才拿起圣骑士的锤子来保卫我们的城市的。你的勇气将为人们所歌颂。"
D.Strings[67894]="梅鲁尔是他家族中的最后一个人。他没有结过婚，也没有孩子。你的名字将与你的荣誉一起被人们所铭记，战士。"
D.Strings[67895]="瓦兰的性格温和，但他今天也勇猛地挥起了自己的战锤。愿你与圣光同在，兄弟。"
D.Strings[67896]="从他的伤口来看，伊纳瓦是在十来名钢铁部落兽人的围攻下牺牲的。你的事迹将被众人所铭记，朋友。"
D.Strings[67897]="梅安妮，她是家中最小的孩子。她一直希望有一天能够走遍整个德拉诺。愿圣光与你同行，孩子。"
D.Strings[67898]="哈瑞妮，你出生的那一天，我还祝福过你。你可称得上是生的伟大，死的光荣，愿你安息。"
D.Strings[67899]="阿穆拉，她和法莉是双胞胎姐妹。愿你的灵魂获得安息。"
D.Strings[67900]="贝拉，她是我们最年轻的助祭之一。你的勇气毋庸置疑。愿你的灵魂获得安息。"
D.Strings[67901]="法薇最受孩子们的欢迎。他们会记住你的故事的。愿你的灵魂获得安息。"
D.Strings[67902]="娅娃，你的儿子们会记住他们的母亲在牺牲前的英勇表现的。愿你与万灵同行。"
D.Strings[67903]="科娃娜，她热爱写作。你的故事将被收入沙塔斯的大图书馆。愿你与万灵同行。"
D.Strings[67904]="瑞妲在医术上非常有天赋。她的牺牲是我们的重大损失。愿你与万灵同行。"
D.Strings[67905]="菲兰非常热爱音乐。她还是个小孩子时，经常唱歌给我听。愿你与万灵同行，孩子。"
D.Strings[67906]="佳鲁娜，你的牺牲是我们的重大损失。愿你与万灵同行。"
D.Strings[67907]="尤娜，她是个飞毛腿。她曾在日落之前从影月谷的一头跑到另一头。愿你能与奥金顿的勇士们一同尽情奔跑。"
D.Strings[67908]="塔瓦拉既聪明又健谈。愿圣光与你同在。"
D.Strings[67909]="莎芙塔和她的丈夫都参加了战斗。这对年轻的夫妻是如此的勇敢。愿圣光与你同在。"
D.Strings[67910]="兰荷尔，你的弓箭技巧无人能及。直到最后一刻，你的箭仍然是百发百中。愿圣光与你同在，勇士。"
D.Strings[67911]="娜薇妮是众多坚守在前线的学者之一。她的勇气在今天拯救了许多生命。愿圣光与你同行，勇士。"
D.Strings[67912]="楚米，我相信你的儿子们会成为出色的年轻人的。你的事迹将被众人所铭记，姐妹。"
D.Strings[67913]="奥兰娜的家人都死于钢铁部落的一次突袭。在那之后，她就拿起锤子加入了部队。但愿你的灵魂得到安息。"
D.Strings[67914]="艾芙特率领她的队伍破坏了钢铁部落的大量攻城武器。你的事迹将被众人所铭记，姐妹。"
D.Strings[67915]="筛选"
D.Strings[67916]="艾露薇和她的两个童年好友一起加入了守备官部队。他们会记住你的事迹的，孩子。"
D.Strings[67917]="快来帮我，你们这群野人！"
D.Strings[67918]="来帮帮我，钢铁狂潮！"
D.Strings[67919]="噢耶！烧死他们！"
D.Strings[67920]="达米在她的丈夫死于高烧之后，就潜心研究出了许多疾病的治疗方法。你的事迹将被众人所铭记，姐妹。"
D.Strings[67921]="金娜是个心直口快的姑娘。我相信，她在跟钢铁部落恶战时，肯定也狠狠地诅咒过他们。愿圣光与你同在。"
D.Strings[67922]="瓦安塔，你的勇气给我们所有人做出了榜样。愿圣光与你同在。"
D.Strings[67923]="芭莎对每一个人都像对待家人一样亲切。愿圣光与你同在，好姑娘。"
D.Strings[67924]="吉帕的家族指挥着我们的海军舰队。愿圣光与你同在，孩子。"
D.Strings[67925]="弗蕾塔的中队粉碎了钢铁部落对北部庭院的包围。你的勇气令我们钦佩。"
D.Strings[67926]="在第一波攻击的混乱之后，阿米塔召集起了正面城墙上的德莱尼。你的勇气令我们钦佩。"
D.Strings[67927]="在战斗打响时，卡维领头发起了第一波冲锋。他的英勇无畏激励了他的战友们。安息吧，勇士。"
D.Strings[67928]="这片战场上的许多守备官都是拉斯提尔一手训练出来的。今天，他给他的学生们做出了榜样。安息吧，兄弟。"
D.Strings[67929]="特鲁姆是怀着巨大的勇气战死沙场的。愿圣光与你同在。"
D.Strings[67930]="为了保护亲人，乌马特加入了卡拉波的守卫部队。愿圣光与你同在，兄弟。"
D.Strings[67931]="杰罗德是雷象骑兵队的领袖。愿圣光与你同在，勇士。"
D.Strings[67932]="金塔领导了对钢铁先遣站的冲锋。愿圣光与你同在，勇士。"
D.Strings[67933]="生命即圣光……圣光即生命。它们可以互相转换并保持守恒。"
D.Strings[67934]="<抓住他！>"
D.Strings[67935]="<你别想逃跑。>"
D.Strings[67936]="<它太强大了！>"
D.Strings[67937]="我不知道我们还能像这样坚持多久。$B$B我们大部分的庄稼都活了过来，并开始攻击我的雇农，我们收获的那一点点粮食完全不够养活从图雷姆涌来的难民。"
D.Strings[67938]="我们没有招、招惹过魔荚人……我、我们当时只是在把最后一批难民带去农场……"
D.Strings[67939]="在钢铁部落攻陷图雷姆时，是我在负责它的保卫工作。我们大多是志愿兵而非职业军人，但我仍然誓死保卫我们的家园。$B$B这里这些可怜的灵魂都是因我的失败而流离失所。我只希望自己不会再一次让他们失望。"
D.Strings[67940]="我们之间很有默契，你不觉得吗？$B$B那个原油机完全不是爆炸二人组——艾萝娜和$n——的对手！"
D.Strings[67941]="快一点，$n。我们得找到伊瑞尔！"
D.Strings[67942]="那些玩意儿的做工太差劲了，你只需要把它们搞乱就行了。"
D.Strings[67943]="现在，该去救我的爱人了。我绝不能再次失去她！来吧，我们走！"
D.Strings[67944]="功能已关闭。请参见操作手册第十卷第1014-1034页。"
D.Strings[67945]="啊噢。管道里有杂音。"
D.Strings[67946]="它不该发出那么大的噪声的。"
D.Strings[67947]="他们干嘛把管道铺设在这里？"
D.Strings[67948]="谁把阀门放那儿了？他们干嘛这么做？"
D.Strings[67949]="Lok'tar？还是睡觉？可能是睡觉。"
D.Strings[67950]="我很高兴你能来，$n。我们一起经历了许多事情。"
D.Strings[67951]="伊瑞尔还活着！那些肮脏的食人魔把她关押在奴隶营里。$B$B我们得摧毁这个地方，把她救出来！"
D.Strings[67952]="救命啊，谁来帮帮我！"
D.Strings[67953]="噢！它着火了！"
D.Strings[67954]="救救我，不然我死定了！"
D.Strings[67955]="一群小气鬼……"
D.Strings[67956]="火！烫！烫！烫！"
D.Strings[67957]="亲爱的……都结束了吗？"
D.Strings[67958]="是的，你们很安全。我不会离开你身边的。"
D.Strings[67959]="你，那边那个！帮个忙，塔布羊都跑啦！"
D.Strings[67960]="到处都是魔荚人！要是我去救它们，我也会送命的！"
D.Strings[67961]="格鲁尔之子，强大的苟克，向雷神氏族的戈隆追猎者戈娜卡屈膝吧！"
D.Strings[67962]="抱歉，你能大点儿声吧？你的锁链声把你的声音都盖住了。"
D.Strings[67963]="对我而言，你的名字就和其他死在强大的苟克手中的家伙一样，微不足道。我要碾碎你！"
D.Strings[67964]="我可以帮你找到你的朋友，只要你保证不杀我。"
D.Strings[67965]="安静，你这个蠢货！"
D.Strings[67966]="别笑了。你是想让我们都被抓住吗？"
D.Strings[67967]="别碰我，否则我就打断你的手。"
D.Strings[67968]="安静！附近有巡逻队。"
D.Strings[67969]="闭嘴！你想让别人听到吗？"
D.Strings[67970]="别笑了。安静！"
D.Strings[67971]="你干嘛要发出那么多噪声？你到底有没有试过怎么偷偷靠近别人？"
D.Strings[67972]="普尔，我要快点返回刀塔堡垒。"
D.Strings[67973]="我们走！"
D.Strings[67974]="让我来给她热热身……"
D.Strings[67975]="来吧，宝贝……"
D.Strings[67976]="这边走。前面有一个安全点，就在钢铁部落的设备外面。"
D.Strings[67977]="我认为首要任务就是去对付那个该死的巨型火炮。"
D.Strings[67978]="有谁提到“巨型火炮”了吗？"
D.Strings[67979]="我们很快就会行动的，但首要任务还是找到伊瑞尔。她就在这附近。"
D.Strings[67980]="达坎，你和我们的勇士已经出去侦察过了。你们发现了什么？"
D.Strings[67981]="……还没有确切的线索，守备官。"
D.Strings[67982]="我明白了。好吧，那我们只能……"
D.Strings[67983]="啊啊！！好多火！"
D.Strings[67984]="卡尔曼就在农场后面。我们走。"
D.Strings[67985]="他就在前面。"
D.Strings[67986]="卡尔曼，我和这位英雄在魔荚人的领地发现了钢铁部落的踪迹！"
D.Strings[67987]="魔荚人正在抢劫农场。我的女儿也失踪了。就让钢铁部落一起来吧。"
D.Strings[67988]="这个冒险者消灭了大部分的魔荚人。我们曾在卡拉波并肩战斗，兄弟。我们不能现在放弃。"
D.Strings[67989]="嗷！嘿！干嘛打我？！"
D.Strings[67990]="不！我要倒了！"
D.Strings[67991]="坦克叮呤当啷，劈啪作响地向前冲去。"
D.Strings[67992]="<开往厄隆绿洲。>"
D.Strings[67993]="它过来了！排好阵列！抓钩准备！"
D.Strings[67994]="我们进来了。用那些炸药去摧毁他们的地面部队吧。"
D.Strings[67995]="啊，昔日的影月谷！想不到还能见到这片森林。"
D.Strings[67996]="守备官阿卡玛！我刚从特鲁纳观星台过来。那里的族人遭到了袭击！"
D.Strings[67997]="我的姐妹萨玛拉就驻扎在观星台。我跟你一起去。"
D.Strings[67998]="告诉那个先知，他的时代结束了。黑暗降临了！"
D.Strings[67999]="我会派技师去保护北边的水晶的。"
D.Strings[68000]="那耐奥祖怎么办？我们就任由这个掳掠我们同胞的罪犯逍遥法外吗？"
D.Strings[68001]="耐心点，玛尔拉德。营救行动需要好好计划一番——在搞清楚族人的下落之前，千万不要贸然犯险。"
D.Strings[68002]="我们已经选错了一次。我不会让悲剧再次重演的。我不能任由我们的人民死去。"
D.Strings[68003]="我会盯着他的，导师。"
D.Strings[68004]="快啊，兄弟！让我们逃出这里，否则就太迟了！"
D.Strings[68005]="钢铁部落要求我们做出选择：加入，或者灭亡。"
D.Strings[68006]="我丈夫耐奥祖为了拯救氏族，加入了钢铁部落，但必须付出沉重的代价。"
D.Strings[68007]="他们说："
D.Strings[68008]="耐奥祖只能求助于寂静的虚空。他打破古老的律法，使用了黑暗之星的力量。"
D.Strings[68009]="我求他住手，但他拒绝回头。"
D.Strings[68010]="他打破了这块岩石，背弃了先祖。 "
D.Strings[68011]="我现在只能求你一件事，陌生人。"
D.Strings[68012]="你必须阻止耐奥祖。阻止他的疯狂行为，否则就迟了。"
D.Strings[68013]="这是什么？一个小$r？$B$B我要一个$r奴隶来干什么？"
D.Strings[68014]="很好，耐奥祖。我们即将攻打卡拉波。召唤黑暗之星吧。"
D.Strings[68015]="坚持住，萨玛拉。我这就去找维伦。他能救你的，坚持住！"
D.Strings[68016]="伊瑞尔……不要悲伤。我已经没有机会了，可你……你还有机会。"
D.Strings[68017]="坚强点，小家伙。我……我会守护着你的。"
D.Strings[68018]="不。不！！！"
D.Strings[68019]="萨玛拉，我发誓，我要变强。我要保护我们的人民。我要奋战到底！"
D.Strings[68020]="来吧，勇士。我需要你帮我粉碎这个“钢铁部落”。"
D.Strings[68021]="跑啊，兄弟！否则就迟了！"
D.Strings[68022]="快去找伊瑞尔吧。还有，$n，如果这个肮脏的食人魔敢找你的麻烦，就杀了他！"
D.Strings[68023]="但愿刀爪已经累了吧……我派去对付他的人，没有一个能活着回来的。"
D.Strings[68024]="$n是吗？你很快就会被卖到纳格兰的角斗场去了。在那之前，奥克默克会先给你找个活儿干干。"
D.Strings[68025]="加兹鲁维的解决方案已经可以安装了！"
D.Strings[68026]="必须靠近加兹鲁维的目标后安装！"
D.Strings[68027]="到前面来，奴隶！"
D.Strings[68028]="烈焰，协助我！"
D.Strings[68029]="我想现在应该不再需要这个幻象了。"
D.Strings[68030]="啊，好多了。"
D.Strings[68031]="我会把我们的新朋友带回避难所的。"
D.Strings[68032]="当幻影粉碎时，暗影将吞噬你的心灵！"
D.Strings[68033]="你为什么不救我？"
D.Strings[68034]="这就是我给你的回报！"
D.Strings[68035]="我或许该把你的身体抢过来！"
D.Strings[68036]="砰！你怕了？"
D.Strings[68037]="<你发现斯基克的尸体毫无生气地瘫倒在地上。>"
D.Strings[68038]="你在灌木丛中搜索着隐藏的敌人。"
D.Strings[68039]="这附近有人，$c。去检查一下灌木丛吧。"
D.Strings[68040]="你把它们都杀了？"
D.Strings[68041]="死蜈蚣对我毫无用处。你得用手抓住它们。"
D.Strings[68042]="这种药水肯定有效。现在，让我们去找斯基尔吧。"
D.Strings[68043]="这……这不可能……我的兄弟。我的亲人。我们太迟了。"
D.Strings[68044]="我要杀了他。我要把巨疤撕成碎片！我会给你报仇的，兄弟！"
D.Strings[68045]="我们是……不可……阻挡的。"
D.Strings[68046]="你的挣扎是徒劳的。"
D.Strings[68047]="我已经尽力为您争取时间了，亡语者。"
D.Strings[68048]="是迅影！他还活着！"
D.Strings[68049]="你就该乖乖呆在笼子里。现在，跟你的兄弟一样去死吧！"
D.Strings[68050]="爸爸，我害怕！"
D.Strings[68051]="我知道，小萤火虫。可爸爸希望你现在能勇敢一点。"
D.Strings[68052]="你还记得你说过长大之后想做什么吗？说出来吧，你今天早上才跟我说过。"
D.Strings[68053]="<抽鼻子><抽鼻子>……守备官。"
D.Strings[68054]="那守备官应该是什么样的呢？"
D.Strings[68055]="……他们很勇敢。"
D.Strings[68056]="这就对了！你能为我勇敢一次吗，守备官梅兰妮？"
D.Strings[68057]="%s站直了身子，挺起胸膛。"
D.Strings[68058]="我试试！"
D.Strings[68059]="这才是我的乖女儿。现在，跟紧爸爸。我们走！"
D.Strings[68060]="你要跟踪它？！随你的便。我可得离开这儿了！"
D.Strings[68061]="进去，你这个没用的$c！你和那头迅猛龙，只有一个能活着走出来！"
D.Strings[68062]="射得好！没什么技术含量，不过很漂亮！现在，趁他们还没有反击，让我们离开这儿。抓紧了！"
D.Strings[68063]="你这条卑微的可怜虫，你休想永远关住我。"
D.Strings[68064]="我要吃掉你那头宝贝驮兽。$b$b还有你。记住，我会把你一起吞下肚！$b$b但我还是更想吃你的驮兽。"
D.Strings[68065]="马上放了我，我或许可以考虑不杀光你们。$b$B或许只要杀掉角落里傻笑的那些兽人就够了。$b$B尤其是那个一直捅我的家伙。"
D.Strings[68066]="我饿了。给我吃的！"
D.Strings[68067]="你们没指望了。你们最好按照肥瘦排成一列，好让我更快地吃掉你们。"
D.Strings[68068]="哪怕是千军万马，都会在我面前崩溃。很快，你们就会明白这一点的。"
D.Strings[68069]="这个戈隆安全吗？"
D.Strings[68070]="安全？一点儿也不。不过还是可以管理的。如果有机会，苟克肯定会吃掉我们。不过钢铁部落成功地将他们的设备正确植入了他的大脑。$b$b没有人控制时，他是动不了的。$b$b但愿那些螺栓不会松掉，否则我们就要有大麻烦了。"
D.Strings[68071]="那个戈隆怎么办？"
D.Strings[68072]="他太大了，我们不可能带上他。虽然他肯定能大大提升我们的火力，可我们还是得控制一下部队规模。他不是钢铁部落军火库里唯一的戈隆。$b$b我们恐怕得把他留在这儿了。那些挽具可以把他困在原地。从被他吃掉的兽人数量来看，我完全不介意把他丢在这里饿死，作为对他罪行的惩罚。"
D.Strings[68073]="我跟随的车队可能需要帮助。你看起来还挺能打的。"
D.Strings[68074]="是否邀请伊基什？"
D.Strings[68075]="失去了斯基克和迅影之后，我都不知道该怎么活下去了。$b$b我的兄弟总是照顾着我。要不是他，我的下场恐怕远不止翅膀被剪掉而已。"
D.Strings[68076]="我和迅影之间的感情，几乎赶得上我跟我兄弟之间的感情了。"
D.Strings[68077]="我和迅影都不知道该如何感谢你今天的善举了，$c。$b$b我们欠你一份人情。$b$b等埋葬好我的兄弟之后，我就去车队那里找你。"
D.Strings[68078]="他们杀了布塔斯克……我们必须拖住他们！"
D.Strings[68079]="鲁古格辜负了我们！"
D.Strings[68080]="隐蔽，同胞们。拉姆塔斯会守护沼泽的。"
D.Strings[68081]="加尔鲁什·地狱咆哮已经逃跑了。\n\n如果你知道那个战争犯的下落，请通知当地官员以及影踪派的密探。"
D.Strings[68082]="面对阿库麦尔的怒火，鱼人们纷纷四散奔逃！"
D.Strings[68083]="快点儿，奴隶！"
D.Strings[68084]="不准偷懒！"
D.Strings[68085]="让我们看看，没有了我设计的机器，你又能有什么表现吧……"
D.Strings[68086]="你要不想挨揍就给我动起来！"
D.Strings[68087]="你还敢瞪我？！"
D.Strings[68088]="加尔鲁什的同党在他受审期间袭击了白虎寺。\n\n在混乱中，青铜龙凯诺兹也参与其中——他背叛了我们所有人——打开了一扇魔法传送门，与加尔鲁什一起逃之夭夭了。"
D.Strings[68089]="加尔鲁什去哪儿了？"
D.Strings[68090]="潘达利亚的水语者告诉我们，他们确信加尔鲁什已经逃出了那片大陆。\n\n除此之外，我们就不清楚了。"
D.Strings[68091]="凯诺兹是谁？"
D.Strings[68092]="凯诺兹多姆是青铜龙军团的成员。\n\n在审判过程中，他负责提供加尔鲁什往日暴行的影像资料。\n\n就我们目前所知，凯诺兹和加尔鲁什之间没有任何联系。我们和青铜龙军团都不知道他究竟为什么要帮助那个兽人。"
D.Strings[68093]="跟我说说袭击时的情况。"
D.Strings[68094]="一个自称督军扎伊拉的兽人领导了这次袭击；协助她的有她的龙喉氏族，大量巨龙，和一伙海盗雇佣军。\n\n加尔鲁什逃脱之后，扎伊拉和幸存下来的龙喉兽人也骑着巨龙逃跑了。\n\n尽管海盗们被抛下了，可他们对加尔鲁什的下落一无所知。"
D.Strings[68095]="你这个废物！"
D.Strings[68096]="快一点儿，否则你就等着下油锅吧！"
D.Strings[68097]="我会守住阵线的。快去找其他人！"
D.Strings[68098]="快点儿，奴隶！干你的活儿去！"
D.Strings[68099]="<低语>你要找的第一个奴隶就在通往采石场的路上。把头低下，我们不会有事的。千万别让你游侠朋友杀我。"
D.Strings[68100]="谬拉和艾萝娜在更远的地方。你得突破钢铁部落的阵线才能找到他们。"
D.Strings[68101]="艾萝娜在农场的另一边。快！"
D.Strings[68102]="够了！拉响警报！"
D.Strings[68103]="你们两个休想活着逃出去！"
D.Strings[68104]="基尔斯普可能知道。他就在山上。来，拿上这箱石头，假装你是在干活儿。"
D.Strings[68105]="伊瑞尔？是他们昨天带回来的那个女德莱尼吗？$B$B是的，我不知道她在哪儿，但基尔斯普可能会知道。"
D.Strings[68106]="<刃牙虎人眯起眼睛，上下打量着你。>"
D.Strings[68107]="<基尔斯普点头应允。>"
D.Strings[68108]="这些家伙没什么了不起的！"
D.Strings[68109]="基尔斯普指向其中一位食人魔，并做出一个抹脖子的动作。"
D.Strings[68110]="指向矿洞，并在地上画了一个的蕨人的样子。"
D.Strings[68111]="缪拉在农场的另一边。快！"
D.Strings[68112]="基尔斯普？他是个刃牙虎人。他们是不会跟你谈的。放弃吧，$n。我会宽大为怀的。"
D.Strings[68113]="如果我是你，就不会那么做！"
D.Strings[68114]="你在戈尔隆德做什么？"
D.Strings[68115]="你会为此付出代价的，$n！"
D.Strings[68116]="在被逐出石林之后，我和我哥哥斯基克一直在寻求庇护。$b$b我们骑着迅影飞了很远的路，直到在这附近被刃牙虎人给打了下来。我想他们是打算吃了我们。"
D.Strings[68117]="你来烦我做什么？没看到我正在休息嘛？"
D.Strings[68118]="作为一个$r，你还算不错。你随时可以帮我干活儿。"
D.Strings[68119]="你想知道你朋友的下落。帮我挖了这些石头吧。"
D.Strings[68120]="谢谢你，$r。她就在大厅下面干苦力呢。"
D.Strings[68121]="为什么你和你哥哥都得靠迅影那样的坐骑才能飞行？"
D.Strings[68122]="这个懒骨头就是欠揍。快回去干活，蕨人！"
D.Strings[68123]="最后一次机会，$n。放了我，然后立即投降，否则你一定会后悔的！"
D.Strings[68124]="你在这儿干什么呢？$B$B快回去干活，否则我可要揍你了！"
D.Strings[68125]="求求你，别杀我！"
D.Strings[68126]="被逐出峰林时，我们翅膀都被剪掉了。是斯基克想到要训练一头坐骑的。对大部分鸦人来说，骑在野兽背上飞行是一种侮辱。可对我和我哥哥来说——这是重返天空的唯一机会。$b$b我们被放逐之后没多久，斯基克就找到了迅影。她从自己的巢穴里掉了下来。$b$b我和我哥哥收养了她。我们为她遮风挡雨，给她食物。$b$b斯基克教会了她飞翔。作为回报，迅影也让我们重新获得了飞行能力。"
D.Strings[68127]="你有东西要修理吗？"
D.Strings[68128]="你有光学碟片吗？"
D.Strings[68129]="你有罗姆尔的扳手吗？"
D.Strings[68130]="这个地方还不错。"
D.Strings[68131]="这些德莱尼看上去很滑稽，你不觉得吗？"
D.Strings[68132]="你能给大技师一点酒水吗？"
D.Strings[68133]="毫不畏惧地踏入未知的领域。在黑暗中寻找答案……"
D.Strings[68134]="我是艾斯卡。既然你已经了解了鸦人的情况，那你是否愿意帮助我推翻他们的暴政呢？"
D.Strings[68135]="你会被你自己的疯狂压垮的……"
D.Strings[68136]="你以为我会任由你这样漫无目的地捅我吗？"
D.Strings[68137]="在永恒的疯狂涡流中旋转吧！"
D.Strings[68138]="我要用你的骨头来磨我的刀。"
D.Strings[68139]="你那点可怜的技巧在我的天赋面前不堪一击。"
D.Strings[68140]="啊，一个挑战者。"
D.Strings[68141]="可……我的……训练……"
D.Strings[68142]="搜索一下这个房间！不要放过任何一处角落和阴影。在我们确认安全之前，不要移动那个神器。"
D.Strings[68143]="你不是被选中的人。"
D.Strings[68144]="快！阻止仪式！"
D.Strings[68145]="我们正在推进！保持下去！"
D.Strings[68146]="我们很快就会让这些恶棍明白，永远不要再踏入我们的家园！"
D.Strings[68147]="照顾好伤员！他们随时可能发动新的攻击！"
D.Strings[68148]="战斗到底！我们绝不会向这些畜生低头！"
D.Strings[68149]="今天就是战争使者托斯克和他那些攻城武器的末日！"
D.Strings[68150]="如果我死了，你们也跑不了！"
D.Strings[68151]="呀啊啊啊！！！！"
D.Strings[68152]="呀啊！呀啊啊啊啊！！！"
D.Strings[68153]="快，站到救赎之地里去，保护好你自己！"
D.Strings[68154]="我的武器就在这座塔楼里。"
D.Strings[68155]="你来得正是时候，$n！我正打算逃跑呢。玛尔拉德呢？"
D.Strings[68156]="我想我的护甲就在这里。"
D.Strings[68157]="这下好多了，总算有趁手的家伙了。"
D.Strings[68158]="太好了，我总算有护甲了。让我们去找奥克默克，拿回玛尔拉德送我的吊坠吧。"
D.Strings[68159]="奥克默克就在这座巨型塔楼的顶层。我们走。"
D.Strings[68160]="那个吊坠是玛尔拉德送给我的。那个食人魔抓住我的时候把它抢走了。"
D.Strings[68161]="谢谢你，$n。你不会明白它对我有多么重要。让我们离开这儿吧。"
D.Strings[68162]="玛尔拉德！"
D.Strings[68163]="小心，它要爆炸了！"
D.Strings[68164]="伊瑞尔，亲爱的！"
D.Strings[68165]="谢谢你来救我，$n。$B$B我得回去找玛尔拉德了。"
D.Strings[68166]="$n？你来得正是时候！我正打算逃跑呢。"
D.Strings[68167]="享受这短暂的胜利吧，凡人。但你已经听到了我们的低语，你迟早是我们的囊中之物。"
D.Strings[68168]="终于自由了！让我们开始复仇吧！"
D.Strings[68169]="去死吧，奴隶贩子！"
D.Strings[68170]="为了复仇，$g兄弟:姐妹;！"
D.Strings[68171]="他们将为自己对我们所做的一切付出代价！"
D.Strings[68172]="重获自由的感觉真好。谢谢你！"
D.Strings[68173]="我来帮你开路，快跑吧！"
D.Strings[68174]="我要用这双手杀了他们！"
D.Strings[68175]="我不会反抗的，$n。求求你，别杀我。"
D.Strings[68176]="是迅影！他回来了！"
D.Strings[68177]="我需要一点时间，单独跟我哥哥道个别。感谢你的帮助，$n。"
D.Strings[68178]="一切安排妥当之后，我和迅影会去车队那里找你的。"
D.Strings[68179]="我正在笼子里呆得无聊呢。"
D.Strings[68180]="是谁在召唤火焰之灵？"
D.Strings[68181]="让我们去调试那块水晶吧。"
D.Strings[68182]="幽灵们非常不安，勇士。请在我调试的过程中掩护我。"
D.Strings[68183]="我们的任务就快完成了……"
D.Strings[68184]="附近的幽灵开始躁动起来。别让他们靠近法杖！"
D.Strings[68185]="请在法杖吸收水晶能量时保护好它。"
D.Strings[68186]="再见，卡尔加。愿大地母亲护佑着你。"
D.Strings[68187]="谢谢你们，英雄们，感谢你们的英勇义举。但愿我们的道路在未来再次交汇。"
D.Strings[68188]="维伦之杖遭到了攻击！"
D.Strings[68189]="帮帮我，英雄！我被攻击了！"
D.Strings[68190]="保护我，勇士！我受伤了！"
D.Strings[68191]="是谁竟敢亵渎我们古老的土地？"
D.Strings[68192]="玛尔拉德正在营地里处理一些麻烦。我会尽力掩护你的。"
D.Strings[68193]="每一块水晶的品质都差不多，而最终产品的质量则取决于技师的切割技术。"
D.Strings[68194]="|TInterface\\Icons\\inv_misc_noose_01:20|t%s被 |cFFFF0000|Hspell:150809|h[绳索陷阱]|h|r绊倒了！"
D.Strings[68195]="我要把你的脑袋挂在格罗玛尔的城墙上，小崽子。"
D.Strings[68196]="是谁竟敢挑战霜火之锤？！"
D.Strings[68197]="我是不会死在你这种家伙手里的，兽人。"
D.Strings[68198]="感谢你的帮助。但愿我们还能再见，朋友。"
D.Strings[68199]="我们支持贾纳尔。他是最年长的，他应该成为我们的酋长。"
D.Strings[68200]="哼，我身上的伤疤都比你年纪大。"
D.Strings[68201]="记住我的话，贾纳尔迟早会执掌霜狼氏族的。"
D.Strings[68202]="你想要什么，小崽子？"
D.Strings[68203]="我还记得多年前与加拉达和贾纳尔并肩抵抗嘲颅氏族的情景。光荣的战斗。那是有史以来战场上最可怕的军队。"
D.Strings[68204]="加拉达是一个了不起的酋长，可在临终前还是昏了头，竟然无视了贾纳尔这个顺位继承人，把氏族交给了杜隆坦。$b$b现在这个与我们一同狩猎的人，才配让我们称他为“酋长”。"
D.Strings[68205]="我很高兴昔日的同盟还没有彻底瓦解。现在，德莱尼只会用炮火来欢迎我们了。"
D.Strings[68206]="我是奈玛之女，鲁尔坎。我曾是影月氏族的长老，但现在已经不是了。$B$B耐奥祖是我的丈夫。我和我的追随者们，已经同他和他的追随者们分道扬镳了。"
D.Strings[68207]="我需要更多的燃料来摆脱这只小虫子……"
D.Strings[68208]="需要更多燃料！"
D.Strings[68209]="你以为我没燃料了？好好想想吧，小崽子！"
D.Strings[68210]="还要燃料！"
D.Strings[68211]="再加点燃料！"
D.Strings[68212]="我要燃料！！！"
D.Strings[68213]="该加燃料了……"
D.Strings[68214]="该加燃料了！"
D.Strings[68215]="你这只小老鼠！"
D.Strings[68216]="霜狼氏族来啦！"
D.Strings[68217]="敌袭！"
D.Strings[68218]="我要把你吊起来喂我的野兽！"
D.Strings[68219]="啊，嫩肉送上门来了。"
D.Strings[68220]="小菜一碟！"
D.Strings[68221]="为了铁狼！"
D.Strings[68222]="啊，尝尝我的铁链吧。"
D.Strings[68223]="木精最初是怎么会出现在刃月密林外的？"
D.Strings[68224]="狼村遭到袭击。阻止雷神氏族的攻击！"
D.Strings[68225]="他们从森林里涌出来……他们为什么要攻击我们？"
D.Strings[68226]="魔荚人从森林里冲出来伏击了我们！当时我们刚逃出图雷姆，想要找一个避难所。$B$B通常只要我们不闯入他们的领地，他们是不会来攻击我们的……现在这是怎么了？"
D.Strings[68227]="要是你见到德拉卡……告诉她我很快就回家了。"
D.Strings[68228]="听了他父亲的话，萨尔咧嘴一笑。"
D.Strings[68229]="这一片地区都被占领了。快跑吧，否则就迟了！"
D.Strings[68230]="贝尔多斯！钢铁部落已经开始进攻了！"
D.Strings[68231]="谢谢你，勇士！今天，你为我带来了新的希望。"
D.Strings[68232]="影月兽人——他们变了。他们变成了虚空的信徒……"
D.Strings[68233]="谢谢你，勇士。我永远都不会忘记……他们的尖叫声……"
D.Strings[68234]="快——耐奥祖把俘虏拖到祭坛那里去了！"
D.Strings[68235]="谢谢你。请救救其他人！耐奥祖正在利用他们进行某种仪式！"
D.Strings[68236]="耐奥祖正在献祭俘虏。他还提到了什么”黑暗之星“！"
D.Strings[68237]="附近还有其他俘虏……他们被抓到别的地方去了……请救救他们！"
D.Strings[68238]="谢谢你救我出来！你绝对想象不出我们看到了怎样的恐怖……"
D.Strings[68239]="我们需要帮助！"
D.Strings[68240]="骚乱惊动了附近的泥滩巨蛛！"
D.Strings[68241]="拔除"
D.Strings[68242]="这是谁呀……？"
D.Strings[68243]="谢谢你。我真的不适合战斗。"
D.Strings[68244]="我们的族人一直从大地和月亮中汲取魔力。$B$B大约三个世纪前，我们的祖先感受到了另一种魔力。一种黑暗的力量。$B$B这就是暗影魔法。它能腐蚀心智，令使用它的人堕落，让他们发疯。$B$B从那时起，我们氏族就严禁使用这些暗影魔法。"
D.Strings[68245]="那些雷神氏族的蠢货在对那个戈隆做什么？"
D.Strings[68246]="在钢铁和火药面前，星象和预知有什么用？拿出点真本事，否则你的族人都得死。"
D.Strings[68247]="为了卡拉波！"
D.Strings[68248]="兄弟姐妹们，站起来！今天，我们要为卡拉波而战！"
D.Strings[68249]="我不要做奴隶！"
D.Strings[68250]="誓死保卫卡拉波！"
D.Strings[68251]="我们来煮药吧！"
D.Strings[68252]="影月堡垒从不对外人开放，但这块钥石能让你进去。祝你好运，英雄。"
D.Strings[68253]="我得干活儿了。"
D.Strings[68254]="好了，再来加点能让它翻滚沸腾起来的东西吧！"
D.Strings[68255]="再加点危险物品……比如毒药！"
D.Strings[68256]="再来点能让它闪闪发光的东西！"
D.Strings[68257]="闲逛。"
D.Strings[68258]="工作中。"
D.Strings[68259]="快消灭那些魔荚人，别让%s将他们催熟了！"
D.Strings[68260]="只是休息一下。"
D.Strings[68261]="拍打炸弹机器人"
D.Strings[68262]="%s的吸力变强了！"
D.Strings[68263]="为了霜狼！"
D.Strings[68264]="收集武器"
D.Strings[68265]="%s兴奋地嗥叫起来。"
D.Strings[68266]="再加点儿肉！"
D.Strings[68267]="这些脑袋将成为这场伟大战役最好的战利品！"
D.Strings[68268]="Throm-Ka，$c。愿元素与你同在。"
D.Strings[68269]="我做好参加仪式的准备了，先知。"
D.Strings[68270]="我诅咒那些雷神兽人和他们的廉价武器。这些东西够我挑一个礼拜了！"
D.Strings[68271]="你准备好进行仪式了就告诉我吧，$n。"
D.Strings[68272]="先知，我想再看一次幻象。"
D.Strings[68273]="信口雌黄，雷神的恶棍。"
D.Strings[68274]="这里唯一的耻辱，就是你的无耻偷袭！"
D.Strings[68275]="真是废物。来吧，朋友，我们好好商量一下。"
D.Strings[68276]="仪式准备好了，$n。可以开始了就告诉我一声。"
D.Strings[68277]="元素曾和我交流……现在我只听到低语。这是我们的命运，还是一种警告？"
D.Strings[68278]="沿着道路往西北走。快，那个怪物会杀了德雷克塔尔的！"
D.Strings[68279]="幸会，$c。欢迎来到狼村。"
D.Strings[68280]="谢谢你能在我们最需要的时候赶回来，$c。"
D.Strings[68281]="你一定要尽快找到德雷克塔尔！"
D.Strings[68282]="狼村的救星。很高兴能再次见到你，$n。"
D.Strings[68283]="我会立刻着手准备的。"
D.Strings[68284]="拿着，这种草药的效果能让你更轻松地抵达那座岛。"
D.Strings[68285]="噢，不！有点不对劲。我们再煮一锅吧。"
D.Strings[68286]="完美！"
D.Strings[68287]="萨玛拉！"
D.Strings[68288]="你准备好之后就告诉我一声吧！"
D.Strings[68289]="我准备好了，菲奥拉。"
D.Strings[68290]="以前搞草药学可比现在容易多了。如今哪怕是要弄一点点草药，我们都得在地狱里杀个来回！"
D.Strings[68291]="是该换个环境了。"
D.Strings[68292]="我们不该信任影月氏族的另一个原因是，他们连自己的魔法都控制不了。"
D.Strings[68293]="我是绝对不会再回去的。"
D.Strings[68294]="尝尝钢铁的怒火吧！"
D.Strings[68295]="目标越大，爆炸越爽！"
D.Strings[68296]="就跟在老家炸狗头人一样简单！"
D.Strings[68297]="我过去之后，那儿恐怕得下上几星期的鬣蜥人碎块雨！"
D.Strings[68298]="这个洞穴的深处隐藏着某种恶魔。把他召唤出来的那个蠢货已经被他干掉了。"
D.Strings[68299]="这就是钢刀比黑暗魔法好用的另一个原因。"
D.Strings[68300]="我们本来是来这个洞穴采集资源的……"
D.Strings[68301]="这简直不可接受。我们为什么要让这些蠢货加入我们？"
D.Strings[68302]="我们成功了！这种药水应该有用。"
D.Strings[68303]="把它交给吉德文。但愿它能起作用。"
D.Strings[68304]="你可以在山脚下找到大部分的飞机残骸。快去把你能找到的东西都带回给我。"
D.Strings[68305]="等我把这个旋翼机发动起来，我马上就去找罗姆尔。"
D.Strings[68306]="我宁可去死，也不愿苟活，做钢铁部落的奴隶。"
D.Strings[68307]="去拿几把武器。是时候站起来反抗这些强盗了。"
D.Strings[68308]="这些兽人对我的族人犯下的罪行简直罄竹难书。快杀光他们。"
D.Strings[68309]="战舰群！向我的位置开火！"
D.Strings[68310]="战舰群！轰炸那边的平台！"
D.Strings[68311]="耐奥祖！你的部队完了，你的堡垒也完了。"
D.Strings[68312]="你的“黑暗之星”成了德莱尼的帮凶。你这废物！"
D.Strings[68313]="我们还可以为钢铁部落效劳，地狱咆哮。我们的魔法——"
D.Strings[68314]="我的钢铁部落没有你的位置！滚回你的小村子去，耐奥祖。你就数着星星，等钢铁狂潮来湮没你吧。"
D.Strings[68315]="滚回你的小村子去吧，耐奥祖。你可以数着星星，等钢铁狂潮来湮没你。"
D.Strings[68316]="考霍尔、扎克塔、卓卡……包抄过来。贾拉克，留在原地。"
D.Strings[68317]="扎克塔，不！……我们会为你复仇！ "
D.Strings[68318]="砍了那家伙的脑袋！"
D.Strings[68319]="该死。贾拉克，上……杀掉那个瞎眼萨满。"
D.Strings[68320]="把援军都叫过来。我要活捉那头母狼。"
D.Strings[68321]="撤退！我们会回来报仇的！"
D.Strings[68322]="看看你能找到些什么吧。如果影月氏族也加入钢铁部落，那更艰苦的日子恐怕还在后头呢。"
D.Strings[68323]="士兵们！生长吧！"
D.Strings[68324]="小的们！快长起来！杀呀！"
D.Strings[68325]="我要吃掉你的朋友们！再吃掉你！"
D.Strings[68326]="看来影月氏族加入钢铁部落的过程遇到了一点麻烦。我们或许能利用这一点。"
D.Strings[68327]="现在，你是我们的了。"
D.Strings[68328]="正在治疗。"
D.Strings[68329]="我已经给了你一些烟雾弹。使用它们帮助塞林瞄准阿肯尼特守护者吧。"
D.Strings[68330]="我装填了足够的炸药，足以把那个戈隆从德拉诺世界抹去了。你只要帮我标记出投弹点就行了。"
D.Strings[68331]="万灵非常不安，杜隆坦。"
D.Strings[68332]="这……这太可怕了。我们该怎么办？"
D.Strings[68333]="我抓住机会逃跑了。可怜的拉布鲁，但愿他还活着。"
D.Strings[68334]="我们必须摆脱这些枷锁。动作快！"
D.Strings[68335]="我们很快就会杀掉你的。"
D.Strings[68336]="钢铁狂潮来势汹汹，因为杜隆坦很强，却又不肯加入他们。"
D.Strings[68337]="快醒醒！我们得马上逃走！看看那玩意儿吧！"
D.Strings[68338]="我们需要支援！"
D.Strings[68339]="快来帮忙！我们这儿有入侵者！"
D.Strings[68340]="钢铁部落的战士们，我们有不速之客了！"
D.Strings[68341]="我来了！"
D.Strings[68342]="钢铁部落将碾碎你！"
D.Strings[68343]="我听到了战斗的声音！"
D.Strings[68344]="坚持住，我们来了！"
D.Strings[68345]="鲜血与征服！"
D.Strings[68346]="我们就到了！"
D.Strings[68347]="我听到了战斗的声音！快去！"
D.Strings[68348]="该死的钢铁部落！"
D.Strings[68349]="治疗之环。"
D.Strings[68350]="站起来吧，我的造物！杀了这些入侵者！"
D.Strings[68351]="许多霜狼兽人倒在了这里。"
D.Strings[68352]="他们在用我族人的灵魂饲养巨像作为武器。"
D.Strings[68353]="$n，消灭这些灵魂萨满，阻止仪式。"
D.Strings[68354]="我和我的战士们会去营救那些幸存下来的同胞。"
D.Strings[68355]="我爸爸呢？"
D.Strings[68356]="你休想击败我们！"
D.Strings[68357]="爸爸！！！"
D.Strings[68358]="雷神兽人，准备战斗！"
D.Strings[68359]="霜狼渣滓！"
D.Strings[68360]="你不配跟雷神兽人较量！"
D.Strings[68361]="<这架旋翼机看起来就是用胶带和泡泡糖粘合起来的。但塞林看起来好像很有把握。它应该是安全的。>"
D.Strings[68362]="返回观星台？"
D.Strings[68363]="我会把你的脑袋留作纪念的。"
D.Strings[68364]="闲逛，诊所。"
D.Strings[68365]="你跟你的宝贝狼群走散了吗？"
D.Strings[68366]="谢谢你，$n。这些恶棍死掉之后，要说服其他人起来反抗就更容易了。"
D.Strings[68367]="这下，钢铁部落下次俘虏德莱尼时，就会三思了。"
D.Strings[68368]="很高兴再次见到你，$n。没有你和塞林，我就死定了。"
D.Strings[68369]="作为雷神氏族的尖兵，这是最高的荣誉。"
D.Strings[68370]="我和雷蹄会碾碎你们的。"
D.Strings[68371]="去死吧，霜狼氏族的废物们。"
D.Strings[68372]="拿着，这种草药能让你健步如飞。小心点，$n。"
D.Strings[68373]="铁砧。"
D.Strings[68374]="铁砧完成。"
D.Strings[68375]="当强大的英雄们靠近时，萨满之石就会发出嗡鸣声。"
D.Strings[68376]="霜狼护佑"
D.Strings[68377]="霜狼之灵"
D.Strings[68378]="**咳咳**"
D.Strings[68379]="你预见到这一天了吗，蠢瞎子？哈哈！！"
D.Strings[68380]="卡拉迪奥斯，我想再看一次融合仪式。"
D.Strings[68381]="从我面前消失，渣滓。$B$B我脱身之后，一定要把你劈成两半。"
D.Strings[68382]="变戏法的懦夫！"
D.Strings[68383]="快去东边增援。"
D.Strings[68384]="小心北边悬崖上的雷神兽人。"
D.Strings[68385]="兄弟姐妹们，到南边去。"
D.Strings[68386]="他们只敢趁我们内部空虚时来偷袭。杀了这些雷神的懦夫！"
D.Strings[68387]="小心他们的督军，贾拉克。"
D.Strings[68388]="今天，杜隆坦将为我们骄傲！"
D.Strings[68389]="下来啊，“铁狼”。让你看看真正的狼是怎么战斗的！"
D.Strings[68390]="保护幻象之池，别让他们靠近先知。"
D.Strings[68391]="检查箱子。"
D.Strings[68392]="卑鄙。铁狼根本不在乎野兽或者兄弟——他们只是狩猎的武器。"
D.Strings[68393]="总是不够用……"
D.Strings[68394]="让我来看看。"
D.Strings[68395]="我们已经征召了所有身强力壮的士兵来保卫城市了。$B$B坚持到底，英雄。考验勇气的时刻到了。"
D.Strings[68396]="报到。"
D.Strings[68397]="钢铁部落正在向卡拉波神殿方向移动。攻击已经开——"
D.Strings[68398]="等等……那是什么光？"
D.Strings[68399]="这人已经没救了。"
D.Strings[68400]="你感觉怎么样，海玛？"
D.Strings[68401]="我很好，公主。"
D.Strings[68402]="让她抿一小口就够了，对她客气点！"
D.Strings[68403]="谢谢你，卡杜斯。我们必须试一试。面前的困难太多了。"
D.Strings[68404]="我随时听候你的差遣。"
D.Strings[68405]="对接。"
D.Strings[68406]="我不能继续留在达纳苏斯了。人民需要我们的帮助。"
D.Strings[68407]="正在输血。"
D.Strings[68408]="好的，公主。"
D.Strings[68409]="海玛，喝了它。它会让你舒服一些。"
D.Strings[68410]="没用的，公主。我们试过了。"
D.Strings[68411]="你很凶猛，小崽子，可你心中的牵挂让你变得软弱！"
D.Strings[68412]="丢掉你的软弱，否则就等着被钢铁狂潮淹没吧！"
D.Strings[68413]="我……我感觉……"
D.Strings[68414]="阿莎？！阿莎，不！！"
D.Strings[68415]="好饿啊！！！"
D.Strings[68416]="海玛！请等一等！控制住自己！"
D.Strings[68417]="我快要失控了……请，帮帮……"
D.Strings[68418]="给，喝了它。你感觉怎么样？"
D.Strings[68419]="这头塔布羊被海玛撕成了碎片。她肯定就在附近。"
D.Strings[68420]="啊，就是它……"
D.Strings[68421]="懦夫！放了卡格，跟我堂堂正正地打一场！"
D.Strings[68422]="我——我在哪儿？幽灵呢？"
D.Strings[68423]="你失控了。你在营地附近的一座山头上。"
D.Strings[68424]="海玛，我们来了。你还好吧？"
D.Strings[68425]="去吧，$c。扫平这个地方。让那些恶棍得到应有的惩罚！"
D.Strings[68426]="我不太记得了。只记得一个幽灵……充满了纯粹的怒火。它在召唤我。"
D.Strings[68427]="我……不太舒服。"
D.Strings[68428]="乌鲁特感谢你拯救了他和影月谷的森林。"
D.Strings[68429]="嗨，你好啊！"
D.Strings[68430]="嗨，回头见！"
D.Strings[68431]="谢谢你，但愿格雷迈恩公主能尽快找到有效的药剂。它肯定就在这附近。"
D.Strings[68432]="你以为你能轻易打败我？"
D.Strings[68433]="是谁竟敢来打搅我的研究工作！"
D.Strings[68434]="我觉得德拉诺的元素并不像艾泽拉斯的那样回应我……"
D.Strings[68435]="继续前进吧，杜隆坦在等你。让我喘口气。 "
D.Strings[68436]="我要疯了！"
D.Strings[68437]="别靠近我！滚开！我要杀了你！我要杀光你们！"
D.Strings[68438]="我能打破它，可我需要一点时间来驾驭元素。"
D.Strings[68439]="先祖的力量在我体内流淌！"
D.Strings[68440]="基尔罗格！我早该想到，这一切都是你搞的鬼。"
D.Strings[68441]="呵呵……那个杂种……<咳嗽>已经跟其他畜生……一起玩完了。"
D.Strings[68442]="你们这些蠢货，居然敢追到这里来。我要把你们的灵魂从身体里抽出来喂给巨像，再用它们碾碎你那脆弱的氏族！"
D.Strings[68443]="进攻刀塔堡垒！"
D.Strings[68444]="不能再浪费时间了！我们得马上进攻！"
D.Strings[68445]="我们必须攻入内部大厅。基尔罗格休想就这么跑掉！"
D.Strings[68446]="这家伙失血过多了。"
D.Strings[68447]="我……我无法相信他死了……"
D.Strings[68448]="伊瑞尔！防护水晶碎了。钢铁部落冲进了卡拉波。除非发生奇迹，否则我们很难突围。"
D.Strings[68449]="%s擦干了眼泪。"
D.Strings[68450]="如果神殿陷落，维伦就白白牺牲了。"
D.Strings[68451]="多罗戈倒下了！保持警惕，霜狼们，我们还没攻下堡垒。"
D.Strings[68452]="<美妙的钟声在你的脑海中回荡着。>"
D.Strings[68453]="我已经做好了与钢铁部落一战的准备。"
D.Strings[68454]="霜狼氏族必胜。"
D.Strings[68455]="这座堡垒必将陷落。"
D.Strings[68456]="打起精神！"
D.Strings[68457]="*嗅*"
D.Strings[68458]="兄弟姐妹们，圣光与你们同在！"
D.Strings[68459]="诅咒他！"
D.Strings[68460]="不过是点小擦伤罢了！我很快就会恢复的。"
D.Strings[68461]="萨玛拉是我唯一的亲人。从我记事起，她就一直教导着我。$B$B她既亲切又善良，而我就……没那么出色了。"
D.Strings[68462]="多年来，影月氏族与卡拉波的德莱尼一直保持着相对的和平。$B$B自从钢铁部落……到来之后……情况就变了。"
D.Strings[68463]="玛尔拉德说他的伤不严重，事实上，他遭到了耐奥祖的重创。虽然我也说不好究竟哪一样伤得更重——到底是他的身体还是他的自尊。$B$B无论如何，他很走运，因为你及时赶到了。"
D.Strings[68464]="你敢相信吗？"
D.Strings[68465]="我们今天收到了些什么呢？"
D.Strings[68466]="咿——咿咿！"
D.Strings[68467]="我要把你们的灵魂困在黑暗之中！"
D.Strings[68468]="你们的极乐天堂已经完了。"
D.Strings[68469]="太迟了……我的主人……已经来了……"
D.Strings[68470]="让暗影吞噬你！"
D.Strings[68471]="你还没有履行你的誓言！"
D.Strings[68472]="回到这个世界吧！"
D.Strings[68473]="幽灵们，听我号令！"
D.Strings[68474]="我要用阴影湮没这个世界！"
D.Strings[68475]="你们不朽的灵魂将让我在黑暗中更进一步。"
D.Strings[68476]="在我面前颤栗吧！"
D.Strings[68477]="我的苦难结束了！"
D.Strings[68478]="保持冷静。一些难民报告说在西边魔荚人的巢穴附近的森林里看到了一头九头魔花。"
D.Strings[68479]="全靠你了，勇士。我会留下来照顾得救的奴隶们。"
D.Strings[68480]="请把她带回来，$n。她是我唯一的亲人了。"
D.Strings[68481]="但至少值得一试。"
D.Strings[68482]="当蜘蛛发起攻击时，我们正在猎杀一个魁梧的白鬼兽人。$b$b在混乱中，我和我的助手甘奇走散了。我在逃跑过程中被咬了无数下。$b$b蜘蛛造成的伤口让我无法好好思考。我得在自己彻底发疯前制作出解药。"
D.Strings[68483]="看来这就是希尔加打算用来制作解药的碗。"
D.Strings[68484]="蘑菇能预示未来。相信我！"
D.Strings[68485]="沐浴在神圣的孢子中，感受蘑菇的力量吧！"
D.Strings[68486]="这朵蘑菇已经给出了预示。这就是真相！"
D.Strings[68487]="德雷克塔尔，老伙计。你还活着！"
D.Strings[68488]="你说的是谁？你带来的这些陌生人吗？"
D.Strings[68489]="我知道你眼睛不好使，萨满，这家伙可是个绿皮。"
D.Strings[68490]="唔，没错。贾纳尔已经惹出麻烦了。"
D.Strings[68491]="好吧，陌生人。你们赢得了萨满的信任。如果你们真的愿意帮忙，我也不会拒绝。"
D.Strings[68492]="我差点就撑不住了。要不是这些英雄相救，我早死了。"
D.Strings[68493]="这些是来自远方的勇士，也是钢铁部落的死敌。"
D.Strings[68494]="我不用看也知道；他们都是高尚的人。他们救了我们的族人——包括你兄弟。"
D.Strings[68495]="来吧，朋友们。既然要与我们并肩作战，就来接受霜狼的祝福吧。"
D.Strings[68496]="伸手触摸萨满之石。拥抱这片土地和我们先祖的智慧吧。"
D.Strings[68497]="我被那些恶魔术士重创，万灵对我沉默了。"
D.Strings[68498]="我能感觉到。这片土地在对我说话，但我听不懂。"
D.Strings[68499]="灵魂不会抛弃你的，德雷克塔尔。我保证。 "
D.Strings[68500]="跟我来，萨满。让我看看你的伤势。"
D.Strings[68501]="德拉卡关切地看着德雷克塔尔。"
D.Strings[68502]="战士们！今天是个转折点。"
D.Strings[68503]="今天，我们将占领刀塔堡垒！"
D.Strings[68504]="让我们并肩作战，共同赢得胜利！"
D.Strings[68505]="贾纳尔是个好战士，但太过莽撞。他带走了我们最好的一批战士。"
D.Strings[68506]="他从不听人劝。他的鲁莽会葬送我们。"
D.Strings[68507]="我们到了——戈莫尔岗哨。它将成为我们的据点。不留活口！LOK'TAR OGAR！"
D.Strings[68508]="杜隆坦，你兄弟已经冲上去了。"
D.Strings[68509]="刀塔食人魔把我关在那鬼地方。我要报仇！用他们的脑壳磨亮我的斧子！"
D.Strings[68510]="刀塔堡垒！我要向那些食人魔复仇，哪怕将其夷为平地也在所不惜。"
D.Strings[68511]="挡住钢铁部落！"
D.Strings[68512]="朋友们，你们获得了英雄般的礼遇。我们去见霜狼酋长。"
D.Strings[68513]="慧耳！你还活着！"
D.Strings[68514]="虽然看不见，但这熟悉的寒意让我舒心。"
D.Strings[68515]="我很担心贾纳尔。他总是不管不顾地一头扎入战场。他对复仇的渴望会让他变得更加鲁莽。"
D.Strings[68516]="没错。加拉达的幼子：可敬的杜隆坦。"
D.Strings[68517]="他很年轻，却睿智过人。我担心他已经成了戈隆的眼中钉——氏族正面临威胁。"
D.Strings[68518]="我们到了！沃高尔，霜狼的家园。"
D.Strings[68519]="你刚才提到了霜狼酋长……"
D.Strings[68520]="杜隆坦！"
D.Strings[68521]="幻象！不！你要为自己的多管闲事付出代价！"
D.Strings[68522]="洛卡拉……每当和你并肩作战时，我就会觉得自己变得不可战胜！我们现在就去挑战铁狼，结束这一切吧！"
D.Strings[68523]="我们该走了，回到狼群中去。铁狼将会面对霜狼氏族的全力一击。"
D.Strings[68524]="老朋友，带我们去找杜隆坦！"
D.Strings[68525]="弗米克矿石比最坚硬的精钢还要硬。你要用我的鬣蜥人利齿矿工锄才能挖开它。"
D.Strings[68526]="感谢万灵在这一刻将你带到我身边来。"
D.Strings[68527]="完成了！剑铸好了。"
D.Strings[68528]="|TInterface\\Icons\\mocking_banner:20|t%s放置了|cFFFF0000|Hspell:153799|h[集结旗帜]|h|r以召唤附近的盟友！"
D.Strings[68529]="现在站在你面前的人是纳什拉！霜狼氏族的武器锻造师。为了感谢你的帮助，我愿意向你效忠。"
D.Strings[68530]="噢！选错线了。小心！"
D.Strings[68531]="你帮了我一个大忙。我的剑将为你所用。$b$b我在此发下血誓：我将辅佐于你，用我的剑术和采矿技术为你的部队效劳。$b$B你愿意接受我的效忠吗？"
D.Strings[68532]="接受剑圣纳什拉的血誓。（要塞追随者）"
D.Strings[68533]="你受伤了。脸色很难看。"
D.Strings[68534]="快给那些还能走路的人包扎一下！任何一个身强力壮的兽人都不该错过这场战斗。"
D.Strings[68535]="好饿啊。"
D.Strings[68536]="搅拌"
D.Strings[68537]="战斗已经打响。Lok-Narash！"
D.Strings[68538]="援军已经过来了。进攻！"
D.Strings[68539]="野猪的臭味。小心它的獠牙……冲啊！"
D.Strings[68540]="岗哨归我们了！重新整队，前进！"
D.Strings[68541]="我得到前面去。霜狼们，守住岗哨。伊戈利玛，跟我来！"
D.Strings[68542]="我来拦住敌人的反击。 Lok'tar ogar！ "
D.Strings[68543]="破坏符文导管，削弱高尔山的防御。"
D.Strings[68544]="自从回到营地之后，希尔加就一直是这副模样。$b$b她一直在念叨着什么需要解药——然后就开始吃泥巴。$b$b我拿的那点薪水可不是让我来干这个的。"
D.Strings[68545]="我就不能休息一会儿了吗？$b$b我还以为只要跟紧奈辛瓦里家的人就能赚到钱呢。$b$b早知这样我还不如呆在艾泽拉斯。"
D.Strings[68546]="你休想。我不能再失去你了。"
D.Strings[68547]="你会好起来的……我保证……只要坚持下去……"
D.Strings[68548]="屏障消失了！让我们来做个了断吧。"
D.Strings[68549]="是否邀请希尔加加入车队？"
D.Strings[68550]="每到夜里，白鬼就会在这一带出没。他们毫无底线，会毫不犹豫地攻击儿童和老人。$b$b我一定要让他们为自己的罪行付出代价。"
D.Strings[68551]="$G他:她;就来了！$n，跟我聊聊吧！"
D.Strings[68552]="我还活着吗？我是谁？我们是谁？好痛啊！"
D.Strings[68553]="好多蜘蛛……好多兔子……"
D.Strings[68554]="|TInterface\\Icons\\spell_shadow_chilltouch.blp:20|t%s施放了|cFFFF0000|Hspell:154766|h[召唤古代灵魂]|h|r！"
D.Strings[68555]="希尔加失踪时，正在写日记。它就在这儿。"
D.Strings[68556]="隐身兔子？嘘……别提那些疯狂的东西。"
D.Strings[68557]="我应该自己读一下的，但这并不在我的工作范畴之内。"
D.Strings[68558]="你要对那些眼球做什么？真是太恶心了。"
D.Strings[68559]="暗刺蛛后，嗯？祝你好运。如果你需要帮助的话，我可以留下来照顾希尔加。"
D.Strings[68560]="我……我感觉好多了。谢谢你，$c。现在，听好了，我们需要你的帮助。"
D.Strings[68561]="但愿这能有用。我可是个工薪族。"
D.Strings[68562]="小心点，$n。等我好一些了，我会马上去找你的。"
D.Strings[68563]="他躲不了多久。"
D.Strings[68564]="好个“铁狼”！只会躲在帮凶身后的懦夫。"
D.Strings[68565]="这已经是我这周损失的第三名助手了。"
D.Strings[68566]="放弃吧，督军。都结束了。"
D.Strings[68567]="感激不尽，$c。要不是你，这恐怕真要变成一场灾难了。"
D.Strings[68568]="恐怕要变成一场灾难？我还是转行吧。"
D.Strings[68569]="……芬里斯？"
D.Strings[68570]="说实话，希尔加从不尊重我或者其他助手。$b$b而且老实说……薪酬也不怎么吸引人。$b$b我想我是该去找个新主顾了。"
D.Strings[68571]="芬里斯！"
D.Strings[68572]="是否邀请格莱布林加入车队？"
D.Strings[68573]="这笔生意一直在变糟。"
D.Strings[68574]="我当然愿意加入你们。只要报酬合适，而且你能保证我不会被蜘蛛吃掉就行。"
D.Strings[68575]="好极了……这下我这周就损失四个助手了。谢谢，$n。"
D.Strings[68576]="我很乐意加入你的车队，$n。快去打包我们的行李，格莱布林。"
D.Strings[68577]="*叹气*这年头要找个好助手太难了。"
D.Strings[68578]="你自己打包吧。我不干了。我要去找个不会被蜘蛛吃掉的工作。"
D.Strings[68579]="你以为我们死了吗，嗯？嘲颅！嘲颅！哈哈哈哈哈！"
D.Strings[68580]="嘲颅的杂碎！"
D.Strings[68581]="怎么？没有可爱的小玩具做挡箭牌了吗？你害怕了？"
D.Strings[68582]="我要在你那张漂亮的兽人脸蛋上刻出一个笑脸！"
D.Strings[68583]="我们要把你那小小的钢铁部落撕成碎片！"
D.Strings[68584]="我的家人！我的朋友！我的家园！你葬送了一切，我要夺回他们！"
D.Strings[68585]="这只是我的复仇名单上的一个名字。下面还有不少等着我去收拾呢。"
D.Strings[68586]="冰舌——吃了他们！"
D.Strings[68587]="这外头真冷啊。"
D.Strings[68588]="要是让中士听见了，你就得在山上站一个冬天。"
D.Strings[68589]="给你。我借了罗姆尔的工具来修理我的望远镜。请帮我跟他说一声谢谢。"
D.Strings[68590]="我已经预见到你会来了，$n，这就是罗姆尔要的水晶。"
D.Strings[68591]="我已经戒酒了，$G伙计:丫头;。我发过誓，在我亲爱的艾尔莎归来之前，我绝不再喝冰啤酒了。"
D.Strings[68592]="我跟他可不一样，我买了很多烈酒来跟大家分享！把这个带给我们楼下那位卷毛的蓝色朋友吧。"
D.Strings[68593]="我们的人数太少了，没法将钢铁狂潮扼杀在萌芽状态下。$B$B但是，我们可以巧妙应对，好好利用他们犯下的错误。"
D.Strings[68594]="%s开始对他的敌人施放|cFFFF0404|Hspell:153804|h[吸气]|h|r！"
D.Strings[68595]="啊，就在这儿呢。这个碟片里应该有罗姆尔需要的信息。"
D.Strings[68596]="%s刺耳的尖叫声引来了附近的食腐蛆虫！"
D.Strings[68597]="哥哥，我们谈谈吧。我们是一家人。"
D.Strings[68598]="勇士——专心对付芬里斯。"
D.Strings[68599]="我们来对付冰舌！"
D.Strings[68600]="“一家人。”你太软弱了——跟我们的父亲一样！"
D.Strings[68601]="你还敢提父亲！你根本不配叫他父亲！"
D.Strings[68602]="一个小氏族的小酋长……我们本应该更伟大。"
D.Strings[68603]="援军，干掉那些霜狼崽子们！"
D.Strings[68604]="贾纳尔，你来殿后。"
D.Strings[68605]="好的，兄弟！"
D.Strings[68606]="发臭的畜生们！跟你们的狗一起去死吧。 "
D.Strings[68607]="兽人注定要成为万兽之王！众生之主！"
D.Strings[68608]="奴隶不会有自由人的战斗意志。"
D.Strings[68609]="去死吧！ "
D.Strings[68610]="小心，兄弟！"
D.Strings[68611]="畜生……霜狼氏族完了……钢铁部落来了…… "
D.Strings[68612]="那就让他们来吧！叛徒！"
D.Strings[68613]="雷神氏族撤退了！他们沿着雷霆小径往钢铁部落那儿去了。"
D.Strings[68614]="他们还会回来的。我们得做好准备。"
D.Strings[68615]="他怎么能这样对我们？"
D.Strings[68616]="我在战场上杀死了自己的侄子！"
D.Strings[68617]="“铁狼”是我们失踪的兄弟，曾经的……兄弟，亲人。"
D.Strings[68618]="他已经不再是了。"
D.Strings[68619]="他将作为雷神兽人下葬，带着酋长应有的荣誉。这是他的选择。"
D.Strings[68620]="来吧，杜隆坦。如果钢铁部落想要战争，我们就给他们战争。他们休想占领雷霆小径！"
D.Strings[68621]="贾纳尔……与你并肩作战是我的荣幸，兄弟。"
D.Strings[68622]="你还好吗，亲爱的？"
D.Strings[68623]="我必将为此抱憾终身。"
D.Strings[68624]="来吧！去雷霆小径。敌我人数是五十比一。他们毫无机会！"
D.Strings[68625]="谢谢你，孩子。我就知道你能靠得住。"
D.Strings[68626]="这里什么都没有。"
D.Strings[68627]="我会跟这个奴隶谈谈，看看他是否知道奥格瑞姆的下落。"
D.Strings[68628]="与此同时，我们还要抢在他们想出移动那门火炮的方法之前，帮德雷克塔尔找到摧毁它的方法。"
D.Strings[68629]="放下你的斧子，来火炉旁喝一杯美酒暖暖身子吧。"
D.Strings[68630]="给！这就是你要找到的东西吗，先知？"
D.Strings[68631]="长吧！长吧！"
D.Strings[68632]="蘑菇的力量。"
D.Strings[68633]="我们德莱尼并不是这个世界的原住民。我们的家乡叫做阿古斯，但它被燃烧军团攻占了。"
D.Strings[68634]="一小队幸存者在先知维伦的带领下侥幸逃了出来。"
D.Strings[68635]="克鲁恩来了！勇士，跟我来。"
D.Strings[68636]="我们的人民曾有三位领袖。他们是维伦、阿克蒙德和基尔加丹。"
D.Strings[68637]="当燃烧军团来到阿古斯时，维伦是唯一一个拒绝了他们许诺的永生和力量的人。"
D.Strings[68638]="基尔加丹领导着燃烧军团的恶魔大军。他曾是一位睿智的领袖，却被敌人的黑暗诺言所诱惑。"
D.Strings[68639]="他会不断追杀我们直至宇宙的尽头，直到亲眼看着我们毁灭。"
D.Strings[68640]="我们的祖先逃出阿古斯后，就一直在各个星球间流浪，寻找躲避燃烧军团的避难所。"
D.Strings[68641]="有一天，飞船上由纳鲁的灿烂光辉所驱动的能量源突然熄灭了。他们将能量源扔出了飞船，但已经太迟了。"
D.Strings[68642]="纳鲁是睿智、强大、纯粹的圣光生物。就是一位纳鲁找到了先知维伦，并帮忙策划了让我们逃出燃烧军团魔掌的计划。"
D.Strings[68643]="它们的大部分情况依然是未知数，但当纳鲁的能量耗尽时，它就会转化成黑暗状态。"
D.Strings[68644]="黑暗纳鲁是纯粹的暗影生物，而且看起来很可怕。"
D.Strings[68645]="如果我试图释放埃克索图斯，它肯定会引来克鲁恩。"
D.Strings[68646]="当飞船开始解体爆炸时，他们驶向了距离最近的一个世界——一片宁静而蛮荒的土地，后来我们将它命名为德拉诺。"
D.Strings[68647]="我们有伴儿了，主人。"
D.Strings[68648]="塔加尔，去对付入侵者。"
D.Strings[68649]="勇士！德雷克塔尔在召唤。我跟你去！"
D.Strings[68650]="霜狼们！钢铁部落来了。眼下，他们正涌向雷霆小径。"
D.Strings[68651]="但霜狼氏族已经统一！我们将携手保卫家园！"
D.Strings[68652]="Lok-Narash，霜狼们！准备战斗！"
D.Strings[68653]="我随时都能战斗，你是知道的。"
D.Strings[68654]="我们要守住这条阵线。"
D.Strings[68655]="德雷克塔尔，你能和大地沟通，在峡谷中制造塌方吗？ "
D.Strings[68656]="阻止他们！绝不能让他们打扰主人的冥想！"
D.Strings[68657]="这是个艰巨的任务……我不能保证。"
D.Strings[68658]="我可以。萨满，如果你能弄塌山崖，我就保证让敌人乖乖在下面等死。"
D.Strings[68659]="我会尽力而为的。"
D.Strings[68660]="最好快一点！他们要来了！"
D.Strings[68661]="你休想吵醒主人！"
D.Strings[68662]="霜狼们，坚守阵地！把他们放过来打！"
D.Strings[68663]="多来点！你们的鲜血将染红我的战斧！"
D.Strings[68664]="举起战斧！他们又来了！"
D.Strings[68665]="我从没见过你这么能打的萨满。"
D.Strings[68666]="因为我有最好的老师，德雷克塔尔。"
D.Strings[68667]="……你应该让你的老师少依赖锤子，多用用脑子。"
D.Strings[68668]="听到你这么说，他一定会很高兴的。"
D.Strings[68669]="……不，还是算了。"
D.Strings[68670]="快回来！他们很快就会卷土重来！"
D.Strings[68671]="杜隆坦，这里简直就像是……绞肉机！"
D.Strings[68672]="……可他们还是会冲上来。"
D.Strings[68673]="是啊！那才好呢！"
D.Strings[68674]="杜隆坦！来帮个忙！"
D.Strings[68675]="德雷克塔尔有麻烦了。贾纳尔，去帮他一把。"
D.Strings[68676]="我还以为你不会求我呢，兄弟。"
D.Strings[68677]="我听到你说的了！"
D.Strings[68678]="谢谢你。我欠你一条命。"
D.Strings[68679]="等一下再拥抱吧，萨满。我要刷新连斩记录了。"
D.Strings[68680]="后撤！准备下一次进攻！"
D.Strings[68681]="雷神兽人的味道……"
D.Strings[68682]="枪兵过来了！坚守阵地！"
D.Strings[68683]="又是一头雷象！"
D.Strings[68684]="又有雷象冲过来了！"
D.Strings[68685]="杜隆坦！把你的小崽子们放出来吧！"
D.Strings[68686]="英雄，靠近我的图腾接受援助！"
D.Strings[68687]="让我来。"
D.Strings[68688]="杜隆坦，看看这个小可爱！她会玩什么把戏吗？ "
D.Strings[68689]="我会的多着呢。"
D.Strings[68690]="来吧，小可爱。我们好好玩玩儿。"
D.Strings[68691]="既然你喜欢，那我们就来“玩”吧！"
D.Strings[68692]="德拉卡……跟我加入钢铁部落吧。脱掉那身盔甲，找个真正的男人吧。"
D.Strings[68693]="真正的男人应该尊重他的伴侣！"
D.Strings[68694]="……还要能接住这把斧子。"
D.Strings[68695]="霜狼们！坚持住！战斗就要结束了！"
D.Strings[68696]="德雷克塔尔！你还要多久？"
D.Strings[68697]="马上就好！"
D.Strings[68698]="我们全靠你了，萨满！"
D.Strings[68699]="酋长，你听到那个巨响了吗？"
D.Strings[68700]="听到了。有个大家伙过来了。"
D.Strings[68701]="很好，我就喜欢大家伙。"
D.Strings[68702]="戈隆！"
D.Strings[68703]="霜狼们——冲锋！打倒那家伙！"
D.Strings[68704]="为了我们的家园，为了亲人们！"
D.Strings[68705]="如果雷神氏族没有撒谎，那钢铁部落应该已经在路上了。阻止他们武力夺取霜火岭的任务就落在我们头上了。$b$b我们得立刻出发，保卫家园！"
D.Strings[68706]="德拉卡！你去斥候发现的那座山洞看看。我到海边的村子去跟指挥官汇合。"
D.Strings[68707]="勇士，等你完成自己的任务之后，就到前面去找我们吧。"
D.Strings[68708]="先知大人！耐奥祖把俘虏带去沙兹古尔了。"
D.Strings[68709]="呸！再卖力点，肮脏的奴隶！"
D.Strings[68710]="这些废物工人真是气死我了！啊啊！！"
D.Strings[68711]="快干活儿，否则我就砸碎你的脑袋！"
D.Strings[68712]="救、救命……快来人……有人吗……"
D.Strings[68713]="让它离德雷克塔尔远点！"
D.Strings[68714]="愿圣光保、保佑你……"
D.Strings[68715]="回诊所去工作吧。"
D.Strings[68716]="休息一下吧。"
D.Strings[68717]="我要拯救氏族，哪怕要赔上先祖的灵魂。"
D.Strings[68718]="要不是你，我可能还在那片丛林里挣扎，甚至更糟。"
D.Strings[68719]="让我们去见杜隆坦吧。"
D.Strings[68720]="我们必须不惜一切代价阻止塔隆戈尔和他的噬骨氏族盟友攻入奥金顿。"
D.Strings[68721]="艾索洛托斯太虚弱了。我最多只能帮他解开束缚。但他很快就会死的。"
D.Strings[68722]="要是我能再强大一点……"
D.Strings[68723]="你一定有办法的。"
D.Strings[68724]="它就快死了，我们没有时间了。"
D.Strings[68725]="有个办法。艾索洛托斯，寄宿在我的灵魂中，与我融合。你的火焰或许就不会熄灭。"
D.Strings[68726]="我很高兴你能来，$n。我们的军力太过薄弱。我需要一些靠得住的帮手。"
D.Strings[68727]="我的灵魂……在燃烧！"
D.Strings[68728]="德雷克塔尔，它对你做了什么？"
D.Strings[68729]="他和霜火之怒融合了。他们的灵魂合而为一了。"
D.Strings[68730]="奥金尼们对这场突袭毫无准备。奥金顿是一座陵墓，不是堡垒。他们需要我们的帮助。"
D.Strings[68731]="我……看到了。我看到元素的变迁，万灵在土地上迁徙。太……太壮观了。"
D.Strings[68732]="如果塔隆戈尔吞噬了里面的灵魂，后果将是灾难性的。"
D.Strings[68733]="食人魔将为他们的所作所为付出代价！"
D.Strings[68734]="我们对这场突袭毫无准备。奥金顿是一座陵墓，不是堡垒。"
D.Strings[68735]="$n，我们必须不惜一切代价阻止塔隆戈尔和他的噬骨氏族盟友攻入奥金顿。"
D.Strings[68736]="你太迟了，英雄。你的世界将被暗影吞噬！"
D.Strings[68737]="我做好出发的准备了，大主教。"
D.Strings[68738]="愿圣光祝福你。"
D.Strings[68739]="他死了？我还以为他想把我留到最后呢。来吧，冰爪，让我们离开这儿。"
D.Strings[68740]="我最后一次看到奥拉克时，他正追着冰爪跑出了沃高尔的南门。"
D.Strings[68741]="你真该去看看，叔叔！我把那头卑鄙的刃牙虎人刚好引到了我的陷阱里。"
D.Strings[68742]="是吗？干得好，奥拉克。你将来一定会成为出色的猎人。"
D.Strings[68743]="谁都逃不出虚空的手心！"
D.Strings[68744]="我们要守护自己的边疆！"
D.Strings[68745]="一旦黑心大人的传送门激活，他就会来接收钥匙并转呈给主人。"
D.Strings[68746]="主人需要钥匙碎片。我们必须守住它，直到黑心大人抵达！"
D.Strings[68747]="这个世界将属于我们，一如大人的预言。"
D.Strings[68748]="这头狼已被开膛破肚并任其腐烂。"
D.Strings[68749]="在我们的巨灵火炮面前，你们那些可怜的武器毫无用处！"
D.Strings[68750]="你是怎么在巨灵火炮的轰炸中活下来的？"
D.Strings[68751]="我们的巨灵火炮将毁灭你们所珍视的一切。"
D.Strings[68752]="黑暗就是我的力量！有了它，影月氏族必将成为胜利者！"
D.Strings[68753]="嗯？我肯定是晕过去了。我以为在温暖的篝火旁跟家人吃一顿热乎乎的饭菜不会有什么大问题的。"
D.Strings[68754]="鲜花？！不！！！"
D.Strings[68755]="求你……不要鲜花了……"
D.Strings[68756]="不是我！现在不行！"
D.Strings[68757]="传说是真的！"
D.Strings[68758]="什么都好，千万别是鲜花！"
D.Strings[68759]="我讨厌煮饭。我应该出去狩猎的。"
D.Strings[68760]="鲜花？"
D.Strings[68761]="没关系。你们已经迟了！"
D.Strings[68762]="来尝尝这个吧，爬虫们！"
D.Strings[68763]="塔隆戈尔来对付你了，凡人……"
D.Strings[68764]="杀了它。它威胁到了主人！"
D.Strings[68765]="新鲜多汁的内脏……"
D.Strings[68766]="杀了它，吃了它，烧死它！"
D.Strings[68767]="嗯？是库伦克派你来的？我马上就好，我们营地见。"
D.Strings[68768]="在搞定这里的事情之前，我是不会回去的。"
D.Strings[68769]="这件礼物最适合莱拉了。谢谢你，$n。等我搞定这里的事情之后，我就回营地去找你。"
D.Strings[68770]="|TInterface\\Icons\\ability_druid_astralstorm.blp:20|t%s施放了|cFFFF0000|Hspell:155105|h[灵魂风暴]|h|r！"
D.Strings[68771]="你的生命值过低！$b$b霜狼治疗者就在阻击点的后面。"
D.Strings[68772]="唔。你们想干什么？你们是钢铁兽人那头的吗？你们会跟他们一样喷火吗？"
D.Strings[68773]="杜隆坦想要跟你们结盟。"
D.Strings[68774]="我代表霜狼氏族欢迎你的到来，$c。"
D.Strings[68775]="比起失败带给我的痛苦，这根长矛不算什么。"
D.Strings[68776]="族人的死令我心痛不已……"
D.Strings[68777]="这么说，霜狼想要跟嘲颅一起玩玩？我得跟杜隆坦谈谈，但我对此不抱希望。他的狼都很软弱，而且缺乏信念。"
D.Strings[68778]="他们打算留着我当餐后甜点！"
D.Strings[68779]="伙计，真高兴能见到你！"
D.Strings[68780]="谢了，伙计！我本来想好好酬谢你的，但你一看就是个不求回报的人！"
D.Strings[68781]="真没想到我还能逃出这里！"
D.Strings[68782]="谢谢你，朋友！等回到竞技场，我一定会让你请我喝一杯的！"
D.Strings[68783]="他们还拿走了我的零钱包……我能跟你借几个金币吗？"
D.Strings[68784]="他们想要吃了我！"
D.Strings[68785]="我还以为自己死定了！谢了，伙计！"
D.Strings[68786]="那些脏兮兮的多毛怪突然就冒了出来！"
D.Strings[68787]="我怎么会遇上这种事？！"
D.Strings[68788]="啊啊！！！够了！让我死吧！"
D.Strings[68789]="艾玛不久前到过这里。循着她的足迹到山上去！"
D.Strings[68790]="我几乎可以肯定那就是伊瑞尔，可玛尔拉德现在不能分心。要是她还活着，我们一定会救她的。"
D.Strings[68791]="发现萨满之石：霜狼护佑"
D.Strings[68792]="发现萨满之石：霜狼之灵"
D.Strings[68793]="发现萨满之石：烈焰之触"
D.Strings[68794]="寒冰之触"
D.Strings[68795]="发现萨满之石：飞沙走石"
D.Strings[68796]="发现萨满之石：食人魔之韧"
D.Strings[68797]="飞沙走石"
D.Strings[68798]="食人魔之韧"
D.Strings[68799]="烈焰之触"
D.Strings[68800]="发现萨满之石：寒冰之触"
D.Strings[68801]="他们就是在这里抓住她的。"
D.Strings[68802]="入侵者来啦！影月兽人们，坚守岗位！"
D.Strings[68803]="火枪手，开火！别让他们进入堡垒！"
D.Strings[68804]="哦，小鬼，她很大，是不是？你最好回去跟玛尔拉德报告一声。"
D.Strings[68805]="别让他们过去！把狼放出来！"
D.Strings[68806]="我在尝试用占卜窥视耐奥祖的计划，可惜，至今一无所获。"
D.Strings[68807]="别找借口，考戈尔。我们正在与另一个世界作战。我不管你是去鼓动你的人民，还是拿起矿锄自己干。但你必须完成分派给你的定额，否则你的氏族就将成为我们下一次武器试射的目标。"
D.Strings[68808]="这里，让我来做个调整。"
D.Strings[68809]="好了，来吧。"
D.Strings[68810]="你进去之后，一定要让那门主炮重新开火。"
D.Strings[68811]="这可不太妙……"
D.Strings[68812]="可……我恐高啊！"
D.Strings[68813]="要我像小鸟一样飞翔？可我没有翅膀啊！"
D.Strings[68814]="我感觉到了主人的力量……在我的血管中流淌……"
D.Strings[68815]="以塔隆戈尔之名，去死吧！"
D.Strings[68816]="我将使用奥克纳鲁实现你的意志，主人！"
D.Strings[68817]="塔隆戈尔说了……尸体归我们……他只吃灵魂……"
D.Strings[68818]="他们人太多了。"
D.Strings[68819]="肮脏的懦夫。"
D.Strings[68820]="汉瑟尔！下面出什么事了？！"
D.Strings[68821]="去找到那些钢铁部落的懦夫。让圣光来制裁他们。"
D.Strings[68822]="你们这些人渣不配得到宽恕。"
D.Strings[68823]="钢铁部落已时日无多。"
D.Strings[68824]="塞林，去把坦克准备好。马上！"
D.Strings[68825]="这些兽人还没完没了了？"
D.Strings[68826]="我们得救了！谢谢你，英雄。"
D.Strings[68827]="考戈尔，你的守卫不堪一击。干掉这个入侵者。"
D.Strings[68828]="杜隆坦？德拉卡？你们在这儿干什么？"
D.Strings[68829]="你说得对，缚魂者。我们不能冒险让奥金顿变成不设防的空城。我们要用剩余的部队守住我们的土地。"
D.Strings[68830]="奥格瑞姆·毁灭之锤！你必须为你对我的人民发动的袭击付出代价！"
D.Strings[68831]="你们会哭着求我给你们一个痛快的。"
D.Strings[68832]="你们以为我是竞技场里那些不堪一击的废物吗？"
D.Strings[68833]="你们钢铁部落谋杀了我的兄弟，威胁我的人民，买卖奴隶，满手血腥。你还想让我们跟这种势力合作？"
D.Strings[68834]="住手，英雄。我要让他活着。"
D.Strings[68835]="只要封印不松动，奥金顿就是安全的。我们得取回钥匙碎片，让我的牧师们来守护它们。"
D.Strings[68836]="我不是想忘记或宽恕他的罪行。但奥格瑞姆曾是一个高尚的兽人，是我最好的朋友。我至少应该给他一个重拾荣耀的机会。"
D.Strings[68837]="你还是这么多愁善感，杜隆坦。和你一样，我也要忠于我的人民。别以为我是自愿走上这条路的。有些事比荣誉更重要。"
D.Strings[68838]="丈夫？是他的军队杀害了你的兄弟。"
D.Strings[68839]="够了。我们没有多余的人手了。我们得留在这里。"
D.Strings[68840]="暗影余孽冲破了束缚！"
D.Strings[68841]="我们得尽快找回其他碎片，否则就迟了。"
D.Strings[68842]="等等，$n……我跟你一起去。"
D.Strings[68843]="来了！隐蔽！"
D.Strings[68844]="朋友们，准备出发吧。这位英雄会掩护我们冲进奴隶营地的！"
D.Strings[68845]="为了毁灭之锤！"
D.Strings[68846]="要是再让钢铁部落开一次炮，我们就完了。不管那些超大炮弹是用什么打出来的，我们都得摧毁它。"
D.Strings[68847]="那里到处都是炸药包。但是，我们得一路冲到最里面，才能让那门大炮重新开火。"
D.Strings[68848]="跟我来，$n。我要为牺牲的同胞们进行临终祈祷。你来对付神殿里残余的钢铁部落士兵。"
D.Strings[68849]="按钮就在那儿。按下它就能重启巨型火炮了。"
D.Strings[68850]="你下去的时候，顺便看看汉瑟尔有没有什么需要吧。"
D.Strings[68851]="所谓的妙计也不过如此。嘲颅氏族的那些家伙会把我们都害死的。"
D.Strings[68852]="唔。我记得食人魔的建筑应该要比这坚固得多。"
D.Strings[68853]="我要杀了你，就像我杀死其他人一样！"
D.Strings[68854]="感谢圣光，你来得正是时候。"
D.Strings[68855]="愿圣光指引我们的利剑刺入敌人的心脏。"
D.Strings[68856]="你准备好之后，我们就可以出发了。"
D.Strings[68857]="你这个没脑子的蠢货！那个轮子怎么还没修好？"
D.Strings[68858]="石头都比你的动作快！"
D.Strings[68859]="快把那个轮子修好，否则我就把你扔给白鬼！快干活！"
D.Strings[68860]="修好了没有？影月氏族还等着我们呢。"
D.Strings[68861]="谢谢你救了我，英雄。其他俘虏都被他们带到山顶上去了。"
D.Strings[68862]="<前往碎脊裂口。>"
D.Strings[68863]="维伦派我来的。我们正在搜集有关耐奥祖的情报。"
D.Strings[68864]="欢迎，旅行者。我很了解耐奥祖，可他最近完全变了。我们或许可以互相帮助。"
D.Strings[68865]="我没下过这种命令。我是想让你的人民加入我们，共同抵抗来自传送门另一边的威胁。"
D.Strings[68866]="改写载具控制命令。返回创建者位置。"
D.Strings[68867]="你好，旅行者。今天你想飞去哪儿呢？"
D.Strings[68868]="我很高兴你能看到这其中所包含的智慧，杜隆坦。但愿玛尔拉德和联盟也能和你一样。"
D.Strings[68869]="跟我的某些同胞不同，我对德莱尼向来不抱偏见，卡德加。"
D.Strings[68870]="你的计划很有道理，我愿意加入。我们进城之后，保证不会轻举妄动。"
D.Strings[68871]="你可以相信卡德加的计划，杜隆坦。他的事业是正义的，他的动机是高尚的。"
D.Strings[68872]="你们就是我的先锋。"
D.Strings[68873]="这片海岸属于我们！"
D.Strings[68874]="不要放过任何敌人！"
D.Strings[68875]="铁血意志，非胜即死。"
D.Strings[68876]="向胜利前进吧！"
D.Strings[68877]="指挥官。$B$B我们已经控制住了洛克拉斯和战歌氏族。$B$B随时等候你的命令。"
D.Strings[68878]="我们不能再放任战歌氏族穷追猛打。$B$B我们更不能让悬槌食人魔重拾高里亚帝国的辉煌。$B$B在被它毁灭之前，我们必须保护自己的族人，在纳格兰伸张正义。"
D.Strings[68879]="不久之前，我们还是分属不同氏族的兽人，为了一点残羹冷炙争斗不休，忽视了本该属于我们的世界。"
D.Strings[68880]="而现在，作为一个统一的氏族，没有敌人能够阻挡钢铁部落！"
D.Strings[68881]="我们将踏碎他们的尸骨。我们要烧毁他们的城市！"
D.Strings[68882]="钢铁狂潮将会湮没他们！"
D.Strings[68883]="关闭"
D.Strings[68884]="即将降临的灾难将毁灭我们所有人。如果兽人们不能齐心协力，先发制人，这些外来者就会把烈火和死亡倾泻到我们头上。"
D.Strings[68885]="因为我亲眼见证过这一幕！每个晚上！许多个月以来，夜夜如此。我的梦境变成梦魇，在那些噩梦中，我无助地看着我们脚下的大地被腐蚀，天空化为火海。"
D.Strings[68886]="不管你们怎么想，但末日即将来领。而这些来自传送门另一头的生物，就是造成灾难的罪魁祸首。"
D.Strings[68887]="你怎么这么肯定？"
D.Strings[68888]="我可从来不知道伟大的毁灭之锤也有害怕的时候。"
D.Strings[68889]="古加尔！我是派你来奴役这个家伙的。"
D.Strings[68890]="小心别被压制住！他们骁勇善战！"
D.Strings[68891]="让我们开始攻击吧！"
D.Strings[68892]="要是我们能把钢铁部落赶出沙塔斯，那将对他们的战略造成重大打击。如果我们还能解决掉他们的超级武器……"
D.Strings[68893]="带上这些火把，清理掉神殿里的兽人尸体。"
D.Strings[68894]="我们会永远记住你的，我亲爱的朋友。"
D.Strings[68895]="维伦会制裁这场闹剧的始作俑者的，我对此深信不疑。"
D.Strings[68896]="你见到我的父母了吗？"
D.Strings[68897]="喂！请……透不过气了……"
D.Strings[68898]="我不知道你是谁，但我不会忘记你今天的善举的。"
D.Strings[68899]="Lok'tar……朋友。我们在村子里再见。"
D.Strings[68900]="好了！让我们解放所有的嘲颅兽人吧！让他们想起该怎么笑！把这些奴隶贩子都烧成灰烬！"
D.Strings[68901]="啊哈哈哈哈！杀戮时刻！"
D.Strings[68902]="捅死所有人！"
D.Strings[68903]="烧死奴隶贩子！用鞭子抽他们！让他们满地爬！"
D.Strings[68904]="让食人魔再次恐惧嘲颅氏族！"
D.Strings[68905]="我！回！来！了！"
D.Strings[68906]="现在是……捅死食人魔的时刻！"
D.Strings[68907]="谢谢你，$n。我们欠你一个人情。"
D.Strings[68908]="我听说独眼的食人魔比两只眼的食人魔更聪明。我们不如来试试？"
D.Strings[68909]="死神等着你，叛徒……"
D.Strings[68910]="来打个赌。我要捅几下才能让这个恶棍尖叫呢？"
D.Strings[68911]="噢，我们会让你哈哈大笑的。他们会一直笑……笑到死为止。"
D.Strings[68912]="我在想，那些狼崽子会让我们留着你吗？"
D.Strings[68913]="啊，一个既不属于霜狼也不属于嘲颅的勇士。$b$b我很好奇，你是否会选择一面旗帜向它效忠呢？还是最终让它们效忠于你？"
D.Strings[68914]="非常感谢，勇士，你让我想起了我是谁。迟早有一天，钢铁部落也会想起这一点，他们将为此感到恐惧。"
D.Strings[68915]="你赢得了嘲颅兽人的支持，英雄。但愿等你明白它真正的含义时，不会像那些狼崽子一样大惊小怪。"
D.Strings[68916]="我期待着捅死你的敌人。"
D.Strings[68917]="断肢说你把他从一座着火的房子里救了出来。那你有没有抢救出他欠我的钱？"
D.Strings[68918]="笑吧……"
D.Strings[68919]="为了嘲颅！"
D.Strings[68920]="见证我们的力量吧！铁血意志，非胜即死！"
D.Strings[68921]="摧毁温度调节器，释放熔炉中的山脉之心。"
D.Strings[68922]="|TInterface\\Icons\\ability_foundryraid_bellows.blp:20|t鼓风者正在提高熔炉温度，快击败他们，阻止温度升高。"
D.Strings[68923]="一个压力调节器已被摧毁，还剩一个。"
D.Strings[68924]="两个温度调节器都被摧毁，山脉之心出现！"
D.Strings[68925]="击败元素尊者，解开山脉之心的束缚。"
D.Strings[68926]="还有三个元素尊者。"
D.Strings[68927]="还有两个元素尊者。"
D.Strings[68928]="还有一个元素尊者。"
D.Strings[68929]="所有元素尊者都被击败，山脉之心自由了！"
D.Strings[68930]="不惜一切代价保护熔炉！ "
D.Strings[68931]="快拉风箱！"
D.Strings[68932]="提高温度，伙计们，蒸熟他们！"
D.Strings[68933]="再叫点守卫进来！"
D.Strings[68934]="去死吧，渣滓！"
D.Strings[68935]="噢……呃……"
D.Strings[68936]="快，控制住它！"
D.Strings[68937]="卫兵！入侵者正在破坏熔炉！"
D.Strings[68938]="设备损坏了。别让那些渣滓破坏熔炉！"
D.Strings[68939]="熔炉过热了！蠢货，如果让怒炎之灵跑出来，我们的工作就全完了！"
D.Strings[68940]="怒炎之灵已得到控制，请增派安保人员来清理区域内的入侵者。"
D.Strings[68941]="我们正在损失控制人员。安保部队，解决入侵者！"
D.Strings[68942]="一次小小的胜利，但你们将在黑石核心的烈焰中化为灰烬！"
D.Strings[68943]="趁早享受你们的胜利吧。和我相比，爆裂熔炉里的烈焰就像火山面前的蜡烛一样微不足道！"
D.Strings[68944]="坚持住，卡拉波的防御者们！圣光与你们同在！"
D.Strings[68945]="只要团结一致，我们就能赶走这些兽人！"
D.Strings[68946]="让圣光指引你们赢下这场战斗！"
D.Strings[68947]="钢铁狂潮将湮没我们的敌人！"
D.Strings[68948]="啊啊啊啊！哈哈哈！"
D.Strings[68949]="火！火！哇啊啊！哈！"
D.Strings[68950]="……V.2.6型地震追踪器启动……"
D.Strings[68951]="……正在追踪……失败：：降低震源深度……正在追踪……失败：：降低震源深度……"
D.Strings[68952]="卓古克是一个骄傲的兽人。感谢你让他带着荣耀上路。"
D.Strings[68953]="……震源偏移：：百分之二十……"
D.Strings[68954]="……警告：：体波接近……"
D.Strings[68955]="……警告：：发现地表塌陷……"
D.Strings[68956]="明白我的意思了吧？我们不可能精确定位地震活动的震源……"
D.Strings[68957]="唔……震源在移动？这怎么可能？！"
D.Strings[68958]="啊哦……打起精神来！"
D.Strings[68959]="”地表塌陷“？噢，你想到了没？！它在往外喷兽人！"
D.Strings[68960]="……正在追踪……发现新震源……正在追踪……位移：：百分之五十……"
D.Strings[68961]="又来了一个！"
D.Strings[68962]="……警告：：地表即将塌陷……"
D.Strings[68963]="好吧，收到。"
D.Strings[68964]="……正在追踪……未发现地震活动……"
D.Strings[68965]="……最终分析：：地震活动源属于非自然成因……"
D.Strings[68966]="……感谢使用地震追踪器……祝你过得愉快……"
D.Strings[68967]="噢，靴子在上，总算完了……"
D.Strings[68968]="哟，分析很精彩。多谢了。"
D.Strings[68969]="我要让你们这些鬣蜥人吃到苦头！"
D.Strings[68970]="伊瑞尔——啊啊！"
D.Strings[68971]="勇士，我们会守好这条道路的。"
D.Strings[68972]="卡拉已经选择了你作为突围的人选——你将得到纳鲁之力的加持。"
D.Strings[68973]="伊瑞尔，先知维伦呢？"
D.Strings[68974]="先知维伦已经……牺牲了。"
D.Strings[68975]="但他的光辉将永存我们心间。谁都无法阻挡我们。"
D.Strings[68976]="勇士，前进吧！铲平那座营地！"
D.Strings[68977]="让我们离开这里吧。伊瑞尔已经回卡拉波去了，她想跟我们谈谈。"
D.Strings[68978]="我们已经把他们赶回堡垒里去了。$b$b现在，是时候把他们彻底赶出影月谷了。"
D.Strings[68979]="那我们就快动手吧。"
D.Strings[68980]="英雄，到暮光林地去找我吧。我们必须救出那些俘虏。"
D.Strings[68981]="预言是高难度的法术。未来经常模糊不清，一个人只能靠直觉来分辨哪些是必然发生的，哪些是有可能发生的。"
D.Strings[68982]="自——由——！"
D.Strings[68983]="我要把你们都烧成灰！"
D.Strings[68984]="湮没在火海中吧！"
D.Strings[68985]="我的烈焰将让你们的血肉一块块剥落！"
D.Strings[68986]="我要毁灭一切！"
D.Strings[68987]="我的火焰……熄……灭了。"
D.Strings[68988]="我要将这座山化为灰烬！"
D.Strings[68989]="热得受不了了？那就滚出熔炉吧！"
D.Strings[68990]="爆裂熔炉里的入侵者已被消灭。马上将他们的尸体扔进熔炉，然后返回岗位！"
D.Strings[68991]="燃烧吧！烧灼吧！着火吧！"
D.Strings[68992]="霜狼和嘲颅？合作？你们兽人比我想象得还要疯狂。"
D.Strings[68993]="干得好，$n。这些水晶是几百年前，我们来到这个世界时，从我们的飞船上散落下来的。"
D.Strings[68994]="可惜的是，耐奥祖口中的”黑暗之星“也如影而至。"
D.Strings[68995]="我恐怕我们的到来已经彻底改变了影月兽人的命运。"
D.Strings[68996]="我会好起来的。再次感谢你的帮助，$n。"
D.Strings[68997]="干的不错，勇士。现在，我们只剩三块水晶要找了。"
D.Strings[68998]="你迷路了吗，陌生人？"
D.Strings[68999]="有外来者靠近。"
D.Strings[69000]="小心点，陌生人。"
D.Strings[69001]="放下你的武器。这肯定是德莱尼先知许诺过的信使。"
D.Strings[69002]="请找到那些俘虏，英雄。我的姐妹也在其中。如果我是个战士就好了，那我就能帮上忙了……"
D.Strings[69003]="我已经得到了惨痛教训，伊瑞尔。你必须竭尽全力，为你爱的人而战。"
D.Strings[69004]="你要坚信圣光会保佑你的——如果那不管用，就相信自己，然后做你该做的事。"
D.Strings[69005]="先知——你还好吗？"
D.Strings[69006]="我不小心听到了你们的谈话。玛尔拉德说得对。有时，我们必须为自己的事业奉献一切。"
D.Strings[69007]="但我们绝对、绝对不能背弃圣光……哪怕这会耗尽我们的生命。"
D.Strings[69008]="好极了！这块水晶已经失踪几十年了。"
D.Strings[69009]="你收集的能量是我们对抗黑暗之星的唯一希望……"
D.Strings[69010]="这只是第一块水晶。我们必须找到其他三块！"
D.Strings[69011]="这是最后一块水晶了。等你完成任务之后，就来特鲁纳山顶上见我吧，勇士。"
D.Strings[69012]="耐奥祖正在努力争取钢铁部落的信任。"
D.Strings[69013]="为此，他不惜搬出他根本无法控制的暗影魔法。"
D.Strings[69014]="如果他成功召唤出黑暗之星，他的氏族——还有他的世界——都将为他的傲慢所累。"
D.Strings[69015]="我们已经找到了两块水晶，必须在耐奥祖完成仪式前找到其余的两块。"
D.Strings[69016]="只剩一块水晶了。要想成功，我们就需要全部四块水晶的力量。"
D.Strings[69017]="这是最后一块水晶了。快到特鲁纳山的山顶来见我——时间已经不多了！"
D.Strings[69018]="感谢你的帮助，$n。我会把这些发现报告给维伦的。"
D.Strings[69019]="我们要找的水晶就在那边的山上。"
D.Strings[69020]="魔荚人本想把这些雷象留到以后再吃。如果你愿意的话，可以骑上这头雷象，返回森林的外围。"
D.Strings[69021]="我绝不能坐视卡拉波被焚毁，$n。我要跟你一起去。"
D.Strings[69022]="我不是个战士，但我会尽力而为的。"
D.Strings[69023]="我是在这座神殿接受训练的。我希望能一辈子呆在这里。"
D.Strings[69024]="我可不想千辛万苦从塔纳安的奴隶营地逃回来，却看到家园化为火海。"
D.Strings[69025]="你战斗起来很英勇，$n。你的表现鼓舞了我。"
D.Strings[69026]="我想这里应该是安全的！谁会来攻击神殿呢？"
D.Strings[69027]="等这一切结束后，我想回去继续教导我的学生。"
D.Strings[69028]="我没受过战斗训练。我又不是守备官！"
D.Strings[69029]="他们想把我们的光辉圣殿变成某种……黑暗神庙！"
D.Strings[69030]="那肯定是他们的首领，就在亭子上。"
D.Strings[69031]="小心脚下，$n！他会烧光眼前的一切！"
D.Strings[69032]="我会尽力协助你的。"
D.Strings[69033]="这些兽人简直像钢铁和火焰的化身。他们以前不是这样的。"
D.Strings[69034]="我想这应该管用。"
D.Strings[69035]="你真是……又蛮横又直接。你肯定经历过战斗。"
D.Strings[69036]="一想到围墙外的厮杀，我就忍不住发抖。"
D.Strings[69037]="问题解决了。"
D.Strings[69038]="我们的神殿还能从这场大战中恢复过来吗？"
D.Strings[69039]="|TInterface\\Icons\\item_summon_cinderwolf.blp:20|t%s召唤出了|cFFFF0000烬狼|r！"
D.Strings[69040]="他们这是在送死！"
D.Strings[69041]="先知就在前面！"
D.Strings[69042]="快，$n！我看到维伦就在前面！"
D.Strings[69043]="先知维伦会救我们的。"
D.Strings[69044]="|TInterface\\Icons\\spell_shaman_stormearthfire.blp:20|t%s开始引导|cFFFF0404|Hspell:155493|h[火焰风暴]|h|r！"
D.Strings[69045]="耐奥祖已经向我们展示了黑暗中的力量！"
D.Strings[69046]="仪式很快就会完成。黑暗之星来了！"
D.Strings[69047]="你的鲜血将滋养黑暗之星……"
D.Strings[69048]="虚空在召唤我们！"
D.Strings[69049]="黑暗中的力量。"
D.Strings[69050]="耐奥祖曾窥视虚空，并得到了它的回应……"
D.Strings[69051]="耐奥祖赐予我们虚空的力量！"
D.Strings[69052]="我们被袭击了！"
D.Strings[69053]="他们在摧毁我们的城市！"
D.Strings[69054]="德莱尼必将陨落，众生都将臣服于虚空。"
D.Strings[69055]="谢谢你，勇士。我早就预感我的命运会与黑暗之星发生交集。"
D.Strings[69056]="圣光。纯粹的圣光。绝望时代的希望，我们黑暗中的光明！"
D.Strings[69057]="耐奥祖的仪式……开始了！我们要没时间了！"
D.Strings[69058]="我们必须阻止影月酋长。"
D.Strings[69059]="那是我们的责任，孩子。"
D.Strings[69060]="快，勇士。我会尽快赶来的。"
D.Strings[69061]="你要尽力拖住耐奥祖……"
D.Strings[69062]="先知！你在做什么！？"
D.Strings[69063]="唔！唔唔！！"
D.Strings[69064]="那就来吧！这个样机应该能把我们送到塞林那里去！"
D.Strings[69065]="<逐夜不断地抓着摇摇欲坠的木质路障。>"
D.Strings[69066]="你不必如此，伊瑞尔。带上幸存者撤退吧。"
D.Strings[69067]="嘲颅！嘲颅！哈哈哈哈哈哈！"
D.Strings[69068]="现在，是时候把他们彻底赶出影月谷了。"
D.Strings[69069]="圣光在上——那是什么！？"
D.Strings[69070]="它肯定有弱点——绕到它背后去！"
D.Strings[69071]="兽人是怎么造出这种怪物的？"
D.Strings[69072]="这种东西在你的世界很常见吗？"
D.Strings[69073]="在守卫离开的间歇，我秘密制作了一个小玩意儿。"
D.Strings[69074]="苏特！到爸爸这儿来！"
D.Strings[69075]="它很漂亮，不是吗？现在，让我们去搞搞破坏吧。"
D.Strings[69076]="卫兵！卫兵！？那些废物上哪儿去了？"
D.Strings[69077]="我的宠物又有霜狼崽子吃了！裂肠，进攻！"
D.Strings[69078]="你会变成猪食的！"
D.Strings[69079]="营地里有入侵者！"
D.Strings[69080]="营地里有敌人！"
D.Strings[69081]="我要把你的脑袋献给乌尔戈斯，他会奖赏我的！"
D.Strings[69082]="你们对我的妨碍到此为止了！"
D.Strings[69083]="你们是在妄图对抗注定好的命运。"
D.Strings[69084]="我已经死过一次了……"
D.Strings[69085]="钢铁部落已经对我们在德拉诺所珍视的一切都造成了明确且迫在眉睫的威胁。"
D.Strings[69086]="这些数据……太惊人了。哪个疯子会把自己的同胞变成这样？"
D.Strings[69087]="不！我们的工作绝不能中断！"
D.Strings[69088]="黑暗之星的力量在我们体内流淌！你休想阻止我们！"
D.Strings[69089]="这是我们的森林！"
D.Strings[69090]="钢铁部落只是在试探我们……"
D.Strings[69091]="烬喉潜入地下，向东南方钻去。"
D.Strings[69092]="%被水晶中的力量压垮了。"
D.Strings[69093]="保护我！我需要维持传送门！"
D.Strings[69094]="烬喉潜入地下，向北方钻去。"
D.Strings[69095]="黑心大人！陵墓里有入侵者！"
D.Strings[69096]="我们不需要你的宝贝钥匙。我们是……燃烧军团……"
D.Strings[69097]="塞林的应急工具已经可以安装了！"
D.Strings[69098]="伊瑞尔！我们要让兽人血债血偿……"
D.Strings[69099]="我是酋长；我命令你立即把你的人撤回来。"
D.Strings[69100]="你现在这副样子，真让父亲蒙羞！"
D.Strings[69101]="我们的力量来自团结一致。"
D.Strings[69102]="我们会帮你打败你的敌人。我们会把欠你的人情还给你的，小东西。"
D.Strings[69103]="我欠你一份人情，小东西。你将我的人民从永恒的痛苦中拯救了出来。"
D.Strings[69104]="很少有霜狼兽人愿意到这么远的东方来做买卖。"
D.Strings[69105]="你可以在这里得到庇护，旅行者。充分的休息能让你在战斗中表现更出色。"
D.Strings[69106]="是谁派你来的？！枯蕾，肯定是枯蕾。真该死！"
D.Strings[69107]="而你……没错！就是你！向你那个叛徒大王卑躬屈膝，为你的傲慢而死吧！！！"
D.Strings[69108]="虽然我不忍看着自己的孩子被消灭，但我也不能让你独自进入灵魂世界。"
D.Strings[69109]="我的灵魂将与你同行。等任务完成之后，再回来见我吧。"
D.Strings[69110]="我很高兴你能看到这其中所包含的智慧，玛尔拉德。我相信杜隆坦和他的氏族也会明白的。"
D.Strings[69111]="我承认，杜隆坦的确是个比他大部分同胞都睿智得多的领袖。"
D.Strings[69112]="如果你能说服他同意你的计划，我们也愿意照办。"
D.Strings[69113]="我做好参加沙塔斯之战的准备了！[排队等待单人副本。]"
D.Strings[69114]="蠢货！我可不是这么好骗的！"
D.Strings[69115]="奥格瑞姆曾得意地提到过钢铁部落的实力，可我从未想到他们会如此强大。这里的规模……$b$b只凭我们的小队不可能摧毁这个基地，但我们至少要阻止那些舰船离开港口。你愿意跟我一起去吗，$n？"
D.Strings[69116]="我跟你去，酋长。"
D.Strings[69117]="无尽的愤怒……面对狼的怒火吧！"
D.Strings[69118]="不！我会继承你的力量……"
D.Strings[69119]="你的心……在渴望着烈焰……"
D.Strings[69120]="弗特莱！我会为你报仇的！敌人必须——血！债！血！偿！"
D.Strings[69121]="伊瑞尔，跟我们一起走走吧……"
D.Strings[69122]="装填火药"
D.Strings[69123]="哈哈！完蛋！"
D.Strings[69124]="根本不值一抓！"
D.Strings[69125]="下一个！哈哈！"
D.Strings[69126]="我是不会死的！弗特莱，来帮帮你的主人！ "
D.Strings[69127]="来啊！我要把你们的血肉跟骨头喂给野兽！ "
D.Strings[69128]="尝尝我的怒火吧！"
D.Strings[69129]="让我们碾碎他们！"
D.Strings[69130]="把你的力量给我！"
D.Strings[69131]="野性爆发！"
D.Strings[69132]="我不会让他独自上路的。"
D.Strings[69133]="他们会……为我……报仇的……"
D.Strings[69134]="一头绿色的蜘蛛咬了我，但只是小伤而已。吃得苦中苦，方为人上人，不是吗？"
D.Strings[69135]="我是见习守备官，所以还能对付一两头蜘蛛。可当夜幕降临，黑暗中亮起上百双眼睛时……"
D.Strings[69136]="“我们去旧矿井探险吧，”她说，“我需要一些标本来做研究。”噢，我为什么要听伊萨莉的？"
D.Strings[69137]="蜘、蜘、蜘、蜘蛛……为什么会有蜘、蜘、蜘蛛呢？"
D.Strings[69138]="请找到我的其他三位朋友！如果你能救出他们，那我在回到圣光之眠后一定会好好报答你的。"
D.Strings[69139]="我的另外两个朋友还在里面……请找到他们，英雄。"
D.Strings[69140]="没关系，我可以自己回圣光之眠去，可我还有一个朋友失踪了。请找到他们！"
D.Strings[69141]="你找到其他人了？谢天谢地！来圣光之眠找我吧。我们一定会想办法好好感谢你的。"
D.Strings[69142]="请找到我的其他三位朋友！如果你能救出他们，那我在回到誓日营地后一定会好好报答你的。"
D.Strings[69143]="没关系，我可以自己回誓日营地去，可我还有一个朋友失踪了。请找到他们！"
D.Strings[69144]="你找到其他人了？谢天谢地！来誓日营地找我吧。我们一定会想办法好好感谢你的。"
D.Strings[69145]="“我们去旧矿井探险吧，”她说，“我需要一些标本来做研究。”噢，我为什么要听诺拉纳的？"
D.Strings[69146]="我是见习血骑士，所以还能对付一两头蜘蛛。可当夜幕降临，黑暗中亮起上百双眼睛时……"
D.Strings[69147]="伙计们？我……我感觉……不太好……"
D.Strings[69148]="我要保护我的土地和人民，无论要付出怎样的代价。"
D.Strings[69149]="我跟你去！[开启场景战役]"
D.Strings[69150]="我……知道的……都已经说了…… "
D.Strings[69151]="你到底会不会拿武器！？"
D.Strings[69152]="就像从德莱尼手里抢糖果一样简单。"
D.Strings[69153]="它现在归我了！"
D.Strings[69154]="我从伊萨莉还是个小姑娘时就认识她了。她总是给我惹麻烦！"
D.Strings[69155]="我到现在还能听见它们……发出的吱吱声……$B$B<多鲁恩颤抖了起来。>"
D.Strings[69156]="好吧，我很高兴我们能毫发无损地逃出来。"
D.Strings[69157]="我到现在还能听见它们……发出的吱吱声……$B$B<奥利安颤抖了起来。>"
D.Strings[69158]="没错！我再也不参加诺拉纳的白痴探险队了！"
D.Strings[69159]="看来你们都安全了。"
D.Strings[69160]="谢谢你，$n，我们都活下——伊萨莉？你还好吗？"
D.Strings[69161]="谢谢你，$n，我们都活下——诺拉纳？你还好吗？"
D.Strings[69162]="给我流血吧！"
D.Strings[69163]="我要把你烤熟！ "
D.Strings[69164]="我们会继续收集霜狼氏族的消息，包括他们为了保命所做的一切努力。"
D.Strings[69165]="有东西吗？"
D.Strings[69166]="你看见什么了吗？"
D.Strings[69167]="雪……我看到了很多雪。"
D.Strings[69168]="呸……这纯属白费时间。高斯克根本不知道他在做什么。"
D.Strings[69169]="唔……没错。我们干得很好。去告诉高斯克，我们在这里的确刺探到了重大情报。"
D.Strings[69170]="很好。我会告诉高斯克的。"
D.Strings[69171]="它正好就在前面，在陵墓的最深处。我得离开这儿！"
D.Strings[69172]="点燃木桶"
D.Strings[69173]="$n，你可回来了！快拿上这辆车上的箱子。这是我的一点小心意，谢谢你救了我的命。"
D.Strings[69174]="我是这里最棒的战士！我要好好揍你一顿。"
D.Strings[69175]="嘿，$n，还记得我吗？你在英灵之庭救过我的命！拿上我身后这个箱子，那是我的一点谢意。"
D.Strings[69176]="什么？快停下！我要揍你……"
D.Strings[69177]="<哇啊啊！！！>"
D.Strings[69178]="你以为你能打败我！？？？我要揍扁你的猪头，$c！"
D.Strings[69179]="他从桥上滑下去了？"
D.Strings[69180]="我会尽力不让传送门关闭的！"
D.Strings[69181]="快走吧，趁我还能坚持住！"
D.Strings[69182]="这个蠢货……好吧，让我们拿上这些补给品回营地去。"
D.Strings[69183]="你干得很好，缚魂者。"
D.Strings[69184]="来吧，塔隆。奥金顿在等着我们。你将获得难以想象的力量。"
D.Strings[69185]="钢铁部落会毫不犹豫地用那门火炮对准我们的营地。我们得换个地方。"
D.Strings[69186]="我好像尿裤子了……"
D.Strings[69187]="我的酒还在那儿呢……"
D.Strings[69188]="嗯，大家似乎都没事。"
D.Strings[69189]="很好。我们得在前面扎营，然后再来对付这门火炮。"
D.Strings[69190]="伊瑞尔只能等等了。"
D.Strings[69191]="该你了，胡尔坎。以我的名义，干掉这些凡人！"
D.Strings[69192]="灵魂的盛宴正在等着我。"
D.Strings[69193]="我的氏族属于血魔！"
D.Strings[69194]="妮可茜死了？太好了！她就是那么鼠目寸光。伙计们，我们走！"
D.Strings[69195]="打起精神来，你们这些废物！很遗憾卡尔拉克离开了我们，可这并不意味着你们就可以偷懒了。"
D.Strings[69196]="我跟你说了多少次了！你要是一直把那个桶放在外面，它会坏掉的！"
D.Strings[69197]="钢铁部落为了把这些货准时送到可是给了一个好价钱的。所以给我再卖力点！"
D.Strings[69198]="你休想逃走。"
D.Strings[69199]="卡尔拉克这蠢货……我要向钢铁部落的人力资源部投诉这个白痴，如果他们有人力资源部的话。"
D.Strings[69200]="我真该保住在艾泽拉斯的卡亚可乐工厂的工作。"
D.Strings[69201]="我才不在乎你怎么想！我是这里的头儿。现在，给我回去干活！"
D.Strings[69202]="货车被一只大虫子袭击了，那个又高又壮的钢铁部落兽人又干了些什么？"
D.Strings[69203]="他抱着一桶啤酒逃跑了。嘁……"
D.Strings[69204]="嘿！你在这儿干嘛呢？！你别想碰我们的货！"
D.Strings[69205]="叮——咚！妮可茜死啦！"
D.Strings[69206]="我们终于自由了！"
D.Strings[69207]="很高兴见到你，$R，我们急需你的帮助！"
D.Strings[69208]="开始建造！"
D.Strings[69209]="准备好开始建造要塞了吗？"
D.Strings[69210]="各位。伊瑞尔正被关押在石槌食人魔的奴隶营地里。"
D.Strings[69211]="要不是某个谎话连篇的游侠，伊瑞尔没准已经得救了。"
D.Strings[69212]="我做了我认为正确的选择，守备官。那个失踪的女孩让你无法专注于我们的任务。"
D.Strings[69213]="没错，这个女孩到底有什么特别的？"
D.Strings[69214]="我曾失去过她一次。我不能再失去她了。"
D.Strings[69215]="我理解你的心情。"
D.Strings[69216]="而且，食人魔在向钢铁部落出售奴隶。在任务范围内教训他们一下也挺不错的。"
D.Strings[69217]="你们都会被揍扁的。"
D.Strings[69218]="噢，食人魔，那你可就错了。你瞧，今天，我们才是揍人的一方。塞林？"
D.Strings[69219]="在，队长！"
D.Strings[69220]="我们机会来了！塞林，全速前进！"
D.Strings[69221]="什么……？"
D.Strings[69222]="你们都给我安静点儿！食人魔，你要是再嘟嘟囔囔的，我就亲手揍扁你。"
D.Strings[69223]="我们可以在那里扎营。"
D.Strings[69224]="奥克默克再也不出声了，别打奥克默克。"
D.Strings[69225]="哎，我预感你肯定要挨揍了。"
D.Strings[69226]="直接攻击。一个大胆的决定。"
D.Strings[69227]="召集同伴。明智的决定。"
D.Strings[69228]="所有人，集合整队。我们要向硝烟仓栈进发了。"
D.Strings[69229]="所有人，集合整队。我们要向高地进发了。"
D.Strings[69230]="那头雷象还能多载一个人吗？"
D.Strings[69231]="当然，亲爱的。"
D.Strings[69232]="伊瑞尔，你在被捕之前，侦察到什么有关巨灵火炮的情报吗？"
D.Strings[69233]="我查到了一点。你们摧毁的那门火炮只是一个样品。北边的军工厂里正在建造实战用的火炮。"
D.Strings[69234]="我偷听到一个兽人头目说，他们打算用这些火炮去攻打沙塔斯。"
D.Strings[69235]="沙塔斯？哈！就算是那个大铁疙瘩也不可能从这里打到沙塔斯啊。"
D.Strings[69236]="如果它们被装上船，那就不一定了。"
D.Strings[69237]="我也是这么想的。他们肯定是打算把那些炮装到东北边的海军基地里那些战舰上。"
D.Strings[69238]="我们这支小队不可能去突袭海军基地。那里的守卫太森严了。"
D.Strings[69239]="我们应该继续骚扰他们的补给线。"
D.Strings[69240]="达坎，你在戈尔隆德游历多久了？"
D.Strings[69241]="很久，比你活过的年头还要长，可能是它的两、三倍。"
D.Strings[69242]="你不觉得寂寞吗？"
D.Strings[69243]="耐不住寂寞的游侠不是好游侠。"
D.Strings[69244]="听起来完全不合适我。如果家里没有老婆孩子等着，这种生活毫无意义。"
D.Strings[69245]="你有妻子了吗，汉瑟尔？"
D.Strings[69246]="哎……她被黑石兽人抓走了。"
D.Strings[69247]="那也是我来这里的原因之一：来保护塞林，还有找回我的妻子。"
D.Strings[69248]="我们会找到你妻子的，汉瑟尔。我们还要把这里杀个血流成河。兽人将为他们对我们亲人的所作所为付出血的代价。"
D.Strings[69249]="知道吗，这是我从一个圣骑士嘴里听到的最黑暗、最冷酷、最振奋人心的话。"
D.Strings[69250]="我们在这里的任务已经完成了。接下来，我们该去硝烟仓栈了。"
D.Strings[69251]="塞林，你在里面还好吗？"
D.Strings[69252]="很好，女士。我很高兴能远离战场，回到我的坦克里。"
D.Strings[69253]="<叹气>这片土地上到处都是肆虐的战火。你觉得我们完成任务后，还能安全回家吗？"
D.Strings[69254]="我不知道你对艾泽拉斯了解多少，女士，但我们那儿也不太平。"
D.Strings[69255]="我只知道等我找到我的艾利，我就回灼热峡谷去。"
D.Strings[69256]="你呢，丫头？你打算回家吗？"
D.Strings[69257]="维伦去世后，我觉得我已经没有家了。"
D.Strings[69258]="我们是德莱尼，伊瑞尔。我们天生就无家可归。"
D.Strings[69259]="我在想是不是该跟你到传送门的另一边去，亲爱的。"
D.Strings[69260]="当然，伊瑞尔。艾泽拉斯将成为你的新家。"
D.Strings[69261]="但首先，我们要让这些兽人为他们对你所做的一切付出代价。他们的罪行不可饶恕。"
D.Strings[69262]="玛尔拉德，你吓到我了。"
D.Strings[69263]="钢铁部落的补给线已经被切断了，但这只是暂时的。我们得跟塑造者们结盟。"
D.Strings[69264]="眼下就是最好的时机。让我们到海军基地那儿去，向钢铁部落复仇吧！"
D.Strings[69265]="我们的计划是什么，玛尔拉德？"
D.Strings[69266]="我们要尽力多干掉一些恶棍，烧毁他们的家园，让他们尝到恐惧的滋味。"
D.Strings[69267]="我要让他们感受到我失去你时的那种痛苦，伊瑞尔。"
D.Strings[69268]="玛尔拉德……我很荣幸……"
D.Strings[69269]="……但你似乎太过执着于复仇了。你忘了先知对我们的教导了吗？"
D.Strings[69270]="先知已经死了，伊瑞尔。看看他的教导给他带来了什么吧。"
D.Strings[69271]="你太过火了，玛尔拉德。"
D.Strings[69272]="圣光正在远离你。连我都看出来了。"
D.Strings[69273]="我并不怎么热爱圣光，可我同意他们的话。你不能忘了自己的立场，守备官。"
D.Strings[69274]="你们有谁比我更神圣？我是这支队伍的领袖，我不想再听到任何质疑！"
D.Strings[69275]="圣光并未远离我，塞林。不……圣光已经向我展现了它的真容。"
D.Strings[69276]="那就是复仇。"
D.Strings[69277]="我在清洗格罗玛尔的战斗中见识到了纳鲁的复仇。我看到卡拉亲自将神圣的死亡播撒到那群肮脏的乌合之众头上。"
D.Strings[69278]="玛尔拉德，亲爱的，已经够了。"
D.Strings[69279]="伊瑞尔……"
D.Strings[69280]="你经历了太多悲剧，玛尔拉德。你对复仇的执念只会害死我们大家。"
D.Strings[69281]="休息一下吧。让我来指挥对海军基地的突袭。"
D.Strings[69282]="我支持你，伊瑞尔。"
D.Strings[69283]="我也是。"
D.Strings[69284]="还有我。"
D.Strings[69285]="谢谢你，伊瑞尔。我不知道自己是怎么了。"
D.Strings[69286]="拉下第一根拉杆，加强燃烧！"
D.Strings[69287]="拉下第二根拉杆，让引擎超载！"
D.Strings[69288]="拉下第三根拉杆，摧毁终极毁灭者！"
D.Strings[69289]="后退！它失控了！"
D.Strings[69290]="干得好，勇士！我们会尽力修好这个单位的。谢谢你。"
D.Strings[69291]="我们都有权发表意见。只是你的大错特错而已。现在，给我回去干活！"
D.Strings[69292]="抱歉！我只是个打工的！"
D.Strings[69293]="哇！我干了些什么？！"
D.Strings[69294]="妮可茜！救命啊！"
D.Strings[69295]="我真不该离开艾泽拉斯！"
D.Strings[69296]="我们能好好谈谈吗？"
D.Strings[69297]="加兹鲁维，帮我们争取一点时间！"
D.Strings[69298]="我们往东走！"
D.Strings[69299]="奥格瑞姆，你将为你的背叛付出代价！"
D.Strings[69300]="奥金顿很快就会落入我们手中。可惜你看不到那一天了，精灵。"
D.Strings[69301]="无辜？！"
D.Strings[69302]="是的，我将看着德拉诺熊熊燃烧。而你，叛徒，将没有这个荣幸。"
D.Strings[69303]="我来挡住码头上的援军！"
D.Strings[69304]="我来把孩子们送到安全的地方去！"
D.Strings[69305]="你说了算，头儿！"
D.Strings[69306]="来，让我们并肩战斗！"
D.Strings[69307]="准备反击！"
D.Strings[69308]="他们往海港方向撤退了！"
D.Strings[69309]="孩子们都安全了！他们的军官暴露了！"
D.Strings[69310]="现在，我们和那台武器之间只隔着一座海港了！"
D.Strings[69311]="勇士！你准备好前往敌人旗舰后就告诉我一声吧。"
D.Strings[69312]="我可不会残杀这么多无辜的人！"
D.Strings[69313]="你才是让德拉诺陷入火海的那个人。你才是该被阻止的人！"
D.Strings[69314]="为了沙塔斯！"
D.Strings[69315]="塞林，用你的坦克救他们！我们来掩护你。"
D.Strings[69316]="我们来拖住黑手！你去摧毁那台武器！"
D.Strings[69317]="那些房子里关着许多孩子！"
D.Strings[69318]="我们往西边走！"
D.Strings[69319]="正在拆解"
D.Strings[69320]="%s嘶鸣着退回了暗影深渊！"
D.Strings[69321]="刺骨的寒风在空山间呼啸……"
D.Strings[69322]="吱吱声在树丛中回荡，然后低沉了下去……"
D.Strings[69323]="有什么东西在阴影中扑棱着翅膀，逐渐靠近……"
D.Strings[69324]="我们并不想惹麻烦，$c。我们早就不再战斗了。"
D.Strings[69325]="我饿得能吃下一头兽人。"
D.Strings[69326]="如果你像我们一样生活在一个野蛮的世界，你也会生出避世的念头。$b$b这就是我们抛弃战争的原因。"
D.Strings[69327]="尝尝这些鱼吧，味道很不错的。"
D.Strings[69328]="|TInterface\\Icons\\ability_fixated_state_red:20|t一辆%s |cFFFF0000|Hspell:156653|h[锁定]|h|r了你。快跑！"
D.Strings[69329]="站住！谁在那里！在我射瞎你的眼睛之前，快滚开！"
D.Strings[69330]="请原谅我的粗鲁，旅行者。我以为你是敌人呢。$B$B暗影议会已经袭击了我家好几次。$B$B第一次，他们没想到我这样的老隐士还能有还手之力。结果我射死了三个袭击者。$B$B第二次，我有了准备。四个兽人跌入了我的陷阱。一群蠢货。$B$B我激怒了他们。现在，我就在等着他们卷土重来。$B$B我倒希望他们多派点人来。那我就能多杀几个敌人了。"
D.Strings[69331]="如果你愿意就留下吧。除非我死了，否则我绝不会让这些恶狗占领我的家。小心！他们来了！"
D.Strings[69332]="呵呵，你很能打嘛，旅行者。还能继续吗？"
D.Strings[69333]="就这样，朋友。让我们砍掉他们的脑袋吧！"
D.Strings[69334]="我们成功了！我……真不知道该怎么感谢你，陌生人。我身无长物，只能请你收下这个了。"
D.Strings[69335]="狩猎结束。快，喝下这瓶解药！蜘蛛的毒素就不能再干扰你了！"
D.Strings[69336]="你确定这是个好主意吗？"
D.Strings[69337]="如果你想完成什么事，就得自己去干！"
D.Strings[69338]="我在这些洞穴中另有目标。这个就留给你了。"
D.Strings[69339]="快想办法摧毁补给站！"
D.Strings[69340]="空骑兵发现你了！"
D.Strings[69341]="站起来，侍奉你的主人！"
D.Strings[69342]="我们的氏族每时每刻都在壮大。"
D.Strings[69343]="小心——我们困住了一个厉害的对手。"
D.Strings[69344]="古鲁尔克要砸烂你们！啊啊！！"
D.Strings[69345]="有点虚弱……古鲁尔克需要血清……"
D.Strings[69346]="古鲁尔克砸死你！！啊啊啊！！"
D.Strings[69347]="古鲁尔克好累……想睡觉。"
D.Strings[69348]="古鲁尔克是最强壮的！！啊啊！！"
D.Strings[69349]="这就是古鲁尔克蜕变的地方……过去的我就死在这里……"
D.Strings[69350]="够了！！古鲁尔克要碾碎一切！"
D.Strings[69351]="是的，你不会有事的。我上次只是忘了调整瞄准镜。"
D.Strings[69352]="提高警惕……这些石头告诉我们有麻烦了。"
D.Strings[69353]="猎手们，埋好陷阱。我闻到了什么味道……"
D.Strings[69354]="又一个战利品。"
D.Strings[69355]="岩石已经预言了你的末日。"
D.Strings[69356]="是谁竟敢吵醒我？"
D.Strings[69357]="我看见你们了，入侵者。你们踏上了神圣的土地……"
D.Strings[69358]="卑微的废物，是什么给了你们挑战我的胆量？"
D.Strings[69359]="我要把你们碾成灰烬！"
D.Strings[69360]="湮没在毒汁中吧！"
D.Strings[69361]="让逆流吞噬你们！"
D.Strings[69362]="哈！这里在我的掌控之下。"
D.Strings[69363]="阿迦玛甘必将再次崛起！"
D.Strings[69364]="奥金顿……已经……完了……"
D.Strings[69365]="没有生者胆敢攻击神圣的奥金尼。"
D.Strings[69366]="我要打倒你。"
D.Strings[69367]="愿圣光指引我！"
D.Strings[69368]="愿圣光指引你的灵魂。"
D.Strings[69369]="沐浴在圣光的荣耀中吧！"
D.Strings[69370]="我不知道……洛克塔尔看起来不太好。"
D.Strings[69371]="我曾立誓守护这座陵墓和它的土地。$B$B我们要战斗至最后一人，绝不能让这些兽人抢走灵魂碎片！"
D.Strings[69372]="缚魂者尼娅米派我来把灵魂碎片送去安全的地方。"
D.Strings[69373]="用你的生命来保护它！我们需要它来为奥金顿的防御屏障充能！"
D.Strings[69374]="我会给你个痛快的！"
D.Strings[69375]="立刻放我下来，你这畜生！"
D.Strings[69376]="没用的畜生！放开我！"
D.Strings[69377]="古鲁尔克受够钢铁部落了……古鲁尔克要走了。"
D.Strings[69378]="你是古鲁尔克的朋友……古鲁尔克不会忘记你的。"
D.Strings[69379]="我是最强的！这个食物是我的！滚开！"
D.Strings[69380]="你别想挑战我！现在，乖乖做我的食物吧！"
D.Strings[69381]="我要杀了你！我要吃掉你！"
D.Strings[69382]="看到我的厉害了吧？！别来惹我！否则下一个就是你。"
D.Strings[69383]="坚守阵地。我们得保护伤员！"
D.Strings[69384]="%s呼叫了一辆远程|cFFFF0000攻城战神坦克|r！"
D.Strings[69385]="没关系。这些灵魂都归我了。我的力量正在增长。"
D.Strings[69386]="奥金顿将属于我！我要吞掉所有的灵魂，沐浴在地狱火的灰烬之中！"
D.Strings[69387]="学者们，准备战斗！鸦人过来了！英雄，请帮我们一把！"
D.Strings[69388]="战友们，地平线上出现了更多的鸟人。把他们打回阿兰卡峰林去，那里才是他们应该呆的地方！"
D.Strings[69389]="他们到底有多少人？鼓起勇气，朋友们。我们是不会轻易倒下的！"
D.Strings[69390]="我们总算把他们的首领引出来了！来吧，你这个扁毛恶棍！"
D.Strings[69391]="多亏了你们，我们镇子安全了。今天，我们给了鸦人一个铁与血的教训。坚强起来，学者们！我们必须保持警惕。"
D.Strings[69392]="欢迎来到学者之家，旅行者。这里汇集了众多前来卡拉波神殿朝圣的虔诚信徒。"
D.Strings[69393]="你凭什么认为我们需要你的帮助，“血精灵”？我们奥金尼都曾发誓保卫奥金顿。"
D.Strings[69394]="爆炸、破坏、毁灭……这都是家常便饭了，朋友。"
D.Strings[69395]="保护碎片！我们必须把它送到塔隆戈尔大人手中！"
D.Strings[69396]="联盟根本不靠谱，格罗玛尔就是最好的例证……"
D.Strings[69397]="我以前见过你的族人，都越过群山飞到南方去了。你来这里做什么？"
D.Strings[69398]="啊啊！你干了什么？太阳……我看不见了！好烫！好烫啊！！"
D.Strings[69399]="黑暗正在迫近。我感受不到圣光了。你！都是你干的！"
D.Strings[69400]="我一个人就能对付你。我要把你赶出这片土地！"
D.Strings[69401]="老圣骑士突然吸了一口气，脸上闪过一阵狂喜。他眨了眨眼，第一时间看向你。"
D.Strings[69402]="我……我又能感受到圣光了！我摆脱了她的诅咒。我……我看见了通向奥金顿的道路。"
D.Strings[69403]="一个鸦人太阳祭司曾试图统治我们的土地。"
D.Strings[69404]="我的村子逐渐消亡。许多人都倒在他的巫术之下。我也中了他那可怕的诅咒……“日盲症。”"
D.Strings[69405]="我们知道太阳祭司迟早会来攫取他的胜利果实。"
D.Strings[69406]="最后只剩下我一个人去面对他。我的视力几乎为零，圣光也不再回应我的祈祷。"
D.Strings[69407]="我最后一次向圣光祈祷，曾经神圣的仪式只让我感到空虚。"
D.Strings[69408]="那一刻，我感受到了真正的恐惧。"
D.Strings[69409]="我没有看见太阳祭司的降临，但我听到了他拍打翅膀的声音，感受到他喷到我脸上的贪婪气息。最后，我感到他死在了我的剑下。"
D.Strings[69410]="之后，我就四处流浪。一个孤独的瞎子，与圣光失去了联系。哪怕在垂死的时候，我都感觉自己被遗弃了。"
D.Strings[69411]="你帮助我摆脱了他的诅咒。你拯救了我的信仰，勇士。"
D.Strings[69412]="拿上我的剑吧，它就在那块石头上。愿它能在你的信念动摇时指引你的道路。"
D.Strings[69413]="你要再敢靠近一步，我就要像剖鱼一样把你开膛破肚，兽人！"
D.Strings[69414]="感谢群星，你总算来了，英雄！我们就是泰尔莫全部的幸存者了。"
D.Strings[69415]="谢了，伙计！我很想跟你来个拥抱，但我们没时间了……"
D.Strings[69416]="帮我个忙，把古鲁尔克从笼子里放出来吧……别担心，他很酷的。"
D.Strings[69417]="是砸还是不砸？这对古鲁尔克来说是个问题。"
D.Strings[69418]="你要砸什么东西吗？"
D.Strings[69419]="你能相信吗？！古鲁尔克被钢铁部落强行转化，然后又因为不肯听话而被关了起来。"
D.Strings[69420]="砸！！！"
D.Strings[69421]="古鲁尔克要唱个歌！$b$b砸砸砸，砸坏人！$b$b砸扁坏人做肉汤！"
D.Strings[69422]="我们要炸毁这个变异实验室，否则就太迟了！古鲁尔克会为你介绍详细情况的。"
D.Strings[69423]="我还是回去跟队友汇合吧。等你摧毁实验室之后，就来找我们。"
D.Strings[69424]="是的，图拉妮。这下你明白了。"
D.Strings[69425]="你的努力是徒劳的。学者们不可能仅仅靠一块水晶来为防御工事供能。"
D.Strings[69426]="但什么都不能阻止我的计划，或者我的主人。而我们唯一的障碍……"
D.Strings[69427]="守护者！消灭这些入侵者！"
D.Strings[69428]="他们想生吞了我们……真的！"
D.Strings[69429]="奥金尼呢？为什么没人来救我们？"
D.Strings[69430]="没希望了！快跑吧！"
D.Strings[69431]="他们杀了我的家人！"
D.Strings[69432]="很高兴能遇见你。我们差点就被杀了！"
D.Strings[69433]="这附近的生物很难对付。$b$b我不得不将食物和贵重物品藏在高处以防万一。"
D.Strings[69434]="哇！谢谢！到了这里，我就能自己出去了。我肯定不会再被抓住了。再见！"
D.Strings[69435]="碾碎、砸扁、割裂！啊哈哈哈哈……"
D.Strings[69436]="窃窃私语声……在我的眼球后面滑动！"
D.Strings[69437]="不！仪式还没完成！是谁竟然干扰我的降临！"
D.Strings[69438]="我的力量在……消褪！"
D.Strings[69439]="不！不——！！！！！"
D.Strings[69440]="加兹鲁维，解决那个路障！"
D.Strings[69441]="加兹鲁维……"
D.Strings[69442]="我担心就算奥金顿之心恢复完整，那里的防御也还是不够。暗影议会的耳目向来无孔不入。"
D.Strings[69443]="目标——路障！"
D.Strings[69444]="塞林，把那个坦克弄下来。"
D.Strings[69445]="在孩子附近开火可不安全！但我敢打赌，近距离射击造成的震荡一定能轰开那些门……"
D.Strings[69446]="勇士，快去控制住那门大炮！要是他们敢靠近，那就开火……哈哈哈哈！"
D.Strings[69447]="苏特！我们回家！"
D.Strings[69448]="我们走……慢慢转过来……慢一点……"
D.Strings[69449]="噢，可怜的小东西。我不会忘记你的！"
D.Strings[69450]="钥匙就在墙边的箱子里，快去找到它，放我出去！"
D.Strings[69451]="你还在看什么呐？快去拿箱子里的钥匙，放我出去！"
D.Strings[69452]="伙计，真高兴见到你！钥匙就在那边的箱子里，请帮个忙，放我出去，好吗？"
D.Strings[69453]="我被锁在里面了，你得找到钥匙。它就在墙边的箱子里！"
D.Strings[69454]="别管我，在你把我放出去之前，我就呆在这个笼子里！钥匙在那边的箱子里！"
D.Strings[69455]="这可不是什么“拯救高塔中的公主”之类的浪漫桥段。这是一间刑房，而我被关在畸形的笼子里！快让我出去！"
D.Strings[69456]="宣誓效忠你的主人，你就将获得无与伦比的力量！"
D.Strings[69457]="见证燃烧军团的无穷力量吧！"
D.Strings[69458]="兄弟姐妹们，团结起来，德莱尼将在我们面前土崩瓦解！"
D.Strings[69459]="谁都阻挡不了我们的力量！不管是面对钢铁部落还是德莱尼，我们是不可战胜的！"
D.Strings[69460]="将你们的灵魂献给塔隆戈尔。沐浴在他的威能之下吧！"
D.Strings[69461]="快点……我们还有活儿要干呢。"
D.Strings[69462]="这纯属浪费时间。"
D.Strings[69463]="你好了没有。"
D.Strings[69464]="*叹气*"
D.Strings[69465]="至于你这个畜生，尽管跑吧，但我的箭会刺穿你的！"
D.Strings[69466]="我马上就好！再给我一点时间。"
D.Strings[69467]="你一定要试试这个！"
D.Strings[69468]="小心，不要敲打它。"
D.Strings[69469]="来吧！你肯定会喜欢的。"
D.Strings[69470]="死吧，畜生。记住，无论你下到哪层地狱，都比落在我手里要好！"
D.Strings[69471]="谢谢你的帮助，冒险者。回营地来找我吧，我们得好好谈谈。"
D.Strings[69472]="那个叫古鲁尔克的家伙很不可思议，不是吗？被强行转化……渴望复仇……健硕的肱二头肌……女孩子是不可能那么壮了。"
D.Strings[69473]="你有麻烦需要解决？那你就找对人了……可对的人都不便宜。"
D.Strings[69474]="不！！我要把你撕成碎片！我会为你报仇的，裂肠！"
D.Strings[69475]="雷神氏族必将……再次……崛起……"
D.Strings[69476]="钻探机，回家吧！"
D.Strings[69477]="别咬我！我不会伤害你的……真的，别咬我。"
D.Strings[69478]="我真该留在影月谷。"
D.Strings[69479]="求求你！我还有很多地方没去过呢，我还不想死。"
D.Strings[69480]="谢谢你，朋友！我们后会有期！"
D.Strings[69481]="如此强大的力量！我是无敌的！"
D.Strings[69482]="可我有这力量……保护着我……"
D.Strings[69483]="真让我失望，我还以为你有多厉害呢。"
D.Strings[69484]="弱者就该放聪明点，别来挑战我！"
D.Strings[69485]="%s开始引导|cFFFF0404|Hspell:157059|h[纠缠之地符文]|h|r！"
D.Strings[69486]="虫洞正在飞速旋转。你只能先跳下去，然后乞求老天保佑。"
D.Strings[69487]="林立交错的山峰"
D.Strings[69488]="一座橙红色的森林"
D.Strings[69489]="阴影……"
D.Strings[69490]="选择你的第二个位置。"
D.Strings[69491]="太多的霜狼兽人牺牲在这场战争中。"
D.Strings[69492]="在雷神氏族覆灭之前，我永远无法得到安宁！"
D.Strings[69493]="我曾猎杀裂蹄牛，获取牛肉和皮革。现在，我改行猎杀雷神兽人，收集他们的脑袋。其实也没多大区别。"
D.Strings[69494]="芳草萋萋的平原"
D.Strings[69495]="原兽森林"
D.Strings[69496]="熔岩与白雪"
D.Strings[69497]="位置07"
D.Strings[69498]="位置08"
D.Strings[69499]="位置09"
D.Strings[69500]="位置10"
D.Strings[69501]="位置11"
D.Strings[69502]="位置12"
D.Strings[69503]="你有什么要紧事吗？还是纯粹来浪费我的时间的？"
D.Strings[69504]="位置13"
D.Strings[69505]="位置14"
D.Strings[69506]="位置15"
D.Strings[69507]="位置16"
D.Strings[69508]="掩埋"
D.Strings[69509]="在你干掉他们之前，先让他们尖叫吧，那可以更好地分散敌人的注意力。"
D.Strings[69510]="最好别忘了我的宝贝斧子！"
D.Strings[69511]="来面对你的送葬者吧，$r。"
D.Strings[69512]="等你完事儿之后，就到格罗玛尔里面来找我吧！谁都别想在击沉我的战舰之后拍拍屁股走人！"
D.Strings[69513]="|TInterface\\Icons\\ability_blackhand_demolition.blp:20|t%s施放了|cFFFF0000|Hspell:156425|h[毁灭]|h|r！"
D.Strings[69514]="|TInterface\\Icons\\spell_fire_ragnaros_lavabolt.blp:20|t %s施放了|cFFFF0000|Hspell:156928|h[炉渣喷发]|h|r！"
D.Strings[69515]="我的熔炉怎么了？我的卫兵呢？快解决这些入侵者！"
D.Strings[69516]="我打算潜入营地。等你完成之后，我们就在约定的地点汇合，我已经给你标在地图上了。"
D.Strings[69517]="鲜肉似乎还是很紧缺啊……"
D.Strings[69518]="天天都是烧烤的好日子！"
D.Strings[69519]="烧烤和杀人……这可是我最擅长的两件事！"
D.Strings[69520]="解除这些结界！无论我怎么召唤圣光来净化它们，这些结界似乎总能抵消我的解除技能。"
D.Strings[69521]="看来还得再提高点温度……"
D.Strings[69522]="制作美味烧烤的秘诀就是得用高温慢慢烤……"
D.Strings[69523]="有人喜欢焦香口味的吗？"
D.Strings[69524]="符文已经被摧毁了。"
D.Strings[69525]="准备好面对瑞梵妮了吗？"
D.Strings[69526]="闻上去好像烧焦了……说明它就快完成了！"
D.Strings[69527]="已经过去这么久了吗？自从上次分别之后，她真的已经长得这么大了？"
D.Strings[69528]="结局尚不可知。"
D.Strings[69529]="孩子！快走。那些结界是保护你的。你不应该来这儿。"
D.Strings[69530]="是的。她永远不会属于你。"
D.Strings[69531]="什么？我在哪儿？我好累。"
D.Strings[69532]="等等。我想起来了。这里是黑石塔，而我们……我们是来讨伐邪恶势力，并搜刮战利品的。"
D.Strings[69533]="我全想起来了。你们是我的朋友，我一辈子的朋友。奇怪，我记得应该不止这样才对。"
D.Strings[69534]="不管了，你们都是聪明人，就负责制定完美的计划，而我会像做外科手术般精准地执行你们的计划。"
D.Strings[69535]="但首先，我饿了。我简直就像八年没吃东西了一样。我还是趁你们制定进攻计划时把背包里这只鸡给煮了吧。"
D.Strings[69536]="好了，我要把背包里这只还没烂掉的鸡煮一煮。你们继续制定你们的完美计划吧。"
D.Strings[69537]="这计划听起来不错，伙计们。它显然经过了深思熟虑，真是完美无缺。"
D.Strings[69538]="好了，伙计们，我回来了！我们动手吧。里诺——艾！火车王！"
D.Strings[69539]="我准备好引爆炸药了。"
D.Strings[69540]="岩石的无穷力量在我体内流淌！你们的死期到了！"
D.Strings[69541]="好吃……"
D.Strings[69542]="迎接你们的末日吧！远古的岩石赋予我超乎想象的力量！"
D.Strings[69543]="你们休想挑战我的权威！我掌握着岩石的力量，无人能及！"
D.Strings[69544]="好渴……好多血……"
D.Strings[69545]="真是美味多汁……"
D.Strings[69546]="圣光在上！你怎么……还不……碎！"
D.Strings[69547]="这个屏障是谁建的？！它好像很了解我。"
D.Strings[69548]="我就算是死，也要打破这个屏障！"
D.Strings[69549]="把……我……爸爸……还给我！"
D.Strings[69550]="打开！圣光在上，快打开！"
D.Strings[69551]="屏障消失了！干得好，勇士！我能感觉到我父亲就在附近。这边走。"
D.Strings[69552]="第二座塔楼已经进入射程！点燃雷管！"
D.Strings[69553]="那座堡垒需要重建一下……让我们帮他们一把吧！"
D.Strings[69554]="钟摆？！"
D.Strings[69555]="啊！你一定会成为非常出色的祭品。"
D.Strings[69556]="完美！我需要一个目标来测试一下我的新力量。"
D.Strings[69557]="跟我的小伙伴们打个招呼吧。"
D.Strings[69558]="敌人过来了！不惜一切代价保护埃克萨纳托斯！"
D.Strings[69559]="每一个生者都将被转化。你休想阻止这一切！"
D.Strings[69560]="啊，你来了。难怪我闻到了$r的味道。"
D.Strings[69561]="你休想击败布洛克。"
D.Strings[69562]="布洛克喜欢揍人。你想挨揍吗？"
D.Strings[69563]="哎唷！别打了。布洛克很抱歉。布洛克输了。"
D.Strings[69564]="布洛克以前从来没有打输过。布洛克愿意跟小个子赢家走。"
D.Strings[69565]="布洛克可以跟你走？布洛克喜欢做追随者，虽然没有像喜欢揍人那么喜欢。但布洛克被揍了，所以布洛克愿意跟你走。"
D.Strings[69566]="总有一天，布洛克要打败所有的小个子。这是布洛克的梦想。"
D.Strings[69567]="拔出"
D.Strings[69568]="好了！你去拖住他们，看我来变个戏法！"
D.Strings[69569]="准备就绪！重新接入抓手！"
D.Strings[69570]="财源滚滚！！"
D.Strings[69571]="有人吗……救命……好烫啊……"
D.Strings[69572]="快点，废物兽人！酋长需要奴隶！"
D.Strings[69573]="谁都休想击沉我的战舰！"
D.Strings[69574]="图拉妮，你去泰尔莫找缚魂者艾德拉。她已经取回了最后一块水晶并将它带去了那里。"
D.Strings[69575]="谢谢你，缚魂者。"
D.Strings[69576]="让我们来拧紧这个排气阀……"
D.Strings[69577]="拧开这个……拧紧那个……然后……"
D.Strings[69578]="我们将作为征服者昂首挺胸地返回霜火岭！"
D.Strings[69579]="你！快点干！"
D.Strings[69580]="再加把劲，你这废物！否则我就把你交给老板！"
D.Strings[69581]="快点挖，没用的奴隶！否则就让老板弄死你！"
D.Strings[69582]="不好好教训你，你就不知道好好干活！"
D.Strings[69583]="遵、遵、遵、遵命，先生，你说了算。"
D.Strings[69584]="啊！能别打了吗？"
D.Strings[69585]="够了！别打了！求求你！"
D.Strings[69586]="啊！这些废物奴隶真是气死我了！"
D.Strings[69587]="如果让他们看见你跟我说话，他们会把我们都杀了的！快走开！"
D.Strings[69588]="那些工头身上有镣铐的钥匙。帮帮我，求你了！"
D.Strings[69589]="我……坚持不住了……请让我一个人待会儿。"
D.Strings[69590]="求求你，别打了！我只想休息一下！"
D.Strings[69591]="你是谁？别烦我。"
D.Strings[69592]="只要给我一把斧子，我一定要让这些食人魔为他们对我所做的一切付出代价！"
D.Strings[69593]="你自由了！快离开这里，到最近的营地去。"
D.Strings[69594]="你自由了！快跑吧！"
D.Strings[69595]="你救了我一命。谢谢你！"
D.Strings[69596]="不要放过那些食人魔。"
D.Strings[69597]="我一直在期盼着这一天！"
D.Strings[69598]="我们在这里损失了太多人。太多太多了。"
D.Strings[69599]="这场噩梦终于结束了。"
D.Strings[69600]="小心点，我见过那些从他们的“头儿”那里运出来的尸体。他们身上都没有被折磨的痕迹，可脸上却都凝固着尖叫的表情。"
D.Strings[69601]="几天前的一个夜晚，熔岩流另一边的洞穴里透出了一束诡异的光。那景象真让我毛骨悚然！第二天，我们被指使着拖出了几具俘虏的尸体去喂鸟。我……一想到当时的情景我就觉得恶心。"
D.Strings[69602]="我帮忙从西边的洞穴里运出了几具尸体。有一个看起来毛茸茸的怪东西还是活的！他们把它弄到东北边山坳的营地里去了。"
D.Strings[69603]="我感觉到了！"
D.Strings[69604]="嘿，肉鸡！快来熔岩里跟我聊聊吧。"
D.Strings[69605]="你们竟敢突袭悬槌王座？是古加尔那个叛徒教唆的？跪下，发誓效忠我，没准我会大发慈悲，只把你们投入角斗场。"
D.Strings[69606]="你们马上就会明白，为何我是国王，而你们只是贱民。"
D.Strings[69607]="我会把阿塔尔送到安全的地方去的。惩戒岗哨离这里不远。"
D.Strings[69608]="斥候们！找到那个渣滓！"
D.Strings[69609]="我们是来接受今天的奴隶的。嗯……人呢？"
D.Strings[69610]="开启我这个笼子的钥匙就在你身后的箱子里。你能去把它拿来，放我出去吗？"
D.Strings[69611]="在你权衡当前局势的同时，能麻烦你去那个箱子里拿一把钥匙来放我出去吗？"
D.Strings[69612]="真是让人意外，你居然会出现在这个地牢里！此时此刻，你就好比是让我获得自由的钥匙！而真正的钥匙就在你身后的箱子里。"
D.Strings[69613]="我很愿意在笼子外面与你相见，但不幸的是，我目前事实上正被锁在笼子里。"
D.Strings[69614]="可怜虫送来的奴隶太弱了。可怜虫要给纳布找点好奴隶来。"
D.Strings[69615]="虽然这个牢笼相当宽敞，但并不适合居住。你能放我出去吗？"
D.Strings[69616]="待在这个笼子里害得我的皮肤都发痒了。你有止痒的药膏吗？"
D.Strings[69617]="什么？！不是说好我们到的时候货物就能准备好了吗？"
D.Strings[69618]="向您致敬！请原谅我的唐突无礼，可我们的时间已经不多了……"
D.Strings[69619]="在我滞留于这个地牢期间，我有幸结识了你面前的笼子里的这位古鲁尔克先生……"
D.Strings[69620]="请释放古鲁尔克吧，$n。别害怕。我发现他的性格相当温和……"
D.Strings[69621]="古鲁尔克是被钢铁部落强行转化的，他掌握着一些有关格罗玛尔中罪恶暴行的珍贵情报。"
D.Strings[69622]="在你协助古鲁尔克处理这个变异计划的同时，我会设法跟我的队友汇合并继续行动。祝你好运，$n！"
D.Strings[69623]="嗯？你不是食人魔。我不会是看错了吧？"
D.Strings[69624]="全体步行！让我们去抓住他们！"
D.Strings[69625]="你是来救我出去的吗？"
D.Strings[69626]="旋翼机的坠毁肯定不是我的错。虽然老实说，我也是有一点责任的啦。有人想要追究责任吗？如果是的话，那我坚持认为此次事故的责任是无法判断的。"
D.Strings[69627]="我们得在日落前把这批货发出去！"
D.Strings[69628]="我们有活儿干了。这是刃怒的命令！"
D.Strings[69629]="快点，否则我就踹死你！"
D.Strings[69630]="所有这些冰雪和烈焰。这些的一切都在想方设法灼伤你。"
D.Strings[69631]="嘿，头儿！我们需要一些东西。但这些东西可不好弄。"
D.Strings[69632]="放弃末日守卫"
D.Strings[69633]="放弃恐惧卫士"
D.Strings[69634]="放弃地狱火"
D.Strings[69635]="放弃深渊魔"
D.Strings[69636]="接受暗影猎手莱拉的效忠。"
D.Strings[69637]="我的姐妹还有其他任务，但我愿意离开老沃金来为你效命。$b$b你已经证明了自己的实力，也完成了必须的任务。$b$b如果你同意的话，我愿意跟你走，头儿。"
D.Strings[69638]="|TInterface\\Icons\\ability_blackhand_marked4death:20|t你被施放了|cFFFF0000|Hspell:156096|h[死亡标记]|h|r！"
D.Strings[69639]="不！我必须得到升华！"
D.Strings[69640]="是圣光！好烫啊！"
D.Strings[69641]="你会为此付出代价的，凡人！"
D.Strings[69642]="你在做什么？快住手！"
D.Strings[69643]="住手！我必须将自己献给塔隆戈尔！"
D.Strings[69644]="太少了，太迟了。我得到了升华！"
D.Strings[69645]="你的祝福阻止不了任何事！"
D.Strings[69646]="我……是……燃烧军团！"
D.Strings[69647]="对你们来说，我们的力量过于强大了。"
D.Strings[69648]="$n，去跟楚伦娜谈谈吧。让我们看看这个……羽颈之釜到底有什么蹊跷。"
D.Strings[69649]="抓紧了，$n。"
D.Strings[69650]="我们到了。这是什么地方？"
D.Strings[69651]="我一直很喜欢跟当地人打成一片，可这身钢铁部落的护甲里面太臭了。如果他们能多洗洗澡，或许就不会这么暴躁了。"
D.Strings[69652]="钢铁部落是个不可小觑的对手，$n。虽然他们的武器和庞大的军队十分可观，但他们坚韧不拔的毅力才是最不可忽视的。"
D.Strings[69653]="我最信赖的腕载式侏儒隐身装置可以让我在不被发现的情况下修好我的旋翼机。要我说的话，这简直是个天才的发明！"
D.Strings[69654]="波加尔！快滚回来，你这个兔崽子、杀人犯！"
D.Strings[69655]="木桶是特工们最好的伪装。没有人会怀疑一只木桶……"
D.Strings[69656]="钢铁部落逃不过我们锐利的眼睛。"
D.Strings[69657]="我从没见过这么庞大的喷气裂口和火山口群。这真是一个值得研究的地方！"
D.Strings[69658]="送我去羽颈之釜。"
D.Strings[69659]="浓烟之釜就在上面了。"
D.Strings[69660]="我觉得可能更糟……我可能是在厕所里。"
D.Strings[69661]="我想知道到底是谁发明了“一大桶欢乐”这个词的，因为我觉得我好像选错桶了。"
D.Strings[69662]="等等……这是什么……白蚁！？"
D.Strings[69663]="但愿你的伪装也能跟我的一样好，阿黛尔。"
D.Strings[69664]="避免侦测的关键是从不被侦测到。"
D.Strings[69665]="真希望这是一个啤酒桶……"
D.Strings[69666]="这点力量不过是九牛一毛！看看我的帝国发现的古代魔法吧。"
D.Strings[69667]="卫兵们，快过来！我必须集中力量来唤醒岩石！"
D.Strings[69668]="如此强大！它即将毁灭你们！"
D.Strings[69669]="多么充沛的力量。很快，它就会喷薄而出！"
D.Strings[69670]="我的激活者是$n。"
D.Strings[69671]="够了！历代巫王长年守护着这些殿堂。今天，你们将见识到我们的秘密力量！"
D.Strings[69672]="卫兵们，干掉这些贱民。"
D.Strings[69673]="它的力量增长超出了你们的想象！"
D.Strings[69674]="古加尔？！该死的叛徒——我就知道这是你搞的鬼！"
D.Strings[69675]="我喜欢购物，你喜欢闲逛。"
D.Strings[69676]="我喜欢购物，你呢？"
D.Strings[69677]="不行……废物一件。"
D.Strings[69678]="上面有“乌拉托克”的签名……这个“r”还写反了。我感觉这并不是我们要找的东西。"
D.Strings[69679]="唔，这个上面没有印记。"
D.Strings[69680]="这是在戈尔隆德的厂房里批量生产的。看来他们是把零件运到这里来组装的。"
D.Strings[69681]="啊哈！这个带有“DA”签名，字母周围还有铁砧形状的边框。我认识这个记号。"
D.Strings[69682]="德拉诺的威胁会影响到我们所有人。我很高兴你们中至少有一部分人愿意携起手来，共同应对这个重大事件。"
D.Strings[69683]="请打开通往艾泽拉斯的传送门，卡德加。"
D.Strings[69684]="奴隶已经准备好了，头儿。"
D.Strings[69685]="很好，相比那孱弱的躯体，他们可悲的灵魂对我更有用！"
D.Strings[69686]="小点儿声，蠢货！"
D.Strings[69687]="啊……没错，磨魂者开始散发出能量了！有了它，我们必将百战百胜！"
D.Strings[69688]="哟，暗砧！很高兴你能挖到这里——如果嗜血的兽人恶棍再少一点就更好了。但我想这只会让你更加激动吧。"
D.Strings[69689]="钻头已经不是问题了。你做好离开这儿的准备了吗？"
D.Strings[69690]="加兹鲁维！听着，他们强迫我造了一种钻头——"
D.Strings[69691]="但你最好用它光荣地战死！"
D.Strings[69692]="我是不会把我的作品留给钢铁部落的。我有一个补救的办法，如果你能给我一罐你那有名的火箭燃料……"
D.Strings[69693]="你现在改行当英雄了，嗯？好吧，随你。给，拿着。"
D.Strings[69694]="干得好，$n！这肯定就是他们在找的大厅。"
D.Strings[69695]="哈！我们矮人更喜欢把别人炸成碎片——而不是把自己炸上天。那种“好事儿”还是留给那个地精工程师吧。"
D.Strings[69696]="等等，$G小子:丫头;，别出声，到这儿来。"
D.Strings[69697]="真是个可怕的怪物。干得好，勇士。"
D.Strings[69698]="等等……我感受到了一种庞大的力量。它是从洞穴深处传来的。"
D.Strings[69699]="这就是钢铁部落要找的东西吗？"
D.Strings[69700]="噢，不！这座洞穴在晃动。我们快离开这儿！跟紧我！"
D.Strings[69701]="这边走，$n！"
D.Strings[69702]="我们前赴后继。燃烧军团必将崛起！"
D.Strings[69703]="看来那就是唯一的出路了，英雄。快上去！"
D.Strings[69704]="你们无法理解这伟大的工程。"
D.Strings[69705]="你们别想破坏我们的工程。"
D.Strings[69706]="这是万物演化之道。你们休想阻挠。"
D.Strings[69707]="你们不懂……你们不明白……"
D.Strings[69708]="我是个伐木工。安全状况如何？"
D.Strings[69709]="我是伐木工，你是头儿。"
D.Strings[69710]="我们都喜欢闲逛。"
D.Strings[69711]="我喜欢闲逛。你呢？"
D.Strings[69712]="耶！百战百胜！百战百胜！"
D.Strings[69713]="我必须返回灵魂世界来继续我的研究。守好这个房间，绝对不能让任何人触碰传送门！"
D.Strings[69714]="多谢你的燃料，加兹鲁维。等我顺利大逃亡之后，或许我还能去看看你，给你讲讲我是怎么做到的。"
D.Strings[69715]="全戈尔隆德天空下的鸟儿都听我指挥。黑手哪怕是上个茅房，我都要知道得一清二楚。"
D.Strings[69716]="蠢货！你的训练还没完呢！"
D.Strings[69717]="白痴！快回来！"
D.Strings[69718]="来吧，磨魂者！来享用我们为你准备的灵魂吧！"
D.Strings[69719]="快回来！你可不能乱跑！"
D.Strings[69720]="住手，兄弟们！都认不出自己的同胞了吗？ "
D.Strings[69721]="我们到家了。"
D.Strings[69722]="我们要将你们的家园烧成白地！"
D.Strings[69723]="求求你！别杀我们！"
D.Strings[69724]="我们要抢光一切！"
D.Strings[69725]="你们会为今天的暴行付出代价的。"
D.Strings[69726]="我是不会放弃的……"
D.Strings[69727]="你们的氏族根本不是我们的对手！"
D.Strings[69728]="雷神才是最强的氏族！"
D.Strings[69729]="看着！"
D.Strings[69730]="这下你的狼可帮不了你了！"
D.Strings[69731]="霜狼真是太弱了！"
D.Strings[69732]="把它射成刺猬。"
D.Strings[69733]="我们绝不会向你们低头！"
D.Strings[69734]="哈，想都别想。烧掉它！"
D.Strings[69735]="驳接火箭鸡"
D.Strings[69736]="萨尔，你怎么看？"
D.Strings[69737]="它充斥着怨恨和尘土，楚伦娜。我不想将它留在要塞里。"
D.Strings[69738]="但我更不想让它落在钢铁部落手里。"
D.Strings[69739]="我们应该摧毁它。"
D.Strings[69740]="或许吧。但首先，我们要搞清楚它对黑手有什么用。"
D.Strings[69741]="楚伦娜，我们要加快在戈尔隆德的行动了。无论钢铁部落有什么阴谋，我们都应做好准备。"
D.Strings[69742]="飞啰！"
D.Strings[69743]="那玩意儿会是很好的润滑剂。你知道的，我是指引擎。"
D.Strings[69744]="小心点，现在……万一那玩意儿碎了，我们就都变成烤乳猪了。"
D.Strings[69745]="哈！有本事就来啊！"
D.Strings[69746]="弱者活该被抢！"
D.Strings[69747]="它现在归雷神氏族了！"
D.Strings[69748]="等等，我感觉这里还有别人。乖乖出来吧，别逼我动手！快出来！"
D.Strings[69749]="你阻止不了我们！"
D.Strings[69750]="而你又是什么东西？"
D.Strings[69751]="有意思。"
D.Strings[69752]="我还以为死定了呢！谢谢你。"
D.Strings[69753]="矿井突然开始震动，然后那些怪物就冒了出来……"
D.Strings[69754]="谢谢你！我想我能自己出去。"
D.Strings[69755]="请别动手！我没有恶意。我只想确认你们不是跟波尔加一伙的。从你们俩的言行来看，你们恐怕不是因为关系好才追他的。"
D.Strings[69756]="这里是霜狼的土地，但作为拯救我族人的奖赏，这片土地就归你们了。"
D.Strings[69757]="谢谢你，酋长。我们这就动手修建要塞。"
D.Strings[69758]="说实话，头儿，我有点不适应这里的环境。我想我们应该给她一个机会。我们可能会需要她的帮助的。"
D.Strings[69759]="那个肥猪食人魔必须为他造成的苦难付出代价！或许我们可以合作？只要你们帮我一个忙，我就帮你们找到波加尔。"
D.Strings[69760]="我们为什么要相信你？"
D.Strings[69761]="要不是你，我就死定了。谢谢你，英雄。"
D.Strings[69762]="请帮帮其他人……我会自己想办法出去的。"
D.Strings[69763]="我们的死难者需要一个公道！"
D.Strings[69764]="要不是你的帮助，我就死定了。太感谢了！"
D.Strings[69765]="别担心，小家伙们。我们会挺过去的。"
D.Strings[69766]="要是有雷神兽人敢进来，我们就把他们大卸八块！"
D.Strings[69767]="这就是弱者的下场！"
D.Strings[69768]="你救不了他们的！"
D.Strings[69769]="又一个来送死的。"
D.Strings[69770]="我们会照样碾碎你们的！"
D.Strings[69771]="就连我们的双足飞龙都受不了这种严寒的天气。"
D.Strings[69772]="这里的天空似乎都特别不友好。"
D.Strings[69773]="我们得想一个更好的办法，来帮助我们的双足飞龙保暖。"
D.Strings[69774]="看来我们得依靠当地的双头飞龙来飞行了。"
D.Strings[69775]="这个兽人的脸都被咬烂了。"
D.Strings[69776]="这个兽人的半个身子都被蒸汽裂隙烧没了。"
D.Strings[69777]="损毁的尸体上布满了深深的爪印。"
D.Strings[69778]="尸体上的皮肉已经被泡得几乎认不出来了。"
D.Strings[69779]="呃，头儿。我们需要更多的毛皮。在我们过来之前，可没人告诉我们传送门这边会这么冷。"
D.Strings[69780]="我要把你拆散了重装一遍！"
D.Strings[69781]="抓紧了，蛆虫，体验一下风驰电掣的快感吧！"
D.Strings[69782]="伊瑞尔，你怎么看？"
D.Strings[69783]="它充斥和怨恨和尘土，欧穆隆。我不喜欢它。"
D.Strings[69784]="好了，我们动手吧！波加尔经常让人将俘虏押送到熔岩流另一边的一座山洞里。"
D.Strings[69785]="那些可怜的家伙！快点，$G小子:丫头;，我们得干掉格鲁布诺，然后跟着波加尔穿过那座传送门到……随便什么鬼地方去！"
D.Strings[69786]="这碎片是我的！传送门还会继续扩大！"
D.Strings[69787]="不！燃烧军团必将吞噬一切！"
D.Strings[69788]="好冷啊，我的灵魂好像都冻僵了。我可不是为了这个来的。"
D.Strings[69789]="没错，伙计。这些毛皮可以让我的腿暖和一些。我总算又能感觉到自己的脚趾了。"
D.Strings[69790]="他们怎么不告诉我们这里就是一片冻土呢。连这里的火都被冻住了。火怎么会被冻住的？"
D.Strings[69791]="之前我拿出酒壶想喝一口。结果酒水刚到舌尖就被冻住了。我找了两个兽人才把它拽下来。他们不会喜欢这种天气的。"
D.Strings[69792]="呃，伙计。呃。你敢去舔一下金属么？试试嘛。"
D.Strings[69793]="是哪个负责人以为海岛巨魔能适应这种严寒地带的战争？"
D.Strings[69794]="我呼出的热气直接就在鼻子前面冻住了，然后像冰渣一样掉到了地上。我恨这地方。"
D.Strings[69795]="我感觉暖和多了！我总算又能好好思考，而不用在寒风中抱怨了。"
D.Strings[69796]="这块毛皮真的很有用，伙计。"
D.Strings[69797]="我身上都是雪人味儿。我喜欢。"
D.Strings[69798]="我真搞不懂。你们是怎么在同一个地方同时应付烈焰和寒冰的。"
D.Strings[69799]="我显然低估了这里的出土的骨骼尺寸。我需要一把更大的锯子，一些狼拉雪橇，或许还需要几条狼来做研……呃……干活。对，就是干活。"
D.Strings[69800]="你闻上去就像是雷神氏族的猎物。"
D.Strings[69801]="你或许是有把子力气，可这里的严寒能在开战后几秒钟内让你精疲力尽。如果你想活下去，就一定要注意保暖。"
D.Strings[69802]="雷神兽人最喜欢成群结队地去捕杀大型猎物。你会成为那个大型猎物吗？"
D.Strings[69803]="在对付雷神兽人时，最重要就是尽快削减他们的数量。集结成群的雷神兽人是最致命的。一旦这些家伙落单，你就能像碾死虫子一样碾死他们了。"
D.Strings[69804]="看看我，这个理由还不够充分吗？我死了！我的躯体已经腐烂消失了！我过去最喜欢爬上山顶观赏日出。而现在，我注定再也不能享受阳光的温暖了。"
D.Strings[69805]="而这都是拜波加尔所赐……是他把我还成这样的。我要让他的灵魂为他对我和其他被害者所做的一切而哀嚎。这个理由够不够让你们相信我？"
D.Strings[69806]="不要害怕冰雪。你要利用它们。如果受伤了，你可以用它们来迅速延缓伤势发作，直到得到治疗者的救助。拥抱严寒，你才能生存下来。"
D.Strings[69807]="这里很适合建造要塞。"
D.Strings[69808]="我可以打开一道通往奥格瑞玛的传送门，但维持不了多久。那边援军应该已经整装待发了吧？"
D.Strings[69809]="绝对没问题。"
D.Strings[69810]="有人要找修补匠吗？"
D.Strings[69811]="……你让一个地精来做监工？"
D.Strings[69812]="加兹鲁维主持修建了奥格瑞玛。"
D.Strings[69813]="奥格瑞玛！永不陷落之城！"
D.Strings[69814]="它最近不是刚被攻陷吗？"
D.Strings[69815]="对对，好吧，一次小失败。"
D.Strings[69816]="欧穆隆，要加快我们在戈尔隆德的行动了。无论钢铁部落有什么阴谋，我们都得做好准备。"
D.Strings[69817]="她的话很有说服力。说实话，头儿，我觉得我们应该给她一个机会。我们可能需要她的帮助。"
D.Strings[69818]="附近的幼蛛试图逃走……"
D.Strings[69819]="|TInterface\\Icons\\ability_hunter_rapidregeneration.blp:20|t加安上将看向你，并准备施放|cFFFF0000|Hspell:156626|h[急速射击]|h|r！"
D.Strings[69820]="你们这些蠢货！我要让你们为此付出代价！"
D.Strings[69821]="够了！等我干掉你们这些闯入者，就没人能阻止我了！"
D.Strings[69822]="不！不应该是……这样的……"
D.Strings[69823]="如此强大……潜力非凡。这块水晶中蕴藏的能量绝不能再被白白浪费掉！"
D.Strings[69824]="你们可真是天真。这地方毫无价值，不过是我吞噬这颗力量果实时剥开丢掉的果壳而已！"
D.Strings[69825]="你们休想夺走我们的家园！"
D.Strings[69826]="快住手，凯尔娜拉！看看你所造成的这些破坏吧！"
D.Strings[69827]="你对力量的渴求已经蒙蔽了你的心智，凯尔娜拉。我绝不会让你摧毁这座矿井的！"
D.Strings[69828]="为了纪念我们的死难者！"
D.Strings[69829]="誓死保卫我们的家园！"
D.Strings[69830]="赶走入侵者！"
D.Strings[69831]="这是什么——慧耳！你还活着！"
D.Strings[69832]="沃高尔是霜狼氏族的冬季家园。"
D.Strings[69833]="杜隆坦就像在走钢丝，周旋于雷神兽人和刀塔食人魔之间。"
D.Strings[69834]="而贾纳尔似乎已决心向这两者复仇了。"
D.Strings[69835]="啊，没错！我很担心他。他总是那么急躁。对复仇的渴望会让他更加鲁莽。"
D.Strings[69836]="那是什么？一座岩石堡垒！"
D.Strings[69837]="那是刀塔堡垒。它曾是食人魔帝国的边境哨所。"
D.Strings[69838]="如果氏族想要生存下去，就必须赶走堡垒里的食人魔。"
D.Strings[69839]="这是杜隆坦的目标。他不会开口求助，但我们需要你！"
D.Strings[69840]="波加尔的死只是时间问题，而我最不缺的就是时间。"
D.Strings[69841]="我发现了这个图腾，你能帮我看看吗？"
D.Strings[69842]="这是波加尔在发现磨魂者之前用来引导魔法的图腾之一。$b$b我能感觉到上面依然散发着强大的灵魂之力。如果我们找到他的其他图腾，我就可以用它们来将波加尔驱逐出灵魂世界。一旦他得不到这个位面的力量支援，你和欧文就可以干掉他了。"
D.Strings[69843]="尤鲁恩矿场为奥金顿和沙塔斯提供了大量能量水晶。"
D.Strings[69844]="我们加入联盟的德莱尼兄弟姐妹们警告过我们血精灵对魔力的渴望。如果这就是让他们帮忙抵抗燃烧军团的代价，那我宁愿独自面对恶魔。"
D.Strings[69845]="快过来，英雄！我需要你的帮助！"
D.Strings[69846]="燃烧军团必将崛起！德拉诺将被熊熊燃烧的地狱火所包裹！"
D.Strings[69847]="贾纳尔已经等不及了。他实在是太冲动了。"
D.Strings[69848]="去吧！打场胜仗回来。告诉我丈夫，我会守住村子，等他回来的。"
D.Strings[69849]="集中精神，姐妹们！我们必须守住奥金顿。"
D.Strings[69850]="别放弃，缚魂者们。奥金顿绝不能陷落！"
D.Strings[69851]="这里的防线绝不会崩溃。我们是奥金顿的守护者！"
D.Strings[69852]="正如你所知，奥术水晶是德莱尼文化的重要组成部分。这座矿场出产的水晶用途十分广泛，但大部分都供应给了沙塔斯和奥金顿。$b$b经过加工后，这些水晶可以成为强大的奥术能量源。试图释放这么大块的水晶中的能量，这种行为简直鲁莽，愚不可及。$b$b你现在看到的这些肆虐矿场的土元素本应沉睡在大地深处。凯尔娜拉的鲁莽举动似乎激怒了它们。$b$b我的守备官们迟早都能夺回矿场，但一场硬仗是免不了的。"
D.Strings[69853]="我们都誓死保卫奥金顿。守住防线！"
D.Strings[69854]="我们必须不惜一切代价找到卡拉布恩。只要他们的阵线上出现缺口，你就要毫不犹豫地冲进去！"
D.Strings[69855]="我们与你同在，大主教。我绝不会坐视恶魔踏足奥金顿。"
D.Strings[69856]="今天我们会践行自己永恒的誓言。我们将用生命保护奥金顿！"
D.Strings[69857]="我的奴役……结束了。"
D.Strings[69858]="终……于……自由了。"
D.Strings[69859]="甜蜜的自由……"
D.Strings[69860]="尘归尘。"
D.Strings[69861]="燃烧军团是不会轻易放弃的。奥金顿对他们来说太有价值了。"
D.Strings[69862]="塔隆戈尔！圣光来制裁你了！"
D.Strings[69863]="噢……我感觉不太好。"
D.Strings[69864]="你被|cFFFF0000|Hspell:156479|h[毁天灭地]|h|r杀死了。远离冲击点可降低所受伤害。"
D.Strings[69865]="燃烧军团绝不会止步于此。他们太渴望得到奥金顿了。"
D.Strings[69866]="尼娅米，图拉妮。我们得立刻赶去圣光之眠。"
D.Strings[69867]="精神控制仪就在桌子上。"
D.Strings[69868]="我跟莉亚德琳说能应付这个……局面。现在誓日血精灵绝不能失去奥金尼的信任。"
D.Strings[69869]="木材！"
D.Strings[69870]="攻击他们的心脏！"
D.Strings[69871]="占领"
D.Strings[69872]="那些尸体似乎是不久前才被搬来的。我们还得继续赶往那座洞穴，但你一定要打起精神，随时注意周围的动静。"
D.Strings[69873]="我是受大法师卡德加的指派前来塔拉多协助奥金尼对抗燃烧军团的。当我了解到矿场的情况后，就主动要求留下来帮忙了。"
D.Strings[69874]="在地狱的烈火中煎熬吧，没用的蛆虫！"
D.Strings[69875]="臣服于我吧，傲慢的凡人！"
D.Strings[69876]="躺下吧，肮脏的畜生！"
D.Strings[69877]="吁！我说了，“吁！！！”"
D.Strings[69878]="别转了！"
D.Strings[69879]="屈服吧！"
D.Strings[69880]="我要吐了！"
D.Strings[69881]="停下！你这白痴！"
D.Strings[69882]="噢，这下好像很疼啊！"
D.Strings[69883]="嘿！停下！等等！"
D.Strings[69884]="小心背后！"
D.Strings[69885]="这到底是怎么了？！"
D.Strings[69886]="为什么是我？！"
D.Strings[69887]="我还以为我们已经是朋友了！"
D.Strings[69888]="我们又见面了，$n！能请你等一下吗？$B$B诺拉纳随时都会回来。我们想一起感谢你。"
D.Strings[69889]="我们又见面了，$n！再次感谢你的帮助。"
D.Strings[69890]="<安卡的眼中闪着泪花。>伊萨莉的遭遇太可怕了。她是我最好的朋友！"
D.Strings[69891]="我们就不该进那座森林。我……我都不知道该怎么面对这场灾难。"
D.Strings[69892]="撬锁"
D.Strings[69893]="你根本不了解你所染指的力量，马尔高克。（它在召唤我们。我们知道！它的力量将属于我们！）"
D.Strings[69894]="看到这片曾经辉煌而美丽的土地沦为邪能肆虐的荒凉外域，这让我感到非常沮丧。"
D.Strings[69895]="接受大法师瓦格斯的法杖。（要塞追随者）"
D.Strings[69896]="你的统治已经结束了，永夜已经降临。（黑暗降临了！）"
D.Strings[69897]="塔加尔，消灭入侵者！这些灵魂马上就属于我了！"
D.Strings[69898]="圣光能穿透一切黑暗，耐奥祖。"
D.Strings[69899]="你不能把狼栓在那个雪橇上，伙计。万一被霜狼兽人发现了，他们会杀了你的。"
D.Strings[69900]="看看那条小狼崽子，伙计。它拉不动整个雪橇的。你太刻薄了。"
D.Strings[69901]="你有问题，伙计。大问题。那条狼对你做过什么？"
D.Strings[69902]="暗影已经吞噬了我的灵魂，先知。"
D.Strings[69903]="啊，这下好多了！稍微有点松，但只要来几杯啤酒就万事大吉了。"
D.Strings[69904]="快，英雄！阻止这个畜生！"
D.Strings[69905]="蠢货！奥金顿将属于我。每吞噬一个灵魂，我的力量都会增长一点。你所面对的力量远超你的想象。"
D.Strings[69906]="长官，雷神兽人正在向要塞进发！"
D.Strings[69907]="下雨？现在？这太不正常了，我敢打赌，我知道这是谁搞的鬼。"
D.Strings[69908]="雷神兽人，在这儿？斥候，快敲响警钟，让所有人都回要塞里来！"
D.Strings[69909]="士兵们，拿起武器！我们绝不能葬身德拉诺！到你们的岗位上去！"
D.Strings[69910]="不！黑暗之星的力量是我的！"
D.Strings[69911]="现在还不迟。放弃这条黑暗之路，让我们来帮你。 "
D.Strings[69912]="回去，你们这些杂种！除非我死了，否则你们休想离开这儿！"
D.Strings[69913]="别担心，姑娘们。我不会让你们有事的。"
D.Strings[69914]="我得回前线去了。为了奥金顿！"
D.Strings[69915]="感谢你的帮助。这些野蛮人要想打败我们还早着呢！"
D.Strings[69916]="雷神的同胞们！到前线上去！"
D.Strings[69917]="快去前线报到！"
D.Strings[69918]="我们要阻止霜狼氏族！"
D.Strings[69919]="注意保暖，一切都会好起来的。你会没事的。"
D.Strings[69920]="我们来挡住其他人！"
D.Strings[69921]="靠近火堆，双足飞龙受不了这种严寒。一定要注意保暖。"
D.Strings[69922]="别盯着我了。注意保暖！"
D.Strings[69923]="我做好挑战凯尔娜拉的准备了。"
D.Strings[69924]="我准备好返回尤鲁恩矿场了。"
D.Strings[69925]="干得好！我们在前面汇合！"
D.Strings[69926]="我们走！指挥官，我们在塔楼那儿见。"
D.Strings[69927]="熔炉压力失控——山脉之心的温度越来越高了！"
D.Strings[69928]="欢迎，旅行者。这片土地近来虽然灾祸频发，但也涌现出了许多英雄事迹。你愿意追随这些勇者的脚步，见证他们的事迹吗？"
D.Strings[69929]="我所讲述的传奇仍需要你去亲身体会！快踏上冒险之旅吧！$b$b（需要达到至少91级才能聆听福云的故事。）"
D.Strings[69930]="跟我说说绿石村的故事吧。"
D.Strings[69931]="跟我说说盎迦猴岛的故事吧。"
D.Strings[69932]="跟我说说遗忘之王古墓的故事吧。"
D.Strings[69933]="跟我说说破军比武场的故事吧。"
D.Strings[69934]="跟我说说酝酿风暴的故事吧。"
D.Strings[69935]="跟我说说突袭扎尼维斯的故事吧。"
D.Strings[69936]="跟我说说酿月祭的故事吧。"
D.Strings[69937]="跟我说说塞拉摩的沦陷的故事吧。"
D.Strings[69938]="跟我说说黑暗中的匕首刺杀沃金的故事吧。"
D.Strings[69939]="跟我说说公海激战的故事吧。"
D.Strings[69940]="跟我说说瓦里安和泰兰德在王者的耐心一役中的故事吧。"
D.Strings[69941]="跟我说说潘达利亚的黑暗之心的发现过程吧。"
D.Strings[69942]="跟我说说怒焰之谜的故事吧。"
D.Strings[69943]="跟我说说雪山血战的故事吧。"
D.Strings[69944]="做好准备，$n。一旦她的护盾被打破，我就把我们传送出矿洞。"
D.Strings[69945]="马上停止你的疯狂行为，凯尔娜拉！我们绝不允许你继续制造灾难！"
D.Strings[69946]="这么说，你决定跟我一起来驯服黑潮主母？$b$b看来你并不是唯一一个这么想的人。钢铁部落正在毁灭这座岛和它上面的生物。他们毫不尊重自己所捕猎的双头飞龙。$b$b放心吧，$c，我一定会惩戒这个卑鄙的屠夫的。"
D.Strings[69947]="看来你的一位盟友已经到了，法师。"
D.Strings[69948]="我的守备官能应付这里的事了。愿圣光保佑你们俩平安返回。"
D.Strings[69949]="等等……你在干什么……？！不！！！"
D.Strings[69950]="很不幸，但我们现在知道的更多了。你可以使用传送门返回索姆瓦尔。"
D.Strings[69951]="很好，我正想大打一场呢！"
D.Strings[69952]="傲慢的灵魂，你竟敢召唤我！"
D.Strings[69953]="等我回到凡俗世界，你那点可怜的魔法就控制不了我了。等我把你的朋友们喂给磨魂者之后再来对付你！"
D.Strings[69954]="你们欠我一场战斗，懦夫。"
D.Strings[69955]="让我们给观众送上一场值得回味的比赛吧。"
D.Strings[69956]="你太脆弱了！"
D.Strings[69957]="你将成为我靴子上的一点污渍，我会记住你的。"
D.Strings[69958]="先锋军倒下了。我们决不能让他们的巨大牺牲白白浪费！"
D.Strings[69959]="你的牺牲会被人们所铭记的，奈瑟维。"
D.Strings[69960]="大法师，让我留下断后吧。看守这座传送门本就是我的职责。"
D.Strings[69961]="我与你分担了那项使命，达图恩。我们也将共同迎敌。"
D.Strings[69962]="你的英勇事迹将被人们所传唱，达图恩。"
D.Strings[69963]="放我出来，陌生人。我可以用这把铲子杀死几百头蠢猪。"
D.Strings[69964]="准备跟我一起勇敢地跨过传送门！"
D.Strings[69965]="我帮忙从西边的洞穴里运出了几具尸体。有一个又高又瘦，绿头发、浅蓝色皮肤的女人还活着！她看起来不像兽人，如果是的话，那她一定是我见过的最病态的兽人。一个食人魔把她弄到东北边的山洞里去了。"
D.Strings[69966]="几天前的一个夜晚，熔岩流另一边的洞穴里透出了一束诡异的光。这显然不是那个恶心的食人魔所能掌握的魔法。"
D.Strings[69967]="小心点，$n。等我打破凯尔娜拉的护盾，我就把我们传送出矿井！"
D.Strings[69968]="已经够了！你的疯狂到此为止了，凯尔娜拉！"
D.Strings[69969]="凯尔娜拉的背叛真是太不幸了。我会向阿斯塔洛通报他学徒的下场的。"
D.Strings[69970]="你准备好之后，我就把你传送回尤鲁恩矿场。"
D.Strings[69971]="真正的施法能力只能依靠勤奋练习得来。凯尔娜拉太天真了，只想走捷径……"
D.Strings[69972]="我把伤员送到安全的地方去。掩护我们！"
D.Strings[69973]="狂怒汲魔蛾进入了虚弱状态。"
D.Strings[69974]="欢迎你，狼之$g兄弟:姐妹;。快到火堆旁来暖和一下吧。"
D.Strings[69975]="你好，我一直在研究那些新来的外来者们的英勇事迹。你想听听这些故事吗？"
D.Strings[69976]="跟我说说公海激战的故事吧（英雄难度）。"
D.Strings[69977]="跟我说说潘达利亚的黑暗之心的发现过程吧（英雄难度）。"
D.Strings[69978]="跟我说说怒焰之谜的故事吧（英雄难度）。"
D.Strings[69979]="跟我说说雪山血战的故事吧（英雄难度）。"
D.Strings[69980]="跟我说说酝酿风暴的故事吧（英雄难度）。"
D.Strings[69981]="跟我说说遗忘之王古墓的故事吧（英雄难度）。"
D.Strings[69982]="古尔丹是个狡猾的家伙。$B$B别为这点挫折沮丧，指挥官。我们会抓住他的。"
D.Strings[69983]="抱歉我不能加入你了，指挥官。我很乐意跟你一起去杀暗影议会的人。$B$B但我的首要任务是保护大法师。$B$B当然，你可以说服他派我的一位姐妹来替代我。"
D.Strings[69984]="暗影议会一直很恶心。可是，将恶魔能量灌注进死去的霜狼体内这种行为简直太没有下限了！"
D.Strings[69985]="那些岩虫肯定是那个引发地震的家伙带来的，我可以拿我备用的环刃和你打赌。$B$B就算你不知道怎么使用这武器，至少你可以把它挂到墙上当装饰。"
D.Strings[69986]="我会没事的。"
D.Strings[69987]="指挥官，我们在这里的任务已经完成了。请使用传送门返回索姆瓦尔吧。$B$B等你回来之后，我们得好好谈谈下一步的计划。"
D.Strings[69988]="如果我们要想摧毁邪能水晶并瓦解保护着深黯峰的屏障，你必须找到恶魔钥匙。$B$B是我的话，就会从击杀菲努斯着手。"
D.Strings[69989]="快，$n。下一步就是穿过废墟，用恶魔之心摧毁邪能水晶了。"
D.Strings[69990]="时间紧迫，指挥官。古尔丹随时可能离开。$B$B你必须摧毁那些邪能水晶，并进入深黯峰抓住他。"
D.Strings[69991]="你的身手一如既往的出色，$n指挥官。$B$B现在只剩一件事了：那就是抓住古尔丹。"
D.Strings[69992]="古尔丹就在下面。我不管你怎么做，$n，但一定要在他逃跑之前抓住他。"
D.Strings[69993]="都给我用力砸！我们要在下一次鲜血之环中击败刀塔氏族！"
D.Strings[69994]="再加把劲，否则我就揍死你！"
D.Strings[69995]="只要你能赢下鲜血之环的比赛，我就把锁在外面的奴隶送给你。"
D.Strings[69996]="很抱歉，狼之$g兄弟:姐妹;。让大法师在我们的家中遭到袭击，我们对此深感惭愧。"
D.Strings[69997]="如果我有能力的话，真想回到过去，在古尔丹饮下玛诺洛斯的鲜血前掐死他。"
D.Strings[69998]="记住我的话，$g兄弟:姐妹;，古加尔跟这些白鬼搅和在一起是不会有好下场的。"
D.Strings[69999]="我的心情很沉重。感谢你给了狼母应有的体面。$B$B我们会为她复仇的。"
D.Strings[70000]="无论你是谁……总之谢谢你。"
D.Strings[70001]="他们想让我们的鲜血流干。我觉得我们坚持不了多久了……"
D.Strings[70002]="放我们出去！"
D.Strings[70003]="该给你们放点血了！"
D.Strings[70004]="快！我们得把这些补给品运过去。耐奥祖绝不允许出现任何延误，我也一样！"
D.Strings[70005]="四……你最需要苦力的时候，怎么就偏偏找不到人呢？"
D.Strings[70006]="看看那些德莱尼，多么与世无争。他们还不知道自己即将被征服。"
D.Strings[70007]="要是没有你的帮助，指挥官，我们很难打倒那个食人魔。"
D.Strings[70008]="快点，小崽子们，我们的订单还没完成呢！"
D.Strings[70009]="钢铁部落需要更多的精钢！"
D.Strings[70010]="我要把你的肉一块块咬下来！"
D.Strings[70011]="献出你的鲜血……"
D.Strings[70012]="现在，你归血环氏族了！"
D.Strings[70013]="碾碎你，流血吧！"
D.Strings[70014]="滚开，爬虫！"
D.Strings[70015]="你的球呢？"
D.Strings[70016]="这里的魔精很强，伙计。现在，我们该对付这个怪物了。"
D.Strings[70017]="你们以为逃跑这么容易？攻击！"
D.Strings[70018]="阻止他们！谁都不准离开！"
D.Strings[70019]="你们已经走投无路了，德莱尼！"
D.Strings[70020]="恐牙会解决你们的。"
D.Strings[70021]="$n触发了一个炉渣炸弹。"
D.Strings[70022]="别跑，小矮子！我要让你亲眼看着我把你的朋友喂给磨魂者！"
D.Strings[70023]="给我留下吧，小矮子！你休想用你那古怪的魔法对付我！你就在一旁看着我把你的朋友喂给磨魂者吧！"
D.Strings[70024]="快！控制住这里的火势！"
D.Strings[70025]="再来点水！"
D.Strings[70026]="你！快去找水！我们得把火扑灭。"
D.Strings[70027]="快去找水来！"
D.Strings[70028]="我们必须加入钢铁部落，否则就会被它给碾碎。我们必须证明自己的价值！"
D.Strings[70029]="我们的祖先曾禁止使用黑暗魔法，都是他们拖了我们的后腿。"
D.Strings[70030]="我们应该找回这种能够拯救我们氏族的力量！"
D.Strings[70031]="影月氏族的兄弟姐妹们，我在此号召你们，使用我们世代相传的技艺！"
D.Strings[70032]="用它们召唤出先祖的灵魂。"
D.Strings[70033]="让它们服从你的意志。"
D.Strings[70034]="将它们变成我们急需的力量，我们应得的力量！"
D.Strings[70035]="只有这样，影月氏族的未来才有保障！"
D.Strings[70036]="挤压"
D.Strings[70037]="祝福你，陌生人。多亏了你，我才能重见天日。"
D.Strings[70038]="谢谢你，陌生人！我差点就变成了他们的盘中餐……"
D.Strings[70039]="谢谢你，英雄。到了这里，我就能自己杀出去了。"
D.Strings[70040]="我们决不能让塔隆戈尔进入奥金顿。来吧，我会在惩戒岗哨等你，我们得讨论一下如何才能打败敌人。"
D.Strings[70041]="我们走，伙计，那座山洞就在熔岩地的西南边。"
D.Strings[70042]="这些尸体还有体温。让我们保持警惕，继续前进吧。"
D.Strings[70043]="我杀了你！"
D.Strings[70044]="再杀几个，伙计，那我们就能把灵魂带回这里来了！"
D.Strings[70045]="等等，伙计，别出声，到这儿来。"
D.Strings[70046]="我们走，伙计！我们得快点干掉那个独眼魔，好使用传送门。"
D.Strings[70047]="我们得继续追杀猎物！快穿过传送门！"
D.Strings[70048]="小心点，指挥官，这里不止我们两个人。我发现你了，幽灵！快出来吧！"
D.Strings[70049]="指挥官，我感觉她身上没有邪气，而且她是我们进来之后第一个跟我们说话的幽灵。我们应该争取她的帮助。"
D.Strings[70050]="你*咳嗽*恢复了这位垂死兽人的荣光，勇士。再见了。还有雪足，我的老朋友，再见……"
D.Strings[70051]="谢谢你，英雄。你的英勇事迹将被人们所铭记。"
D.Strings[70052]="你听说了吗？钢铁部落派出特使来跟耐奥祖谈判了。"
D.Strings[70053]="我从一个钢铁部落的家伙那里偷听到，他们好像计划在近期攻打卡拉波。"
D.Strings[70054]="耐奥祖教会我们如何获得自己应得的力量。德莱尼很快就会见识到我们的厉害了。"
D.Strings[70055]="鲁尔坎带着氏族里那些不愿意拥抱虚空的弱者们出走了。"
D.Strings[70056]="我听到传言说，耐奥祖打算召唤黑暗之星！"
D.Strings[70057]="我必须得烤烤火！"
D.Strings[70058]="我根本就不该来这里！"
D.Strings[70059]="趁他们还没把你冻僵，快离开这里吧！"
D.Strings[70060]="好冷啊……可还有意识……"
D.Strings[70061]="痛苦……"
D.Strings[70062]="这灼人的严寒！"
D.Strings[70063]="我根本感觉不到热度……"
D.Strings[70064]="我来释放双头飞龙。你来对付这只爬虫。"
D.Strings[70065]="这个祭坛挡住了我们的路！我来找一个薄弱点……"
D.Strings[70066]="这没用。我想我得拖出……"
D.Strings[70067]="好了，现在可以开始大砸特砸了！"
D.Strings[70068]="好了，都砸烂了。我们回去吧。"
D.Strings[70069]="休息够了，出发！"
D.Strings[70070]="我们的盟友只能帮我们争取到这点时间了，那个……钢铁部落很快就会全力突袭我们的营地。$b$b我们得继续前进了。"
D.Strings[70071]="那我们就走吧！"
D.Strings[70072]="|TINTERFACE\\ICONS\\Spell_Arcane_MassDispel.blp:20|t你受到了|cFFF00000|Hspell:158605|h[混沌标记]|h|r的影响！"
D.Strings[70073]="|TINTERFACE\\ICONS\\spell_Mage_NetherTempest.blp:20|t$n身上的|cFFF00000|Hspell:158648|h[混沌之球]|h|r爆炸了！"
D.Strings[70074]="接受我的恩赐，沃匹尔。你将成为新一代的征服者！"
D.Strings[70075]="多么古怪的标本！你以前见过这样的花吗，旅行者？"
D.Strings[70076]="啊，我的眼中钉来了。"
D.Strings[70077]="是时候给你点教训了。"
D.Strings[70078]="来吧，赛鲁斯。晚餐来了。"
D.Strings[70079]="启动仪式。"
D.Strings[70080]="见证我无尽的力量吧，凡人。"
D.Strings[70081]="斯比雷！"
D.Strings[70082]="抓住她！在仪式完成之前，绝不能让她跑了！"
D.Strings[70083]="我们就要完成了！再过一会儿，她的力量就将属于我们！"
D.Strings[70084]="稳住！要想加入钢铁部落，我们必须吞噬先祖的力量。"
D.Strings[70085]="别管我！"
D.Strings[70086]="兽栏。"
D.Strings[70087]="移除兽栏。"
D.Strings[70088]="好吧，英雄，你挽救了我的生命和荣誉。请让我为你效命以偿还这份人情。$b$b你会发现我是一个可怕的战士。我还掌握着双头飞龙骑术，这在霜狼兽人中可是很少见的。$b$b你愿意接受我的效劳吗？"
D.Strings[70089]="接受穆维里克的效忠。（要塞追随者）"
D.Strings[70090]="你的事迹已经表明你是一个出色的指挥官。与你这样的指挥官并肩作战是我的荣幸。"
D.Strings[70091]="快跑！%s已经|cFFFF0000|Hspell:159632|h[饥肠辘辘]|h|r并想要吃了你！"
D.Strings[70092]="快跑吧……他们也会折磨你的……"
D.Strings[70093]="你……你是谁……？"
D.Strings[70094]="就让我死吧！"
D.Strings[70095]="快动手吧，陌生人！结束我的痛苦吧！"
D.Strings[70096]="水……水……"
D.Strings[70097]="出什么事了？你是谁？"
D.Strings[70098]="我要妈妈……"
D.Strings[70099]="来，拿上他们的利刃。在我们发信号之前，千万不要乱用它。"
D.Strings[70100]="我在此奉上我的力量，主人！"
D.Strings[70101]="莫格索德大人，听从我的召唤。这个凡人威胁到了主人的计划！"
D.Strings[70102]="嘿，头儿！快进来避避寒。我们在这些石头里找到一个暖和的地儿，千万别客气。"
D.Strings[70103]="刃牙虎人！我闻到你们在阴影中散发出的臭气了……出来跟我玩玩儿吧！"
D.Strings[70104]="这最好能管用，古尔丹。"
D.Strings[70105]="你为什么要折磨我们？"
D.Strings[70106]="你毁了你自己和我们的氏族。"
D.Strings[70107]="嘿！你在干什么？那是我的食物！！"
D.Strings[70108]="我们这么做，都是为了生存！"
D.Strings[70109]="别对我妄加批判！挽救氏族的力量就藏在你的灵魂里。"
D.Strings[70110]="我会很乐意扭曲你的残魂的。"
D.Strings[70111]="我也不喜欢这样，请别让我更加难受了。"
D.Strings[70112]="来吧，塔隆戈尔。我们的内应说出了奥金顿的另外一个入口。你很快就能享用那里的灵魂了。"
D.Strings[70113]="我的……晚餐……"
D.Strings[70114]="好的，古尔丹，如你所愿。"
D.Strings[70115]="有我的保护，谁都死不了！"
D.Strings[70116]="活下去！"
D.Strings[70117]="呸！你把我从冰块里放了出来，这让我还怎么学习控制寒冰呢！我要砸死你！"
D.Strings[70118]="我好像在变冷……"
D.Strings[70119]="我已经看够了。"
D.Strings[70120]="卡加斯，你这个懦夫！"
D.Strings[70121]="在我面前，你连十秒钟都撑不过去，德莱尼。"
D.Strings[70122]="你好像害怕了，卡加斯。"
D.Strings[70123]="二对一？这话合我胃口！"
D.Strings[70124]="真是没有竞技精神啊，刃拳。我们为什么不去竞技场解决这场纷争呢？"
D.Strings[70125]="都住手！他们的话很合我胃口！"
D.Strings[70126]="但我恐怕你也只能让我热热身了，德莱尼。今天就没有其他人要来送死了吗？"
D.Strings[70127]="就等你这句话呢。"
D.Strings[70128]="回去找卡德加吧，勇士！我们会帮你争取时间的！"
D.Strings[70129]="我要砍掉你们的脑袋，德莱尼。"
D.Strings[70130]="你怎么没把刀刃装在嘴上呢，卡加斯？"
D.Strings[70131]="……看来有些人已经把刀刃装在手上了。"
D.Strings[70132]="我有个更好的想法，把我的利刃砍进你的喉咙里！"
D.Strings[70133]="你就让一个德莱尼来帮你冲锋陷阵吗，绿皮？"
D.Strings[70134]="如果我们有共同的敌人，那我不介意这么做。"
D.Strings[70135]="呸！亏我还把你当成兽人……"
D.Strings[70136]="你手上的是黑石战锤，绿皮。"
D.Strings[70137]="没错。你要仔细看看吗？"
D.Strings[70138]="我喜欢跟德莱尼战斗。你们这些家伙在面对死亡时，总是一副惊恐万状的样子。"
D.Strings[70139]="抱歉让你失望了。"
D.Strings[70140]="肮脏的畜生！你们就像猫咪一样无力！"
D.Strings[70141]="亮出你们的爪牙，冲我来吧！"
D.Strings[70142]="你们的爪子上浸满了无辜者的鲜血！"
D.Strings[70143]="%s逃离战场，去报告你的位置了！"
D.Strings[70144]="剩下的人都跑了……但不是我们放走的。"
D.Strings[70145]="空气……好像……有些怪味道。"
D.Strings[70146]="阿莎！到我这儿来！"
D.Strings[70147]="我会帮你的！"
D.Strings[70148]="我会和你并肩战斗的。"
D.Strings[70149]="你能想象一个活的巨人吗？他们说这是最后一个了，雷神氏族在数代之前杀了它。"
D.Strings[70150]="我得去帮助其他人。再帮我多杀几个敌人吧！"
D.Strings[70151]="我是来结束你的痛苦的，朋友。安息吧，折磨你的人一定会得到惩罚的。"
D.Strings[70152]="干掉那些无人切割者，然后到岛屿的南边来见我们吧。"
D.Strings[70153]="哈，我们会把他们也干掉的！"
D.Strings[70154]="是时候让钢铁部落学会尊重狩猎了。哈拉萨，留在这里保护好我们的朋友。"
D.Strings[70155]="当我说我愿意征战沙场时，我还以为自己会作为一名士兵，用熟练的武器技艺赢得胜利。$b结果我却在这里绘图砌砖。$b$b但我想这至少能让我多活几年。"
D.Strings[70156]="我会遵守承诺放了你的。但我想你在离开之前，恐怕得先跟这些狼谈谈。"
D.Strings[70157]="我们走，$n。狩猎继续。"
D.Strings[70158]="喂！等等！就一小会！让我们好好谈谈吧！"
D.Strings[70159]="我要将你的英勇事迹告诉我在竞技场里的同胞们。保重。"
D.Strings[70160]="来人啊！！救命啊！！我需要支援！！"
D.Strings[70161]="我感觉烈焰正在熄灭。出什么事了，大主教？"
D.Strings[70162]="我们有客人了。也许……还是我们的救星。"
D.Strings[70163]="我们自由了！跟我走，萨满。我们得翻山逃跑。"
D.Strings[70164]="冷静……冷静。你已经安全了。我不会伤害你的。"
D.Strings[70165]="我会把她送去安全的地方。到东边岛上来见我吧。尼莎会按你的要求，载着你飞过去的。"
D.Strings[70166]="哇！很好……好姑娘。"
D.Strings[70167]="古尔丹之眼发现了你！"
D.Strings[70168]="%s放置了一面铁军战旗！"
D.Strings[70169]="塔隆戈尔不想再受到打扰了。干掉入侵者！"
D.Strings[70170]="我准备好选择岗哨建筑了。"
D.Strings[70171]="这里就是事发现场……"
D.Strings[70172]="看这里——狼的足迹突然变成了兽人的足迹。我们的某个萨满发现了她。"
D.Strings[70173]="她的尸体呢？"
D.Strings[70174]="钢铁部落会把这些狼喂给双头飞龙吃。$b$b在我打破大门时，这个小崽子想要逃走。$b$b让我们看看他对我们有没有用吧。"
D.Strings[70175]="不管那是谁，他们肯定带走了阿莎的尸体。"
D.Strings[70176]="他们会给她一个体面的葬礼的。来吧，让我们去跟杜隆坦谈谈。"
D.Strings[70177]="我是不会轻易放弃的！加尔鲁什亲口把暴风城许给了我！"
D.Strings[70178]="嘿，弗兰兹？弗兰佐克！我们这儿卡住了！"
D.Strings[70179]="我才不去修呢！上次就是我修的！"
D.Strings[70180]="嘿，你！快进去修好那个冲压机！"
D.Strings[70181]="所以呢？快去修一下吧！"
D.Strings[70182]="你想告诉黑手我们的冲压机压不了东西吗？"
D.Strings[70183]="哈哈哈！我猜这批产品里肯定会有不少杂质了。"
D.Strings[70184]="干活，干活，干活……"
D.Strings[70185]="他说的对。钢铁部落会来的。我们得做好准备。"
D.Strings[70186]="我们会准备好的。他们休想占领雷霆小径。"
D.Strings[70187]="这是他的选择。"
D.Strings[70188]="<艾瑞德睡得很不安稳，呼吸十分急促。>"
D.Strings[70189]="仔细检查艾瑞德的状况。"
D.Strings[70190]="<艾瑞德睡得很不安稳，呼吸十分急促。他满头大汗，鲜血淋漓的伤口散发着腐臭的气味。看来他已经时日无多了。>"
D.Strings[70191]="附近的一头虚空狼向你发出了警告！快在它发动攻击之前远离它！"
D.Strings[70192]="附近的一头虚空眼魔向你发出了警告！快在它发动攻击之前远离它！"
D.Strings[70193]="我看到你的部队自信勇敢地穿过了战歌氏族的地盘。$b$b你很值得我关注。"
D.Strings[70194]="接受戈隆追猎者洛卡什的投诚。（要塞追随者）"
D.Strings[70195]="你去对付那些尉官，勇士。刃拳就交给我吧。"
D.Strings[70196]="竟然屠杀手无寸铁的囚犯？为什么不来一场真正的战斗呢？"
D.Strings[70197]="能让我追随你吗？"
D.Strings[70198]="接受洛卡拉的血誓。（要塞追随者）"
D.Strings[70199]="你即将从你的沃尔瓦攻城车里被弹射出来，并返回纳格兰。"
D.Strings[70200]="加盖"
D.Strings[70201]="我们就全靠你了，$n。"
D.Strings[70202]="$n制造了一件空气法器！"
D.Strings[70203]="$n正试图解除一名盟友身上的所有群体控制效果！"
D.Strings[70204]="一群愤怒的兽人开始向竞技场内投掷|cFFFF0000|Hspell:159386|h[钢铁炸弹]|h|r！$B$B x5 钢铁投弹手|TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70205]="一群醉醺醺的食人魔开始从看台上向下投掷|cFFFF0000|Hspell:159410|h[暴虐酒]|h|r！$B$B x2 喝醉的投毒者|TInterface\\Icons\\achievement_reputation_ogre.blp:32|t x5 钢铁投弹手 |TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70206]="渴望鲜血的观众纷纷向竞技场内投掷杀伤性物品！$B$B x1 喝醉的投毒者|TInterface\\Icons\\achievement_reputation_ogre.blp:32|t x5 钢铁投弹手 |TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70207]="醉心暴力的观众开始尝试增加尸体的数量！$B$B x3 喝醉的投弹手 |TInterface\\Icons\\achievement_reputation_ogre.blp:32|t x5 钢铁投弹手 |TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70208]="由于尸体不足，愤怒的观众纷纷向竞技场内投掷炸药！$B$B x5 钢铁投弹手 |TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70209]="可维伦大师，我从没带过兵。你确定——"
D.Strings[70210]="你的能力超出了你的想象，伊瑞尔。"
D.Strings[70211]="去吧。游侠们会听从你的指挥。去找到那些俘虏。"
D.Strings[70212]="已经没有希望了。我们该怎么出去？"
D.Strings[70213]="想想你的同胞。那些俘虏还需要我们的帮助！"
D.Strings[70214]="为什么？救了他们又有什么用？我们最终还是难逃一死。"
D.Strings[70215]="我们不能就这么放弃！英雄都是在挫折中成长起来的。"
D.Strings[70216]="英雄？才不是呢！我只是个新兵，还是个不怎么样的新兵。"
D.Strings[70217]="我们都是从小人物成长起来的。我就曾在丹莫罗寒冷的群山中杀过穴居人。"
D.Strings[70218]="我明白了，$n。你从不逃避挑战。我也应该努力向你学习。"
D.Strings[70219]="打起精神来，伊瑞尔！你可以做得更好！"
D.Strings[70220]="噢！我早该听你的意见，$n。我不会再屈服于自己的恐惧了。"
D.Strings[70221]="你必须做出选择，伊瑞尔。你是要起来战斗，还是让怀疑压垮你？"
D.Strings[70222]="你是对的，$n。我的选择是有意义的。我选择……战斗到底！"
D.Strings[70223]="相信圣光！不要在意一点小挫折，圣光必胜。"
D.Strings[70224]="真的？可正义并非总能战胜邪恶。"
D.Strings[70225]="圣光的力量取决于它的勇士。相信你自己。"
D.Strings[70226]="其实只是因为“怀疑圣光”听起来不够响亮。"
D.Strings[70227]="你的族人曾战胜过无数艰难险阻。如今你愿意在毫不抗争的情况下，就这么让他们的希望在这里覆灭吗？"
D.Strings[70228]="你真是睿智，$n。我必须相信自己，因为圣光与我同在。"
D.Strings[70229]="你的幽默可真不合时宜，$c。但你说的有点道理。我要勇敢起来！ "
D.Strings[70230]="你说的对，$n。我不能就这样认输。我要战斗！"
D.Strings[70231]="$n激活了主峰的聚焦之虹！"
D.Strings[70232]="你即将从你的塔拉坦克里被弹射出来，并返回纳格兰。"
D.Strings[70233]="你这家店很不错嘛。比我在沙塔斯工作的那个小棚子大多了。"
D.Strings[70234]="我们的战舰即将抵达卡拉波，做好准备。"
D.Strings[70235]="我想要升级装备……"
D.Strings[70236]="我找到了一些奇怪的金属，请你帮我检查一下……"
D.Strings[70237]="我这里还有一些寒铁锭要给你。"
D.Strings[70238]="火炮轰击来袭！"
D.Strings[70239]="你要想变成兽人烤肉串，就继续信口开河吧。"
D.Strings[70240]="你们两个比地精小矮子干得还要慢！"
D.Strings[70241]="你是想等诺森德的雪都化完了才修好那个冲压机吗！"
D.Strings[70242]="我要立刻听到工作已经完成的消息。"
D.Strings[70243]="你知道要想在这些东西下面藏一具尸体有多么容易吗？"
D.Strings[70244]="你的废话已经够多了。"
D.Strings[70245]="管好这些苦力！听到耐奥祖的话没有？谁都不准离开村子！"
D.Strings[70246]="|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t山脉之心释放|cFFFF0000|Hspell:155209|h[冲击]|h|r的频率提高！"
D.Strings[70247]="前门附近发现入侵者！"
D.Strings[70248]="农场附近发现入侵者！"
D.Strings[70249]="议政厅附近发现入侵者！"
D.Strings[70250]="很好！我们肯定是抢在塔隆戈尔和古尔丹前头了！"
D.Strings[70251]="尼娅米正在加固工事，抵御他们的攻击——跟我来，我们得去向她报告。"
D.Strings[70252]="很漂亮，不是吗？想想吧——你是第一个进入奥金顿参观的外来者。"
D.Strings[70253]="奇怪……门怎么锁上了？没关系……"
D.Strings[70254]="历代守备官和大主教们。他们都是英雄——他们的灵魂仍然与我们同在。"
D.Strings[70255]="尼娅米！我们来——"
D.Strings[70256]="这是什么？噢，不……不……"
D.Strings[70257]="你必须阻止他们！"
D.Strings[70258]="……守护者……仍然听从她的命令……你必须击败它！"
D.Strings[70259]="她……逃跑了。防御工事……"
D.Strings[70260]="她还有帮手。组织里的许多成员都被腐蚀了……"
D.Strings[70261]="我得召集那些忠贞不渝的成员并保护好他们。你——请你出去阻止这场疯狂的暴行！"
D.Strings[70262]="你……你成功了！"
D.Strings[70263]="拿着——这并不足以酬谢你的无私帮助，但这是我们应该给的。"
D.Strings[70264]="现在我们可以……我们也必须东山再起。我们绝不会让同胞的灵魂落入燃烧军团之手。"
D.Strings[70265]="你不知道你所做的一切有多么伟大。我们的族人将永远感激不尽。"
D.Strings[70266]="地震冲击波！快用蒸汽喷泉口远离地面！"
D.Strings[70267]="既然奥金顿之心已经回归，我们的防御工事应该就固若金汤了！"
D.Strings[70268]="勇士！你能来真是太好了！我来拖住这些雷神兽人，说不定你的盟友也会来。"
D.Strings[70269]="$n失去了减伤护盾！"
D.Strings[70270]="后门附近发现入侵者！"
D.Strings[70271]="矿井附近发现入侵者！"
D.Strings[70272]="西侧城墙附近发现入侵者！"
D.Strings[70273]="城镇广场附近发现入侵者！"
D.Strings[70274]="就是你，图拉妮，还有你的外来者朋友。"
D.Strings[70275]="尽管去尝试吧，但这个地方已经完了。毁灭只是时间问题……"
D.Strings[70276]="很好！很好！水晶开始共鸣……只需要调整一下焦距并且……"
D.Strings[70277]="是时候来造房子了！"
D.Strings[70278]="我想他已经死了。"
D.Strings[70279]="武器！"
D.Strings[70280]="现在，让我们看看他们被活剐时的表情吧！"
D.Strings[70281]="我终于自由了！"
D.Strings[70282]="再见了，亲爱的。"
D.Strings[70283]="我还以为我要死在这儿了。"
D.Strings[70284]="你不会明白我等这一刻等了多久。"
D.Strings[70285]="去死吧，肥猪！"
D.Strings[70286]="我会为你报仇的，塔诺什。"
D.Strings[70287]="愿圣光与你同在，姐妹。"
D.Strings[70288]="愿你的灵魂与先祖一同安息。"
D.Strings[70289]="杀了他们。杀光他们。"
D.Strings[70290]="让他们也尝尝我所受的痛苦。"
D.Strings[70291]="我之前从来都没拿过武器。"
D.Strings[70292]="感觉不错。"
D.Strings[70293]="你给我的族人带来了希望，陌生人。"
D.Strings[70294]="这个小可怜，她在逃离火场时受伤了。$b$b<维罗妮娅温柔地拍了拍噜噜小姐的脑袋。>$b$b看看她那忧郁的小脸，我不能扔下她独自面对烈焰。"
D.Strings[70295]="奥尔高格饿了，他要吃更多的黑石矿石！"
D.Strings[70296]="敌人放下了一枚炸弹！快找到它！"
D.Strings[70297]="快来帮忙！小徘徊者都被大火吓傻了，连跑都不会跑了！请你去让它们冷静下来，好让它们逃跑！"
D.Strings[70298]="达戈谢谢你，朋友！<达戈发出一阵粗哑的笑声。>"
D.Strings[70299]="真不知该怎么谢谢你才好啊，$n。"
D.Strings[70300]="指挥官！你还是一如既往的准时啊。"
D.Strings[70301]="鲁卡，跟我走。我们该回要塞去了。"
D.Strings[70302]="奥尔高格吃够黑石矿石了！"
D.Strings[70303]="贾纳尔让我别挡他的道，所以我照办了。我可不想为了铁狼或者他的亲戚把命送掉。$b$b我们得谈谈……如果你能活下来的话。"
D.Strings[70304]="你愿意和我一起对抗钢铁部落吗？"
D.Strings[70305]="别看我，我是不会卷入这场纷争的。"
D.Strings[70306]="我也不知道是怎么被那些兽人抓住的。<达戈窘迫地笑了笑。>"
D.Strings[70307]="嗨，又见面了。"
D.Strings[70308]="你自己去问他们吧，“到底是他们抓住了达戈还是达戈抓住了他们？”\n\n大英雄识破了达戈的伪装！但达戈觉得，你是特别的。达戈是伪装大师，达戈想要加入你。\n\n达戈没有意见。"
D.Strings[70309]="是否与达戈达成协议？（要塞追随者）"
D.Strings[70310]="一个伟大的领袖应该为他的追随者做出榜样。$b$b他们知道什么时候该发表意见，什么时候该耐心聆听。$b$b他们知道何时应该为生存而奋起反抗，也知道何时应该为了更伟大的事业而流血牺牲。$b$b你做好成为领袖的准备了吗，$n？"
D.Strings[70311]="谢谢你，陌生人。现在，我终于可以进入奥金顿了。"
D.Strings[70312]="我祝福你，$c。"
D.Strings[70313]="感谢圣光，多亏你及时出现了。"
D.Strings[70314]="你感觉到了吗，$n？一支大军即将集结在此，他们将听从你的号令。"
D.Strings[70315]="插下你的旗帜，迎接你的命运吧。"
D.Strings[70316]="不要拆穿达戈的身份！$B$B人们是不会询问一棵树的意见的。$B$B达戈没有意见。"
D.Strings[70317]="别让他们看见我们在说话！\n\n人们从来不向两个脑袋的家伙询问意见。\n\n达戈没有意见。"
D.Strings[70318]="嘘！表现得自然点。"
D.Strings[70319]="嘘！别拆穿我。"
D.Strings[70320]="烧毁大桥！谁都别想来插手！"
D.Strings[70321]="快转身，躲开催眠魔蛙的|cFFFF0000|Hspell:160664|h[催眠凝视]|h|r"
D.Strings[70322]="那么，这里就是你建造要塞的地方了。$b$b你以前指挥过这么多部队吗？$b$b我相信你会做得很好的……但愿如此。"
D.Strings[70323]="有你在这里，我感觉就更有把握了，$n。"
D.Strings[70324]="卡拉波神殿？不……这不可能。我们遭到了攻击！"
D.Strings[70325]="等等……不……这不可能。神殿遭到了攻击！"
D.Strings[70326]="守住路障！不惜一切代价保护防护水晶！"
D.Strings[70327]="够了！游戏结束了。舰队，听我的命令，集中火力轰击水晶！"
D.Strings[70328]="不！那块水晶是我们唯一的希望了。"
D.Strings[70329]="跟紧我，勇士！"
D.Strings[70330]="这些旧骨头里肯定有我们能用得上的东西。"
D.Strings[70331]="快点干，蠢货，黑暗之星的降临之日已经越来越近了！"
D.Strings[70332]="$n摆出了一桌红肉盛宴。快来享用吧！"
D.Strings[70333]="伊瑞尔，出什么事了？"
D.Strings[70334]="我们阻止不了黑暗之星，先知。钢铁部落占领了港口！"
D.Strings[70335]="小心脑袋！钢铁飞弹过来了！"
D.Strings[70336]="|TInterface\\Icons\\Spell_Fire_Fireball02:20|t$n获得了|cFFFF0000|Hspell:160702|h[黑石迫击炮弹]|h|r！"
D.Strings[70337]="|TInterface\\Icons\\inv_misc_pyriumgrenade:20|t$n获得了|cFFFF0000|Hspell:160703|h[黑石手雷]|h|r！"
D.Strings[70338]="|TInterface\\Icons\\spell_shaman_improvedfirenova:20|t$n获得了|cFFFF0000|Hspell:156357|h[黑石榴弹]|h|r！"
D.Strings[70339]="我要你跟我一起去巡逻。"
D.Strings[70340]="欢迎来到试炼竞技场！我正在这里举办格斗比赛。如果你想要赚点外快，那你可来对地方了！"
D.Strings[70341]="我能为你做些什么，指挥官？"
D.Strings[70342]="我来帮你，指挥官！"
D.Strings[70343]="坚持住，长官！"
D.Strings[70344]="你不会那么轻易倒下的！"
D.Strings[70345]="标记"
D.Strings[70346]="你想参加竞技场的比赛？去跟戴克希尔说吧，负责比赛的人是他。$b$b我？我只是来宣布比赛开始……并在战斗后清理尸体的！哇哈哈！"
D.Strings[70347]="来啊，你们这些丑八怪！"
D.Strings[70348]="这些家伙就交给我吧！"
D.Strings[70349]="干嘛不冲我来呢？"
D.Strings[70350]="快阻止破坏者！"
D.Strings[70351]="我们已经做好开工的准备了！我在建造奥格瑞玛时学到了一些新技术。"
D.Strings[70352]="开始施工[建造要塞]"
D.Strings[70353]="钢铁舰队！全力开火！"
D.Strings[70354]="我准备好接受试炼之环的第一场挑战了。"
D.Strings[70355]="血腥的玛拉卡开始对你引导|cFFFF0000|Hspell:158079|h[鲜血仪式]|h|r！"
D.Strings[70356]="任务繁重，时间紧迫。"
D.Strings[70357]="我准备好接受试炼之环的第二场挑战了。"
D.Strings[70358]="我准备好接受试炼之环的第三场挑战了。"
D.Strings[70359]="我准备好接受试炼之环的第四场挑战了。"
D.Strings[70360]="我准备好接受试炼之环的第五场挑战了。"
D.Strings[70361]="他们正用火炮轰击我们！"
D.Strings[70362]="感谢你的帮助，我已经痊愈，可以返回战场了！"
D.Strings[70363]="前进！我们必须阻止沃尔卡！"
D.Strings[70364]="非常感谢。我痊愈了，又可以继续战斗了！"
D.Strings[70365]="真没想到在这片荒野上还能见到友善的面孔。我们全靠团结一致，互相依赖才走到了这一步。$b$b但我们的逃亡计划只完成了一半。考戈尔事先得到了风声，我们的刺杀失败了，没能拿到他的斧子。"
D.Strings[70366]="我从没遇到过猎杀不了的野兽！"
D.Strings[70367]="不！呱！你只是又一个幻影！又一个谎言！呱呱！我会揭穿你的黑暗本质的！"
D.Strings[70368]="加安上将准备操纵无畏舰的主炮！"
D.Strings[70369]="执行者苏卡准备操纵无畏舰的主炮！"
D.Strings[70370]="血腥的玛拉卡准备操纵无畏舰的主炮！"
D.Strings[70371]="我恐怕必须离开了，请到沃高尔与我们的队伍汇合吧。Aka'Magosh。"
D.Strings[70372]="滚开，苦力！"
D.Strings[70373]="卡什德拉克说逃跑的时机到了。"
D.Strings[70374]="谁在那儿！？噢——很高兴看到还有人跟我一样在与这些怪物奋战。"
D.Strings[70375]="黑暗已经降临了……"
D.Strings[70376]="我父亲派你来的？我就说他一定会想办法来救我的！谢谢你，陌生人。"
D.Strings[70377]="你自以为很聪明吗？！下一个就轮到你了！"
D.Strings[70378]="蠢货！这么点火可烧不死我！"
D.Strings[70379]="懦夫！你不可能一直躲在这些陷阱后头！"
D.Strings[70380]="我的死改变不了什么！全力……进攻！"
D.Strings[70381]="看那儿！舰队的指挥官出现了！"
D.Strings[70382]="勇士，我需要你帮忙保护我。如果你能帮我争取到足够的时间，我们就能击退围攻的敌人！"
D.Strings[70383]="他们正在突破路障。退到台阶那里去！我们要在那里决一死战！"
D.Strings[70384]="指挥官。我随时听候你的差遣。$B$B你还有别的命令吗？"
D.Strings[70385]="噢，太好了，你来了，$n。"
D.Strings[70386]="你竟敢干扰我的工作！我要把你尖叫的灵魂送入彼岸的世界！"
D.Strings[70387]="$n摆出了一桌千水鱼宴。快来享用吧！"
D.Strings[70388]="什么？你是怎么找到我睡觉的地方的？！"
D.Strings[70389]="我能进去了吗？"
D.Strings[70390]="幻象指引着我们，$n。让我们看看它想告诉我们什么吧。"
D.Strings[70391]="先知，我们正在溃败！"
D.Strings[70392]="我听说它跟鸡肉的味道差不多，我才不吃生肉呢。"
D.Strings[70393]="她可能会出现回火的状况，但别担心。她会把你送到地方的。"
D.Strings[70394]="只要我还活着，卡拉波就不会陷落！"
D.Strings[70395]="没用的，先知。看看钢铁部落的真正实力吧！所有火炮......开火！"
D.Strings[70396]="钢铁部落的实力超乎你的想象！每一餐都是盛宴，每一件战利品都是财富！我们是不可战胜的，我们的荣耀永无止境！"
D.Strings[70397]="入侵者又来了！"
D.Strings[70398]="格罗玛什带领我们在两个世界取得了无数胜利。只要有战歌氏族带头，我们怎么可能失败？战歌氏族和钢铁部落的同盟是战无不胜的！"
D.Strings[70399]="纳格兰的平原上确实遍布着敌人和荣耀。但这对你们的酋长来说远远不够，他将许给你们整个德拉诺。快加入钢铁部落，见证两个世界的真正荣耀吧！"
D.Strings[70400]="带着圣光之力，勇敢地战斗吧，$n！"
D.Strings[70401]="我们是对抗黑暗的屏障！"
D.Strings[70402]="希望才是最强大的力量！"
D.Strings[70403]="欢迎来到影月谷。我一直在等你。"
D.Strings[70404]="我们是对抗黑暗的光明，是弱者的保护伞，是绝望者的希望！"
D.Strings[70405]="不要动摇！有光的地方就有希望。战斗吧！"
D.Strings[70406]="伊瑞尔，我最有潜力的学生回来了。请你带领这些朋友们前往影月废墟。"
D.Strings[70407]="我会在路上向你解释一切的。"
D.Strings[70408]="好的，导师。$n，快骑上那头雷象吧，我们这就出发。"
D.Strings[70409]="你跟我来！"
D.Strings[70410]="你即将面对的挑战可不简单，$n。你肯定会失去一些最最信赖的伙伴。当黑暗来临，我们更要坚定地追随圣光之道。"
D.Strings[70411]="我们得尽快在影月谷建立一个据点。在这里附近就有一块非常合适的空地。"
D.Strings[70412]="荣耀与牺牲！"
D.Strings[70413]="不要问钢铁部落能为你们做什么，而要问你们能为钢铁部落做什么。有了你们的帮助，钢铁部落就能横扫整片大陆，统治世间万物！"
D.Strings[70414]="或许你们会害怕硝烟和火光。但我要告诉你们，这些都不可怕！我们的护甲坚不可摧！我们的武器所向披靡！我们的工业之火将使你们成为有史以来最伟大的战士！"
D.Strings[70415]="追随钢铁部落，你们将获得数不清的荣耀！钢铁部落的敌人强大而危险。但这都没什么好怕的！强大的敌人只会让我们变得更强，我们或许会受伤，但绝不会倒下！绝不！"
D.Strings[70416]="快！我没法让它一直开着！"
D.Strings[70417]="杀了这头畜生一定能赢得卡拉波护卫的尊重。"
D.Strings[70418]="标记出那些树木，剩下的就交给雪莉的伐木工吧。"
D.Strings[70419]="巨大的杀人渡鸦……我预感这将是一个漫长而寒冷的夜晚。"
D.Strings[70420]="<低语>小声点！"
D.Strings[70421]="指挥官。让我们的游侠好好教训一下战歌氏族怎么样？"
D.Strings[70422]="愿圣光宽恕我。我辜负了他们。"
D.Strings[70423]="看来我们所需要的材料已经备齐了。让我们开始建造要塞吧。"
D.Strings[70424]="Throm-ka，指挥官。"
D.Strings[70425]="指挥官$n来了！敬礼！"
D.Strings[70426]="Lok'tar，指挥官！"
D.Strings[70427]="愿为您效劳，指挥官$n。"
D.Strings[70428]="求求你，放过我们吧。我们没有伤害过任何人。"
D.Strings[70429]="至少放过伊塞尔吧。她只是个孩子。"
D.Strings[70430]="我们从没伤害过你们。我们一直相处得很融洽。"
D.Strings[70431]="我只想带着我的女儿离开。我们不会威胁到你们的。"
D.Strings[70432]="或许我可以跟你们的首领谈谈？解释一下？你会明白的，放了我们是不会有问题的。"
D.Strings[70433]="如果你敢伤害我的孩子，我一定会杀了你！"
D.Strings[70434]="你这个怪物，竟然威胁手无寸铁的妇孺！"
D.Strings[70435]="求你了。放过我们吧！"
D.Strings[70436]="有什么指示吗，指挥官？"
D.Strings[70437]="欢迎，指挥官$n。能为您效劳是我的荣幸。"
D.Strings[70438]="指挥官来了！伙计们，各就各位！"
D.Strings[70439]="碎手氏族灭绝人性的罪行不可宽恕，我们不能违心地无视他们的罪行。"
D.Strings[70440]="|TInterface\\Icons\\ability_paladin_beaconoflight.blp:20|t你获得了|cFFFF0000|Hspell:160972|h[卡拉的精华]|h|r的祝福！"
D.Strings[70441]="卡德加想让我们探查一下那座洞穴。"
D.Strings[70442]="如果我们能活着走出这片丛林，我会亲自监督，确保你和你的人民得到妥善的安置。"
D.Strings[70443]="|TInterface\\Icons\\spell_holy_aspiration.blp:20|t卡拉使用|cFFFF0000|Hspell:149699|h[卡拉之仁]|h|r祝福了你！"
D.Strings[70444]="|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t你获得了|cFFFF0000|Hspell:157035|h[卡拉之韧]|h|r的祝福！"
D.Strings[70445]="噢，感谢圣光把你送来这里，陌生人！"
D.Strings[70446]="战歌氏族毫无征兆地袭击了我们。"
D.Strings[70447]="来吧，伊塞尔。我们一定要保持安静。"
D.Strings[70448]="你成功了，$n！现在，快去阻止这场突袭吧！"
D.Strings[70449]="好的，妈妈。谢谢你，$g先生:女士;！"
D.Strings[70450]="如果我要被遗忘在此处，那么你也跑不了。"
D.Strings[70451]="不！你会像我一样被世人遗忘！"
D.Strings[70452]="我……还会……回来的……"
D.Strings[70453]="你愿意帮助我吗，$c？我的许多同胞们都牺牲了，因为我没能保护好他们。"
D.Strings[70454]="审讯者克安的遗体就在你面前。"
D.Strings[70455]="你拿到蛋了吧？它们得马上被放入孵化器，所以我就带着它们先走一步了。愿圣光给你恩泽。"
D.Strings[70456]="那些可怕的怪物突然冒了出来，并开始屠杀幼龙！$b$b如果我们袖手旁观的话，它们会被杀光的！$b$b如果你可以干掉那些攻击幼龙的怪物，并帮我收集一些它们掉落的龙蛋，那就再好不过了。$b$b拜托了，$c，我是唯一幸存的护蛋者了，我需要你的帮助才能让这些幼龙活下去！"
D.Strings[70457]="别碍我的事。"
D.Strings[70458]="我是不可战胜的！"
D.Strings[70459]="这真是太有意思了！"
D.Strings[70460]="你！你伤害了头儿！"
D.Strings[70461]="该执行B计划了！"
D.Strings[70462]="蠢货！我可以沟通超出你想象的力量！"
D.Strings[70463]="救命！！"
D.Strings[70464]="战歌兽人正试图激活下面那个塔拉的防护水晶。如果他们成功了，我们就没法支援你了。"
D.Strings[70465]="战歌兽人正试图激活塔拉的防御护盾。如果他们成功了，岗哨的游侠就没法支援你了。"
D.Strings[70466]="雪？我们的萨满说过今天会很暖和的……我可不相信那些云。"
D.Strings[70467]="东侧城墙附近发现入侵者！"
D.Strings[70468]="我们得快一点——这些影月兽人都听命于一个叫“耐奥祖”的首领。"
D.Strings[70469]="干掉了他的指挥官之后，耐奥祖肯定会来找我们的。"
D.Strings[70470]="我来对付右翼，玛尔拉德对付左翼，你保护卡拉！"
D.Strings[70471]="我和这位助祭去召集其他队友。你一定竭尽全力阻止那个兽人开启传送门！"
D.Strings[70472]="我们会带着援军回来的。"
D.Strings[70473]="我要杀光你们！"
D.Strings[70474]="你们谁先来？"
D.Strings[70475]="想送死吗？那你就来对地方了，小子。"
D.Strings[70476]="别害羞。我有的是精神呢。"
D.Strings[70477]="别担心，我会一个一个杀光你们的。"
D.Strings[70478]="你们把幸存者都藏在哪儿了，畜生？"
D.Strings[70479]="如果你们敢动她一根头发，我一定会让你们痛苦地死去活来！"
D.Strings[70480]="守备官……审讯者，能听到吗？我来了。"
D.Strings[70481]="西门附近发现入侵者！"
D.Strings[70482]="再次感谢你的帮助。幸运的是，我已经把那些蛋放进孵化器了。$b我真希望自己能再强一点，那我就拿起武器出去伸张正义了，可惜……照看这些龙蛋就是我全部的本事了。\n请找出这场混乱的源头，并解决它。我和这些灵龙就全靠你了！"
D.Strings[70483]="我应该没事……只是扭到了蹄子。"
D.Strings[70484]="我才不跳呢！快去找架梯子来！"
D.Strings[70485]="不可能！这太远了！我说真的……快去找架梯子来！"
D.Strings[70486]="你不会有事的。大胆跳吧！"
D.Strings[70487]="没有那么远的。来吧，快跳！"
D.Strings[70488]="多年来，我一直致力于驯化这些温顺的生物。$b你瞧，它们非常聪明。如果有更多的年轻人愿意来学习与它们沟通的精妙技艺，我们一定可以从它们身上学到很多东西。$b$b<阿洛隆叹了口气。>$b$b要是这世道再太平一点，我就可以把我的本事教给其他人了。但我们恐怕还有更紧急的问题要处理。"
D.Strings[70489]="我帮你教训过他们了。"
D.Strings[70490]="咳……我有点虚弱。你自己能搞定吗？我得回岗哨去了。"
D.Strings[70491]="不……不！这绝不会是德莱尼的命运！"
D.Strings[70492]="是耐奥祖导演了这场悲剧。为了拯救卡拉波，我们必须阻止他。"
D.Strings[70493]="回暮光林地来找我吧，勇士。我们有许多事要做。"
D.Strings[70494]="<剑柄刻着一行铭文：>\n\n“为了平息古树的怒火，守备官托瓦斯战殁于此。\n\n 愿圣光照耀着他拼死守护的这片树林，并为它的住民带来永久的和平。”"
D.Strings[70495]="<水面开始波动。>"
D.Strings[70496]="珀西！你就不能安静点吗？！你这么飞来飞去的，我还怎么读东西？"
D.Strings[70497]="你来拖住使者，我们就先溜了。我们在镇子外面的桥那里见！"
D.Strings[70498]="走了，珀西！"
D.Strings[70499]="乌瑞恩堡的居民们，你们的指挥官又建成了一座新建筑！"
D.Strings[70500]="我们得齐心协力才能让产量达到最大。别让指挥官久等了！"
D.Strings[70501]="我……挡不住……他们……"
D.Strings[70502]="哟，各位，听好了。感谢我们的指挥官，我们又建好了一座新建筑！"
D.Strings[70503]="我们得赶快把这座新建筑造好，明白吗？工期昨天就该到了！"
D.Strings[70504]="我相信你能搞定接下来的事。干得好！"
D.Strings[70505]="你已经不需要我了，毕竟你才是这里的头儿。"
D.Strings[70506]="和你并肩作战是一种荣幸，$n。"
D.Strings[70507]="他们的堕落让我感到恶心。$b$b我们应该彻底抹杀这个钢铁部落。"
D.Strings[70508]="我带这个德莱尼回去见卡德加。你一定要阻止那个兽人开启传送门！"
D.Strings[70509]="古树开始苏醒了！"
D.Strings[70510]="第二棵古树加入了战斗！"
D.Strings[70511]="第三棵古树开始攻击！"
D.Strings[70512]="喝下药水，把精神集中在水晶上。将自己浸入时间的潮汐…… "
D.Strings[70513]="我有你要的东西，指挥官。你迟早会来求我的。战歌兽人，去找到$g他:她;！"
D.Strings[70514]="啊哈哈。有本事的话，就快来拿你的宝贝图纸啊！"
D.Strings[70515]="去吧，$n，去干掉它，为塔拉的死难者伸张正义吧。"
D.Strings[70516]="干得好，指挥官！"
D.Strings[70517]="我们会尽力多运一些矿石出去的，但这些城墙可能需要加固一下。"
D.Strings[70518]="这地方看起来相当衰败。"
D.Strings[70519]="我要这座护盾包围住整个塔拉，马上。"
D.Strings[70520]="快去找到入侵者和那些该死的游侠。"
D.Strings[70521]="不用再抓俘虏了。杀光外来者！"
D.Strings[70522]="战咏者们，再加点能量。只要德莱尼的护盾包围住整个塔拉，就没人能冲进来了。"
D.Strings[70523]="我们将德莱尼赶出了我们的家园。今天是战歌氏族最光荣的日子。"
D.Strings[70524]="再快点！我马上就要赶去塔拉岗哨！"
D.Strings[70525]="很快，我们就会碾碎那些德莱尼幸存者。为了战歌氏族！"
D.Strings[70526]="加兹鲁维说：“快穿过传送门，你会发财的。”$B$B他真是画了好大一块饼啊。"
D.Strings[70527]="$n制造了一根防御棱柱！"
D.Strings[70528]="$n制造了一件炎阳法器！"
D.Strings[70529]="|TInterface\\Icons\\inv_feather_14.blp:20|t鲁克兰射出一大蓬|cFFFF0000|Hspell:159382|h[飞羽]|h|r，快隐蔽！"
D.Strings[70530]="|TInterface\\Icons\\inv-mount_raven_54.blp:20|t鲁克兰的近战范围内没有敌人，开始施放|cFFFF0000|Hspell:153896|h[尖啸]|h|r，快攻击鲁克兰，打断它的尖啸！"
D.Strings[70531]="为了战歌氏族！"
D.Strings[70532]="为了加尔鲁什！"
D.Strings[70533]="纳格兰属于战歌氏族。"
D.Strings[70534]="嘿，头儿！我们这儿有点要紧事需要你处理一下。"
D.Strings[70535]="能量缓冲器激活。正在重启核心系统。请等待。"
D.Strings[70536]="好了，欢乐机器人8000。快回去干活！"
D.Strings[70537]="你获得了纳鲁的赐福！快杀出庭院，我们在港口那里见！"
D.Strings[70538]="我知道这地方有多危险，但在拿回属于我的东西之前，我是不会走的！"
D.Strings[70539]="你看来是个出色的渔夫，你能帮我们一个忙吗？\n\n我们在附近建了一座小要塞，但在部队供养方面遇到了点困难。如果你能给我们一些捕鱼方面的建议，那就是帮了我们大忙了。"
D.Strings[70540]="天知道我们能用这个世界的材料发明出什么东西来？"
D.Strings[70541]="好了，欢乐机器人8000。执行X47G5号指令！"
D.Strings[70542]="我能帮你什么忙吗，指挥官？"
D.Strings[70543]="卡德加的魔法的确很强大。他打开了一座直通暴风城的永久性传送门。"
D.Strings[70544]="一切都在按计划进行，指挥官。我能帮你什么忙吗？"
D.Strings[70545]="在击败这头巨兽之后，肃清这一地区就再无阻碍了。"
D.Strings[70546]="要我说的话，选择伐木场是最明智的决定了。"
D.Strings[70547]="干得不错，指挥官。没有了这些到处乱飞的杀人怪鸟，我晚上就能睡得更好了。"
D.Strings[70548]="你想开始建造的时候，就告诉我一声，指挥官。"
D.Strings[70549]="多亏了你，我们在影月谷建起了一座了不起的要塞。"
D.Strings[70550]="巴隆斯就在阶梯下面。我想他会更乐意帮你建造兵营的。"
D.Strings[70551]="营房造好之后，我们的部队在这漫漫长夜里总算有一个栖身之所了。"
D.Strings[70552]="奇娅娜刚刚去月花谷了。她已经等不及想要探索这片全新的土地了。"
D.Strings[70553]="我帮忙了！你看见没有？"
D.Strings[70554]="那只是凑巧！"
D.Strings[70555]="我们把战利品分了吧！六四开怎么样？"
D.Strings[70556]="你是不是又有钱又有名？如果是的话，那我长大以后也要像你一样！"
D.Strings[70557]="快去看看有没有战利品！"
D.Strings[70558]="你能教我战斗吗？"
D.Strings[70559]="下一个让我来！看好了！"
D.Strings[70560]="请把我改造得更强大！"
D.Strings[70561]="我觉得那条胳膊还能用，没准还有那条腿。"
D.Strings[70562]="你无法战胜我！"
D.Strings[70563]="我要消灭你。"
D.Strings[70564]="我能感受到它在我的灵魂中。"
D.Strings[70565]="想想我能用你的零件做出多少东西吧。"
D.Strings[70566]="但愿这些残肢不要损坏得太严重。"
D.Strings[70567]="好多残肢！"
D.Strings[70568]="别想跑，你会累死的。"
D.Strings[70569]="我要抓住你，我要修理你。"
D.Strings[70570]="那个！那正是我需要的！"
D.Strings[70571]="我能感觉到邪恶的污物在我体内流淌。"
D.Strings[70572]="嗯？一次报复性袭击？斥候，拉响警钟！让工人们都进来！"
D.Strings[70573]="拿起武器！各就各位！让雷神氏族看看部落的实力！"
D.Strings[70574]="中士，雷神兽人攻上城墙了！"
D.Strings[70575]="你竟敢挑战强大的斯库戈？！"
D.Strings[70576]="我们都是从小人物成长起来的。我就是从艾尔文森林的一座修道院里走出来的。"
D.Strings[70577]="我们都是从小人物成长起来的。我的人生就是从埃索达的废墟里起步的。"
D.Strings[70578]="我们都是从小人物成长起来的。我曾经只是神真子背上的一名学徒。"
D.Strings[70579]="我们都是从小人物成长起来的。我的旅途开始于泰达希尔的宁静枝桠之下。"
D.Strings[70580]="我们都是从小人物成长起来的。我的故事开始于吉尔尼斯的街头。"
D.Strings[70581]="没有我这样的兽人提供后勤补给，什么军队都运转不了。"
D.Strings[70582]="发出嗜血尖叫的观众开始大肆破坏竞技场$B$B x2 喝醉的投毒者|TInterface\\Icons\\achievement_reputation_ogre.blp:32|t x5 钢铁投弹手 |TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70583]="渴望杀戮的观众开始叫嚣着来一场大屠杀。$B$B x3 喝醉的投毒者|TInterface\\Icons\\achievement_reputation_ogre.blp:32|t x5 钢铁投弹手 |TInterface\\Icons\\achievement_character_orc_male_brn.blp:32|t"
D.Strings[70584]="你不能任由他们遭受这种命运。如果我们今天抛弃自己的朋友，那我们就跟耐奥祖一样坏了。"
D.Strings[70585]="最重要的不是会不会死，而是我们要怎么活下去。你想怎么活下去，伊瑞尔？"
D.Strings[70586]="如果你在这里放弃，你的战友们就白白牺牲了。让他们的牺牲鼓舞你吧。"
D.Strings[70587]="你说的很对，$n。萨玛拉和其他人全指望我们了。为了他们，我要活下去！"
D.Strings[70588]="我要活下去，守护正义，保护无助和绝望的人们。你真是个睿智的导师，$n。"
D.Strings[70589]="我们这就动手吧。"
D.Strings[70590]="我们都是从小人物成长起来的。我曾是巫妖王的手下。"
D.Strings[70591]="嘿！嘿！等一等！"
D.Strings[70592]="你是来对付刃牙虎人的吗？我需要你的帮助！"
D.Strings[70593]="拜托了，你一定要帮帮我！"
D.Strings[70594]="你想要什么？金钱？权力？只要你帮我一把，我什么都给你！"
D.Strings[70595]="别担心，我能照顾好自己，但你得帮我拿回我的东西！"
D.Strings[70596]="你随意吧，我就待在这里……等……下一个人……等到死。"
D.Strings[70597]="你不会把我丢在这里的……吧？"
D.Strings[70598]="你肩上的重任太多了！你根本想不到后果！"
D.Strings[70599]="锤打"
D.Strings[70600]="你以为自己能打败巫王的弟子？哈！"
D.Strings[70601]="敢阻止我的研究？就让你们看看我的研究成果吧！来认识一下我的最新造物——布尔高！"
D.Strings[70602]="回去干活，头儿。"
D.Strings[70603]="指挥官救了我。我是快活的兽人！"
D.Strings[70604]="好好看看这些图纸吧，指挥官。"
D.Strings[70605]="我还以为自己死定了！"
D.Strings[70606]="老虎人想要吃我！"
D.Strings[70607]="你找到了！罗克西火箭手套……炸弹美人……它们全都在！"
D.Strings[70608]="我的宝贝……"
D.Strings[70609]="专业技能建筑图纸"
D.Strings[70610]="那么，头儿，你想造哪个？记住，只有第一个是免费的。"
D.Strings[70611]="噢，指挥官，你最近还真忙啊。想来一杯清凉的饮料吗？或者一把锋利的长剑？"
D.Strings[70612]="只有一个办法能向我证明你的价值，陌生人。$B$B那就是战斗。"
D.Strings[70613]="啊，甜蜜的自由！你不会后悔的，指挥官。我会为你制造出全德拉诺最好的武器！"
D.Strings[70614]="来看看我们有些什么材料。"
D.Strings[70615]="熔炉是铸造厂的灵魂。这个熔炉有点小，但只要有合适的设备，我就能改进它。"
D.Strings[70616]="这些看起来还不错，只要稍稍改装一下，我就可以把它们装进火炮里发射了。"
D.Strings[70617]="你向我证明了自己。"
D.Strings[70618]="你想亲眼看一看奥金顿？$B$B那就用战斗向我证明你的资格吧。"
D.Strings[70619]="我投降！你的确有这个资格。你拥有纯洁的灵魂。"
D.Strings[70620]="愿你得到安息。"
D.Strings[70621]="我是不会死在前线的。我还要继续在悬槌堡的研究！享受你们短暂的胜利吧……"
D.Strings[70622]="嘘！别让他们看见我们说话，否则你会拆穿我的伪装的！"
D.Strings[70623]="我需要一件影月兽人伪装。"
D.Strings[70624]="伪装可以一直维持到你完成任务。$B$B但魔法是善变的！$B$B拿上我的幻影护符。如果你在沙兹古尔弄丢了伪装，那就使用护符。"
D.Strings[70625]="小心沙兹古尔里那些巡逻的狼。伪装能骗过眼睛，但骗不过它们的鼻子。"
D.Strings[70626]="有什么任务吗？"
D.Strings[70627]="我来看看，能不能让这个家伙动起来。卡德加，帮我争取点时间！"
D.Strings[70628]="我们会尽力的，塞林。"
D.Strings[70629]="$n，别让那些兽人靠近我们！"
D.Strings[70630]="坦克冲上高地了！小心！"
D.Strings[70631]="这些控制板完全没有条理！下次记得提醒我，再也别驾驶兽人造的坦克了。"
D.Strings[70632]="坚持住，各位。他们过来了！"
D.Strings[70633]="他们带着炸弹！$n，炸掉那些车，别让它们靠近！"
D.Strings[70634]="敌人太多了……"
D.Strings[70635]="别放弃，圣骑士。"
D.Strings[70636]="成了！我把它发动起来了！让我们结束这一切吧。"
D.Strings[70637]="我们受到召唤前来保护奥金顿不受进一步的骚扰。"
D.Strings[70638]="只有证明自己灵魂纯洁的人才能进入。"
D.Strings[70639]="我这就过去了，谢谢你！"
D.Strings[70640]="Throm-Ka，指挥官。$B$B很高兴你能来。我需要你来接管击溃战歌氏族的筹备工作。$B$B我们会正面打垮他们，并将加尔鲁什绳之以法。"
D.Strings[70641]="你……没有……资格！"
D.Strings[70642]="没有资格。"
D.Strings[70643]="大门不会开启！"
D.Strings[70644]="嘿，$c！你是这儿的头吧？快让你的走狗放我出去！"
D.Strings[70645]="你有没有检查过这个笼子？它都快散架了！放我出去，我来让你看看怎么才能关住一个足以挡住暴怒的裂蹄牛的强者。"
D.Strings[70646]="嘿，快把我弄出去！"
D.Strings[70647]="我怀念塔拉，但见到你总能让我感到欣慰，指挥官$n。$B$B愿纳鲁照亮你的道路。"
D.Strings[70648]="血肉烧焦了。"
D.Strings[70649]="|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t卡拉的能量几近全满并获得了|cFFFF0000|Hspell:161045|h[卡拉的防护]|h|r！"
D.Strings[70650]="哦呵呵——漂亮的一击！"
D.Strings[70651]="击杀首领！"
D.Strings[70652]="战歌兽人都是可靠的战士！你们已经将纳格兰抓在了手掌心里！战歌勇士的加入将是钢铁部落的荣幸。当你们为钢铁部落驰骋疆场时，全德拉诺都将在战歌氏族的威名下瑟瑟发抖！"
D.Strings[70653]="噢，呵呵呵，你这个可爱的小蝌蚪。告诉我，你喜欢青蛙吗？"
D.Strings[70654]="其他人都不相信我，可我真的看见“他”了。伟大的蛙神。只要被他看上一眼，你就会脱胎换骨！"
D.Strings[70655]="呱……呱……呱……听听它们的叫声！我最喜欢听它们说话了。"
D.Strings[70656]="就算我要死，也得拉上十个垫背的！"
D.Strings[70657]="你喝过青蛙汤吗，亲爱的？非常美味，而且对你的身体有好处。"
D.Strings[70658]="噢，我最喜欢它们可爱的小肚子和滑溜溜的小脚趾了，你呢？"
D.Strings[70659]="死吧，软蛋！"
D.Strings[70660]="倒在强大的钢铁部落脚下吧！"
D.Strings[70661]="钢铁部落需要矿石，而你们碍了我们的事！"
D.Strings[70662]="就算是石头，我也要榨出矿来！"
D.Strings[70663]="我的枪百发百中，我的剑所向披靡！"
D.Strings[70664]="老托格罗克已经把几百个你这样的家伙送下地狱了！去跟他们做伴去吧！"
D.Strings[70665]="在基地中央遭到攻击？！我得把这事告诉巫王大人！"
D.Strings[70666]="我可不是钢铁部落的废物。你面前的是巫王大人亲手训练出来的强者！"
D.Strings[70667]="你们的努力毫无意义！你和你的盟友很快就要完蛋了！"
D.Strings[70668]="你以为杀了我，战歌氏族就不会加入钢铁部落了吗？我在这里的使命已经完成了，战歌氏族会进一步壮大的钢铁部落的队伍！"
D.Strings[70669]="杀了你一定可以让征兵变得更加容易，我甚至都不用刮花自己的护甲。"
D.Strings[70670]="拜托，图丽娅，快醒醒。求求你……你一定要醒过来……"
D.Strings[70671]="上啊，头儿！杀了那个猫人！"
D.Strings[70672]="嘿，猫人！你真臭！"
D.Strings[70673]="这会儿怎么不逞强了啊，猫人？"
D.Strings[70674]="喔！踢爆他的屁股！"
D.Strings[70675]="猫人？看上去更像侏儒的情人！"
D.Strings[70676]="尝尝这个！再尝尝这个！"
D.Strings[70677]="就这样！干掉他！"
D.Strings[70678]="你是不败的神话！"
D.Strings[70679]="谢了，头儿！回去干活儿咯！"
D.Strings[70680]="那些肮脏的刃牙虎人是跑不了的……没有人能在偷了热砂港的东西之后逍遥法外！$b$b没有！"
D.Strings[70681]="试炼竞技场是个赚钱的好地方！"
D.Strings[70682]="你敢惹农夫，头儿来对付你了！"
D.Strings[70683]="我相信你一定会赢的！"
D.Strings[70684]="你会后悔的，怪物。我用我的妈妈起誓！"
D.Strings[70685]="杀了他，指挥官！"
D.Strings[70686]="你就像个耀武扬威的地精！"
D.Strings[70687]="你能行的！"
D.Strings[70688]="伊塞尔，别走远了。"
D.Strings[70689]="就呆在这儿，年轻的小姐。"
D.Strings[70690]="快点回来，伊塞尔。"
D.Strings[70691]="伊塞尔，回来！"
D.Strings[70692]="别到围墙外面去。"
D.Strings[70693]="别走得太远了，伊塞尔。"
D.Strings[70694]="跟紧我，这里已经不再安全了。"
D.Strings[70695]="你的家务做完了吗？"
D.Strings[70696]="噢，妈妈。"
D.Strings[70697]="嗯哼，好的。"
D.Strings[70698]="马上就回来。"
D.Strings[70699]="我不是小孩子了！"
D.Strings[70700]="我都收拾干净了。你答应过的！"
D.Strings[70701]="别担心。我不会到门外去的。"
D.Strings[70702]="这里太无聊了！"
D.Strings[70703]="呃，真是孩子气。"
D.Strings[70704]="听话，年轻的小姐。"
D.Strings[70705]="别去打扰那些守卫。"
D.Strings[70706]="我真希望她至少能听一次话。"
D.Strings[70707]="她长得太快了。"
D.Strings[70708]="还有，不准去钓鱼。"
D.Strings[70709]="我是认真的，小鬼头，注意安全。"
D.Strings[70710]="伊塞尔皱了皱眉头。"
D.Strings[70711]="伊塞尔！"
D.Strings[70712]="求求你，我的家人都在挨饿。"
D.Strings[70713]="怎么了，小猫咪？不喜欢鞭子吗？"
D.Strings[70714]="冒险者，给几个小钱吧。"
D.Strings[70715]="指挥官萨贝克，你的部下好像放进来一群可悲的英雄。"
D.Strings[70716]="伊塞尔叹了口气。"
D.Strings[70717]="伊塞尔的脸上闪过一丝失望。"
D.Strings[70718]="年轻的小姐转动着眼珠。"
D.Strings[70719]="伊塞尔摇了摇头。"
D.Strings[70720]="伊塞尔皱了皱鼻子。"
D.Strings[70721]="女孩夸张地呼出一口气。"
D.Strings[70722]="伊塞尔踢了踢地上的土。"
D.Strings[70723]="我对这次失误深感抱歉，督军扎伊拉。我的铁军会解决这些入侵者的！"
D.Strings[70724]="铁军，杀了他们，否则你们就等死吧！"
D.Strings[70725]="杀了穿那件衣服的人！"
D.Strings[70726]="为什么？！我要杀了他们……我要杀光他们！！"
D.Strings[70727]="或许你会喜欢跟我的小宠物住在一个笼子里！"
D.Strings[70728]="你没看见我正在招待“贵”客吗？！！"
D.Strings[70729]="你们来救这只可怜的残废猫？我或许是该换一批宠物了！"
D.Strings[70730]="这边走，朋友。结界已经快要充能完毕了。"
D.Strings[70731]="我们会将这些水晶共振发生器埋进地里，利用德拉诺的能量来为我们的防御护盾提供能量。"
D.Strings[70732]="|TInterface\\Icons\\ability_warrior_shieldguard:20|t%s正准备施放|cFFFF0000|Hspell:158136|h[盾牌冲锋]|h|r！"
D.Strings[70733]="|TInterface\\Icons\\ability_whirlwind:20|t%s正准备施放|cFFFF0000|Hspell:157943|h[旋风斩]|h|r！"
D.Strings[70734]="我们不能就这么逃跑，任由这些野蛮人榨干同胞的鲜血。我们必须阻止他们！"
D.Strings[70735]="很好，但别太久了。我稍后还要用到你们俩，你们一定要活下来。"
D.Strings[70736]="毫无疑问，她很漂亮。我们真是最佳搭档，$n。$B$B现在，一起去打垮战歌氏族吧！"
D.Strings[70737]="没时间偷懒了！$B$B等这个小美人儿造好之后，我们就要去打垮战歌氏族和一切碍事的家伙。"
D.Strings[70738]="兽栏建造完毕。是时候好好利用它，让正义在纳格兰得到伸张了。"
D.Strings[70739]="坦克工厂建造完毕。是时候好好利用它们，让正义在纳格兰得到伸张了。"
D.Strings[70740]="我们要齐心协力，制裁加尔鲁什和战歌氏族。"
D.Strings[70741]="嘿，头儿！要不要休息一下？"
D.Strings[70742]="来吧，科达娜！"
D.Strings[70743]="让我们过去，守门者。"
D.Strings[70744]="很好，指挥官，但入侵者好像还是活蹦乱跳的。"
D.Strings[70745]="什么？这真是不可容忍！"
D.Strings[70746]="杀了他们，你们这群蠢货！"
D.Strings[70747]="普罗德摩尔女士已经明令禁止部落成员进入肯瑞托的范围。"
D.Strings[70748]="我正打算组建一支小队去侦察敌人的防御工事。"
D.Strings[70749]="那就让吉安娜自己来跟我理论吧。我也是议会成员，让我和我的朋友过去！"
D.Strings[70750]="我的法师塔就在这条小路的尽头。"
D.Strings[70751]="萨尔，你来率领剩余的幸存者，到前面去跟我们汇合。"
D.Strings[70752]="玛尔拉德，你来率领剩余的幸存者，到前面去跟我们汇合。"
D.Strings[70753]="钢铁部落对武器的质量和工艺毫不关心。他们只能靠粗笨的体积来弥补钢材的粗劣。$b$b真可悲。"
D.Strings[70754]="好的，大法师。"
D.Strings[70755]="<这头骡子用大而衰老的眼睛看着你……接着又嚼了嚼你的衬衣。>"
D.Strings[70756]="好吧，大法师，如你所愿。"
D.Strings[70757]="这附近很难找到好的食材。"
D.Strings[70758]="这真是太难看了！你的人都不知道斧子的刃开在哪一边吗？"
D.Strings[70759]="我也搞不懂，这些入侵者就像被愤怒的格罗玛什附体了一样能打。"
D.Strings[70760]="在上面！快看！"
D.Strings[70761]="愿祖先保佑我们……快看！"
D.Strings[70762]="我已经听够这些借口了。我去准备武器，马上干掉这些入侵者，否则我就让你看看真正的兽人是怎么处理失败者的。"
D.Strings[70763]="你准备好之后，就通过这个传送门进入我的法师塔吧。"
D.Strings[70764]="%s被鲜血的气味吸引了！"
D.Strings[70765]="遵命，督军大人！我会亲自解决那些家伙的！"
D.Strings[70766]="牵我的坐骑来，我不想再看到你们这些苦力让我的钢铁部落蒙羞了。"
D.Strings[70767]="够了！我在督军大人面前丢尽了脸，你们要为此付出代价！"
D.Strings[70768]="督军大人，我……辜负了你。"
D.Strings[70769]="现在，让我们来做个了断吧。"
D.Strings[70770]="督军扎伊拉！我夺回了自己的荣耀！"
D.Strings[70771]="你的朋友们很快就会来陪你的！"
D.Strings[70772]="你是怎么走到这里的？"
D.Strings[70773]="我知道该怎么做了。"
D.Strings[70774]="鲜血与荣耀！"
D.Strings[70775]="基尔罗格·死眼"
D.Strings[70776]="血环氏族督军"
D.Strings[70777]="看看是什么穿过我的丛林送上门来了。新鲜的肉！"
D.Strings[70778]="我们是不会不战而退的，死眼。"
D.Strings[70779]="看来你需要帮忙。"
D.Strings[70780]="不！你的对手是我！"
D.Strings[70781]="去……找到……卡德加……"
D.Strings[70782]="我的朋友就在前面。"
D.Strings[70783]="保护我，我来打破包围圈，$n！"
D.Strings[70784]="啊，你来了！这就是我跟你说起过的那个人。"
D.Strings[70785]="你们这些蠢货！你们能把地雷丢进海港里？！"
D.Strings[70786]="我应该出去跟白色海怪号拼命的，现在却只能在这里收拾这个烂摊子！快多派点兽人下来！"
D.Strings[70787]="要是明天天亮之前还不能清理掉那些地雷，我发誓我一定会炮轰港口！"
D.Strings[70788]="很好。相信我很快就会再见到你们俩的。"
D.Strings[70789]="我是魔导师克雷拉斯。幸会。那就让我们开始吧，好吗？"
D.Strings[70790]="沃尔卡正在登陆，快干掉他，阻止他对卡拉波的狂轰滥炸！"
D.Strings[70791]="非常好！接下来的事就交给我吧。"
D.Strings[70792]="普罗德摩尔女士有令，外来者禁止入内。"
D.Strings[70793]="我是加总本次探险之旅的左膀右臂。像加总这样的天才是不屑理会那些日常琐事的。$b$b我的责任就是打理好一切，让他能够集中精力处理那些大事！"
D.Strings[70794]="太好了！谢谢你，大法师。剩下的事就交给我吧。"
D.Strings[70795]="热砂保护协会的创会宗旨就是保护艾泽拉斯和德拉诺的珍贵遗物和古董。$b$b我们远赴各地，寻找最珍贵的遗物！$b$b我们的任务就是让这些无价之宝找到最好的归宿……也就是价高者得！"
D.Strings[70796]="我想分解一些旧装备。"
D.Strings[70797]="精华之泉可以将武器和护甲分解成附魔材料。分解后的物品将被永久摧毁。\n\n确定要继续吗？"
D.Strings[70798]="耶！谢谢！谢谢！谢谢！太谢谢你了！"
D.Strings[70799]="我还以为大家都把我忘了呢，谢谢你，好心的$G先生:女士;！"
D.Strings[70800]="哇，你把那些兽人都打跑了？你真厉害！"
D.Strings[70801]="<小女孩嚎啕大哭着。>"
D.Strings[70802]="让我们开始吧！"
D.Strings[70803]="帮帮我！我动不了了！"
D.Strings[70804]="大地母亲在上，这片土地无时无刻不在考验着我们！"
D.Strings[70805]="就是这样，伙计们，从现在开始，我们要罢工！"
D.Strings[70806]="%s登陆了。快攻击他！"
D.Strings[70807]="这些狂暴的元素威胁到了工人的安全。合同上可没有这一条！"
D.Strings[70808]="要是弗兹万格勒还想完成岩壁峡谷的挖掘工作，那就让他自己去干吧！"
D.Strings[70809]="是时候订立一份新合同了！我们要修改劳动合同！"
D.Strings[70810]="我们要更多的薪水！更多的休息时间！少一些条条框框！"
D.Strings[70811]="来吧！让我们闹点动静出来！让老弗兹万格勒知道，在得到更好的待遇之前，我们是不会再动一根指头的！"
D.Strings[70812]="弗兹万格勒上一次让我们开派对是什么时候的事了？我们要为开派对的权利而斗争！"
D.Strings[70813]="你们被侵害了！你们被剥削了！你们被蒙蔽了。你们被欺骗了！"
D.Strings[70814]="我们或许可以利用这些带能量的蘑菇。"
D.Strings[70815]="郭雅夫人已经决定将她的公司转移到利润更高的市场里去了。是时候抛弃这份吃力不讨好的工作了。"
D.Strings[70816]="真奇怪，都出了这么大的乱子了，这些古树守护者居然都不醒。"
D.Strings[70817]="如果顺利的话，那些小东西现在应该都逃跑了，我们可以开始建造了。"
D.Strings[70818]="当地的这些水域都很合适钓鱼，我们只要大胆地走出去就是了！"
D.Strings[70819]="我可以去钓鱼了吗？我很快就会带着收获回来的。"
D.Strings[70820]="是谁竟敢来挑战我？"
D.Strings[70821]="准备——！！！"
D.Strings[70822]="让他们尝尝厉害吧，小伙子们！"
D.Strings[70823]="我已经看见你了。"
D.Strings[70824]="快速射击！！！"
D.Strings[70825]="火力全开。"
D.Strings[70826]="哈！就让我们公平竞争好了。"
D.Strings[70827]="又少了一个竞争者！"
D.Strings[70828]="太弱了！"
D.Strings[70829]="无人能敌！"
D.Strings[70830]="我还没有……使出……全力呢……"
D.Strings[70831]="没人能阻止钢铁部落。没人！"
D.Strings[70832]="太好了！我们可以用这些东西制作群体传送卷轴了。"
D.Strings[70833]="我在附近看见了大量雷神兽人。他们在准备发动袭击。"
D.Strings[70834]="卡德加对你的评价很高。你已经获得了一系列的赞誉。"
D.Strings[70835]="指挥官！太好了！你能不能告诉加兹鲁维一声？如果他真的想在这块空地上打渔种田的话，那他必须找几个懂行的人来。"
D.Strings[70836]="我没想到奥术能量会……这么强。"
D.Strings[70837]="拉昆，让他们吃点苦头吧！"
D.Strings[70838]="真让人吃惊……"
D.Strings[70839]="你们休想拦下这辆列车！"
D.Strings[70840]="你们……休想……"
D.Strings[70841]="我可以马上开工，但没有图纸的话，我是造不出东西的。无论我们想做什么，图纸都是关键。"
D.Strings[70842]="火刃氏族是个高贵的氏族，但他们在这场冲突中站错了队。"
D.Strings[70843]="让他们看看你的真本事吧！"
D.Strings[70844]="加兹鲁维需要你的备用建筑材料。"
D.Strings[70845]="都给我动起来，你们这些懒骨头。该干活儿了。"
D.Strings[70846]="粗犷！这座要塞给你的感觉就是这样的吧，指挥官？不对！它太老土了！但这就是我的工作了。$b$b我们可以用这些半成品图纸建造一座拉风的建筑，比如……药剂店！对，药剂店。或者是铁匠铺或者车间。$b$b如果要使用大块空地，我们可以为你建造一座兵营，让你的部队在打击敌人归来后好好睡一觉。$b$b天马行空，创意无限就是我们的风格。"
D.Strings[70847]="指挥官，你的工人们正在等待你的指令。"
D.Strings[70848]="[%s]忏悔：要塞是什么？能吃吗？"
D.Strings[70849]="[%s]忏悔：我知道他以前是玩牧师的……"
D.Strings[70850]="[%s]忏悔：我不知道“砮皂寺”这个词怎么读。"
D.Strings[70851]="[%s]忏悔：我经常把锦绣谷和四风谷搞混。"
D.Strings[70852]="[%s]忏悔：我潜水的时候从不聊天。"
D.Strings[70853]="[%s]忏悔：我常常会想高级好运护符都去哪儿了。"
D.Strings[70854]="[%s]忏悔：我曾经在一天里做完了所有的日常任务。"
D.Strings[70855]="[%s]忏悔：我真的很想在“恰当”的时机对盟友使用信仰飞跃。"
D.Strings[70856]="[%s]忏悔：我最喜欢吹嘘自己在无主的黑市宝箱里开出过什么东西。"
D.Strings[70857]="[%s]忏悔：我都不明白怎么会那么多人知道搏击俱乐部的事。它的第一条原则……"
D.Strings[70858]="[%s]忏悔：我曾被同一只巨型蜗牛打死三次。"
D.Strings[70859]="[%s]忏悔：我曾不止一次在试炼场里故意让苏立死掉。"
D.Strings[70860]="[%s]忏悔：我曾在碎银矿脉里找了一整天的矿点。"
D.Strings[70861]="[%s]忏悔：我曾以为在深风峡谷里占领敌人的矿车可以提高我的采矿技能。"
D.Strings[70862]="[%s]忏悔：我每次玩宠物对战时都会哼同一首曲子。"
D.Strings[70863]="我们要把你们都变成奴隶。"
D.Strings[70864]="这是我的救赎！"
D.Strings[70865]="你们都将成为我们的新奴隶！"
D.Strings[70866]="和刀塔的大军相比，你们不值一提！"
D.Strings[70867]="首先，我们得先解决这座桥。"
D.Strings[70868]="这个奴隶贩子和虐待狂完全不懂荣誉为何物。"
D.Strings[70869]="我们不可能一直躲在这里。"
D.Strings[70870]="走进我的竞技场，带着荣耀战死沙场吧。"
D.Strings[70871]="你们已经进入了我的竞技场，陌生人。要想出去的话，你们要么作为胜利者离开，要么变成尸体躺着出去。"
D.Strings[70872]="这就是碎手之道。"
D.Strings[70873]="一座竞技场。这可能是个陷阱，但至少我们可以光荣地战死。"
D.Strings[70874]="我的财产！"
D.Strings[70875]="这是什么？一个外来者！"
D.Strings[70876]="[%s]忏悔：我曾在一个基维斯刚消失之后马上要求别人再开一个基维斯。"
D.Strings[70877]="我去你的要塞制作卷轴了。你有空时就去那里找我吧。"
D.Strings[70878]="你还敢自称火刃兽人？"
D.Strings[70879]="那些杂种都比你能打！"
D.Strings[70880]="要不是还有我的儿子们，我真要为氏族的未来痛哭了。"
D.Strings[70881]="你们真是我训练过的最差劲，最让我生气的团队。"
D.Strings[70882]="要是让大人们看见你们这个样子，我肯定会被处死，我的剑也会被熔化，我的旗帜都得被丢到火里烧掉。"
D.Strings[70883]="要不是这场笨拙的表演太过拙劣，我都要被你们逗笑了。"
D.Strings[70884]="那些乡下人都比你们强。"
D.Strings[70885]="你的水产品很快就会运到了，请稍后再来查看。"
D.Strings[70886]="%s开始施放|cFFFF0404|Hspell:157659|h[撕裂猛击]|h|r！"
D.Strings[70887]="弗兹万格勒雇了一个罢工破坏者？！"
D.Strings[70888]="他们抢走了我们的工作！"
D.Strings[70889]="你不能因为我们罢工就抢走我们的饭碗！这是不对的！"
D.Strings[70890]="我就知道会这样！我要夺回我的工作！"
D.Strings[70891]="都归你了，伙计。跟元素好好玩儿吧！"
D.Strings[70892]="弗兹万格勒雇了几个搅局的？！"
D.Strings[70893]="你说我没有工资是什么意思？！"
D.Strings[70894]="或许我还能拿回我的工作！"
D.Strings[70895]="快，艾克诺！再给我一个。黑手绝不容许出现任何延误。"
D.Strings[70896]="我的工作。你们打断了我的工作！"
D.Strings[70897]="我的刀下又多了一个亡魂！"
D.Strings[70898]="你的血肉将成为生火的燃料。"
D.Strings[70899]="钢铁与烈焰！"
D.Strings[70900]="来吧，我的宠物们。"
D.Strings[70901]="我有的是朋友！"
D.Strings[70902]="工作完成！"
D.Strings[70903]="荣耀属于黑石氏族！"
D.Strings[70904]="让火焰亲吻你的细皮嫩肉吧！"
D.Strings[70905]="你们的尸体会成为很好的燃料。"
D.Strings[70906]="艾克诺！你真是氏族之耻。"
D.Strings[70907]="够了——我要烧死你们！统统烧死！"
D.Strings[70908]="我的火焰……烧得太亮了。"
D.Strings[70909]="什么风把你给吹来了？我这里没有东西可卖，也不需要流浪汉！"
D.Strings[70910]="你需要穿过灌木林地。快去吧，睁大你的眼睛！$B$B啊哈哈哈！"
D.Strings[70911]="我是一名守卫！"
D.Strings[70912]="“暗影蔽日……”"
D.Strings[70913]="我是个工人！"
D.Strings[70914]="我也是工人！"
D.Strings[70915]="好的，好的，我明白了。我会告诉你怎么走的。"
D.Strings[70916]="我看见你在外头了，瑞沙德！不用再躲了，亲爱的。进来，快进来！"
D.Strings[70917]="还有你，珀西！就这样……给老奥耐卡一个吻吧。"
D.Strings[70918]="啊……好吧，当然。你好啊，奥耐卡。"
D.Strings[70919]="嘿，等等！别走啊，我们才刚刚开始呢！"
D.Strings[70920]="来吧，伙计们！在萨维克斯给我们惹出更大的麻烦之前，我们还是快回去工作吧……"
D.Strings[70921]="让我看看我的要塞。"
D.Strings[70922]="你杀了戈哈的朋友，戈哈现在该去跟谁做生意呢？"
D.Strings[70923]="那你就跟我做生意吧。"
D.Strings[70924]="或许你可以去我的要塞做生意？"
D.Strings[70925]="我的拳头！"
D.Strings[70926]="戈哈觉得这是个馊主意。"
D.Strings[70927]="奇怪的人头金币，非常闪亮。或许我应该找个时间去一次。"
D.Strings[70928]="你不好。"
D.Strings[70929]="你真的要给戈哈金币吗？"
D.Strings[70930]="你阻止不了耐奥祖。虚空之力会吞噬你的！"
D.Strings[70931]="你想拿回那些宝贝文件的话，就帮我找回我的长剑，否则免谈。"
D.Strings[70932]="戈哈喜欢你。我会找时间去拜访的。"
D.Strings[70933]="一个$c？你是来哈瓦洛送死的吧？看来我也是。$B$B作为一个兽人和德莱尼的混血儿，我在火刃氏族里的仇人在上位之后就把我放逐了。但我的荣耀不允许我忍受这种侮辱。$B$B对我的放逐是一种懦弱的表现。他们应该允许我像其他人那样为自己的地位而战。$B$B现在，我要用我的剑向他们讨要正义。"
D.Strings[70934]="听好了，你们这些蠢货！没了你们，发掘工作照样继续！如果你们还想要工资，那就赶紧去干活！"
D.Strings[70935]="杀人犯！强盗！刺客！我的守卫呢！？！"
D.Strings[70936]="如果你在占星师附近看见任何影月兽人……杀了他们。"
D.Strings[70937]="影月氏族显然不愿意看到我们建立自己的村子。我们需要保持警惕。"
D.Strings[70938]="救命啊！守卫！守卫去哪了？好吧，那我就亲手杀了你！"
D.Strings[70939]="大部分建筑都需要一点时间来建造。但考虑到这是你的第一座的建筑，我就特别照顾你一次，让我的II级资深苦工来帮你干活。"
D.Strings[70940]="当建筑建造完成并经你确认之后，我们就可以让它开张了。"
D.Strings[70941]="看呐，它烧得多么热烈！"
D.Strings[70942]="如果你找到更多的图纸和材料，你可以把它们带来给我，我们可以把其他空地都利用起来。"
D.Strings[70943]="雷兹拉克那里可能也囤积了一些图纸供你选购……只是需要花一点钱。"
D.Strings[70944]="烧光它！"
D.Strings[70945]="我曾和祖卡扎交往过……那都是以前的事了。那时我们都年轻，而且我还没遇到我的伴侣。$B$B这几年，我已经婉拒过他好几次了，可是，唉，他的脸皮比雷象还要厚。"
D.Strings[70946]="爱情真是个善变的东西……"
D.Strings[70947]="就等你了！"
D.Strings[70948]="这些蘑菇也被影响了。我们可以好好利用它们！"
D.Strings[70949]="真奇怪，都出这么大的乱子了，这些古树保护者居然都不醒。"
D.Strings[70950]="制作群体传送卷轴的材料应该已经凑齐了。干得好！"
D.Strings[70951]="知道吗，大法师经常提起你。你真是个大英雄！"
D.Strings[70952]="噢，我的天呐。它们的能级比我想象得还要高！"
D.Strings[70953]="我要去你的要塞制作卷轴了。回头见！"
D.Strings[70954]="你休想夺走我们的土地！"
D.Strings[70955]="这是戈杜尼的土地！"
D.Strings[70956]="把你砸进地里去一定会很有趣！"
D.Strings[70957]="爱情的气息！"
D.Strings[70958]="看看$n给我带来了什么！凯拉一定会爱上我的！"
D.Strings[70959]="嘿！你吃了我的花！！"
D.Strings[70960]="我注定要孤独一生了。"
D.Strings[70961]="不！！！我放弃了……"
D.Strings[70962]="快，伊瑞尔。你的战锤对我们的帮助很大。"
D.Strings[70963]="如果你找到卡拉扎，而他又跟那个虚空巫婆多玛克混在一起的话，就告诉他他母亲在找他。"
D.Strings[70964]="蠢货！如果你不尊重耐奥祖，那就成为祭品吧！"
D.Strings[70965]="妈妈说的对，影月氏族不可信！"
D.Strings[70966]="谢谢你，$n。或许下次我儿子就会听他妈妈的话了。"
D.Strings[70967]="能为我介绍一下热砂保护协会的情况吗？"
D.Strings[70968]="告诉我，当你看着一件古老的遗物时，你看见了什么？$b$b历史？文化？未解之谜？$b$b那是因为你的眼睛没有受过训练！你知道我看见的是什么吗？$b$b钱！大把的钱！$b$b如果你够聪明的话，只要跟着我一段时间，你就会对考古学的真谛有所领悟！"
D.Strings[70969]="这就好多了！"
D.Strings[70970]="再来几下！"
D.Strings[70971]="%s正准备施放|cFFFF0404|Hspell:154989|h[炼狱吐息]|h|r！"
D.Strings[70972]="%s正准备发射|cFFFF0404|Hspell:155499|h[高热弹片]|h|r！"
D.Strings[70973]="中士，我们的士兵需要帮助！快到前面去支援他们！"
D.Strings[70974]="联盟赢得了这一阶段的胜利！"
D.Strings[70975]="部落赢得了这一阶段的胜利！"
D.Strings[70976]="中士，我们的处境每时每刻都在恶化！我要你立刻投入战斗！"
D.Strings[70977]="中士，我们的战士非常英勇，但他们需要帮助！去吧，带领他们走向胜利吧！"
D.Strings[70978]="中士，目前的情况非常危急！出发吧，为了荣耀！"
D.Strings[70979]="联盟的士兵们！顶住他们，不要后退！我来帮你们了！"
D.Strings[70980]="我看见先知了！他在这儿！"
D.Strings[70981]="伊瑞尔，我的好徒弟！我还以为你死定了。"
D.Strings[70982]="先知，这位英雄——和这些来自其他世界的人——来帮助我们了。"
D.Strings[70983]="非常感谢，勇士。"
D.Strings[70984]="我们需要在你的世界建立一个基地。先知大人。"
D.Strings[70985]="很高兴见到你，我的孩子。我们欢迎你的帮助，勇士。请跟我来。"
D.Strings[70986]="先知，我必须提醒你：钢铁部落想抹杀一切反对他们的人。我们得做好防备！"
D.Strings[70987]="确实，我们如今是内外交困。"
D.Strings[70988]="我们得一个一个解决问题。首先得安置好你们的人。"
D.Strings[70989]="这里！这里扼守着山谷的入口。"
D.Strings[70990]="看出它的潜力了吗？总有一天，一支大军将在这里崛起，他们需要你的指引。"
D.Strings[70991]="插下旗帜吧，指挥官，迎接你的命运。"
D.Strings[70992]="我能开启通向暴风城的临时传送门。"
D.Strings[70993]="国王陛下承诺会派最好的建筑师来。"
D.Strings[70994]="就是这儿，伙计们！快动手，为联盟占领这个世界吧！"
D.Strings[70995]="但愿我没有信错人。"
D.Strings[70996]="先知大人，我保证，我们选定的指挥官完全可以代表联盟。"
D.Strings[70997]="这些陌生人救了很多人的命。"
D.Strings[70998]="唔，那就好。这个世界危在旦夕。前面还有许多考验。许多人都将为此牺牲。"
D.Strings[70999]="当黑暗临近……跟随圣光的指引。"
D.Strings[71000]="这里需要我。勇士，请去帮帮其他人。"
D.Strings[71001]="你有什么计划吗，阿里乌克？"
D.Strings[71002]="只有一个备用计划。但愿我们用不上它。"
D.Strings[71003]="不。我们要留下来对抗钢铁部落。我要战斗。"
D.Strings[71004]="是时候结束这一切了。到剑圣洞穴来找我吧。"
D.Strings[71005]="村里有外来者！"
D.Strings[71006]="杀了$g他:她;！"
D.Strings[71007]="你卑贱的鲜血将染红我的长剑。"
D.Strings[71008]="一个简单的考验。"
D.Strings[71009]="我要杀了你，证明我的实力！"
D.Strings[71010]="你毫无荣耀可言。"
D.Strings[71011]="你的小把戏对我没用，$c。"
D.Strings[71012]="你竟敢闯入我的家园，去死吧！"
D.Strings[71013]="你死后，没有人会记得你。"
D.Strings[71014]="我要把你投入火海。"
D.Strings[71015]="一份献给亥伯里奥斯的完美祭品。"
D.Strings[71016]="让熔岩吞噬你吧！"
D.Strings[71017]="哈瓦洛遭到了攻击！Lok-Narash！"
D.Strings[71018]="烈焰即荣耀！"
D.Strings[71019]="我的生命属于火刃氏族！"
D.Strings[71020]="你毫无荣誉可言。"
D.Strings[71021]="尝尝我的利刃吧。"
D.Strings[71022]="为了火刃氏族。"
D.Strings[71023]="为了荣耀！"
D.Strings[71024]="没有人会传唱你的事迹，$c。"
D.Strings[71025]="我的剑渴望复仇。"
D.Strings[71026]="剑圣不畏惧死亡，唯独怕蒙羞。"
D.Strings[71027]="有外来者靠近！"
D.Strings[71028]="走进竞技场，发起挑战吧。"
D.Strings[71029]="指挥官，能让我们看看你的部队实力吗？你将有幸第一个品尝敌人的鲜血。"
D.Strings[71030]="你们会在这趟旅途中闯出好名声的。"
D.Strings[71031]="记住，千万别把当地人惹火了。在我们自身实力壮大之前，一定要保持低调。"
D.Strings[71032]="把你们的侦查报告交给我吧，我会转交给指挥官的。"
D.Strings[71033]="要留意一切不正常的情况。"
D.Strings[71034]="那些刃牙虎人一定会恶有恶报的！"
D.Strings[71035]="要是不能把货物找回来，我们就不必担心刃牙虎人了，还是先担心匹克西尼会怎么处罚我们吧！"
D.Strings[71036]="你还来得及救出其他人……但是要快！"
D.Strings[71037]="这将是毕生难忘的冒险！"
D.Strings[71038]="大部分角斗士多少都有些卑鄙手段；而碾槌……他就是卑鄙的化身！"
D.Strings[71039]="犁爪只有在竞技场中获胜后才有东西吃……你最好祈祷她还不是很饿！"
D.Strings[71040]="你杀了犁爪……你杀了碾槌！快进去把霍亚拉也干掉吧！祝你好运！"
D.Strings[71041]="没人能熄灭爆火的激情！他总能像烈火吞噬茅草屋一般将敌人化为灰烬！"
D.Strings[71042]="就是他了，$n！击败罗卡之后，你就再无敌手了！快去让他们好看吧！"
D.Strings[71043]="要是你在下面遇到我那些懒鬼工人，就告诉他们，要想拿工资的话就赶紧给我开工！"
D.Strings[71044]="我受伤了，但你最好继续前进！"
D.Strings[71045]="谢谢你的帮助。"
D.Strings[71046]="我这头霜狼还没完蛋呢。"
D.Strings[71047]="Lok'tar，朋友。"
D.Strings[71048]="让这些野蛮人尝尝我们的厉害吧！"
D.Strings[71049]="唔，又厚又好，足够涂满这一堆东西了。"
D.Strings[71050]="这么多木柴很快就会烧起来的，做好准备！"
D.Strings[71051]="我要复仇！"
D.Strings[71052]="我要让食人魔血流成河！"
D.Strings[71053]="这里还有其他人，我们得救救他们。"
D.Strings[71054]="我让他们看看，被逼入绝境的狼有多么可怕！"
D.Strings[71055]="让我们杀光这些食人魔吧！"
D.Strings[71056]="我的手腕被那些锁链磨得生疼，但我还能战斗。"
D.Strings[71057]="这些食人魔将付出血的代价。"
D.Strings[71058]="我还很虚弱，但我会跟上你的。"
D.Strings[71059]="兰特瑞索割断了身上的锁链。"
D.Strings[71060]="你想买我的东西？"
D.Strings[71061]="那些该死的鬣蜥人，在我们撤离矿井前，就有超过一半的人死在他们手里。$b$b虽然我们已经坚守住了这里，但要想肃清整个矿井，就需要一些帮助了。"
D.Strings[71062]="我在竞技场等你。为荣耀而战吧，$n。"
D.Strings[71063]="我到前面去侦察一下城门，你来对付这些投石车。 Lok'tar ogar！"
D.Strings[71064]="它坏了。"
D.Strings[71065]="或许我们能修好它？"
D.Strings[71066]="不是我弄坏的！"
D.Strings[71067]="魔法真可怕。"
D.Strings[71068]="我才不回去呢。"
D.Strings[71069]="但愿它很快就会没油了。"
D.Strings[71070]="我的东西也都在塔里呢……"
D.Strings[71071]="指挥官，这边！"
D.Strings[71072]="该死的食人魔，该死的魔法！我没法破解这道屏障，我们只能悄悄绕过去了。"
D.Strings[71073]="我会先走一步，肃清前面的道路，我们在另一边见吧。"
D.Strings[71074]="这个$g男人:女人;……这个外来者发起了挑战。"
D.Strings[71075]="干掉它。让我们见识下战歌氏族的力量吧。"
D.Strings[71076]="乐意之极。"
D.Strings[71077]="让我们做个了断吧，小崽子。"
D.Strings[71078]="他只是个战歌兽人，根本不怎么会战斗。"
D.Strings[71079]="显然，你将面对真正的挑战——我的孙子们。"
D.Strings[71080]="你在外面杀了他们的父亲。现在轮到他们回敬你了。"
D.Strings[71081]="为了父亲！为了荣耀！"
D.Strings[71082]="我的孩子。你杀了我的继承人！"
D.Strings[71083]="我要亲手杀了你。让荣耀见鬼去吧！"
D.Strings[71084]="达尔。你毫无荣耀可言。你死定了。"
D.Strings[71085]="火刃兽人们，听我说！我，达尔之女，阿祖卡·刃怒，将凭借顺位继承权，继任督军之位。"
D.Strings[71086]="有意愿的氏族成员尽可以来挑战我。"
D.Strings[71087]="而你，兰特瑞索·火刃，你无权加入这场挑战。"
D.Strings[71088]="你只是一个杂种，一个流亡者。你不配作为火刃兽人。滚吧，永远不要回来。"
D.Strings[71089]="兰特瑞索吐了口唾沫，将他的旗帜丢在地上。"
D.Strings[71090]="达鲁克，是你偷了$g他:她;的图纸才把$g他:她;引来的。"
D.Strings[71091]="你是怎么发现我的？"
D.Strings[71092]="鲜血与雷鸣，真是一场激烈的大战！"
D.Strings[71093]="我们来杀几个食人魔吧！"
D.Strings[71094]="愿为你效劳，$n。我将与你并肩作战，至死方休。"
D.Strings[71095]="我从没见过这么美丽的东西。跟你合作可真不错，$n。$B$B让我们一起去碾碎战歌氏族吧！"
D.Strings[71096]="我跟你去，英雄。热烈的欢迎仪式正在安波里村等着我们呢。"
D.Strings[71097]="你的要塞令人印象深刻，英雄。哪怕是德莱尼的建筑师也没有这么高的效率。"
D.Strings[71098]="你好啊，塔沃斯先生！"
D.Strings[71099]="那座神殿就是影月氏族的家园。他们的首领是督军耐奥祖。"
D.Strings[71100]="幽影林地里危机四伏。如果你想进去的话，我就在外面等你。"
D.Strings[71101]="这片林子给我的感觉很不好。如果你想进去，我就留在这里等你。"
D.Strings[71102]="我们已经靠近德莱尼的领土了。来吧，我的姐妹在等着我们呢！"
D.Strings[71103]="没想到我还能活着从塔纳安的奴隶营里回来。"
D.Strings[71104]="我眼睁睁看着许多同胞死去……却帮不了他们。"
D.Strings[71105]="哇！我从没见过这么能打的人。"
D.Strings[71106]="什么？我听不清！快，英雄，在她追上来之前，我们赶快走吧！"
D.Strings[71107]="招招到肉！"
D.Strings[71108]="让我猜猜。你以前也这么干过吧。"
D.Strings[71109]="你真有天分。"
D.Strings[71110]="真想马上给我的姐妹萨玛拉一个惊喜。想不到我还能再见到她。"
D.Strings[71111]="伊瑞尔？你被钢铁部落抓走之后，我还以为你死定了！"
D.Strings[71112]="在我最需要的时候，圣光赐予了我力量。回家的感觉真好。"
D.Strings[71113]="萨玛拉！我回来了！"
D.Strings[71114]="最终，一切都将被吞噬。"
D.Strings[71115]="那只是黑暗之星的一小部分力量。"
D.Strings[71116]="我们走着瞧！"
D.Strings[71117]="钢铁部落的舰队已经出现在港口。我们得把所有守军都召集到神殿来。"
D.Strings[71118]="但耐奥祖也很危险。我们该怎么办，先知？"
D.Strings[71119]="勇士，你要帮我阻止黑暗之星降临。玛尔拉德，你能守住卡拉波，直到我们成功吗？"
D.Strings[71120]="只要防护水晶还在，我们就能守住。"
D.Strings[71121]="指挥官，我来召集你要塞里的部队。别耽搁时间了，他们需要你在战场上指挥。"
D.Strings[71122]="戈杜尼真是脱离帝国太久了。他们真以为一道城墙就能挡住我们？"
D.Strings[71123]="我们动手吧！一起来，好吗？"
D.Strings[71124]="但愿贾纳尔战斗的本事能比他认路的本事强一点。"
D.Strings[71125]="我都不知道我们是怎么活下来的。你真是天生的野战指挥官。"
D.Strings[71126]="英雄，你会帮我们吗？"
D.Strings[71127]="这边的任务完成了……"
D.Strings[71128]="成功了！我们打破了封锁！"
D.Strings[71129]="我们击溃了围攻的主力！回地面跟部队汇合吧。"
D.Strings[71130]="这些就是我们仅剩的部队了。我们要留在这里死守神殿的大门。"
D.Strings[71131]="勇士，我需要你冲到港口那里去。"
D.Strings[71132]="我来对付南边来的敌人。愿纳鲁之光指引着你。"
D.Strings[71133]="勇士，纳鲁来帮助我们了。我们得在它聚集力量时保护它！"
D.Strings[71134]="我们成功了！是时候结束这场袭击了……"
D.Strings[71135]="在上面！舰队的指挥官出现了。"
D.Strings[71136]="纳鲁在做什么？"
D.Strings[71137]="结束了。胜利是我们的了！"
D.Strings[71138]="英雄，感谢你的英勇无畏。请接受我的谢意。"
D.Strings[71139]="我要传送到船上去。"
D.Strings[71140]="你好，德莱尼的拯救者！"
D.Strings[71141]="当你听到这段信息，说明我已经死了——但卡拉波得救了。"
D.Strings[71142]="我欠你一个解释。"
D.Strings[71143]="德莱尼崇拜的纳鲁是纯粹的圣光生物。"
D.Strings[71144]="但在临死时，它们的精华会流失，并塌缩成暗影生物。"
D.Strings[71145]="自从德莱尼刚来到这个世界，纳鲁就陪伴着我们。但它们无法阻止飞船的坠毁。"
D.Strings[71146]="在那个可怕的夜晚，出现在德拉诺天空中的“黑暗之星”并不是什么神祇……"
D.Strings[71147]="那是一个堕落的纳鲁，在混乱和恐惧中冲出了我们的飞船。它叫做卡拉。"
D.Strings[71148]="一个曾经忠诚而美丽的生物变成了黑暗而饥渴的神，一个黑暗的活化身。"
D.Strings[71149]="我们欠卡拉太多了。没有祂的帮助，我的人民不可能逃出阿古斯。"
D.Strings[71150]="看着卡拉转化成暗影生物一直让我难以释怀。当祂归来时……我做了应该做的事。"
D.Strings[71151]="记住……生命即圣光……圣光即生命。它们可以互相转换并保持守恒。"
D.Strings[71152]="猫咪！"
D.Strings[71153]="喵喵先生。"
D.Strings[71154]="我们来玩吧，喵喵。"
D.Strings[71155]="坏猫咪。"
D.Strings[71156]="来，喵喵先生。跟我来。"
D.Strings[71157]="妈妈说你是一只坏老猫，但我不这么想。"
D.Strings[71158]="不知道谁会飞进来。"
D.Strings[71159]="过于靠近碎石堆，%s将他的匕首扔过了碎石堆！"
D.Strings[71160]="对不起，加尔鲁什，我辜负了你。"
D.Strings[71161]="尝尝龙喉氏族的利刃吧。"
D.Strings[71162]="和钢铁部落作对的人都得死。"
D.Strings[71163]="你是真死了还是在装死，懦夫？"
D.Strings[71164]="让烈焰吞噬你！"
D.Strings[71165]="死在我的剑下吧！"
D.Strings[71166]="现在，你死定了。"
D.Strings[71167]="你们是来抢占前排位置，坐看暴风城毁灭的吗？"
D.Strings[71168]="这不是我的错。我至少还有炸鸡。"
D.Strings[71169]="里——诺艾！火——车王！"
D.Strings[71170]="来看看它有没有藏着我的护肩！"
D.Strings[71171]="我的虔诚护肩！我就知道它们在这儿！我的任务完成了。"
D.Strings[71172]="终于可以好好休息了！如果你有需要，我会回你的要塞的。"
D.Strings[71173]="同调"
D.Strings[71174]="它们杀了我的猎手。你跟我，我们一起来和这些恶狼玩玩吧。"
D.Strings[71175]="卡戈拉出来了。是时候干掉她，摧毁那个护盾了，伙计。"
D.Strings[71176]="我是一个老派的萨满，我对氏族间的无聊冲突毫无兴趣。$b$b在漫长的岁月中，许多氏族都曾称这座山谷为家园，但它始终是属于元素的。"
D.Strings[71177]="请稍后再来查收更多物资吧，指挥官。在你离开的时候，苦力们会不断将物资放进这个箱子里的。"
D.Strings[71178]="你闭嘴。"
D.Strings[71179]="可是，小姐，我们藏在池——"
D.Strings[71180]="没问题。马上就会有一支装备齐整、训练有素、干劲十足的施工队过来了。"
D.Strings[71181]="加把劲儿，小伙子们，这些石头可不会自己把自己炸飞！"
D.Strings[71182]="工作时间不准睡觉，伙计们！"
D.Strings[71183]="以这个速度，我们就永远别想拿到工程款了。快点干！"
D.Strings[71184]="唔……这样应该就对了。"
D.Strings[71185]="不，这完全不行。"
D.Strings[71186]="战歌氏族出其不意地偷袭了我们。自从钢铁部落成立以来，纳格兰的局势就日趋紧张，但我们完全没想到会这样。$B$B我跟你明说吧，我帮你的原因只有2个，$r。$B$B首先，你的这位暗影猎手救了我的命。我都没想过自己还能看见第二天的日出。$B$B其次，如果让战歌氏族学会怎么使用塔拉的护盾，那就真的没人能阻挡他们了。"
D.Strings[71187]="把你看到的，躲在泥浆里的蛤蟆都带回来给我；我确信我的丈夫就在它们中间。"
D.Strings[71188]="在使用我们准备好的群体传送卷轴前，必须先摧毁所有这些结界。"
D.Strings[71189]="我得亲吻每一只蛤蟆，解除我丈夫身上的咒语。"
D.Strings[71190]="嘿，亲爱的。我回来了。"
D.Strings[71191]="噢，又来了……露拉，我就在这儿。看在圣光的份上……我不是蛤蟆。"
D.Strings[71192]="我不确定……感觉很可疑。或许我该亲吻几只蛤蟆来确定一下。"
D.Strings[71193]="干得好！现在，我们只需要干掉祖尔莫克和克罗矛格了。"
D.Strings[71194]="现在该去找克罗矛格，终结他可悲的生命了。"
D.Strings[71195]="干掉两个了，只剩下祖尔莫克了。"
D.Strings[71196]="干得好！现在，我们只需要干掉沃戈什和克罗矛格了。"
D.Strings[71197]="干掉两个了，只剩下沃戈什了。"
D.Strings[71198]="干得好！现在，我们只需要干掉祖尔莫克和沃戈什了。"
D.Strings[71199]="现在该去找沃戈什，终结他可悲的生命了。"
D.Strings[71200]="这能算进危险津贴里去吗？"
D.Strings[71201]="我要把这个打不穿的护盾移回格罗玛什尔去。这样战歌氏族就能百战百胜了。"
D.Strings[71202]="这上面的空气有点稀薄……"
D.Strings[71203]="我们越努力工作，就能越早实现盈利。"
D.Strings[71204]="这是最后一个了。这下我们不用担心他们的干扰了。"
D.Strings[71205]="我们得让苦力来帮忙。"
D.Strings[71206]="什么时候才能休息啊？"
D.Strings[71207]="这个鹤嘴锄是什么做的？磁石？"
D.Strings[71208]="我们得弄点苦力来干活。"
D.Strings[71209]="有人要咔啡豆吗？10金一粒。"
D.Strings[71210]="我们游侠受过训练，可以长时间保持警戒姿态。我已经几个小时没有动过了。"
D.Strings[71211]="今晚的沼泽荧光虫似乎特别焦躁。"
D.Strings[71212]="似乎有大量木精进入了沼泽。"
D.Strings[71213]="露拉奶奶应该再小心一些。她又在沼泽里到处游荡，亲吻蛤蟆了。"
D.Strings[71214]="多头蛇造成了一些混乱。为了确保自身安全，我们迟早得去对付他们。"
D.Strings[71215]="你可以在沼泽各地找到潜伏的游侠。跟他们每一个人都交谈之后再来向我报告吧。"
D.Strings[71216]="了不起。感谢你能这么快回来报告，$n。"
D.Strings[71217]="黑暗……降临了……"
D.Strings[71218]="阴影来了！"
D.Strings[71219]="黑暗之星降临了……"
D.Strings[71220]="虚空将吞噬一切……"
D.Strings[71221]="你的部队已经整装待发，随时可以传送过来。莫库克挡不住我们多久。"
D.Strings[71222]="这些木头可真不少！"
D.Strings[71223]="我这儿很少有人来。有客人上门的感觉真不错。$b$b你要留下来吃晚餐吗？"
D.Strings[71224]="谢了，伙计。这些战歌兽人太狡猾了，居然伏击老贾瓦。"
D.Strings[71225]="我要去萨米迪的国度了。我们回头见。"
D.Strings[71226]="我想知道达哈卡之死的真相。你知道她是怎么死的吗？"
D.Strings[71227]="黑石兽人的首领"
D.Strings[71228]="入侵者正在接近要塞！准备战斗！"
D.Strings[71229]="为了莫库克！为了帝国！"
D.Strings[71230]="那么，我们说到哪儿了？"
D.Strings[71231]="杜隆坦已经成长为一位伟大的领袖。从某种程度来说，这其中也有你的功劳。"
D.Strings[71232]="奥格瑞姆的部队十分强大。他虽然背叛了我，但我绝不会让复仇冲昏了头脑。"
D.Strings[71233]="我为人人！"
D.Strings[71234]="一把扳手加一条灵巧的胳膊足以解决一切难题。"
D.Strings[71235]="在我家乡的这趟探索之旅显然比我预想的要危险得多。"
D.Strings[71236]="我要不惜一切代价来阻止沙塔斯再次陷落。不要对这些兽人手下留情。"
D.Strings[71237]="我担心玛尔拉德会被他自己的怒火所吞噬。"
D.Strings[71238]="下压"
D.Strings[71239]="正在获取目标！"
D.Strings[71240]="正在校正空气流速。"
D.Strings[71241]="调整阻力系数。"
D.Strings[71242]="所有系统上线！开火！"
D.Strings[71243]="正中面部！"
D.Strings[71244]="噢！那一定很疼。"
D.Strings[71245]="加洛克是个蠢货！我本可以跟他分享这些力量！"
D.Strings[71246]="我要吞了你！"
D.Strings[71247]="屈服于我真正的力量吧！"
D.Strings[71248]="这么说，那个可怜的蠢货加洛克要死了，所以想知道真相？"
D.Strings[71249]="我记得达哈卡。她就跟你现在一样……"
D.Strings[71250]="谢谢你的祝福，伙计。愿死神永远不会来找你的麻烦。"
D.Strings[71251]="沃舒古里有什么东西让我魂不守舍。我得去看看。"
D.Strings[71252]="……直到我抽干了她那可怜躯体里的生命力！"
D.Strings[71253]="这是怎么了？我已经死了！"
D.Strings[71254]="我要追杀这些战歌兽人直到永远。别靠近那些巫术。"
D.Strings[71255]="啊啊啊啊啊！！！！"
D.Strings[71256]="很高兴见到你，指挥官。我们应该祝福牺牲者，关停护盾，杀掉所有的战歌兽人。"
D.Strings[71257]="这其实很简单，真的。你只要激活边界上那些水晶就行了。幸好战歌兽人都不怎么聪明。"
D.Strings[71258]="我与你同在，加洛克。带着荣耀安息吧。"
D.Strings[71259]="我要抹杀你的存在！"
D.Strings[71260]="尝尝帝国的力量吧！"
D.Strings[71261]="我受够你这多管闲事的家伙了。"
D.Strings[71262]="你这蠢货，居然敢来挑战我。"
D.Strings[71263]="我要把你碾成粉末。"
D.Strings[71264]="除非杀了我，否则你休想拿到水晶，凡人。"
D.Strings[71265]="< 铁钩刺穿了他的四肢，他的喙上还烙着一个碎手氏族的印记。$B$B看来兽人先找到了他。>"
D.Strings[71266]="快！我们需要一道屏障来抵挡他的奥能毁灭！"
D.Strings[71267]="不——！"
D.Strings[71268]="想看看帝国元首的力量吗，小家伙？那好吧。我正想来点消遣呢。"
D.Strings[71269]="我的躯体越来越疲惫了，$n。"
D.Strings[71270]="你的部队足以应付剩下的食人魔了。让我们离开这儿吧。"
D.Strings[71271]="我会把我们传送回去的。"
D.Strings[71272]="我为联盟带来了这份死亡礼物。"
D.Strings[71273]="我的敌人暂时占据了上风，但当局势对我方有利时，我还会回来的。"
D.Strings[71274]="是时候看看我的能力，挑战一下并突破自身极限了！"
D.Strings[71275]="我从不畏惧失败。"
D.Strings[71276]="我想在这片蛮荒的土地上钓鱼。"
D.Strings[71277]="我们是不会轻易倒下的！"
D.Strings[71278]="范·鲁克倒下了，呃……"
D.Strings[71279]="让这些苦力回去干活儿。"
D.Strings[71280]="加洛克，我的丈夫……"
D.Strings[71281]="我就像那和煦的清风，时刻陪伴在你的身旁。"
D.Strings[71282]="我默默注视着你为荣耀而战，我的爱从未褪色。"
D.Strings[71283]="坦克设计图？好主意。我会好好看看的。"
D.Strings[71284]="嘿，$n，想找点乐子吗？过来玩玩这个起爆器吧。"
D.Strings[71285]="站起来，我的丈夫。先祖在召唤……让我们一同响应。"
D.Strings[71286]="快去找到入侵者和那个该死的暗影猎手。"
D.Strings[71287]="不留活口。杀光外来者！"
D.Strings[71288]="再快点！我马上就要赶去沃尔瓦！"
D.Strings[71289]="很快，我们就会碾碎敌人。为了战歌氏族！"
D.Strings[71290]="小心，英雄！我们要不惜一切代价保护卡拉！"
D.Strings[71291]="他们把护盾升起来了。我们出击的时候到了，$n。干掉卡戈拉，把护盾关闭。"
D.Strings[71292]="我的眼前一片黑暗……"
D.Strings[71293]="基尔尼看来充满了希望。"
D.Strings[71294]="达哈卡，这么多年来，我一直在等待你的召唤。"
D.Strings[71295]="我们要将胜利的消息散播出去。骑上这头灵龙，回到安波里村来见我吧。"
D.Strings[71296]="你对我们来说……不过是一颗小石子……"
D.Strings[71297]="从你踏入这里的那一刻起，你就已经死定了。"
D.Strings[71298]="不！我是不会像你们一样倒下的！我……"
D.Strings[71299]="这里的钓鱼技巧跟老家那里的完全不同。来帮我们完成这里捕捞作业如何？"
D.Strings[71300]="我要再对你说一声谢谢，指挥官。这些恶魔想要生吃了我。我在要塞里等着你。"
D.Strings[71301]="%s看到它的主人倒下，变得非常愤怒。"
D.Strings[71302]="死畜生！都给我动起来，一群懒骨头！"
D.Strings[71303]="你们这群懒虫！快肃清走廊！"
D.Strings[71304]="快跑，畜生！快把这些补给品送到下面去！"
D.Strings[71305]="你休想进入钢铁装配车间！"
D.Strings[71306]="达鲁克，你是客人，这首战的荣耀，就让给你了。"
D.Strings[71307]="让我们见识下战歌氏族的力量吧。"
D.Strings[71308]="我需要休息！"
D.Strings[71309]="你使用之后，它就会“轰！”地一声飞上天了！"
D.Strings[71310]="火刃兽人在战斗中是出了名的品格高尚。但是，这并不意味着他们见到你的时候不会开打。"
D.Strings[71311]="我们刚来的时候，就应该彻底灭绝德拉诺的兽人。那么这一切就都不会发生了。"
D.Strings[71312]="必须破坏钢铁部落的战争机器。小心点，$n。"
D.Strings[71313]="那些武器再也不能伤害我们的人民了。干得好，$c。"
D.Strings[71314]="你只要把那些还能看清的书页带回来就行了！"
D.Strings[71315]="唔……睡觉……"
D.Strings[71316]="我就睡一会儿……"
D.Strings[71317]="你完成之后，记得提醒我清理镜片。那玩意儿都几百年没清理过了。"
D.Strings[71318]="我已经帮你全部修好了！"
D.Strings[71319]="好累！"
D.Strings[71320]="你击败了她！你已经向我证明了自己，让我摆脱了在熔炉做苦役的命运。我的命归你了，$n。"
D.Strings[71321]="立刻使用你的|TInterface\\Icons\\inv_scroll_02.blp:32|t |cFFFF0000|Hspell:162568|h[群体传送卷轴]|h|r！"
D.Strings[71322]="感谢你在塔拉的帮助，$n。$B$B我已经控制住她了，但有你在身边总是让人觉得安心，$g小子:丫头;。"
D.Strings[71323]="要我说，我们就该把看到的所有兽人都干掉！谁在乎他们到底属于哪个氏族？"
D.Strings[71324]="还是石头！"
D.Strings[71325]="唔……石头！"
D.Strings[71326]="嗯……火！"
D.Strings[71327]="又是……火？"
D.Strings[71328]="噢！他们动手了！"
D.Strings[71329]="走开！陛下谁也不见！"
D.Strings[71330]="我们也动手吧。"
D.Strings[71331]="听到了吗？"
D.Strings[71332]="呵呵……这一定很棒。"
D.Strings[71333]="我也干掉一个！"
D.Strings[71334]="他们太小了。"
D.Strings[71335]="哈哈哈！！"
D.Strings[71336]="砸死他！"
D.Strings[71337]="哈哈……砸！"
D.Strings[71338]="让我们玩玩吧！"
D.Strings[71339]="这家伙死了。"
D.Strings[71340]="他们被砸中的时候还会尖叫。"
D.Strings[71341]="真好玩。我们再来！"
D.Strings[71342]="噢……好……痛啊……"
D.Strings[71343]="没意思。我们杀了他们吧。"
D.Strings[71344]="噢，没错！你最好离爆炸点远些，不然会被炸飞的。"
D.Strings[71345]="在钢铁部落出现之前，我从没见过这样的机器。"
D.Strings[71346]="祝你好运，小心那些炸药。"
D.Strings[71347]="我已经等不及想要修好这玩意儿了！"
D.Strings[71348]="抱歉，我的耳目可能有点怪味儿。但这没什么好担心的！"
D.Strings[71349]="好好享受驾驶切割者的乐趣吧！这一定很有趣！"
D.Strings[71350]="好极了。让我们拿上那块水晶，然后离开这里！"
D.Strings[71351]="你准备好之后，就带着我们进入沙塔斯吧。"
D.Strings[71352]="沿着这条路往前走就是奥耐卡的小屋了。我和珀西会跟紧你的。"
D.Strings[71353]="让我们完成这座建筑，让它运转起来吧！"
D.Strings[71354]="身为法师总是会有一些特权的！"
D.Strings[71355]="多么老套。一堵墙！戈杜尼食人魔真的是脱离帝国太久了。"
D.Strings[71356]="这应该能让我们过去！"
D.Strings[71357]="我们得摧毁这些结界。它们会令我们无法使用准备好的群体传送卷轴。"
D.Strings[71358]="太好了！很高兴我们不用去应付他们了。"
D.Strings[71359]="精彩的战斗！快拿上那块水晶，让我们离开这儿。"
D.Strings[71360]="你真是个不可思议的战士！现在我们只剩下祖尔莫克和克罗矛格要对付了。"
D.Strings[71361]="现在我们只需要找到克罗矛格了。"
D.Strings[71362]="现在只剩下祖尔莫克了。"
D.Strings[71363]="你真是个不可思议的战士！现在我们只剩下沃戈什和克罗矛格要对付了。"
D.Strings[71364]="你真是个不可思议的战士！现在我们只剩下祖尔莫克和沃戈什要对付了。"
D.Strings[71365]="现在我们只需要找到沃戈什了。"
D.Strings[71366]="你的部队就等我们启动传送了。我们肯定能打莫库克一个出其不意。"
D.Strings[71367]="我们回要塞去吧。你的部队可以应付剩下的食人魔了。"
D.Strings[71368]="我来把我们传送回去。"
D.Strings[71369]="装填"
D.Strings[71370]="黑暗在西方滋长。伟大的大地之怒戈达乌也失去了踪影。"
D.Strings[71371]="元素王座的愤怒之灵，我们响应你们的召唤，有什么可以效劳的吗？"
D.Strings[71372]="自从大地之怒离开王座，维系这个世界的元素纽带就被削弱了。"
D.Strings[71373]="我们必须找到戈达乌，让他回到王座。"
D.Strings[71374]="平衡已被打破。元素高地日益动荡，必须得到净化。"
D.Strings[71375]="如果任由它发展，元素就将席卷整座山谷，撕碎所有的生命。"
D.Strings[71376]="这就是元素王座。$b$b你面前的就是诸位元素之怒，$n。在这里，你脚下的大地有着生命，周围的轻风监视着你的行动。$b$b这是一片真正的圣地。"
D.Strings[71377]="我准备好与元素之怒沟通了。"
D.Strings[71378]="%s出现并开始纠缠你！"
D.Strings[71379]="我们明白了。我们一定会找到戈达乌并恢复平衡的。"
D.Strings[71380]="元素的命运就在你们的手中。"
D.Strings[71381]="在经历过那么多事情之后，谁能想到我会走到这一步？$b$b再也没有比活剐食人魔，再把他们的下水扔到我那个傲慢的钢铁部落前老板脸上更爽的事了！"
D.Strings[71382]="指挥官！我一听到食人魔垂死的哀号就尽快赶来了。一切都还顺利吗？"
D.Strings[71383]="立刻使用你的|TInterface\\Icons\\CREATUREPORTRAIT_GOBLIN_ROCKET.blp:32|t |cFFFF0000|Hspell:162896|h[紧急火箭背包]|h|r！"
D.Strings[71384]="有人要搭车吗？"
D.Strings[71385]="呃！抓住他们！"
D.Strings[71386]="当你变得更聪明一点时，我会给你讲伟大的英雄传说的。$b$b（需要达到至少91级才能聆听辛恒的故事。）"
D.Strings[71387]="跟我说说魔古山守护者的故事吧。"
D.Strings[71388]="我要歌颂一位手持神兵利器的英雄……噢，咳，你还不能听这一段。等你再多经历一些世事之后再来吧。$b$b（需要达到至少91级才能聆听韩恩的故事。）"
D.Strings[71389]="不久之前，外来者的船只搁浅在潘达利亚的海岸，带来了冲突和勇气。听着，我要告诉你深渊中的阴影是如何肆虐潘达利亚，而勇敢的英雄又是如何为我们带来新的黎明的。"
D.Strings[71390]="跟我说说神秘宝库的故事吧。"
D.Strings[71391]="跟我说说恐惧临近恐惧之心的故事吧。"
D.Strings[71392]="跟我说说夏柯希尔的梦魇的故事吧。"
D.Strings[71393]="跟我说说永春台的故事吧。"
D.Strings[71394]="现在只剩克罗矛格了。"
D.Strings[71395]="跟我说说赞达拉的背水一战的故事吧。"
D.Strings[71396]="跟我说说雷电王座下的被遗忘的深渊的故事吧。"
D.Strings[71397]="跟我说说扭曲的魔古修身殿的故事吧。"
D.Strings[71398]="跟我说说雷神的风暴之巅的故事吧。"
D.Strings[71399]="跟我说说锦绣谷之殇的故事吧。"
D.Strings[71400]="跟我说说发生在复仇之门的那场战争吧。"
D.Strings[71401]="跟我说说奥格瑞玛的地下堡垒的故事吧。"
D.Strings[71402]="跟我说说暴君的黄昏的故事吧。"
D.Strings[71403]="我们是不可能穿过他们的大门的。如果你想试试，我可以在这里等你。"
D.Strings[71404]="你不是鸦群的一份子，但你为鸦母送上了令人难忘的礼物。"
D.Strings[71405]="让我看看！"
D.Strings[71406]="休想。如果让马尔洛克知道我让别人接近那玩意儿，他会扒掉我们的皮的。"
D.Strings[71407]="呸！我才不怕那个老东西呢。"
D.Strings[71408]="你应该怕的。"
D.Strings[71409]="现在，让我们行动吧！"
D.Strings[71410]="只有当你能与元素共鸣时，才能接受融合仪式。"
D.Strings[71411]="你准备好之后，我就要跟伟大的元素之怒们沟通了。"
D.Strings[71412]="快，$c。重生循环必须开始。"
D.Strings[71413]="虽然被削弱了，但他们在高地的化身依然非常强大。千万别低估他们的力量。"
D.Strings[71414]="燃烬之花的烈焰和荆棘总是让我想起她的力量和信念。"
D.Strings[71415]="我一直在怀疑查尔莉，但我没有足够的证据来制裁她。"
D.Strings[71416]="我已经走到了生命的尽头，但我知道我将永远活在她的心中。"
D.Strings[71417]="你可以在俯瞰元素王座的悬崖上找到加洛克。"
D.Strings[71418]="当你身边流过更多的时间之沙时再来找我吧。你现在还无法面对这个挑战。$b$b（需要达到至少86级才能单独进入随机难度的巨龙之魂。）"
D.Strings[71419]="时间之沙从你身旁流过，但我能把你送回暮光审判的那天，整个世界在灭世者的威胁下命悬一线。$b$b（奥里多米可以将你和你的小队成员直接送入随机难度的巨龙之魂，无需外界帮助。)"
D.Strings[71420]="我要去围攻龙眠神殿。"
D.Strings[71421]="送我回死亡之翼的陨落之前。"
D.Strings[71422]="你暂时引起了我的好奇心。告诉我，是什么让你来找我们的？"
D.Strings[71423]="对于高里亚帝国的成员来说，这可不是什么体面的营地。如果你们钢铁部落还想保住盟友的话，就得好好款待我们！"
D.Strings[71424]="水能够滋养并延续生命，也能够切断泥土和岩石。"
D.Strings[71425]="汲取了大地之力的人可以碾碎他们的敌人，就好像碾碎脚下的沙粒。"
D.Strings[71426]="砸死你！"
D.Strings[71427]="我一用力，你就死了！"
D.Strings[71428]="那些有着炽烈信念和凶猛勇气的人常常会发现自己很适合烈焰之道。"
D.Strings[71429]="风是元素之声，它会在微风中轻声低语，在风暴中凶猛呼号。"
D.Strings[71430]="加入……我们……"
D.Strings[71431]="带你去……核心……"
D.Strings[71432]="救命……快来我这里……"
D.Strings[71433]="借用"
D.Strings[71434]="坚强起来，鸦群的兄弟姐妹们！鸦母只是在考验我们的信仰！"
D.Strings[71435]="鸦母派这些野兽来考验我们的决心！我们要用更大的热忱让她听到我们的呼声！"
D.Strings[71436]="高阶鸦语者，我为您带来了这份礼物，希望得到您的接见。"
D.Strings[71437]="愿鸦母庇佑你。"
D.Strings[71438]="黑手在塔拉多等着这些货呢。快！"
D.Strings[71439]="黑手绝不容许出现任何延误。"
D.Strings[71440]="1号轨道。"
D.Strings[71441]="进入1号轨道！"
D.Strings[71442]="2号轨道！"
D.Strings[71443]="进入2号轨道。"
D.Strings[71444]="3号轨道。"
D.Strings[71445]="进入3号轨道。"
D.Strings[71446]="4号轨道！"
D.Strings[71447]="进入4号轨道。"
D.Strings[71448]="列车进站！"
D.Strings[71449]="快速前进。"
D.Strings[71450]="清理轨道！"
D.Strings[71451]="啊——援军。"
D.Strings[71452]="援军，来得正是时候。"
D.Strings[71453]="军列进站！"
D.Strings[71454]="他们来了——下车吧，伙计们！"
D.Strings[71455]="指挥车到了。"
D.Strings[71456]="老大来了。"
D.Strings[71457]="真呛人。"
D.Strings[71458]="那是火炮。"
D.Strings[71459]="炸弹来了！"
D.Strings[71460]="特快专列来了！"
D.Strings[71461]="快车，本站不停。"
D.Strings[71462]="让它过去！"
D.Strings[71463]="快点！有多快跑多快！"
D.Strings[71464]="死路一条。"
D.Strings[71465]="终点到了！"
D.Strings[71466]="哈，扁得跟铜片一样了。"
D.Strings[71467]="都上车吧！"
D.Strings[71468]="刚好赶上。"
D.Strings[71469]="嗯？坚持不下去了？"
D.Strings[71470]="哈哈，这张时刻表太折磨人了！"
D.Strings[71471]="让我们加快速度。"
D.Strings[71472]="你们正巧赶上了高峰时间。"
D.Strings[71473]="没什么大不了的。进站的列车多的是！"
D.Strings[71474]="我在赶时间！"
D.Strings[71475]="你们没时间了……"
D.Strings[71476]="终点站到了！"
D.Strings[71477]="时刻表……不是这么写的……"
D.Strings[71478]="|TInterface\\Icons\\spell_shadow_mindbomb.blp:20|t攻城炸弹锁定了你！"
D.Strings[71479]="你这没用的蠢猪！回去干活。我们的指标还没完成呢！"
D.Strings[71480]="%s陷入了狂乱！"
D.Strings[71481]="不！你会付出……"
D.Strings[71482]="我要磨碎你的灵魂！"
D.Strings[71483]="记住破碎琉璃之卷的教诲！你们要敬畏鸦母的威能，不要迷失在生活的苦海，堕入永恒的轮回！在鸦母的祝福下，鸦群必将生生不息！"
D.Strings[71484]="我有一个计划。"
D.Strings[71485]="他有什么计划？"
D.Strings[71486]="队形很好。现在，进攻！"
D.Strings[71487]="鸦母还告诉我：科卡，你是我亲爱的孩子。你要找回我其他任性的孩子，将他们带回鸦巢。"
D.Strings[71488]="当鸦群团聚之时，末日就将降临。世界将在灾难中四分五裂！不要恐惧，因为鸦母会拯救我们！"
D.Strings[71489]="鸦母会从天空降下，来拯救她的孩子。我们将乘着她漆黑的翅膀，在她的黑暗国度中占据一席之地！"
D.Strings[71490]="到那时，你们一定会尽情赞美鸦母的！她用教诲和力量眷顾她高贵的子嗣。愿她的阴影笼罩你们！"
D.Strings[71491]="抄写员！你都记下来了吗？"
D.Strings[71492]="是的，高阶鸦语者。"
D.Strings[71493]="赞美鸦母！"
D.Strings[71494]="谁在那儿？父亲……是你吗？"
D.Strings[71495]="请靠近一点。这里太黑了……"
D.Strings[71496]="你不是我父亲……可是……你身上有他的东西……"
D.Strings[71497]="|c00FFFF00|Hspell:178380|h[食人魔大王考洛克]|h|r苏醒了！"
D.Strings[71498]="|c00FFFF00|Hspell:178380|h[食人魔大王考洛克]|h|r又沉睡了。"
D.Strings[71499]="|c00FFFF00|Hspell:178380|h[食人魔大王考洛克]|h|r选择与联盟并肩作战！"
D.Strings[71500]="|c00FFFF00|Hspell:178380|h[食人魔大王考洛克]|h|r返回了他的王座。"
D.Strings[71501]="|c00FFFF00|Hspell:178380|h[食人魔大王考洛克]|h|r选择与部落并肩作战！"
D.Strings[71502]="%s对你施放了|cFFFF0404|Hspell:155277|h[炽热光辉]|h|r！"
D.Strings[71503]="不！我的……磨魂者……"
D.Strings[71504]="小伙子们，今晚有淡水兽肉吃了！"
D.Strings[71505]="鸦母的阴影在上！这种、这种大屠杀怎么会发生在我们身上？"
D.Strings[71506]="保持信念，书记官！记住黑暗黎明之卷里的教诲，“鸦群必须团结一致。”当鸦母归来，她的孩子都将进入她的巢穴，到时我们就安全了。"
D.Strings[71507]="当然，大人。"
D.Strings[71508]="计划有变！推倒它！"
D.Strings[71509]="我们准备走另一条路线了。推倒这座建筑！"
D.Strings[71510]="有了钥石，你就可以通过了，但只能你一个人去。你进去之后，就关闭他们的护盾，让我们跟你汇合。"
D.Strings[71511]="车队由一个像狼一样的女人带领。我得承认，我还在适应你们艾泽拉斯人。他们几个小时之前刚刚离开这里。"
D.Strings[71512]="指挥官，我们发现这个德莱尼躺在城墙外的路上。"
D.Strings[71513]="坚持住，吉德文。支援已经在路上了。"
D.Strings[71514]="来吧，我带你去见高阶鸦语者。"
D.Strings[71515]="我真不该离开达拉然。我当时是怎么想的？"
D.Strings[71516]="你找到隐藏的神器了吗？$B$B你可以在阿什兰各地找到它的碎片。我听说最近有人在击杀荣耀之路外围的生物时也发现了一些。$B$B你可以把你找到的神器交给我，我会将它们分发给需要的人。"
D.Strings[71517]="你来的正是时候。很快，鸦母就会降临到我们中间！"
D.Strings[71518]="高阶鸦语者，愿鸦母的神圣阴影永远庇佑你。"
D.Strings[71519]="高阶鸦语者，这个外来者正如书里所著的那样来到了我们身边！"
D.Strings[71520]="唔？你需要什么吗？"
D.Strings[71521]="是的。我需要你帮我开动那台巨型坦克。"
D.Strings[71522]="快买一只神奇的生物回家吧，这可是从未在德拉诺出现过的稀罕货色！"
D.Strings[71523]="快来切丽的神秘动物园看看吧！观赏来自遥远国度的珍稀动物！"
D.Strings[71524]="这边，英雄，别让他们看见我们！听——他们在谈论黑暗之星。"
D.Strings[71525]="透……不过气了……这股臭气让我更生气了！"
D.Strings[71526]="有时我会来这里清醒一下头脑。"
D.Strings[71527]="我的妹妹来这里思考圣光的教诲。我和穆库会尽量不让兽人去打扰她的。"
D.Strings[71528]="马上就好。"
D.Strings[71529]="很快。我的冥想马上就能结束了。"
D.Strings[71530]="再给我几分钟。这里是如此祥和，让我想起了……过去。"
D.Strings[71531]="我们得在这等多久？这里很不安全，艾努米。"
D.Strings[71532]="你要在这里一直跪下去吗？"
D.Strings[71533]="快告诉我你可以返回村子了！我们已经在这里呆了好几个小时了！"
D.Strings[71534]="我爱我的小猫咪！"
D.Strings[71535]="噢……巴伯是不是你见过的最可爱的小猫咪？"
D.Strings[71536]="迪娜是个小甜心。但要小心她的爪子，特别是当她眼神疯狂的时候。"
D.Strings[71537]="那些植物人想把我活埋了！"
D.Strings[71538]="前往大路。"
D.Strings[71539]="噢，伙计……这场战争太疯狂了，是吧？$b$b我已经等不及了，真希望它马上结束，好让我回家看老婆孩子。$b$b想看照片吗？$b$b这是我妻子阿什莉，这是我漂亮的女儿艾拉。伙计，我想死她们了。"
D.Strings[71540]="我想你最好还是离开这里，$r。"
D.Strings[71541]="哇，哇，有位英雄来救我们了。小心点，我的朋友，戈尔隆德可不是逞英雄的地方。"
D.Strings[71542]="道路已经安全了。"
D.Strings[71543]="你不用跟我说两遍。我们路上见！"
D.Strings[71544]="现在吗？好吧，既然岗哨已经不安全了，那我想我们就该放弃它了。古魈已经闻到了我们的气味，他们不会让我们滞留在这里的。"
D.Strings[71545]="好吧。我们到那儿见。注意安全。"
D.Strings[71546]="要让你疲惫的身体休息一下吗？"
D.Strings[71547]="高尔玛什的灵魂非常冷酷。让这份先祖之风的恩赐指引你的双手吧。"
D.Strings[71548]="如果柴堆还不能点燃，我们也会被吸入虚空而送命的。"
D.Strings[71549]="要想让这些剩下的灵魂安息，我们必须消灭那些残影。"
D.Strings[71550]="为了战歌氏族的荣耀，我要碾碎你！"
D.Strings[71551]="你竟敢接近巨人屠夫？我要砍掉你的脑袋！"
D.Strings[71552]="为什么我感觉不到疼痛？"
D.Strings[71553]="我想起来了……这不是我的末日。我早就死了……我是光荣地死去的！"
D.Strings[71554]="你想跟艾瑞德谈谈？很抱歉，他的伤很重，而且病得厉害。"
D.Strings[71555]="艾瑞德肯定不想看到我站在这里哭成这样。让我们去你的军械库吧。"
D.Strings[71556]="这真是太棒了！要是艾瑞德能活着见到它，他一定会很骄傲的！"
D.Strings[71557]="我们在逃出沙塔斯的过程中经历了太多的困难，他最终还是没能战胜病魔。$b$b亲爱的老师，我会想你的。"
D.Strings[71558]="码头。去码头！快，快！"
D.Strings[71559]="冲我来，地狱咆哮！"
D.Strings[71560]="别蠢了，贾纳尔——快跑！我们改天再战。"
D.Strings[71561]="继续跑。我看见船了，就在前面。"
D.Strings[71562]="他们的整支大军都跟在我们后头。"
D.Strings[71563]="现在往哪儿？"
D.Strings[71564]="不！让我靠近点……看看。这肯定是它！"
D.Strings[71565]="到道路尽头的船上去。"
D.Strings[71566]="这边走，快快快！"
D.Strings[71567]="你们无路可逃了。这是我的世界。我们会找到你们的！"
D.Strings[71568]="死亡……或者耗尽力气。我曾以为自己一定能在这里找到想要的东西！"
D.Strings[71569]="霜狼氏族会等着你的，地狱咆哮！你，你的食人魔，你的整个钢铁部落……你们死定了！"
D.Strings[71570]="别理会他的威胁。我们得去影月谷增援。这一次，德莱尼必将胜利。"
D.Strings[71571]="那就让我们出发吧。要想终结钢铁部落的威胁，我们得建造一座要塞。同时，我们还需要当地人的帮助。"
D.Strings[71572]="去影月谷！"
D.Strings[71573]="去霜狼的家园！"
D.Strings[71574]="快，蠢猪们！拿出吃奶的劲儿来。"
D.Strings[71575]="他们来了……快起来！"
D.Strings[71576]="马上列队，快！"
D.Strings[71577]="等等，我感觉到了。它就在附近。快！到我这儿来！"
D.Strings[71578]="人人都说我是个傻子，收集了这么多宠物。现在你再看，到底是谁笑到了最后？"
D.Strings[71579]="珍稀宠物？这些看起来都很普通啊……"
D.Strings[71580]="对你来说可能是很普通。但这些乡巴佬连鸡都没见过！我肯定会发大财的！"
D.Strings[71581]="很久之前，当流亡者们还没登上吉尼达尔时，德莱尼曾是伟大的艾瑞达文明的一部分。"
D.Strings[71582]="哈卡玛，告诉大家，那个曾被艾瑞达称为家园的世界叫什么名字呢？"
D.Strings[71583]="呃……是叫艾瑞多吗？"
D.Strings[71584]="猜得不错，哈卡玛，但那个世界其实叫做阿古斯。"
D.Strings[71585]="艾瑞达是睿智而强大的种族。但一位堕落神祇用花言巧语腐蚀了他们，导致了艾瑞达的衰落。"
D.Strings[71586]="那么，拉斯塔克，你知道那个腐蚀了艾瑞达的堕落神祇叫什么名字吗？"
D.Strings[71587]="他们需要你帮忙对付黑手！我可以送你过去。你准备好之后就告诉我一声吧。"
D.Strings[71588]="我记得是……萨格拉斯。"
D.Strings[71589]="非常好，孩子。"
D.Strings[71590]="当萨格拉斯怀着阴谋接近艾瑞达时，我们睿智的先知看穿了他的谎言，并成功救出了一小部分人民。那些幸存者建立起了我们今天的文明。"
D.Strings[71591]="谁能告诉我，那位让我们的人民免受腐蚀，并带领我们来到德拉诺的先知叫什么名字？阿莱娜，你知道吗？"
D.Strings[71592]="你瞧，我们真是一对好搭档。$b$b一开始，我只是想纪念一下我的老师，而现在，我很希望能为你长期工作下去。谢谢你给了我一个机会。"
D.Strings[71593]="是维伦，齐尔丽小姐。"
D.Strings[71594]="没错，答得很好。"
D.Strings[71595]="可是，就算是维伦这样的先知也不可能独自拯救德莱尼。他的行动得到了神圣的圣光生物的帮助。"
D.Strings[71596]="谁知道那种帮助维伦拯救德莱尼的生物叫什么？"
D.Strings[71597]="噢，这个我知道！"
D.Strings[71598]="说吧，哈卡玛。"
D.Strings[71599]="是纳鲁！"
D.Strings[71600]="非常好，哈卡玛！"
D.Strings[71601]="我们德莱尼，是唯一完全逃过萨格拉斯腐蚀的人。其他艾瑞达人都被变成了他的黑暗爪牙。"
D.Strings[71602]="下面这个问题有加分哦，现在我们管这些早已迷失了艾瑞达本性的爪牙叫什么呢？阿莱娜？"
D.Strings[71603]="堕落者，齐尔丽小姐。"
D.Strings[71604]="答得很好，阿莱娜。你答对了。"
D.Strings[71605]="今天的课就讲到这里。回家别忘了预习下一课的内容，关于我们的新家园，德拉诺的种种奇观。"
D.Strings[71606]="保持冷静，伙计们。你们将被传送到食人魔领土的核心区域。"
D.Strings[71607]="握紧你们的武器。你们将被直接传送到地狱里去。"
D.Strings[71608]="我到前面去侦察一下城门，你来对付这些投石车。Dioniss aca。"
D.Strings[71609]="我早就发现上面的池塘里鱼更多。但，真正的专家都知道，大鱼都喜欢躲在更加隐蔽的地方。\n\n等着吧，我就是要让萝鲁娜看看我能在草丛里钓到些什么！"
D.Strings[71610]="是……是这个地方吗？它在这里吗？去干掉那些怪物，让我好好想想！"
D.Strings[71611]="这道魔法屏障太强大了，我们的炸药炸不开它。我也没有办法关闭它，所以我们得想办法绕过屏障，然后溜进去。"
D.Strings[71612]="我看不清楚……给我一点时间……"
D.Strings[71613]="谢谢你的帮助，$n。我们后会有期。"
D.Strings[71614]="谢谢你的帮助，$n。我相信，我们以后还会见面的。"
D.Strings[71615]="勇士们，尼娅米在西边的仪式大殿里等着你们。"
D.Strings[71616]="铁匠哈菲斯特能造出影月谷最好的武器和护甲。他的作品能在沙塔斯的市场上卖出一个好价钱。"
D.Strings[71617]="呸，废物。等你变强一点再来吧。"
D.Strings[71618]="伊瑞尔！？！ 你没有死啊？！"
D.Strings[71619]="想要打败我，就靠那几个兽人可不够！"
D.Strings[71620]="伊瑞尔！是你吗？你还欠我六个铜板呢！"
D.Strings[71621]="你还欠我六个铜板呢！"
D.Strings[71622]="一个货车空空的商人，多么悲伤的景象，是吧？\n\n要是我的伙伴达鲁恩能早点下定决心，我们现在应该已经在路上了。"
D.Strings[71623]="非常可爱的盆栽，是吧？什么颜色最能迎合沙塔斯的市场呢？\n\n这年头还有人买盆栽吗？"
D.Strings[71624]="耶！你来了！"
D.Strings[71625]="伊瑞尔！她来救我们了！"
D.Strings[71626]="这个陌生人会帮助我们的！"
D.Strings[71627]="她回来了！"
D.Strings[71628]="英雄！英雄！"
D.Strings[71629]="午安，孩子们！我带来了一位从远方来的英雄。"
D.Strings[71630]="那支该死的军队随时可能抵达这里。我们走！"
D.Strings[71631]="塞斯克！"
D.Strings[71632]="高恩！"
D.Strings[71633]="魔网已经将我们连接在了一起，我们可以建立一座直通你要塞的传送门了。"
D.Strings[71634]="拿着武器在野外行军，这简直跟在熔炉干活一样有趣！"
D.Strings[71635]="启动人员疏散系统。"
D.Strings[71636]="茂林幽谷有麻烦了。我们最好去看看能不能帮上忙。"
D.Strings[71637]="南达兹自以为聪明，非要在下面的海湾里钓鱼，可你也看到这上面有多少鱼了！这么多！他真是个蠢货。"
D.Strings[71638]="我没事。我们得继续前进。它在召唤我们。"
D.Strings[71639]="哈！我能看出你很勇敢，但危险就是我的老本行！"
D.Strings[71640]="我活着，我热爱，我屠杀，我满足。"
D.Strings[71641]="啊，终于。"
D.Strings[71642]="啊！这些畜生都在冲我乱吼，我没法思考了。让它们闭嘴！"
D.Strings[71643]="伊瑞尔是我最聪明的学生，但有时也是最糟糕的。$B$B她战斗起来十分勇猛，但从不把训练当回事。$B$B她学得很快，但总是静不下心来读书。$B$B比起背诵圣典，她宁愿去和村子的孩子玩耍。$B$B要是她能再专心一点该多好！"
D.Strings[71644]="圣光在上，真是场激烈的战斗！"
D.Strings[71645]="不是男人，不是女人，也不是野兽……"
D.Strings[71646]="这才是我最信赖的东西。"
D.Strings[71647]="对我来说，春天是不存在的。"
D.Strings[71648]="先知维伦是个很好的老师，但他有时候太一本正经了！$B$B我宁愿在生活中实践神圣的戒律，而不是在书本上阅读它们。你说呢？"
D.Strings[71649]="除了痛楚，没有什么能伤害我！"
D.Strings[71650]="谁都不该带着镣铐过活！"
D.Strings[71651]="最重要的是，我们这点人要对付许多敌人。"
D.Strings[71652]="很好。如果你想活命，就跟我走。"
D.Strings[71653]="我们动手吧！"
D.Strings[71654]="偷窃"
D.Strings[71655]="就要……到了。再过去一点。很快……"
D.Strings[71656]="别废话了！"
D.Strings[71657]="我们连通了魔网。现在我们可以建立一条直通你要塞的连接了。"
D.Strings[71658]="我会……回来的……"
D.Strings[71659]="我们从嘲颅兽人那里学会了一个秘诀：魔荚人最恨火焰。"
D.Strings[71660]="达坎会赶来帮忙的。"
D.Strings[71661]="独自前行吧，陌生人。我只会拖你的后腿。我会留下来等待达坎抵达。"
D.Strings[71662]="那些邪恶的生物在长矛上涂抹了毒药。我还有一支解毒剂，但我需要一点时间，等头脑清醒后才能移动。"
D.Strings[71663]="这里。对，就是这里！这就是我要找的地方。"
D.Strings[71664]="别担心我，朋友。我会等着达坎过来的。请去寻找其他人吧。"
D.Strings[71665]="啊，胜利的味道。要是我的剑还在身边就好了……那我一定能立下不朽的功勋。"
D.Strings[71666]="我们一起击溃了奴隶贩子，加速了他们的灭亡！他们夺走了我的一切。\n\n但我还有一样东西。成为更伟大的事业的一份子……我几乎都忘记那种感觉了。"
D.Strings[71667]="是的，我现在明白了。我们必须拿走它。我们要把它带给我们的人民，为他们指出前进的方向。你帮了我很多忙，我想是时候让你加入我们了。"
D.Strings[71668]="我是不会把牺牲者留给原祖荆兽的幼苗的。我要保护他们的遗体，直至达坎抵达。"
D.Strings[71669]="我们已经尽力厮杀了。但最后，我的许多朋友还是牺牲了。"
D.Strings[71670]="如果它会流血，那我们就能杀了它！"
D.Strings[71671]="我将是你最可怕的梦魇！"
D.Strings[71672]="当那些东西冲出来攻击我们时，吉德文和我正在外面钓鱼。$b$b多亏了这些德莱尼，否则我们就死定了。$b$b要不是需要有人把吉德文送回营地，我一定要亲手杀了它们……这个白痴矮人。"
D.Strings[71673]="你正好落入了我的陷阱，“指挥官”。战歌氏族，进攻！"
D.Strings[71674]="木精从没这么充满敌意过。$b$b如果这种情况持续下去，我们就不得不深入密林深处了。"
D.Strings[71675]="小心点，指挥官。虽然我们胜利了，但我有种不好的预感。"
D.Strings[71676]="我在格罗玛什尔的城门那边等你。"
D.Strings[71677]="我们的要塞需要一些鱼，你能胜任这个任务吗？"
D.Strings[71678]="那个霜狼崽子被吓破胆了吗？"
D.Strings[71679]="让那个霜狼崽子继续挖！哈哈哈……"
D.Strings[71680]="别对那个霜狼崽子手软。我们要压垮他的意志。"
D.Strings[71681]="要是我们在纳格兰只需要对付战歌兽人和悬槌食人魔就好了。$B$B在河的另一边，完全是一个人间地狱。"
D.Strings[71682]="带头冲向那些原祖荆兽吧，$n。游侠就在你的身后。"
D.Strings[71683]="如果没有你的话，我不知道我们能不能打败那个原祖荆兽。我们后会有期，$n。"
D.Strings[71684]="小心脚下，$c。这片密林不仅美丽，而且致命。"
D.Strings[71685]="引爆炸药……快！"
D.Strings[71686]="我们得确保旅行者不再受木精的袭击。$b$b阿瑞菲奥刚带着其他人离开了，如果你现在就走，或许还能追上他。"
D.Strings[71687]="要是我们只能整天干坐在这儿，那我还怎么赚钱？$b$b是的，我知道吉德文看起来有些不好，可我还有很多货要卖呢。"
D.Strings[71688]="根据我学到的专业知识，水晶的特质与德莱尼非常相似。\n\n它的核心材料有着惊人的潜力，但最初的水晶原石总是十分粗糙，而且布满瑕疵。只有通过精心打磨和培育，它的潜力才能完全发挥出来。\n\n然后，它才能展现出惊人的美丽与澄澈。"
D.Strings[71689]="贪婪的血喉被放出了笼子！"
D.Strings[71690]="指挥官！影月氏族的大军正在要塞外面集结。我们的部队已经进入防御阵地，等候你的指令。"
D.Strings[71691]="他才刚刚开始呢！"
D.Strings[71692]="你是个不错的消遣，但没有人能阻止破坏者！"
D.Strings[71693]="别让我失望，布尔高，你抵得上一百个食人魔战士！"
D.Strings[71694]="绞肉时间！"
D.Strings[71695]="生猛鲜甜！"
D.Strings[71696]="美味多汁！"
D.Strings[71697]="好险啊。"
D.Strings[71698]="已经没有回头路了。我们只能继续前进，从那头野兽的嘴巴里穿过去。"
D.Strings[71699]="来啊，你们这些皮包骨头的强盗！"
D.Strings[71700]="一点肉都没有。"
D.Strings[71701]="可以炖一锅白鬼汤了。"
D.Strings[71702]="干巴巴，臭烘烘的小东西！"
D.Strings[71703]="下去！我都懒得吃你。"
D.Strings[71704]="只要切掉脑袋！"
D.Strings[71705]="让血流出来！"
D.Strings[71706]="看来肉已经上菜单了！"
D.Strings[71707]="谢谢你救了我，伙计！我就知道我们不该坐着造了一半的飞艇出来的。"
D.Strings[71708]="如果你没问题，那我就出发了。"
D.Strings[71709]="你总算来了。这地方太臭了，让我们快点搞定这一切吧……"
D.Strings[71710]="谢谢！真高兴能看到一张没有长满真菌的脸！"
D.Strings[71711]="谢谢你救了我，伙计。这场坠毁事故真是太可怕了。"
D.Strings[71712]="真是一场超超超、超级壮观的大爆炸！要是我没在爆炸范围内就更好了。"
D.Strings[71713]="我身上所有的骨头好像都摔断了。连那些叫不上名字的骨头好像都断了！"
D.Strings[71714]="山脉之心狂暴了！"
D.Strings[71715]="让狂风毁灭你！"
D.Strings[71716]="战歌氏族会消灭你的！"
D.Strings[71717]="我要把你的骨头抛进风里！"
D.Strings[71718]="我就是风暴！"
D.Strings[71719]="战歌必胜！"
D.Strings[71720]="我的力量将毁灭你！"
D.Strings[71721]="掌握虚空！感受深入你们骨髓深处的力量吧！"
D.Strings[71722]="啜饮虚空之力，兄弟姐妹们！战歌氏族正在壮大！"
D.Strings[71723]="有了这份黑暗的恩赐，无人能挑战战歌氏族的霸权！"
D.Strings[71724]="施展虚空之力！战歌氏族的力量无人能挡！"
D.Strings[71725]="弱者毫无荣耀可言！让自己沐浴在黑暗之力中，变得强大吧！"
D.Strings[71726]="让这份黑暗的恩赐在你们的血脉中流淌！感受它在体内壮大的滋味！"
D.Strings[71727]="你们都是软弱的凡人！饮下虚空能量，你们就将被赐予力量！"
D.Strings[71728]="掌控虚空之力！召唤这份恩赐，实现你们真正的命运！"
D.Strings[71729]="噢，太好了，指挥官你来了。这个“东西”归你处置了。"
D.Strings[71730]="篡位者！我才是利爪之王！"
D.Strings[71731]="塞泰之血是一种恩赐，而非诅咒！我们要让所有人都明白这一点！"
D.Strings[71732]="泰罗克……"
D.Strings[71733]="塞泰克必将崛起！"
D.Strings[71734]="为了利爪之王艾吉斯！"
D.Strings[71735]="我看到了彼岸的世界……"
D.Strings[71736]="鲁克玛抛弃我们了。"
D.Strings[71737]="你们的生命将成为献给塞泰的祭品。"
D.Strings[71738]="艾吉斯需要祭品！"
D.Strings[71739]="我们的生命属于塞泰！"
D.Strings[71740]="潜行与速度是我们最好的朋友。"
D.Strings[71741]="我的游侠最擅长埋设陷阱和制造伪装。影月氏族完全不知道我们在这里。"
D.Strings[71742]="影月氏族是一个古老的兽人氏族，掌握着无数有关这个世界的知识和秘密。要是我们能拿到他们的记载就好了！"
D.Strings[71743]="关于我们德莱尼，你必须搞清楚一点。$B$B我们很乐于学习其他民族的知识，并让它们为我所用。"
D.Strings[71744]="臣服于塞泰克吧！"
D.Strings[71745]="谁能想到，德莱尼会在他们的神殿里面藏着这么……美味的宝物呢？"
D.Strings[71746]="你们敢挑战我吗，奥金顿的守护者们？！"
D.Strings[71747]="粉碎我身上的枷锁……传送门就会崩溃……"
D.Strings[71748]="如此堕落……它将化为火海。"
D.Strings[71749]="格罗玛什将为他的傲慢付出代价。"
D.Strings[71750]="燃烧军团已经降临……我们将痛快享用这些灵魂。"
D.Strings[71751]="别拖拉了，凡人。我能感觉到你们部队的生命力正在减弱。你以后会后悔的……"
D.Strings[71752]="后会有期……$n。"
D.Strings[71753]="古尔丹，多么愚蠢。这份恩赐……比你想象中更强大……"
D.Strings[71754]="我已经等了太久……"
D.Strings[71755]="……还要……更多……"
D.Strings[71756]="一边是我们的敌人——战歌氏族。另一边，是我们古老的宿敌——悬槌食人魔。$B$B我们必须制裁这两者。我们必须将他们赶出纳格兰。"
D.Strings[71757]="而现在，万物都将臣服于我！"
D.Strings[71758]="这力量……你们将是第一批有幸见识它的人。"
D.Strings[71759]="伊露恩……你一生都在与恶魔战斗……可死后，你的力量将成为它们的养料。"
D.Strings[71760]="乔拉，秩序的化身……我要扭曲你的灵魂，成为毁灭的力量之源！"
D.Strings[71761]="艾鲁姆……你当了一辈子治疗者，现在，你将成为疾病和腐朽之源！"
D.Strings[71762]="万物都将臣服于我。"
D.Strings[71763]="畏惧我的威名吧。"
D.Strings[71764]="我……将会……更伟大！"
D.Strings[71765]="快，马上！"
D.Strings[71766]="更多！我……还要……更多……"
D.Strings[71767]="束缚被削弱了。我就要自由了！"
D.Strings[71768]="古伊尔觉得我应该留在艾泽拉斯照顾我们的孩子。我很能理解他在这件事上的立场。$B$B但我和我的古伊尔一起经历了许多困难。现在这种情况下，我们更不应该分开。$B$B在经过那么多事之后重返这个时代的纳格兰。我们两个都有些情难自抑。$B$B我现在只希望我们俩能在这一切都结束后快点回到我们的孩子们身旁。"
D.Strings[71769]="你和暗影猎手们要将战歌氏族逐出塔拉，这是大地母亲的旨意。"
D.Strings[71770]="所有人——寻找掩体！"
D.Strings[71771]="我们必须击败食人魔，火刃氏族以及洛克拉斯的兽人。然后，我们就得准备向格罗玛什尔进发了。"
D.Strings[71772]="说得好像我们在纳格兰只要对付战歌氏族和悬槌食人魔一样。$B$B在那条河的另一边，完全是一个修罗场。"
D.Strings[71773]="小心，指挥官。虽然我们胜利了，但战歌氏族绝对不容小觑。"
D.Strings[71774]="我要把你们的肉一片片割下来！"
D.Strings[71775]="我们要拿你们的尸体去喂卡利鸟！"
D.Strings[71776]="跑快点，爬虫！"
D.Strings[71777]="你们的末日到了。"
D.Strings[71778]="你们快不过狂风！"
D.Strings[71779]="只要我们还统治着天空，谁也别想反抗我们！"
D.Strings[71780]="我们要把你们这些被遗弃的杂种扔下去！"
D.Strings[71781]="你不配站得这么高，回到肮脏的地面去！"
D.Strings[71782]="多么滑稽的小鸟，你都没有翅膀！"
D.Strings[71783]="把他们扔下去，让下面的食腐鸟吃掉他们！"
D.Strings[71784]="仆从们，保护你们的主人！"
D.Strings[71785]="我们展翅……高飞……"
D.Strings[71786]="只要我们还统治着天空，你们就永远是下等人！"
D.Strings[71787]="见证鸦人的力量吧！"
D.Strings[71788]="我的兄弟姐妹们会在阴影中监视的，只要有机会，我们就会来帮你。"
D.Strings[71789]="那些可怜的淡水兽……"
D.Strings[71790]="塞林？你在这里做什么？"
D.Strings[71791]="这个蠢货暴露了我们的位置，还引来了一头原祖荆兽。"
D.Strings[71792]="没事的，吉德文。你会好起来的。"
D.Strings[71793]="如果我能做什么来报答你的话，请尽管开口。"
D.Strings[71794]="如果你打算去平原上闲逛的话，最好小心点，旅行者。风牙狼崽子们最近变得特别危险。"
D.Strings[71795]="算那些植物走运，我刚巧没带剪刀……"
D.Strings[71796]="到刃月密林里来找我吧。是时候结束这一切了。"
D.Strings[71797]="我听说佐卡拉和她的追随者们险之又险地躲过了兽人的追捕，逃入了塔拉多。"
D.Strings[71798]="或许我们可以把赌注押在艾吉斯身上……"
D.Strings[71799]="这些有关毒素和瘫痪的对话对我的销售毫无帮助。吉德文有时候真是太粗鲁了。"
D.Strings[71800]="嘿，你想在出发前买一些针尾蜻蜓眼药水吗？它对夜间阅读很有好处，而且几乎不会致盲。"
D.Strings[71801]="胡扯！要我向那个疯子下跪，我宁可早点去死。"
D.Strings[71802]="这是谁呀？一个英雄？戈尔隆德可不是逞英雄的地方，我的朋友。"
D.Strings[71803]="然后呢？加入艾斯卡的傻瓜军团，起来反抗信徒？"
D.Strings[71804]="我们只会妨碍他。"
D.Strings[71805]="我们不太习惯有这么多同伴。我们游侠所受的训练都是要求我们自给自足，并在荒野中长时间生存。$b$b你或许会发现我们中的一些人更喜欢这种方式。"
D.Strings[71806]="而现在，我们得消失了。销声匿迹，努力求生。"
D.Strings[71807]="贸然引起原祖荆兽和古魈的注意并不明智。在他们眼中，我们只是一堆肥料。"
D.Strings[71808]="啊！嘎……咔……啊！！！"
D.Strings[71809]="啊，一位来自北方的外国旅行者。来看看我的货物吧！"
D.Strings[71810]="别太久了，我可不会分给你人头！"
D.Strings[71811]="总之，你到底是怎么来到德拉诺的？"
D.Strings[71812]="哦，这个啊？我好像是搭着顺风车穿过了你要塞的传送门。\n\n现在回想起来，他们真该把那些东西再看紧一点的。"
D.Strings[71813]="他们点燃了阿卡拉兹鸦巢！"
D.Strings[71814]="它……完了……"
D.Strings[71815]="来吧，我们得走了！"
D.Strings[71816]="我失去了我的姐妹和人生导师，但我也知道还有其他人正在经受更大的伤痛。$B$B为了他们，我必须坚持下去。"
D.Strings[71817]="先知维伦是一位伟大的导师。我会永远记住他的。"
D.Strings[71818]="有太多事要做了。我们得集中精神。"
D.Strings[71819]="我非常感谢你能在这里，$n。你是少数我能信赖的人之一。"
D.Strings[71820]="贸易是安波里村的支柱产业。作为我们村的商人代表，我的责任就是确保商业运转流畅。"
D.Strings[71821]="天空中隐藏着无数奇迹等待人们的发现。我们的研究员就在瞭望台上研究星辰和其他课题。\n\n旅行者，如果你有时间的话，我建议你上去看看。"
D.Strings[71822]="安波里牧场饲养的雷象和塔布羊满足了沙塔斯和许多小型德莱尼村庄的需求。\n\n如果你想看看那些家畜，可以在村子外围找到那些牧场。"
D.Strings[71823]="请别介意这些噪音和尘土，指挥官。$B$B我能为你做点什么吗？食物？饮料？或是一个歇脚的地方？"
D.Strings[71824]="愿纳鲁祝福你，我的朋友。$B$B重返德拉诺，这种感觉很古怪不是吗？我从没想过自己还会回到这里。"
D.Strings[71825]="……失落的幽魂消散了。"
D.Strings[71826]="一名|c00FFFF00|Hspell:178360|h[联盟队长]|h|r加入了战斗。"
D.Strings[71827]="一名|c00FFFF00|Hspell:178361|h[部落队长]|h|r加入了战斗。"
D.Strings[71828]="不要失去信心，联盟的战友们，我会帮助你们的。"
D.Strings[71829]="等我抓住他之后……"
D.Strings[71830]="让我们看看谁能笑到最后吧。"
D.Strings[71831]="变戏法的蠢货！我才是这个传送门的钥匙。"
D.Strings[71832]="放了我，否则你的宝贝世界将化为火海。"
D.Strings[71833]="古尔丹！卡德加——他们把古尔丹关在这里了。"
D.Strings[71834]="他被锁链绑住了。"
D.Strings[71835]="很好！那是他应得的下场。对他说的话，一个字也别信。"
D.Strings[71836]="啊，通天峰。我已经很多年没有这么靠近过她了。"
D.Strings[71837]="高阶贤者身边守卫森严。我们不能再飞近了。"
D.Strings[71838]="摧毁他们的假太阳，让我们在阴影中再次相见。"
D.Strings[71839]="骨头不会说谎。它们向我展示了烈焰，以及一片虚无！"
D.Strings[71840]="预兆已经很清晰了！斯克提斯完了！"
D.Strings[71841]="罪人，我们都是罪人！匍匐在鲁克玛脚下，乞求净化之火的救赎吧！"
D.Strings[71842]="鲁克玛！听听你绝望的子民们的呼号吧！祈祷吧，让我们摆脱这卑贱的躯壳吧。"
D.Strings[71843]="什么？啊啊啊啊啊啊啊！"
D.Strings[71844]="地精！你最好快点干完。铁路主管箭火就快要修好恐轨了。"
D.Strings[71845]="得了吧，你们这些小鬼。我最讨厌别人妨碍我工作了！"
D.Strings[71846]="你错了。是火刃氏族不配得到我的忠诚。"
D.Strings[71847]="吃吧，你们这些蠢货。全给我吃光！"
D.Strings[71848]="别再把那玩意儿滚来滚去了，吃掉它！"
D.Strings[71849]="中士，一头戈隆正在冲向我们的要塞。再过几分钟，它就要到了！"
D.Strings[71850]="站起来，霜狼们！为被害的酋长复仇，夺回霜狼氏族的荣耀吧！"
D.Strings[71851]="来吧，兄弟姐妹们！我们要为死去的同胞伸张正义，将这些兽人送入黑暗的地狱！"
D.Strings[71852]="既然戈隆来了，那鬣蜥人也不远了。快，让劳工们都躲到高地上去！"
D.Strings[71853]="我们没多少时间了！所有人，上高地！"
D.Strings[71854]="终于自由了。"
D.Strings[71855]="我用我父亲的灵魂发誓，我要让他们付出代价。"
D.Strings[71856]="啊，噢！"
D.Strings[71857]="这下好了。"
D.Strings[71858]="我就说我们会发挥作用的。"
D.Strings[71859]="真菌怪物还在不断爬进来，而我们就要不断烧死它们。就好像天天都在庆祝火焰节一样。我喜欢这样！"
D.Strings[71860]="你是来灭火的还是来干嘛的？"
D.Strings[71861]="伊莲娜是个好姑娘。我肯定她正在悠然自得地对付那些食人魔呢。"
D.Strings[71862]="很高兴见到你，狼之$g兄弟:姐妹;。$B$B距离我上一次踏入伟大的凛风之地，已经过去许多年了。但有些东西从未改变。$B$B战歌氏族还是那么卑劣。自从加尔鲁什·地狱咆哮当上他们的新督军之后，情况就更糟糕了。$B$B我知道你以前就跟他有过节。我们应该想办法解决掉他。$B$B萨尔整天都把制裁加尔鲁什挂在嘴边。"
D.Strings[71863]="这真是太卑鄙了，$n。经过这件事之后，我恐怕永远也不会原谅你和伊瑞尔了。$B$B……$B$B哈，我这是在骗谁啊？我想我是在自讨苦吃。$B$B这真是个不错的恶作剧，你觉得呢？$B$B我得想想下一次该捉弄谁。一定要找个看不穿我的人。"
D.Strings[71864]="她来了……"
D.Strings[71865]="……等等……"
D.Strings[71866]="噢，这真是世上最美丽的景象，不是吗？"
D.Strings[71867]="嘲颅兽人的战斗技巧在于将敌人捅死的同时保持嘲讽的笑容。"
D.Strings[71868]="你负责战斗，我负责修理。现在，让我们登上那辆坦克吧！"
D.Strings[71869]="我回想了一下，我们应该可以用那些铁链爬上去。"
D.Strings[71870]="我看见控制台了！"
D.Strings[71871]="干掉右前方的兽人！"
D.Strings[71872]="看来我们来的正是时候。"
D.Strings[71873]="$n！跳到那个炮台里去，别让他们靠近！"
D.Strings[71874]="我该如何获得材料？"
D.Strings[71875]="嘿……我可是个多才多艺的地精。我可以用几乎任何东西来造房子。如果你能在野外找到宝藏，或者某些邪恶怪物掉落的战利品，也或许能获得对我有用的额外材料。$b$b我已经听说这附近的各种珍稀野兽可能收藏着对你有用的材料。何况我敢打赌，塞娜小姐肯定从她经手的材料中偷偷克扣了不少，而且就藏在你的要塞附近。$b$b快出去找找吧。"
D.Strings[71876]="战歌氏族，出发。"
D.Strings[71877]="嗯？一个旅行者？要知道，现在进入斯克提斯可是非常危险的。"
D.Strings[71878]="阿兹克派你来向我寻求答案，我保证会给你一个满意的答复。$B$B但现在，我们得先逃跑了。"
D.Strings[71879]="指挥官$N。骑兵出击。"
D.Strings[71880]="你想知道我的族人为什么会逃离阿兰卡？看看外面吧。因为这个诅咒，我们自己的同胞都在畏惧并辱骂我们。"
D.Strings[71881]="沃舒古的山峰俯瞰着纳格兰的山谷。这里是所有兽人氏族的圣地，可现在战歌氏族却想将它据为己有。"
D.Strings[71882]="动点儿真格的，否则他们会让食人魔淹没这个地方的。"
D.Strings[71883]="这回算你赢了。可等我们在“真正”的竞技场里战斗时，我一定会干掉你的。"
D.Strings[71884]="你……是来救我的？哈。"
D.Strings[71885]="你究竟是来救人还是来挑战的？"
D.Strings[71886]="挑战角斗士。"
D.Strings[71887]="跟我说说保卫雄狮港的故事吧。"
D.Strings[71888]="跟我说说保卫统御岗哨的故事吧。"
D.Strings[71889]="拿起武器！各就各位！注意脚下。他们会从地下发起攻击……"
D.Strings[71890]="告诉阿卡尼，我会等着她的信号的。"
D.Strings[71891]="我看到阿卡尼在你的衣服上做了一个记号。这么说，逃跑的时机终于来了吗？"
D.Strings[71892]="跟我战斗。别让食人魔看出弱点。"
D.Strings[71893]="够了！这又不是真正的竞技场。"
D.Strings[71894]="死吧，死吧，死吧！"
D.Strings[71895]="我等着阿卡尼的信号。"
D.Strings[71896]="终于自由了！你完成之后，就到食人魔的高地上来，我们要一起干掉食人魔酋长。"
D.Strings[71897]="你救了我的命，我一定要偿还这份恩情。我会教给你只在斯克提斯最黑暗的角落里传播的战斗技巧。"
D.Strings[71898]="你手里的武器真是个可爱的玩具。让我们看看它能不能接住我的兽人铁拳吧！"
D.Strings[71899]="我会大笑着面对失败！"
D.Strings[71900]="你管这叫战斗风格？哈哈哈！"
D.Strings[71901]="哦，是的，我想我可以等她的信号。"
D.Strings[71902]="回到阿卡尼那里去吧，告诉她我要撕碎这个地方，将它烧成废墟，并对着所有食人魔的尸体畅快大笑！"
D.Strings[71903]="你知道我最恨竞技场哪一点吗？$b$b那些失败者！$b$b他们总是死得太快。这真是太让人难堪了。我都来不及给他们一个得体的微笑……"
D.Strings[71904]="……后退！"
D.Strings[71905]="我准备好了，指挥官。你打算从哪里开始？"
D.Strings[71906]="我就是……推土机！"
D.Strings[71907]="%s狂吼着冲上了斜坡。"
D.Strings[71908]="滚回到尘土中去吧！"
D.Strings[71909]="<这个生物还活着，但完全被钢铁部落的锁链捆住了。>"
D.Strings[71910]="解开这只生物身上的锁链。"
D.Strings[71911]="等等！饶了我，我就把知道的事统统告诉你！"
D.Strings[71912]="毁灭者神器。我们找到它了！它就在西边的独眼魔岩洞深处。在营地被捣毁前，我们正打算去把它弄到手。"
D.Strings[71913]="滚出我的视线吧。"
D.Strings[71914]="我们得走了。我已经很接近了……我必须找到它。"
D.Strings[71915]="这真是一场噩梦！"
D.Strings[71916]="谢谢你——整个矿场都被攻陷了！"
D.Strings[71917]="是共鸣水晶——它让他们都陷入了疯狂！"
D.Strings[71918]="这是谁呀？一个新的挑战者？你被我的小宠物吃掉的场面一定会非常有趣的。"
D.Strings[71919]="大法师告诉了我这一切行动的幕后黑手都是加尔鲁什。他是来自你们世界的逃犯，对吧？我以前从没见识过兽人眼中的“正义”。$B$B我很想说这一切已经结束了，但这场战争才刚刚开始。格罗玛什的钢铁部落还在不断壮大。只要他的铸造厂还在不断生产出可怕的武器，我的人民就不会安全。我们德莱尼对这场战争的开始毫无准备，但我们必须准备好结束它。$B$B我们面前阴影重重——但这只因为圣光在我们背后。"
D.Strings[71920]="一场微不足道的胜利而已。让我们看看你能不能挡住我的独眼魔吧。"
D.Strings[71921]="我们随时听候你的进军指令，指挥官。加尔鲁什和他的大军在等着我们。"
D.Strings[71922]="真是卑鄙。我要看着你被我最喜欢的宠物吞掉。"
D.Strings[71923]="那是我最喜欢的掠食者。你这个脏脏的野蛮人。我要亲手杀了你！"
D.Strings[71924]="我们的部队已经集结起来了，随时可以出击。$B$B带路吧，指挥官。让我们彻底解决这个加尔鲁什·地狱咆哮。"
D.Strings[71925]="这个加尔鲁什突然就冒了出来，像打鼓一样操纵着兽人氏族。幸好他已经完了。$B$B但伤害已经造成。我似乎都快认不出我的同胞们了。格罗玛什·地狱咆哮让亲人和朋友反目成仇，我们必须阻止他。我们要瓦解他的战争机器：首先解决他的食人魔盟友，然后捣毁黑石铸造厂。$B$B然后，我们将地狱咆哮本身绳之以法，就像我们今天所看到的那样。"
D.Strings[71926]="看起来，钢铁部落是想在这个戈隆的背脊上熔铸一门火炮。"
D.Strings[71927]="用脑子想想都知道铸铁头盔和戈隆是多么不相配了。"
D.Strings[71928]="一手装一门火炮，背上再背一堆炸药？不是在开玩笑吧？"
D.Strings[71929]="<萨尔陷入了深思，似乎暂时不想说话。>"
D.Strings[71930]="我丈夫总是把整个世界的重担扛在自己肩上，好像这是他一个人的责任似的。$B$B朋友，这个世界还处在动乱之中。元素在哭号。它们正在黑石铸造厂深处饱受煎熬，古尔丹也依然逍遥法外。$B$B我们还有太多的事情要做……而你建造的要塞就是关键。如果需要我帮忙的话，千万不要犹豫。这也是我的战争。"
D.Strings[71931]="送我去塔拉多的基地。"
D.Strings[71932]="注意信息。"
D.Strings[71933]="传说中的血吼深深插入芳草萋萋的山体中。当你触摸它时，一股几乎无法察觉的力量从斧中传出。"
D.Strings[71934]="回忆预言之石之战。"
D.Strings[71935]="快躲到护盾里来！"
D.Strings[71936]="拦住他们！我来激活这个钢铁之星！"
D.Strings[71937]="我来搞定这个！别让他们靠近我！"
D.Strings[71938]="感受下地精科技的威力吧！"
D.Strings[71939]="哎哟！你会为此付出代价的！"
D.Strings[71940]="如果你不介意高温和让人喘不过气来的潮湿的话，宾奇维斯拓殖点也不失为一个好地方。$b$b好吧，我的意思是，如果你不介意高温和让人喘不过气来的潮湿，以及到处传染的真菌的话。"
D.Strings[71941]="宾奇维斯拓殖点绝对不容有失，我必须找到治疗方法！"
D.Strings[71942]="矿井被攻陷了！"
D.Strings[71943]="指挥官，奥秘圣殿的援军到了！"
D.Strings[71944]="获取雪莉的报告。"
D.Strings[71945]="派普斯去哪儿了？这些小鬼一直在偷我的补给。$b$b噢！我原本打算去跟巴隆斯核对一下的，可我们实在太忙了。$b$b这座森林里已经快要没有木头了……我得制定一个砍伐计划。我会尽快向巴隆斯提交完整报告的。"
D.Strings[71946]="我要飞往纳格兰的边境。"
D.Strings[71947]="格挡！"
D.Strings[71948]="干得好，士兵们。"
D.Strings[71949]="我受够了。滚开！"
D.Strings[71950]="我……才是……国王……"
D.Strings[71951]="我在要塞底层等着你。"
D.Strings[71952]="你让我感到厌烦。"
D.Strings[71953]="你们惹怒我了！"
D.Strings[71954]="魔力屈从于我的意志，你们也一样！"
D.Strings[71955]="来吧，看看你们错得多么离谱。"
D.Strings[71956]="滚出我的视线。"
D.Strings[71957]="我掌握着魔力！"
D.Strings[71958]="我会在要塞底层等你。"
D.Strings[71959]="元首高维杜斯狂笑了起来。"
D.Strings[71960]="噢，拜托！只是一个小蜘蛛而已！"
D.Strings[71961]="这个小东西一直在扭动！你能来帮我一把吗？！"
D.Strings[71962]="我这儿需要帮忙，霍图斯。"
D.Strings[71963]="一只小蜘蛛？！你长眼睛了吗？"
D.Strings[71964]="不不不不！"
D.Strings[71965]="好吧，我这边也需要清理一下蜘蛛了，利维娅！"
D.Strings[71966]="我们是来寻找对付鬣蜥人的方法的，结果我跟同伴走散了。$b$b然后这些木精就冒了出来，喂我吃各种浆果、蜜酒和蜂蜜。$b$b我发誓，自从来了这里之后，我至少胖了二十磅。"
D.Strings[71967]="他们只是想把你养肥一点。你的朋友都被做成肥料喂给木精的幼苗了。"
D.Strings[71968]="救兵？总算把你盼来了！我一个水果都吃不下了。"
D.Strings[71969]="非常谢谢你。我稍后会将结果告知你的。"
D.Strings[71970]="达坎，那些零件去哪儿了？我只有两只手。"
D.Strings[71971]="祝你好运，指挥官。"
D.Strings[71972]="你想要什么，新兵？"
D.Strings[71973]="我们才是神的选民。"
D.Strings[71974]="萨格雷必将夺回本该属于我们的一切。"
D.Strings[71975]="这里将是他们发动第一波攻击的地方……"
D.Strings[71976]="欢迎，新兵。所有想要加入我们教派的人必须证明自己。你看起来……很有潜力。"
D.Strings[71977]="只要你带着萨满之石，我们就可以依靠元素的力量通话了。$b$b它还能让我通过你的眼睛来观察世界。"
D.Strings[71978]="他们来了……"
D.Strings[71979]="<拉安达压低声音，悄声说道：>$B$B你看起来像是我们的盟友，但我时间有限。我正在努力打入萨格雷，从内部瓦解他们的组织。到目前为止，还没有人怀疑我的身份。"
D.Strings[71980]="影月谷下雨了。"
D.Strings[71981]="茉德拉向你问好。"
D.Strings[71982]="雷象是自然界最高贵的动物。"
D.Strings[71983]="传送门将我送入了扭曲虚空，先知。"
D.Strings[71984]="你也这么认为，对吧？"
D.Strings[71985]="我知道了。我已经做好迎接暴风雨的准备了。"
D.Strings[71986]="我成功了，爸爸！我许了一个愿望！"
D.Strings[71987]="这个$r在这里干什么？"
D.Strings[71988]="确认中"
D.Strings[71989]="破坏传送门"
D.Strings[71990]="真正的审判日降临了！"
D.Strings[71991]="你知道自己在干什么吗？"
D.Strings[71992]="不管我们身处何地，军情七处总能完成任务。"
D.Strings[71993]="死吧，小东西！"
D.Strings[71994]="我下次必须想办法提高我的表现。"
D.Strings[71995]="练习总算结束了！尝尝我的斧头吧！"
D.Strings[71996]="瑞拉克说了不要麻烦……你就是个麻烦。"
D.Strings[71997]="我的研究！瑞拉克……需要……它……"
D.Strings[71998]="我想我还要再多练练……"
D.Strings[71999]="部落渣滓，但愿你喜欢被盾牌打脸的感觉！"
D.Strings[72000]="唔，我在奥特兰克山谷可没遇到过这种问题。"
D.Strings[72001]="你的魔法在此毫无用处。"
D.Strings[72002]="我受够你们了。"
D.Strings[72003]="你们要为此付出代价！！！"
D.Strings[72004]="为了……悬槌……"
D.Strings[72005]="你们竟敢闯进这些大厅？"
D.Strings[72006]="一文不值。"
D.Strings[72007]="你的努力是徒劳的！"
D.Strings[72008]="安静！"
D.Strings[72009]="粉碎吧。"
D.Strings[72010]="悬槌将毁灭你们。"
D.Strings[72011]="你们的攻击太弱了！"
D.Strings[72012]="我要把你撕成两半！"
D.Strings[72013]="我是这里的主宰。"
D.Strings[72014]="我们控制着这里的能量流。"
D.Strings[72015]="他们不可能只有这么点儿人。"
D.Strings[72016]="散开！保护建筑！"
D.Strings[72017]="你们休想阻止我！我会让我们的毁灭者更加强大！"
D.Strings[72018]="其他人会完成我的研究的！"
D.Strings[72019]="我要吞掉你的风系魔法！"
D.Strings[72020]="不……风系魔法？"
D.Strings[72021]="我想下达一个工作指令。"
D.Strings[72022]="我要把你们这些走狗送入虚空！"
D.Strings[72023]="等我归来之日，就是你们的死期。"
D.Strings[72024]="我已经把你的部队可以接受的任务清单都放在你的指挥台上了。$B$B为了方便起见，我可以帮你把命令传达给要塞里的部队，指挥官。"
D.Strings[72025]="我已经把你的部队可以接受的任务清单都放在你的指挥台上了。$B$B你只要动动嘴，我立刻就派信使将你的命令传达到你的要塞里去。"
D.Strings[72026]="准备好面对艾泽拉斯最伟大的勇士了吗？！"
D.Strings[72027]="这个不是鬣蜥人！"
D.Strings[72028]="呜！"
D.Strings[72029]="喔唷！"
D.Strings[72030]="这个鬣蜥人对你嘟囔了几句听不懂的话。"
D.Strings[72031]="我留意你很久了，$r。靠近点。"
D.Strings[72032]="我预见到了……你的失败。"
D.Strings[72033]="见证你的末日吧！"
D.Strings[72034]="我看到了……你在这个世界的旅程将止步于此。"
D.Strings[72035]="不久，这个食人魔堡垒就会比以前繁忙多了。$b$b让我们做点什么吧，嗯？"
D.Strings[72036]="池塘中肥大的种子和根须扎入莱拉的尸体中大快朵颐着。"
D.Strings[72037]="多亏了你，这地方终于恢复正常了！"
D.Strings[72038]="打烂你一定会很有趣。"
D.Strings[72039]="我要先摧垮你的精神，再把你像奴隶一样卖掉。"
D.Strings[72040]="你将沦为捡炉渣的奴隶！"
D.Strings[72041]="元素听从我的命令！"
D.Strings[72042]="你焦黑的尸体会是一个很好的示范。"
D.Strings[72043]="你该学会听话！"
D.Strings[72044]="你休想……获得……自由……"
D.Strings[72045]="活捉他们，罗托尔。他们可以卖个好价钱。"
D.Strings[72046]="这个死去的矮人脸上凝固着震惊的表情。"
D.Strings[72047]="这个矮人在死前似乎胖了很多。"
D.Strings[72048]="来吧，各位，快过来吧。我们还得填饱肚子呢。"
D.Strings[72049]="那个新来的！守卫，抓住他！"
D.Strings[72050]="长官，指挥官！$b$b根据玛尔拉德的命令，我已经召集了一批混混——呃——熟练工人。只要你一句话，我们马上就派这支车队去艾洛多尔弄点食物回来。"
D.Strings[72051]="很好，链爆。出发吧。"
D.Strings[72052]="嘿！你不属于这里！维克萨，快去告诉拉安达，我们中间出了个叛徒。"
D.Strings[72053]="你们真是太讨厌了。我得去睡一会儿了。"
D.Strings[72054]="没听到指挥官的话吗？出发！走了走了！"
D.Strings[72055]="指挥官！你建造的要塞令人印象深刻。我已经等不及想要看看你的人是怎么工作的了。"
D.Strings[72056]="我们太蠢了，居然跟着维伦走。索克雷萨才是我们真正的领袖！"
D.Strings[72057]="嘿，伙计，让我们谈谈你看到了什么吧。"
D.Strings[72058]="你会发现我们联盟总能带来惊喜，大主教。这位就是我跟你提过的指挥官。"
D.Strings[72059]="我们会护送这支车队到艾洛多尔跟你汇合的，指挥官。"
D.Strings[72060]="啊。这个小家伙是工头啊。"
D.Strings[72061]="我要撕裂你凡人的躯体，享用你的灵魂！"
D.Strings[72062]="不要花言巧语了。我知道自己看到了什么！"
D.Strings[72063]="事实上，我打算亲手解决你。扎玛亚肯定会因此而提拔我的！"
D.Strings[72064]="德莱尼休想获得自由！"
D.Strings[72065]="你会跟这个德莱尼一起烂掉的。"
D.Strings[72066]="除非我死了，否则你休想救走这个德莱尼，废物。"
D.Strings[72067]="你看到那家伙的体型了吗？它比我想象得还要大。"
D.Strings[72068]="它抓走了塔拉库。那个蠢货太靠近洞穴入口了。"
D.Strings[72069]="我觉得根本不可能杀死它。我是说，它是由泥土和石头组成的。"
D.Strings[72070]="你先走。"
D.Strings[72071]="好，呃……我只是想调整一下我的手套，马上就好。"
D.Strings[72072]="看来大部分地怒元素都是从这个洞穴里跑出来的。"
D.Strings[72073]="圣光在上！你真是个伟大的勇士！"
D.Strings[72074]="奥格瑞姆！我的兄弟，你都干了什么？"
D.Strings[72075]="兄弟？你和敌人、和入侵者结盟了，杜隆坦。你已经选择了敌人的阵营。"
D.Strings[72076]="你难道看不出来吗？钢铁部落会毁了德拉诺的！"
D.Strings[72077]="我看到的景象却恰好相反。"
D.Strings[72078]="指挥官，我会在前面等你的。我得去帮德拉卡了。"
D.Strings[72079]="跟我来！"
D.Strings[72080]="或许那些兽人的船上有我们能用的东西？……除了用兽牙铆接的设备。"
D.Strings[72081]="呃，这批补给大部分都被水泡坏了而且……黏糊糊的？这些东西应该有用，但说真的，它们真的很恶心。"
D.Strings[72082]="所以这个就是我们中间的叛徒。"
D.Strings[72083]="加入我吧，兄弟。维伦最大的错误就是拒绝了燃烧军团的礼物。"
D.Strings[72084]="绝不。接受基尔加丹的祝福只会让你们失去灵魂。"
D.Strings[72085]="蠢货，你的灵魂将属于我，就算你死了也得不到解脱！沙塔斯、奥金顿、艾洛多尔、卡拉波……全都将陷落！"
D.Strings[72086]="扎玛亚，杀了他！"
D.Strings[72087]="我很荣幸，大人。"
D.Strings[72088]="我一个人怎么可能完成这个任务！？坚持住，巴隆斯……坚持住。"
D.Strings[72089]="我感觉轻松多了。今晚或许可以观测一下星象了。这是一种很好的调剂。"
D.Strings[72090]="巴隆斯在找我？$b$b我一直跟我的工人待在这里……可怜的家伙，他真是忙昏头了。$b$b好吧，休息时间结束了。"
D.Strings[72091]="该回去干活儿了。"
D.Strings[72092]="理智点，老朋友。你必须停止这种疯狂的行为！"
D.Strings[72093]="战争不是讲理智的时候。副官，解决他们。"
D.Strings[72094]="在……*咳嗽*……这儿……"
D.Strings[72095]="建造兵营花不了多少时间。跟我来，指挥官。"
D.Strings[72096]="钢铁部落已经登上了这片海滩。而我们的任务就是让他们后悔这么做。"
D.Strings[72097]="目前为止，萨格雷还没有发现我们的存在。让我们保持下去吧。"
D.Strings[72098]="一个|cFFFF0404%s|r从深渊中冲了出来！"
D.Strings[72099]="我们刚来时带来的那点补给都被难民用完了。\n\n但愿我们能尽快离开这里，否则我们就会像他们一样被困在奥金顿里了。"
D.Strings[72100]="我们剩下的大部分建筑都需要比较长的时间来建造。"
D.Strings[72101]="这座兵营看起来很棒。你可以跟玛尔拉德进去检查一下。我要出去欣赏我的手艺了。"
D.Strings[72102]="我们必须尽快赶去沃舒古。"
D.Strings[72103]="战歌萨满已经背弃了他们的传统，$n。做你应该做的事吧。"
D.Strings[72104]="小心那些仪式的主持者。他们的力量之源虽然堕落，但并不弱小。"
D.Strings[72105]="等你进入扭曲虚空之后，就用萨满之石与我联络吧。"
D.Strings[72106]="小心点，指挥官。如果这些白鬼兽人真的存在，天知道他们会有怎样的力量。"
D.Strings[72107]="我不知道白鬼是从哪里学会奴役元素的。但我们不能让他们继续下去了。"
D.Strings[72108]="这些白鬼兽人听起来很危险。但愿这是我们最后一次见到这些家伙了。"
D.Strings[72109]="去找到这个格雷希尔，让他从哪儿来的回哪儿去！"
D.Strings[72110]="到先祖之地去吧，找出那里骚乱的原因。"
D.Strings[72111]="虚空怪物的力量和数量正在增长。我们必须阻止它们。"
D.Strings[72112]="扭曲虚空内打开了无数传送门。我们必须尽快关闭它们！"
D.Strings[72113]="在面对伊瓦里杜斯时，千万不要心慈手软，你的仁慈不会有任何回报。"
D.Strings[72114]="你还好吗？欢迎来到德拉诺最好的修理厂。$b$b如果你想修理三轮车、改装跑车、伐木机、火焰喷射器或火箭车的话，那找我们就对了！$b$b事实上，我们已经垄断了这个市场。"
D.Strings[72115]="从扭曲虚空回来找我吧，我们得再谈谈。"
D.Strings[72116]="纳鲁……已经奄奄一息了！快，你必须阻止古加尔，否则就迟了！"
D.Strings[72117]="我需要一块新的萨满之石。"
D.Strings[72118]="在这儿呢！"
D.Strings[72119]="国王说你会救我们出去的！"
D.Strings[72120]="我们愿意为你而战！"
D.Strings[72121]="为了老国王，为了新国王！"
D.Strings[72122]="我们会帮你的，因为你帮了我们！"
D.Strings[72123]="这是我们解脱的出路！"
D.Strings[72124]="这可以拯救我们的灵魂！"
D.Strings[72125]="我们不能在这里久留。很快，整个钢铁部落都会来追杀我们的。"
D.Strings[72126]="我们的勇士$n，将留下来骚扰敌人的营地。其他人就去找穿越丛林的安全路径。"
D.Strings[72127]="好好打，$n。"
D.Strings[72128]="要想对付老重拳，光靠几个爱吹牛的大地生物可不够！"
D.Strings[72129]="别问我们是怎么找到那个神器的。那可不是什么愉快的故事。"
D.Strings[72130]="入侵者！保护莫库克，你们这些蠢货！"
D.Strings[72131]="巫师领主需要你们！进攻！"
D.Strings[72132]="你休想伤害莫库克！"
D.Strings[72133]="小心，恶魔随时可能再次发动袭击。看来暗影议会为了攻破奥金顿的大门，已经不择手段了。\n\n我们必须保持警惕！"
D.Strings[72134]="燃烧军团的威胁比联盟和部落大得多。哪怕是不情愿，我们也必须搁置分歧，以防止历史重蹈覆辙。"
D.Strings[72135]="雷米尔跟我说了他的族人的故事。我们的共同点比旁人想象中要多得多。"
D.Strings[72136]="我们必须制止萨格雷。"
D.Strings[72137]="塔布羊和雷象是德拉诺赐予我们的礼物。我们应该只在不得已时才取用它们，并在有能力时尽快回馈自然。"
D.Strings[72138]="以主人之名，干掉他们！"
D.Strings[72139]="不留活口。烧死所有活物！"
D.Strings[72140]="这个世界必将化为灰烬！"
D.Strings[72141]="你将面对主人的熊熊怒火，蠢货。"
D.Strings[72142]="一个不留。杀光他们！"
D.Strings[72143]="好好欣赏燃烧军团的恐怖力量吧。"
D.Strings[72144]="你们这些蠢货，这个世界已经完了。"
D.Strings[72145]="是的……来吧。迎接你的死亡吧。"
D.Strings[72146]="好了，伙计们，休息时间结束了。"
D.Strings[72147]="我叔叔就在宾奇维斯拓殖点，但愿大家一切都好。"
D.Strings[72148]="记住，秘语是：“影月谷下雨了。”"
D.Strings[72149]="好吧，好吧。"
D.Strings[72150]="这个地方既适合造兽栏又适合造坦克工厂。只要你做出选择，我就能给你造出来。"
D.Strings[72151]="如果你不懂得运用自己的力量，那么力量就毫无用处了。"
D.Strings[72152]="光消灭你的敌人并不足以赢得战争。如果不能保护好自己的人民，那你永远成不了胜利者。"
D.Strings[72153]="如果我们的领袖压制了哪怕一个德莱尼的声音，我们伟大的文明也就无以为继了。"
D.Strings[72154]="纳鲁用圣光祝福了德莱尼人民。愿它指引你的道路，慰藉你的心灵。"
D.Strings[72155]="元素可以提供无穷的力量，但也一定会让那些无法保持平衡的人走向毁灭。"
D.Strings[72156]="领袖的力量取决于他最弱小的追随者。胜利的关键在于让最底层的士兵变成伟大的战士。"
D.Strings[72157]="德拉诺的潜力就藏在每一块石头之中。只要小心运用，它就永远不会衰弱。"
D.Strings[72158]="嘿，你来得正是时候！"
D.Strings[72159]="我的合同里只提到了烧死真菌、修理引擎和打捞工作。这上面可没说还要对付虫子！"
D.Strings[72160]="你好，新兵。我能为你做些什么？"
D.Strings[72161]="我再也不溜到其他马车上去了。我发誓！"
D.Strings[72162]="你的潜入任务进展如何？要想深入敌后，你一定要穿上萨格雷的伪装服。$B$B你可以从死掉的萨格雷敌人身上收集兜帽、长袍和软鞋来做一套伪装。"
D.Strings[72163]="联络中"
D.Strings[72164]="你赢得了我最大的敬意，指挥官。我愿意追随你直到生命的尽头。"
D.Strings[72165]="一些大型恶魔可以比较迅速地破坏我们的弩炮。\n\n如果我的生产速度赶不上他们的破坏速度，那就没人能阻止暗影议会了。"
D.Strings[72166]="|TInterface\\Icons\\inv_misc_embers.blp:20|t%s彻底脱水，造成了|cFFFF0404|Hspell:164275|h[脆弱表皮]|h|r效果！"
D.Strings[72167]="%s吸收了足够的水分，又活跃了起来！"
D.Strings[72168]="一只失控蔓生吸收了附近的小水滴，活了过来！"
D.Strings[72169]="用指挥台为奇娅娜指派任务。"
D.Strings[72170]="星坠岗哨并不远。祝你好运，奇娅娜。"
D.Strings[72171]="上去拖住那只原祖荆兽。我会尽快让这门火炮开火的！"
D.Strings[72172]="踢"
D.Strings[72173]="但愿你是对的。死者正越来越……恐惧。某个真正黑暗的存在即将到来。"
D.Strings[72174]="呃，指挥官，自从跟了你之后，我的人生就变得相当刺激了。$b$b我看到你弄到了那个原祖荆兽神器。给，拿上这些种子和水，把它们带给主岗哨的玛尔拉德。$b$b与此同时，我们会帮塞林让他的坦克动起来的。"
D.Strings[72175]="我可以自己去你的要塞。为荣耀而战。"
D.Strings[72176]="大主教，让你的缚魂者们到我的营地来见我。我要在塔隆戈尔放出更多恶魔前阻止他。"
D.Strings[72177]="我们必须在德拉诺像其他世界那样陨落之前阻止塔隆戈尔。"
D.Strings[72178]="我知道我们与德莱尼之间的关系经历了许多困难，但现在，这些士兵需要我的帮助。 \n\n要想击败暗影议会，我们就必须团结一致。"
D.Strings[72179]="我们必须保持警惕。这里到处都是食人魔。"
D.Strings[72180]="别担心，$n。我们会掩护你的！"
D.Strings[72181]="叶之影遮蔽了我们的位置，不让塔隆戈尔发现。而他的部队也还没有离开古尔罗克去对奥金顿发动最后的总攻。我们还有机会打他个措手不及。"
D.Strings[72182]="他们太强大了，我们不能正面进攻。瑞斯塔兰最了解这个地区。我相信他已经有计划了。"
D.Strings[72183]="众光之光，请庇护我们不受心怀恶意者的伤害。"
D.Strings[72184]="请让我们远离黑暗，用你的光辉照耀我们。"
D.Strings[72185]="让我们远离黑暗之王。保护我们的人民远离邪恶之影。"
D.Strings[72186]="我们是圣光的孩子。我们别无所求，只想得到和平与安宁。"
D.Strings[72187]="你不是一个人。圣光会赐予我们力量的！"
D.Strings[72188]="我们被圣光团结到一起。我们将并肩战斗。"
D.Strings[72189]="今天，我将偿还自己的罪孽。我来控制传送门。"
D.Strings[72190]="安葛洛什的渣滓们！冲我来！"
D.Strings[72191]="莉亚德琳，我抓住它了。快干掉它！"
D.Strings[72192]="我们走。他们已经穿过那座传送门了。"
D.Strings[72193]="谢谢你帮我包扎！既然你救了我，我也想给你一个建议作为回报——离宾奇维斯拓殖点远点。"
D.Strings[72194]="宾奇维斯拓殖点到处都是被感染者，我……我觉得那个镇子已经完了。"
D.Strings[72195]="宾奇维斯拓殖点彻底完了。我们只遇见了一个似乎没有被感染的人，可在与他取得联系前，我们的飞艇就失控了。"
D.Strings[72196]="那个声音在召唤我们前往沃舒古……而我的祖先曾经做出响应。而我们，迟早也将别无选择地响应它。"
D.Strings[72197]="看到你在加洛克临终前让他得到安息，我感到非常欣慰。我们会永远感激你的善良与勇敢的。"
D.Strings[72198]="这些朝圣者从德拉诺各地涌来，聆听埋葬在奥金顿内的灵魂们的智慧。对德莱尼来说，这种智慧将带来巨大的回报。"
D.Strings[72199]="暗影议会的散兵游勇已经将许多旅行者困在了奥金顿里。\n\n除非战局扭转，否则我们可能永远离不开这个地方了。"
D.Strings[72200]="你这个傻大个！别把我的东西都砸坏了！"
D.Strings[72201]="那是我全部的炉石卡牌了！"
D.Strings[72202]="啊！那是我最后一个主动式负载平衡器了！你知道这些东西有多难弄到手吗？"
D.Strings[72203]="嘿，傻大个！要是我把你的东西都砸烂了，你会怎么想？！"
D.Strings[72204]="我们的补给已经快用完了，但难民还在不断涌来。这种情况维持不了多久。"
D.Strings[72205]="遵命，头儿。"
D.Strings[72206]="这些巨型防护水晶只是尤鲁恩矿井出产的水晶的众多用途之一。\n\n暗影议会居然强迫我们将它们全部用于战争，这真是太遗憾了。"
D.Strings[72207]="就是它了，士兵们。让指挥官为你们骄傲吧。"
D.Strings[72208]="送我去沃舒古附近的幽魂林地。"
D.Strings[72209]="小蓝人，你们已经证明了自己，可以躲过我的怒火。"
D.Strings[72210]="小红人，是的，他们将见证我的毁灭之力！"
D.Strings[72211]="这是伏击——是影月兽人。他们迂回包抄过来，发动了一场屠杀。"
D.Strings[72212]="我回来了！贱民们，臣服于伟大的食人魔帝国吧！"
D.Strings[72213]="我们打不过他们的。我们只是农夫！我们连武器都没有！"
D.Strings[72214]="真是没信心啊。把你的镰刀给我。睁大眼睛看看圣光带来的奇迹吧。"
D.Strings[72215]="送我去影月谷。"
D.Strings[72216]="沃舒古山曾是一个祥和神圣的地方。"
D.Strings[72217]="在克许哈格祭典期间，各大氏族会齐聚在圣山脚下举行庆祝仪式。"
D.Strings[72218]="现在，克许哈格祭典已经成为回忆了。战歌氏族将沃舒古据为了己有。"
D.Strings[72219]="特里西娅是个好士兵，可她完全被毒药控制了。我别无选择。 \n\n但愿我们能将暗影议会从德拉诺连根拔起。我们的人民应该获得比这更好的结局。"
D.Strings[72220]="这里的空气中弥漫着黑暗的臭气……和我记忆中完全不同。"
D.Strings[72221]="<发出了虚弱而低沉的呻吟>"
D.Strings[72222]="我们的力量不足以复活这棵古树，可我们会不断尝试的。你愿意帮助我们吗？"
D.Strings[72223]="我们来自月光林地。你去过那里吗？每年到了这个时候，那里的景色简直太棒了。"
D.Strings[72224]="在这个古怪的世界里，我们一直无法变形成乌鸦。但我听传言说，使用神器的力量可以让我们在这里施展乌鸦变形。"
D.Strings[72225]="我要驾着坦克到西南方去了。我会试着请一位游侠来给我做向导。"
D.Strings[72226]="我看见……一个美味多肉的$c……你喜欢眼前所看到的一切吗？古加尔教会了我们许多东西……"
D.Strings[72227]="对……靠近点，$c……到洞穴深处来，我会向你展示白鬼的真正力量！主人对我们好极了……"
D.Strings[72228]="主人让我们变得强大……看看他的恩赐吧！"
D.Strings[72229]="谨遵主人的命令！"
D.Strings[72230]="来吧，我们得马上过去！"
D.Strings[72231]="我们早就在等待这一刻。岩石的真正力量终将实现！（无人能够生还。我们就是死神！消灭他们！湮没这个世界！）"
D.Strings[72232]="凝视深渊吧。（它看见你了！它知道！）"
D.Strings[72233]="你的世界将被黑暗吞噬！（众生都将聆听它的召唤！）"
D.Strings[72234]="死亡降临了！（我们对此深信不疑。）"
D.Strings[72235]="末日临近了！（这就是我们的目标！）"
D.Strings[72236]="拥抱死亡。"
D.Strings[72237]="融入黑暗。"
D.Strings[72238]="它来了……（你们逃不了……）"
D.Strings[72239]="让黑夜吞噬我们！（我们胜利了！这一切早有预言！）"
D.Strings[72240]="你的俘虏跟我是一伙的。他对你的人民没有恶意。"
D.Strings[72241]="我们将披着午夜的斗篷划过燃烧的天空。"
D.Strings[72242]="让那个俘虏走。它的主人获得了我们的认可。"
D.Strings[72243]="给，宾奇维斯小姐！"
D.Strings[72244]="你来的正是时候！过来，加兹维茨。"
D.Strings[72245]="遵命，女士。"
D.Strings[72246]="当然是监督你啦。现在，快行动起来吧！"
D.Strings[72247]="卡德加让我们去吸引基尔罗格之眼的注意力。"
D.Strings[72248]="你准备好之后就可以出发了，长官。"
D.Strings[72249]="我会让部队做好准备，接受你的检阅的，指挥官。"
D.Strings[72250]="我会先走一步，确保部队做好接受检阅的准备。"
D.Strings[72251]="你和我两个人要对抗一整个氏族？听起来挺合我胃口的。"
D.Strings[72252]="我们在这儿呢，你们这些懦夫！来迎接我们的挑战吧！"
D.Strings[72253]="我看见你们了……"
D.Strings[72254]="我们就在你的厨房里呢，基尔罗格！来抓我们呀！"
D.Strings[72255]="我来抓你们了，入侵者……"
D.Strings[72256]="看来卡德加和其他人已经行动起来了。我们的任务马上就能完成了，勇士！"
D.Strings[72257]="我们会永远记住你的英勇事迹的，$n。我的人民在说起你的名字时，都会满怀敬意。"
D.Strings[72258]="都给我站直了，你们这些没用的野蛮人！指挥官过来了！"
D.Strings[72259]="这边走，指挥官！"
D.Strings[72260]="看到完好无损的大主教阿卡玛真是让人高兴。"
D.Strings[72261]="小心——他们过来了。"
D.Strings[72262]="快走吧。我来殿后。"
D.Strings[72263]="目前为止，我们的药物对这种蜘蛛毒素毫无作用。\n\n我们必须采集更多的样本，才能调制出有效的解毒剂。"
D.Strings[72264]="我们又为你的实验找来了一颗蜘蛛卵，特里斯。但愿它能有用。"
D.Strings[72265]="干得好，游侠。这些蜘蛛卵应该有助于调配出针对其毒素的解毒剂。"
D.Strings[72266]="立——正！我们的指挥官到了。敬礼！"
D.Strings[72267]="这边走。我对这片丘陵很熟悉。"
D.Strings[72268]="又一次袭击。他们肯定把我们当成软柿子了。哈！"
D.Strings[72269]="快把所有人都召集过来，我们得扩大工作规模了。如果你找到派普斯，请告诉我一声……他偷走了我最喜欢的一双拖鞋。"
D.Strings[72270]="我发誓，要是他又去游泳的话……他的职业道德太糟糕了。他说他弄丢了那些补给。我压根就不相信。"
D.Strings[72271]="我们就要到了。"
D.Strings[72272]="补给？什么补给？我根本不知道你在说什么。$b$b<斯克拉普的眼珠转来转去，同时紧张地清着嗓子。>$b$b什么？我没偷过任何东西……我是说，我根本不知道你在说什么。"
D.Strings[72273]="你成功了。"
D.Strings[72274]="都在这儿呢，快去给我干活儿，你们这些懒虫！"
D.Strings[72275]="血环兽人使用野蛮的鲜血魔法将他们的战士变成了异常魁梧的狂战士。"
D.Strings[72276]="听好了，小家伙们。从现在起，我们必须加紧巡逻。在指挥官视察期间，绝对不能出任何差错，明白吗？"
D.Strings[72277]="所有人，都给我打起精神来！我希望给指挥官留下一个完美无瑕的好印象。"
D.Strings[72278]="指挥官，请稍等。"
D.Strings[72279]="如果运气好的话，我们可以在他们完成转化仪式之前逃走。"
D.Strings[72280]="我们成功了！|c00FFFF00|Hspell:178358|h[范加尔]|h|r冲入阿什兰去清理那些部落渣滓了。联盟的勇士们，别让他死了！"
D.Strings[72281]="太好了。如果有机会的话，我会努力多带一点来的。Anu belore dela'na！"
D.Strings[72282]="当我们站在曾经无比强大的戈达乌的阴影下时，我能感觉到元素在哭泣。"
D.Strings[72283]="|TInterface\\Icons\\spell_holy_surgeoflight.blp:20|t %s正准备施放|cFFF00000|Hspell:153006|h[圣洁之光]|h|r。快躲开！"
D.Strings[72284]="交给我了。"
D.Strings[72285]="嘿，指挥官，你有时间吗？"
D.Strings[72286]="范加尔诞生了！此刻，他正沿着荣耀之路镶嵌推进。"
D.Strings[72287]="神器碎片内蕴藏的魔力足以让我们彻底恢复这棵古树的力量。$B$B你给我带来了多少碎片？"
D.Strings[72288]="去西北方搜索一下。我就在你身后。"
D.Strings[72289]="啊！脑袋好冷啊！"
D.Strings[72290]="噢！脑袋冻住了！"
D.Strings[72291]="还有许多伤员需要我的帮助。不能再浪费时间了。"
D.Strings[72292]="部落击杀了|c00FFFF00|Hspell:178358|h[范加尔]|h|r！"
D.Strings[72293]="他死了？呼……干得好，指挥官。我会留下来应付那些残兵的。"
D.Strings[72294]="这片丛林里没有拜神者和金属匠的位置。你们需要我的帮助才能生存下来。"
D.Strings[72295]="唔。只要你能坚持，我没意见。"
D.Strings[72296]="我到前面去排查一下陷阱，指挥官。"
D.Strings[72297]="我到前面去看看还有没有埋伏的兽人，指挥官。"
D.Strings[72298]="我们要把钢铁部落赶出卡拉波，先知维伦把这个任务交给了我。我可以应付这片丛林。"
D.Strings[72299]="你为什么要跟我们同行呢，卡尔娅？既然我们对你是个累赘，你干嘛不让我们乘坐自己的坦克呢？"
D.Strings[72300]="游侠从不抛下任何同伴。"
D.Strings[72301]="噢，真恶心！好吧，它和我想象中的不太一样。"
D.Strings[72302]="嘿，你看起来没有被感染。你一定就是我侄女提起过的那个$G家伙:女士;。快过来！"
D.Strings[72303]="看，虚空之神已经诞生！（你们这些蠢货已经迟了！）"
D.Strings[72304]="可惜我不能留下来欣赏你们的灭亡了。（我们要去悬槌堡！）"
D.Strings[72305]="你可以在任何一棵树下找到那些浆果。"
D.Strings[72306]="新来的宝宝能让这两位获得前所未有的满足感。"
D.Strings[72307]="……嚏！"
D.Strings[72308]="他们可能从任何方向发动攻击。"
D.Strings[72309]="他们会来破坏我们的建筑的！"
D.Strings[72310]="我完全听不到挖土的声音了……"
D.Strings[72311]="他们开始溃逃了。"
D.Strings[72312]="他们的攻击力度正在减弱。"
D.Strings[72313]="噢！指挥官！那个原祖荆兽发现我们了。姑娘们都出去抵挡它了。她们需要你的帮助！"
D.Strings[72314]="汉瑟尔！你还活着！来……我来帮你装弹。"
D.Strings[72315]="现在，尝尝这个吧！"
D.Strings[72316]="嗷嗷嗷！为什么是我？！"
D.Strings[72317]="哈哈！过来抓我呀！"
D.Strings[72318]="呃！让你瞧瞧我的厉害！"
D.Strings[72319]="大主教阿卡玛，这些攻击还只是个开始。"
D.Strings[72320]="现在，谁才是傻瓜？"
D.Strings[72321]="冰块才是最好的！"
D.Strings[72322]="那些来攻击我们坚固城市的兽人都是蠢货。"
D.Strings[72323]="虽然我很尊重您，但我不同意您的看法。我们决不能低估他们。请带我去参加主教议会吧。"
D.Strings[72324]="勇士们！是尼娅米的密探——他们走了这条路！"
D.Strings[72325]="最好快点解决那个家伙。后面还有敌人在不断涌来。"
D.Strings[72326]="不……噢，不……"
D.Strings[72327]="踏入真理的圣殿，接受净化吧！"
D.Strings[72328]="在我们家乡，艺术、科学、魔法和科技是相互融合的。啊，我们创造了一个怎样的奇迹啊！"
D.Strings[72329]="现在，我只剩一些备用零件和原材料了，只能粗略地组装一下。"
D.Strings[72330]="成功了！快进去操作控制台，我来给你望风……"
D.Strings[72331]="猎犬鬼魂发现了你！"
D.Strings[72332]="抓住那个鬣蜥人 ！"
D.Strings[72333]="有人发现了弄垮隧道的方法！"
D.Strings[72334]="这些家伙都是从哪儿冒出来的？"
D.Strings[72335]="这些家伙的数量太多了！"
D.Strings[72336]="他们人太多了！"
D.Strings[72337]="看看它的牙！"
D.Strings[72338]="不知道他们身上的水晶值不值钱……"
D.Strings[72339]="小心别死了，否则你会被他们吃掉的……"
D.Strings[72340]="这座洞穴会对我们很有用的。"
D.Strings[72341]="终于……我的时代来临了！这个世界将在虚空的力量下分崩离析！"
D.Strings[72342]="元素之怒们在元素王座等着你，$n。"
D.Strings[72343]="就和妈妈以前做的一样。"
D.Strings[72344]="它让我想起了铁炉堡。"
D.Strings[72345]="啊。家乡的味道。"
D.Strings[72346]="它能让你好受一些，小子。"
D.Strings[72347]="不，不，不。这完全不对！"
D.Strings[72348]="这里曾出现过某种邪恶的巫术，指挥官。"
D.Strings[72349]="布莱恩！是我，贾斯伯。你怎么了？"
D.Strings[72350]="联盟胜利了！"
D.Strings[72351]="好了，好了。一切都会好起来的。"
D.Strings[72352]="圣光将抚平一切伤痛。"
D.Strings[72353]="去吧，我来挡住后面跟着的援军！"
D.Strings[72354]="你饿了吗，小月光？来，给你几条鱼吃。"
D.Strings[72355]="我的工人都去哪儿了？他们得加班干完这些才行。"
D.Strings[72356]="把图纸拿给布莱恩看。"
D.Strings[72357]="虽然流失了很多，但我在元素中感受到了莫大的安宁。我会永远记住你的勇气，朋友。"
D.Strings[72358]="谁是漂亮的小灵龙？你就是漂亮的小灵龙！"
D.Strings[72359]="这似乎是一枚多头蛇的蛋，而且已经快要孵化了。$b$b它的母亲可能就在附近，而且肯定不会喜欢你靠近她的巢穴。"
D.Strings[72360]="我准备好开始融合仪式了。"
D.Strings[72361]="出——出什么事了？我在哪儿？贾斯伯……是你吗？"
D.Strings[72362]="好了，月光，现在——装死！"
D.Strings[72363]="出——出什么事了？我在哪儿？"
D.Strings[72364]="坐下，月光，坐下！真乖！"
D.Strings[72365]="部落胜利了！"
D.Strings[72366]="好了，慢慢移过来。稳住……稳住……"
D.Strings[72367]="小戈隆们，打碎他们的骨头，把他们带来给我！"
D.Strings[72368]="戈隆，用你的牙齿咬碎他们！"
D.Strings[72369]="瓦拉沙冲进了她的巢穴！"
D.Strings[72370]="<爱丽丝似乎完全没有注意到你的存在。>"
D.Strings[72371]="将鬼灵精华拿给爱丽丝看。"
D.Strings[72372]="你——你是谁？布莱恩呢？"
D.Strings[72373]="如果你见到她……请……告诉她我爱她。"
D.Strings[72374]="那些村民太好对付了。接下来就轮到你了。"
D.Strings[72375]="让我们看看谁才是最棒的。"
D.Strings[72376]="让艾泽拉斯为你骄傲吧，指挥官。"
D.Strings[72377]="别低估了塔布羊，$c。虽然它们通常都很温顺，但攻击力并不比雷象差。"
D.Strings[72378]="我知道……“高个子”巴克这名字太傻了。但我们总得给它个称呼，而它确实很高大。"
D.Strings[72379]="我是努波顿，一个谦卑的圣骑士。我被风中的某个声音召唤来此。我们能帮你什么忙吗？"
D.Strings[72380]="我们愿意帮助你找到大地之怒，并恢复这里的平衡。"
D.Strings[72381]="你必须让自己与高地上的元素产生共鸣。"
D.Strings[72382]="你准备好之后，我们就要跟伟大的元素之怒们沟通了。"
D.Strings[72383]="我们必须尽快行动，沃舒古在等着我们。"
D.Strings[72384]="我听说过元素王座，元素可以在那里与兽人交流。我从没想过自己有一天会站在这些巨人面前。$b$b虽然我在这里只是一个陌生人，但我觉得自己似乎来过这里……也许是在梦中吧。"
D.Strings[72385]="你好啊，指挥官。我能帮你什么忙吗？"
D.Strings[72386]="跟我来，跟紧了。"
D.Strings[72387]="你好，狼之$g兄弟:姐妹;。"
D.Strings[72388]="别低估了塔布羊，狼之$g兄弟:姐妹;。虽然它们通常都很温顺，但攻击力并不比雷象差。"
D.Strings[72389]="快回去干活！我们可不能让泰勒指挥官久等。"
D.Strings[72390]="别想再多休息一个小时了。回去干活！"
D.Strings[72391]="我要给你记处分！"
D.Strings[72392]="我受够了。你被解雇了！"
D.Strings[72393]="我已经看见敌人了。保持队形，小伙子们！"
D.Strings[72394]="现在——去杀掉一百个对手，拼命的时候到了！"
D.Strings[72395]="抱歉，但我们没那个时间。"
D.Strings[72396]="哼，我只数到九十九，巫师。"
D.Strings[72397]="那我想我们还欠你一次。"
D.Strings[72398]="所有人，跟我来！"
D.Strings[72399]="快！到洞里去，趁他们还没融化。"
D.Strings[72400]="这棵树苗是我们从家乡带来的，而它正在死去。我无法感觉到附近有邪恶力量，可我会继续尝试的。"
D.Strings[72401]="在被兽人称为沃舒古的水晶山下，躺着吉尼达尔的残骸。要不是先知维伦和纳鲁克乌雷的仁慈，我的人民早就死于燃烧军团之手了。"
D.Strings[72402]="你已经学会了这个研究方向下的所有配方。"
D.Strings[72403]="好了，回去干活儿吧。"
D.Strings[72404]="可是，我马上就要赢了……"
D.Strings[72405]="一定要这样吗？"
D.Strings[72406]="元素王座的元素之怒们给我们的萨满之石能让我们通过元素通话。"
D.Strings[72407]="传送门将我送进了扭曲虚空。"
D.Strings[72408]="<触碰长剑。>"
D.Strings[72409]="池塘中迅速发芽的种子伸出的根须和藤蔓正在吞噬这具尸体的残骸。"
D.Strings[72410]="这个嘲颅兽人在被杀死前似乎吃了很多东西，他们的身材在死前曾经发胖走样过。"
D.Strings[72411]="这具尸体的残骸现在成了这个池塘里的种子们的肥料。"
D.Strings[72412]="吉尼达尔曾是一艘由纳鲁领航，圣光驱动的飞船。现在，当我们站在这艘伟大飞船的残骸中时，圣光已经消逝……我只能在这里感觉到黑暗。"
D.Strings[72413]="别让他们拿到神器！"
D.Strings[72414]="我们要找的东西就在这儿！"
D.Strings[72415]="哈哈哈！我最喜欢杀戈隆了。"
D.Strings[72416]="尼莎，干掉她！"
D.Strings[72417]="布拉克，我这次不会再放过你了。"
D.Strings[72418]="要想成功训练灵龙，你就必须让它们吃饱睡足。焦躁不安的灵龙会更难接受指令。\n\n所以请不要打扰它们。"
D.Strings[72419]="我准备好做出选择了。"
D.Strings[72420]="这里是我们训练幼年灵龙听从指令的地方。\n\n虽然它们滑稽的动作看起来傻乎乎的，但要想把它们训练成坐骑，现在所学习的纪律是必不可少的。"
D.Strings[72421]="我本应该干掉你，可这又有什么意义呢……我没能完成任务，只能在这里等死……"
D.Strings[72422]="一座建筑被吃掉了！"
D.Strings[72423]="亮眼睛急切地看着你，等待着你的指令。"
D.Strings[72424]="亮眼睛，接住！"
D.Strings[72425]="谢谢你没有杀我。你的什么任务失败了？"
D.Strings[72426]="坐下，亮眼睛，坐下！"
D.Strings[72427]="好的，亮眼睛，现在装死！"
D.Strings[72428]="迪奥诺是我们族中一位强大而勇敢的勇士。他曾试图突破古老的战线与我们的敌人交战。$b$b但他最终死于几个玛戈隆之手……这里是他的陨落之地，他的力量为我们这些幸存者制造出了一片小小的避难所。如果我能够成功……可我失败了……"
D.Strings[72429]="你本打算做什么？"
D.Strings[72430]="像迪奥诺这样的勇士陨落后，他的躯壳上会生长出一个凋零之蕾。我想要采集这朵芽蕾并在此举行神圣的仪式，解放他的生命力，让他返回森林。$b$b可在行动时，我遭到了一些毛茸茸的两腿生物的攻击，他们抢先夺走了芽蕾。我们试图追上去，可他们升起了屏障，并用火焰逼退了我们。$b$b所以现在我只能咀嚼失败的苦果，等着敌人将我们碾为尘土……"
D.Strings[72431]="这么说只要夺回芽蕾就能解决问题……有意思……"
D.Strings[72432]="轮到你值班了。快醒醒！"
D.Strings[72433]="你想要什么？你没看到我正打算喝一杯吗？给你自己也倒一杯吧。$B$B赫米特来到了联盟和部落口中的纳格兰。因为这里还有大型野兽可供狩猎。$B$B可是，当我来到这里之后，他们有让我尽情狩猎吗？没有！$B$B赫米特，去杀掉战歌氏族的座狼。杀光兽人的坐骑。$B$B这可不是赫米特·奈辛瓦里该做的事！"
D.Strings[72434]="亮眼睛是我们在达克瑞姆训练过的，最聪明的灵龙之一。他最喜欢跟访客做游戏了！\n\n你何不去试试，看看亮眼睛愿不愿意跟你玩游戏呢？"
D.Strings[72435]="干得好。这个神器归你了。"
D.Strings[72436]="它生效了！虽然……不太稳定。但它确实有效。"
D.Strings[72437]="这个全新的装置可以汲取惊人的能量。"
D.Strings[72438]="不惜一切代价保护结界！"
D.Strings[72439]="挡住那些影月兽人。是什么让他们如此疯狂？"
D.Strings[72440]="让他们过来吧。我们要守住山脊线。"
D.Strings[72441]="拖住他们。防御结界吸收的能量太多了——我维持不了多久。"
D.Strings[72442]="这里是我的几位伙伴安息的地方，他们都是被独眼魔杀死的。"
D.Strings[72443]="维沙，他还是个孩子，还没做好战斗的准备。"
D.Strings[72444]="奇莎，她还年轻，但已经展现出非凡的潜质。"
D.Strings[72445]="最后，还有我最亲爱的拉提莎。"
D.Strings[72446]="我要消灭这条峡谷中的毁灭者，为我失去的伙伴们复仇！"
D.Strings[72447]="我曾是一个像你一样的冒险者……$b$b那些日子至今依然历历在目，就好像发生在昨天一样。那时我还在艾泽拉斯，坐在我最喜欢的旅店里，或许你听说过它？就是狮王之傲旅店，就在闪金镇的中央。$b$b那时，我就坐在老杜宾斯的对面，就着一壶西瓜汁享用美味的陈年干酪。突然，多吉冲进了旅店！$b$b他的脸色变得雪白……不对，是比雪还要白！他说他在附近看见了一只狗头人，它还带着一支蜡烛，好像是打算将闪金镇付之一炬！$b$b我丢下美味的陈年干酪，冲向门口，却被一个矮人猎人绊倒了。$b$b我们都摔在了地上，然后“啪”的一声，我的膝盖中了一箭！"
D.Strings[72448]="你！怪东西！快过来吃吧！这食物太美味了。你一定得尝尝。$b$b这真是太好吃了，我都没想起来要捅你一刀……暂时而已。"
D.Strings[72449]="伊瑞尔，让我们轰开大门，占领格罗玛什尔吧。"
D.Strings[72450]="立正，新兵们！我的骑兵战友们都管我叫“月鹿”。你们可以叫我“长官”。"
D.Strings[72451]="你们以前都飞行过，但现在你们将进入一个新的世界，所以都给我集中注意力。"
D.Strings[72452]="我是部队中速度最快的通讯员。你有报告需要递交吗？"
D.Strings[72453]="这是一头达克瑞姆灵龙。它就像长耳兔一样灵活，可以在一秒内快速转身。"
D.Strings[72454]="今天，我们要做基本的起飞、接近和着陆练习。"
D.Strings[72455]="不集中精神的人最后只会变成达克瑞姆石头上的一滩肉泥。现在解散！"
D.Strings[72456]="追上他们！别让他们跑了！"
D.Strings[72457]="杜隆坦，让我们轰开大门，占领格罗玛什尔吧。"
D.Strings[72458]="快回来，猪排！你把我们的脸都丢光了！！！"
D.Strings[72459]="坏猪排！"
D.Strings[72460]="计划有变，伙计们。让我们从头来过吧！"
D.Strings[72461]="能量……衰减……"
D.Strings[72462]="必须……继续……战斗……"
D.Strings[72463]="不能失败……我绝不能失败……"
D.Strings[72464]="我们要为艾泽拉斯而战！"
D.Strings[72465]="要是我能闭一会儿眼睛就好了……"
D.Strings[72466]="你们敢不尊重我们指挥官的意见？你们还算部落人吗？！推倒重建！"
D.Strings[72467]="我没法一个人杀光这些木精。我跟你一起去！"
D.Strings[72468]="撤退！我们得去别的地方找耐奥祖所需的祭品。"
D.Strings[72469]="趁还有时间，快烧毁它！"
D.Strings[72470]="把尸体都烧掉，否则就迟了！"
D.Strings[72471]="我的断头台上又多了一条黑暗的亡魂。"
D.Strings[72472]="违背主人的意志只有死路一条。"
D.Strings[72473]="我很高兴，可以看着你们这些老鼠打上几个小时了。"
D.Strings[72474]="这些该死的植物毁了我的猎场！"
D.Strings[72475]="在那些洞穴里，塑日者的能力将被极大地削弱，但千万别小看他们！"
D.Strings[72476]="我……我记得……"
D.Strings[72477]="我们得帮帮泰勒！"
D.Strings[72478]="你确定他们看不见我吗？"
D.Strings[72479]="谢谢你，可我现在该去哪儿？"
D.Strings[72480]="啊，一个诱饵。我的机会来了！"
D.Strings[72481]="快躲回去……"
D.Strings[72482]="拜托，我的嘴巴可没那么大！这玩意儿一点也不像我……"
D.Strings[72483]="愿鸦神护佑着你，朋友。"
D.Strings[72484]="大主教玛拉达尔，让奇娅娜跟你一起去侦察那座洞穴吧。"
D.Strings[72485]="$n——我有一个特殊的任务给你。"
D.Strings[72486]="女伯爵莉亚德琳，让欧林跟你一起去侦察那座洞穴吧。"
D.Strings[72487]="长官，我们的要塞正面临一场袭击。我已经准备了一些你可能用得上的东西。$B$B不管这些蠢货是谁，我都很乐意为自己再添一道光荣的伤疤。"
D.Strings[72488]="准备与鬣蜥人战斗。"
D.Strings[72489]="是否开启要塞入侵事件？"
D.Strings[72490]="猪排被压扁了？！我要把你也压扁！"
D.Strings[72491]="碾压时间！"
D.Strings[72492]="*喘气*谢……*咳嗽*谢谢你把我救了出来！"
D.Strings[72493]="那该死的舱门卡住了，把我关在了里面！我还真是倒霉，刚从感染者手里逃出来，就被关在了有故障的逃生舱里。"
D.Strings[72494]="快阻止它！打倒它！"
D.Strings[72495]="呆在你的沼泽里，游侠。我来对付这家伙。"
D.Strings[72496]="你真是救了我一命啊……见鬼！哈，我差点害死自己……真见鬼！……因为我被困在逃生舱里了……呃，你懂的。"
D.Strings[72497]="长官，我们会按你的吩咐集结部队的。"
D.Strings[72498]="呃，我还没谢谢你把我救出来呢。我在逃出镇子的时候顺手带上了这个东西；它对你可能会更有用。"
D.Strings[72499]="我们后会有期，$g老兄: 宝贝儿;！"
D.Strings[72500]="噢！现在又是黄蜂了吗？这到底怎么了！？！？"
D.Strings[72501]="这里出什么事了？整座蘑菇林都在疯长。"
D.Strings[72502]="你又把共鸣水晶埋进地里去了吗？你让这些大地生物都疯狂了！"
D.Strings[72503]="你什么时候才能明白，这个世界和阿古斯是完全不同的？"
D.Strings[72504]="<两位大主教正在激烈地争吵。>$b$b感谢你的帮助，$n。显然我的设备刺激到了当地的植被——更别提我的这位同僚了。$b$b但没关系，我会不惜一切代价保护我们的人民，并重建我们所失去的一切的……偶尔的错误是可以被原谅的。你肯定也赞同这一点吧？"
D.Strings[72505]="<两位大主教正在激烈地争吵。>$b$b大主教哈塔鲁总是太过执着于我们失去的一切。我一直想让他明白——想把这个世界变成第二个阿古斯是多么愚蠢，虽然我们有这个能力。德拉诺是独一无二的，我们应该研发适应这个新世界的技术，而不是反其道行之！$b$b他似乎比较听得进你的话。或许你能让他变得理智一点。"
D.Strings[72506]="到我身后去！"
D.Strings[72507]="卡德加！快过来！"
D.Strings[72508]="英雄，快帮我下去。我们没有多少时间了！"
D.Strings[72509]="厄菲阿尔背叛了我。他杀死了我的属下，并把他们变成了——"
D.Strings[72510]="你可真是大胆，泰勒。我会让你如愿的。"
D.Strings[72511]="我想伪装已经没有意义了。"
D.Strings[72512]="现在，上将，是时候结束我一手导演的这场闹剧了。"
D.Strings[72513]="原祖荆兽来了。做好准备！"
D.Strings[72514]="快去帮帮德拉卡和卡兹！德拉卡让我使用这把巨型火枪。我要用这把矮人造的巨型火枪把那个畜生撕成碎片！"
D.Strings[72515]="装弹"
D.Strings[72516]="他们在……吞噬我们的要塞。"
D.Strings[72517]="他们在吞吃我们的建筑！"
D.Strings[72518]="他们什么都能吃！"
D.Strings[72519]="去吧！我会保护你，不让那些白鬼来捣乱的……"
D.Strings[72520]="你想要交换卡片吗？"
D.Strings[72521]="把那头畜生烧成灰！"
D.Strings[72522]="你的工人们正在辛勤工作，指挥官。你的要塞很快就会有充足的食物了。"
D.Strings[72523]="我会找到大主教阿卡玛和玛拉达尔的。祝你好运，指挥官。"
D.Strings[72524]="我们决不能让白鬼召集起由元素奴隶组成的大军。"
D.Strings[72525]="与卡拉迪奥斯交谈，开始仪式。"
D.Strings[72526]="虚空的恐怖生物正在涌向沃舒古，$n。我们必须阻止他们。"
D.Strings[72527]="必须尽快解决那些仪式主持者，否则就迟了！"
D.Strings[72528]="伊瓦里杜斯的力量每时每刻都在增长。快一点！"
D.Strings[72529]="我们必须阻止战歌氏族的仪式！"
D.Strings[72530]="如果让传送门开启，恐怖的虚空生物就能毫无障碍地涌入德拉诺了！"
D.Strings[72531]="找到高地上的四根柱子，并让你自己与元素共鸣。"
D.Strings[72532]="很好。我要亲手结果了你。"
D.Strings[72533]="站起来吧，实现我的意志！"
D.Strings[72534]="你成功了。我们自由了！"
D.Strings[72535]="我们自由了。"
D.Strings[72536]="信徒们会竭尽全力将你们的尸体扔到下面的森林里。我可以把你们平安带回来。"
D.Strings[72537]="送我回地面吧，朋友。"
D.Strings[72538]="你确定要离开地下城吗？"
D.Strings[72539]="拿起武器！为了部落！"
D.Strings[72540]="终于能战个痛快了。"
D.Strings[72541]="把工人送到安全的地方去。"
D.Strings[72542]="空气、清风以及万物之灵……"
D.Strings[72543]="让这个生物响应我的召唤吧！"
D.Strings[72544]="你在染指……你完全不了解的力量。"
D.Strings[72545]="什么？！他要走了？！"
D.Strings[72546]="安息吧，迪奥诺，抱歉让你久等了……"
D.Strings[72547]="我会沿着大路，到永晨之泉的南边跟你汇合的。如果你能活下来的话。"
D.Strings[72548]="指挥官，你没事吧？"
D.Strings[72549]="你还好吧，指挥官？"
D.Strings[72550]="前线已经摇摇欲坠了。他们坚持不了多久。"
D.Strings[72551]="这应该很简单。"
D.Strings[72552]="元素会为我们争取时间的！为了艾泽拉斯！"
D.Strings[72553]="大地之怒，赐予我力量吧！"
D.Strings[72554]="我……感到很疲惫。元素的声音只剩下微弱的低语。"
D.Strings[72555]="打起精神来！又来了一支钢铁部落的部队！"
D.Strings[72556]="你休想阻碍主人的计划"
D.Strings[72557]="%s就要爆炸了！"
D.Strings[72558]="免责声明：\n\n热砂保护协会对火箭升空过程中出现的任何意外死亡、肢解或残疾事故不承担任何赔偿责任。\n\n米斯蒂·飞弹，\n热砂保护协会法务部"
D.Strings[72559]="目前为止一切正常！水晶导管正在传输能量。只要再过几分钟……"
D.Strings[72560]="非常好。别让他们靠近。我马上就完成了！"
D.Strings[72561]="成功了！还不错，陌生人。如果你喜欢的话，就拿着那头畜生留下的战利品吧。我们应该暂时安全了。"
D.Strings[72562]="小心！他们过来了！"
D.Strings[72563]="滚出去！只有工作人员才能进入储藏室。"
D.Strings[72564]="%s召唤出了|cFFFF0404|Hspell:150045|h[熔火冲击]|h|r！"
D.Strings[72565]="我会送海军上将泰勒返回营地的。我们在那儿见。"
D.Strings[72566]="我会帮上将找到他的人的。我在营地那儿等着你。"
D.Strings[72567]="“……渡鸦吞天。”是谁派你来的？"
D.Strings[72568]="很好。我听着呢。"
D.Strings[72569]="钢铁部落的坦克冲上前线了！好大的坦克啊！"
D.Strings[72570]="嘿！你知道修复这个东西要花多少钱吗！？"
D.Strings[72571]="别再用我自己的炸弹来对付我了！"
D.Strings[72572]="给你一个忠告！站到我的火焰里来，你会喜欢的！"
D.Strings[72573]="哇哈哈！我们是空降兵！"
D.Strings[72574]="这玩意儿在建造时，没有考虑过搭载这么多乘客的情况，所以你就随便找个地方抓紧吧。但愿你的手劲儿够大。"
D.Strings[72575]="我想我们可以达成一份合理的租赁协议。我的车间下面有一张小床，5,000,000金租给你，怎么样？"
D.Strings[72576]="我们成功了！克鲁努斯加入了部落的阵营！"
D.Strings[72577]="联盟击杀了克鲁努斯！"
D.Strings[72578]="过来一起坐吧！汉堡就快好了，头儿！"
D.Strings[72579]="你们跑不了了，老鼠们。"
D.Strings[72580]="别那么肯定，耐奥祖。"
D.Strings[72581]="是的……靠近点！我要活埋了你，为了钢铁部落的荣耀！"
D.Strings[72582]="好好瞧瞧，你得到了房间里最好的位置！\n\n你也是来观战的吗？"
D.Strings[72583]="我不知道，基姆兹。我已经老了，接受不了这种笑话了。你在车间里有个好位置；能不能腾出一点地方让你亲爱的老叔叔歇歇脚呢？"
D.Strings[72584]="我的腿突然就好多了。"
D.Strings[72585]="这次真不走运！"
D.Strings[72586]="我钓到一条！我钓到一条了！"
D.Strings[72587]="好大的鱼！"
D.Strings[72588]="我是做走私生意的……而且生意不错。"
D.Strings[72589]="快来抢购我的稀罕货吧！"
D.Strings[72590]="啊，是的！我专门为你留了一样好东西。"
D.Strings[72591]="一条咬钩的鱼都没有！"
D.Strings[72592]="唉……"
D.Strings[72593]="有鱼咬钩了！"
D.Strings[72594]="我是不是感觉到什么了？"
D.Strings[72595]="我好像钓到一条了！"
D.Strings[72596]="下毒"
D.Strings[72597]="啊，旅行者，你还想从我这个三流艺术家这里买点什么吗？买件首饰怎么样？纪念币或者纪念品呢？"
D.Strings[72598]="看看你面前的一切吧。这一刻的美丽才是真正的宝藏。"
D.Strings[72599]="废物……"
D.Strings[72600]="不要犹豫！"
D.Strings[72601]="打倒他们！"
D.Strings[72602]="胜利近在眼前了！"
D.Strings[72603]="我要让你血溅五步！"
D.Strings[72604]="坚强起来！"
D.Strings[72605]="不要放弃！"
D.Strings[72606]="我们决不动摇！"
D.Strings[72607]="坚强点！"
D.Strings[72608]="你肯定没见识过我的魔法！"
D.Strings[72609]="你见过魔法吗？"
D.Strings[72610]="只要团结一致，我们就不会失败！"
D.Strings[72611]="嘿，再次感谢你在宾奇维斯拓殖点救了我。"
D.Strings[72612]="嘿，如果你需要修理引擎或者烧掉什么东西，尽管开口！$b$b我可以给你个内部价，打十折哦！"
D.Strings[72613]="好了，伙计们，考古时间！"
D.Strings[72614]="头儿！我发现了神器周围有异常！"
D.Strings[72615]="我们得解除它。用你的考古爆破器解决它！"
D.Strings[72616]="我收到了反馈！我的考古爆破器对付不了它。"
D.Strings[72617]="我真该穿上红色的衬衣……"
D.Strings[72618]="把爆破器威力调到最大！"
D.Strings[72619]="真厉害！你肯定经过了许多战斗才学会了那样的战斗技巧。现在只剩下祖尔莫克和克罗矛格了。"
D.Strings[72620]="它可真有劲儿！"
D.Strings[72621]="它还在挣扎！"
D.Strings[72622]="现在只剩下克罗矛格了。"
D.Strings[72623]="我是不会让你跑掉的！"
D.Strings[72624]="祖尔莫克是我们的最后一个目标。"
D.Strings[72625]="真厉害！只有老手才懂得像你那样战斗。现在只剩下两个目标了。"
D.Strings[72626]="现在我们得去对付沃戈什了。"
D.Strings[72627]="现在我们得去对付祖尔莫克了。"
D.Strings[72628]="|TInterface\\Icons\\ability_hanzandfranz_bodyslam.blp:20|t$n即将被|cFFF00000|Hspell:159646|h[抱摔]|h|r击中！"
D.Strings[72629]="我会到你的要塞去安顿好你的法师们。我们在那儿见吧！"
D.Strings[72630]="请允许我先走一步，指挥官。我想看看你的要塞，并且安顿好你的法师们。"
D.Strings[72631]="打得好！继续下一个目标！现在只剩下沃戈什和克罗矛格了。"
D.Strings[72632]="打得好！继续下一个目标！现在只剩下祖尔莫克和克罗矛格了。"
D.Strings[72633]="打得好！继续下一个目标！现在只剩下祖尔莫克和沃戈什了。"
D.Strings[72634]="我是不会袖手旁观，看着我们的英雄们死去的！"
D.Strings[72635]="暴风之怒，请听从我的祈求！"
D.Strings[72636]="不！你们不能抢走威布森，他是我的全部！"
D.Strings[72637]="为我报仇，威布森。为我报仇……"
D.Strings[72638]="是来喂萨皮的吗？"
D.Strings[72639]="萨皮饿了。"
D.Strings[72640]="<给萨皮喂食。>"
D.Strings[72641]="快转身，躲开罗卡的|cFFFF0000|Hspell:166139|h[炫目强光]|h|r"
D.Strings[72642]="只要你有金币，我这里什么货都有！"
D.Strings[72643]="让我们看看吧。"
D.Strings[72644]="达坎，我们进去吧。"
D.Strings[72645]="攻城坦克，开火。"
D.Strings[72646]="联盟，前进！"
D.Strings[72647]="战歌的勇士们，把他们的脑袋给我带来！"
D.Strings[72648]="你从西面袭击他们的侧翼，我们会掩护你的。"
D.Strings[72649]="小心。狼骑兵！"
D.Strings[72650]="欢迎欢迎！来休息一下，并留下你的金币吧！"
D.Strings[72651]="战歌的勇士们，追击！"
D.Strings[72652]="接好了，小丫头。"
D.Strings[72653]="这下你肯定扛不住了。"
D.Strings[72654]="解决这些废物。"
D.Strings[72655]="我们得继续前进。"
D.Strings[72656]="跳出来吧，我的座狼们。"
D.Strings[72657]="快封闭那些狼穴！"
D.Strings[72658]="指挥官，坏消息。他们奴役了饥饿者杜恩。"
D.Strings[72659]="把饥饿者放出来。"
D.Strings[72660]="快进入圣光。"
D.Strings[72661]="游侠，开火！"
D.Strings[72662]="来啊，德莱尼女巫。我等着呢。"
D.Strings[72663]="达坎，我要你和我们的部队留在这里。"
D.Strings[72664]="你们得帮我们争取到足够的时间来对付加尔鲁什。"
D.Strings[72665]="无论发生了什么，玛尔拉德都会为你而骄傲的。"
D.Strings[72666]="轰开这些门！"
D.Strings[72667]="你这个蠢货，居然敢到这里来。"
D.Strings[72668]="经过了这一切之后，你以为你真能杀得了我？"
D.Strings[72669]="正义。你根本不理解这个词的真意。"
D.Strings[72670]="我就是你的末日。"
D.Strings[72671]="尝尝血吼的利刃吧。"
D.Strings[72672]="我是不可战胜的。"
D.Strings[72673]="加尔鲁什！"
D.Strings[72674]="萨尔？你来迟了一步，老朋友。"
D.Strings[72675]="不。够了，加尔鲁什。就你和我，让我们决一死战吧。"
D.Strings[72676]="我要跟你决斗。"
D.Strings[72677]="不行，萨尔。"
D.Strings[72678]="很好，萨满。这一切都源自我们的恩怨，就让我们私下解决吧……"
D.Strings[72679]="……地点就定在预言之石。"
D.Strings[72680]="我在梦里见过……这些来自异世界的陌生人将把我们为之奋斗的一切化为火海。"
D.Strings[72681]="但德拉诺的血管里流淌着兽人的鲜血！"
D.Strings[72682]="前进，钢铁部落！把我们的敌人变成尸体。"
D.Strings[72683]="为了格罗玛什的荣耀！"
D.Strings[72684]="干得好！现在只剩两个了。"
D.Strings[72685]="精彩的战斗！现在只剩两个了。"
D.Strings[72686]="打得好！还剩两个。"
D.Strings[72687]="那些暴怒的野兽向我们冲过来了！"
D.Strings[72688]="阿格娜，我们进去吧。"
D.Strings[72689]="攻城车，开火。"
D.Strings[72690]="暗矛勇士们，开火！"
D.Strings[72691]="靠近我的治疗图腾。"
D.Strings[72692]="来啊，酋长。我等着呢。"
D.Strings[72693]="阿格娜，我要你和我们的部队留在这里。"
D.Strings[72694]="知道吗，杜隆坦，你越来越像萨尔的父亲了。"
D.Strings[72695]="在孤寂的山峰之下，阴影正在泰罗克鸦巢中汇聚。"
D.Strings[72696]="让我来揍你一顿吧！"
D.Strings[72697]="这把锤子也想帮我揍你一顿。"
D.Strings[72698]="你不想再挨揍了吗？"
D.Strings[72699]="这将是给你的最后一击！"
D.Strings[72700]="我有话要跟你说！"
D.Strings[72701]="我听说你喜欢挨揍！"
D.Strings[72702]="谢谢！要不是你，我肯定会死在那里的。"
D.Strings[72703]="我永远都不会忘记你的恩情的。"
D.Strings[72704]="感谢圣光！我要去救我的姐妹们。"
D.Strings[72705]="你是位真正的英雄。"
D.Strings[72706]="我要杀光眼前所有的食人魔！"
D.Strings[72707]="谢谢你，$n。愿万灵指引你的道路。"
D.Strings[72708]="甜蜜的自由！"
D.Strings[72709]="我的力量呢，食人魔？"
D.Strings[72710]="你的力量？（那是我的力量！）"
D.Strings[72711]="你会屈服的，学徒。交出它的控制权。"
D.Strings[72712]="我不这么认为。（我们不会再听命于你了！）"
D.Strings[72713]="这才是真正的考古！"
D.Strings[72714]="嘿，头儿，你觉得这玩意儿安全吗？"
D.Strings[72715]="邪能正在吞噬大主教哈塔鲁的灵魂。我们必须尽快行动。$b$b缚魂者尼娅米会将哈塔鲁的灵魂固定在这个位面，由我来驱逐攻击他的恶魔。如果走运的话，我们就能找出是谁谋杀了他。$b$b等我释放出那个邪恶的存在，就由你来消灭它。你准备好了吗，$n？"
D.Strings[72716]="我准备好了。开始仪式吧，大主教。"
D.Strings[72717]="我们中间有叛徒——一个堕落的大主教！$b$b这真是……不可思议。"
D.Strings[72718]="我们出发吧！$n，我们会在营地那里等着你的。"
D.Strings[72719]="一旦仪式开始，我就帮不上你的忙了。集中精神。"
D.Strings[72720]="遗体已经准备好了，大主教。我会固定住他的灵魂。"
D.Strings[72721]="当然！一点点宇宙辐射不会有什么坏处的！"
D.Strings[72722]="嘿，欢迎光临锈筒烧烤酒吧！"
D.Strings[72723]="Golad，maloch，valsheva。听从我的声音，幽灵——让生者看到你所见的一切吧。Golad，maloch，valsheva！"
D.Strings[72724]="滚开，大主教。这个灵魂，以及他所有的秘密，现在都属于我们了。"
D.Strings[72725]="你可以带走他的遗体，但我要保护他不朽的灵魂。"
D.Strings[72726]="Golad，maloch，valsheva！Golad，maloch，valsheva——圣光赐予我力量……"
D.Strings[72727]="我们从克乌雷那里学到了很多。（我们正在写一本书。）"
D.Strings[72728]="跑吧，老东西。（悬槌很快就会化为火海。接下来，就轮到整个世界了！）"
D.Strings[72729]="滑翔机可以起飞了！如果你发现什么有趣的东西，就告诉我一声，好吗？"
D.Strings[72730]="看来这个地方已经空了。或许你该试试其它的滑翔机。"
D.Strings[72731]="Golad，maloch，valsheva。听从我的声音，幽灵。让生者看到你所见的一切吧。Golad，maloch，valsheva！"
D.Strings[72732]="快一点。这一切都让我有种不祥的预感……"
D.Strings[72733]="嘿，伙计。今天真是个滑翔的好日子，不是吗？"
D.Strings[72734]="你们，陌生的入侵者……"
D.Strings[72735]="你们想关闭黑暗之门？"
D.Strings[72736]="我可以帮你们。只要……你们放我出来。"
D.Strings[72737]="我们收集了多少神器碎片？"
D.Strings[72738]="你是个执着的人，对吧？我想你现在可以继续前进了，头儿。"
D.Strings[72739]="这架滑翔机归你了，朋友。我可以自己去，可会不会死我就保证不了了。"
D.Strings[72740]="还活着呢？如果我是你的话，我早就斩仓止损了。这附近不可能再有什么值得搜寻的东西了。"
D.Strings[72741]="你的内心乐观向上，但枪林弹雨即将到来。祝你渡过愉快的一天。"
D.Strings[72742]="我还得去执勤呢。我得马上走了。"
D.Strings[72743]="来租用我的构造体吧。"
D.Strings[72744]="好啊，我要租一个。"
D.Strings[72745]="请把它们拿远点。"
D.Strings[72746]="你喜欢我的构造体吗？"
D.Strings[72747]="租金是一个铜板吗？"
D.Strings[72748]="先让我们找出真相。我们必须知道是谁杀害了他！"
D.Strings[72749]="Exoch，maloch，talomai！哈塔鲁，追随圣光的指引吧……"
D.Strings[72750]="我的人民肯定会怀念克乌雷的，但你直面邪恶的勇气一定能鼓舞他们。"
D.Strings[72751]="大主教，他们正在撕扯他的灵魂。我们必须阻止他们！"
D.Strings[72752]="奥金顿……他们想要……"
D.Strings[72753]="……想要什么，哈塔鲁？进入奥金顿的密码？还是你的安全结界？"
D.Strings[72754]="玛拉达尔。他快不行了。"
D.Strings[72755]="……大主教的命令……"
D.Strings[72756]="是谁，哈塔鲁？是谁杀了你？"
D.Strings[72757]="<咳嗽>好臭！但我想我应该没有吸进去多少……"
D.Strings[72758]="……缚魂者……"
D.Strings[72759]="%s指向了缚魂者尼娅米。"
D.Strings[72760]="我们快要失去他了。你也看到了——他刚才在呼唤我的帮助。他的灵魂现在已经安全了。"
D.Strings[72761]="怎么了？你为什么打断他？"
D.Strings[72762]="他提到了一个大主教。我们的议会里出了叛徒吗？"
D.Strings[72763]="尼娅米，将他的遗体送去奥金顿，让他安息吧。"
D.Strings[72764]="%s即将喷吐灵质！"
D.Strings[72765]="净化磨魂者的虚空能量！"
D.Strings[72766]="磨魂者被净化了！"
D.Strings[72767]="有了这些暴怒的元素，我们的航程就能大大缩短。但这需要大量滑翔机。乘上其中一架出去兜兜风，看看你能不能发现什么吧？"
D.Strings[72768]="没必要再冒生命危险了。我们已经把所有有价值的挖掘场都扫荡过一遍了。"
D.Strings[72769]="我们会想出办法的，这可是宾奇维斯拓殖点最擅长的事！"
D.Strings[72770]="停——立刻停止仪式！集中精神。我们必须保护他的灵魂。"
D.Strings[72771]="我们的部队已经摇摇欲坠，我的力量也在衰退，$n。剩下的时间不多了，我们马上就会被击溃的。"
D.Strings[72772]="法力炸弹安放完毕！"
D.Strings[72773]="你要不择手段，不惜一切代价，勇士。你是艾泽拉斯最后的希望了了。"
D.Strings[72774]="你逃不出我们的手掌心，藏卷人！"
D.Strings[72775]="你的喙将成为高阶贤者的精美战利品！"
D.Strings[72776]="你那可怜的起义到此为止了。"
D.Strings[72777]="你以为躲进树林里就安全了吗？世间万物都逃不过鲁克玛的眼睛！"
D.Strings[72778]="肮脏、该死的废物——让我结束你的痛苦吧。"
D.Strings[72779]="啊，真是唾手可得"
D.Strings[72780]="找到你了，瑞沙德！"
D.Strings[72781]="哇！！这是什么？！"
D.Strings[72782]="一个诱饵？！"
D.Strings[72783]="我的眼睛！出什么事了？！"
D.Strings[72784]="瑞……沙德……"
D.Strings[72785]="呱！我……我在哪儿？"
D.Strings[72786]="是头儿派你来的吗？\n\n你瞧，如果他问起的话，你就说我正在进行水下发掘工作。"
D.Strings[72787]="要我说的话，发掘巨型蘑菇可不是什么好主意，但你尽管选一架滑翔机出去看看。毕竟，你浪费的又不是我的时间。"
D.Strings[72788]="我很怀疑你在外面还能有什么发现。我看到的只有蘑菇、蘑菇，还是蘑菇。"
D.Strings[72789]="是它……就是它！"
D.Strings[72790]="这个不幸的灵魂似乎经历了非常悲惨的死亡。"
D.Strings[72791]="别再浪费时间了，地精。盯紧那座城市。"
D.Strings[72792]="别走神了，法师。我们的时间不多。"
D.Strings[72793]="别让那座传送门关闭了。我们的先知就快完成火炮的校准了。"
D.Strings[72794]="苦力，把这些炮弹装进火炮。快！"
D.Strings[72795]="你在干什么，蛆虫？你昨天就该完成这个任务了！"
D.Strings[72796]="先知，报告情况！"
D.Strings[72797]="萨满，更新你的情况。"
D.Strings[72798]="你看见了什么？"
D.Strings[72799]="我们就快到了，上尉。"
D.Strings[72800]="她就在前面，上尉。"
D.Strings[72801]="马上就能看见了，上尉。"
D.Strings[72802]="守好大门，好吗？"
D.Strings[72803]="我们终于到了……但有些不对劲。我得再靠近一点……我别无选择！"
D.Strings[72804]="拖住信徒。"
D.Strings[72805]="哟，哟……真是奇怪的藏书……"
D.Strings[72806]="珀西，你找到什么了？过来，让我们看看……"
D.Strings[72807]="五十种暗影射线……五十种？珀西好孩子，赶快把它放回去。"
D.Strings[72808]="啊，看看这个！泰罗克的传说。"
D.Strings[72809]="他还做了笔记。就在这儿，你看。"
D.Strings[72810]="恶心的鸟人……"
D.Strings[72811]="在死后……我将解脱……"
D.Strings[72812]="Lok'tar，指挥官。"
D.Strings[72813]="你的意志决定我们的命运，指挥官。"
D.Strings[72814]="一路顺风，指挥官。"
D.Strings[72815]="愿万灵护佑着你，指挥官。"
D.Strings[72816]="愿清风颂扬你的伟大传奇，指挥官。"
D.Strings[72817]="摧毁那件圣物，入侵者！"
D.Strings[72818]="那些钢铁部落的杂种把我们当成导管来为他们的传送门供能。我会让他们后悔的。"
D.Strings[72819]="暗影议会感谢你的帮助。"
D.Strings[72820]="你……外来者。快摧毁那件圣物，放我们出去。（摧毁那件圣物！砸烂它！）"
D.Strings[72821]="摧毁那件圣物！砸烂它！"
D.Strings[72822]="如果你真的想阻止钢铁部落，就去找到古尔丹。（古尔丹！古尔丹在为传送门供应能量！）"
D.Strings[72823]="古尔丹！古尔丹在为传送门供应能量！"
D.Strings[72824]="快点挖！巫师之王需要更多的遗物！"
D.Strings[72825]="快点干！遗物的关键部分肯定就在这附近。"
D.Strings[72826]="别再砸烂了！巫师之王需要完好无缺的遗物！"
D.Strings[72827]="杀掉所有的入侵者！我们的工作必须保密！"
D.Strings[72828]="挖掘遗物的第一条规矩就是不能谈论它们！"
D.Strings[72829]="你们这些蠢货怎么会弄坏那么多货车？这下你们就自己把遗物搬去悬槌堡吧！"
D.Strings[72830]="要是你敢偷懒，那就自己去向巫师之王解释吧！"
D.Strings[72831]="看！传送门变弱了！"
D.Strings[72832]="守住阵地！我们的任务马上就要完成了！"
D.Strings[72833]="钢铁部落的战士们！入侵者正在释放囚犯！"
D.Strings[72834]="啊啊！！希望你喜欢死亡的滋味！"
D.Strings[72835]="卑贱的$r！我要像碾碎虫子一样碾碎你！"
D.Strings[72836]="我要把你砸成肉泥！啊啊！"
D.Strings[72837]="嗨。"
D.Strings[72838]="你要为偷窃遗物付出代价！啊！"
D.Strings[72839]="你和那些讨厌的地精会付出代价的！"
D.Strings[72840]="那是属于悬槌氏族的遗物！你死定了！"
D.Strings[72841]="你竟然敢偷遗物，我要砸碎你的骨头！"
D.Strings[72842]="小声点，头儿。如果让战歌兽人发现我们在这里，呃，这对我们的生意可是非常不利的。"
D.Strings[72843]="这些战歌兽人不可能用得完存放在这里的所有补给——尤其是等部落开始猎杀他们之后。 \n\n所以依我看，就算我们拿一点出去卖钱，又有什么不好呢？"
D.Strings[72844]="这里的瘴气笼罩了一切！我们不能停留太久……"
D.Strings[72845]="我好像没办法弄掉这个恶心的玩意儿了……别担心，我还遇到过更糟的情况呢……"
D.Strings[72846]="这里的雾太浓了，我几乎都看不见东西了……它太吵了。真想让所有人都闭嘴！"
D.Strings[72847]="告诉达坎……我很……抱歉……"
D.Strings[72848]="一点黏糊糊的孢子吓不倒我！"
D.Strings[72849]="让我们结束这一切吧。这里有一股力量，我能闻到它，感觉到它！不管是尖叫的沼泽还是雾气组成的怪物都休想阻止我！"
D.Strings[72850]="我们……本可以靠它统治戈尔隆德……染红一切……"
D.Strings[72851]="只要再拧紧一个螺丝……"
D.Strings[72852]="鬣蜥人逃跑了，但我觉得它们并不是因为害怕我们……"
D.Strings[72853]="<卡鲁静静地看了你一会儿，然后你的脑海中响起了她的声音。>$b$b在过去漫长的岁月中，我从没有让别人骑在我的背上过。但现在不是讲虚荣的时候，无数生灵已经命悬一线。$b$b鲁克玛的子孙不仅威胁到了这些被诅咒的贱民，也威胁到了我的鸦群。我知道只有将所有的力量团结起来，我们才能获胜。$b$b你准备好做你该做的事了吗？"
D.Strings[72854]="如果你打算乘坐滑翔机飞到格罗玛什尔的上空，那一定要小心点，伙计。下面那些兽人可不怎么喜欢空中飞人。"
D.Strings[72855]="我想你已经彻底扫清那些战歌兽人了，就没必要再出去冒险了。"
D.Strings[72856]="纳格兰到处都是珍贵的遗物，热砂保护协会就是来寻找这些遗物的！"
D.Strings[72857]="战争古树有什么用？"
D.Strings[72858]="就当为了我们，快回阴影里去吧，珀西。"
D.Strings[72859]="啊，是你啊。相信我，朋友，接下来的事我会搞定的。你可以走了。"
D.Strings[72860]="啊，你好啊！今天你有什么东西要给我吗？"
D.Strings[72861]="在戈尔隆德，就连天空都非常危险。请保持警惕。"
D.Strings[72862]="我要去见游侠艾达妮。"
D.Strings[72863]="范加尔将前往荣耀之路并清除它见到的所有部落成员。"
D.Strings[72864]="那是什么？是玛拉达尔做的吗？不不，你不用那么做。他不可靠。"
D.Strings[72865]="传送门已经开始运转了，$n！你可以使用它们迅速往返于阿什兰各地。"
D.Strings[72866]="术士们可以建造传送门，让我们在阿什兰快速移动。我们只需要收集散落在阿什兰的那些神器中的魔力。$B$B你给我带来多少了？"
D.Strings[72867]="她已经不是我的姐妹了，她只是一个被禁锢在我们世界中的扭曲灵魂。她曾是那么甜美、那么可爱、那么年轻……这都是影月氏族干的！他们用邪恶的魔法扭曲了她！让她像阴影一样在世界上游荡，在永恒的折磨中哭号。\n\n我不能。我做不到。我不能结束她的痛苦。我无法减轻她的苦难。\n\n去解放她的灵魂吧。让她安息。我不忍心看她这个样子。"
D.Strings[72868]="你成功了？好吧。请你走开，让我独自哀悼我的亲人。\n\n这么年轻……她还这么年轻……"
D.Strings[72869]="我们在这里的任务已经完成了。鲁克玛被遗忘的孩子勇敢地迎战他们任性的同胞。现在，我们得继续进攻了。抓紧了，我们的目标是下一座山峰。"
D.Strings[72870]="投降吧，老朋友……在你临死之前，我们会宽恕你的罪孽的。"
D.Strings[72871]="索克雷萨！我们带来了你谋杀副官的证据。你是想要报复我们呢，还是你已经害怕了？"
D.Strings[72872]="他们死在圣光的荣耀之下。而你将死在我们面前，恶魔！"
D.Strings[72873]="谁敢来挑战我？我可是那些大人物的代言人，他们迟早会将这个世界烧成灰烬！"
D.Strings[72874]="休想！我的力量来自燃烧军团……永无止境。"
D.Strings[72875]="现在，去死吧！"
D.Strings[72876]="当你见到加兹莫夫的时候，告诉他是加比让你来的！"
D.Strings[72877]="那个卑贱的流亡者到最后只求速死——你也会跟他一样的！"
D.Strings[72878]="我们决不能让那件遗物落入食人魔之手！那是私人藏品！"
D.Strings[72879]="原来这就是那个鬼祟的家伙想要掩盖的东西……高阶贤者一定会很满意的。"
D.Strings[72880]="阿什兰东南方和西北方的两座传送门已激活。你可以使用它们往返于两地之间。"
D.Strings[72881]="传送门有什么用？"
D.Strings[72882]="奥耐卡，这里很不安全——信徒们已经倾巢出动了。跟我们一起去泰罗克鸦巢吧。"
D.Strings[72883]="噢，你真好，瑞沙德！我从来不知道你这么关心我。"
D.Strings[72884]="但我这把老骨头只会拖累你们。我在这里不会有事的。"
D.Strings[72885]="下次发掘活动再见，$n！没有你，我们不可能完成这个任务。"
D.Strings[72886]="打得好，女伯爵莉亚德琳。让我们回圣光高塔去吧。"
D.Strings[72887]="您也一样，大主教。我们得去向大法师卡德加报告了。"
D.Strings[72888]="一头小戈隆让你的部队陷入了恐惧！"
D.Strings[72889]="我带来了这个作为和平礼物。希望我们能成为亲密的盟友。"
D.Strings[72890]="你带来了这件奇怪的礼物，还帮助了斯克提斯的鸦人……是的，我想我们可以达成协议。阴影能够庇荫万物。"
D.Strings[72891]="这是谁呀？一位至亲好友？"
D.Strings[72892]="我们决不能让燃烧军团在德拉诺获得立足之地。索克雷萨的统治必须终结。"
D.Strings[72893]="索克雷萨直接与暗影议会勾结到了一起。为了阻止燃烧军团，我们必须终结他的统治。"
D.Strings[72894]="我承认，索克雷萨虽然疯狂，但他的话也有那么一丝道理。"
D.Strings[72895]="他质疑了我们的自满情绪。或许我们确实是太满足、太保守了，一味躲藏在德拉诺。"
D.Strings[72896]="时代的召唤已经临近，英雄。我能感觉到，它就在地平线的另一边，声势浩大、若隐若现。当它来临时，德莱尼必须做出响应。"
D.Strings[72897]="今天，我们击败了古尔丹最强大的盟友之一。"
D.Strings[72898]="没有了他们的领导者，萨格雷就会分崩离析。奥金尼很快就能夺回他们的城市。"
D.Strings[72899]="|c00FFFF00|Hspell:178535|h[术士传送门]|h|r被部落摧毁了！"
D.Strings[72900]="我们可以暂时将它看做一场里程碑式的胜利。谢谢你，英雄。"
D.Strings[72901]="先锋会守住前线的，指挥官。你必须完成你的任务！"
D.Strings[72902]="就快到了。过来，珀西！"
D.Strings[72903]="我准备好起飞了，卡鲁。"
D.Strings[72904]="肃静！"
D.Strings[72905]="重大新闻！"
D.Strings[72906]="拉斯托克，我要你遮蔽那片挖掘场。库拉，你来支援他。"
D.Strings[72907]="暗影蔽日……"
D.Strings[72908]="信徒的胆子越来越大了。我们现在只能保护泰罗克鸦巢不受他们的侵袭。"
D.Strings[72909]="你拿到圣物了吗？"
D.Strings[72910]="是的，是的。我还发现了一些意想不到的东西！我们得好好商量一下。"
D.Strings[72911]="<鸦母的声音在你的脑海中响起。>$B$B你知道我为什么会让这些被诅咒、被鲁克玛遗忘的子孙跟我的鸦群住在一起吗？因为我同情他们。$B$B他们在两位神灵之间左右为难：一位恐惧并排斥他们，一位则想用他的黑暗意志奴役他们。$B$B他们唯一的勇士很久之前就抛弃了他们，从那时起，就再也没有人站在他们那边了。$B$B直到你的出现。"
D.Strings[72912]="谢谢你，指挥官。如果她出了什么意外，我真不知道自己该怎么办。"
D.Strings[72913]="你最好习惯失去，孩子。这就是生活。"
D.Strings[72914]="我们是霜狼兽人。我们从不失败，血精灵。"
D.Strings[72915]="我一定要为我的家人报仇。"
D.Strings[72916]="谢谢你让指挥官过来，曼科里克。"
D.Strings[72917]="我再也不想跟你分开了。"
D.Strings[72918]="好样的，孩子。"
D.Strings[72919]="瑞沙德！你活着逃出了斯克提斯！"
D.Strings[72920]="差点就死了。我们来迟了吗？"
D.Strings[72921]="我家人的灵魂将永远在我心里。"
D.Strings[72922]="感谢你所做的一切，指挥官。$B$B我很高兴能和曼科里克团聚，虽然他有时候像个混蛋。你可别告诉他，但我也有点喜欢他。"
D.Strings[72923]="我真是个笨蛋，居然没有跟她一起走。"
D.Strings[72924]="我欠你一条命，指挥官。$B$B我和奥格拉已经对彼此许下誓言。总有一天，她会成为我的妻子。"
D.Strings[72925]="异教徒！杀呀！吃了他们！"
D.Strings[72926]="真该死。我在把玛拉达尔丢给钢铁部落时还以为能彻底摆脱他了呢。"
D.Strings[72927]="没错，是我杀了哈塔鲁。而你就是下一个。"
D.Strings[72928]="燃烧军团有着无可比拟的力量。"
D.Strings[72929]="这片丛林很美丽。我以前从没见过这样的地方。$b$b当然，卡尔娅总是强调，“就因为这样，所以丛林会害死你的。”"
D.Strings[72930]="干得好。这件神器就归你使用了。"
D.Strings[72931]="这片丛林可不是拜神者和金属匠来的地方。$b$b可是对你，我却有些不敢肯定。$b$b你的武器和装备说明你是一个去过许多地方的人。"
D.Strings[72932]="搜索书籍"
D.Strings[72933]="这是一个传统的路边神龛。泰罗克在各地建造了许多这样的神龛来引导流亡者前往斯克提斯。"
D.Strings[72934]="如果我们想要进步，就得明白自己究竟遗忘了什么。"
D.Strings[72935]="这把武器看起来很旧，还生锈了……你还说这是新造的！"
D.Strings[72936]="这把斧子连树枝都砍不断……更别说一个角斗士了！"
D.Strings[72937]="这把武器上刻着某人的名字缩写……你是在竞技场的地上捡来的吗？"
D.Strings[72938]="这些武器太钝了，根本没法用来战斗……"
D.Strings[72939]="你的价钱很公道……但这些武器也太破了。"
D.Strings[72940]="这些到底是角斗士的武器还是旅游纪念品？"
D.Strings[72941]="要我拿着这面盾牌去战斗的话，我还不如带根树枝去呢……"
D.Strings[72942]="你管这叫战斧？它看上去更像一把廉价的砍柴斧……"
D.Strings[72943]="艾泽拉斯的命运就全看你的了，$n！"
D.Strings[72944]="就是它了，指挥官$n。审判日已经降临！我们必须胜利！"
D.Strings[72945]="让我们安全地回家吧，$n。我还想见到我的亲人呢。"
D.Strings[72946]="如果我的牺牲能让你顺利完成任务，那我的死就是有价值的。"
D.Strings[72947]="那座大门的能量似乎源于无辜者的灵魂！"
D.Strings[72948]="我听说古尔丹就在这里！这是真的吗，指挥官？"
D.Strings[72949]="我一辈子都在为这一刻而努力。为艾泽拉斯而牺牲就是最荣耀的死法！"
D.Strings[72950]="来吧，来吧！到我的火炉旁来坐坐。想要来几条青蛙腿吗？"
D.Strings[72951]="你们的尸体将成为鲜花的肥料。是不是感觉很欣慰呢？"
D.Strings[72952]="她死了！我要离开这儿！"
D.Strings[72953]="再卖力点儿！认真点儿！再快点儿！加把劲儿！"
D.Strings[72954]="把垂降绳索放下去，指挥官。"
D.Strings[72955]="你们以为自己就是角斗士了？我要踩碎你们的脑袋！"
D.Strings[72956]="卖力打，否则你们也不用等进了竞技场再死那么麻烦了，我现在就亲手杀了你们！"
D.Strings[72957]="我会到那里跟你汇合的。不用等我！"
D.Strings[72958]="继续，我会没事的！我可以赶上来。"
D.Strings[72959]="我才不是叛徒。是那个虚伪的先知维伦背叛了我们的人民。"
D.Strings[72960]="你有补给品要给我吗，指挥官？每一件补给品都能对战争有所帮助。"
D.Strings[72961]="%s携带着一个血槌宝箱！"
D.Strings[72962]="还有补给品吗，指挥官？我们的战士总会需要它们的。"
D.Strings[72963]="等你们这些废物死在竞技场里时，我一定会哈哈大笑的！"
D.Strings[72964]="现在，我要侍奉我们真正的主人。响应曾被我拒绝的——燃烧军团的召唤。"
D.Strings[72965]="如果你们想像蝴蝶一样跳舞……那你们也会像蝴蝶一样被拍死的！"
D.Strings[72966]="萨格拉斯大人将烧焦这个可悲的世界，就像他曾经摧毁的无数个世界一样。"
D.Strings[72967]="你们这些懦夫，连给竞技场擦地板都不配！"
D.Strings[72968]="等你们死在那里之后，我会让肉肠好好享用你们的尸体！"
D.Strings[72969]="你们要生存下去，并为了竞技场的荣耀而厮杀！"
D.Strings[72970]="我已在圣礼上宣誓。接受了新的名字……索克雷萨。"
D.Strings[72971]="哦嘿！这些植物人散播的到处都是，可我却再也不想见到他们了！"
D.Strings[72972]="点燃火把"
D.Strings[72973]="检查脉搏。"
D.Strings[72974]="非常遗憾，这位审讯者没能坚持下来，他牺牲时正当盛年。"
D.Strings[72975]="嘘……你不会有事的，尼莎。"
D.Strings[72976]="刚才那下差点打中我！"
D.Strings[72977]="我不是故意偷你东西，真的！"
D.Strings[72978]="从没有人跟我说过偷东西不好！我还是个小孩子时就被人教坏了！"
D.Strings[72979]="放我下来吧，我已经知道错了！"
D.Strings[72980]="哇，你为了那个目标所以想要在竞技场里战斗？"
D.Strings[72981]="我只是想借用一下你的钱包……还有你的装备……你的坐骑。我会还回来的！"
D.Strings[72982]="你恐怕是我见过的最差劲的弓箭手了！"
D.Strings[72983]="艾泽拉斯被一个想要统治世界的邪恶敌人入侵了。$b$b如果我们想制止这逐渐蔓延的混乱，就必须尽快行动。"
D.Strings[72984]="我保证再也不说谎、骗人或者偷东西了！真的！"
D.Strings[72985]="我将获得应有的地位。"
D.Strings[72986]="燃烧军团必胜。"
D.Strings[72987]="还有别人在听从我的指令。他们都在沙塔斯和奥金顿。"
D.Strings[72988]="够了！当我们下次再见时，胜利的一定是我。"
D.Strings[72989]="告诉剩余的大主教，他们的生命已经进入了倒计时。"
D.Strings[72990]="开始收割器官。"
D.Strings[72991]="求求你！送我去议政厅吧！"
D.Strings[72992]="加玛克已经死了。你今天打得不错。回营地来见我吧。"
D.Strings[72993]="这场疯狂到此为止了，加玛克！"
D.Strings[72994]="为了守望堡！"
D.Strings[72995]="我们必须守住前线！"
D.Strings[72996]="我很高兴有你在我们这边，$n。"
D.Strings[72997]="如果让那些钢铁部落的战争机器继续运转下去，我们就不可能赢得这场战斗。"
D.Strings[72998]="那些机器被摧毁之后，我们就可以集中精力进行下一步的行动了。"
D.Strings[72999]="如果敌人总能领先我们一步，那我们是不可能赢得这场战斗的。"
D.Strings[73000]="干掉那些斥候之后，我们就更有机会打钢铁部落一个措手不及了。干得好，$n。"
D.Strings[73001]="我的货物只卖给食人魔和角斗士！如果你不属于这两种人，我就要用我的锤子砸烂你的脸！"
D.Strings[73002]="守望堡已经失去太多了。我不忍心再看着他们继续牺牲了。"
D.Strings[73003]="给肉肠的肉一定要是最新鲜的！否则我就打扁你的脑袋！"
D.Strings[73004]="我就是黑夜！"
D.Strings[73005]="但愿你救出的俘虏有机会重振守望堡的辉煌。"
D.Strings[73006]="为了鸦母！"
D.Strings[73007]="在竞技场里划伤了膝盖？只要你出得起价钱，我什么伤都能治好！"
D.Strings[73008]="我又能飞了！"
D.Strings[73009]="将那些作战计划带回来给我，我们就可以开始瓦解这个钢铁部落了。"
D.Strings[73010]="快来买汉堡啊！你喜欢香肠？我这里有最美味多汁的裂蹄牛香肠！"
D.Strings[73011]="唔……钢铁部落似乎和巨槌食人魔结盟了。这局面比我想象的还要难应付。"
D.Strings[73012]="你想在竞技场里战斗？你需要的所有装备都能在我这里一次买齐！"
D.Strings[73013]="你想要打人、砸人、砍人或者捅人吗？我这里的武器能满足你的一切需求！"
D.Strings[73014]="在守望堡里插下联盟的旗帜，剩下的事就交给我们的人吧。"
D.Strings[73015]="我们得继续打压钢铁部落。一定要让他们知道，我们是不会坐视他们屠杀我们的兄弟姐妹的。"
D.Strings[73016]="我在欧卡里隆堡垒等着你。我们要一起解决加玛克。"
D.Strings[73017]="加玛克死了之后，钢铁部落就会陷入群龙无首的局面，直到他们选出在艾泽拉斯的新首领为止。虽然我们赢得了这场战斗，但我担心战争才刚刚开始。"
D.Strings[73018]="那些食人魔应该在痛苦中慢慢死去。这种毒药绝对能做到这一点。"
D.Strings[73019]="你帮我的姐妹报了仇。我欠你一份人情，$c。"
D.Strings[73020]="原祖荆兽的意志必将实现！"
D.Strings[73021]="你不过是一根必须被拔除的杂草。"
D.Strings[73022]="为了艾韵！"
D.Strings[73023]="为了原祖荆兽！"
D.Strings[73024]="你的尸体将成为我们大军的肥料。"
D.Strings[73025]="去死吧，烂肉。"
D.Strings[73026]="你休想破坏我们的丛林。"
D.Strings[73027]="这里不欢迎你，血肉畜生。"
D.Strings[73028]="杂草！"
D.Strings[73029]="邪恶的怪物。"
D.Strings[73030]="一位惊恐的工人在开阔地带被抓了！"
D.Strings[73031]="别按起爆器！"
D.Strings[73032]="我会努力跑回塞林那里去的。我在那里等着你。"
D.Strings[73033]="去死吧，钢铁部落！"
D.Strings[73034]="焦眉！不！他们像碾死虫子一样杀害了你。我发誓，只要我的体重降到可以战斗的程度，我一定会为你复仇的。"
D.Strings[73035]="好了，我们开始干正事，动手建造发生器吧！"
D.Strings[73036]="让我们把发生器开动起来吧！"
D.Strings[73037]="淘气鬼，你不该来这儿的……"
D.Strings[73038]="你太迟了，可怜的小东西。"
D.Strings[73039]="我永远不会安息！我必须加入塞泰克！"
D.Strings[73040]="我们壮志……未酬……"
D.Strings[73041]="尽管那棵古树一直在攻击，但这些刃牙虎人的表现很不错……我已经等不及要改变局面了！<令人毛骨悚然的笑声>"
D.Strings[73042]="为了火刃氏族！"
D.Strings[73043]="我要让这些刃牙虎人看看谁才是真正的猎人……当然这也是为了嘲颅氏族好！我们需要这些原料！"
D.Strings[73044]="真让人失望……不像被屠杀一空的刃牙虎人村子……也不像惨遭洗劫的植物宝藏……好吧，或许这才是正常的收获。$b$b我最希望的还是能骑着原祖荆兽上战场……"
D.Strings[73045]="面对挑战吧！"
D.Strings[73046]="你是个……可敬的对手……"
D.Strings[73047]="胆敢挑战我的人只有死路一条！"
D.Strings[73048]="我被……击败了？不……"
D.Strings[73049]="过来吧！"
D.Strings[73050]="你伤不了我的！"
D.Strings[73051]="我的培根……煮熟了……"
D.Strings[73052]="求求你，$c，发挥出这颗核心真正的作用！你一定会赢得迪奥诺的极大好感的！"
D.Strings[73053]="让我们提高温度！"
D.Strings[73054]="你的圣光将会熄灭！"
D.Strings[73055]="见证我的辉煌吧！"
D.Strings[73056]="她要爆炸了！"
D.Strings[73057]="小心。"
D.Strings[73058]="喔哦。"
D.Strings[73059]="这些弹药很不稳定！"
D.Strings[73060]="混合剂太多了！"
D.Strings[73061]="我的光芒绝不会熄灭……"
D.Strings[73062]="如果你有现金，我就送你一程！"
D.Strings[73063]="干掉那些斥候之后，我们就更有机会打钢铁部落一个措手不及了。Aka'Magosh，$n。"
D.Strings[73064]="在守望堡里插下部落的旗帜，剩下的事就交给我们的人吧。"
D.Strings[73065]="我们得继续打压钢铁部落。一定要让他们知道，我们是不会坐视他们屠杀我们的同胞的。"
D.Strings[73066]="欧卡里隆已经失去了这么多人。我不忍心再看着他们继续牺牲了。"
D.Strings[73067]="跟着线索，找出隐藏的敌人。"
D.Strings[73068]="但愿你救出的俘虏有机会重振欧卡里隆的辉煌。"
D.Strings[73069]="你要去哪儿，$c？"
D.Strings[73070]="$n，看着我的眼睛，你就能从远处监视阿什兰。$B$B你想看什么？"
D.Strings[73071]="我要看蛮兵高地。"
D.Strings[73072]="我要看熔岩采石场。"
D.Strings[73073]="我要看毁灭斗兽场。"
D.Strings[73074]="我要看灰槌墓地。"
D.Strings[73075]="我会在沃舒古附近的幽魂林地等你。我们必须尽快行动！"
D.Strings[73076]="快逃命吧！它太强大了！"
D.Strings[73077]="我在沃舒古附近的幽魂林地等你。我们必须阻止古加尔！"
D.Strings[73078]="我们唯一可行的方案就是撤退。所有人，跟我来！"
D.Strings[73079]="好像有鱼咬钩了……"
D.Strings[73080]="把它拉上来！"
D.Strings[73081]="你的到来是我们的荣幸，卡加斯。我很高兴看到你再次出现在竞技场，虽然你的手……有些不便。"
D.Strings[73082]="角斗士们！抓住机会，光荣地战死吧，你们将会名垂青史。开始战斗吧！"
D.Strings[73083]="干掉他。"
D.Strings[73084]="卫兵！阻止他！"
D.Strings[73085]="关上大门！保护宫殿。悬槌绝不会毁在你们这种人手里。"
D.Strings[73086]="你们在挑战超出你们理解的力量。让我给你们展示一下……"
D.Strings[73087]="感受你体内流淌的能量！"
D.Strings[73088]="我掌握着岩石和它们的力量。"
D.Strings[73089]="你脆弱的心智抵挡不了我的命令！"
D.Strings[73090]="悬槌绝不会倒下。高里亚帝国绝不会被这些贱民颠覆！"
D.Strings[73091]="马上解决他们，马尔戈斯。把他们扔出我的大殿。"
D.Strings[73092]="你以为你能囚禁我们，马尔高克？（你别想控制我们！）"
D.Strings[73093]="摧毁他们！把这座城市夷为平地！（岩石将属于我们！一切都将归于黑暗！）"
D.Strings[73094]="拿上这把钥匙，躲到安全的地方去！"
D.Strings[73095]="这是我的荣幸才对。鉴于刚才那家伙一下就完蛋了，应该让观众们见识见识真正的超级角斗士。"
D.Strings[73096]="没搞错吧！这些没用的软蛋就是纳格兰的灾星吗？他们看着就是一坨雷象屎。"
D.Strings[73097]="哈！今天的比赛将为巫师之王带去荣耀！我们将看到他在赤塔之战中战胜兽人，夺得血淋淋的胜利！"
D.Strings[73098]="索科塔，等他们被打扁时，我们就能知道他们是什么构成的了！哈哈哈哈！"
D.Strings[73099]="现在，有请我们强大的王者，为他欢呼雀跃吧，有请悬槌之影，比赛冠军，乌尔戈！"
D.Strings[73100]="下面，为悬槌抛头颅洒热血吧！赤塔之战开始！"
D.Strings[73101]="这些懦夫不但没有断手断脚，还砍断了不少手脚！"
D.Strings[73102]="看来他们并不在乎自己会死。"
D.Strings[73103]="那些废物……击败了，乌尔戈！？"
D.Strings[73104]="巫师之王！？在这儿！？陛下离开皇宫，来观看这场史诗大战了。"
D.Strings[73105]="观众们看到了他们想要的，鲜血和伤口。"
D.Strings[73106]="哟，这些小矮子还不错嘛。"
D.Strings[73107]="这些蛆虫很能打。他们被杀掉的时候，我一定会为他们难过的。"
D.Strings[73108]="呵呵，等一下负责打扫的奴隶们要辛苦了。"
D.Strings[73109]="呵呵，要是你被那一下打中，肯定变成肉泥了。哈哈哈！"
D.Strings[73110]="战斗结束后，他们就会变成一滩烂泥。"
D.Strings[73111]="但愿这些废物死掉之后能变得好闻一点。"
D.Strings[73112]="我们不是赢下赤塔之战了吗？"
D.Strings[73113]="不尊重传统的人将得不到明年大赛的邀请。"
D.Strings[73114]="小个子怎么可能战胜强大的乌尔戈？！"
D.Strings[73115]="哎哟，我好像都能感觉到那一下有多狠。"
D.Strings[73116]="卡加斯是个胆小鬼。他砍人的时候，连自己的手都保不住！哈哈！"
D.Strings[73117]="够了！我要让这些废物看看真正的冠军实力。"
D.Strings[73118]="你竟敢阻止我成神！"
D.Strings[73119]="动手！"
D.Strings[73120]="开始仪式吧！我将和虚空合为一体！"
D.Strings[73121]="你不应该来插手的！"
D.Strings[73122]="送我去黑潮栖木。"
D.Strings[73123]="我的叫声能像雷霆一样震慑你的敌人。为我指出目标，然后击落他们！"
D.Strings[73124]="我们建好的传送门已经开始运转了。干得不错！"
D.Strings[73125]="法师传送门有什么用？"
D.Strings[73126]="如果你能将散落在阿什兰的神器碎片带来交给我们，我们就能用它们的力量召唤出法师传送门。$B$B你给我带来多少了？"
D.Strings[73127]="骑兵们都出去执行任务了。感谢你带来的那些神器，干得不错，士兵。"
D.Strings[73128]="给我带回足够的神器，我就能武装我们的骑士，并派他们上战场了。$B$B你给我带来多少了？"
D.Strings[73129]="骑兵有什么用？"
D.Strings[73130]="我们最好的骑士能巡视阿什兰，保卫联盟的利益。你懂的，就是不让部落有好日子过。"
D.Strings[73131]="欢迎来到试炼之环！你的第一个对手将是兽人杀手碾槌！"
D.Strings[73132]="难以置信！碾槌被击败了！索科塔，怎么会这样？"
D.Strings[73133]="让我们接上这个小装置。"
D.Strings[73134]="好了，所有系统都完成了。让它发动起来吧！"
D.Strings[73135]="下一场，你将面对犁爪！这将是一场精彩的大战！"
D.Strings[73136]="哈哈哈哈！！"
D.Strings[73137]="犁爪死了！这是犁爪第一次死在竞技场里！"
D.Strings[73138]="<老国王泰罗克的遗物上装饰着一个粗糙的鸦人雕像。>"
D.Strings[73139]="触摸翼刃，见证泰罗克的传奇之一。"
D.Strings[73140]="下一场试炼即将开始！但愿你会喜欢死亡，因为你将要面对的是霍亚拉！"
D.Strings[73141]="不可思议！霍亚拉被击败了！谁能想到这个结果？"
D.Strings[73142]="山崩！"
D.Strings[73143]="埋葬你！"
D.Strings[73144]="碾碎……你！"
D.Strings[73145]="灰飞烟灭吧……"
D.Strings[73146]="化……为……尘……埃"
D.Strings[73147]="归于尘土……"
D.Strings[73148]="%s发出隆隆的笑声。"
D.Strings[73149]="格鲁尔闻到了肉的味道……"
D.Strings[73150]="哈哈哈哈，格鲁尔一只手就能干掉你们！"
D.Strings[73151]="留下吧……"
D.Strings[73152]="格鲁尔砸死你们！"
D.Strings[73153]="快跑……"
D.Strings[73154]="格鲁尔……倒……下了？"
D.Strings[73155]="格鲁尔碾碎你们！！！"
D.Strings[73156]="联盟打上门来了！部落的士兵们，拿起武器！"
D.Strings[73157]="准备进入下一个回合吧！你将要面对的是爆火上尉和燃烬者。"
D.Strings[73158]="快住手吧。"
D.Strings[73159]="好好好……看看是谁掉进了我们的陷阱。"
D.Strings[73160]="你将成为我献给地狱咆哮酋长的礼物。"
D.Strings[73161]="联盟的蠢货！你们以为袭击了我的营地还能活着回去？！"
D.Strings[73162]="爆火上尉被击败了！现在只剩下一个角斗士了！"
D.Strings[73163]="让我来接上这个装置。马上就好。"
D.Strings[73164]="所有系统激活。开火！"
D.Strings[73165]="他被发现时就是这个样子。被谋杀了！"
D.Strings[73166]="大主教奈丽，有人听到你之前跟哈塔鲁吵了一架？"
D.Strings[73167]="我们经常吵架。但这并不能说明是我杀了他！"
D.Strings[73168]="这把武器被邪能污染了。"
D.Strings[73169]="你似乎对我们敌人的手段非常了解。"
D.Strings[73170]="这是我的职责。我要和尸体沟通。"
D.Strings[73171]="我反对！他遭受的痛苦已经够多了！"
D.Strings[73172]="我同意。退席吧，大主教。伤害已经够多了。"
D.Strings[73173]="我们中间有个叛徒。我必须找出那个人。"
D.Strings[73174]="最后一回合即将开始！狂热者罗卡对挑战者！"
D.Strings[73175]="你完成之后，就到北边来找我吧。"
D.Strings[73176]="难以置信！试炼竞技场的新冠军诞生了！索科塔，你怎么看？"
D.Strings[73177]="碾槌将以泰山压顶之势赢得比赛！哈哈哈！！"
D.Strings[73178]="这显然纯属侥幸！这就是我的专业意见，乔恩！"
D.Strings[73179]="犁爪在饥饿时总是会更加凶猛，而我们这周都没有喂过她。哇哈哈哈哈！！"
D.Strings[73180]="犁爪只是太虚弱了！下一场战斗就没这么轻松了！"
D.Strings[73181]="上一次，霍亚拉在战斗真正开始前就干掉了挑战者！哈哈哈！！"
D.Strings[73182]="是，是啊……没什么大不了的！让我们看看下一场战斗怎么样吧！"
D.Strings[73183]="在爆火上尉的那些战斗中最精彩的部分就是将酥脆的挑战者一口口吃掉！哈哈哈！"
D.Strings[73184]="这回被烤的又酥又脆的人变成了爆火上尉！给我留一条腿！哈哈哈！！一条腿！"
D.Strings[73185]="唯一有实力击败罗卡的角斗士就是乌尔戈！这场战斗还没开始就已经结束了！"
D.Strings[73186]="我们是真正的生死之交，$n。后会有期。"
D.Strings[73187]="这个角斗士将成为竞技场的新冠军，但他还是比不上乌尔戈！"
D.Strings[73188]="很久以前，一位血鬃虎王命令他的猎人们给他送上一万根鸦人羽毛。"
D.Strings[73189]="但利爪之王独自应战，而接下来发生的，也不是什么战争，而是一场屠杀。"
D.Strings[73190]="唔……你不配和乌尔戈战斗！"
D.Strings[73191]="他战斗时就像风一样优雅而强大。"
D.Strings[73192]="他的双翼所到之处，就连最强壮的血鬃战士也像野草一样纷纷倒地。"
D.Strings[73193]="你好啊，指挥官！今天有什么计划吗？$b$b让我上前线吧，我已经准备好了！"
D.Strings[73194]="虽然他们的虎王非常凶猛，但他也比不上泰罗克。"
D.Strings[73195]="你好，指挥官！$b$b有什么东西要修理、修补……或是斩杀吗？"
D.Strings[73196]="在清楚地表达自己的意思之后，利爪之王满意地凯旋，任由血鬃氏族收拾残局。"
D.Strings[73197]="你好，指挥官。$b$b我一直在要塞周围侦察，确保边境安全。不幸的是，那里不止我一个人。有些东西在灌林里监视我，但我让它跑了。足迹消失在了河边。$b$b请保持警惕！"
D.Strings[73198]="渴望在战斗中赢得荣耀的年轻酋长想要挑起与鸦人的战争。"
D.Strings[73199]="游侠切尔前来报到！"
D.Strings[73200]="最后的夕阳已经临近。"
D.Strings[73201]="你好，指挥官。我是游侠切尔。$b$b自从我们首次抵达德拉诺，这个世界就是个谜。一个危险的谜。游侠们受命探索这个全新的、充满敌意的环境。我们学会靠双脚生存——使用周围大地上的自然资源，并悄无声息地进入敌人的领地。$b$b作为你的追随者，我会努力不被发现，压迫敌人并对其造成严重的伤害。"
D.Strings[73202]="我希望有一天能够摘掉“初级”这两个字。"
D.Strings[73203]="指挥官！$b$b我是初级技师安德伦。在哈塔鲁遇害前，我是他最信赖的助手之一。作为技师，我能使用德莱尼科技预先摧毁敌人的战斗力，以便我或其他人彻底消灭他们。或许在你们的眼里，我就像一个……工程战士？$b$b如果你选择了我作为追随者，我会尽我所能为你服务的。"
D.Strings[73204]="守备官欧纳拉，随时待命。"
D.Strings[73205]="指挥官，很高兴见到你。$b$b年轻时，我曾努力训练，希望成为一名学者。但圣光却指引我走上了一条神秘的道路。我的防御法术是如此强大，连先知本人都鼓励我向守备官方向发展。$b$b如今，我已经不再害怕与敌人面对面，并保护我身后的人民了。选择我做你的追随者，我的信仰将成为保护你的盾牌，我的盔甲将是守护你的要塞不受敌人侵扰的壁垒。"
D.Strings[73206]="石槌食人魔迫使我们成为了角斗士。$b$b我们日复一日地战斗、杀戮、行礼。$b$b那些食人魔让我们和他们能找到的一切野兽或生物战斗。$b$b经过了漫长的计划，我们中的一些人成功逃跑了。"
D.Strings[73207]="现在，我终于可以按自己的心意杀人了！你完成之后，就到食人魔高地来找我，我们要一起撕碎敌人！"
D.Strings[73208]="塔纳安的行动一切顺利。堡垒就快建成了。"
D.Strings[73209]="酋长，我一直在密切关注悬槌食人魔。到目前为止，他们一直很……恭顺。"
D.Strings[73210]="你那边呢，黑手？"
D.Strings[73211]="联盟和部落的队伍袭击了铸造厂，但我完全能够应付。"
D.Strings[73212]="又来了，黑手？我已经听够借口了。"
D.Strings[73213]="阿祖卡！寻找巨灵的行动怎么样了？"
D.Strings[73214]="一切顺利，酋长。只要拿到高格里克之心，我们就能让它复活了。"
D.Strings[73215]="很好。我还打算让你去对付那些异界人。你有没有丢掉你先辈们的血性呢？"
D.Strings[73216]="我的剑术已经超过了我的祖先，酋长。我完全有能力帮黑手收拾他的烂摊子。"
D.Strings[73217]="哼……小心我割掉你的舌头！"
D.Strings[73218]="哈哈哈……真是大胆，不愧是我最年轻的督军。非常好。"
D.Strings[73219]="拔出你祖传的利刃。让它饱饮敌人的鲜血吧。让我看看它的传奇力量。"
D.Strings[73220]="证明你自己，阿祖卡，我就会将你和其他督军一视同仁。"
D.Strings[73221]="别担心，小老鼠。我还没忘了你呢。我等一会儿……就来对付你。"
D.Strings[73222]="我……我丈夫……你救出我丈夫了吗？"
D.Strings[73223]="非常感激，陌生人，我愿意为你效劳。在离开之前，去杀个食人魔酋长怎么样？"
D.Strings[73224]="再打一场吧。"
D.Strings[73225]="已经累了吗，小德莱尼？"
D.Strings[73226]="你得学会在每次击杀敌人后行礼，否则我就挖出你的另一只眼睛。"
D.Strings[73227]="再快点！你应该只需要一半的时间就能干掉它了。"
D.Strings[73228]="安德伦，我选择你！"
D.Strings[73229]="你确定想要这位追随者吗？"
D.Strings[73230]="我想再跟其他人谈谈。"
D.Strings[73231]="切尔，我选择你！"
D.Strings[73232]="欧纳拉，我选择你！"
D.Strings[73233]="别泄气，$G先生:女士;。我是来帮你的。"
D.Strings[73234]="来吧，小德莱尼，那家伙伤不了你。是你自己太大意了。"
D.Strings[73235]="真是只聪明的小鸟。你现在还剩下多少小聪明呢？"
D.Strings[73236]="滚开，入侵者！我，马尔科才是这里的主宰！我的仆从们将啃食你们的骨头！"
D.Strings[73237]="我的仆从们，找出那些入侵者！找到他们，把他们带来见我！"
D.Strings[73238]="如果你们跪下来求我，那我就在把你们丢进消化池前给你们一个痛快！"
D.Strings[73239]="别以为你的夸夸其谈能骗得了我。"
D.Strings[73240]="别担心我。我认识这附近的路。"
D.Strings[73241]="我在这附近转转。看看你能不能在营地的其他地方有所发现。"
D.Strings[73242]="你去哪儿了，我的兄弟！自从我们上次见到食人魔，这才过了一千年！他们随时可能卷土重来，我们必须保持警惕！"
D.Strings[73243]="你对格罗玛什·地狱咆哮的计划知道些什么？"
D.Strings[73244]="骄傲的伊基什，戴着镣铐，距离你的宝贝斯克提斯万里之遥。"
D.Strings[73245]="我……我要留下来，直到完成任务。我的兄弟们……返回了茂林，我再过几千年就回去找你……我还不能休息，必须等我的仆从们将每一块人工岩石砸成碎粉！"
D.Strings[73246]="我……我不记得了……这是什么？一群血肉之躯在我的地盘里！杀了他们，我的仆从们！"
D.Strings[73247]="你随时都能走，只要你会飞。呵呵。"
D.Strings[73248]="杀食人魔！等等……已经没有食人魔了……早就全跑光了。只剩下他们破败的废墟，必须归入大地……"
D.Strings[73249]="加尔鲁什·地狱咆哮在跟他的督军们——黑手、卡加斯·刃拳、基尔罗格·死眼和阿祖卡·刃怒开会。我会注意阿祖卡的……她似乎将负责消灭联盟在德拉诺的部队。"
D.Strings[73250]="援军到了！干掉那些残兵败将。"
D.Strings[73251]="<附近的一张纸片上写着：$B$B我们发现了裂世者高格里克，这头上古玛戈隆被冻结在戈尔隆德的一个岩池里。$B$B战歌氏族的长老们相信这头玛戈隆曾是强大的毁灭者首领，能够号令同类的低级生物。$B$B古老的氏族文献上说，这头野兽是可以被唤醒的。>"
D.Strings[73252]="<黑石铸造厂的地图周围都是碎纸片。看起来像是战争机器的制造订单。>"
D.Strings[73253]="<这张地图上的塔纳安丛林里画着许多记号，包括防御工事的位置和军队的行军路线。地狱咆哮似乎对这一地区非常感兴趣。>"
D.Strings[73254]="触摸手镯，见证泰罗克的贬落。"
D.Strings[73255]="接受泰罗克的力量。"
D.Strings[73256]="送我去暗影哨所。"
D.Strings[73257]="很荣幸能为您效劳，指挥官。"
D.Strings[73258]="|TInterface\\Icons\\spell_holy_avengersshield:20|t%s向$n投出了|cFFF00000|Hspell:153480|h[神圣之盾]|h|r！"
D.Strings[73259]="听候您的调遣。"
D.Strings[73260]="利爪之王的贤者们背叛了他。泰罗克和他的盟友被投入了血池。"
D.Strings[73261]="被诅咒的鲜血烧灼着他的血肉，撕扯着他的精神。"
D.Strings[73262]="在痛苦中，泰罗克只担心一个人：他的女儿蕾希。"
D.Strings[73263]="看着她破碎的尸体，泰罗克绝望了，最终屈服于可怕的黑暗。"
D.Strings[73264]="但在黑暗中，某个存在找到了它。"
D.Strings[73265]="一种陌生的力量充盈在利爪之王体内。某个存在不断鞭策着他。"
D.Strings[73266]="蠢货！你落入了我的陷阱！"
D.Strings[73267]="一颗奇怪的宝珠从虚无中复现出来。泰罗克凝视着它，见到了拯救他的存在。"
D.Strings[73268]="鸦神安苏，赐予泰罗克和他的护卫们黑暗的力量。后来，他们就被称为鸦爪祭司。"
D.Strings[73269]="这是你们的人吗？"
D.Strings[73270]="小心点，野狗！"
D.Strings[73271]="滚开，蠢货！"
D.Strings[73272]="我都说了！告诉他我是谁，指挥官。告诉他我是多么喜欢骨头和杀戮。"
D.Strings[73273]="你在别处绝对找不到这么好的货色了！"
D.Strings[73274]="这些都是我亲自偷运过来的！"
D.Strings[73275]="没时间讨价还价了！不买就走吧。"
D.Strings[73276]="很好，但我的动物朋友们会保持警惕的。"
D.Strings[73277]="我得走了。或许你下次可以多花点钱。"
D.Strings[73278]="没时间了。我该回去骗当地人了。"
D.Strings[73279]="我又该上路了。"
D.Strings[73280]="该走了。别惹麻烦！"
D.Strings[73281]="卡加莎可找到你了，伙计。我是来帮你的。"
D.Strings[73282]="嘘……让他们都睁大眼睛，竖起耳朵。"
D.Strings[73283]="援军到了！把这群乌合之众赶出暴风之盾！"
D.Strings[73284]="暴风之盾遭到了攻击！守好防线。击退他们！"
D.Strings[73285]="醒醒！可悲的蛆虫……我们怎么会跟你们扯上关系。"
D.Strings[73286]="使用虚空道标"
D.Strings[73287]="走开，小鬼。我都说了，我们不感兴趣。"
D.Strings[73288]="<买卖你的战利品>"
D.Strings[73289]="你有些不错的货色，伙计。我能帮你把它们变成肮脏的铁币。我有我的门路。稍后再来找我，用这些硬币买点好货色吧！"
D.Strings[73290]="不要对部落的家伙手软，$n。把他们死亡的证据带来给我，我会好好奖赏你的。"
D.Strings[73291]="我听说过督军刃怒。她是位剑圣，在兽人氏族中未有败绩。那些低估了她的人，都死了。"
D.Strings[73292]="她野心勃勃，聪敏过人，而且非常残酷。既然她已经成为督军，我们最好小心一点。"
D.Strings[73293]="我听说过督军刃怒。她是位剑圣。许多人最初都轻视了她，可她在兽人氏族中却是百战百胜。"
D.Strings[73294]="她野心勃勃，聪敏过人，而且非常残酷。既然她已经上台，我们恐怕很快就会面对她了。"
D.Strings[73295]="那些被诅咒逼疯的可怜人在血池中痛苦地翻滚。但泰罗克让他们得到了解脱。"
D.Strings[73296]="|TInterface\\Icons\\sha_ability_rogue_bloodyeye.blp:32|t$b|cFFFF0000|Hspell:167410|h[卡德加的守望]|h|r回溯了时间！"
D.Strings[73297]="准备与钢铁部落战斗。"
D.Strings[73298]="我准备好了，高阶鸦语者。"
D.Strings[73299]="很好，非常好。"
D.Strings[73300]="不对，仪式不该是这样的。再试一次。"
D.Strings[73301]="沙塔斯的防御者们，我们已经占领了码头！撤回城区，搜寻幸存者吧！"
D.Strings[73302]="蠢孩子。现在你是我的财产了。"
D.Strings[73303]="你父亲抛弃你了。现在你将顶替他在竞技场的位置。"
D.Strings[73304]="你将长大，你将流血，你将战斗，或是死亡。"
D.Strings[73305]="现在该轮到你了，小鬼，去为你逃跑的父亲还债吧。"
D.Strings[73306]="我父亲会把你的角撕下来。"
D.Strings[73307]="你最好担心一下我离开笼子的那一天！"
D.Strings[73308]="你不可能永远关着我。"
D.Strings[73309]="你们这些狗东西很快就将为钢铁部落的强盛贡献出你们的力量！"
D.Strings[73310]="嘘……这一切很快就会结束了。痛苦将会结束，你们的灵魂将离开身体，融入黑暗之门！"
D.Strings[73311]="这就是你们霜狼氏族不肯加入钢铁部落的代价！"
D.Strings[73312]="别着急，现在，钢铁部落正在霜火岭积聚力量。你们的家园很快就将属于我们！"
D.Strings[73313]="我们抓住了你们的首领！哈！他正在采石场里铲我们的大粪呢！下一个就该轮到他的兄弟杜隆坦了！"
D.Strings[73314]="我们抓住了暗影议会和他们的首领古尔丹！他们正在为这个传送门提供能量——用你们的灵魂！"
D.Strings[73315]="只有通过对鸦母的信仰，我们才能获得救赎。"
D.Strings[73316]="这可能会有一点疼。"
D.Strings[73317]="就像待宰的小鸟一样。"
D.Strings[73318]="我要吞掉你的骨头！"
D.Strings[73319]="我的项链上又多了一件战利品。"
D.Strings[73320]="你们的“先知”有没有预见到你们的下场呢？哈！"
D.Strings[73321]="小德莱尼，你以为你们能永远压在我们头上？这是我们的世界，没人能阻止我们得到它！"
D.Strings[73322]="钢铁部落的战争机器已经开向卡拉波了。那里很快就会化为灰烬！"
D.Strings[73323]="你的人民将滋养钢铁部落的战争机器！"
D.Strings[73324]="你们的灵魂将成为传送门的燃料。很快，你就将和无数已经消亡的灵魂一样了！"
D.Strings[73325]="没人能阻挡督军们！你毫无机会！一旦卡拉波陷落，沙塔斯也将迅速失陷！"
D.Strings[73326]="时间或许能夺走我的一部分力量，但我这头老狼还是能咬人的！"
D.Strings[73327]="至少，我是……战死的……"
D.Strings[73328]="<当你靠近萨满之石，卡拉迪奥斯的声音在你脑海中响起。>"
D.Strings[73329]="作为泰兰德的侍女，我的哨兵们随时可以与你并肩作战，并保卫你的要塞。"
D.Strings[73330]="我想让暗夜精灵来守卫要塞。"
D.Strings[73331]="尼古拉斯先生？请再来一杯咖啡。"
D.Strings[73332]="马上就来，孩子。代我向你妈妈问好。"
D.Strings[73333]="她是我最好的顾客。"
D.Strings[73334]="谢谢，我会的。"
D.Strings[73335]="这座要塞是你的地盘，指挥官。"
D.Strings[73336]="换回人类守卫。"
D.Strings[73337]="嘿，阿娜！"
D.Strings[73338]="嘿，艾克桑德。"
D.Strings[73339]="嗨，托普。"
D.Strings[73340]="你最好快点，孩子。那杯咖啡很快就不热了。"
D.Strings[73341]="别担心，你们都会轮到的。"
D.Strings[73342]="这是你的咖啡，妈妈。"
D.Strings[73343]="呼。我真的要休息一下了。"
D.Strings[73344]="呃。我刚刚刷的靴子。"
D.Strings[73345]="谢谢，宝贝。"
D.Strings[73346]="唔，真不错。好了，你可以走了。去玩吧。"
D.Strings[73347]="所有人都到位了吗？很好，让我们开始吧！"
D.Strings[73348]="好的！我们一小时后见。"
D.Strings[73349]="他最强大的护卫保持了清醒。当利爪之王发出召唤，他们立刻做出了响应。"
D.Strings[73350]="嗨，儿子。"
D.Strings[73351]="这在“坠沙圣典”和“时不我待”中有明确记载。鸦母早就知道会有一个不属于鸦群的外人参加仪式！噢，你真是受眷顾的幸运儿！"
D.Strings[73352]="嘿，爸爸！"
D.Strings[73353]="嘿，就是你！你一定要帮帮我……我的裤子都快把我的皮肤磨破了。"
D.Strings[73354]="我们要让空气中充满甜香味。在火里加点香料。"
D.Strings[73355]="现在，诵读群鸦卷轴以获取启示。"
D.Strings[73356]="快，将圣羽丢到风里！"
D.Strings[73357]="现在，将圣水泼进火里！"
D.Strings[73358]="他们一起建造了斯克提斯，庇护不受鲁克玛垂青的孩子。"
D.Strings[73359]="年复一年，利爪之王的身体逐渐衰弱。他的心中充满悲伤，诅咒时刻都在啃噬着他的精神。"
D.Strings[73360]="他开始憎恨这个世界，不但抛弃了斯克提斯，甚至牺牲自己的子民来寻求解脱。"
D.Strings[73361]="鸦母！我们谦卑地欢迎您回到鸦巢！您的光临让我们喜不自胜！"
D.Strings[73362]="你管这叫痛苦？我对自己做的可比这狠多了。"
D.Strings[73363]="你的毒药不值一哂。"
D.Strings[73364]="是的……痛苦……它支撑着我……"
D.Strings[73365]="还要……我还要更多！"
D.Strings[73366]="我的意志坚如钢铁。我是不会说的。"
D.Strings[73367]="再加把劲儿，小崽子。"
D.Strings[73368]="我要嚼碎你的骨头。"
D.Strings[73369]="你想要痛苦？我让你看看什么才叫痛苦。"
D.Strings[73370]="我曾砍断过自己的手。你不算什么！"
D.Strings[73371]="对，更多。我还要更多！"
D.Strings[73372]="卡加斯会把你的尸体挂在他的宝座上。"
D.Strings[73373]="这就是你对毒药的理解？我洗澡用的毒药都比它强。"
D.Strings[73374]="让我给你尝尝真正的毒药吧。"
D.Strings[73375]="我已经把一切都献给了碎手氏族。你从我这儿得不到什么。"
D.Strings[73376]="我是为痛苦而活的。你这点本事太弱了。"
D.Strings[73377]="你太迟了。我们的毒刃将成为你的末日。"
D.Strings[73378]="住手！够了！"
D.Strings[73379]="我们的刺客首领名叫加杜尔·毒刃。毒药都是他配制的。"
D.Strings[73380]="他现在就在道路那头的营地里。可你永远都无法阻止……"
D.Strings[73381]="杀死鸦人的毒药是谁配制的？"
D.Strings[73382]="幕后黑手是谁？他们在哪儿？"
D.Strings[73383]="你刀刃上的毒药是谁配制的。说！"
D.Strings[73384]="回答我！你用的毒药是谁配制的？"
D.Strings[73385]="你配不出这种毒药。只要告诉我是谁干的，你就可以解脱了。"
D.Strings[73386]="这个“G.V.”是谁？他的毒药杀死了鸦人。说！"
D.Strings[73387]="是谁领导了对鸦人的袭击？他躲在哪儿？"
D.Strings[73388]="不要考验我的耐心。告诉我，你手里的毒药是谁配制的？"
D.Strings[73389]="别浪费我的时间。这个“G.V.”是谁，他又在哪儿？"
D.Strings[73390]="住手，兄弟们。我觉得这个人不像是食人魔的爪牙。"
D.Strings[73391]="住手，朋友们！这家伙看起来不像食人魔的爪牙。"
D.Strings[73392]="%s被毒药击垮了。"
D.Strings[73393]="时间宝贵！到苍白地穴来找我，我们将一起面对古加尔！"
D.Strings[73394]="我们必须拯救克乌雷！到苍白地穴来找我，我们将一起面对古加尔！"
D.Strings[73395]="噢，我的腿！"
D.Strings[73396]="小小！求求你，别死！"
D.Strings[73397]="请你救救小小吧！"
D.Strings[73398]="他会好起来吗？"
D.Strings[73399]="你干嘛要去跟那些兽人老坏蛋战斗呢！？"
D.Strings[73400]="坚持住，小小！"
D.Strings[73401]="别担心，他会好起来的。"
D.Strings[73402]="他战斗得非常勇敢，你应该为他骄傲！"
D.Strings[73403]="你的雷象救了很多人的生命。"
D.Strings[73404]="我保证会让他痊愈的。"
D.Strings[73405]="好了，该走了！"
D.Strings[73406]="我看到你的朋友就在上面的大厅里。我想我可以安全地抵达那里。"
D.Strings[73407]="你——是从传送门的另一边来的！你会成为很好的祭品。"
D.Strings[73408]="靠近点……燃烧吧！"
D.Strings[73409]="让虚空吞噬你！"
D.Strings[73410]="耐奥祖……救救我……"
D.Strings[73411]="帮我们弄点护甲和武器来。我发誓，如果有需要，我的同胞可以在这些兽人中杀出一条通向卡拉波的血路来。"
D.Strings[73412]="只要你将斧子交到我们手里，我保证，这里的每一个霜狼兽人都能打赢十个其他氏族的兽人。"
D.Strings[73413]="我们要痛打他们一顿，猪排！"
D.Strings[73414]="哇哈哈！你太没用了！"
D.Strings[73415]="我感觉到了一个不属于鸦群的外人。靠近点，孩子。"
D.Strings[73416]="到我这儿来，兄弟！"
D.Strings[73417]="哦，这比我想的还要糟糕。他们也袭击了这里。"
D.Strings[73418]="黑暗女王在注视着我们。我们并不孤独。"
D.Strings[73419]="我们还不清楚伤亡人数。"
D.Strings[73420]="怎么会这样……"
D.Strings[73421]="……还有孩子们。现在还有谁能照顾他们呢？"
D.Strings[73422]="这不仅影响了我们的生活——天空也变得更阴暗了。整个世界都在为这场袭击而哀悼。"
D.Strings[73423]="愿圣光保佑我们。"
D.Strings[73424]="注意你的姿势。"
D.Strings[73425]="那些野蛮人可不会这么好心地放过这种错误。"
D.Strings[73426]="好……很好。"
D.Strings[73427]="保持平衡。你必须随时保持沉稳。"
D.Strings[73428]="干得好。你的技巧大有进步。"
D.Strings[73429]="见识下高里亚的文明吧！"
D.Strings[73430]="<这个脑袋曾属于一个魁梧的野蛮人，直到另一个名叫布洛奇约的、更魁梧的野蛮人把它扯了下来。>"
D.Strings[73431]="挑战布洛奇约。"
D.Strings[73432]="我最喜欢大清早烧烤角斗士的香味儿了！"
D.Strings[73433]="看一看……"
D.Strings[73434]="鲁克玛起飞了！"
D.Strings[73435]="|TInterface\\Icons\\ability_fixated_state_red:20|t一只凤凰|cFFFF0000锁定|r了你！它将在接触你之后|cFFFF0000|Hspell:167630|h[爆炸]|h|r！"
D.Strings[73436]="快过去，勇士！"
D.Strings[73437]="我需要一些运气！"
D.Strings[73438]="%s向喷泉内扔了一枚硬币。"
D.Strings[73439]="到悬槌堡来吧，我的爪子会撕裂你……"
D.Strings[73440]="治疗开始。"
D.Strings[73441]="我知道这很疼，但你必须坚强，并且多休息。"
D.Strings[73442]="你的伤很重，但你的精神更坚强。"
D.Strings[73443]="祝福对你的伤有好处。"
D.Strings[73444]="$n为逝去的灵魂诵读了祷告词。"
D.Strings[73445]="%s缓缓地吸气，每吸一口气都觉得更加难受。"
D.Strings[73446]="%s无视自己的痛苦，让附近受伤的同胞优先得到照顾。"
D.Strings[73447]="%s低声呢喃着，慢慢发出痛苦的叹息声。"
D.Strings[73448]="%s对着目标用力挥舞着武器。"
D.Strings[73449]="%s调整着战斗姿态，改进自己的平衡性和姿势。"
D.Strings[73450]="%s沉重地喘息着，精准而专注地攻击着目标。"
D.Strings[73451]="我们会有机会的。"
D.Strings[73452]="珀西瓦尔先生今天过得怎么样啊？"
D.Strings[73453]="过来，珀西！"
D.Strings[73454]="真是个好孩子。"
D.Strings[73455]="给我带回足够的神器，我就能武装我们的狼骑兵，并派他们上战场了。$B$B你给我带来多少了？"
D.Strings[73456]="好了，珀西。用力撞！"
D.Strings[73457]="别对他们手软。"
D.Strings[73458]="让他们自食苦果。"
D.Strings[73459]="我想要一份新配方。"
D.Strings[73460]="我想请你帮我做点东西。"
D.Strings[73461]="如果你不介意和怪物、陷阱、强盗以及一切试图杀死你的家伙战斗的话，不知道你能挖到点什么。"
D.Strings[73462]="叛徒，你们这些叛徒。你们把敌人引到家门口来了！"
D.Strings[73463]="为了让衰老的国王恢复活力，鸦爪祭司们将泰罗克封印在暗影之中。"
D.Strings[73464]="嗨，甜心——能回到你的手下真是太好了！$b$b加兹鲁维说你这里可能需要一些地精火力、设备和奇迹的支援，所以我自然就被选上了。$b$b这跟他不想让我靠近他的炸药一点关系都没有。$b$b我会掩护你的，指挥官！"
D.Strings[73465]="而这也造就了我们今天的一切！有了圣物和鸦爪祭司的帮助，我们就能召唤利爪之王了。"
D.Strings[73466]="亲爱的，再考虑一下吧。这不会有什么好结果的。"
D.Strings[73467]="够了。我要亲手解决敌人。"
D.Strings[73468]="大人，我——"
D.Strings[73469]="我们已经为这一篇章画上了句号。但加尔鲁什已经推动了历史的车轮……我们必须终结所有的循环，才能保护艾泽拉斯的安全。为此，我们必须找到并消灭古尔丹。$B$B<卡德加重重地叹了口气。>$B$B但在我们继续干正事之前，还是可以小小地庆祝一下。我这里有一瓶特意为这种场合保存的陈年达拉然红酒，你要是有兴趣，等一下就来我的法师塔找我吧。"
D.Strings[73470]="我还活着呢，你们这些绿皮畜生！有种的话就冲托莫克来啊！"
D.Strings[73471]="诅咒你……马尔高克……"
D.Strings[73472]="你不该在这儿的！对黑暗之门的突袭还没准备好！$b$b稍后再来吧，$c，"
D.Strings[73473]="你看起来是个强大，优秀的$c。我正需要你这样的勇士。$b$b有兴趣冒着生命危险来执行一个拯救艾泽拉斯的自杀式任务吗？$b$b你只要说一句话就行。"
D.Strings[73474]="大法师正在筹备另一场战役。他现在只说这是有关寻找古尔丹的。$B$B可我担心……古尔丹已经试图刺杀过卡德加一次了。大法师需要一切可能的帮助。<科达娜意有所指地看着你。>"
D.Strings[73475]="一句话。"
D.Strings[73476]="我们霜狼兽人总是独来独往，身边只有我们的狼陪伴。但我们的氏族也是这个世界的一部分，我们显然有义务保护它。$B$B这个“加尔鲁什”是个危险的家伙。但他也让我们看到了一些宝贵的东西。我现在明白了团结起来的兽人是多么强大。更重要的是，要有一个正义的声音来领导他们。$B$B霜狼氏族必须成为那个声音。"
D.Strings[73477]="你们就这点本事吗？！我在战斗中烧毁过更多的森林！"
D.Strings[73478]="你们这群杂草不过是在送死！好吧！我既然已经杀了一百个，就能再杀几百个！"
D.Strings[73479]="守备官伊瑞尔说我们必须和来自你们世界的联盟和部落合作。$B$B可是，既然你们的世界诞生了加尔鲁什这种怪物——我们又该怎么相信你们？"
D.Strings[73480]="我是不会死在这片该死的丛林里的！我才不要变成植物的肥料！我只能死在比你们这些植物伟大得多的敌人手里！"
D.Strings[73481]="有人想去塔纳安吗？"
D.Strings[73482]="不要害怕，血肉之躯，你埋入地下之后，将比你行走于地面时更加有用。我保证。"
D.Strings[73483]="哈哈哈，这点小风可伤不了我。"
D.Strings[73484]="钢铁部落始终是个威胁。我们应该打蛇七寸，铲平黑石铸造厂。"
D.Strings[73485]="或许我们可以铲除他们的盟友，纳格兰这里的食人魔就很脆弱了。"
D.Strings[73486]="你从西面攻击敌人的时候，我会掩护你的。"
D.Strings[73487]="很好，很好。"
D.Strings[73488]="没错，进展很顺利。"
D.Strings[73489]="但愿不会再有人来打扰了。"
D.Strings[73490]="要想完成这个星期的定额可不容易。"
D.Strings[73491]="为了证明你配得上这头狼，你必须先通过力量和韧性的考验。 \n\n为此，你必须去采石场找一块沉重的岩石，然后背着它进入敌人的地盘。你得从他们中杀出一条血路，将石头放在显眼的位置，然后在上面摆上得自敌人的战利品。\n\n只有这样，你才能让所有人看到你的力量，才有希望驯服一头座狼。"
D.Strings[73492]="一旦你向所有人展示过你的力量之后，就必须去驯服你的狼了。\n\n去它们的狩猎场吧。你必须找到狼群中最大的狼，在它的同胞面前驯服它。你可能会被它们活吞了，但如果你能从这种严酷的考验中活下来，那这头狼就会奉你为主。"
D.Strings[73493]="光让座狼认你为主还不够。要想骑上你的狼，你还必须彻底征服它的意志。\n\n在驯服你的狼之后，你必须骑着它爬上纳格兰最高的山峰。如果你的狼足够倔强，它可能会把你摔死在山坡上。 \n\n如果你能活着登上山顶，那你的狼就已经完全驯服了。 \n\n然后，你就能自称为“狼骑兵”了。"
D.Strings[73494]="狼骑兵有什么用？"
D.Strings[73495]="我们最好的狼骑兵能巡视阿什兰，保卫部落的利益，把那些联盟狗撕成碎片。"
D.Strings[73496]="克鲁努斯有什么用？"
D.Strings[73497]="这个蠢货。他会把我们直接引到他的制毒基地去。跟紧我。"
D.Strings[73498]="克鲁努斯可以巡视荣耀之路并清除它见到的所有联盟成员。"
D.Strings[73499]="杀……吃……撕成碎片……活……吃了……他们抓住我们……死了……杀了我……杀了我……杀了我……求求你……"
D.Strings[73500]="让这位下士解脱。"
D.Strings[73501]="你还傻站着干嘛呢？快去杀掉几个联盟的渣滓。把他们的脑袋、牙齿、尾巴……随便什么带回来给我！去吧，快！！"
D.Strings[73502]="这个蠢货。他会把我们直接引到他的制毒基地去。跟我走。"
D.Strings[73503]="我来清出通往旗舰的道路。在我念完咒语前，挡住这些入侵者！"
D.Strings[73504]="你的尸体将滋养我们无数的幼苗！"
D.Strings[73505]="在这里……我们是无穷无尽的……"
D.Strings[73506]="我恨这片丛林……你！我要跟你谈谈。"
D.Strings[73507]="自从我的远征军进入这片被遗忘的土地，你是第一个没有在见到我之后立刻攻击的家伙……我就不该来这儿！"
D.Strings[73508]="谁都不该成为这些怪物的肥料。你是怎么来到这里的？"
D.Strings[73509]="自从“巫师之王”马尔高克掌权并发现了那些神器之后，他就整天念叨着破魔者长灭火者短的。有了新发现的力量之后，他就觉得自己不再需要我们的军团了！$b$b这个帝国是靠食人魔的力量和刀剑建立起来的，我就是这么告诉他的！"
D.Strings[73510]="我很怀疑他能不能听进去……"
D.Strings[73511]="他不但听不进去，还用我的话来对付我！$b$b他命令我和我的忠实支持者发起这场该死的远征，寻找食人魔的原始文明以及一些白痴神器！我不能反抗……现在我的部队全完了，我也回不去了……"
D.Strings[73512]="你和你的朋友来迟了一步，$n。我的剑已经痛饮了乌布莱特的鲜血。很快，我的力量就将无人能挡了。"
D.Strings[73513]="现在，请允许我告退，我还需要更多的鲜血。干掉这个蛆虫。"
D.Strings[73514]="我们后会有期，$n。"
D.Strings[73515]="噢！太多了！"
D.Strings[73516]="我们坚持不住了！"
D.Strings[73517]="我们必须给那个巫师多争取一点时间！守住阵线！"
D.Strings[73518]="完成了。我得休息一会儿了。旗舰就在前面，等我恢复力量之后，就过去找你。"
D.Strings[73519]="不打算买的话就别碰我的商品。"
D.Strings[73520]="难以置信，我们俩居然会站在这里，$n。这是德拉诺……但它又不是德拉诺。我感觉我们好像走到了镜子的另一面。$b$b让我们赶快完成任务，然后离开这个地方吧，好吗？"
D.Strings[73521]="你有什么打算，卡德加？"
D.Strings[73522]="这到底是怎么回事？！"
D.Strings[73523]="没错……这具尸体会很有用的！"
D.Strings[73524]="送我去纳格兰的破碎悬崖。"
D.Strings[73525]="大法师正在等着你。"
D.Strings[73526]="呱！我仍然——呱——仍然效忠于您，陛下！"
D.Strings[73527]="我……还有力量……"
D.Strings[73528]="我……嗯……什么？呱！！"
D.Strings[73529]="利爪之王还活着！"
D.Strings[73530]="终、终、终于，陛——陛下！"
D.Strings[73531]="他肯定逃走了，我知道的。"
D.Strings[73532]="我们必须保持坚强。我确信他很快就会回来的。"
D.Strings[73533]="保持希望，$n！圣光会保佑你的。"
D.Strings[73534]="<这团难以名状的魔法能量似乎带着人们游览你的要塞。>"
D.Strings[73535]="愿圣光祝福你，$r！"
D.Strings[73536]="这个战歌兽人似乎在试图带着巨石穿过高里亚岗哨时战死了。 \n\n没有明确的痕迹显示他将石头放在哪儿了，但它显然没在战斗中帮上什么忙。"
D.Strings[73537]="让这些战争机器准备攻城。"
D.Strings[73538]="在看清他们的眼睛之前，不要急着射击！"
D.Strings[73539]="别让战斗的欲望蒙蔽你们的视线。"
D.Strings[73540]="别再炫技了。"
D.Strings[73541]="都进去，让我看看你们的本事。"
D.Strings[73542]="你们以为自己能代表钢铁部落吗？"
D.Strings[73543]="不要手软。一个不留。"
D.Strings[73544]="战歌的利箭在天空中欢唱！在我砸扁你的脑袋时，这将是你听到的最后一种声音。"
D.Strings[73545]="火葬开始！"
D.Strings[73546]="让他们尝尝这个！"
D.Strings[73547]="就这样？你都没法让我流血！"
D.Strings[73548]="战士就应该这样战死！"
D.Strings[73549]="让恐惧吞噬你，死神来了。"
D.Strings[73550]="屠杀的盛宴！"
D.Strings[73551]="我的剑渴望更多鲜血。"
D.Strings[73552]="你们将与我一同葬身火海。"
D.Strings[73553]="这下你就高不起来了。"
D.Strings[73554]="噢！要杀敌人吗？让我来！"
D.Strings[73555]="你最好后退点。我要呼叫爆破小队了！"
D.Strings[73556]="时间就是金钱，朋友！看来这两样你都没有！"
D.Strings[73557]="滴答滴答滴答……轰！"
D.Strings[73558]="啊啊啊啊！！！我被击中了！"
D.Strings[73559]="$n浏览着书籍。"
D.Strings[73560]="唔……有什么有用的书吗？"
D.Strings[73561]="好了……他们都走了。"
D.Strings[73562]="我要去杀戈隆！"
D.Strings[73563]="我们现在可以回头了吗？"
D.Strings[73564]="我……救不了他们。"
D.Strings[73565]="怎么了？下面出什么事了？"
D.Strings[73566]="在黑石氏族的战争机器面前，一小撮奴隶能有什么作为？"
D.Strings[73567]="黑石兽人们……干掉他们！"
D.Strings[73568]="你休想打败圣光，恶魔！"
D.Strings[73569]="呃，头儿！老沃金酋长给我派了几个暗影猎手来充当你的耳目。$b$b只要我在这个世界打听到什么重要消息，一定马上通知你。"
D.Strings[73570]="召唤泰罗克。"
D.Strings[73571]="哇，那可是个大家伙！"
D.Strings[73572]="需要我做什么吗？"
D.Strings[73573]="哇！好了，好了，我这就回去工作！"
D.Strings[73574]="好痛！好痛！"
D.Strings[73575]="但没有公主大。"
D.Strings[73576]="我忙着呢。让我安静一会儿。"
D.Strings[73577]="我们得把它从这里弄出去！"
D.Strings[73578]="我可不是那种兽人。"
D.Strings[73579]="这个地狱咆哮之子是个疯子。$B$B我不想伸张正义……我只想报复他对塔拉所做的一切。"
D.Strings[73580]="达坎，前面发生什么事了？"
D.Strings[73581]="加尔鲁什一次次逃脱制裁，但这次，我们一定能彻底解决他。"
D.Strings[73582]="阿格娜，前面发生什么事了？"
D.Strings[73583]="他们似乎把注意力都集中在仪式上了。或许摧毁这些鲜血宝珠能吸引他们的注意力。"
D.Strings[73584]="这些神器碎片中蕴含着力量，$n。给我带回足够的神器，法师们就能召唤出传送门，方便我们快速返回战争之矛岗哨。$B$B你给我带来多少了？"
D.Strings[73585]="传送门已经开启了，$c。干得好。"
D.Strings[73586]="术士传送门有什么用？"
D.Strings[73587]="法师们将在阿什兰西部召唤出一座传送门，可以让你返回战争之矛。"
D.Strings[73588]="传送门将位于阿什兰的西北面和东南面，可以让你快速往返于两地之间。"
D.Strings[73589]="有人需要高质量的伐木机吗？"
D.Strings[73590]="术士们已经激活了传送门并将其完全投入使用了。干得好，$n。"
D.Strings[73591]="如果我们能在阿什兰收集到足够的神器碎片，我们就能激活术士传送门，让我们快速往返于不同区域。$B$B你给我带来多少了？"
D.Strings[73592]="谢谢你，英雄，你将我的灵魂从古加尔的魔掌中解救了出来。$b$b虽然我的躯体已经安息，但我的灵魂将保持警惕，并维持自然的平衡，直到新的大地之怒接替我的位置。"
D.Strings[73593]="德拉卡，你和这个德莱尼一起去搜寻幸存者。"
D.Strings[73594]="前进！超级武器就在其中的某艘船上。跟我来！"
D.Strings[73595]="死者的鲜血会让我更强大！"
D.Strings[73596]="你敢质疑我的力量？？？我们的血液中充斥着能量！"
D.Strings[73597]="我将沐浴你的鲜血！"
D.Strings[73598]="不！没人具有能驾驭我的力量！"
D.Strings[73599]="哈。我也是。"
D.Strings[73600]="还没完呢。"
D.Strings[73601]="战歌兽人！到我这儿来！"
D.Strings[73602]="别担心，伙计。我会挡住这些骑兵的！"
D.Strings[73603]="请将阻拦这些骑兵的荣幸交给我！"
D.Strings[73604]="战歌氏族会将你撕成碎片！"
D.Strings[73605]="千万别低估了这片土地的危险性。$b$b<索恩指了指自己的眼罩。>$b$b这就是我的天真和疏漏留下的记号。"
D.Strings[73606]="在潘达利亚，我从没有在执行任务时请求“帮助”的习惯。或许这就是我们从没见过的原因？"
D.Strings[73607]="我的鲜血如玫瑰般鲜红。我的心永远为吉尔尼斯而跳动。"
D.Strings[73608]="别高兴得太早，伙计！"
D.Strings[73609]="尝尝我的战锤吧！"
D.Strings[73610]="哈哈，谁能想到一个学徒的身份能让我来到这里？这真是太刺激了！"
D.Strings[73611]="嘿，你觉不觉得阿历克斯顿和索恩很般配？呵呵！"
D.Strings[73612]="嘿，指挥官，你玩过战球游戏嘛？去试试吧！"
D.Strings[73613]="那个索恩真该放松一点，开朗一点！呃……指挥官！"
D.Strings[73614]="所以你就是新任的指挥官，嗯？我还以为你会更高一点呢。"
D.Strings[73615]="你看见布莱斯顿了吗？呃……我新来的助手还真是麻烦。$b$b她干什么都非常极端——不管是酗酒、聊天还是干活……$b$b但她是个超棒的建筑师，或许也会是我最聪敏的学生。$b$b所以我也就忍了。"
D.Strings[73616]="指挥官！我相信你已经准备好被我的设计震晕了。$b$b我在想……木头！是的，木头！很多木头。用大胆的结构营造出只有早期部落的兽人才能想出来的造型。$b$b还有尖刺！是的，尖刺。我们决不能忘了尖刺。这可是部落的标志性装饰。"
D.Strings[73617]="索恩中尉是我们所有人的光辉榜样。我从没见过这么敬业的领袖。$b$b我还没鼓起勇气跟她搭讪过，但或许有一天，她会记住我的名字的。"
D.Strings[73618]="你需要一位砍树高手吗，指挥官？"
D.Strings[73619]="你不是还要去拯救世界吗，$n？这种脏活就交给我吧！"
D.Strings[73620]="你知道吗，我们树木终结者在野外有百分之二十的存活率。"
D.Strings[73621]="我明白了，指挥官$n。快去拯救几个孤儿或者杀掉几个兽人，总之去干点类似的英雄事迹吧。"
D.Strings[73622]="快回塔纳安丛林！"
D.Strings[73623]="等我干掉你之后，连卡利鸟都不屑啄食你的尸体！"
D.Strings[73624]="鲁克玛有令，你必须死！"
D.Strings[73625]="我这就来解决这场荒唐的起义！"
D.Strings[73626]="我会看着你的尸体摔碎在下方的岩石上！"
D.Strings[73627]="肮脏的渣滓！你竟敢踏足我的平台！"
D.Strings[73628]="格莱布林·迅爆最后一次现身是在破碎悬崖。你准备好之后，杜加尔会送你前往那里的。"
D.Strings[73629]="我的生命……属于鲁克玛……"
D.Strings[73630]="小声点，他们的营地就在这儿。"
D.Strings[73631]="小点声。他们的营地就在这儿。"
D.Strings[73632]="不……我不想陷入黑暗……"
D.Strings[73633]="你们这些流亡者竟敢登上我的平台！我会看着你们的身体摔碎在下面的岩石上！"
D.Strings[73634]="这边，蜥蜴先生……这边。"
D.Strings[73635]="对，那些都是锯刃。现在，让开点！我要开始砍树了！"
D.Strings[73636]="我砍过比这更大的树！让开，我要开始工作了！"
D.Strings[73637]="你去干你擅长的事吧，我也要干我最擅长的事了，那就是砍树。"
D.Strings[73638]="你感觉到了吗？这棵树害怕了。我应该说它已经吓傻了……"
D.Strings[73639]="在我进行治疗的时候，请保持平静。"
D.Strings[73640]="杀了他们！没人能阻止我们占领这座城市。"
D.Strings[73641]="又一只误闯战场的小崽子？"
D.Strings[73642]="德洛克向你挥手告别。"
D.Strings[73643]="我将毕生的精力都投入了保护珍贵遗物，并将其迅速转手，赚取利润的事业中。$b$b这是一项艰巨的工作，但我喜欢钱。你明白我的意思吧？"
D.Strings[73644]="如果你有什么需要保护的东西，就告诉一声，我或许能把它卖给哪个喜欢古董的家伙。"
D.Strings[73645]="你知道那句老话吗？$b$b一个地精的垃圾就是另一个地精的废物，所以快把它卖给蠢到会买它的人吧。$b$b这是我那亲爱的老母亲在把那辆狼人马车卖给我之前告诉我的。$b$b我到现在还说不清自己当时是什么感觉。"
D.Strings[73646]="<这头双足飞龙期待地看着你。>"
D.Strings[73647]="送我回岗哨。"
D.Strings[73648]="<这头狮鹫期待地看着你。>"
D.Strings[73649]="等那些食人魔消失，我就可以让我的人过来进行发掘了。"
D.Strings[73650]="这些神经病食人魔。要是他们早点死掉，我几个星期前就该完成这次调查工作了。"
D.Strings[73651]="在一大堆有关海盗生涯的潦草记录以及藤壶数量惊人的各种用途中间，你发现了这么一条记录：\n\n“那只该死的鸟偷走我的箱子钥匙已经整整一周了。他总是飞来飞去，好像在嘲笑我一样，可我就是抓不住他。 \n\n但那只混蛋肥鸟不可能永远飞下去。我就等在这里，直到他飞不动为止。”"
D.Strings[73652]="就算有一件珍贵的遗物跳起来咬了他们的屁股，这些食人魔估计也认不出来。事实上，估计不管是什么咬了他们的屁股，他们估计都不会有感觉。你明白我的意思吧？"
D.Strings[73653]="部落控制了市场墓地，持续15分钟！"
D.Strings[73654]="联盟控制了市场墓地，持续15分钟！"
D.Strings[73655]="市场墓地恢复中立！"
D.Strings[73656]="我……呃……我以为这会很有趣的。"
D.Strings[73657]="我睡了一整晚，又干了一整天的活儿，指挥官。$B$B我需要释放一下压力。"
D.Strings[73658]="希望你别介意，指挥官。"
D.Strings[73659]="事情不是你看到的那样，我发誓。$B$B千万别让我去扫厕所。"
D.Strings[73660]="“去摸一下掠食者的巢穴，”汤姆说。他还说：“这会很有趣的。”$B$B我这就让他看看……"
D.Strings[73661]="布洛奇约杀死了老食人魔酋长，将他的脑袋插在宝座旁的木桩上。他周围守卫森严，但相信我，只要你摸一下那个食人魔脑袋，他就会冲出来热烈“欢迎”你了。"
D.Strings[73662]="<尼莎冲你摆了摆脑袋，她闪闪发光的蓝眼睛里流露出感动的神情。>"
D.Strings[73663]="我干起活儿来也很卖力的，指挥官。真的。$B$B汤姆捉弄过我很多次了，事情就是这样。我一定要回敬他一下。"
D.Strings[73664]="骑上尼莎返回狂怒裂隙。"
D.Strings[73665]="很好，看来你欠我的债终于还清了。我们回头见。"
D.Strings[73666]="<尼莎顽皮地伸出舌头，舔了舔你的脸颊。>"
D.Strings[73667]="不准碰！我要把你这个笨蛋挤扁！"
D.Strings[73668]="我们的命运交织在了一起。"
D.Strings[73669]="你是跟其他蠢货一样来送死的吗？"
D.Strings[73670]="接受我的力量。现在它归你了。"
D.Strings[73671]="我会让你后悔爬这么高的！"
D.Strings[73672]="为了鲁克玛！"
D.Strings[73673]="天空属于我们！"
D.Strings[73674]="我和伊瑞尔会带着大部分部队到这座屏障的南边去。$B$B同时，我建议你带着剩下的士兵到西面去，从侧面迂回过去。"
D.Strings[73675]="我同意，从侧翼迂回能帮你争取足够的时间，让我们的大部分部队更靠近加尔鲁什。"
D.Strings[73676]="我和杜隆坦会带着大部分部队到这座屏障的南边去。$B$B同时，我建议你带着剩下的士兵到西面去，从侧面迂回过去。"
D.Strings[73677]="卡德加！把我们弄出去！"
D.Strings[73678]="达坎刚刚完成对前方的侦查。你恐怕不会喜欢他带来的消息。"
D.Strings[73679]="不管喜欢与否，我们都得继续前进。前面到底是什么情况？"
D.Strings[73680]="前面有被他们奴役的饥饿者杜恩。$B$B要想穿过他，就需要我们投入全部的力量。"
D.Strings[73681]="阿格娜刚刚完成对前方的侦查。你恐怕不会喜欢她带来的消息。"
D.Strings[73682]="加尔鲁什就坐在这些城门后面的宝座上。是时候拿出我们全部的实力了，$n。$B$B下令吧，我们将彻底解决这个恶棍。"
D.Strings[73683]="下令吧，伊瑞尔。摧毁城门，让我们进去。"
D.Strings[73684]="下令吧，杜隆坦。摧毁城门，让我们进去。"
D.Strings[73685]="我从没想过能在有生之年目睹如此神奇的地方，指挥官。$B$B我很高兴和我最信赖的老朋友，贝林顿先生一起来到这里。"
D.Strings[73686]="早上好，指挥官！"
D.Strings[73687]="下午好，指挥官！"
D.Strings[73688]="真是漫长的一天啊，指挥官。"
D.Strings[73689]="指挥官。"
D.Strings[73690]="继续加油吧，指挥官。"
D.Strings[73691]="我的背好痛啊！"
D.Strings[73692]="我已经准备好去喝一杯了。"
D.Strings[73693]="是我一个人这么觉得，还是这活儿真的永远也干不完？"
D.Strings[73694]="很高兴见到你，指挥官。"
D.Strings[73695]="一切平静，指挥官。"
D.Strings[73696]="就算是你，偶尔也需要休息一下的，指挥官。"
D.Strings[73697]="送我去破碎悬崖。"
D.Strings[73698]="我在干活儿呢！"
D.Strings[73699]="我只是在闭目养神，指挥官。"
D.Strings[73700]="我会搞定的，指挥官。"
D.Strings[73701]="你好，指挥官。"
D.Strings[73702]="指挥官。你有什么吩咐吗？"
D.Strings[73703]="指挥官！我们被袭击了！"
D.Strings[73704]="有什么吩咐吗，指挥官？"
D.Strings[73705]="以你为荣，指挥官。"
D.Strings[73706]="没什么值得报告的，指挥官。"
D.Strings[73707]="愿清风载着你迅速抵达目的地，指挥官。"
D.Strings[73708]="你的祖先会为你的功绩而自豪的，指挥官。"
D.Strings[73709]="我能把你送去任何你想去的地方，指挥官。你尽管开口。"
D.Strings[73710]="愿艾露恩祝福我们的使命，指挥官。"
D.Strings[73711]="走开，这里没什么好看的。"
D.Strings[73712]="死亡……将孕育新生。"
D.Strings[73713]="旧的不去，新的……不来。"
D.Strings[73714]="站起来吧，我的小树苗。"
D.Strings[73715]="我绽放出的这些……都是全新的叶子。"
D.Strings[73716]="谢谢你，德鲁伊……你拥有着自然之触。"
D.Strings[73717]="现在，让我们把那些部落赶出这片土地吧。"
D.Strings[73718]="苹果，核对无误。头盔，核对无误。漂亮的军需官，核对无误。"
D.Strings[73719]="不，不，不，这完全不对。我们的长剑快不够用了。"
D.Strings[73720]="噢，天呐。我们需要更多的食物。"
D.Strings[73721]="这是什么？我的竞技场里来了一个鸦人挑战者？！"
D.Strings[73722]="你是不想继续当猎物了吗？还是来报仇的？"
D.Strings[73723]="来吧，小鸟。使出你最卑劣的手段来！"
D.Strings[73724]="什么？！你是谁？！"
D.Strings[73725]="够了。一切到此为止了！"
D.Strings[73726]="我是利爪之王！我从死神的国度归来，阻止钢铁狂潮！"
D.Strings[73727]="啊！这……不可能……"
D.Strings[73728]="我是卡加斯·刃拳，我想杀谁，谁就得死。"
D.Strings[73729]="哼，所以那里面的是你。"
D.Strings[73730]="这回，卡德加可保护不了你了。"
D.Strings[73731]="黑手对你施放了|TInterface\\Icons\\ability_rogue_hungerforblood.blp:20|t|cFFFF0404|Hspell:168261|h[死亡标记]|h|r。快到钢铁之星后面躲避攻击！"
D.Strings[73732]="什么？！啊啊啊！！！！"
D.Strings[73733]="我不想说我们毫无准备，可我们在阿什兰的补给已经不够了。我们没有从传送门那边带来足够的补给。$B$B但愿斯波奇特的队伍能将我们所需的重型机械带来，帮我们战胜部落。"
D.Strings[73734]="你还好吗？刚才可真是千钧一发啊。"
D.Strings[73735]="是时候来完成我的杰作了！"
D.Strings[73736]="没有哪棵树能抵挡我的力量！"
D.Strings[73737]="这棵怪树马上就会被消灭了，指挥官。你就在一旁看着吧！"
D.Strings[73738]="我就是移动伐木机，我生来就是砍树的料。后退！"
D.Strings[73739]="我可以做得更好。"
D.Strings[73740]="为了等你修好他，我已经等了一整天了。不过没关系，还有很多事情可以用来打发时间。"
D.Strings[73741]="为了找到横穿山谷的“捷径”，费尔沃什把我们的团队都带迷路了。现在，我的靴子里都是泥沙！\n\n从现在开始，我来保管地图。"
D.Strings[73742]="你的飞行管理员坚持要你飞回去。"
D.Strings[73743]="很好，贝楚斯，让我们看看它管不管用吧。这是心之种。"
D.Strings[73744]="你不会失望的。我漫长的冒险终于要结束了！站起来吧，迪奥诺！"
D.Strings[73745]="我们没有迷路，我只是选择了比较冒险的路线！"
D.Strings[73746]="那么，你是做什么工作的？"
D.Strings[73747]="噢，我专门研究和翻译古代魔古卷轴。"
D.Strings[73748]="是的，我知道，去跟我的上司说吧。"
D.Strings[73749]="你在这儿恐怕找不到多少类似的东西……"
D.Strings[73750]="让我看看地图，费尔沃什。我来决定接下来该往哪儿走。"
D.Strings[73751]="城中的巡逻警戒已经加强了。我们绝不屈服于这些野蛮人的进攻。"
D.Strings[73752]="卡拉波的防御者们，做好准备！"
D.Strings[73753]="我们的人民，我们的城市，决不能落在野蛮人的手中！"
D.Strings[73754]="此刻，我们必须比以往任何时候更加团结、更加坚强。"
D.Strings[73755]="我真是太走运了，伙计！我在这下面找到一个超棒的钓鱼点。可元素生物和食人魔把我的钓鱼装备都弄坏了。 \n\n现在，我需要一根新鱼竿、一个新线轮，还有特制的巫毒鱼饵。然后，我就能把那些躲在水草里的大家伙给钓上来了。"
D.Strings[73756]="我想我能帮你。（将阿布加尔的鱼竿、线轮和鱼饵交给他）"
D.Strings[73757]="嘿，指挥官！你确定你不想离开嘲笑之颅吗？"
D.Strings[73758]="你已经证明自己有能力在最危险的环境中生存下来。我从没见过你这样的战斗技巧。我很高兴能成为你的朋友。"
D.Strings[73759]="嘿，头儿。来休息一下吧。放松点。"
D.Strings[73760]="愿圣光之力与你的义举共鸣。我们决不能让野蛮敌人的仇恨压倒我们求生的意志。继续前进，让我的同胞们恢复健康吧！"
D.Strings[73761]="所以这是真的。这颗心脏能为这些生物注入生命力。"
D.Strings[73762]="啊，英雄……我就知道你会来的。你来得正是时候，来见证恐惧之心的力量吧。"
D.Strings[73763]="在第一个兽人诞生之前，这头玛戈隆的身影就已经出现在了德拉诺的土地上。现在，它……以及无穷无尽的毁灭者大军……都将服从于我的意志！"
D.Strings[73764]="跟我来，$n。她往这边走了。"
D.Strings[73765]="工头，请把这座建筑改造成坦克工厂。"
D.Strings[73766]="我们在最后关头把你救了出来。"
D.Strings[73767]="那个兽人……卡加斯。即使在我全盛时期，他也是个难缠的对手。"
D.Strings[73768]="我的孩子们，要想战胜今天的挑战，只靠一些昔日的陈旧回忆是不够的。"
D.Strings[73769]="改造建筑将花费5,000金币。\n\n确定要改造吗？"
D.Strings[73770]="你们必须杀出属于自己的道路。抛弃过去，培养出新的勇士。"
D.Strings[73771]="目前为止，联盟在阿什兰各地都曾发现过神器。杀掉你遇到的所有生物也能提高发现神器的几率。"
D.Strings[73772]="我们收到风声说，在这个名为阿什兰的地方藏着一些神器，是由一些残余的悬槌食人魔留下的。$B$B它们或许就是我们战胜钢铁部落的关键。"
D.Strings[73773]="酒趾！是你吗？"
D.Strings[73774]="你们已经有了一位新勇士。"
D.Strings[73775]="英雄，我无法再将全部的力量灌输给你了。卡加斯切断了我们之间的联系。"
D.Strings[73776]="但只要你们在阿兰卡，我的一些力量残片还会伴随着你们。"
D.Strings[73777]="工头，请把这座建筑改造成兽栏。"
D.Strings[73778]="我会尽力帮助你们的。"
D.Strings[73779]="你的苦难将成为传奇。"
D.Strings[73780]="塞林，让我们把这座建筑改造成坦克工厂吧。"
D.Strings[73781]="但首先……我得去洗个手。我会在你的营地里等你的。"
D.Strings[73782]="塞林，让我们把这座建筑改造成兽栏吧。"
D.Strings[73783]="站起来吧，我的仆从们！撕碎他们的血肉。"
D.Strings[73784]="寄生虫！我要把你们的世界化为灰烬！"
D.Strings[73785]="它们到底在哪儿？"
D.Strings[73786]="我要把它们带来交给你吗？"
D.Strings[73787]="我会尽力的！"
D.Strings[73788]="我跟你直说吧，给我带五件左右的神器来，然后把他们交给坐在那边营火旁的法师。他叫艾希兰姆。他能用神器的力量，在阿什兰召唤出几座法师传送门。"
D.Strings[73789]="指挥官，出什么事了？"
D.Strings[73790]="我已经等不及想射死几个钢铁部落的恶棍了。"
D.Strings[73791]="吱——！"
D.Strings[73792]="然后他就掏出了一把苔藓。真是个怪人！"
D.Strings[73793]="于是我就说：“可以，但价钱可不便宜。”"
D.Strings[73794]="等我醒过来时，已经躺在店后面，头发里都是苔藓！"
D.Strings[73795]="他们又来了！"
D.Strings[73796]="还得多杀几个。"
D.Strings[73797]="我都数不清了。杀了几个了？"
D.Strings[73798]="他们肯定像鱼人一样能生。"
D.Strings[73799]="赞美鸦母，一切都准备就绪了！你准备开始的时候，就告诉我一声吧。"
D.Strings[73800]="你觉得那个……玩意儿怎么样？它好大呀。"
D.Strings[73801]="能再给我一个冰脊钉刺者诱饵吗？"
D.Strings[73802]="就是现在……快！"
D.Strings[73803]="死亡……降临……"
D.Strings[73804]="就这样——"
D.Strings[73805]="画什么好呢……画什么好呢？"
D.Strings[73806]="啊！看来我们得先对付那头戈隆了。"
D.Strings[73807]="好吧，至少我们解决了那个玩意儿。来吧，英雄。我们最好尽快回总部报告。"
D.Strings[73808]="沙塔斯被一个可怕的敌人袭击了！"
D.Strings[73809]="许多人在袭击中丧生，包括我们的朋友和亲人。"
D.Strings[73810]="但多亏了你们的英勇壮举，许多人因此而得救。"
D.Strings[73811]="虽然我们对袭击毫无准备，但你们每一个人的表现都可圈可点。"
D.Strings[73812]="从今天起，我们要在沙塔斯各地设置新的巡逻队。"
D.Strings[73813]="不要疏忽大意，我们决不能再被偷袭了！"
D.Strings[73814]="愿圣光拥抱你们！"
D.Strings[73815]="前线的战斗怎么样了，$n？"
D.Strings[73816]="$n长官！报到，长官！"
D.Strings[73817]="别让这个家伙靠近火炮。"
D.Strings[73818]="别让那些部落的家伙靠近暴风之盾，$n。"
D.Strings[73819]="哼，看来我得亲自来对付你了。"
D.Strings[73820]="我要跟你同归于尽！"
D.Strings[73821]="你的炼金实验室遭到袭击！"
D.Strings[73822]="看看这个！"
D.Strings[73823]="你的军械库遭到袭击！"
D.Strings[73824]="你的畜棚遭到袭击！"
D.Strings[73825]="你的兵营遭到袭击！"
D.Strings[73826]="你的铁匠铺遭到袭击！"
D.Strings[73827]="你的附魔研究室遭到袭击！"
D.Strings[73828]="你的工坊遭到袭击！"
D.Strings[73829]="你的旅店遭到袭击！"
D.Strings[73830]="你的铭文师之家遭到袭击！"
D.Strings[73831]="你的珠宝店遭到袭击！"
D.Strings[73832]="你的制革厂遭到袭击！"
D.Strings[73833]="你能向我展示一下阿什兰吗？"
D.Strings[73834]="你的伐木场遭到袭击！"
D.Strings[73835]="你的格斗竞技场遭到袭击！"
D.Strings[73836]="噢，不！弓弦又断了。"
D.Strings[73837]="你的法师塔遭到袭击！"
D.Strings[73838]="你的废品站遭到袭击！"
D.Strings[73839]="你的兽栏遭到袭击！"
D.Strings[73840]="你的仓库遭到袭击！"
D.Strings[73841]="你的货栈遭到袭击！"
D.Strings[73842]="你的裁缝店遭到袭击！"
D.Strings[73843]="你的车间遭到袭击！"
D.Strings[73844]="又在卖弄了。"
D.Strings[73845]="现在，让我们再试一次。"
D.Strings[73846]="你惹火砂齿了！我要揍扁你！"
D.Strings[73847]="那我们就赶快出发吧！"
D.Strings[73848]="此处禁止入内。"
D.Strings[73849]="请退后。"
D.Strings[73850]="木材已经发往你的伐木场了！"
D.Strings[73851]="我准备好再次起飞了，卡鲁。"
D.Strings[73852]="兽人为什么要制造这么多痛苦？"
D.Strings[73853]="下一次……我一定将他们都化为灰烬！"
D.Strings[73854]="敌人的旗舰就停在海滩旁。我们来拖住黑手，毁掉船只、拯救沙塔斯的任务就交给你了！"
D.Strings[73855]="你想要报告什么？最好不要像上次那样！"
D.Strings[73856]="我们知道如何控制戈隆的精神了。"
D.Strings[73857]="很好，完成你的工作，将他们带来我这里。"
D.Strings[73858]="遵命，指挥官加尔。"
D.Strings[73859]="你好啊，$n。你是来砍木头的吗？"
D.Strings[73860]="我想提交一张产品订单。"
D.Strings[73861]="将你的手放在尼莎的脑袋上。"
D.Strings[73862]="<尼莎拍打着双翼，准备为雷克萨进行侦察。>"
D.Strings[73863]="<考里格双眼紧闭，肤色十分苍白。>"
D.Strings[73864]="对考里格使用解毒剂。"
D.Strings[73865]="<伦祖尔双眼紧闭，肤色十分苍白。>"
D.Strings[73866]="对伦祖尔使用解毒剂。"
D.Strings[73867]="噢，我的头。"
D.Strings[73868]="啊，指挥官，真是太感谢你了。我这就把酒厂开起来。相信我，塔布羊摇两下尾巴的功夫我就能搞定了。"
D.Strings[73869]="我的头疼得都要裂开了。"
D.Strings[73870]="祝福你，头儿。我这就把旅店开起来，速度绝对超出你的想象。"
D.Strings[73871]="你的炼金实验室受损！"
D.Strings[73872]="你的车间受损！"
D.Strings[73873]="你的货栈受损！"
D.Strings[73874]="你的裁缝店受损！"
D.Strings[73875]="你的仓库受损！"
D.Strings[73876]="你的兽栏受损！"
D.Strings[73877]="你的格斗竞技场受损！"
D.Strings[73878]="你的废品站受损！"
D.Strings[73879]="你的法师塔受损！"
D.Strings[73880]="你的伐木场受损！"
D.Strings[73881]="你的制革厂受损！"
D.Strings[73882]="你的珠宝店受损！"
D.Strings[73883]="你的铭文师之家受损！"
D.Strings[73884]="你的旅店受损！"
D.Strings[73885]="你的工坊受损！"
D.Strings[73886]="钢铁女武神牺牲了？她们是我最看重的手下！找到这些入侵者，把他们的脑袋带来给我！"
D.Strings[73887]="你的附魔研究室受损！"
D.Strings[73888]="那头野兽是不可替代的。袭击者在哪儿？我要他们死。让他们统统去死！"
D.Strings[73889]="你的铁匠铺受损！"
D.Strings[73890]="你的兵营受损！"
D.Strings[73891]="你的畜棚受损！"
D.Strings[73892]="你们？你们就是那群在我的铸造厂大肆破坏的走狗？过来！我要让你们认清自己的身份。"
D.Strings[73893]="你的军械库受损！"
D.Strings[73894]="我要把你们支离破碎的尸体挂在铸造厂的大门口！"
D.Strings[73895]="你们毁了我的熔炉……现在，我的熔炉也要毁了你们。"
D.Strings[73896]="打开引流槽！用熔火炉渣淹没这个房间。"
D.Strings[73897]="我要活活烧死你们，哪怕为此要淹没整个铸造厂……"
D.Strings[73898]="我把整个铸造厂都砸到你们的头上！"
D.Strings[73899]="如果有必要，我不惜摧毁这个地方！"
D.Strings[73900]="铸造厂还可以重建……但你们不会再有复活的机会了。"
D.Strings[73901]="你太慢了。"
D.Strings[73902]="你应该躲开的。"
D.Strings[73903]="现在，你无处可躲了。"
D.Strings[73904]="你们总是像孩子一样东躲西藏。"
D.Strings[73905]="滚出来战斗！"
D.Strings[73906]="狙击手！打死他们。"
D.Strings[73907]="士兵们！开火！"
D.Strings[73908]="黑石战士们——开火！"
D.Strings[73909]="把攻城战神坦克开进来。"
D.Strings[73910]="攻城器！摧毁这个地方！"
D.Strings[73911]="所有武器，开火！不惜一切代价消灭他们！"
D.Strings[73912]="烧吧——你们都会被烧死的！"
D.Strings[73913]="这座铸造厂的熔火核心将吞噬你们。"
D.Strings[73914]="你们的尸体将成为烈焰的燃料。"
D.Strings[73915]="熔炉将吞噬你们！"
D.Strings[73916]="火焰温度越高，钢铁就越强韧……"
D.Strings[73917]="这座锅炉将成为你们的葬身之地。"
D.Strings[73918]="你们已经没有时间了。"
D.Strings[73919]="这口坩埚将成为你的熔火坟墓！"
D.Strings[73920]="你的纪律性太差了。"
D.Strings[73921]="我们的武器是最棒的。"
D.Strings[73922]="呸！死了。"
D.Strings[73923]="你们就这点本事吗？"
D.Strings[73924]="我要亲手了结你们！"
D.Strings[73925]="这可以引发大爆炸……"
D.Strings[73926]="这可能有点儿烫。"
D.Strings[73927]="这台样机装备了双层装甲。"
D.Strings[73928]="这是我们军械库里最快的机器！"
D.Strings[73929]="我们是……酋长的武器……没有我们，他……"
D.Strings[73930]="一名受伤的防御者牺牲了！"
D.Strings[73931]="准备与原兽战斗。"
D.Strings[73932]="尽量别让工人们死掉。他们就像磁石一样吸引着怪物！"
D.Strings[73933]="<你的脑海中响起一个声音。>$b$b趁鲁克玛的子嗣还没有重新集结军力，我们必须尽快行动。"
D.Strings[73934]="很好，但我会盯着她的。"
D.Strings[73935]="噢，这下就好多了！我是来见指挥官的。"
D.Strings[73936]="请别走远了。我们这里需要你，勇士。"
D.Strings[73937]="雪莉？是你吗？"
D.Strings[73938]="别相信他们，雪莉！他们是在骗你。他们会吃了你的。他们会把我们都吃了的！"
D.Strings[73939]="我最讨厌蔬菜了……"
D.Strings[73940]="嗨，妈妈！"
D.Strings[73941]="干得好，朋友。很少有人能活着从那个洞里出来。"
D.Strings[73942]="列队，蛆虫们！看来我们有伴儿了。"
D.Strings[73943]="鲁比很喜欢她的饭菜。"
D.Strings[73944]="冷静点，佐格什。我们不会逃跑的。既然这些废物都急着送死，那我们就成全他们。"
D.Strings[73945]="佐格什，别质疑我的权威。这不是别的戈隆，这是格鲁尔之子，斯古洛克。他体内流淌着勇士的鲜血。我才不担心这些……没用的小崽子呢。"
D.Strings[73946]="你以为他们能对兽人钢铁做些什么？估计也就是摔死在上面吧。我根本不担心。"
D.Strings[73947]="哈。你看看。或许我……低估了他们。佐格什！让斯古洛克准备好！让这些家伙尝尝他的厉害。"
D.Strings[73948]="开火……开火！瞄准了再开火！"
D.Strings[73949]="你怎么回事？！继续开火，蠢货！"
D.Strings[73950]="啊啊！算了吧！他们休想穿过轨道。马考格，阿里奥克——出列！把他们捶成肉泥！"
D.Strings[73951]="这点损失不算什么。让他们自己蹦跶吧，就当帮我们剔除一些弱者——不配在黑手军团服役的弱者！鲜血与荣耀，佐格什。这就是兽人的信条。"
D.Strings[73952]="少拍马屁，佐格什，我向来善于思考。"
D.Strings[73953]="我已经玩够了。让刃牙虎人上，赶紧搞定他们。"
D.Strings[73954]="给它套上笼头。"
D.Strings[73955]="我不是指那只猫。"
D.Strings[73956]="你们怎么敢闯到我的码头和舰艇上来。没人能阻止钢铁部落，更别提你们了。享受你们的末日吧，废物。佐格什，去操纵机械炮台！"
D.Strings[73957]="我没有产品订单所需的10份木材。哪里还能找到木材？"
D.Strings[73958]="佐格什，拿起你的战斧。一切到此为止了！"
D.Strings[73959]="臣服于钢铁部落的威力之下吧！"
D.Strings[73960]="这……不可能……"
D.Strings[73961]="长官，他们攻破了大门！诺格加尔……他死了！我们应该立刻起锚，前往塔拉多！"
D.Strings[73962]="可长官，这是我们最后一头戈隆了！要是我们两手空空地回去，黑手会扒了我们的皮！"
D.Strings[73963]="长、长……长官！他们在干扰钢铁之星！"
D.Strings[73964]="正在点火，长官！"
D.Strings[73965]="长官，没有弹药了！我正在重新填装！"
D.Strings[73966]="长官，我们的部队已经被消灭一半了！我们是不是应该——"
D.Strings[73967]="啊，很好的想法，长官。"
D.Strings[73968]="船长，他们快要过来了！我们该怎么办？！"
D.Strings[73969]="呃……你确定要让那家伙出来吗？我们抓到它之后，好像就没喂过它。"
D.Strings[73970]="好主意，长官！"
D.Strings[73971]="科拉玛尔，不！我会为你报仇的！"
D.Strings[73972]="鲁比洛洛看了看你，然后跑开了！"
D.Strings[73973]="斥候！你有什么要报告的？"
D.Strings[73974]="看来钢铁部落已经行动了。步兵！让工人们都躲起来！"
D.Strings[73975]="拿起武器！各就各位！我们今天的对手相当难缠……"
D.Strings[73976]="中士！地平线上出现了硝烟，远处还传来了战鼓声！"
D.Strings[73977]="我们将首先面对他们的斥候。"
D.Strings[73978]="鲁比洛洛饿了！"
D.Strings[73979]="要成为大主教，我首先得经受一系列的试炼。"
D.Strings[73980]="我可以请一位勇士陪伴我完成这次旅程。我希望这个人是你，$n。"
D.Strings[73981]="我准备好了。来吧，主教议会在等着呢。"
D.Strings[73982]="他们只是来削弱我们的战斗力的……"
D.Strings[73983]="散开！他们可能从各个方向杀过来！"
D.Strings[73984]="鲁克玛射出她的羽毛，将所有灰烬堆点燃，让它们最后战斗一次！"
D.Strings[73985]="我们……我们成功了……"
D.Strings[73986]="|TInterface\\Icons\\Ability_Mage_MoltenArmor.blp:20|t大法师索尔开始施放火焰法术！"
D.Strings[73987]="|TInterface\\Icons\\Spell_Frost_FrostArmor02.blp:20|t大法师索尔开始施放冰霜法术！"
D.Strings[73988]="|TInterface\\Icons\\Spell_MageArmor.blp:20|t大法师索尔开始施放奥术法术！"
D.Strings[73989]="鲁比洛洛看了看你，然后慢慢走开了。"
D.Strings[73990]="鲁比洛洛吠叫起来。那里有东西！"
D.Strings[73991]="它……它死了吗？"
D.Strings[73992]="我被许以了……永恒的生命……"
D.Strings[73993]="我们就快逃出塔纳安丛林了。集中精神，$n。"
D.Strings[73994]="你来、来、来得正是时候，$n。这里好、好好、好冷。难怪我们德莱尼都住、住、住、住在暖和的地方。"
D.Strings[73995]="我准备面对恒燃了。"
D.Strings[73996]="你准备好了吗，英雄？让我们出发吧。"
D.Strings[73997]="打起精神来。这可不是普通野兽的巢穴。"
D.Strings[73998]="来吧，元素之怒！我是不会畏惧你的！"
D.Strings[73999]="干得好，勇士！阿卡玛的任务已经完成了。我已经等不及想看看他听到我们成功会是什么表情了。"
D.Strings[74000]="我要把你和你的要塞撕成碎片。"
D.Strings[74001]="战士的责任……是永无止尽的。"
D.Strings[74002]="迟早会……轮到你的。"
D.Strings[74003]="你是个蠢货，就像泰勒一样。"
D.Strings[74004]="我让海军上将的“追随者”们背叛了他。或许接下来，我该去你的要塞拜访一下？"
D.Strings[74005]="那位黑暗的至尊许给了我很多东西……只要我能成功……"
D.Strings[74006]="<鲁比洛洛好像饿了。或许她的主人可以提供一些帮助。>"
D.Strings[74007]="你的背包被|c00FFFF00|Hspell:168798|h[扒手]|h|r光顾了，损失5个 |c00FFFFFF|Hcurrency:944|h[神器碎片]|h|r。"
D.Strings[74008]="要不是你的话，尼莎也要躺在这里了。"
D.Strings[74009]="奥尔高格已经饿疯了！"
D.Strings[74010]="非常好！我不在的时候，你们排练过吗？"
D.Strings[74011]="对，你们做得很好。"
D.Strings[74012]="太棒了！仪式的力量正在增长！"
D.Strings[74013]="太完美了！哦，我们就要成功了！"
D.Strings[74014]="来吧，布莱恩。振作起来！"
D.Strings[74015]="振作起来，伙计。回我们这儿来。"
D.Strings[74016]="%s未能侦测到附近的敌人 ，即将发动|cFFFF0404|Hspell:168929|h[火炮弹幕]|h|r！"
D.Strings[74017]="它来了……在黑夜之中……"
D.Strings[74018]="就是这里。加尔鲁什·地狱咆哮就得意洋洋地高踞于这些城门后面的宝座上。$B$B这次，我们决不能再让他跑了，$n。"
D.Strings[74019]="你没看见我正在钓鱼吗？"
D.Strings[74020]="此时此刻，我们只需要等待一个机会。一旦敌人的攻势减弱，我们就可以行动了。"
D.Strings[74021]="<大法师全神贯注地盯着黑暗之门。>$b$b看，他们的人数变少了，但还很不明显。这或许就是我们的机会。$b$b你们做好准备，面对黑暗之门另一边的一切了吗？"
D.Strings[74022]="为了艾泽拉斯！"
D.Strings[74023]="小心点。如果我听说的传闻是真的，你就会发现自己正置身于极大的危险之中。"
D.Strings[74024]="你已经展示出了极大的勇气，并找回了一件珍贵的神器。Lok'tar。"
D.Strings[74025]="我不知道你会在那里发现什么，但如果你遇到钢铁部落的人，绝对不要手下留情。"
D.Strings[74026]="玛戈隆之心……这下我们终于有了对付钢铁部落的利器了。"
D.Strings[74027]="宾奇维斯小姐！矿脉号，它刚刚撞上了南边的山峰！"
D.Strings[74028]="什么？！他们应该只负责观察才对；我们得立刻派出救援小队！"
D.Strings[74029]="哇！那是什么？"
D.Strings[74030]="你做好了起飞准备，就告诉卡鲁吧。"
D.Strings[74031]="整个德拉诺到处都是木材！"
D.Strings[74032]="这个世界到处都是木材，指挥官，但我推荐你去戈尔隆德或塔拉多收集。"
D.Strings[74033]="这个世界到处都是木材，指挥官，但我推荐你去阿兰卡峰林或塔拉多收集。$B$B这两个地区都有着丰富的木材资源！"
D.Strings[74034]="纳格兰是收集木材的最前线，$g先生:女士;。$B$B当然，德拉诺的其他地方也完全能让你发挥你的伐木技术。"
D.Strings[74035]="我无法相信巴隆斯已经不在了……指挥官，如果你不介意，那我要专心工作了。"
D.Strings[74036]="可怜的索恩，她是那么伤心。我想她再也不会从狼人形态变回来了。"
D.Strings[74037]="从这里到黑石铸造厂，依然有着一大段的危险地带。"
D.Strings[74038]="戈尔隆德并不适合大部队活动。这片土地会吞噬所有进入它的人。只要能看一眼钢铁部落的基地，我们就算是走运了。"
D.Strings[74039]="我们应该带一支部队来打击钢铁部落！"
D.Strings[74040]="生命短暂，指挥官，最重要的是把握现在。"
D.Strings[74041]="巴隆斯是个好人。$b$b要是我能在他生前多关注他就好了。我永远也无法原谅自己就这么错过了他。"
D.Strings[74042]="哈！你的个头只会拖累你，巨人。"
D.Strings[74043]="告诉我，指挥官，你觉得索恩中尉这人怎么样？每次靠近她时，我就会变得紧张。$b$b我就是……不擅长和女性相处。只有她是个例外。是的，一个女人。虽然她是个狼人。那我也喜欢。噢，那长长的，丝滑的毛发……$b$b唉……"
D.Strings[74044]="指挥官，我就是想问问。巴隆斯有没有跟你提过我？什么？噢……我就是随口问问。$b$b<索恩脸红了起来。>"
D.Strings[74045]="伐木只是一种爱好。我真正的职业是唱歌跳舞。我和我的团队，摇摆男孩，我们总有一天会大红大紫的。"
D.Strings[74046]="这个世界到处都是木材，指挥官，但我推荐你从戈尔隆德找起。$B$B如果你喜欢冒险，也可以去影月谷碰碰运气，但我听说那个地区已经被联盟控制了。如果不小心的话，你可能会遇到一些麻烦。$B$B霜火岭的树木不多，如果你实在没办法了，也可以在附近看看，或许能找到一些小树。"
D.Strings[74047]="这个世界到处都是木材，指挥官，但我推荐你从影月谷或戈尔隆德找起。$B$B如果你喜欢冒险，也可以去霜火岭碰碰运气，但我听说那个地区已经被部落控制了。如果不小心的话，你可能会遇到一些麻烦。"
D.Strings[74048]="大地之怒，请用你的力量保护这些英雄吧！"
D.Strings[74049]="烈焰之怒，让我们的拳头和武器熊熊燃烧吧！"
D.Strings[74050]="狂风之怒，用你的力量祝福这些战士吧！"
D.Strings[74051]="流水之怒，治疗我们的伤口吧！"
D.Strings[74052]="我还以为自己死定了呢。谢谢你，英雄。"
D.Strings[74053]="这场大雾让我措手不及。感谢你的帮助。"
D.Strings[74054]="谢谢你，陌生人。这场大雾怎么会突然降到我们头上？"
D.Strings[74055]="非常感谢，英雄。我还以为自己死定了呢。"
D.Strings[74056]="祝福你，陌生人。现在我能自己回去了。"
D.Strings[74057]="这片沼泽的土著生物似乎完全不受这种毒雾的影响。$B$B这些龙虾人和螃蟹肯定有什么办法抵抗这种奇怪的现象。"
D.Strings[74058]="幸运的是，我们发现本地生长的蘑菇具有很强的滋补作用。$B$B当我们在大雾中探路时，就是靠吃蘑菇来恢复力气，抵抗毒素的。"
D.Strings[74059]="我们激活了|c00FFFF00|Hspell:178538|h[法师传送门]|h|r！干得好！"
D.Strings[74060]="塞拉希尔之斧控制了你！"
D.Strings[74061]="法师传送门被部落摧毁了！"
D.Strings[74062]="哈！我接下来的对手……是你？"
D.Strings[74063]="我很抱歉！我必须服从这把斧子的低语！"
D.Strings[74064]="|c00FFFF00|Hspell:178537|h[骑兵]|h|r们外出巡逻了！"
D.Strings[74065]="|c00FFFF00|Hspell:178537|h[骑兵]|h|r被部落击杀了！"
D.Strings[74066]="我的头脑被控制了！塞拉希尔！"
D.Strings[74067]="你今天杀了几个联盟杂碎，$n？"
D.Strings[74068]="抓住你了！就是你！"
D.Strings[74069]="愚蠢的小老鼠，你们又迟了一步。高格里克之心是我的了。"
D.Strings[74070]="你太不走运了，我的剑刃渴望鲜血。"
D.Strings[74071]="看看我们谁快！"
D.Strings[74072]="督军，我们控制住它了。"
D.Strings[74073]="看我们谁先跑回去！"
D.Strings[74074]="它……出来了。督军，我们失败了……"
D.Strings[74075]="嘿，这不公平。"
D.Strings[74076]="我没时间陪你玩了，英雄，你的末日将近。下次碰面就是你的死期。"
D.Strings[74077]="20！准备好了吗？我来了！"
D.Strings[74078]="找到你了！"
D.Strings[74079]="希德，布莱！"
D.Strings[74080]="那么，我希望你能在天黑之前回家来。"
D.Strings[74081]="不要惹麻烦。"
D.Strings[74082]="再见，妈妈。"
D.Strings[74083]="好的，妈妈。"
D.Strings[74084]="有什么收获吗？"
D.Strings[74085]="有鱼咬钩吗？"
D.Strings[74086]="所以，别动……"
D.Strings[74087]="或许我们该换个地方？"
D.Strings[74088]="和上两次一样。"
D.Strings[74089]="主母已经安全了。你已经证明自己是个有价值的朋友；我期待能再次与你并肩作战。"
D.Strings[74090]="哈哈……哈哈……啊哈哈哈哈！没人告诉过你们不要随便玩火吗？"
D.Strings[74091]="他们抓走了图卡玛下士！"
D.Strings[74092]="对我们来说，天空也不是遥不可及的。是的，就是这样。"
D.Strings[74093]="暮色渐起，群星璀璨。"
D.Strings[74094]="我的枪从不落空！奖品基本已经是我的了！"
D.Strings[74095]="圣光在上，你就非得要最臭的那一个吗。"
D.Strings[74096]="噢，搞得那么臭也不是他的错，对吧？"
D.Strings[74097]="托米·乔，你上次洗澡，还是大灾变之前的事了。"
D.Strings[74098]="即使在光明之下，也有阴影的存在。"
D.Strings[74099]="来抓一头最凶的吧，指挥官！"
D.Strings[74100]="看它跑起来的样子！"
D.Strings[74101]="噢……刚才只差一点了！"
D.Strings[74102]="看来你不打碎几只鸡蛋是做不成牛奶了！"
D.Strings[74103]="不知道其他选手进展如何了。"
D.Strings[74104]="要塞里的人肯定会喜欢它的。"
D.Strings[74105]="我已经想吃掉它了，就咬一口怎么样？"
D.Strings[74106]="又打偏了。"
D.Strings[74107]="托米·乔，你上次这么做的时候，结果可是弄得一脸的伤。"
D.Strings[74108]="要想赢得比赛的话，我真的要好好提高一下准头了！"
D.Strings[74109]="你知道吗，把这些东西拖回去可不像逛公园那么轻松。"
D.Strings[74110]="一头狼差点就咬到我的脚了！"
D.Strings[74111]="在我那会儿，雪地里的狼会咬掉我们两只脚，正好离开和返回铁炉堡的路上各咬掉一只。"
D.Strings[74112]="这家伙比上次那个还要大！"
D.Strings[74113]="比三头牛捆在一起还要大！"
D.Strings[74114]="是啊，确实很大……等等，什么？"
D.Strings[74115]="快来看看我的新货吧！"
D.Strings[74116]="快来试试德拉诺最好用的工具把！"
D.Strings[74117]="来自传说中的艾泽拉斯的稀罕货色！"
D.Strings[74118]="总有一天，我会拥有自己的暖房。"
D.Strings[74119]="只要再等两年，我就能自己出来单干了。"
D.Strings[74120]="我很高兴杰赛尔能逃出卡拉波。"
D.Strings[74121]="能再给我一个月壳蟹爪诱饵吗？"
D.Strings[74122]="图门？是你吗？"
D.Strings[74123]="那个大吼大叫的家伙是谁？"
D.Strings[74124]="贝雷萨尔？好久不见。你怎么回来了？"
D.Strings[74125]="我听说了袭击的事，就出来帮忙了。"
D.Strings[74126]="很高兴见到你。要我帮你拿点什么吗？"
D.Strings[74127]="先来两包吧。"
D.Strings[74128]="你觉得自己有资格接受我的力量？那就证明一下吧！"
D.Strings[74129]="很不错啊……"
D.Strings[74130]="我一直在等着你。我要砍死你——然后把你的要塞烧成灰烬。"
D.Strings[74131]="蠢货，你竟敢挑战我？我要把你烧成灰。"
D.Strings[74132]="这么说，你就是阿祖卡提起过的那个人。太弱了，我还以为这会有多难呢。准备受死吧。"
D.Strings[74133]="多年来，我的人民一直被塞泰的诅咒所折磨，我们一直在寻求解决的办法。"
D.Strings[74134]="某种屏障包裹着这个岗哨。我们得找出原因。"
D.Strings[74135]="让我们来调查一下吧。"
D.Strings[74136]="开始施展法术吧。我会保护你的！"
D.Strings[74137]="如你所愿。卡特索，让这个“角斗士”看看火刃氏族的实力。"
D.Strings[74138]="箱子是空的，混沌之心已经被偷走了。"
D.Strings[74139]="算你走运，竞技场里的荣耀让我及时收手了。"
D.Strings[74140]="巫术、仪式和典礼。黑暗绝望、难以名状的暴行，一切都是徒劳的。"
D.Strings[74141]="是谁敢挑战我的氏族？"
D.Strings[74142]="现在我们必须面对钢铁部落的舰队了。他们的一艘战舰上搭载了一件强大的武器，现在就停泊在海岸边。我知道一个可以肃清道路的法术，但它需要我集中全部精神来引导。在念诵咒语时，我将非常脆弱，只能靠你和我们的盟友来保护我了。"
D.Strings[74143]="继续搜索阿祖卡·刃怒。"
D.Strings[74144]="虽然我们在阴影中找到栖身之所，但依然为此感到羞耻。我们迷失了自己的道路。"
D.Strings[74145]="这不可能！无礼的畜生。你竟敢亵渎我氏族的荣耀？"
D.Strings[74146]="这已经成为私怨了。让我亲自来试试你的本事。"
D.Strings[74147]="我将我的人民引入了歧途。就算你和其他人一样对他们敬而远之，也没人能指责你。"
D.Strings[74148]="但你却对他们表达了善意。有意思。"
D.Strings[74149]="我们要塞的农场从艾泽拉斯进口了玫瑰吗？我都不记得了。"
D.Strings[74150]="我得安排一次巡逻，看看还有没有火刃氏族的成员混进了要塞。"
D.Strings[74151]="巴隆斯，你这个笨蛋……你应该早点向我表白的。那事情就不会变成这样了。"
D.Strings[74152]="游戏还没结束呢。钢铁部落……会……付出代价的。"
D.Strings[74153]="这些雾气相当危险。我会尽力保护你安全的，但别忘了用蘑菇来治疗自己。"
D.Strings[74154]="看！那个怪物肯定是这场毒雾的源头！"
D.Strings[74155]="合作愉快，英雄！我们已经解决了沼泽的诅咒。我得继续前进了，等你搞定之后就来找我吧。"
D.Strings[74156]="我手下的六位游侠失踪了。请找到他们！"
D.Strings[74157]="谢谢你帮助我的人民，朋友。我一定会将你的善举告诉大主教伊瑞尔的。"
D.Strings[74158]="琼斯先生！是你吗？"
D.Strings[74159]="你带给了他们力量。虽然诅咒可能会永远纠缠入骨，但我看到他们仍能傲然挺立。"
D.Strings[74160]="你做到了我没能做到的事。你让我的人民得到了自由。"
D.Strings[74161]="你就是他们的利爪之王。"
D.Strings[74162]="你就是他们的利爪女王。"
D.Strings[74163]="艾里塔克从她的蛛网里爬下来了！"
D.Strings[74164]="|TInterface\\Icons\\Ability_Racial_Cannibalize.blp:20|t艾里塔克开始|cFFFF0000|Hspell:169248|h[吞噬]|h|r一名白鬼兽人！"
D.Strings[74165]="|TInterface\\Icons\\spell_festergutgas.blp:20|t一个白鬼兽人开始|cFFFF0000|Hspell:169233|h[吸入]|h|r剧毒瓦斯！他们活得越久，力量就越强。"
D.Strings[74166]="好……渴啊。"
D.Strings[74167]="回归大地吧。"
D.Strings[74168]="滋养我的根须吧。"
D.Strings[74169]="我是，不可，阻挡的。"
D.Strings[74170]="焕然一新。"
D.Strings[74171]="来吧，他的力量还没有完全恢复。"
D.Strings[74172]="我来对付塞泰，你去对付邪教徒！"
D.Strings[74173]="见证我的重生吧！"
D.Strings[74174]="我的鲜血将染黑大海！"
D.Strings[74175]="我的血肉将使天空朽烂！"
D.Strings[74176]="我的恨意……难以平息……"
D.Strings[74177]="*阿嚏*空气中有股气味……"
D.Strings[74178]="穿越了这么厚的岩层？这不可能。拉响警报！"
D.Strings[74179]="拿起武器！各就各位！小心新的野性蔓生物。"
D.Strings[74180]="中士，要塞里长出了奇怪的植物。"
D.Strings[74181]="在德拉诺最危险的地区，常常能见到埃匹希斯水晶。你会发现它们对强化装备非常有用。"
D.Strings[74182]="我们马上得把这玩意儿运回基地去，指挥官！"
D.Strings[74183]="我觉得这是一个良好的开端，预示着紧密高效的合作，朋友。祝你好运。"
D.Strings[74184]="我带来了我最喜欢的绳子！"
D.Strings[74185]="噢不，千万不要是克莱德。"
D.Strings[74186]="这个小家伙身上有些有趣的痕迹。"
D.Strings[74187]="噢，看看他身上的毛！"
D.Strings[74188]="别碰那玩意儿，托米·乔。"
D.Strings[74189]="小心点，勇士。"
D.Strings[74190]="你把敌人引到西边去，我带着剩下的人往南边跑。"
D.Strings[74191]="伊瑞尔、玛尔拉德和杜隆坦需要你去旗舰上帮忙。黑手是不会不战而降的。"
D.Strings[74192]="是谁竟敢挑战鲁格多尔？"
D.Strings[74193]="我要扭断所有挑战者的脖子！"
D.Strings[74194]="没人能击败鲁格多尔！鲁格多尔是最厉害的！"
D.Strings[74195]="已经没有对手了。鲁格多尔真难过。"
D.Strings[74196]="我必将成为新的鲜血勇士。你死定了！"
D.Strings[74197]="下一个鲜血勇士就是我。去死吧！"
D.Strings[74198]="你的脑袋将成为我的幸运符，让我成为新的鲜血勇士。"
D.Strings[74199]="你只是我迈向鲜血勇士道路上的又一个祭品罢了。"
D.Strings[74200]="我们激活了|c00FFFF00|Hspell:178539|h[法师传送门]|h|r！"
D.Strings[74201]="结局不该是这样……"
D.Strings[74202]="可你这么矮小……"
D.Strings[74203]="|c00FFFF00|Hspell:178539|h[法师传送门]|h|r被联盟摧毁了！"
D.Strings[74204]="鲁格多尔……完了。"
D.Strings[74205]="够了！鲁格多尔要揍扁你！"
D.Strings[74206]="|c00FFFF00|Hspell:178536|h[狼骑兵]|h|r们外出巡逻了！"
D.Strings[74207]="|c00FFFF00|Hspell:178536|h[狼骑兵]|h|r被联盟击杀了！"
D.Strings[74208]="|c00FFFF00|Hspell:178534|h[术士传送门]|h|r被联盟摧毁了！"
D.Strings[74209]="|c00FFFF00|Hspell:178359|h[克鲁努斯]|h|r复活了！"
D.Strings[74210]="你们这些蠢货！联盟杀了|c00FFFF00|Hspell:178359|h[克鲁努斯]|h|r！"
D.Strings[74211]="我们已经设法控制了这座建筑。在这里，你就不会受到雾气侵蚀了。"
D.Strings[74212]="当里面有人在工作时，矿井入口会被封起来。"
D.Strings[74213]="我们要联手战胜它。"
D.Strings[74214]="你的体型只会拖累你！"
D.Strings[74215]="我记得你的真面目。"
D.Strings[74216]="对！烧死它……姐妹。"
D.Strings[74217]="噢，对，这段对话从未发生过。我们要做公正的推广者。"
D.Strings[74218]="小心你的侧面，姐妹。"
D.Strings[74219]="马上就来。"
D.Strings[74220]="这就是生活。我很想念昔日美好的纳格兰。"
D.Strings[74221]="这些应该能管用。谢谢你，图门，希望我能尽快返回他们身边。"
D.Strings[74222]="我们竞技场里见，勇士。"
D.Strings[74223]="给。希望你能尽快回到沙塔斯的家人身边。"
D.Strings[74224]="我们正在逐步占得上风。联盟和部落都在大陆上建立了要塞。但我们还得小心敌人的反击……"
D.Strings[74225]="我准备好了。开始施法吧！"
D.Strings[74226]="我已经迫不及待地想要探索德拉诺了，珀西！"
D.Strings[74227]="移除路障！"
D.Strings[74228]="噢，新戏法！"
D.Strings[74229]="那真是太棒了！"
D.Strings[74230]="他到底是什么？"
D.Strings[74231]="汪*汪*"
D.Strings[74232]="珀西是一条哈巴狗。"
D.Strings[74233]="一条……什么？"
D.Strings[74234]="唔……呃，哈巴狗是我们艾泽拉斯的一种狗。"
D.Strings[74235]="他的脸真是太让人遗憾了。"
D.Strings[74236]="汪汪*！"
D.Strings[74237]="我是魔导师赛琳娜。很高兴见到你！"
D.Strings[74238]="指挥官，我们的空军中队已经削弱了那头玛戈隆，可我们也被拖在这儿了。我们需要你帮忙去突袭那座主建筑。"
D.Strings[74239]="我不喜欢这玩意儿的样子，英雄。"
D.Strings[74240]="这是他吗？"
D.Strings[74241]="加尔鲁什一抵达德拉诺就背叛了他。"
D.Strings[74242]="是的。这里就是凯诺兹多姆的葬身之地。"
D.Strings[74243]="啊，欢迎，守备官伊瑞尔。我知道你是来接受玛拉达尔的试炼的。"
D.Strings[74244]="英灵们都感受到了你的决心。他们已经等不及要挑战你了。"
D.Strings[74245]="能面对古代的英雄们是我的荣幸。我不会让他们失望的。"
D.Strings[74246]="祝你好运，伊瑞尔女士。"
D.Strings[74247]="伊瑞尔，我一直都期待看到这样的你。别让我失望。"
D.Strings[74248]="你好，老师。请看看我在旅途中学到的东西吧。"
D.Strings[74249]="你已经超出了我的期望，伊瑞尔。你可以继续前进了。"
D.Strings[74250]="现在，该去让玛尔拉德安息了。"
D.Strings[74251]="伊瑞尔……你比我们上次见面时成长了很多。但这……是否足够？你能不能领导我们的人民？"
D.Strings[74252]="现在，就让我来考验一下你的力量吧。"
D.Strings[74253]="当你面对更强大的敌人时，还能保持坚定吗？"
D.Strings[74254]="别怕，我一定会坚持到底的！"
D.Strings[74255]="当我们的人民都指望着你时，你做好发号施令的准备了吗？"
D.Strings[74256]="我不会辜负他们的！"
D.Strings[74257]="当所有的希望都消失时，你还能……继续……战斗吗？"
D.Strings[74258]="我绝不放弃！"
D.Strings[74259]="我……可以……"
D.Strings[74260]="当你审视内心，却只有一片黑暗时，你还能继续追随圣光吗？"
D.Strings[74261]="因为……在这个世界……我们永远不会……"
D.Strings[74262]="英雄！使用战锤，快！"
D.Strings[74263]="伊瑞尔……看来是真的。学生已经超越了老师。你已经做好了准备。"
D.Strings[74264]="如果先知维伦能看到你现在的样子该多好……他会为你骄傲的。"
D.Strings[74265]="站起来吧，伊瑞尔。团结德莱尼的任务就交给你了。让他们做好迎接挑战的准备吧。"
D.Strings[74266]="玛尔拉德，我的朋友……安息吧。"
D.Strings[74267]="谢谢你，英雄。我稍后再来找你。我需要一些时间来向先祖致敬。"
D.Strings[74268]="只剩最后一个试炼了，伊瑞尔。就是我们！"
D.Strings[74269]="你已经选择了你的勇士。现在，让我们开始吧！"
D.Strings[74270]="啊，我被击败了。"
D.Strings[74271]="真是强大！"
D.Strings[74272]="我认输！"
D.Strings[74273]="伊瑞尔，今天，你完成了大主教的试炼。"
D.Strings[74274]="你已经证明了自己的勇气、仁慈、信仰和力量……它们正是支撑我们民族的脊梁。"
D.Strings[74275]="但是，在衡量一位领袖时，我们看的并不仅仅是她本人的表现，还有她朋友们的表现。"
D.Strings[74276]="勇士，你也同样接受了考验。"
D.Strings[74277]="在霜火岭，我们看到了你的勇气；在纳格兰，我们看到了你的执着；在奥金顿，我们看到了你的忠诚。"
D.Strings[74278]="你对伊瑞尔女士的忠诚向我们证明了她有这个能力。不是我们，而是你选出了新的大主教。"
D.Strings[74279]="伊瑞尔，别忘了，一个优秀的领袖能带领人民走向伟大。相信你的人民，相信你自己。"
D.Strings[74280]="现在，站起来吧……"
D.Strings[74281]="大主教伊瑞尔！"
D.Strings[74282]="祝你好运，伊瑞尔。勇气源自头脑和心灵。"
D.Strings[74283]="我的祝福与你同在，伊瑞尔。别忘了那些不幸的人们。"
D.Strings[74284]="让信仰指引你，伊瑞尔。"
D.Strings[74285]="看清楚你们的送葬者吧，英雄们。"
D.Strings[74286]="这头玛戈隆在第一个兽人出现前就行走于德拉诺。而现在，它将服从于我的意志。"
D.Strings[74287]="它将摧毁你的部队和你那微不足道的要塞。但首先，它将摧毁你！"
D.Strings[74288]="那头野兽被击败了，可我们还不能休息。我们还有一个敌人。"
D.Strings[74289]="大门那边需要我。有人在战场上看见了地狱咆哮酋长。"
D.Strings[74290]="去找到刃怒，把她的脑袋带来给我！"
D.Strings[74291]="漂亮！打得好，伙计。可在那个女兽人死掉之前，我们是不会离开的。"
D.Strings[74292]="大门那边需要我。他们说格罗玛什也加入了战斗。"
D.Strings[74293]="刃怒就交给你了，把她的脑袋带来给我！"
D.Strings[74294]="我已经玩够了，小老鼠。是时候结束这一切了。"
D.Strings[74295]="我的剑渴望着你的鲜血！"
D.Strings[74296]="不……不……酋长……我……辜负了你……"
D.Strings[74297]="停下！地狱咆哮过来了。"
D.Strings[74298]="看！地狱咆哮现身了。"
D.Strings[74299]="战斗结束了！我们击溃了钢铁部落，把他们赶回大门里去了！"
D.Strings[74300]="钢铁部落是不会失败的！我绝不投降！"
D.Strings[74301]="我会记住这一天的，英雄们。我会记住你们的名字和你们的脸孔，总有一天，我要将你们碎尸万段！"
D.Strings[74302]="你想打一场吗，嗯？你有多厉害呢？"
D.Strings[74303]="万灵从没有像这样强硬地跟我对话过。"
D.Strings[74304]="有一次，我赤手空拳搏杀了两头裂蹄牛！"
D.Strings[74305]="抱歉，每次都让你接受这么危险的任务。但你会把这些经历全部忘光的，希望这能让你感觉好受一些。"
D.Strings[74306]="这些灰槌食人魔没能打破我的巨石之盾，所以把我扔进了这个牢笼……现在我自由了，已经用不上它了，就送给你吧，$n。"
D.Strings[74307]="哈！你根本不够强嘛。"
D.Strings[74308]="如果没有了这种原始之美，德拉诺就不是德拉诺了。"
D.Strings[74309]="我们三个各有长处。克罗米能操纵时间治疗我们的伤口，我能抵挡巨龙的攻击。我们都是出色的战士。$b$b但你才是战术专家。我们都听你指挥。你最擅长哪方面呢？等你做好决定，我们就开始了。"
D.Strings[74310]="我来负责输出伤害。"
D.Strings[74311]="我来负责治疗。"
D.Strings[74312]="我来负责防御。"
D.Strings[74313]="别对你的学生们大吼大叫的；相反，你应该在教导他们时使用温和但坚定的语气。这会让他们更加专心听讲。而且老实说，这会比大吼大叫更加吓人。"
D.Strings[74314]="很少有人能真正理解这个世界的结构有多么脆弱。$b$b为什么一个设计得如此差劲的法术都能让我们的现实世界戛然而止呢？"
D.Strings[74315]="火焰箭、寒冰箭、奥术冲击，这些都是魔力的简单表现。$b$b它们都属于安全法术，经过了时间的检验，稳定而有效。$b$b现在，如果你们真的想炸掉整个宇宙，呃……有些东西最好还是放在高级班上讲吧。"
D.Strings[74316]="在真正理解创造法术的技巧前，你们最好先问问自己能看见多少兔子？$b$b当你们理解这个问题的真意时，宇宙的本质就会更加清晰了。"
D.Strings[74317]="如果法术没能命中，请确认你们试图掌握的魔力有足够的能量出现在目的地。"
D.Strings[74318]="这周我们要继续讨论……魔网。关于它的实用性的魔法解释是很难理解的。"
D.Strings[74319]="永远不要低估一个掌握了隐形术的孩子的机灵劲儿和淘气程度。"
D.Strings[74320]="鲁格多尔！这个小东西对你做了什么？！"
D.Strings[74321]="格罗姆卡弓箭手，自由射击！！！"
D.Strings[74322]="我曾被夺走过翅膀。你休想再夺走它们！"
D.Strings[74323]="干得好，$n。让我把你安全地送回地面吧。"
D.Strings[74324]="这不可能！我的翅膀又一次辜负了我……"
D.Strings[74325]="太好了，又有材料送上门了！"
D.Strings[74326]="你觉得自己够强吗，$n？记住，战斗开始之后，你就必须留在竞技场内。这可是生死之战！"
D.Strings[74327]="来吧，女士们、先生们。欢迎来到独一无二的鲜血竞技场欣赏史无前例的大屠杀、大破坏吧！在这场终生难得一见的比赛中，来历不明的$n将与火刃氏族的卡特索争夺荣耀的鲜血勇士头衔！"
D.Strings[74328]="鲜血勇士之战现在开始！"
D.Strings[74329]="差的太远了，宝贝！简直是一面倒的屠杀！"
D.Strings[74330]="干掉他！噢，等等，你又来了。竞技场的地板也被弄脏了。我们这儿得打扫一下了！"
D.Strings[74331]="噢，看在老天的份上……我刚刚打扫过这里！你下次杀人时能不弄得这么脏吗？"
D.Strings[74332]="真是场一面倒的战斗！完全不公平。双方差距太大了！"
D.Strings[74333]="伍迪，把刮刀扔给我。这下面真是一团糟！"
D.Strings[74334]="正中面部！我在这儿都能感觉到这一击的威力！"
D.Strings[74335]="要……要……死了！彻底死了。噢，真是没人性！"
D.Strings[74336]="一定要把这场战斗转述给你们的孩子们，各位。我很多年都没见过这么刺激的屠杀了！"
D.Strings[74337]="阿祖卡·刃怒从阴影中显身了！"
D.Strings[74338]="我们要找到那条龙，不论死活！"
D.Strings[74339]="难以置信。要不是你，大法师就死定了！"
D.Strings[74340]="经过这么多年，我有点厌倦艾尔文森林了，因此决定出来闯荡一番。"
D.Strings[74341]="这里的夜晚真是安静得恐怖，让我有点怀念远处闪金镇传来的噪音了。"
D.Strings[74342]="你见过那些双头飞龙吗？不知道它们吃起来是什么味儿。"
D.Strings[74343]="真希望不用再住在这个兽栏里了，我衣服上这股臭味不知道还能不能洗掉。"
D.Strings[74344]="妈妈就在附近烤肉呢。她能帮你烤一片腰肉！"
D.Strings[74345]="跟这么多不同的人一起出来闯荡之后，我开始反思那些马科伦家的人是不是真有那么坏。"
D.Strings[74346]="你能教我怎么用陷阱抓捕野兽吗？"
D.Strings[74347]="这个强化钢铁陷阱有什么新功能？"
D.Strings[74348]="致命的钢铁陷阱有什么用？"
D.Strings[74349]="打到的兽肉有什么用？"
D.Strings[74350]="哦，你需要从我身边的这些陷阱里挑选一个，然后出去找一头野兽。你需要找塔布羊和雷象，但狼和裂蹄牛也能凑活。$B$B你要做的就是狠狠地揍你选中的野兽，等它失去战斗力之后，再把它引到陷阱里就行了。要小心的是，陷阱也可能会夹住你的脚！$B$B然后，把陷阱带回来给我们，我们可以把它变成物资。你抓到的野兽类型将决定我们的收获：裂蹄牛和雷象能提供最好的皮革，而塔布羊和狼有最丰厚的毛皮。"
D.Strings[74351]="这种陷阱显然比上一种更加有弹性。有了强化钢铁陷阱，你就可以抓到野猪和淡水兽了。$B$B把你抓到的野猪和淡水兽带回来，我母亲可以帮你做出最美味的烤肉！"
D.Strings[74352]="这是我们能制造的最大，最坚固的陷阱。它能让你抓住这个世界上最大的野兽。在纳格兰，你可以找到最强大的动物。只要抓住一头，你就能获得大量顶级物资！"
D.Strings[74353]="把它们交给我妈妈，她可以帮你烤一块肉排。"
D.Strings[74354]="非胜即死，伙计！非胜即死！你可不能逃跑！"
D.Strings[74355]="你想要打一场吗，勇士？"
D.Strings[74356]="主厅的入口开启了！"
D.Strings[74357]="大主教哈塔鲁背后的屏障打开了！"
D.Strings[74358]="你的一去不回让我愤怒极了。我不明白你为什么一定要去。"
D.Strings[74359]="我知道，库戈拉……可我们的军队需要我。"
D.Strings[74360]="通向中央平台的传送器已经激活！"
D.Strings[74361]="我不明白你为什么一定要走。"
D.Strings[74362]="我知道，库戈拉……可，我希望能帮忙结束这场惨痛的冲突。"
D.Strings[74363]="雷神氏族饶了我一命，可他们强迫我为他们干活……为他们锻造武器来对付我们的氏族。"
D.Strings[74364]="你为什么不试着逃跑！？"
D.Strings[74365]="我试了，库戈拉！他们抓住了我……折磨我……"
D.Strings[74366]="库戈拉，你不用向我道歉！可现在，我必须请求你继续我的工作。"
D.Strings[74367]="雷神氏族想让我锻造武器来对付我们的兄弟姐妹。"
D.Strings[74368]="你也算是我的助手。你应该学会多关注你的员工。"
D.Strings[74369]="我……我不知道。我很抱歉，我的愤怒害死了我自己的父亲。"
D.Strings[74370]="对不起，老板。"
D.Strings[74371]="库戈拉，你不用向我道歉！拿上我的锤子，继续战斗，为我争光吧！"
D.Strings[74372]="看看发生了什么？你的助手被烧死了。你对此有什么感觉？"
D.Strings[74373]="不太好……"
D.Strings[74374]="我在此宣誓效忠$n。我将追随$G他:她;完成 $G他的:她的;任务，对抗钢铁部落这一新的威胁。"
D.Strings[74375]="父亲，我发誓我会让你骄傲的！"
D.Strings[74376]="我肯定不想被这些火刃氏族的长剑刺中。说说都觉得疼。"
D.Strings[74377]="你已经做到了，库戈拉，你已经……"
D.Strings[74378]="一个$c？噢，你来得正是时候。$b$b我们像往常一样进行挖掘时，根本没想到会发现什么东西。"
D.Strings[74379]="我可怜的助手……"
D.Strings[74380]="谢谢你，$n。如果你需要帮助，就尽管回来找我吧。"
D.Strings[74381]="|TInterface\\Icons\\warrior_disruptingshout.blp:20|t%s开始施放|cFFFF0000|Hspell:169498|h[震耳怒吼]|h|r！"
D.Strings[74382]="我准备好参加鲜血勇士之战了。"
D.Strings[74383]="我很抱歉，我的愤怒害死了我的父亲。"
D.Strings[74384]="好了，好了，往里走。不敢上场也没什么好羞愧的。下一个！"
D.Strings[74385]="看来我们的选手临时退出了，各位。直接开始下一场比赛吧！"
D.Strings[74386]="时间到，时间就是金钱。让我们直接有请下一位！"
D.Strings[74387]="人呢？我刚才睡着了！下一个！"
D.Strings[74388]="快走，快走。我们的时间有限，各位。"
D.Strings[74389]="我是不会怪你的，伙计。要是你真进去的话，现在恐怕已经死了。"
D.Strings[74390]="这是什么情况？快让选手进入竞技场！"
D.Strings[74391]="在这个节骨眼上，我们到底是要奋力战斗还是高挂免战牌？投入点感情，各位！"
D.Strings[74392]="我准备好接受信仰的试炼了。"
D.Strings[74393]="让我看看你的本事吧。"
D.Strings[74394]="|TInterface\\Icons\\achievement_halloween_rottenegg_01.blp:20|t艾里塔克对你放出剧毒小蜘蛛！"
D.Strings[74395]="你把戒指带来了吗？很好！你准备好了吗？$b$b抓紧舵柄，$c！"
D.Strings[74396]="我准备好了，大法师。"
D.Strings[74397]="我现在就前往你的要塞，$n。"
D.Strings[74398]="够了！对一只逃出笼子的老鼠来说……还算不错。"
D.Strings[74399]="但你知道我的剑有什么力量吗？杀的人越多，它就会变得越强。"
D.Strings[74400]="你休想活着离开！"
D.Strings[74401]="%s将一封信投入邮箱。"
D.Strings[74402]="传送门失守了！我们必须在这头野兽逃跑前阻止它！"
D.Strings[74403]="我们引起了它的注意！"
D.Strings[74404]="快，把它引到火场那边去！"
D.Strings[74405]="它在复活那些喽啰！"
D.Strings[74406]="藤蔓缠住了所有人！"
D.Strings[74407]="这看起来可不太妙……"
D.Strings[74408]="我们失败了！它击退了我们！"
D.Strings[74409]="你想死在这里吗？！快跑！"
D.Strings[74410]="你们救了我们所有人！谢谢你们，陌生人，要不是你们，这座城市就失守了。"
D.Strings[74411]="我从没想过我们会被部落的人所救。趁暴风城的守卫还没赶到，你们快走吧……"
D.Strings[74412]="你逃不掉的……"
D.Strings[74413]="你亵渎了这片土地！"
D.Strings[74414]="你应该被净化！"
D.Strings[74415]="森林庇佑着我们。"
D.Strings[74416]="我们是自然的守护者。"
D.Strings[74417]="生命走到了尽头。"
D.Strings[74418]="我会……再次……重生的……"
D.Strings[74419]="森林包围了你们。"
D.Strings[74420]="水是生命之源！"
D.Strings[74421]="万物滋长！"
D.Strings[74422]="重获新生！"
D.Strings[74423]="小心入侵者！"
D.Strings[74424]="我将回归于……土壤……"
D.Strings[74425]="兽皮已交付！"
D.Strings[74426]="等等……那是塞林的坦克吗？那个家伙还活着！"
D.Strings[74427]="请送我去鸦爪岗哨。"
D.Strings[74428]="他们长得像杂草一样快。"
D.Strings[74429]="割草是苦力干的活儿。"
D.Strings[74430]="占领并控制篝火！"
D.Strings[74431]="联盟控制了这团火焰，但又出现了一团新的！"
D.Strings[74432]="部落控制了这团火焰，但又出现了一团新的！"
D.Strings[74433]="杀了入侵者，把他们的尸体带回来给我。我们还有很多工作要做。"
D.Strings[74434]="快一点。我可不愿让伟大的艾韵久等。"
D.Strings[74435]="把那些入侵者给我带来，死活不论。"
D.Strings[74436]="将这片该死的营地连根拔起。"
D.Strings[74437]="我们的土地又有肥料了！"
D.Strings[74438]="我见过比你们更加危险的杂草。"
D.Strings[74439]="你们休想违逆艾韵的意志。"
D.Strings[74440]="我会为你争光的，督军！"
D.Strings[74441]="亵渎者！你的鲜血将浇灌永茂之地！"
D.Strings[74442]="孤单！"
D.Strings[74443]="穆戈尔有令，竞技场外禁止斗殴。"
D.Strings[74444]="竞技场就在前面，别惹麻烦。"
D.Strings[74445]="穆戈尔说了，竞技场外面禁止斗殴。"
D.Strings[74446]="准备好战斗了吗，小家伙？竞技场就在前面。"
D.Strings[74447]="注意遵守秩序，只有竞技场里才能打架。呃……竞技场外面不准打。"
D.Strings[74448]="如果你想打架，就去跟穆戈尔的小绿皮说吧。"
D.Strings[74449]="如果你敢在竞技场外面打架，我就揍扁你。这是穆戈尔说的。"
D.Strings[74450]="啊啊啊啊！！！我……要维护秩序！"
D.Strings[74451]="你好啊，甜心？"
D.Strings[74452]="%s将最新的坐标标在了羊皮纸上。"
D.Strings[74453]="%s仔细查看着传送器的发现。"
D.Strings[74454]="%s考虑着下一个传送器的位置。"
D.Strings[74455]="好好珍惜这次胜利吧，入侵者。下次见面时，你就要倒霉了！"
D.Strings[74456]="我又发现你了，亵渎者！荒野也救不了你了！"
D.Strings[74457]="碎棘从树上飞下来保护她的巢穴了！"
D.Strings[74458]="你的……你的种群更优越。我全听你的。"
D.Strings[74459]="你已经击败了我两次。这次你输定了！"
D.Strings[74460]="我这就前往你的要塞，主人。到那里之后，我就把知道的一切都告诉你。"
D.Strings[74461]="有什么好东西吗？"
D.Strings[74462]="我会为这份工作找到合适的人选的。"
D.Strings[74463]="我想招募一些人手。"
D.Strings[74464]="|cFF0000FF+1点|r"
D.Strings[74465]="你好，感谢你参加《德拉诺之王》的内测活动！ \n\n我可以将你直接传送到目前开放测试的各大团队副本或地下城。这是单纯的传送，不包括配对服务，所以请事先组织好队伍以应对副本内的挑战。如果你没有队伍，请使用我们最新的队伍查找器功能寻找盟友。\n\n请在传送前选择好你想要测试的难度，因为要想离开副本以变更难度将会比较困难！"
D.Strings[74466]="我想前往血槌炉渣矿井。"
D.Strings[74467]="我想前往钢铁码头。"
D.Strings[74468]="我想前往奥金顿。"
D.Strings[74469]="我想前往通天峰。"
D.Strings[74470]="我想前往恐轨车站。"
D.Strings[74471]="我想前往茂林岗哨。"
D.Strings[74472]="我想前往影月墓地。"
D.Strings[74473]="我想前往黑石塔上层。"
D.Strings[74474]="我想前往悬槌堡（团队副本）。"
D.Strings[74475]="我想前往黑石铸造厂（团队副本）。"
D.Strings[74476]="这么急着去送死吗？"
D.Strings[74477]="我们准备好了，加戈！"
D.Strings[74478]="领袖的任务是无止尽的。让我们继续前进，为正义和人民而战吧。"
D.Strings[74479]="我准备好与主教议会战斗了。"
D.Strings[74480]="辛利一看到你就逃跑了！"
D.Strings[74481]="准备好接受更多挑战了吗，$n？"
D.Strings[74482]="送我去竞技场吧，加戈。"
D.Strings[74483]="不！住手！我控制不住他了！"
D.Strings[74484]="你离家可够远的，$r。只要你有钱，我就能让你飞回去，而不是用斧子招呼你。但你最好别让我等太久。"
D.Strings[74485]="抱歉让你失望了，如果你是来加入奈辛瓦里狩猎队的话，那就太不走运了。$b$b赫米特去协助联盟和部落对付战歌氏族了，所以狩猎队的活动已经暂停了。$b$b这确实很遗憾，这里是我见过的最壮观、最狂野的土地。"
D.Strings[74486]="我还没有完全解开赞加菌类的秘密，但我已经有了很大的进展。$b$b如果我的理论是正确的，那么只要理解了真菌菌株与当地生态之间的联系，我们就能更深刻地了解德拉诺的许多物种！"
D.Strings[74487]="很高兴见到你！我是哈德利·里卡德博士。如你所见，我似乎遇到了一点麻烦……$b$b我被这些魔荚人俘虏了，如果我没有猜错他们的意图的话……他们是想杀了我，然后把我的尸体作为他们幼苗的肥料！"
D.Strings[74488]="是玛丽贝拉·威尔什派我来救你的。快走，我会保护你的！"
D.Strings[74489]="我的研究站就在海滩附近，离这里不远。我在那里等你！"
D.Strings[74490]="我有用过的玻璃瓶。"
D.Strings[74491]="这儿有一箱草药。"
D.Strings[74492]="我在冒险时发现了这些药水。"
D.Strings[74493]="我带来了你想要的东西。"
D.Strings[74494]="希望这能对你有用。"
D.Strings[74495]="有新货色吗？"
D.Strings[74496]="有新货吗？"
D.Strings[74497]="我要选购一些东西。"
D.Strings[74498]="你有些什么？"
D.Strings[74499]="你弄到我要的东西了吗？"
D.Strings[74500]="你有什么可卖的？"
D.Strings[74501]="我就看看。"
D.Strings[74502]="有打折的东西吗？"
D.Strings[74503]="你就想靠那种技术来保护我们？"
D.Strings[74504]="在攻击时，一定要注意保护自己！"
D.Strings[74505]="进攻时再凶猛一点！"
D.Strings[74506]="刚才那下太差劲了！"
D.Strings[74507]="唔……刚才的攻击还不错。继续保持！"
D.Strings[74508]="把你需要的东西列成清单交给我，我马上就开工。"
D.Strings[74509]="你缺什么东西吗？"
D.Strings[74510]="我很快就会完成你的订单的。"
D.Strings[74511]="我们今天有一点滞后了。"
D.Strings[74512]="战争！"
D.Strings[74513]="都去死吧！"
D.Strings[74514]="让他们血流成河吧！"
D.Strings[74515]="这……只是……皮外伤！"
D.Strings[74516]="怨叶……为我报仇！"
D.Strings[74517]="我不能……死……"
D.Strings[74518]="我们的种子……将遮蔽太阳！"
D.Strings[74519]="去死吧，真菌怪！"
D.Strings[74520]="只要找回研究设备和补给，我和腌菜就可以继续我们的实验了！"
D.Strings[74521]="我听说戴格米尔的巢穴就在海滩附近的某个水下洞穴里……真是原始！"
D.Strings[74522]="要想精确解剖这么复杂的器官，你必须有一双稳定的手和精准的……"
D.Strings[74523]="腌菜……不！！"
D.Strings[74524]="快，腌菜！告诉我，你现在是什么感觉，每一个细节都不要漏！"
D.Strings[74525]="等等，腌菜！我们得把实验记录下来！"
D.Strings[74526]="看来我得找个新的研究助理了……"
D.Strings[74527]="一名镇民发生了变异！"
D.Strings[74528]="感谢你帮助我的人民渡过这个黑暗时期。希望有一天我们能够报答你的恩情。"
D.Strings[74529]="法术已经准备就绪了。等你准备好我就可以开始了，$n。"
D.Strings[74530]="如果你的护甲在竞技场里被打烂了，格鲁布能帮你修好它。"
D.Strings[74531]="给肉神的肉！"
D.Strings[74532]="那我走了！"
D.Strings[74533]="嘿，你去过浅滩了吗？"
D.Strings[74534]="我追了它几个小时了。我的袋子就快装满了，马上就可以发货了。"
D.Strings[74535]="来看看我目前收集到了点什么。"
D.Strings[74536]="收集鸟爪显然不那么容易。"
D.Strings[74537]="今年的竞争可真够激烈的！"
D.Strings[74538]="你见识过加莱尔的身手吗？那真是太惊人了！"
D.Strings[74539]="嘿，叫你呢！我这儿有新鲜的食物哦！"
D.Strings[74540]="我们到地方见，指挥官！"
D.Strings[74541]="谢了，伙计！你真是我的救星！"
D.Strings[74542]="还不够！多点，多点，再多点！"
D.Strings[74543]="把他们炸成碎片！"
D.Strings[74544]="救命！救命！……"
D.Strings[74545]="在杜隆塔尔住了那么多年之后，回家的感觉可真不错。"
D.Strings[74546]="我还不太喜欢这么新鲜的空气，感觉野猪的气味淡多了。"
D.Strings[74547]="这不是我记忆中的德拉诺，但那时候我还小，而且纳格兰才是我的老家。"
D.Strings[74548]="我们会尽一切力量帮助部落的。"
D.Strings[74549]="我们这儿的防御很强大，但这片土地非常狂野。"
D.Strings[74550]="为了这次冒险，我特意搞了一根新的草叉。"
D.Strings[74551]="这么说，你想用德拉诺的野兽来检验自己的力量？我年轻时也曾在这上面花费过很多时间。从我身后挑一个钢铁陷阱，然后去找一头狼、裂蹄牛、塔布羊或雷象当对手吧。$B$B首先，你必须将野兽打成重伤，然后把它引到陷阱里，让它被陷阱夹住。$B$B将被抓住的动物带回来给我们，我们可以把它变成物资。你选择的猎物将决定我们的收获：塔布羊和狼有最丰厚的毛皮；裂蹄牛和雷象有最结实的皮革。"
D.Strings[74552]="我们制作出了一种比过去更紧的陷阱。有了这种强化钢铁陷阱，你就可以捕捉强大的野猪和淡水兽了。$B$B野猪和淡水兽的肉肥厚味美。我们可以将它们做成美餐。"
D.Strings[74553]="我们的长老曾说过，在纳格兰的西部平原上栖息着最古老、最强大的野兽。现在，我们有了一种能够比拟任何战狼铁颚的陷阱。如果你能用它抓到那些野兽，那收获的兽毛、兽肉和皮革绝对能够用我们用上一阵子的了。"
D.Strings[74554]="它修好得正是时候，索尔顿！"
D.Strings[74555]="真是一次大丰收，指挥官，我会把它带回要塞的。"
D.Strings[74556]="真是只强大的野兽，干得好！我们这就把它送回去。"
D.Strings[74557]="不错的野兽，它肯定能为我们提供许多物资。"
D.Strings[74558]="这家伙的气味让我想起了杜隆塔尔的野猪牧场。"
D.Strings[74559]="这家伙的皮硬得像铁一样！我得磨一下刀了。"
D.Strings[74560]="啊，纳格兰的空气和我记忆中一模一样。清新中带着鲜血的气味！"
D.Strings[74561]="我闻到了空气中的血腥味，真是不虚此行！"
D.Strings[74562]="杀得好，你应该为此感到骄傲！"
D.Strings[74563]="找到邪能的痕迹并追上他们！我看到她往西边跑了。"
D.Strings[74564]="我看到有什么东西跑过去了。我想她是顺着这座悬崖爬下去了……"
D.Strings[74565]="如果你需要，我会驻扎在你的要塞里。外出时要多加小心。"
D.Strings[74566]="再次感谢你，朋友。我们后会有期。"
D.Strings[74567]="你这个寄生虫！你休想吸食我的世界的鲜血！我们是不会让你得逞的！"
D.Strings[74568]="我是一万年的总冠军，噢耶！"
D.Strings[74569]="鲁克玛尼亚只是希利苏斯沙漠里的一颗小沙子，疯狂主宰才是沙漠！"
D.Strings[74570]="历史在召唤疯狂主宰！"
D.Strings[74571]="我是疯狂主宰兰迪·毁灭，我是艾泽拉斯搏击俱乐部的冠军，而你不是！"
D.Strings[74572]="我们在德拉诺，德拉诺是我们的地盘！"
D.Strings[74573]="噢——耶！"
D.Strings[74574]="再加把劲儿。非常好！"
D.Strings[74575]="我得走了。"
D.Strings[74576]="陷阱起作用了！杀了它！"
D.Strings[74577]="诅咒这些植物害虫。"
D.Strings[74578]="打倒他们。"
D.Strings[74579]="别让那些小东西从你身边溜过去！"
D.Strings[74580]="他们还在不断涌过来！"
D.Strings[74581]="可怜的植物。"
D.Strings[74582]="这里只欢迎角斗士！如果你不是来战斗的，那就不能逗留！"
D.Strings[74583]="你这么弱也敢自称是角斗士？这是在开玩笑吗？快滚！"
D.Strings[74584]="只有角斗士才能进入……要是让我发现你不是来参战的，那我就亲手杀了你！"
D.Strings[74585]="没用的$r！你这下这是惹火我了！"
D.Strings[74586]="知己知彼，百战不殆。"
D.Strings[74587]="保持冷静，指挥官。"
D.Strings[74588]="战斗已经趋于白热化。我们必须继续推进！"
D.Strings[74589]="这是我们打散钢铁部落的机会。坚强点，我们必须守住前线！"
D.Strings[74590]="报告战况！"
D.Strings[74591]="我们在丛林之心见。"
D.Strings[74592]="我得花上几个星期才能把盔甲上的刺拔干净……"
D.Strings[74593]="就是它了，战士们。举起你们的斧子吧！"
D.Strings[74594]="嘿，指挥官！我发现了一片极具战略价值的树林。$b$b我只需要建一座前门，免得我们每次进出时找不到北。$b$b你愿意接受这份荣幸吗？只要按下这个起爆器，你就可以坐在一边欣赏烟花了。"
D.Strings[74595]="$n往布告牌上钉了一张通告。"
D.Strings[74596]="拿上我所有的神器碎片吧！"
D.Strings[74597]="哦，伙计，刚才那下撞得太狠了，我的肚子里都搅成一锅粥了。"
D.Strings[74598]="我还以为自己肯定要死在那里了。真是太感谢你了！"
D.Strings[74599]="我一定要请你喝一杯！"
D.Strings[74600]="我欠你一条命！谢谢你救了我！"
D.Strings[74601]="<这个刺客已经坚持不下去了。她的胳膊无力地垂在身侧。>$b$b杀了我吧，$c。$b$b<你快速翻检了一下她的随身物品，找到了她对你使用的毒药的解药。你急忙拿出监禁符文，将她送上卡德加的法师塔。>"
D.Strings[74602]="<使用监禁符文。>"
D.Strings[74603]="谢谢你，$r。我还以为会被一直关到死呢。"
D.Strings[74604]="基姆兹小姐，在失事前，我们看见了一个幸存者，我想那可能是你叔叔。"
D.Strings[74605]="克里希叔叔！？快让开，我要去救他！"
D.Strings[74606]="爸爸！爸爸！我们把你的工具带来了！"
D.Strings[74607]="我要让这些联盟杂种看看，什么才是真正的战士！"
D.Strings[74608]="是我父亲派你来的吗？"
D.Strings[74609]="啊啊！看来我应该留在酒馆里玩牌的。"
D.Strings[74610]="啊哈哈，不堪一击。"
D.Strings[74611]="是的，跟我来。"
D.Strings[74612]="坏……坏……坏主意……"
D.Strings[74613]="长官，敌人正在接近我们的要塞。我已经准备了一些你可能用得上的东西。"
D.Strings[74614]="各位，我有一个坏消息……我被击败了。"
D.Strings[74615]="我以为自己已经很适应寒冷了，可这已经超出兽人的忍受能力了。"
D.Strings[74616]="是时候让部落尝尝我的力量了！"
D.Strings[74617]="百发百中！！！"
D.Strings[74618]="哇——达里斯——醒醒。是我！"
D.Strings[74619]="踩扁一个！"
D.Strings[74620]="祝你好运，$r。我得去找个温暖的篝火烤一烤了！"
D.Strings[74621]="失败是不可容忍的，经过刻苦训练，我还会回来的。"
D.Strings[74622]="愤怒的巴赫拉出现了！"
D.Strings[74623]="我自由了！我不会再浪费时间了。"
D.Strings[74624]="祝你好运，$r。不要浪费时间！"
D.Strings[74625]="我的力量更胜于我的身高！"
D.Strings[74626]="帮我向武器大师霍林卡问好，小东西！"
D.Strings[74627]="或许我应该躲得远远地，只动嘴就行了。"
D.Strings[74628]="什么？！你们看了我的血没有！"
D.Strings[74629]="比起太阳和月亮的力量，部落不值一提。"
D.Strings[74630]="天呐。"
D.Strings[74631]="这些蕨叶看起来不太友好……"
D.Strings[74632]="现在，我该去哪儿处理我的战利品呢？！"
D.Strings[74633]="元素的力量在我体内流淌。"
D.Strings[74634]="这不过是小小的挫折，我还会回来的。"
D.Strings[74635]="完胜！"
D.Strings[74636]="小巧，机灵，随时能够战斗！"
D.Strings[74637]="为了诺莫瑞根……"
D.Strings[74638]="狩猎开始了！"
D.Strings[74639]="狩猎结束了……但这只是暂时的。"
D.Strings[74640]="如果帕泽普不能尽快回来，我就得派一个斥候去找我的斥候了。这对所有人来说都不是好事。"
D.Strings[74641]="暗影比以往更强大了……"
D.Strings[74642]="这还没完。"
D.Strings[74643]="我们已经牺牲了太多性命。这场战斗已经失控了。"
D.Strings[74644]="告诉艾萨克，我尽力了。"
D.Strings[74645]="你要找的东西一直就在这里！"
D.Strings[74646]="让我们并肩战斗吧！"
D.Strings[74647]="如果没有勇气，我们就无法取胜。"
D.Strings[74648]="我是不会沉寂太久的。"
D.Strings[74649]="你的实力已经得到了验证。"
D.Strings[74650]="啊，拜托！你一分钟前还能动呢！"
D.Strings[74651]="让我来试试你的力气和技巧。"
D.Strings[74652]="你的战斗意志将在我的眼前流失殆尽。"
D.Strings[74653]="该死的蠢货……噢！不小心夹到我自己了！"
D.Strings[74654]="这玩意儿需要好好修一下！"
D.Strings[74655]="希望你已经从迦罗娜带给你的创伤中恢复过来了。$b$b等你准备好之后，我们就要合力升级你的戒指了。"
D.Strings[74656]="如果你们敢来挑战我，我就在塔纳安丛林等着。这些大门之后，就是你们的葬身之地。"
D.Strings[74657]="不要害怕联盟，因为现在，恐惧就是你们的盟友。"
D.Strings[74658]="我只是被击败了，但还没有被打垮。"
D.Strings[74659]="我要一个一个干掉他们！"
D.Strings[74660]="这不是我期待的结局。"
D.Strings[74661]="疾病、死亡和失败降临到你们头上了，部落的渣滓！"
D.Strings[74662]="$g长官:女士;，我知道我并不是这里最聪明的人，可这似乎并不是什么好主意。你确定要这么做吗？"
D.Strings[74663]="那好吧！不说话就等于默认了。"
D.Strings[74664]="不！你休想阻止我！"
D.Strings[74665]="他们会……碾压……你的……"
D.Strings[74666]="别担心！效果很快就会消退的！"
D.Strings[74667]="放松点……好好休息一下。"
D.Strings[74668]="难以置信，我们居然成功了！"
D.Strings[74669]="<音乐盒在劈啪作响。>"
D.Strings[74670]="我很惊讶，你居然正中目标。上一次可没这么走运！"
D.Strings[74671]="完好无损，对吧？那可是个新的。"
D.Strings[74672]="哇！你从哪儿冒出来的？这玩意儿还没有连上呢。"
D.Strings[74673]="我、我、我的……新护目镜。接下来会是什么？飞行报警机器人？"
D.Strings[74674]="演奏“艾泽拉斯传奇”"
D.Strings[74675]="演奏“燃烧的远征”"
D.Strings[74676]="演奏“巫妖王之怒”"
D.Strings[74677]="演奏“毁灭”"
D.Strings[74678]="演奏“潘达利亚之心”"
D.Strings[74679]="演奏“倾世之战”"
D.Strings[74680]="演奏“暴风城”"
D.Strings[74681]="演奏“远洋”"
D.Strings[74682]="头儿，我不是个聪明人，可这棵树不太对劲。或许我们应该放过它？"
D.Strings[74683]="懂了！抱歉我蠢了！我是个蠢货！蠢货！蠢货！我这就砍倒它，头儿！"
D.Strings[74684]="剩下的部队去哪儿了？"
D.Strings[74685]="如果你遇见帕扎提克，请告诉他洛坎正在找他。"
D.Strings[74686]="钢铁部落是个坏兆头。我们得阻止它。"
D.Strings[74687]="跟我来，英雄！"
D.Strings[74688]="放弃吧，格罗玛什！看看周围，你失败了！"
D.Strings[74689]="很好，格罗玛什……我们会来找你的。"
D.Strings[74690]="祝贺你，英雄。我们胜利了。"
D.Strings[74691]="虚空在召唤你的灵魂！"
D.Strings[74692]="%s陷入狂暴状态，开始无差别地攻击盟友和敌人！"
D.Strings[74693]="鬣蜥人的牙齿是切割厚实护甲的利器。"
D.Strings[74694]="你好，指挥官，我很荣幸能见识到你的行动。"
D.Strings[74695]="我差点就把一袋神器碎片带回营地了，可一群部落把它们偷走了。你要随时注意身后，$n。"
D.Strings[74696]="搜一下他的身，看看有没有槌子。"
D.Strings[74697]="你是怎么上来的？哈里森·琼斯可没提过这次冒险会这么……危险。"
D.Strings[74698]="幸好没有人碰过我的……工作。我选择这个地方就是为了避开那些可能会干扰我……采集的家伙……"
D.Strings[74699]="你今天是想骑马还是咬人？"
D.Strings[74700]="元素在上……古加尔干了什么？"
D.Strings[74701]="抓紧了，$n！纳鲁正在转化成虚空之神……我们别无选择……只能起来战斗！"
D.Strings[74702]="奥金顿……暂时安全了。都散开，去找到塔隆戈尔和古尔丹。"
D.Strings[74703]="我们必须把这里发生的一切告诉伟大的元素之怒。快，跟我来！"
D.Strings[74704]="我感觉到一股凉风拂过肌肤，还有泥土和草叶的味道……这里肯定有通向外界的出口！"
D.Strings[74705]="纳鲁……这不可能！"
D.Strings[74706]="克乌雷正在转化为虚空之神……我们是阻止它毁灭这个世界的最后障碍了！"
D.Strings[74707]="失去克乌雷令我心痛不已……可现在没有时间悲伤了。我们必须找到出去的路。跟我来！"
D.Strings[74708]="很好，让我们进去吧！"
D.Strings[74709]="%s在呼唤它母亲的帮助。"
D.Strings[74710]="和我想的一样！前面不远处就有一个出口！"
D.Strings[74711]="%s激动地吱吱叫着飞走了。"
D.Strings[74712]="这场战斗还刚刚开始。不要放过一个钢铁部落的渣滓！"
D.Strings[74713]="指挥官，我们的双头飞龙骑兵削弱了那头玛戈隆，可我们也被拖在外面了。我们需要你帮忙攻入主建筑。"
D.Strings[74714]="欢迎，指挥官！我们今天的伟大发明就在工作台上等着你呢。"
D.Strings[74715]="跟我说说这些发明有什么用。"
D.Strings[74716]="稍等，$n，让我准备一下材料。"
D.Strings[74717]="你的骨头将被磨成肥料！"
D.Strings[74718]="让森林的力量消灭你！"
D.Strings[74719]="永恒的黑暗在等待着你！"
D.Strings[74720]="我是这片森林的守护者。去死吧！"
D.Strings[74721]="把它们放在我能看得见的地方，又高又大。"
D.Strings[74722]="你的滑翔机直接掉进了我的营地里！"
D.Strings[74723]="战斗结束了。我们将钢铁部落的大军赶回大门里去了。"
D.Strings[74724]="放下武器，格罗玛什！看看周围吧，你已经失败了。"
D.Strings[74725]="那你就等着吧，格罗玛什。我们会来找你的。"
D.Strings[74726]="谢谢你，英雄。今天，我们品尝到了甘美的胜利！Lok'tar ogar！"
D.Strings[74727]="升级完成了，我们有什么新发明吗？"
D.Strings[74728]="和我说说制造车辆的事。"
D.Strings[74729]="这座车间真是太棒了！每天，我们都会生产一种不同的发明供你试用。我们现有的图纸和设备可以制作四种发明。$B$B黏性手雷是一种可以黏在目标上的……手雷！只要等上一会儿，它就会爆炸，并造成严重的伤害！$B$B气压动力手套可以将敌人拉到你身边或者将他们推开，使用蒸汽和磁铁动力。它能依照你的战斗技能自动检测应该使用哪种功能。$B$B机械公鸡是根据我们在艾泽拉斯测试过的OOX技术制造而成的，这只机器鸟还可以开启狂暴模式，疯狂打击敌人！$B$B我们还将一架滑翔机和一架火箭捆绑制成了“空中霸王”级私人运输系统，可提供最棒的高爆单程飞行体验！"
D.Strings[74730]="很高兴听到你这么问！我们制造的七面翼型螺帽解锁了我们最杰出的发明！$B$B摩托车样机是我们生产的最快速的地面交通工具，还带有爆炸弹射座椅。$B$B如果你想再快一点，那么一定不能错过XD-57“标靶”跟踪导弹工具箱。它无法停止，不能减速，击中物体时还会爆炸！$B$B而哨卫炮台装配器，可以将你的敌人切割成均匀整齐的碎块。$B$BGG-117型微型火箭背包可以让你迅速从一个地方飞跃到另一个地方，并在着陆时造成大爆炸。你可以通过简单的跳跃激活该装置！$B$B最后，则是N.U.K.U.L.A.R.目标标定器。你只要指定一个地点，我们就会发射一支巨型火箭并造成大爆炸！"
D.Strings[74731]="我们最近刚刚建成了载具车间，可以让我们在车间里建造攻城武器了！$B$B只需要一点物资和一天的时间，我们就能制造出大功率的毁灭武器。$B$B攻城武器将受燃料消耗的限制，所以你一定盯紧那个仪表盘！"
D.Strings[74732]="我想让矮人来守卫要塞。"
D.Strings[74733]="铁炉堡的大军听候您的召唤，指挥官。"
D.Strings[74734]="侏儒别动队随时待命，指挥官！"
D.Strings[74735]="尽管下令吧，指挥官，德莱尼很愿意为维护和平出一份力。"
D.Strings[74736]="其他人以为他们能帮上忙，这真是太可笑了。只有强大而凶猛的狼人才能适应这片土地并保卫你的要塞。你不这么认为吗？"
D.Strings[74737]="愿意为您效劳，指挥官。"
D.Strings[74738]="我想让侏儒来守卫要塞。"
D.Strings[74739]="我想让德莱尼来守卫要塞。"
D.Strings[74740]="是的。我想让狼人来守卫要塞。"
D.Strings[74741]="我想让熊猫人来守卫要塞。"
D.Strings[74742]="这座城市已经安全了。"
D.Strings[74743]="卡拉波的人民一定会战胜失败。我们的人民绝不会屈服于野蛮的暴行。"
D.Strings[74744]="不仅为了自己，我们更要为我们的人民而坚强！"
D.Strings[74745]="不……你不能……这……我无法抗拒它！"
D.Strings[74746]="快跑！那些藤蔓！我们都被它们控制了！"
D.Strings[74747]="对了，火！火可以克制这些蔓生物。"
D.Strings[74748]="严寒应该能让它们枯萎吧？"
D.Strings[74749]="不！它们也会控制你的！"
D.Strings[74750]="你决不能再变成它们的宿主了！"
D.Strings[74751]="烧掉我的躯体吧，这是阻止它们的唯一方法。"
D.Strings[74752]="外来者！我要你的脑袋！"
D.Strings[74753]="别来烦我。只有熟悉附魔之道的人才能理解我的窘境。"
D.Strings[74754]="你想要什么，废物？"
D.Strings[74755]="我会在元素王座等你的。注意安全。"
D.Strings[74756]="出口就在前面！"
D.Strings[74757]="准备与影月氏族战斗。"
D.Strings[74758]="你帮不了我的，附魔师。让我继续研究吧。"
D.Strings[74759]="我会在元素王座等你回来的。"
D.Strings[74760]="我不能再等下去了。利爪之王必须归来。"
D.Strings[74761]="小心点，$c。"
D.Strings[74762]="我会把那个吓坏了的小女孩从木头下面弄出来的，$g长官:女士;。"
D.Strings[74763]="好像有个女人被卡在下面了，头儿！我们得帮帮她！"
D.Strings[74764]="这里有一种力量。我会得到它的。"
D.Strings[74765]="我能高兴能帮上忙，$c。"
D.Strings[74766]="显然，冰霜才是王道。放弃吧！"
D.Strings[74767]="检测到N.U.K.U.L.A.R.发射信号"
D.Strings[74768]="唔！救命！我被卡在木头下面了！"
D.Strings[74769]="啊，感谢你的帮忙，年轻人。这是我的一点谢意。"
D.Strings[74770]="如果你还想赚点钱，可以去你的要塞找点活儿干干。我得走了。如果你有需要，就去那里找我吧。"
D.Strings[74771]="他们的指挥官来了！"
D.Strings[74772]="我的身体好像被别人控制了。"
D.Strings[74773]="我在这儿干什么？我得找个安全的地方呆着！"
D.Strings[74774]="哇，我总算能控制住自己了！谢谢，朋友！"
D.Strings[74775]="渣滓！我要把你送回你应该呆的地方！"
D.Strings[74776]="这可能需要一点时间。"
D.Strings[74777]="%s听到的低语声越来越多，并随着秘密的力量增长变得越来越响。"
D.Strings[74778]="……你听到了吗？"
D.Strings[74779]="他的力量比我预计的要强得多。"
D.Strings[74780]="等到周末时，我应该就能回卡拉波了。"
D.Strings[74781]="你能来真是太好了，这里的麻烦已经超出我的处理能力了。"
D.Strings[74782]="法术已经被解除了。我们的水晶再次散发出了充沛的能量。"
D.Strings[74783]="再也没有比乘坐老红色火箭更棒的事了！"
D.Strings[74784]="我会试着解除莫卡的法术。"
D.Strings[74785]="我很好奇，克里斯·克拉奇是怎么处理大家交给他的那些巨魔的脚的。"
D.Strings[74786]="你在石板上发现的那些咒语能为你的戒指灌注巨大的力量。准备好了吗？"
D.Strings[74787]="我很高兴能摆脱那个狭窄的笼子。等找到剩下的补给品，我就回村子里去。"
D.Strings[74788]="发现信号弹！有盟友正在求援。具体位置已被标记在你的地图上！"
D.Strings[74789]="发现信号弹！我们的士兵需要你的帮助。具体位置已被标记在你的地图上！"
D.Strings[74790]="嘿，小心那把剑！"
D.Strings[74791]="一个嘲颅兽人在这里做出了可怕的暴行。我们得在他们回来之前尽快完成任务。$b$b这个家伙特别残暴……"
D.Strings[74792]="这些刃牙虎人在摆弄他们根本不理解的魔法！他们一定会激怒玛戈隆的。"
D.Strings[74793]="我们有些什么？"
D.Strings[74794]="这个多少钱？"
D.Strings[74795]="真有意思！"
D.Strings[74796]="但愿这能起作用……"
D.Strings[74797]="空气中有一股寒意……"
D.Strings[74798]="那肯定是影月氏族。敲响警钟！"
D.Strings[74799]="拿起武器！各就各位！影月氏族来找麻烦了。"
D.Strings[74800]="别害怕，兄弟姐妹们。我们已经跟兽人战斗了几十年了。"
D.Strings[74801]="你感觉到那股寒意了吗？好像有东西踏上了你的坟墓……"
D.Strings[74802]="迦罗娜是个危险的刺客。我们必须保持警惕。你准备好就告诉我一声吧！"
D.Strings[74803]="那只是一次测试。"
D.Strings[74804]="我准备好了。让我们解开对迦罗娜的控制吧！"
D.Strings[74805]="振作起来。黎明之前总是最黑暗的时刻。"
D.Strings[74806]="它在这儿。冲锋！为了联盟！"
D.Strings[74807]="中士，死者在我们的要塞外面徘徊。"
D.Strings[74808]="%s查看了交货清单。"
D.Strings[74809]="在交货清单上写些什么。"
D.Strings[74810]="在离开生者的国度前，影月幽灵们向你表达了谢意。"
D.Strings[74811]="折币先生，\n\n我方已经安排好你的报酬，但为免货物被当地兽人没收，我不得不将它留在了远离岸边的地方。\n\n为了帮助你找到它，我放出了一些浮标。祝你好运，伙计。\n\n此致，\n加兹瑞克斯·轮锁"
D.Strings[74812]="你还有很长的路要走。跟着浮标，你就能找到它。\n\n- 加兹瑞克斯"
D.Strings[74813]="你就快到了。我相信你现在已经看到最后一个浮标了，老朋友。\n\n- 加兹瑞克斯"
D.Strings[74814]="噢，我没跟你说过报酬是在海底吗？这样你下次试图欺骗财阀时，或许就会三思而行了。\n\n不过只要你一直往下潜就行了。我相信你会找到它的，朋友。\n\n- 加兹瑞克斯·轮锁"
D.Strings[74815]="这些骨头好大啊！我敢打赌，它们肯定属于一头食人魔……或许是一头巨型食人魔！"
D.Strings[74816]="今天天气真不错，指挥官。"
D.Strings[74817]="这里的一切都生长良好。"
D.Strings[74818]="这些植物看起来都很棒，不是吗？"
D.Strings[74819]="我想挑选一下下次种植的草药。"
D.Strings[74820]="好的，指挥官，我目前是随机种植草药的。你想让我改种指定的草药吗？"
D.Strings[74821]="寒霜草。"
D.Strings[74822]="炎火草。"
D.Strings[74823]="戈尔隆德捕蝇草。"
D.Strings[74824]="塔拉多幽兰。"
D.Strings[74825]="纳格兰箭叶花。"
D.Strings[74826]="烁星花。"
D.Strings[74827]="让我们随便种点什么吧。"
D.Strings[74828]="好的，指挥官，我目前种的是寒霜草。你想让我改种指定的草药吗？"
D.Strings[74829]="好的，指挥官，我目前种的是炎火草。你想让我改种指定的草药吗？"
D.Strings[74830]="好的，指挥官，我目前种的是烁星花。你想让我改种指定的草药吗？"
D.Strings[74831]="好的，指挥官，我目前种的是塔拉多幽兰。你想让我改种指定的草药吗？"
D.Strings[74832]="好的，指挥官，我目前种的是戈尔隆德捕蝇草。你想让我改种指定的草药吗？"
D.Strings[74833]="好了，指挥官。你可以坐钻探机返回岗哨了。"
D.Strings[74834]="好的，指挥官，我目前种的是纳格兰箭叶花。你想让我改种指定的草药吗？"
D.Strings[74835]="指挥官，尽管使用钻探机返回岗哨吧。它能把你送到目的地的……大概能。"
D.Strings[74836]="太好了，现在来办正事吧！"
D.Strings[74837]="你觉得它们是怎么跑到这里来的？会不会是有人把它们埋进沙子里的？"
D.Strings[74838]="不对，笨蛋！是有什么东西死了，然后变成了骨头！"
D.Strings[74839]="是的，探索这个地方相当有趣。但你去过永恒岛吗？那才是完美的探险之地！"
D.Strings[74840]="我想我把钥匙留在海军上将泰勒的保险箱里了。我只记得不久之前还拿着它的，可现在什么都记不清了……"
D.Strings[74841]="或许你可以试着重现一下当时的行动？"
D.Strings[74842]="我最后的记忆是，我正在附近的某棵树下看书。但我记不清究竟是哪儿了。\n\n我好像记起了一些大石头……上面还画了一个骷髅头……就这些了。"
D.Strings[74843]="我差点死在那里，$n。我们这些活着回来的人都是受到祝福的。"
D.Strings[74844]="那是什么东西？看起来像石雕的人像。"
D.Strings[74845]="什么！你是谁？！你怎么跑到这边来的？"
D.Strings[74846]="%s吸了一口气，有些晕眩。"
D.Strings[74847]="一瓶药剂？还有一种强大的……"
D.Strings[74848]="今晚，我就要戴上你的脸做成的面具！"
D.Strings[74849]="为了碎手氏族！"
D.Strings[74850]="要想拥有美丽的花园，你只需要一点爱心和细心。"
D.Strings[74851]="你能帮我将这些德拉诺种子种成草药吗？"
D.Strings[74852]="德拉诺的各个草药点都能收集到德拉诺种子。等你手里的种子超过5个之后再来找我吧，我可以帮你把它们种成草药。"
D.Strings[74853]="你！或许还来得及。这个岗哨顶层的传送门可以通往我们的世界——暴风城！那头原祖荆兽……"
D.Strings[74854]="如果让那头野兽过去了，它无节制的生长会吞噬整个艾泽拉斯！快！"
D.Strings[74855]="看看我的马，它是不是很威风？我那边的搭档连马都没有。转头看看他们吧，再回头来看看我。我还在马上！你是不是很惊讶？还有，看看我的帽子，多拉风！"
D.Strings[74856]="我的下一个宠物可没这么好对付了！"
D.Strings[74857]="小猴子和战争一样，都是不择手段的！"
D.Strings[74858]="什么？怎么可能？？我会报仇的，你这个胡言乱语的臭猪肝！"
D.Strings[74859]="又一场毫无悬念的史诗大战，由我倾力奉献！"
D.Strings[74860]="准备接受终生难忘的沉重打击吧！"
D.Strings[74861]="啊，算你走运，这次我没留神！"
D.Strings[74862]="我得赶去泰罗克鸦巢。时间有限，我们有很多准备工作要做。"
D.Strings[74863]="下面都是我们的人民。愿圣光让他们安息。"
D.Strings[74864]="爸爸说如果你再不从船上下来，那你就有麻烦了！"
D.Strings[74865]="我还没扮够船长呢！等我玩够了，我会回去的。"
D.Strings[74866]="我要告诉爸爸去！"
D.Strings[74867]="即使像我这么强大的法师，也一样分身乏术。"
D.Strings[74868]="可你，指挥官，你是我最大的依仗。在你的盟友们超高的本领和你要塞的强大实力面前，任何堡垒都不堪一击。"
D.Strings[74869]="在你的领导下，联盟远征军将全力对抗钢铁部落。"
D.Strings[74870]="在你的领导下，部落最伟大的战士将全力对抗格罗玛什和他的大军。"
D.Strings[74871]="而我将集中精力对付艾泽拉斯最大的威胁："
D.Strings[74872]="古尔丹，那个黑暗的化身。"
D.Strings[74873]="古尔丹是我这辈子遇到过的最狡诈、最残忍的敌人。我应该对他的逃跑负责。"
D.Strings[74874]="我们必须找到并消灭古尔丹，以及他那还处在萌芽状态的暗影议会。"
D.Strings[74875]="有了你的帮助，我就能找到他。我需要你帮我一个大忙。这个任务可能已经逼近了你的能力极限。"
D.Strings[74876]="但我也会尽力帮助你。我们会一起为你制作一件拥有传奇力量的神器。"
D.Strings[74877]="有了用德拉诺的太阳之心熔铸而成的核心，我们将在这枚戒指的基础上创造一个奇迹。"
D.Strings[74878]="……好了！完成了。现在，去找古尔丹吧。"
D.Strings[74879]="跟我来，指挥官！"
D.Strings[74880]="一旦我们发现古尔丹的下落，就必须尽快行动……"
D.Strings[74881]="让我睁开双眼：Van shalach, om aeschis, khaz'tolim！"
D.Strings[74882]="来，来吧……你在哪儿……"
D.Strings[74883]="等等——这里——什么……？"
D.Strings[74884]="小心！他正在反制我的法术。"
D.Strings[74885]="勇士，塔隆戈尔的死肯定给了他当头一棒。这很好。但现在，他已经知道我们在找他了。"
D.Strings[74886]="我们需要……更多的力量！"
D.Strings[74887]="你来得正是时候！"
D.Strings[74888]="我们会从空中跟着你的！"
D.Strings[74889]="这些踪迹并不容易追踪。先往东边走吧。"
D.Strings[74890]="跟着这种时空异常的痕迹走。"
D.Strings[74891]="就是这里！看来加尔鲁什在抵达德拉诺之后就往这边走了。可凯诺兹呢？"
D.Strings[74892]="你们看加尔鲁什。他的双手被绑着。但他只有一个人。他什么时候和凯诺兹分开的？"
D.Strings[74893]="唔……那个食人魔不应该出现在这里。这座山上肯定发生了什么诡异的事。"
D.Strings[74894]="那是伪装后的凯诺兹。加尔鲁什杀了他！可尸体去哪儿了？"
D.Strings[74895]="就要水落石出了！"
D.Strings[74896]="很好：我来吸引凯诺兹的注意力，你来发动攻击。"
D.Strings[74897]="如果有人受了重伤，我能让你的伤口复原。"
D.Strings[74898]="很好！我来吸引凯诺兹的注意力，克罗米来发动攻击。"
D.Strings[74899]="你要尽力保住我们俩的命！"
D.Strings[74900]="好主意。你来吸引凯诺兹的注意力，我来攻击。"
D.Strings[74901]="血槌……$B$B不管你听说过多少有关那个可怕地方的传闻，你都完全不了解它！我是绝对不会再回去的。"
D.Strings[74902]="我已经自由了，我也要想办法帮其他人逃出血槌的魔掌。我们决不能丢下我们的兄弟姐妹！"
D.Strings[74903]="你不再是酋长了，地狱咆哮。你的自由是我给的。你的性命也是我给的。你能找到你父亲，并集结起古老的兽人氏族也是靠的我！"
D.Strings[74904]="他以为自己还在和加尔鲁什战斗。"
D.Strings[74905]="凯诺兹！你想要什么？你需要一支军队做什么？"
D.Strings[74906]="不是一支……我要无穷无尽的大军……能够横扫诸世界的大军……"
D.Strings[74907]="我将永生！"
D.Strings[74908]="啊啊啊——地狱咆哮——没有了我——谁来帮——"
D.Strings[74909]="我抓住他了……"
D.Strings[74910]="离他远点！"
D.Strings[74911]="住手——克罗米，送我们回去吧！"
D.Strings[74912]="不——这样不行——克罗米——！"
D.Strings[74913]="呃！不——让我来停止这一切！"
D.Strings[74914]="……我搞定了。"
D.Strings[74915]="……我们得再试一次。"
D.Strings[74916]="……没问题。我们有的是时间。"
D.Strings[74917]="胜利！勇士，你成功了！"
D.Strings[74918]="好多人死在了矿井里……$B$B我惊险地逃了出来，可还有许多人被奴役着。"
D.Strings[74919]="凯诺兹创造了这个世界。我们将用他的力量找到这里的古尔丹。"
D.Strings[74920]="晚安，迷失在时间流里的王子。"
D.Strings[74921]="对于那些救我的人，我永远还不清他们的恩情。"
D.Strings[74922]="那些食人魔把我们当做微不足道的尘土。他们奴役我们的人民，强迫他们劳动，并为了找乐子肆意杀害他们。"
D.Strings[74923]="我现在知道该怎么击败古尔丹的魔法并找出暗影议会了。但我们需要更多的能量。"
D.Strings[74924]="那座矿井是个不堪回首的地方。"
D.Strings[74925]="我们得去食人魔帝国的核心地带夺取神器。"
D.Strings[74926]="我可以帮你。让我们强化你那枚戒指的力量吧……"
D.Strings[74927]="伸出你的手，走进这片光芒里去吧！"
D.Strings[74928]="我很抱歉，我忘了告诉你这会让你……不省人事。"
D.Strings[74929]="不要放松警惕，我的朋友。这个时代的食人魔不全是无脑的莽夫。他们中有一些人聪明得可怕。"
D.Strings[74930]="一直以来，巫师之王都是一个可怕的存在。战胜他可不是什么小功绩。"
D.Strings[74931]="太好了……我们需要的东西已经齐了！"
D.Strings[74932]="这次，古尔丹再也没办法逃过我的眼睛了。"
D.Strings[74933]="大法师，小心点。"
D.Strings[74934]="矿井里非常闷热。高温侵蚀了里面的一切。我完全没有动的力气，可我还得一天天不间断地干活。$B$B我从没想过还能获得新生。那真是不堪回首……"
D.Strings[74935]="矿井里非常闷热。高温侵蚀了里面的一切。我完全没有动的力气，可我还得一天天不间断地干活。"
D.Strings[74936]="我们一定要把他关进监狱！"
D.Strings[74937]="让我睁开双眼：Val'mir, khar abra, mal ozymius……"
D.Strings[74938]="来吧，来吧，来吧……我会找到你的……"
D.Strings[74939]="……那里！古尔丹！他在——"
D.Strings[74940]="是你！塔纳安的那个人类法师……"
D.Strings[74941]="我找到你了！"
D.Strings[74942]="我打听过你，“卡德加”。我们之间似乎有些故事。"
D.Strings[74943]="那你也应该明白自己的下场。投降吧。"
D.Strings[74944]="你那笨拙的魔法是把双刃剑。我也同样找到了你。"
D.Strings[74945]="大法师，小——"
D.Strings[74946]="愚蠢的法师。你就在折磨中慢慢等死吧。我真想过去亲眼欣赏一下。"
D.Strings[74947]="勇士——大法师！"
D.Strings[74948]="我会留下来陪着大法师并寻求援助。快！抓住迦罗娜！"
D.Strings[74949]="你很勇敢，居然敢孤身一人来追我……"
D.Strings[74950]="出来吧，“英雄”。让我好好看看你。"
D.Strings[74951]="跟踪我？你很厉害，也很狡猾。我就喜欢出色的猎人。"
D.Strings[74952]="足迹消失了！她去哪儿了呢……？"
D.Strings[74953]="毒素就像火一样烧灼着你的血管，对吧？别担心——很快就会结束了！"
D.Strings[74954]="还能站着？你还真顽强！"
D.Strings[74955]="你最好快点杀了我。你没多少时间了。"
D.Strings[74956]="你太迟了。现在，没人能救得了你的大法师了。"
D.Strings[74957]="古尔丹总能得到他想要的。我的生死无关紧要。"
D.Strings[74958]="不死鸟大挑战该怎么玩？"
D.Strings[74959]="谢谢你，勇士！我们及时找到了谋杀的凶器。"
D.Strings[74960]="别动，卡德加。迦罗娜的匕首上附加了魔法。"
D.Strings[74961]="伤口很严重。你应该去看看牧师。"
D.Strings[74962]="我自由了，可其他人还被关着。当时机来临时，我将为我的兄弟姐妹们复仇。$B$B血槌食人魔绝对想不到自己会是什么下场。"
D.Strings[74963]="血槌食人魔非常残酷。他们总是肆无忌惮地压榨我们的劳动力。"
D.Strings[74964]="多年来，我一直被血槌食人魔囚禁在矿井里，可现在一切都结束了。"
D.Strings[74965]="不——不用找牧师。科达娜，帮我缝好伤口。"
D.Strings[74966]="我准备起飞了！|cFF0008E8（暗月游戏代币）|r"
D.Strings[74967]="我看到你已经跟部落合作了。"
D.Strings[74968]="我们正身处远离艾泽拉斯纷争的世界。我需要一切可能的帮助。"
D.Strings[74969]="六人议会的其他成员不希望让部落插手肯瑞托的事务。"
D.Strings[74970]="这不是我第一次反对议会了，也不会是最后一次。"
D.Strings[74971]="顽固的老家伙！"
D.Strings[74972]="谢谢你，指挥官。你是联盟的表率。"
D.Strings[74973]="是我找到了最优秀的合作者。"
D.Strings[74974]="我听说你也在跟部落合作。六人议会的其他成员不会同意的，我也是。"
D.Strings[74975]="继续保护好我们的大法师，指挥官。没有他，我们就完了。"
D.Strings[74976]="来吧，这边走。我只是有点疼——好吧，是非常疼。"
D.Strings[74977]="这原本只属于巫师之王的力量，现在我将它交到你的手中。"
D.Strings[74978]="你这是在玩火，大法师。"
D.Strings[74979]="我们的朋友需要它们。最艰苦的考验还在后面。"
D.Strings[74980]="欢迎！我们特别准备了这种“不死鸟”级烟火，它可以绑在你的背上，让你在天空翱翔，追寻戒指和荣耀！"
D.Strings[74981]="只要一个游戏代币，我就可以把我们最新的“不死鸟”级烟火绑在你的背上。你将被发射到高空，长出烈焰的翅膀！$B$B接下来就是最困难的地方：你只有10秒的飞行时间，同时会有一些火圈分散出现在马戏团各处。你每穿过一个火圈，你的总分就会增加一点。最重要的是，它能让你再飞行10秒。$B$B只要穿过15个火圈，奖品就归你了！但如果你没能穿过足够的火圈，就得再交出一个游戏代币！"
D.Strings[74982]="今天真是个钓鱼的好日子！现在我们顿顿都能吃鱼了！"
D.Strings[74983]="嘿，你看起来像是个喜欢在背上绑一捆烟火的家伙！"
D.Strings[74984]="不死鸟大挑战，带你翱翔天际！"
D.Strings[74985]="大奖在等着你呢，只有一箭支遥！"
D.Strings[74986]="我看见的是星星吗？不，那只是不死鸟大挑战的又一个挑战者！"
D.Strings[74987]="我不像我丈夫那么热衷于钓鱼，但能获得足够的食物还是让我很开心。"
D.Strings[74988]="我会继续关注你的。"
D.Strings[74989]="祝你好运，勇士。在那个铸造厂里要小心一点！"
D.Strings[74990]="现在，站着别动。"
D.Strings[74991]="这个魔法非常可靠，而且——可能有点致命。我说了，别动！"
D.Strings[74992]="我要从德拉诺之心抽取力量了……"
D.Strings[74993]="来吧，格罗玛什。喝吧。"
D.Strings[74994]="我说了——滚开！"
D.Strings[74995]="他们突袭了你的铸造厂。他们杀害了你的盟友。我才是你唯一的出路。"
D.Strings[74996]="送我去宾奇维斯零件工厂。"
D.Strings[74997]="它起作用了。"
D.Strings[74998]="我专门为这种紧急情况准备了一对地精起搏器。你还好吗，指挥官？"
D.Strings[74999]="这么说，铸造厂已经完了！你把钢铁部落都打跑了，指挥官。"
D.Strings[75000]="跟我来。不好好打上一场，古尔丹是不会放弃控制他的宠物的。"
D.Strings[75001]="杀了我，了结这一切吧，大法师。"
D.Strings[75002]="我不是来杀你的，刺客。"
D.Strings[75003]="%s痛苦地摇晃着。"
D.Strings[75004]="你的主子在哪儿？告诉我！"
D.Strings[75005]="你……会下……地狱的……"
D.Strings[75006]="还是你先去吧。古尔丹在哪儿！？"
D.Strings[75007]="啊……他……会把你千刀万剐……"
D.Strings[75008]="他到底躲在哪儿？"
D.Strings[75009]="大法师……"
D.Strings[75010]="告诉我！"
D.Strings[75011]="%s抓着自己的头。"
D.Strings[75012]="卡德加，住手！这和严刑拷打有什么两样？"
D.Strings[75013]="可她知道……"
D.Strings[75014]="我甚至都不知道你是在为什么而战了。"
D.Strings[75015]="你——你说的对。古尔丹已经给她洗脑了。"
D.Strings[75016]="我很抱歉，迦罗娜。我们得另想办法了。"
D.Strings[75017]="这张纸条似乎是从箱子上掉下来的。上面写着：\n\n“警告。内装极度危险且无法预料的物品。请勿破坏或损伤船运集装箱。”"
D.Strings[75018]="我想加入萨格雷。"
D.Strings[75019]="我要偷走附属声明！"
D.Strings[75020]="不……穆戈尔……不会死的……"
D.Strings[75021]="穆戈尔是不会死的！！！"
D.Strings[75022]="呃……唔……"
D.Strings[75023]="呵……呵呵……哈……"
D.Strings[75024]="呐呐呐呐呐……哈哈……"
D.Strings[75025]="阡陌……道路……呵呵……"
D.Strings[75026]="呼……哈……"
D.Strings[75027]="秘密的探寻者——不！不、不、不……"
D.Strings[75028]="我看见了！"
D.Strings[75029]="大门……你看见了吗？我……"
D.Strings[75030]="看看这个地方。木精都是怪物。$b$b我想我开始明白嘲颅兽人为什么会如此暴虐了。"
D.Strings[75031]="我们后会有期！呵呵呵……"
D.Strings[75032]="大主教玛拉达尔已经向所有愿意参战的人开放了他的武器店。"
D.Strings[75033]="哦，太好了，你回来了！你在那儿还好吧？"
D.Strings[75034]="卡兹！卡兹！卡兹！这不带面具的家伙带我经历了一场大冒险！我们看见了被感染的兽人，一头绿色的独眼魔，我们还把一切都点着了！"
D.Strings[75035]="你抽到了愤怒！"
D.Strings[75036]="你抽到了毁灭！"
D.Strings[75037]="你抽到了灵巧！"
D.Strings[75038]="你抽到了脆弱！"
D.Strings[75039]="你抽到了易伤！"
D.Strings[75040]="你抽到了迅捷！"
D.Strings[75041]="你抽到了虚空！"
D.Strings[75042]="你抽到了兽群！"
D.Strings[75043]="你抽到了迁跃！"
D.Strings[75044]="你抽到了野人！"
D.Strings[75045]="我在阴影中蛰伏多年。我不能再躲下去了。"
D.Strings[75046]="你准备好与塞泰战斗了吗，$r？"
D.Strings[75047]="我准备好了，安苏，我们不会输的。"
D.Strings[75048]="你准备好加入安苏与塞泰的战斗了吗？"
D.Strings[75049]="保护我，$n！塞泰的血会对所有穿过它的人造成伤害。"
D.Strings[75050]="帮帮我，$n！我的生命力正在流失！"
D.Strings[75051]="我将遮蔽天空，万物都将陨落！"
D.Strings[75052]="结束了。到蕾希之眠来找我吧。"
D.Strings[75053]="我们会尽快召集救援小队的。你最后一次见到他是在哪里？"
D.Strings[75054]="<幽灵狼并没有发现你的存在，依然空洞地盯着附近一座粗糙的坟墓。>"
D.Strings[75055]="（野兽控制）弯下腰，挠一挠狼的耳朵。"
D.Strings[75056]="嘿，伙计！很高兴能在这儿见到联盟的$g小伙子:小丫头;！\n\n我敢打赌，有了你的帮助，我的工作一定能取得进展。"
D.Strings[75057]="如果她正在找“高格里克之心”，那我们必须抢在她前头找到它。一旦收到更多消息，我会立即通知你的。"
D.Strings[75058]="指挥官，这将是一场持久战。等到下周，我应该就能向你提供更多情报了。"
D.Strings[75059]="如果她和钢铁部落正在找“高格里克之心”，那我们必须抢先找到它。一旦收到更多消息，我会立即通知你的。"
D.Strings[75060]="你是从部落来的，是吧？$b$b我不知道基姆兹会跟你们合作，但考虑到局势，我愿意接受一切可能的帮助。"
D.Strings[75061]="啊啊啊！！！！"
D.Strings[75062]="不是只有我们才会抓俘虏的，$n。$B$B在部落的营地里同样有监狱，它就在大门左边的急救站下面。$B$B如果我们能在阿什兰找到那些战争之矛监狱钥匙，就可以把那些囚犯放出来了。"
D.Strings[75063]="你……听到什么声音没有？"
D.Strings[75064]="萨格雷可不蠢。他们一直在盯着我。$B$B但知道自己的努力没有白费，我还是很高兴的。"
D.Strings[75065]="你逃不掉的。"
D.Strings[75066]="你们的灵魂归我了。"
D.Strings[75067]="逃吧，逃离你们的主人！"
D.Strings[75068]="凡人的躯壳真是脆弱。"
D.Strings[75069]="又吞噬了一条灵魂。"
D.Strings[75070]="你们这些蛆虫，只配涌向垂死神祇的尸体。"
D.Strings[75071]="对……靠近点……你们的灵魂强大而骄傲，你们的恐惧足够我享用几天了！"
D.Strings[75072]="看来他们就快明白死亡的意义了。你说我们要不要多告诉他们一点？"
D.Strings[75073]="不，我们应该让他们自己去发现体会。就像我们自己懂得生命轮回的真意时一样，他们同样需要经历这一切。"
D.Strings[75074]="啊，我还以为自己再也出不来了呢！干得好！"
D.Strings[75075]="只要一有机会，我就会带着我的塔布羊去海滩上放松。他非常喜欢看船上的那些渔夫。"
D.Strings[75076]="爸爸，哥哥不肯从船上下来。我都跟他说了，他就是不肯听我的！"
D.Strings[75077]="没关系，甜心。那你妈妈炖的汤就全归我们了！"
D.Strings[75078]="%s开始对同时|cFFFF0404|Hspell:171061|h[浸水]|h|r和|cFFFF0404|Hspell:171065|h[着火了！]|h|r的目标施放|cFFFF0404|Hspell:171078|h[蒸汽反应]|h|r！"
D.Strings[75079]="现在，他大概已经学会不要错过饭点了。"
D.Strings[75080]="你，藏卷人。你并不是那些鸦语者。你站在我面前做什么？"
D.Strings[75081]="伟大的卡鲁，那些关于您如何威严的传说与现实相比真是太苍白无力了。"
D.Strings[75082]="你在讨好我，但却显得心事重重——有话直说吧，孩子。"
D.Strings[75083]="鲁克玛的信徒拥有强大的力量。他们会用它烧死我们的，包括您的鸦群。"
D.Strings[75084]="他们也征服了我的子孙，迫使他们厮杀至死。你想让我们怎么做？"
D.Strings[75085]="伟大的鸦母，以安苏之名，我们谦卑地请求您将您的双翼借给我们。"
D.Strings[75086]="有了您的帮助，我们就能熄灭烧灼天空的光。"
D.Strings[75087]="安苏就喜欢插手凡人的事务。别人肯定以为我会从他的错误中吸取教训。"
D.Strings[75088]="很好，藏卷人。我的鸦群归你了。"
D.Strings[75089]="我是来找我爸爸的工具的，却被这些野人给抓住了！他还等着这些工具开工呢……"
D.Strings[75090]="珀西，你留在这里守着鸦巢。"
D.Strings[75091]="我们必须占领这个平台，帮我们的部队扭转战局！"
D.Strings[75092]="你战斗起来真像个传奇英雄！来吧，让我们返回天空吧。"
D.Strings[75093]="我们得夺取那些校控器。"
D.Strings[75094]="鸦语者已经在等候你的命令了。"
D.Strings[75095]="糟了，他们快死了！快帮他们清出一条道路！"
D.Strings[75096]="援军！杀光他们！"
D.Strings[75097]="看来所有人都到位了。卡鲁，发出信号吧，带我们离开这儿！"
D.Strings[75098]="如果你不喜欢它，就在推特上@我吧。"
D.Strings[75099]="如果你喜欢它，就在推特上@我吧。"
D.Strings[75100]="如果你发现了bug，就在推特上@我吧！"
D.Strings[75101]="这棵！砍倒它！"
D.Strings[75102]="看来我那卑鄙的兄弟还活着……他还派了一个刺客来！"
D.Strings[75103]="杜纳！我的儿子……我还以为你死了呢。"
D.Strings[75104]="侍从们，攻击！！！"
D.Strings[75105]="你能帮我到附近抓点鱼回来吗？"
D.Strings[75106]="补给能够决定一支大军的生死。"
D.Strings[75107]="你觉得你今天能捕到多少鱼？"
D.Strings[75108]="我感觉今天很走运，应该能捕到相当于昨天两倍的鱼。"
D.Strings[75109]="所以你觉得今天能捕到两条鱼？"
D.Strings[75110]="昨天那条鱼可大了！比你抓到的那些小鱼大多了……"
D.Strings[75111]="我只是用错了鱼饵！今天我带来了正确的鱼饵。"
D.Strings[75112]="我们要清除狩猎场里的这些钢铁部落渣滓！"
D.Strings[75113]="这是我的盟友之一。"
D.Strings[75114]="它完全能运转了！请别在意那些浓烟……"
D.Strings[75115]="我的幽灵药水最适合用来溜过部落的守卫，甚至潜入他们的主基地！你试过没有，$n？"
D.Strings[75116]="有人刚给我看了他们在阿什兰东边发现的一个薯块。$B$B它们的效果都能和我的治疗药水媲美了！"
D.Strings[75117]="你是来看望伤员的吗，$n？"
D.Strings[75118]="每天都有越来越多的伤员涌入这座急救站。听我一句劝，带个治疗者一起去完成任务吧。"
D.Strings[75119]="治疗者完全被低估了，$n。如果更多人愿意带上我们一起去执行任务，那我的急救站就不会有这么多伤员了。"
D.Strings[75120]="你看见菲兹尔了吗？我哪儿都没看见他。"
D.Strings[75121]="今天真是大丰收！"
D.Strings[75122]="哇！看看那条鱼的个头！"
D.Strings[75123]="好大的鱼。"
D.Strings[75124]="看到没有？"
D.Strings[75125]="大丰收！"
D.Strings[75126]="呼噜。"
D.Strings[75127]="我们一定会揭开埃匹希斯的秘密的！"
D.Strings[75128]="姐妹……"
D.Strings[75129]="烧死……你……"
D.Strings[75130]="你竟敢挑战鲁克玛的意志！"
D.Strings[75131]="小心那些血清，我还无法确定它们究竟有什么效果。"
D.Strings[75132]="不用担心，我总会让这玩意儿飞起来的。"
D.Strings[75133]="你们这些地面的居民应该搞清楚自己的身份！"
D.Strings[75134]="低贱的……渣滓……"
D.Strings[75135]="一名影月召亡者开始召唤亡者。"
D.Strings[75136]="快挖，你们这些蛆虫！"
D.Strings[75137]="很荣幸能与你并肩作战！"
D.Strings[75138]="你打得不错！"
D.Strings[75139]="有你帮我们，他们赢不了！"
D.Strings[75140]="想要挖点矿石吗？"
D.Strings[75141]="鲜血、喜悦和泪水。这是一个坚强的矿工必须经历的东西。\n\n你能胜任这个任务吗？"
D.Strings[75142]="你从没想过自己会成为矿工吧？"
D.Strings[75143]="你能帮我这把这块德拉诺岩石提炼成矿石吗？"
D.Strings[75144]="德拉诺的各个采矿点都能挖到德拉诺岩石。等你手里的岩石超过5个之后再来找我吧，我可以帮你把它们提炼成矿石。"
D.Strings[75145]="好好照料你的药圃，它也会好好回报你的。"
D.Strings[75146]="日安，指挥官。还是说现在已经是晚上了？这个该死的地方，连白天黑夜都分不清楚。"
D.Strings[75147]="向你致敬，指挥官$n，你是联盟的英雄！"
D.Strings[75148]="你是这个黑暗之地的明灯，指挥官。"
D.Strings[75149]="指挥官！德拉诺从来不会让人觉得无聊，对吧？"
D.Strings[75150]="胜利或死亡，指挥官！但如果有可能的话，我还是喜欢前者。"
D.Strings[75151]="让那些钢铁杂种看看真正的部落是什么样的吧，指挥官！"
D.Strings[75152]="力量与荣耀！"
D.Strings[75153]="为了沃金酋长和指挥官$n！"
D.Strings[75154]="你为部落带来了荣耀，指挥官！"
D.Strings[75155]="向你致敬，指挥官$n，你是部落的骄傲！"
D.Strings[75156]="今晚，我们为你举办庆功宴，指挥官！"
D.Strings[75157]="能为您效劳是我的荣幸。"
D.Strings[75158]="要塞很安全。"
D.Strings[75159]="那道疤是新的吧，指挥官？你现在一共有多少疤了？"
D.Strings[75160]="各位，注意了！指挥官来了！"
D.Strings[75161]="指挥官！"
D.Strings[75162]="只要看你一眼，我们敌人就会像狗一样落荒而逃！"
D.Strings[75163]="我在空气中闻到了战争的味道，指挥官。"
D.Strings[75164]="能与你并肩作战是我的荣幸！"
D.Strings[75165]="需要我去杀敌吗？"
D.Strings[75166]="指挥官，战斗进行得怎么样了？"
D.Strings[75167]="快下令吧，我保证完成任务。"
D.Strings[75168]="我们会奋勇作战的。"
D.Strings[75169]="我遇见了一位活的传奇。"
D.Strings[75170]="团结一致！"
D.Strings[75171]="人们会谱写歌谣，赞颂这场战役的。"
D.Strings[75172]="你会是一个很不错的战利品。"
D.Strings[75173]="我能从决战奥格瑞玛一役中活下来，这不算什么。"
D.Strings[75174]="那家伙身上有战利品！快去抢啊！"
D.Strings[75175]="噢，太好了，我正觉得无聊呢。"
D.Strings[75176]="尽管跑吧。"
D.Strings[75177]="又有敌人过来了。小心背后！"
D.Strings[75178]="这不算什么问题。"
D.Strings[75179]="我开始喜欢这座要塞了。你休想得到它。"
D.Strings[75180]="他们进攻了！这对他们真是太不幸了。"
D.Strings[75181]="有人要倒大霉了。"
D.Strings[75182]="别得意！"
D.Strings[75183]="今天就是你的末日。别让自己输得太难看了。"
D.Strings[75184]="等战斗结束后，第一轮酒让我来请。"
D.Strings[75185]="他们来了。集中精神。"
D.Strings[75186]="这应该会很有趣的。"
D.Strings[75187]="所有人，睁大眼睛！他们来了！"
D.Strings[75188]="希望你能比上一个家伙耐打一些。"
D.Strings[75189]="我还没打算死呢。"
D.Strings[75190]="我已经为这一刻准备了一辈子。"
D.Strings[75191]="我杀死过比你更厉害的对手。"
D.Strings[75192]="挑战者！"
D.Strings[75193]="那不叫武器——这才是武器！"
D.Strings[75194]="面对我！像个战士那样战斗吧！"
D.Strings[75195]="我要把你的脑袋留作纪念，懦夫。"
D.Strings[75196]="你为之奋战的一切都将化为尘土。"
D.Strings[75197]="我们才是正义的一方！"
D.Strings[75198]="胜利将属于我。"
D.Strings[75199]="我要打倒你！"
D.Strings[75200]="啊，总算有个像样的对手了！"
D.Strings[75201]="可惜我必须杀了你。"
D.Strings[75202]="真可悲，你战斗起来弱得像个孩子。"
D.Strings[75203]="目标假人的战术都比你强！"
D.Strings[75204]="我要战斗到最后一刻！"
D.Strings[75205]="你的鲜血将染红大地！"
D.Strings[75206]="想知道你的内脏是什么颜色的吗？你马上就会看到了。"
D.Strings[75207]="我要打断你的每一根骨头！"
D.Strings[75208]="等失去了四肢，看你还怎么战斗。"
D.Strings[75209]="你会死在这里，孤零零地被人遗忘。"
D.Strings[75210]="武器不错。我会从你的尸体上拿走它的。"
D.Strings[75211]="哈！每一次打击都在让你的希望流失！"
D.Strings[75212]="别担心，我会给你个痛快的。"
D.Strings[75213]="你已经算是同类中的佼佼者了吗？"
D.Strings[75214]="我要把你的脑袋插在长矛上！"
D.Strings[75215]="你干嘛不做点有用的事呢，比如给自己掘一座坟墓？"
D.Strings[75216]="这真是越来越无聊了！快投降吧！"
D.Strings[75217]="我只要一击就能把你干掉。"
D.Strings[75218]="蠢货！你根本不是我的对手！"
D.Strings[75219]="这太轻松了！你是想找死吗？"
D.Strings[75220]="我带着荣耀而战！而你战斗起来就像一条疯狗！"
D.Strings[75221]="这甚至算不上挑战。"
D.Strings[75222]="快回家去吧，小崽子。你留在这里只能送死。"
D.Strings[75223]="我将回归圣光。"
D.Strings[75224]="我将回归先祖身旁。"
D.Strings[75225]="我让你失望了，指挥官。"
D.Strings[75226]="黑暗吞噬了我。"
D.Strings[75227]="这就是我的结局吗？"
D.Strings[75228]="我为艾泽拉斯献出了生命！"
D.Strings[75229]="告诉我的家人……我爱他们。"
D.Strings[75230]="我诅咒这被圣光遗弃的世界！"
D.Strings[75231]="我不会白白牺牲的。"
D.Strings[75232]="我可以被击败，但艾泽拉斯必胜！"
D.Strings[75233]="我会在地狱里等着加尔鲁什的！"
D.Strings[75234]="我撑不下去了。"
D.Strings[75235]="还没完呢。会有人给我报仇的！"
D.Strings[75236]="我终于不用再战斗了。"
D.Strings[75237]="我死得光荣。"
D.Strings[75238]="答应我……你一定要干掉那个杀死我的家伙。"
D.Strings[75239]="死亡不过是必须的小小代价。"
D.Strings[75240]="为了艾泽拉斯，我百死不悔。"
D.Strings[75241]="其他人不会放过你的……"
D.Strings[75242]="你就这点本事吗……等等，你好像很厉害嘛。"
D.Strings[75243]="我只后悔没能多杀几只钢铁部落的狗杂种。"
D.Strings[75244]="我今天就不该来。"
D.Strings[75245]="这不过是点小伤罢了！"
D.Strings[75246]="我说过愿意为艾泽拉斯而死，只是没想到这一天来得这么快。"
D.Strings[75247]="杀了我吧，狗杂种。我绝不投降！"
D.Strings[75248]="我无法抵抗这个世界的原始召唤。这片土地和艾泽拉斯完全不同。这里有着太多东西等待我们去发现和学习。"
D.Strings[75249]="猛禽德鲁伊是来帮忙保卫我们的世界，抵抗钢铁部落的。艾泽拉斯的生命平衡决不能被破坏。"
D.Strings[75250]="我们德鲁伊是专职对抗钢铁部落的。我将大部分部队都驻扎在了戈尔隆德。$B$B我们在那里巡视森林、沙漠和天空。$B$B我的耳目会定期报告黑手的动向的。"
D.Strings[75251]="猛禽德鲁伊是来帮忙的。我们的部落分散于戈尔隆德各地，打探最新的情报。"
D.Strings[75252]="北部庭院里还有钢铁部落的余孽。"
D.Strings[75253]="我在空气中闻到了战争的味道，指挥官。难道这又是厕所的味道吗？"
D.Strings[75254]="我把要塞炉石弄丢了，你能再给我一块吗？"
D.Strings[75255]="今天铁匠哈菲斯特去村里出售我们的产品了。但我可以为你修理装备。\n\n我能帮你什么忙吗？"
D.Strings[75256]="%s疲惫地叹了一口气。"
D.Strings[75257]="%s看起来非常疲惫。"
D.Strings[75258]="无论我喂它们多少东西，你的宠物还是会溜到议政厅去讨残羹冷饭。"
D.Strings[75259]="我听说你是竞技场里的大明星，$n。"
D.Strings[75260]="不是所有的高阶督军都一样的，$c。有些人是靠持之以恒和日积月累，而有些人则是靠战斗技巧。猜猜我属于哪一种呢？"
D.Strings[75261]="抱歉，我现在无法为你的宠物治疗。如果你能过几分钟再来，我会很乐意帮你的。\n\n（在登录后的3分钟内，你不能治疗你的宠物。）"
D.Strings[75262]="看来这个搏击俱乐部完全不是我的菜。我更喜欢用自制的巨型机械怪物砍伐树木。$b$b如果你以后改变主意，可以告诉我，我可以直接帮你拆了这个搏击俱乐博，帮你建一座热火朝天的大伐木场！就用它自己的切割者搞定一切！$b$b当然，这可不便宜。"
D.Strings[75263]="改建伐木场。"
D.Strings[75264]="你有什么宝贝要卖吗？"
D.Strings[75265]="你为什么被叫做“母狮”？"
D.Strings[75266]="<丽奥眯了眯双眼。>"
D.Strings[75267]="你真的想知道答案吗？"
D.Strings[75268]="<丽奥轻声咆哮起来。>"
D.Strings[75269]="以前也有人这么问过我……但就那么一次。"
D.Strings[75270]="小鬼，别来惹我。"
D.Strings[75271]="追上迦罗娜！"
D.Strings[75272]="算了吧！"
D.Strings[75273]="有什么宠物用品卖吗？"
D.Strings[75274]="噢，真是个好问题。让我们把它记下来吧。"
D.Strings[75275]="你喜欢疤痕吗？"
D.Strings[75276]="你在奥洛克身上发现什么没有？比如一封信？或者指令之类的？"
D.Strings[75277]="破坏者格洛，请倾听我的呼唤！"
D.Strings[75278]="嘲颅兽人的万灵已经说了，我们必须携手对付共同的敌人——钢铁部落！"
D.Strings[75279]="太好了！成功了！万灵说得对！"
D.Strings[75280]="树木？呸！既然可以毁灭，为什么还要重建呢？$b$b我可以让你和士兵见识到切割机无法比拟的技巧。$b$b等你长大一点，口袋里的钱多一点时再来吧，那时我们就能建起一座体面的搏击俱乐部了。"
D.Strings[75281]="艾苏克……"
D.Strings[75282]="改建搏击俱乐部。"
D.Strings[75283]="%s的恶毒诅咒发现了更合适的宿主，并转移到了$n的身上。"
D.Strings[75284]="我要砍下那个把地雷丢进海港的兽人的脑袋！"
D.Strings[75285]="白色海怪号随时可能攻击！我要那些地雷立刻装填完毕！"
D.Strings[75286]="我们已经在德拉诺发现了数百个新物种。这里有太多东西值得研究、收集和记录了！"
D.Strings[75287]="送我去地面。"
D.Strings[75288]="如此美妙的……痛楚……"
D.Strings[75289]="可谁来……阻止……白色海怪号……"
D.Strings[75290]="没有了我，钢铁部落仍将战斗到底！"
D.Strings[75291]="高里亚帝国……必胜……"
D.Strings[75292]="嘿！我正在探查险情呢。"
D.Strings[75293]="这地方可真古怪。它让我想起了我在洛丹米尔湖畔的夏日别墅的仆役区——只是更加老土肮脏。$B$B或许你应该出出资买一些巴罗夫实业集团的产品，以免这座临时木头堡垒被付之一炬。"
D.Strings[75294]="你有什么好卖的？"
D.Strings[75295]="我兄弟必须被绳之以法！"
D.Strings[75296]="想要成为你的公会在坠落之月的代表吗？"
D.Strings[75297]="我想在要塞中显示公会的战旗。"
D.Strings[75298]="我想移除要塞中的公会战旗。"
D.Strings[75299]="入侵者又来了？"
D.Strings[75300]="纵火犯和篡位者！"
D.Strings[75301]="你们竟敢踏入我们的圣林。"
D.Strings[75302]="你的尸体将成为我们的养料。"
D.Strings[75303]="你的鲜血将化为树汁。"
D.Strings[75304]="啊，就是它，这是我的神器。我真蠢，居然把这么珍贵的东西交给布拉克。"
D.Strings[75305]="可惜你们来迟一步，已经无法再阻止我了。交出神器，我就饶你们一命。"
D.Strings[75306]="哈哈哈哈，随便吧！钢铁部落，前进！"
D.Strings[75307]="见识一下我军械库里的武器吧！"
D.Strings[75308]="你们休想抵抗苟克的力量！"
D.Strings[75309]="放出钢铁之星！"
D.Strings[75310]="小戈隆，攻击！"
D.Strings[75311]="嗷……难以置信！你们将为自己的傲慢付出生命的代价！我要将你们大卸八块！"
D.Strings[75312]="不！除非我死，否则你们休想拿走属于我的东西！你们休想……赢得……这场战争！"
D.Strings[75313]="哈哈哈！现在没这么自信了，是吧？！堂堂正正地面对我吧，懦夫们！"
D.Strings[75314]="我们绝不会向你投降的！勇士，是时候了！快使用神器！"
D.Strings[75315]="振作起来，勇士。圣光与你同在。我是不会让你倒下的。"
D.Strings[75316]="神器……他干了什么？！我们必须修复它，并把它送到安全的地方去！"
D.Strings[75317]="结束了，他们的防御土崩瓦解了。我们赢得了这场战斗，但没有了神器，我们还有很多事情要做。"
D.Strings[75318]="让我们回到你的岗哨汇合吧，指挥官。我们得计划一下下一阶段的进攻。"
D.Strings[75319]="结束了，他们的防御土崩瓦解了。我们赢得了这场战斗，但没有了神器，我们还有很多事情要做。让我们回你的岗哨汇合吧，指挥官。我们得为下一阶段的进攻做好打算。"
D.Strings[75320]="呱呱呱！！"
D.Strings[75321]="我们将统治天空，以及天空之下的广袤土地！"
D.Strings[75322]="再坚持一会儿！"
D.Strings[75323]="明智的选择！我这就赶去你的要塞。"
D.Strings[75324]="钢铁码头急需我的支援。"
D.Strings[75325]="现在，没人能阻止我们取得神器了。来吧，让他们的鲜血染红这些岩石吧！"
D.Strings[75326]="钢铁部落完全不了解这件神器的潜力。让我们给他们好好演示一下吧，如何？"
D.Strings[75327]="在戈尔隆德一定保持谨慎，即使是在天上飞行时！"
D.Strings[75328]="祝福你，陌生人，非常感谢。"
D.Strings[75329]="我的人民。他们做了什么？"
D.Strings[75330]="我终于可以安息了。"
D.Strings[75331]="和你的公会同伴一起征服德拉诺的所有地下城，以此向你的公会表达忠诚吧。一旦你完成了这个任务，就可以从公会商人那里购买要塞公会旗帜。\n\n等你拿到旗帜后再来找我，我可以帮你在要塞中升起公会旗帜，让所有人都看到。"
D.Strings[75332]="这就是我的结局吗……"
D.Strings[75333]="要是你能打得再卖力点多好！"
D.Strings[75334]="去吧！我会掩护你的！"
D.Strings[75335]="让我们并肩战斗，团结一致！"
D.Strings[75336]="谁先杀满五十个敌人就算赢！"
D.Strings[75337]="那就来吧！你知道的，战斗可不是天天都有的！"
D.Strings[75338]="守住阵线！别让钢铁部落突破你们的阵地！"
D.Strings[75339]="用尽全力，把钢铁部落赶回去！"
D.Strings[75340]="勇敢地战斗吧，胜利必将属于我们！"
D.Strings[75341]="让钢铁部落明白冷兵器的价值吧！"
D.Strings[75342]="全力战斗，寸土不让！"
D.Strings[75343]="守住阵地！让钢铁部落看看，我们是打不垮的！"
D.Strings[75344]="噢啊啊啊啊……呃……呃……"
D.Strings[75345]="把你砸进山里去。"
D.Strings[75346]="愿治疗法术治愈你的伤口。"
D.Strings[75347]="我的刀锋会把你劈成两半！"
D.Strings[75348]="我的攻击迅捷而凶猛。"
D.Strings[75349]="你的技巧在我的刀剑面前不堪一击。"
D.Strings[75350]="感受治疗法术的抚慰吧。"
D.Strings[75351]="靠近点！我这就给你治疗！"
D.Strings[75352]="移动靶……我的最爱！"
D.Strings[75353]="你休想躲过我的射击！"
D.Strings[75354]="到我身后去！快！"
D.Strings[75355]="我来拖住他们，你负责干掉他们！"
D.Strings[75356]="你得先过我这关！"
D.Strings[75357]="感受我愤怒的法术吧！"
D.Strings[75358]="要想干掉你，都不用我费多少法力！"
D.Strings[75359]="我有比武器更好的东西——魔法！"
D.Strings[75360]="我的攻击从不迟疑！"
D.Strings[75361]="我的攻击从不落空。"
D.Strings[75362]="我的盾永不碎裂！"
D.Strings[75363]="你的攻击在我的护甲面前不值一提！"
D.Strings[75364]="来打穿我的盾牌呀。我打赌你没这本事！"
D.Strings[75365]="就算我有盾牌，你也不用跑呀！"
D.Strings[75366]="你听说过纳特·帕格吗？没有？快过来听我给你讲讲吧！"
D.Strings[75367]="你听说过纳特·帕格吗？他可是个传奇！\n\n为了钓到更大的鱼，纳特走遍了整个世界！说起大鱼，我敢打赌，德拉诺肯定也有不少巨型鱼类。要是我们能把纳特请来教我们钓鱼……你还是多练练钓鱼技巧，能熟练了再回来找我吧。"
D.Strings[75368]="你可以跟破坏者格洛沟通了。"
D.Strings[75369]="你能跟我说说这个“纳特·帕格”吗？"
D.Strings[75370]="早上好啊？"
D.Strings[75371]="你是纳特·帕格吗？我正到处找你呢！"
D.Strings[75372]="主教议会就是“先知之手”。我们代表德莱尼人民，也是先知意志的传达者、执行者和监督者。"
D.Strings[75373]="总算到了！这地方离家乡可真远啊！"
D.Strings[75374]="我们去钓鱼吧！"
D.Strings[75375]="士兵们，守住入口！等那头戈隆懈怠下来之后，我们就冲出去！"
D.Strings[75376]="我要申领本周的印记。"
D.Strings[75377]="我表现得很勇敢……对吧？"
D.Strings[75378]="它就像踩蚂蚁一样踩住了我……"
D.Strings[75379]="我需要些什么呢？"
D.Strings[75380]="别管我了……我只会拖累你……Lok'tar……"
D.Strings[75381]="等我痊愈之后，一定要让那头戈隆好看……"
D.Strings[75382]="驯服这些戈隆的念头太蠢了……我们应该依靠自己的力量！"
D.Strings[75383]="我们会成功的。戈尔多克有办法对付这些家伙……"
D.Strings[75384]="嘲颅氏族必将复兴！"
D.Strings[75385]="雷克萨并不那么可信，对吧？幸好你刚巧遇上了我们。"
D.Strings[75386]="从瀑布上游摔下来的鱼正好吞下了我的鱼饵。$B$B我打算跟营地里的特加分享我的收获。她……可凶了。"
D.Strings[75387]="只要让我把这玩意儿发动起来，我们就能分分钟扫平这座岛屿。\n\n这可是激光，宝贝！"
D.Strings[75388]="相信戈尔多克，他会帮我们搞定这个……烂摊子的……"
D.Strings[75389]="谁能想到这里会有这么多戈隆？我们的斥候简直该死！"
D.Strings[75390]="想趁我们恢复时偷袭我们？想都别想，蠢货！"
D.Strings[75391]="或许你的尸体可以引开戈隆！"
D.Strings[75392]="我们是受伤了，可我们依然强大！"
D.Strings[75393]="我们会回来的……你们休想阻止我们……"
D.Strings[75394]="获得集结分！"
D.Strings[75395]="指挥官，戈尔隆德是个严酷的地方。如果你愿意，它能将你锻炼成一把利刃。$b$B如果你砍够了木头，就来跟我谈谈吧。$b$B只要花一点钱，我们就能把这个伐木场改建成实用的格斗竞技场。"
D.Strings[75396]="改建格斗竞技场。"
D.Strings[75397]="以我的品位来看，你那个格斗竞技场太粗野暴力了。$b$b如果你想要点更实在的东西，那你就找对人了！$b$b我们可以用我的钻探机来帮你建造一座大型伐木场。$b$b我记得我还有一张地精机械切割者的设计图。$b$b只要你存够了钱，我就帮你造。"
D.Strings[75398]="我在格斗竞技场里发挥不了什么作用。但如果你想要一座伐木场，那你就找对矮人了。$b$b等你更加老练，并解决了跟钢铁部落的仇恨之后再来找我吧。"
D.Strings[75399]="你需要一座要塞。$B$B我知道。"
D.Strings[75400]="指挥官，我对伐木或者收集木材不感兴趣。$b$b等你完成对付钢铁部落的任务之后再来找我吧，或许你还需要多积累一些战斗经验。$b$b只要花一些钱，我就能拆掉这座伐木场，在原地造起一座让你自豪的格斗竞技场。"
D.Strings[75401]="为我创建一座要塞。"
D.Strings[75402]="将我的要塞升到下一级。"
D.Strings[75403]="你还在等什么？我们快去抓鱼吧！"
D.Strings[75404]="能再给我一个弯钩鱼饵吗？"
D.Strings[75405]="我需要全套1级和2级建筑图纸。"
D.Strings[75406]="我要立刻完成所有在建的要塞建筑。"
D.Strings[75407]="你需要什么，指挥官？"
D.Strings[75408]="你准备好加入了吗，纳特？我已经等不及要请你加入队伍了！"
D.Strings[75409]="希望我能得到幸运女神的垂青。"
D.Strings[75410]="来点运气总是好的。"
D.Strings[75411]="这总没什么坏处。"
D.Strings[75412]="我感觉要走运了！"
D.Strings[75413]="再给我一些要塞物资。"
D.Strings[75414]="我的要塞需要一些追随者。"
D.Strings[75415]="送我去阿什兰的暴风之盾。"
D.Strings[75416]="如果你有需要，尼莎愿意送你去独眼魔的巢穴。"
D.Strings[75417]="目标过来了！"
D.Strings[75418]="瞄准东北方！"
D.Strings[75419]="瞄准西北方。"
D.Strings[75420]="对方毫无机会！"
D.Strings[75421]="准备开火！"
D.Strings[75422]="看来我们今天有烧烤裂蹄牛吃了！"
D.Strings[75423]="难以置信，这居然就是我们的报酬。"
D.Strings[75424]="他们是从哪儿冒出来的？"
D.Strings[75425]="指挥官！噢，哇，真没想到能在这里见到你。你想要买几张图纸吗？"
D.Strings[75426]="能为您效劳真是我的荣幸，$G长官:女士;。我一定要把这事告诉其他人。"
D.Strings[75427]="我马上就能换班了。你要去埃尔顿·布莱克那里买块牛排吗？我听说他都是当场杀牛的，所以你可以放心，它的牛排都是新鲜的。"
D.Strings[75428]="新鲜的猎物来了！"
D.Strings[75429]="古加尔逃跑了！城市里一片混乱！"
D.Strings[75430]="你今天来这里真是个错误的选择。"
D.Strings[75431]="好好享受冥界的生活吧，$n。"
D.Strings[75432]="你的努力失败了，$n！"
D.Strings[75433]="像你这样的$R应该放聪明点，别来挑战我。"
D.Strings[75434]="准备与食人魔战斗。"
D.Strings[75435]="中士，食人魔向我们的前门冲过来了。"
D.Strings[75436]="那是什么声音？好像是一群奔腾的……"
D.Strings[75437]="敲响警钟！准备迎接正面攻击！"
D.Strings[75438]="拿起武器！各就各位！我们今天的对手是食人魔。"
D.Strings[75439]="站稳了，士兵们。德拉诺的食人魔和艾泽拉斯的可不是一回事。"
D.Strings[75440]="记住，在杀死他们之后，千万别让他们倒在你身上。"
D.Strings[75441]="前门已经没人了……"
D.Strings[75442]="小心那些低级食人魔。"
D.Strings[75443]="他是想从大门外挤进来吗？冲锋！为了联盟！"
D.Strings[75444]="什么……小偷！"
D.Strings[75445]="哇！你也在这儿呢？呼……我都开始以为自己干了件蠢事呢。我已经准备好为联盟赢得这场战争了，$G长官:女士;！"
D.Strings[75446]="你知道我是素食主义者，对吧？"
D.Strings[75447]="你不愿意加入赤色大军？那就去死吧！"
D.Strings[75448]="旅店在这边，指挥官。"
D.Strings[75449]="我会让他们看到的！我要让他们知道我真正的实力！"
D.Strings[75450]="欢迎，指挥官。如果有什么能让你感觉更加舒适，请尽管告诉我。"
D.Strings[75451]="等等，伙计。你没看见我正忙着吗？"
D.Strings[75452]="我们已经走过了不少路，但前面总有更多事情在等着我们去做。"
D.Strings[75453]="愿鸦母的羽翼庇佑着你！"
D.Strings[75454]="愿鸦母祝福你！"
D.Strings[75455]="你准备好飞往阿什兰之后，就告诉杜加尔吧。"
D.Strings[75456]="快来呀，都来呀。快来独一无二的鲜血竞技场观看不死不休的精彩战斗吧！今天，我们的新人$n和$G他:她;的伙伴们竟然愚蠢到想要挑战嚼颅者！是时候多送上几个脑袋了，伙计！"
D.Strings[75457]="战斗开始！"
D.Strings[75458]="我还是个小伙子时，曾接受过我爷爷吉加克斯的训练。我跟你保证，在这一带，你再也找不到比我更出色的战士了。"
D.Strings[75459]="当钢铁部落出现时，大家都有点紧张。你能来真是太好了。"
D.Strings[75460]="德尔瓦·铁拳就在山上。他有点傲慢，但他对战斗的热情是显而易见的。"
D.Strings[75461]="战斗的时刻又到了，乡亲们。快来观看前途远大的角斗士们用生命为你们献上的精彩战斗吧！这场比赛将由$n和$G他:她;的朋友们对战刀枪不入的弗拉克图斯！至今还没有武器能刺穿他岩石般坚硬的皮肤呢！"
D.Strings[75462]="只要把钢铁部落所在的方向指给我看就行了。剩下的就交给我搞定吧。"
D.Strings[75463]="只要法师打开通向暴风城的传送门，这个地方就会开始繁荣起来。我们说不定会在德拉诺这一边见到海量的商人和货物。"
D.Strings[75464]="豪威尔中尉干得很不错，把这个集结地打理得井井有条。"
D.Strings[75465]="豪威尔中尉就在里面。很荣幸能为您效劳，指挥官。"
D.Strings[75466]="有人要来送死了，乡亲们。$n和$G他:她;的朋友们将踏入世界知名的鲜血竞技场，挑战毁灭之神的活武器，腐藤！这场大屠杀绝对值得一看！"
D.Strings[75467]="$n和$G他:她;的朋友们将要证明自己的价值，挑战穆戈尔的珍兽：毁尸者德里夏克斯！这只巨虫已经吞吃了无数夭折天才的尸骨——$n这次还能逃出生天吗？"
D.Strings[75468]="不！他会醒过来的！"
D.Strings[75469]="我们还没有净化水源！"
D.Strings[75470]="我们都……死定了。"
D.Strings[75471]="束缚已经禁锢不住我了……"
D.Strings[75472]="现在，统统去死吧！"
D.Strings[75473]="生命的精华……"
D.Strings[75474]="不！滚开！"
D.Strings[75475]="让我们看看你的武器技巧吧！"
D.Strings[75476]="啊，一个$c。你想参加今天的讲座吗？$b$b我正需要一名志愿者。"
D.Strings[75477]="我要报名。"
D.Strings[75478]="谢谢你，指挥官。"
D.Strings[75479]="我们应该使用宝珠联系安苏。但首先，我相信它的力量能帮我们拯救这里的生命……"
D.Strings[75480]="他们对我……做了什么……"
D.Strings[75481]="声音……他们在阻止……"
D.Strings[75482]="大雾消散了……我在哪儿？"
D.Strings[75483]="谢谢你……我还能走。"
D.Strings[75484]="我的翅膀！我美丽的翅膀！"
D.Strings[75485]="他们会为此付出代价的……"
D.Strings[75486]="这力量……我还要更多！"
D.Strings[75487]="塞泰选中了我！"
D.Strings[75488]="我获得了新生……"
D.Strings[75489]="一条全新的道路……是的……"
D.Strings[75490]="我看见了我的命运……"
D.Strings[75491]="呸！你的脸真让我生气！"
D.Strings[75492]="啊！我要砸扁你的脑袋！"
D.Strings[75493]="我要把你的脑袋砸进身体里去！"
D.Strings[75494]="呜哇！碾碎这个废物！"
D.Strings[75495]="但愿你会喜欢死亡的滋味！哇！"
D.Strings[75496]="头儿，我把最近的一些威胁在桌子上画出来了，以便你随时查看。"
D.Strings[75497]="食人魔和女食人魔们，今天，有人在世界知名的鲜血竞技场创造了历史！竞技场的现任冠军，穆戈尔将为了捍卫自己的头衔与$n以及$G他:她;的朋友们展开激战。这场战斗绝对值得一看！"
D.Strings[75498]="你竟敢在我的竞技场里挑战我？你这个蠢货。"
D.Strings[75499]="我要让你跪地求饶，但我是不会手软的。"
D.Strings[75500]="加油！"
D.Strings[75501]="这让我想起了多年前的那场荆棘谷之战。"
D.Strings[75502]="我感觉自己就像割草的园丁。"
D.Strings[75503]="肉弹要战斗！"
D.Strings[75504]="肉弹要杀人！"
D.Strings[75505]="这些植物让我想起了奥格瑞玛……"
D.Strings[75506]="肉弹要跟你打！"
D.Strings[75507]="他们被削弱了。"
D.Strings[75508]="肉弹想杀就杀！"
D.Strings[75509]="肉弹是不会输的！"
D.Strings[75510]="这个世界有太多我们不了解的秘密了。钢铁部落在这里经营的时间比我们长得多，他们的盟友世代定居于此。$B$B他们比我们更了解这个神器的力量，我们必须利用好每一个优势。"
D.Strings[75511]="肉弹有零食吃了！"
D.Strings[75512]="肉弹肚子咕咕叫！"
D.Strings[75513]="肉弹喜欢战斗！"
D.Strings[75514]="嗝儿……"
D.Strings[75515]="|TInterface\\Icons\\Spell_Arcane_Blink:20|t%s施放了|cFFFF0000|Hspell:163359|h[奥术残片]|h|r！"
D.Strings[75516]="|TInterface\\Icons\\Spell_Arcane_Arcane04:20|t%s施放了|cFFFF0000|Hspell:163372|h[奥能动荡]|h|r！"
D.Strings[75517]="你会后悔的。"
D.Strings[75518]="这座要塞绝不会陷落！"
D.Strings[75519]="我拥有超乎想象的力量。"
D.Strings[75520]="滚开，否则我就将你烧成灰烬！"
D.Strings[75521]="你活该。"
D.Strings[75522]="干掉一个。"
D.Strings[75523]="我警告过你了。"
D.Strings[75524]="|TInterface\\Icons\\Spell_Arcane_FocusedPower:20|t%s对$n施放了|cFFFF0000|Hspell:163297|h[扭曲奥能]|h|r！"
D.Strings[75525]="这和我所看到的世界不一样。"
D.Strings[75526]="原为您效力，指挥官。"
D.Strings[75527]="我誓死效忠于你，指挥官。"
D.Strings[75528]="我们的命运悬而未决，指挥官。"
D.Strings[75529]="真……冷啊……"
D.Strings[75530]="为了奥金顿！"
D.Strings[75531]="你不属于这里。"
D.Strings[75532]="奥金尼的亡魂啊，指引我的双手吧！"
D.Strings[75533]="我的身边有着百万德莱尼的英灵，恶魔。"
D.Strings[75534]="我们遭到攻击了。保护没有武器的同伴！"
D.Strings[75535]="我是不会让你伤害无辜的。"
D.Strings[75536]="我不会再让你夺走无辜的生命了！"
D.Strings[75537]="你的灵魂太软弱了。"
D.Strings[75538]="你不配活着。"
D.Strings[75539]="如此黑暗的灵魂。"
D.Strings[75540]="你的灵魂将离开这个世界。"
D.Strings[75541]="永远地安息吧，异教徒。"
D.Strings[75542]="骑上尼莎前往你的岗哨。"
D.Strings[75543]="你的灵魂总是燃烧得如此明亮！"
D.Strings[75544]="你的英勇壮举进行地怎么样了？"
D.Strings[75545]="只要团结一致，我们就不会屈从于黑暗。"
D.Strings[75546]="圣光永远指引着我们，指挥官。"
D.Strings[75547]="奥金顿……我来了……"
D.Strings[75548]="让我看看你有什么本事。"
D.Strings[75549]="或许你能带来一场真正的战斗。"
D.Strings[75550]="列队！我们有伴儿了。"
D.Strings[75551]="打起精神来。敌人过来了！"
D.Strings[75552]="你别想继续前进了！"
D.Strings[75553]="我们要为联盟而战！"
D.Strings[75554]="我是不会放过你的，恶魔！"
D.Strings[75555]="有我在呢。"
D.Strings[75556]="没人能阻挡联盟的力量。"
D.Strings[75557]="除非我死了，否则你是休想。"
D.Strings[75558]="今天，胜利将属于我们！"
D.Strings[75559]="你应该再加把劲的。"
D.Strings[75560]="又一个沙场的亡魂。"
D.Strings[75561]="在我们俩面前，敌人毫无机会。"
D.Strings[75562]="想要交流一下有关打仗的老故事吗？"
D.Strings[75563]="有部落的踪迹吗？"
D.Strings[75564]="此生此世，为了联盟。"
D.Strings[75565]="圣光指引我们走向胜利。"
D.Strings[75566]="我将与你并肩作战，碾压一切敌人。"
D.Strings[75567]="联盟……长存……"
D.Strings[75568]="新游戏！"
D.Strings[75569]="看看钢铁部落的力量吧！"
D.Strings[75570]="是谁打断了我们的收获？"
D.Strings[75571]="这些野蛮人会吃掉一切的！"
D.Strings[75572]="拿起武器！快拿起武器！"
D.Strings[75573]="危险靠近了！"
D.Strings[75574]="把市民送到安全的地方去。"
D.Strings[75575]="我想从其他地方招募守卫。"
D.Strings[75576]="如果你在铁炉堡、达纳苏斯、诺莫瑞根、埃索达、吉尔尼斯或土水派熊猫人中的声望达到崇拜，或者作为死亡骑士在黑锋骑士团达到崇拜声望，就可以与议政厅内对应的征募官对话，从他们那里招募守卫了。"
D.Strings[75577]="你伤害了砂齿的小宝贝，砂齿会让你后悔的！啊啊啊！"
D.Strings[75578]="啊啊啊！砂齿不喜欢你杀害小宝贝！"
D.Strings[75579]="鸦母又重新关注鸦群了！$b$b没有你，我们是做不到这一点的，$n。$b$b你在我们最需要的时候帮助了我们，我们会永远铭记你的，外来者。"
D.Strings[75580]="肉弹累了！"
D.Strings[75581]="肉弹还是饿！"
D.Strings[75582]="肉弹屁股痒！"
D.Strings[75583]="肉弹讨厌肉弹的声音！"
D.Strings[75584]="肉弹不想打了！"
D.Strings[75585]="这可是个大家伙，伙计！"
D.Strings[75586]="我要像剖鳗鱼一样把你开膛破肚！"
D.Strings[75587]="你吞下了诱饵，该轮到我收线了！"
D.Strings[75588]="这家伙比较经打！"
D.Strings[75589]="你将成为我的下一个诱饵！"
D.Strings[75590]="看来我们又有伴儿了！"
D.Strings[75591]="既然落到我的手上，你就别想跑了，伙计！"
D.Strings[75592]="我能一次性干掉上百个你这样的！"
D.Strings[75593]="这简直都不能算是战斗……"
D.Strings[75594]="我要终结你毫无价值的生命！"
D.Strings[75595]="你可悲的人生到此为止了。"
D.Strings[75596]="你的死亡很快就会被人们遗忘……"
D.Strings[75597]="简直不费吹灰之力。"
D.Strings[75598]="你想知道抓住大鱼的秘诀吗？那就是巫术！"
D.Strings[75599]="最近有什么收获吗，头儿？"
D.Strings[75600]="这个营地需要加强一下纪律，指挥官。"
D.Strings[75601]="嘿，陌生人！我可擅长修东西了。你有什么要让我看看吗？"
D.Strings[75602]="总有一天，我也会成为英雄的！"
D.Strings[75603]="给我一支军队，指挥官，我就能帮你拿下高里亚帝国！"
D.Strings[75604]="我做了一根新鱼竿，伙计。可我想不出什么好名字了。“阿布加尔的坚韧”怎么样？"
D.Strings[75605]="你有什么指示吗，长官？"
D.Strings[75606]="今天没事可做了，伙计。我想这就是人们所说的钓而不获吧。"
D.Strings[75607]="有什么值得一战的敌人吗，指挥官？"
D.Strings[75608]="你想知道最好的钓鱼方法吗？那就是拖钓。"
D.Strings[75609]="我的鱼线从来不断，伙计。这可是我用矮人的胡须编成的。"
D.Strings[75610]="死在……离家这么远的地方……"
D.Strings[75611]="这不是……我想象中的……结局……"
D.Strings[75612]="鱼……跑了……"
D.Strings[75613]="在看了你和雷克萨的行动后，我很想向你们两位多学一些战斗技巧。"
D.Strings[75614]="呜哇！你杀了小宝贝，砂齿要杀回来！"
D.Strings[75615]="你会成为掠食者口中的美餐的。"
D.Strings[75616]="我正在寻找欧文·加多克。送我去霜火岭吧。"
D.Strings[75617]="送我去阿什兰。"
D.Strings[75618]="面对我，看看我们谁更强壮。"
D.Strings[75619]="我们新的鲜血勇士已经出现了。向$n致敬吧，$G他:她;在竞技场中的表现已经赢得了我的尊重。"
D.Strings[75620]="够了！我是不会坐视我的宝贝猛兽倒下的。我要让他们看看真正的力量。"
D.Strings[75621]="再次感谢你，伙计，谢谢帮我找回了装备。 \n\n现在，鱼儿在阿布加尔面前将毫无机会！"
D.Strings[75622]="为了卡拉波之光。"
D.Strings[75623]="我的锤子足以打败你。"
D.Strings[75624]="不要小看我！"
D.Strings[75625]="你被击败了！"
D.Strings[75626]="你有东西要修吗，指挥官？"
D.Strings[75627]="我应该……再……加把劲的……"
D.Strings[75628]="这是个战斗的好日子。"
D.Strings[75629]="你要挑战我？"
D.Strings[75630]="但愿你已经做好准备了。"
D.Strings[75631]="这太简单了。"
D.Strings[75632]="我连爪子都没破。"
D.Strings[75633]="愿艾露恩祝福你，指挥官。"
D.Strings[75634]="愿星辰照耀着你。"
D.Strings[75635]="美好的一天在等着我们。"
D.Strings[75636]="呃……这……还不够……"
D.Strings[75637]="让我看看你的真本事吧。"
D.Strings[75638]="你以为你能对付我？"
D.Strings[75639]="我可是知道一些花招的。"
D.Strings[75640]="唔，不出我的所料。"
D.Strings[75641]="你真不经打。"
D.Strings[75642]="这是给你教训。"
D.Strings[75643]="在挑衅我之前，最好三思而行。"
D.Strings[75644]="我听候您的吩咐，指挥官。"
D.Strings[75645]="愿意为您效劳。"
D.Strings[75646]="你有任务要交给我吗，指挥官？"
D.Strings[75647]="我……没想到……会这样……"
D.Strings[75648]="我会尽力而为的！"
D.Strings[75649]="让我们公平一战吧！"
D.Strings[75650]="还不错！"
D.Strings[75651]="日安，指挥官！"
D.Strings[75652]="我们今天该干点什么？"
D.Strings[75653]="今天是个冒险的好日子。"
D.Strings[75654]="哎哟……"
D.Strings[75655]="耐心点，姐妹们。我们早点干完，就能尽快碾碎敌人。"
D.Strings[75656]="苏卡！让苦工们加把劲！"
D.Strings[75657]="玛拉卡！去给主炮装填弹药！"
D.Strings[75658]="什么？！列车误点了？"
D.Strings[75659]="苏卡，这可不是闹着玩的。快下来！"
D.Strings[75660]="真受不了你……"
D.Strings[75661]="噢，这就是你的扫堂腿吗！"
D.Strings[75662]="姐妹们！准备战斗！"
D.Strings[75663]="姐妹们……我……失败了……"
D.Strings[75664]="或许我不适合这份差事。"
D.Strings[75665]="但愿他们不要发现我在看这本手册……"
D.Strings[75666]="我已经等不及想得到自己第一套真正的盔甲了！"
D.Strings[75667]="谁都无法阻挡钢铁部落。"
D.Strings[75668]="我要让他们看看我的厉害，我要证明他们都错了！"
D.Strings[75669]="投出手雷！"
D.Strings[75670]="进入射击距离……"
D.Strings[75671]="快速射击！"
D.Strings[75672]="……莫过于战死！"
D.Strings[75673]="苏卡！去开炮！"
D.Strings[75674]="玛拉卡！瞄准一点！"
D.Strings[75675]="难道一定要我亲自动手？！"
D.Strings[75676]="……我知道是什么问题了。"
D.Strings[75677]="让我们看看你训练士兵的本事吧，加安。"
D.Strings[75678]="哈！真暴力，真血腥。漂亮。"
D.Strings[75679]="别担心，我来了。这真有意思。"
D.Strings[75680]="感觉……这么……"
D.Strings[75681]="噢，我把它弄坏了！"
D.Strings[75682]="我真是太棒了。"
D.Strings[75683]="靠近点！"
D.Strings[75684]="……去死吧！"
D.Strings[75685]="最大的光荣……"
D.Strings[75686]="我的……血……"
D.Strings[75687]="好好享用吧，科罗克娜……"
D.Strings[75688]="我赢了。"
D.Strings[75689]="科罗克娜，血腥风暴！"
D.Strings[75690]="随着我的利斧起舞吧。"
D.Strings[75691]="死亡……"
D.Strings[75692]="先祖啊，指引我的战斧吧！"
D.Strings[75693]="你会尝到痛苦的滋味……"
D.Strings[75694]="那是什么鱼？我从没见过这样的鱼，快过来让我看看！"
D.Strings[75695]="我是不会对你客气的。"
D.Strings[75696]="罪有应得。"
D.Strings[75697]="黑暗临近了。"
D.Strings[75698]="你需要杀什么人吗，指挥官？"
D.Strings[75699]="派我上前线吧，指挥官。"
D.Strings[75700]="我的剑听候您的召唤。"
D.Strings[75701]="加罗德……我来找你了……很快……"
D.Strings[75702]="你的末日已经到了。"
D.Strings[75703]="我就盼着这个呢。"
D.Strings[75704]="又干掉一个。"
D.Strings[75705]="一场光荣的战斗。"
D.Strings[75706]="打得不错，但这还不够。"
D.Strings[75707]="向你致敬，指挥官。"
D.Strings[75708]="我今天能帮你什么忙吗？"
D.Strings[75709]="元素在召唤。"
D.Strings[75710]="我还不够……强大……"
D.Strings[75711]="如果它会流血，我们就能杀了它。"
D.Strings[75712]="表演时间。"
D.Strings[75713]="你的存在已经被抹去了。"
D.Strings[75714]="让我的扳手砸烂你的脸。"
D.Strings[75715]="完全不费力气。"
D.Strings[75716]="正中目标。"
D.Strings[75717]="这肯定会留下印子的。"
D.Strings[75718]="冻死一个！"
D.Strings[75719]="需要我杀什么人吗，指挥官？"
D.Strings[75720]="今天需要来场战斗，你觉得呢？"
D.Strings[75721]="我是不会轻易倒下的。"
D.Strings[75722]="只要把随便什么食人魔交给我，我就能帮你搞定他们。"
D.Strings[75723]="按照要求，拆卸完毕。"
D.Strings[75724]="很高兴再次见到你，长官。"
D.Strings[75725]="哦，我又搞死一个。"
D.Strings[75726]="下次战斗什么时候开始，指挥官？"
D.Strings[75727]="有时我自己都感到吃惊。"
D.Strings[75728]="今天有什么工作吗？"
D.Strings[75729]="拜托，我都快无聊死了。你有什么事要让我做的吗？"
D.Strings[75730]="那么你喜欢哪个，火药还是汽油弹？我？我比较喜欢汽油弹。"
D.Strings[75731]="什么事，指挥官？"
D.Strings[75732]="嘿，指挥官，你是来给我分派任务的还是直接来给我送钱的？"
D.Strings[75733]="见……鬼……"
D.Strings[75734]="你这是自寻死路。"
D.Strings[75735]="美妙的死亡在等待着你。"
D.Strings[75736]="享受你最后的时光吧。"
D.Strings[75737]="欢迎投入黑暗女王的怀抱。"
D.Strings[75738]="黑暗女王向你问好。"
D.Strings[75739]="有人需要我去杀吗，指挥官？"
D.Strings[75740]="有新任务吗？"
D.Strings[75741]="晚上好，指挥官。"
D.Strings[75742]="美妙的夜晚最适合杀戮了，你不这么认为吗？"
D.Strings[75743]="我的法杖听凭您的调遣。"
D.Strings[75744]="死神也会来……找你的……"
D.Strings[75745]="你也会死在我的剑下的。"
D.Strings[75746]="来吧，有种就来面对我吧。"
D.Strings[75747]="简直是浪费我的时间。"
D.Strings[75748]="你是不见棺材不掉泪吗？"
D.Strings[75749]="终于有人来送死了。"
D.Strings[75750]="我会给你痛快的。"
D.Strings[75751]="你不配做我的对手。"
D.Strings[75752]="没人来挑战我吗？"
D.Strings[75753]="你的鲜血简直让我的剑蒙羞。"
D.Strings[75754]="至少你没有逃跑。"
D.Strings[75755]="向你致敬。"
D.Strings[75756]="你不配这么干脆的死去。"
D.Strings[75757]="还有谁？"
D.Strings[75758]="我渴望真正的对手。"
D.Strings[75759]="$n，很高兴再次见到你。"
D.Strings[75760]="Lok-Regar。我已经准备好迎接新的战斗了。"
D.Strings[75761]="我很怀念纳格兰的草原。"
D.Strings[75762]="我的剑渴望鲜血。"
D.Strings[75763]="荣耀就是一切。"
D.Strings[75764]="有火刃氏族的消息吗？"
D.Strings[75765]="我们到底要在你的“要塞”里待多久？"
D.Strings[75766]="这是……一种……荣耀。"
D.Strings[75767]="里诺——艾！火——车王！"
D.Strings[75768]="时间到了。我们动手吧！"
D.Strings[75769]="干得好，伙计们！"
D.Strings[75770]="抱歉，你说话了吗？"
D.Strings[75771]="呃，你说什么？"
D.Strings[75772]="我们可是生死之交。"
D.Strings[75773]="这不是我的错。"
D.Strings[75774]="至少我还有小鸡。"
D.Strings[75775]="按计划来，伙计们！"
D.Strings[75776]="你似乎很惊讶会在这里见到我们，$C。这是可以理解的。我太清楚鸦人会怎么对待你的人民了。\n\n鲁克玛的信徒都是野蛮的怪物，他们对力量的渴望只会让他们堕落。我们要寻找一条不同的道路。\n\n我们要找到埃匹希斯的神器，并用它们来为鸦人开启一个和平的新时代。为了换取这些圣物，我们可以提供制作精良的货物，相信你会认为这是公平的交换。\n\n你愿意帮助我们吗，$C？"
D.Strings[75777]="别害怕，罗西，我们在这儿很安全。"
D.Strings[75778]="只有最出色的战士才能在竞技场中战斗。"
D.Strings[75779]="请在阴影中休息一会儿吧。"
D.Strings[75780]="闭上你的嘴，地精，否则我就帮你闭上它。我只想试试这家伙的本事。"
D.Strings[75781]="嘿！你们没有在竞技场注册过，拜托！"
D.Strings[75782]="总有一天，你的鲜血将染红它的锋刃。这只是时间问题。"
D.Strings[75783]="你好，$C。我们是觉醒教派的人，我们代表鸦人族群的利益。\n\n我相信你已经见识过了鲁克玛的信徒给鸦人和其他宗族带来的恐怖。我们希望扭转这些伤痛，给我们的族群带来和平的新时代。但为此，我们需要埃匹希斯的知识。\n\n如果你想帮助我们，我们愿意用珍贵的物品换取你找到的埃匹希斯圣物。你看怎么样，$C?。"
D.Strings[75784]="克拉吉尔中尉就在里面。很荣幸能为您效劳，指挥官。"
D.Strings[75785]="头儿！你也在这儿啊？呼……我都开始怀疑自己是不是干了件蠢事呢。让我们为部落赢得这场战争吧！"
D.Strings[75786]="成功了！至于你们，我想可以让我的工具之一来对付……"
D.Strings[75787]="薇薇安就在山下。她有点喜欢纵火，但她对战斗的热情是显而易见的。"
D.Strings[75788]="这太轻松了！"
D.Strings[75789]="如果我有一支皇家军团的话，这场战斗已经结束了！"
D.Strings[75790]="皇帝庇护着我！"
D.Strings[75791]="没有阵型……没有战术……这不是战斗，而是斗殴！"
D.Strings[75792]="如果你敢耍我，那就跟玩火无异……我是说真的。"
D.Strings[75793]="这是……第一百个。"
D.Strings[75794]="如你所愿，指挥官。钢铁部落会吃到苦头的。"
D.Strings[75795]="如果你能有点技巧就好了。"
D.Strings[75796]="再想一想的话……那可能就是我。"
D.Strings[75797]="一个最不幸的结局。"
D.Strings[75798]="你的牺牲给我们都上了宝贵的一课。"
D.Strings[75799]="向你问好。"
D.Strings[75800]="一次崇高的牺牲。"
D.Strings[75801]="愿你死无全尸。"
D.Strings[75802]="这比在熔炉旁工作还要简单。"
D.Strings[75803]="为了纪念艾瑞德！"
D.Strings[75804]="我不会让你过去的！"
D.Strings[75805]="低劣的装备，低劣的战斗。"
D.Strings[75806]="穿着那么破的装备，难怪你会输。"
D.Strings[75807]="你好，指挥官。你需要我的协助吗？"
D.Strings[75808]="随时为您效劳。"
D.Strings[75809]="这把武器比得上我的角吗？我正打算给它们涂上相配的颜色呢。"
D.Strings[75810]="这可比在某个尘封的老城市的熔炉边工作强多了。"
D.Strings[75811]="艾瑞德，我终于能来……找你了……"
D.Strings[75812]="真的？你用那个跟我战斗？哈！"
D.Strings[75813]="是时候测试一下我的最新武器了！"
D.Strings[75814]="都没什么值得拿的。"
D.Strings[75815]="都没在我的武器上留下一个印子。"
D.Strings[75816]="需要我帮你做什么东西吗？"
D.Strings[75817]="你想要我打铁还是战斗，指挥官？"
D.Strings[75818]="发现钢铁部落的踪影没有？我需要他们的装备留下的废金属。"
D.Strings[75819]="还……不能……"
D.Strings[75820]="住手。攻击这里的其他人是懦夫的行为。"
D.Strings[75821]="你是怎么回事？"
D.Strings[75822]="圣光的战士是不会坐视这一切的！"
D.Strings[75823]="我别无选择！"
D.Strings[75824]="你还真是顽固。"
D.Strings[75825]="噢，噢……"
D.Strings[75826]="在临死之前，想想你都干过些什么吧。"
D.Strings[75827]="见识一下我们的圣光是多么辉煌吧！"
D.Strings[75828]="是的，我做到了……我做好了！"
D.Strings[75829]="我就是圣光！"
D.Strings[75830]="令人振奋，对吧？"
D.Strings[75831]="这片土地是神圣的，这里不欢迎你。"
D.Strings[75832]="不用隐藏你的反应。我一直在看着呢！"
D.Strings[75833]="我们被陌生的生物所包围，身处一片陌生的土地……"
D.Strings[75834]="时间流本身被扭曲了……"
D.Strings[75835]="愿让我们合作愉快！"
D.Strings[75836]="要是我能这么容光焕发就好了！"
D.Strings[75837]="能遇见这么勇敢的勇士是我的荣幸！"
D.Strings[75838]="你真的很喜欢跟我聊天，不是吗？"
D.Strings[75839]="我的光芒……黯淡了……"
D.Strings[75840]="它是如此，黑暗……"
D.Strings[75841]="芝源有着令我望尘莫及的铭文天赋。\n\n如果你想接受这方面的训练，那没有比她更好的导师了。"
D.Strings[75842]="我还没完呢！"
D.Strings[75843]="为了我的家人！"
D.Strings[75844]="我不会让你攻击这个地方的。"
D.Strings[75845]="我还有未竟的事业。"
D.Strings[75846]="我是不会动摇的！"
D.Strings[75847]="指挥官，这里有敌人！"
D.Strings[75848]="你休想活着离开这里。"
D.Strings[75849]="我在另外一边等着你。"
D.Strings[75850]="跟我一起进入灵魂的世界吧。"
D.Strings[75851]="你们再也别想祸害这个世界了。"
D.Strings[75852]="你本打算干什么？杀了我？"
D.Strings[75853]="我的灵魂是最坚强的！"
D.Strings[75854]="你至少也要努力一下吧。"
D.Strings[75855]="我的家人再也不用活在对你们的恐惧之中了。"
D.Strings[75856]="在钢铁部落覆灭之前，我是不会安息的。"
D.Strings[75857]="我欠你一份人情，指挥官。"
D.Strings[75858]="我们将一起打败钢铁部落，指挥官。"
D.Strings[75859]="有钢铁部落的踪迹吗，指挥官？"
D.Strings[75860]="多亏了你，剑圣巴罗克再也不能折磨我的家人了。"
D.Strings[75861]="我听候你的调遣，指挥官。"
D.Strings[75862]="一切平静，指挥官。太平静了。"
D.Strings[75863]="给鲁比洛洛一块鲁比饼干。"
D.Strings[75864]="挥砍！"
D.Strings[75865]="突刺！"
D.Strings[75866]="把你知道的都说出来！"
D.Strings[75867]="哈！折磨你们这些可怜虫真是有意思。"
D.Strings[75868]="我的工作真是一种享受。"
D.Strings[75869]="本地的德莱尼已经成为我们在阿什兰不可或缺的盟友了。\n\n只要能保证连接大陆的补给线稳定，我们就赢定了！"
D.Strings[75870]="你们在阿什兰的事业是正义的，我们德莱尼会尽一切可能帮助你们的。"
D.Strings[75871]="人们一直很好奇一个狼人是怎么会变成饲养员的，可事实是，在被感染之前，我一直都是饲养员。只要把你的宠物交给老奥维尔就行了，我会好好照顾它们的。\n\n不用问了，我保证，我肯定不会吃了它们的。"
D.Strings[75872]="让我们开始干活儿吧。"
D.Strings[75873]="杀了塞泰之后，安苏成为了他的临终诅咒的第一个受害者。"
D.Strings[75874]="为了反抗这个诅咒，安苏命令他的恐惧渡鸦灭绝塞泰的子嗣。"
D.Strings[75875]="$g长官:女士;，我把最近的一些威胁画在地图上了，以便你随时查看。"
D.Strings[75876]="|cFF3ADF00+5%完成度！|r"
D.Strings[75877]="你受到了|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t|cFFFF0404|Hspell:154938|h[熔岩激流]|h|r的影响！"
D.Strings[75878]="欢乐机器人8000进入战斗。"
D.Strings[75879]="你的系统好像出故障了。"
D.Strings[75880]="激活防御机制。"
D.Strings[75881]="以指挥官的名字！"
D.Strings[75882]="你的技巧相当匮乏。"
D.Strings[75883]="消灭目标。"
D.Strings[75884]="你的服务结束了。"
D.Strings[75885]="愿意为您效劳！"
D.Strings[75886]="你好，指挥官。想试试我的按摩手法吗？"
D.Strings[75887]="你好！请让我来帮助你吧！"
D.Strings[75888]="能为您效劳是我的……荣幸！"
D.Strings[75889]="指挥官，你的衣服好像脏了。让我为你清洁一下吧。"
D.Strings[75890]="进入休眠模式……"
D.Strings[75891]="系统……过载……"
D.Strings[75892]="很……荣……荣幸为您效劳……"
D.Strings[75893]="我的人民被这些怪物关押得太久了。"
D.Strings[75894]="在一个血腥的夜晚，塞泰的子嗣们被屠杀殆尽。"
D.Strings[75895]="嘿！你在这儿干嘛呢？"
D.Strings[75896]="别看我个子小，我的拳头可硬着呢！"
D.Strings[75897]="我就知道该带些炸药来的！"
D.Strings[75898]="看来这些风蛇就和它们的主人一样，不甘心就这么死去。"
D.Strings[75899]="看来有人需要尝尝爆炸的滋味了！"
D.Strings[75900]="嘿，你！就是你，粉身碎骨吧！"
D.Strings[75901]="卡——布——劳——！"
D.Strings[75902]="哈哈哈哈！又干掉一个！"
D.Strings[75903]="你今天应该呆在家里的，朋友！"
D.Strings[75904]="哇……那一下肯定很疼！"
D.Strings[75905]="我又干掉一个了。"
D.Strings[75906]="别被我的眼罩骗了。我什么都看得见！"
D.Strings[75907]="你需要什么吗，指挥官？"
D.Strings[75908]="嘿，你好！"
D.Strings[75909]="还……没……完呢……"
D.Strings[75910]="我早知道自己会死于一场大爆炸了……"
D.Strings[75911]="抱歉，亲爱的，在考虑还能造什么建筑之前，我们需要先有更多的地皮。等你的要塞升到2级后再来吧，到时候我们再详谈。"
D.Strings[75912]="抱歉，头儿，加兹鲁维说，在考虑改建的事之前，我们需要先有更多的地皮。等你的要塞升到2级后再来吧，然后我再给你看我的货色。"
D.Strings[75913]="浸润"
D.Strings[75914]="你准备好动真格的了吗？"
D.Strings[75915]="长鳞片的害虫！"
D.Strings[75916]="随时为您效劳，$g主人:女主人;。"
D.Strings[75917]="菲拉克，我需要更多的永茂之种。"
D.Strings[75918]="种子用完了？$B$B为了补偿你从大地上偷走的木材，我会再给你一包种子的。"
D.Strings[75919]="不，仪式不是那样的！再试一次。"
D.Strings[75920]="错了！每个小错误都会削弱仪式的力量。快，按我说的做，或许还可以补救。"
D.Strings[75921]="鸦母在上……你到底有没有集中精神？再来。"
D.Strings[75922]="不，那不对。我们再试一次。"
D.Strings[75923]="这种速度是没法让黑手满意的！加把劲儿！"
D.Strings[75924]="快挖！快挖！我们需要这些矿石！"
D.Strings[75925]="干得好，伙计们！再接再厉！"
D.Strings[75926]="准备与暗影议会战斗。"
D.Strings[75927]="潜行侦测系统上线。隐形照明弹启动……"
D.Strings[75928]="系统关闭……"
D.Strings[75929]="火车不会再经过这里了……对吧？"
D.Strings[75930]="我觉得我们不应该站在这些轨道上。"
D.Strings[75931]="我们真的要这么靠近这些轨道吗？"
D.Strings[75932]="我这就去你的要塞，指挥官！"
D.Strings[75933]="你跟错了国王！"
D.Strings[75934]="邪教渣滓！"
D.Strings[75935]="我们在你的要塞见，指挥官！"
D.Strings[75936]="回来，你这个畜生！"
D.Strings[75937]="呱呱！为了安苏！"
D.Strings[75938]="说真的！到底是谁给这些蛇插上了翅膀？！"
D.Strings[75939]="抱歉了，大家伙。"
D.Strings[75940]="看看那个家伙的体格！我们最好快点打倒它。"
D.Strings[75941]="我们去鸦爪祭坛吧。"
D.Strings[75942]="我们快去找卡德加和其他人吧。"
D.Strings[75943]="他在这儿。"
D.Strings[75944]="我们走吧。卡德加就在这附近。"
D.Strings[75945]="你来得很及时，凡人。我们必须阻止塞泰克。"
D.Strings[75946]="你们来得正是时候。见证虚空的威严吧！"
D.Strings[75947]="我期待看到你的要塞，指挥官。"
D.Strings[75948]="看我的脸正中你的锤子！等等……我说反了。"
D.Strings[75949]="这是个战斗的好日子，对吧，指挥官？"
D.Strings[75950]="这些蠢货以为他们能赢？哈"
D.Strings[75951]="光荣地死去吧。"
D.Strings[75952]="你已经失败了，基尔加丹。兽人没有如你保证的那样喝下玛诺洛斯的鲜血。"
D.Strings[75953]="我们将用燃烧军团的无穷力量夺取这个世界。阴谋诡计已经是过去式了。"
D.Strings[75954]="莫格索德大人，召集你的部队。进攻的时机就要到了。"
D.Strings[75955]="是时候了，莫格索德。古尔丹的任务就快完成了。"
D.Strings[75956]="阿扎凯尔，你将是我们的前锋。带头发起冲锋吧。"
D.Strings[75957]="德莱尼的灵魂将壮大我们。所有活下来的兽人和德莱尼都将成为我们的傀儡。"
D.Strings[75958]="是的……奥金顿将属于我们。传送门马上要完成了，我们将发动全面入侵。"
D.Strings[75959]="天空将降下火雨……海水将被鲜血染红……"
D.Strings[75960]="|TInterface\\Icons\\INV_Fabric_Felcloth_Ebon.blp:20|t|cFFFF0404|Hspell:161242|h[腐蚀能量]|h|r开始流向$n。"
D.Strings[75961]="告诉佩妮，你在想什么。"
D.Strings[75962]="你正好撞到我的枪口上了，伙计。"
D.Strings[75963]="准备……跑！"
D.Strings[75964]="我要在黑暗中射击……"
D.Strings[75965]="知道他们为什么叫我殴底吗？因为我最擅长踢人屁股！"
D.Strings[75966]="你不该来惹我的！"
D.Strings[75967]="知道什么能和高速子弹飞得一样快吗？子弹。"
D.Strings[75968]="我需要换把大枪来对付这家伙吗？"
D.Strings[75969]="你跑得晚了点，对吧？"
D.Strings[75970]="我的笑话能杀人！"
D.Strings[75971]="你会爱上火药的味道的。"
D.Strings[75972]="高速飞行的子弹才是最好的子弹。"
D.Strings[75973]="又一个浑身冒烟的倒霉蛋！"
D.Strings[75974]="谁还不服？！"
D.Strings[75975]="他们甚至不值得我浪费子弹。"
D.Strings[75976]="嘿，指挥官！"
D.Strings[75977]="需要火枪手吗？"
D.Strings[75978]="有时我会用斧子把树砍倒。有时我会直接炸飞它们。"
D.Strings[75979]="看看你的要塞，你就会发现它是传统地精工程学的杰作！"
D.Strings[75980]="咦……你有点眼熟……噢，嗨，指挥官！"
D.Strings[75981]="随便说，快点说，说点有用的，小土豆！"
D.Strings[75982]="德拉诺很酷，不是吗？一个有待爆炸的……呃……探索的新世界。"
D.Strings[75983]="这和我……想的不一样……"
D.Strings[75984]="我的十字弓已经瞄准你了。"
D.Strings[75985]="它会是什么呢，斧子还是十字弓？"
D.Strings[75986]="瞄准练习！"
D.Strings[75987]="你敢叫我懦夫？！"
D.Strings[75988]="看来有人想找揍了！"
D.Strings[75989]="让我的斧子跟你问个好。"
D.Strings[75990]="别跑啊！"
D.Strings[75991]="别再失败了。"
D.Strings[75992]="你那个榆木脑袋出什么问题了？"
D.Strings[75993]="乘胜追击！"
D.Strings[75994]="我说了别那么看我。"
D.Strings[75995]="你肯定是第一次遇见黑铁矮人。"
D.Strings[75996]="我最后警告你一次……呃……喔唷。"
D.Strings[75997]="帮我向你的老祖宗问个好。"
D.Strings[75998]="别放松警惕！"
D.Strings[75999]="我的斧子上又多了一个缺口。"
D.Strings[76000]="木头，我都不认识你！"
D.Strings[76001]="你喜欢泡吧吗？"
D.Strings[76002]="你有个好地方，指挥官。"
D.Strings[76003]="厕所在哪儿？"
D.Strings[76004]="你是哪种酒？听得懂吗？"
D.Strings[76005]="啊，你这混蛋！"
D.Strings[76006]="我不关心你跟德莱尼的那点宿怨……但他们的灵魂对我们依然有用。"
D.Strings[76007]="不知道你的骨头是什么样……"
D.Strings[76008]="棍棒和石头会敲碎你的骨头。"
D.Strings[76009]="艾苏克来对付你了！"
D.Strings[76010]="哈哈！哈哈！哈哈哈哈哈哈！"
D.Strings[76011]="我喜欢杀人！还有骨头！"
D.Strings[76012]="你的骨头归我了！"
D.Strings[76013]="这是什么？艾苏克有新朋友了？"
D.Strings[76014]="不过是一堆骨头。"
D.Strings[76015]="该抽掉这家伙的骨头了。"
D.Strings[76016]="你真是太不走运了。"
D.Strings[76017]="又多了一件收藏品。"
D.Strings[76018]="兽人和德莱尼都将臣服于燃烧军团。他们脚下的土地将在我们的大军面前化为焦土。只要携手合作，基尔加丹，我们就是不可战胜的。"
D.Strings[76019]="别让你的骨头染上太多血！"
D.Strings[76020]="有人想踢这具尸体吗？"
D.Strings[76021]="来折磨我的灵魂吧。"
D.Strings[76022]="还记得万灵让我跟那头玛戈隆交谈的事吗？真见鬼。"
D.Strings[76023]="很高兴看到你的骨头还完好无缺，指挥官。"
D.Strings[76024]="艾苏克将在你的要塞徘徊。这是好事。"
D.Strings[76025]="你确定自己不是出生于嘲颅氏族吗？"
D.Strings[76026]="在我说话时，我们的兽人炮灰已经准备好传送到奥金顿的核心地带了。我们将吞噬他们的灵魂，开启燃烧军团的全盛时代。"
D.Strings[76027]="指挥官，你的骨架很迷人。"
D.Strings[76028]="有时吓唬别人也是很有意思的。"
D.Strings[76029]="你的到来令艾苏克倍感荣幸。"
D.Strings[76030]="今晚，我们将畅享杀戮的盛宴！"
D.Strings[76031]="我不再信仰我的先祖了。但我信你。干掉他们。"
D.Strings[76032]="你们将宣告这个世界的末日。"
D.Strings[76033]="没有人能阻止你们的力量。涌入这个世界……尽情享用吧！"
D.Strings[76034]="你不是第一个跟我作对的人。"
D.Strings[76035]="祝你万事不顺，命不久矣。"
D.Strings[76036]="就算是德莱尼的耐心也是有限的。"
D.Strings[76037]="你喜欢死在刀剑还是长弓之下？选一个吧。"
D.Strings[76038]="这将是你的最后一课。"
D.Strings[76039]="这么死掉都算是便宜你了。"
D.Strings[76040]="你需要急救吗？"
D.Strings[76041]="好好去死吧，短命种。"
D.Strings[76042]="享受最后的安息吧。"
D.Strings[76043]="记住这个死亡的教训吧。"
D.Strings[76044]="现在你知道跟我作对的下场了吧？"
D.Strings[76045]="真高兴再次见到你。"
D.Strings[76046]="谢谢你邀请我来这儿。"
D.Strings[76047]="我的训练没能发挥作用……"
D.Strings[76048]="我记得我不是来干这个的。"
D.Strings[76049]="或许结束之后我们能去喝一杯。"
D.Strings[76050]="噢，还没开始呢……我掉了一只鞋。"
D.Strings[76051]="来尝尝我的厉害吧，伙计！"
D.Strings[76052]="好像涨潮了！"
D.Strings[76053]="坐下吧，笨蛋。"
D.Strings[76054]="我想这里不太欢迎你。"
D.Strings[76055]="那家伙是个人物。"
D.Strings[76056]="我又钓上来一个！"
D.Strings[76057]="你被判有罪。哈！"
D.Strings[76058]="站起来吧，燃烧军团，将这个世界化为灰烬！"
D.Strings[76059]="要给你来一杯吗，指挥官？"
D.Strings[76060]="来钓钓鱼吧？"
D.Strings[76061]="你有没有把脚放到冰冷的水里去过？"
D.Strings[76062]="我在这儿就好像是离了水的鱼一样，指挥官。"
D.Strings[76063]="这个要塞恐怕连水坑都没有吧？"
D.Strings[76064]="呃，好吧……这也没什么大不了的……"
D.Strings[76065]="拿着我的鱼钩、鱼线和铅锤吧。"
D.Strings[76066]="沉入深海……"
D.Strings[76067]="喔唷，我上钩了！"
D.Strings[76068]="德拉诺将化为火海！"
D.Strings[76069]="中士，暗影议会来攻击我们了！"
D.Strings[76070]="你救过我一次，现在轮到我来报答你了！"
D.Strings[76071]="空气开始变得污浊了……"
D.Strings[76072]="暗影议会？是恶魔！敲响警钟！"
D.Strings[76073]="士兵们，各就各位！其他人，注意隐蔽。所有信仰圣光的人，开始祈祷吧。"
D.Strings[76074]="我看到了，决战的时候到了。就是现在，士兵们。冲锋！"
D.Strings[76075]="兄弟姐妹们，从战友那里汲取力量吧。"
D.Strings[76076]="愿万灵指引我。"
D.Strings[76077]="现在的风向对你不利。"
D.Strings[76078]="我没时间接受挑衅。"
D.Strings[76079]="你在挑战我的耐心。"
D.Strings[76080]="请允许我向你介绍一个朋友，废物。"
D.Strings[76081]="我能赤手空拳扳倒树木。你不算什么。"
D.Strings[76082]="记住，瞄准脑袋和心脏。别害怕，恐惧只会害死你们。"
D.Strings[76083]="狂风在对我说话。"
D.Strings[76084]="大地母亲与我同在。"
D.Strings[76085]="让大风刮走你。"
D.Strings[76086]="你不过是一堆灰烬。"
D.Strings[76087]="滚回到尘土中去吧。"
D.Strings[76088]="让我在这里洒下一些灰烬……"
D.Strings[76089]="没跑掉。"
D.Strings[76090]="这家伙死得真快。"
D.Strings[76091]="愿狂风指引你的脚步，指挥官。"
D.Strings[76092]="保持平静，指挥官。"
D.Strings[76093]="大地母亲与你同在。"
D.Strings[76094]="无限风光在险峰。"
D.Strings[76095]="风在往哪个方向吹？"
D.Strings[76096]="只要你愿意倾听，就会发现这片土地上的风在低语。"
D.Strings[76097]="如果无人倾听，林中的风声还会存在吗？"
D.Strings[76098]="散开！别让他们站稳脚跟！"
D.Strings[76099]="指挥官，万灵都在传颂你的勇敢。"
D.Strings[76100]="我们都是风中的微尘。"
D.Strings[76101]="我们把他们赶回去了吗？"
D.Strings[76102]="计划不是这样的……"
D.Strings[76103]="利爪卫士，将碎岩峰下的祭坛准备好。"
D.Strings[76104]="英雄，到你粉碎邪教的地方来找我们吧。"
D.Strings[76105]="那么，罗本，今天是什么汤？"
D.Strings[76106]="是豆瓣汤。"
D.Strings[76107]="噢，我妈妈以前最爱做豆瓣汤了。那些橙色的切片是什么？"
D.Strings[76108]="是胡萝卜，我们的新盟友带回来的。"
D.Strings[76109]="有意思，我很想尝一尝。"
D.Strings[76110]="我想它一定很好喝。再见，罗本。"
D.Strings[76111]="谢谢，请告诉我你的感想。"
D.Strings[76112]="呃……我感觉不太好……嗝！"
D.Strings[76113]="你要找碴吗？……嗝！"
D.Strings[76114]="你竟敢反抗鲁克玛？"
D.Strings[76115]="你的存在就是对我们的侮辱！"
D.Strings[76116]="鲁克玛抛弃了我。"
D.Strings[76117]="竟然被肮脏的流亡者和外来的废物击败了！"
D.Strings[76118]="我将接受鲁克玛的审判。"
D.Strings[76119]="鲁克玛又得到了一个祭品！"
D.Strings[76120]="你这废物！"
D.Strings[76121]="你也想跟那些奴隶一样吗？为什么说不呢？"
D.Strings[76122]="不要殴打奴隶？你真搞笑！"
D.Strings[76123]="我恨入侵者！"
D.Strings[76124]="放奴隶走？你这蠢货！"
D.Strings[76125]="我的肠子怎么跑出来了？"
D.Strings[76126]="好痛！等等，又麻了。这下好多了！"
D.Strings[76127]="该睡觉了……"
D.Strings[76128]="这不公平！"
D.Strings[76129]="你不想再玩了吗？"
D.Strings[76130]="你看起来冷冰冰的。给你火！"
D.Strings[76131]="魔法能让奴隶听话！"
D.Strings[76132]="|TInterface\\Icons\\ability_fixated_state_red:20|t一头怪物|cFFFF0000锁定|r了你！它将不断追逐你，直至死亡！"
D.Strings[76133]="让我们给这些疯狗喂点药吧。"
D.Strings[76134]="折磨你一定会很有趣的。"
D.Strings[76135]="我要把你的脑袋留作纪念！"
D.Strings[76136]="你就这么急着送死吗？"
D.Strings[76137]="我要让你求死不得！"
D.Strings[76138]="我的死亡毫无意义。"
D.Strings[76139]="我的痛苦结束了。"
D.Strings[76140]="卡加斯会不高兴的。"
D.Strings[76141]="痛苦……的感觉如此美妙……"
D.Strings[76142]="哈哈！干掉一个！"
D.Strings[76143]="已经准备好受死了吗？可怜虫！"
D.Strings[76144]="我简直懒得杀你。"
D.Strings[76145]="真无聊。你该去死了。"
D.Strings[76146]="差劲的战斗，真是浪费我的时间。"
D.Strings[76147]="磨魂者的食物送上门了！"
D.Strings[76148]="波加尔不喜欢你。我也不喜欢你！"
D.Strings[76149]="奴隶不需要灵魂！你这蠢货！"
D.Strings[76150]="入侵者必须死！"
D.Strings[76151]="波加尔说我不会死的。波加尔撒谎！"
D.Strings[76152]="磨魂者要吃我了？"
D.Strings[76153]="我的血！它流走了！"
D.Strings[76154]="光怎么熄灭了？"
D.Strings[76155]="帮我把这些蛇一样的东西放回肚子里！"
D.Strings[76156]="嘿，我们在这儿干活呢！"
D.Strings[76157]="你想找揍吗？"
D.Strings[76158]="你死得也太快了！下次死慢点！"
D.Strings[76159]="别来妨碍我！"
D.Strings[76160]="让磨魂者吃了你！"
D.Strings[76161]="磨魂者让我的魔法更强大了！"
D.Strings[76162]="我的狼将撕碎你的血肉！"
D.Strings[76163]="我们发现这些动物的手段是完全公正合法的！"
D.Strings[76164]="别用你的脏手碰我们的货物！"
D.Strings[76165]="别为了这些动物枉送了性命！"
D.Strings[76166]="孩子们，来帮帮我……"
D.Strings[76167]="这些鸟绝对能让我们发大财。退后！"
D.Strings[76168]="让风暴吞噬你！"
D.Strings[76169]="什么工作都不值得……赔上性命……"
D.Strings[76170]="告诉我妻子我……啊，算了吧。"
D.Strings[76171]="让阴影吞噬你！"
D.Strings[76172]="呃……这下糟了。"
D.Strings[76173]="把我和……我的金子埋在一起。"
D.Strings[76174]="计算……错误……"
D.Strings[76175]="我的头……好痛……"
D.Strings[76176]="噢……这可真疼。"
D.Strings[76177]="你只会死在这里。"
D.Strings[76178]="我将回归元素的怀抱……"
D.Strings[76179]="这似乎是个坏主意……"
D.Strings[76180]="在战歌的利斧前瑟瑟发抖吧！"
D.Strings[76181]="我……应该多带……几把斧子的……"
D.Strings[76182]="现在……谁来保护……我的小宝贝？"
D.Strings[76183]="为什么大家都这么爱打仗？我们就不能给和平一次机会吗？"
D.Strings[76184]="总有一天，我们将和平共处。但愿如此……"
D.Strings[76185]="你的鲜血将带给我力量！"
D.Strings[76186]="塞泰在召唤我……"
D.Strings[76187]="你不是碎手剧毒的对手！"
D.Strings[76188]="你的死期就快到了……"
D.Strings[76189]="闯入者！你休想染指埃匹希斯的生物！"
D.Strings[76190]="鲁克玛会为我复仇的……"
D.Strings[76191]="再次感谢你在纳格兰对我的帮助，伙计。自从我沦为巫妖王的仆从之后，我最想做的事就是能好好钓一次鱼。\n\n你知道，德拉诺这地方比诺森德适合钓鱼多了。你不用再担心那些浮冰，而且鱼也没有那么凶猛。"
D.Strings[76192]="我要用我的符文剑活剐了你，伙计！"
D.Strings[76193]="你的灵魂会成为不错的巫毒鱼饵！"
D.Strings[76194]="或许我可以试试符文熔铸的鱼竿。"
D.Strings[76195]="钢铁部落将为他们对卡拉波的所作所为付出代价。"
D.Strings[76196]="想夺走剑圣的武器无异于送死。"
D.Strings[76197]="你准备好传送后就进入传送门吧。你将被直接传送到阿什兰岛的暴风之盾。\n\n不用怕，暴风之盾不会让你自动进入PVP状态的。"
D.Strings[76198]="你准备好传送后就进入传送门吧。你将被直接传送到阿什兰岛的战争之矛。\n\n不用怕，战争之矛不会让你自动进入PVP状态的。"
D.Strings[76199]="我准备好传送到阿什兰的暴风之盾了！"
D.Strings[76200]="我准备好传送到阿什兰的战争之矛了！"
D.Strings[76201]="到碎岩峰来我吧。"
D.Strings[76202]="凯斯米特，快坐下来吃点东西吧。"
D.Strings[76203]="放手，你这肮脏的小偷！"
D.Strings[76204]="你好，指挥官！$b$b今天还好吗？"
D.Strings[76205]="图拉，今天饭菜还是一如既往的丰盛。"
D.Strings[76206]="你的帮手们怎么样了？"
D.Strings[76207]="他们都很好。乌瑞尔让我向你问好。"
D.Strings[76208]="他问你收成怎么样。今天钓到的鱼多吗？"
D.Strings[76209]="还行。"
D.Strings[76210]="我明天得下去跟乌瑞尔谈谈了。我还去阿列克谢那里一趟，买些新鱼饵。"
D.Strings[76211]="那对你有好处。你在上面待得太久了。"
D.Strings[76212]="凯斯米特咕哝着。"
D.Strings[76213]="图拉笑了笑。"
D.Strings[76214]="前线的情况如何，$n？"
D.Strings[76215]="只要一个铜板，我就能把所有联盟人的喉咙割断！"
D.Strings[76216]="我来去如风。"
D.Strings[76217]="照料马匹可没有看起来那么轻松，但至少你可以享受户外的新鲜空气。"
D.Strings[76218]="你，就是你！能帮我一个忙吗？跟这些蠢货的想法正相反，其实我还没死呢。至少从字面意义上来说，我还没死。"
D.Strings[76219]="谢谢你，指挥官。我这就回你的要塞去。我想你的要塞应该离这里不远。"
D.Strings[76220]="%s陷入了|cFFFF0404|Hspell:155539|h[毁灭之怒]|h|r！"
D.Strings[76221]="我要响应热砂港的召唤前去帮忙。送我去阿兰卡峰林。"
D.Strings[76222]="你会需要我的！我有你要的消息，帮帮我，伙计！"
D.Strings[76223]="你惹错人了，伙计，这个新的钢铁部落救了我！"
D.Strings[76224]="你好，指挥官，祝你一路顺风。"
D.Strings[76225]="幽灵们！抓住他们！"
D.Strings[76226]="啊！这些喷火者根本没用，我们快被它活吃了！"
D.Strings[76227]="撤退！扔掉武器，撤到船上去！"
D.Strings[76228]="|TInterface\\Icons\\spell_fire_felfirenova.blp:20|t你受到了|cFFFF0404|Hspell:172895|h[魔能散射：邪能]|h|r的影响！"
D.Strings[76229]="午安，指挥官！"
D.Strings[76230]="我们马上就能大丰收了。"
D.Strings[76231]="我们支持你，指挥官。"
D.Strings[76232]="只要法师打开通向奥格瑞玛的传送门，这个地方就会开始繁荣起来。我们说不定会在德拉诺这一边见到海量的商人和货物。"
D.Strings[76233]="有兴趣在这里钓钓鱼吗？"
D.Strings[76234]="蠢乌鸦！"
D.Strings[76235]="<荣耀圣坛静静地等待着供品。>"
D.Strings[76236]="<将供品放在荣耀圣坛上。>"
D.Strings[76237]="在这个血腥的竞技场里，荣耀就是一切！将敌人的破碎骨骼放在圣坛上，你就能获得胜利者的礼物。"
D.Strings[76238]="被诅咒的鸦人摆脱了塞泰的威胁，但他们的天空仍在熊熊燃烧。"
D.Strings[76239]="他们需要渡鸦的帮助。来泰罗克鸦巢找我吧。"
D.Strings[76240]="|Hunit:77182:Oregorger|h奥尔高格准备施放|cFFFF0000|Hspell:156879|h[黑石弹幕]|h|r。"
D.Strings[76241]="我在试图营救乔比时被守卫抓住了。他欠我一个人情。"
D.Strings[76242]="我迟到了一点。你的斥候已经死了……情况比我想象的还要糟糕。钢铁部落的入侵已经开始了。你自己保重。"
D.Strings[76243]="你的失败让我发笑。哈哈哈！"
D.Strings[76244]="下次再多杀几个。这点还不够！"
D.Strings[76245]="那下可真够狠的。"
D.Strings[76246]="我还没杀完呢。"
D.Strings[76247]="多杀几个！"
D.Strings[76248]="让我们在他们脸上刻上笑容吧。"
D.Strings[76249]="好好学学怎么揍人吧。"
D.Strings[76250]="还不错。"
D.Strings[76251]="我们的死期还没到呢。"
D.Strings[76252]="他们以为自己表现很好？"
D.Strings[76253]="这真让人……失望。"
D.Strings[76254]="一场精彩的战斗！"
D.Strings[76255]="开始跑吧，我可以让你几步……"
D.Strings[76256]="我们可能需要更多猎物了。"
D.Strings[76257]="我蒙上眼睛都能干掉你。"
D.Strings[76258]="继续练习吧，指挥官。"
D.Strings[76259]="真精彩，指挥官。"
D.Strings[76260]="你已经是出色的生存专家了。"
D.Strings[76261]="你应该多训练一下，指挥官。"
D.Strings[76262]="还不错！回竞技场去吧！"
D.Strings[76263]="这才是真正的战斗！"
D.Strings[76264]="我是来还你人情的。"
D.Strings[76265]="为了斯克提斯！"
D.Strings[76266]="你太相信你的眼睛了，蠢货。"
D.Strings[76267]="我以为你能做得更好。"
D.Strings[76268]="很好，你有进步。"
D.Strings[76269]="对！按这个速度，我很快就能还清欠你的人情了。"
D.Strings[76270]="我试图将莉迪亚救出去，可是失败了。你觉得她会感谢我吗？"
D.Strings[76271]="卖力点！多挖点石头！"
D.Strings[76272]="这些石头是不会自己裂开的！"
D.Strings[76273]="干活！干活！"
D.Strings[76274]="我必须立刻通知乌瑞恩国王。保持警惕，$c。黑暗的时刻在前面等着你。"
D.Strings[76275]="姆格曾经和这些兽人一样做过苦工，可我是这里最会挖石头的苦工！\n\n现在，他们给了姆格一个名字“石裂”，并让我来管这些小家伙。我跟你说，这是最好的工作了！"
D.Strings[76276]="姆格这家伙真不错。看着他对那些苦工大喊大叫真的很提神。\n\n等我们挖完这些石头，或许我会雇请他参加我的一些行动。"
D.Strings[76277]="嘿！你有什么毛病，干嘛带着这群暴徒来干扰我做生意？"
D.Strings[76278]="生意？！你在这里掠夺的可是无价的神器！"
D.Strings[76279]="按照我的经验，“无价”就是非常昂贵的意思。那你想让我怎么做，把它们交出来？"
D.Strings[76280]="部落需要那些神器！要想在这场战争中占得上风，我们就得研究它们。"
D.Strings[76281]="你还没有回答我的问题。"
D.Strings[76282]="听着，你们这些讨厌的小绿皮！交出所有的神器，否则我们就强迫你们交出来！"
D.Strings[76283]="放轻松，伙计，我给你打个折怎么样，这样你也好交差。九五折怎么样？"
D.Strings[76284]="有道理，九折。如果我是你，我就不会再那么荒谬地讨价还价了。锈水财阀可不好惹。"
D.Strings[76285]="你疯了吗？"
D.Strings[76286]="这些神圣遗物学会的家伙看起来好像是认真的。\n\n在我看来，这对我们的生意可是个大麻烦。"
D.Strings[76287]="我必须立刻通知沃金酋长。保持警惕，$c。黑暗的时刻在前面等着你。"
D.Strings[76288]="需要保镖吗？虽然你不需要，但我也能帮你杀敌的。"
D.Strings[76289]="当然，我正需要一个打手呢。"
D.Strings[76290]="你的订单已经提交了。"
D.Strings[76291]="聚集你的鲜血，重获新生吧！"
D.Strings[76292]="%s安慰你。"
D.Strings[76293]="%s要跟你击掌庆祝！"
D.Strings[76294]="你休想从我这里通过！"
D.Strings[76295]="你的脑袋会是一个不错的战利品！"
D.Strings[76296]="这下是为了我的祖父！"
D.Strings[76297]="呃……你的血都溅到我的胡子上了。"
D.Strings[76298]="为您效劳，指挥官。"
D.Strings[76299]="你想干什么？呃……指挥官。"
D.Strings[76300]="需要杀敌的话，尽管告诉我。"
D.Strings[76301]="上阵杀敌的时候到了吗？"
D.Strings[76302]="死亡……你的毒钩在哪里？"
D.Strings[76303]="我要回家了，爸爸……"
D.Strings[76304]="呸……只是一点……皮外……伤……"
D.Strings[76305]="这血是我的还是你的？……显然是我的……"
D.Strings[76306]="没时间了，我们得重新开始仪式了。所有人就位，我们再次一次！"
D.Strings[76307]="时间用完了，我们得再试一次。请再协助我们举行一次仪式。"
D.Strings[76308]="%s满怀敬意地向你致礼。"
D.Strings[76309]="肮脏的强盗！你的走狗将变成我的晚餐！"
D.Strings[76310]="或许你还没做好举行仪式的准备？没关系，我们可以再来一次。"
D.Strings[76311]="噢，这家伙看起来很好吃！"
D.Strings[76312]="谢谢你，指挥官。以我的荣誉发誓，我不会让你失望的。"
D.Strings[76313]="你今天能提供些什么物资？"
D.Strings[76314]="干活，干活！"
D.Strings[76315]="哈！钓到一个。"
D.Strings[76316]="你惹错暗夜精灵了！"
D.Strings[76317]="我从来不留俘虏。"
D.Strings[76318]="这也没什么难的。"
D.Strings[76319]="危险在哪儿？"
D.Strings[76320]="我时刻保持警惕。"
D.Strings[76321]="你需要我的帮助吗？"
D.Strings[76322]="你想挑衅荒野吗？"
D.Strings[76323]="自然指引着我！"
D.Strings[76324]="愿穆莎指引你的灵魂。"
D.Strings[76325]="愿月亮指引你的道路。"
D.Strings[76326]="与自然融为一体吧，指挥官。"
D.Strings[76327]="嘘，听。清风在低语……"
D.Strings[76328]="我……看见了……圣光……"
D.Strings[76329]="谁敢来挑战强大的斯库戈？！"
D.Strings[76330]="将这些入侵者的尸体带来给我。"
D.Strings[76331]="这些胆敢闯入斯库戈的王国的……是什么……东西？"
D.Strings[76332]="需要我们做什么吗？"
D.Strings[76333]="加兹鲁维需要你。"
D.Strings[76334]="好嘞，没问题。"
D.Strings[76335]="太好了！烧死他们！来吧，我们还有很多事要商量。"
D.Strings[76336]="写呀写，写上一整天。抄呀抄，美妙的文字流出来。"
D.Strings[76337]="血鬃部族的攻击来自南边的山路。只要沿着那条路走，你就能找到他们藏身的山谷了。"
D.Strings[76338]="我发誓消灭德拉诺的所有人类。"
D.Strings[76339]="你选择了人类作为你的宿敌。\n\n你确定吗？"
D.Strings[76340]="圣光必胜……因为有我们在对抗黑暗。"
D.Strings[76341]="你选择了德莱尼作为你的宿敌。\n\n你确定吗？"
D.Strings[76342]="你选择了暗夜精灵作为你的宿敌。\n\n你确定吗？"
D.Strings[76343]="你选择了侏儒作为你的宿敌。\n\n你确定吗？"
D.Strings[76344]="你选择了狼人作为你的宿敌。\n\n你确定吗？"
D.Strings[76345]="你选择了矮人作为你的宿敌。\n\n你确定吗？"
D.Strings[76346]="你选择了熊猫人作为你的宿敌。\n\n你确定吗？"
D.Strings[76347]="明智的选择。人类就是这个世界的祸害，必须被消灭或者赶出德拉诺。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76348]="德莱尼……$B$B<拉扎库尔吐了口口水。>$B$B要是你能把这片土地上的德莱尼赶尽杀绝，那真是帮了这个世界的原住民一个大忙了。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76349]="套索断了！野兽逃跑了！"
D.Strings[76350]="我发誓消灭德拉诺的所有德莱尼。"
D.Strings[76351]="我发誓消灭德拉诺的所有熊猫人。"
D.Strings[76352]="我发誓消灭德拉诺的所有矮人。"
D.Strings[76353]="我发誓消灭德拉诺的所有狼人。"
D.Strings[76354]="我发誓消灭德拉诺，以及所有已知位面的所有侏儒。"
D.Strings[76355]="我发誓消灭德拉诺的所有暗夜精灵。"
D.Strings[76356]="我们一定要守住神殿。我绝不接受其他结果。"
D.Strings[76357]="我们成功了，$n！卡拉的能量消灭了钢铁部落的残余部队。$B$B我们安全了。"
D.Strings[76358]="这些入侵我们土地的狼人和本地的刃牙虎人一样凶残且充满了兽性，但却缺乏它们的生存意识。让他们的死亡给其他所谓的“联盟”成员一个教训吧。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76359]="这些熊猫人本有机会加入你的强大部队，却选择了背叛部落，加入敌人的阵营。现在，他们又开始帮助德莱尼屠杀兽人。背叛部落的联盟熊猫人必须死。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76360]="不管是源自自然变异还是你那个世界的诸神的残酷玩笑，侏儒都没有生存的价值。只有将他们灭绝，才能让更强大的物种有崛起的空间。你必将成为消灭他们的急先锋！$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76361]="指挥官，看看这个。我们发现了一具钢铁之星，那边的塞林帮我将它完全发动了起来。\n\n如果你想试一试的话，我想它应该已经可以开动了。\n\n卡德加和其他人说他们会在港口的入口处等你。或许你可以用它顺手干掉沿路上遇到的钢铁部落渣滓。"
D.Strings[76362]="谢谢。我这就去码头上找他们。"
D.Strings[76363]="万岁，指挥官。我们发现了一具能够修好的钢铁之星，那边的加兹鲁维帮我将它修好了。\n\n等你准备好时，它应该也能动了。\n\n卡德加说他和其他人会在港口的入口处等你。或许你可以开着它顺手压死沿路上遇到的钢铁部落渣滓。"
D.Strings[76364]="嘿，真是头好家伙，指挥官。我这就把它带回兽栏去。"
D.Strings[76365]="暗夜精灵全是一群阴谋家。我们一定要干掉暗夜精灵入侵者，把他们全送去见他们的月神！$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76366]="矮人是联盟不可或缺的组成部分，因为他们是战争机器的制造者。就因为这个，他们也必须死。不要对他们手软，因为敌人也不会的。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76367]="我改变主意了。我觉得另一个敌人更值得承受我的怒火。"
D.Strings[76368]="泰克图斯将他的晶化弹幕对准了你！"
D.Strings[76369]="我们是不可战胜的！"
D.Strings[76370]="还有额外的神器碎片吗，$n？我的朋友艾希兰姆可能会用得上它们。"
D.Strings[76371]="如果你交给克里斯·克拉奇一些牛头人蹄子，他就会好好奖赏你的。$B$B但我也不明白是为什么。"
D.Strings[76372]="我……呃……"
D.Strings[76373]="这个岗哨后面就是暴风之盾堡垒了。如果你不喜欢打打杀杀的话，我建议你最好离它远点。"
D.Strings[76374]="如果你要进去的话，能帮我给大门口的达马库斯和维萨普问个好吗？他们肯定想我了。"
D.Strings[76375]="别来烦我！"
D.Strings[76376]="这个世界是不会天上掉馅饼的，$n。承受苦难是我们的命运……奋起反抗则是我们的天职。$b$b\n这个部落是我们的家！我们不可能总是其乐融融。我们也有过争斗。但当我们团结起来——啊——这个部落就无所不能了。"
D.Strings[76377]="我的兄弟们……会为我复仇的……"
D.Strings[76378]="战歌的敌人必须死！"
D.Strings[76379]="你不会有好下场的。"
D.Strings[76380]="不要对他们手软！"
D.Strings[76381]="我们是钢铁的战争之手！"
D.Strings[76382]="钢铁的风暴降临了！"
D.Strings[76383]="你们这些蛆虫竟敢反抗我们？"
D.Strings[76384]="杂种。你们被包围了！"
D.Strings[76385]="你将要开展一个危险的任务，而且可能无法立即返回。你确定要开始吗？"
D.Strings[76386]="嗯……我还会用到你的迅猛龙的。"
D.Strings[76387]="臣民们，城市失守了！我们必须放弃宫殿！"
D.Strings[76388]="大门被攻破了！他们来抢石头了！"
D.Strings[76389]="……归于……圣光……"
D.Strings[76390]="好痛苦……谢谢你……"
D.Strings[76391]="……你很……善良……"
D.Strings[76392]="愿圣光……保……佑你……"
D.Strings[76393]="很高兴你能安全抵达这里。准备好了吗？"
D.Strings[76394]="你不感到欣慰吗？"
D.Strings[76395]="剩下的故事就等你从鸦爪岗哨回来再说吧。"
D.Strings[76396]="啊，多亏了你从艾吉斯那里夺回的手镯，我们可以直接见证泰罗克的贬落了。"
D.Strings[76397]="这份礼物肯定会非常有用的——但我们还需要鸦爪祭司来举行仪式。"
D.Strings[76398]="小心行事，陌生人。我还不习惯有访客来到这片荒野。"
D.Strings[76399]="有了它，我们就能深入研究泰罗克的贬落了。"
D.Strings[76400]="历史里有许多值得我们学习的东西。"
D.Strings[76401]="一条巨型食腐蛆虫闻到了它的下一顿大餐！"
D.Strings[76402]="<半兽人从魔法牢笼里向你咆哮。她的眼中充满了火焰和仇恨——显然古尔丹依然完全控制着她。>"
D.Strings[76403]="我一直在苦苦磨练我的技艺，陌生人。在我看来，再也没有比欣赏和反映这个世界的美丽更伟大的追求了。"
D.Strings[76404]="不要死……拜托！尼娅米告诫过我不能再失败的！\n"
D.Strings[76405]="你好，勇士。$b$B我是自愿加入远征队，来考察德拉诺的奇异物种的。$b$b如果你在旅途中发现了什么奇怪的东西，我很希望能够检查一番。"
D.Strings[76406]="仪式之火争夺战将在3分钟后开始！"
D.Strings[76407]="%s开始施放|TInterface\\Icons\\ability_priest_voidentropy.blp:20|t |cFFFF0404|Hspell:174016|h[残杀]|h|r！快进入中和之地！"
D.Strings[76408]="快，大主教。让死者借你之口说话吧。"
D.Strings[76409]="故事时间结束！"
D.Strings[76410]="我们找到他了……"
D.Strings[76411]="采石场争夺战将在3分钟后开始！"
D.Strings[76412]="斗兽场争夺战将在3分钟后开始！"
D.Strings[76413]="这不可能！我的凝视是……永不……"
D.Strings[76414]="那个无能的鸦人以为他能奴役我，可没有人能控制虚空永恒的凝视！"
D.Strings[76415]="你说了算，头儿。我在外面等你。"
D.Strings[76416]="你也会遭遇相同的命运！"
D.Strings[76417]="带路吧，头儿。"
D.Strings[76418]="托莫克，回兵营去。"
D.Strings[76419]="好的，头儿。"
D.Strings[76420]="这个特别的鸦人的致命伤似乎来自某种强力黑暗魔法。\n\n但无论是什么造成了这些伤口，现在都已消失无踪了。"
D.Strings[76421]="这没用。"
D.Strings[76422]="|TInterface\\Icons\\ACHIEVEMENT_PVP_H_H.BLP:##|t |cFFF00000%s|r人类杀手正在追杀你。"
D.Strings[76423]="我们服从于耐奥祖的意志！"
D.Strings[76424]="我们将用黑暗笼罩这个世界！"
D.Strings[76425]="献祭用的俘虏又多了一个！"
D.Strings[76426]="黑暗是我们的意志，钢铁是我们的血液！"
D.Strings[76427]="我要将你送进坟墓！"
D.Strings[76428]="你需要个伴儿吗，指挥官？"
D.Strings[76429]="需要保镖吗，指挥官？$B$B那你就找对矮人了。"
D.Strings[76430]="要利奥拉跟$n一起去吗？$B$B利奥拉是个保镖。保证让你活得好好的！"
D.Strings[76431]="暗影预言了你会需要我的保护。$B$B我已经准备好了。"
D.Strings[76432]="要我陪你一起去吗，$g先生:女士;？"
D.Strings[76433]="太棒了！我在外面等你。"
D.Strings[76434]="艾萝娜，回兵营去。"
D.Strings[76435]="我在家等你！"
D.Strings[76436]="我很荣幸。我在外面等你。"
D.Strings[76437]="薇薇安，回兵营去。"
D.Strings[76438]="我这就返回营地。"
D.Strings[76439]="我在外面等你。"
D.Strings[76440]="伊沙尔，回兵营去。"
D.Strings[76441]="听凭你的召唤。"
D.Strings[76442]="我将返回暗影之中。"
D.Strings[76443]="利奥拉在外面等你。"
D.Strings[76444]="利奥拉，回兵营去。"
D.Strings[76445]="有事吗，主人？"
D.Strings[76446]="利奥拉在家等你。"
D.Strings[76447]="遵命，头儿。我在外面等你。"
D.Strings[76448]="德尔瓦，回兵营去。"
D.Strings[76449]="我在家等你。"
D.Strings[76450]="如你所愿。我在外面等你。"
D.Strings[76451]="艾达，回兵营去。"
D.Strings[76452]="请下令吧。"
D.Strings[76453]="指挥官！你愿意帮我的商店做做广告吗？"
D.Strings[76454]="你可真是抓到了一头大家伙啊！我这就把它带回兽栏去洗刷干净。"
D.Strings[76455]="这家伙还真是精力旺盛，但愿我能把它完好无缺地带回去！"
D.Strings[76456]="真是大丰收啊，指挥官！我把它带回去之后，会给它好好洗一洗的。"
D.Strings[76457]="你抓了一头好家伙呢，让我把它带回兽栏吧。"
D.Strings[76458]="噢，这可是我的最爱！跟我来吧，小家伙！"
D.Strings[76459]="啊，一头好家伙。我来把它送回兽栏。"
D.Strings[76460]="一头强大的生物，它会成为优秀的坐骑的。我来带它回家。"
D.Strings[76461]="这头野兽需要好好训练一下。我这就开始。"
D.Strings[76462]="这些野兽非常狂野，但这个家伙看起来还有驯服的可能。跟我来，小家伙。"
D.Strings[76463]="真是大丰收，指挥官。我会把它洗刷干净的。"
D.Strings[76464]="我很久没有见过这么性烈如火的野兽了。跟我来吧，暴躁的家伙。"
D.Strings[76465]="欢迎，指挥官。我这里有全阿什兰最好的武器和护甲。$b$b如果你有什么需要我帮忙的，尽管开口。"
D.Strings[76466]="小心！联盟召唤了一头冰霜巨龙！远离大路！"
D.Strings[76467]="|TInterface\\Icons\\ACHIEVEMENT_PVP_H_H.BLP:##|t |cFFF00000%s|r德莱尼杀手正在追杀你。"
D.Strings[76468]="|TInterface\\Icons\\ACHIEVEMENT_PVP_H_H.BLP:##|t |cFFF00000%s|r矮人杀手正在追杀你。"
D.Strings[76469]="|TInterface\\Icons\\ACHIEVEMENT_PVP_H_H.BLP:##|t |cFFF00000%s|r暗夜精灵杀手正在追杀你。"
D.Strings[76470]="|TInterface\\Icons\\ACHIEVEMENT_PVP_H_H.BLP:##|t |cFFF00000%s|r侏儒杀手正在追杀你。"
D.Strings[76471]="|TInterface\\Icons\\ACHIEVEMENT_PVP_H_H.BLP:##|t |cFFF00000%s|r狼人杀手正在追杀你。"
D.Strings[76472]="马尔高克会为失去我这样的好手而后悔的。"
D.Strings[76473]="哈。我在睡梦中杀掉过比这更厉害的家伙！"
D.Strings[76474]="你将面对帝国之拳，蠢货。"
D.Strings[76475]="面对我，懦夫！"
D.Strings[76476]="我都还没出汗呢。"
D.Strings[76477]="这就跟挠痒痒没什么差别。"
D.Strings[76478]="再来一个。我能杀上一整天呢！"
D.Strings[76479]="肯定还有比这更强的对手吧？"
D.Strings[76480]="想来点肉吗？"
D.Strings[76481]="我们将并肩杀死无数敌人。"
D.Strings[76482]="这将是一场辉煌的战斗。"
D.Strings[76483]="我就知道你会正视我的力量，指挥官。"
D.Strings[76484]="整个德拉诺都将匍匐在我们脚下。"
D.Strings[76485]="你需要一个真正的食人魔来帮你，指挥官。"
D.Strings[76486]="听候您的吩咐，吾主。"
D.Strings[76487]="这么……快……"
D.Strings[76488]="不！我……拒绝……"
D.Strings[76489]="我们再打得狠一点怎么样？"
D.Strings[76490]="别担心，就快结束了。"
D.Strings[76491]="靠近点。我的剑还没有喝饱鲜血呢！"
D.Strings[76492]="有那么一瞬间，我还以为这会是个挑战呢。"
D.Strings[76493]="想让你的朋友们羡慕嫉妒恨吗？想吸引你在旅店里遇到的那位姑娘的眼球吗？那你就走运了，我的朋友。快来看看比尔·星酒的神奇魔法吧！\n\n只要付出极低的价格，你也可以星光闪耀，风靡世界！ \n\n我的助手鲍勃也能帮你了解来自德拉诺的最新强力附魔！"
D.Strings[76494]="让星酒的炫酷星光为你赢得女士们的青睐吧！"
D.Strings[76495]="星酒附魔店：为你送上全暴风之盾最具性价比的附魔。"
D.Strings[76496]="使用星酒附魔，拥有本地最闪亮的武器！"
D.Strings[76497]="星酒附魔店：为您带来快乐的附魔！"
D.Strings[76498]="欢迎光临星酒附魔店，本店可提供全暴风之盾最低价的附魔。\n\n要看看我们的配方列表吗？"
D.Strings[76499]="啊，带着范妮出去度蜜月的感觉真不错！"
D.Strings[76500]="我希望能暂时逃离诺森德的冰封荒原。看来我的选择是错误的。"
D.Strings[76501]="<这个年轻冒险者的尸体上有好几处伤口。$B$B从这个临时营地的状况来看，这里不久之前刚爆发过战斗。$B$B他的手中握着一个纸团。>"
D.Strings[76502]="这是什么生物？"
D.Strings[76503]="我变得更强大了！"
D.Strings[76504]="我是全德拉诺最强大的食人魔！"
D.Strings[76505]="那去啊，贾纳尔。带上整个氏族。冷血杀死自己的兄弟。看看有谁会追随你。"
D.Strings[76506]="你以为这就是父亲的愿望？"
D.Strings[76507]="噢！睡觉时间到……"
D.Strings[76508]="我的图腾可以增强你的实力！"
D.Strings[76509]="留在附近，使用我图腾的力量。"
D.Strings[76510]="站到我的图腾旁以获取它的力量。"
D.Strings[76511]="明智的选择。血精灵就是这个世界的祸害，必须被消灭或者赶出德拉诺。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76512]="奥金尼，守住这座大厅。"
D.Strings[76513]="保护奥金顿的屏障碎裂了。"
D.Strings[76514]="一股邪恶力量渗入了这些神圣的殿堂。"
D.Strings[76515]="兽人……$B$B<库卢斯吐了口口水。>$B$B要是你能把这片土地上的兽人赶尽杀绝，那真是帮了这个世界的原住民一个大忙了。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76516]="去侦察一下，我们得在这里建个据点。"
D.Strings[76517]="不……她不能这么做！我被控制了！"
D.Strings[76518]="我将归于圣光。"
D.Strings[76519]="在我的语言中，地精基本就是寄生虫的意思。他们给自己取得名字可真合适。就让他们的死亡给其他所谓的“部落”成员一个教训吧。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76520]="这些熊猫人本有机会加入你的强大部队，却选择了背叛联盟，加入敌人的阵营。现在，他们又开始帮助兽人屠杀德拉尼。背叛联盟的部落熊猫人必须死。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76521]="在阿古斯，我们会猎杀一种很像牛头人的强大长角生物为乐。用这个强大的对手来证明你的力量吧！$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76522]="巨魔全是一群阴谋家。我们一定要干掉巨魔入侵者，把他们全送去见他们的野蛮伪神！$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76523]="死亡的化身在大地上横行。这些亡灵的存在就是对生命的亵渎……对圣光的诅咒。就因为这个，他们也必须被清除出德拉诺。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[76524]="你训练中的坐骑害怕地逃跑了！"
D.Strings[76525]="振作起来，勇士。部落的力量与你同在。Lok'tar ogar！"
D.Strings[76526]="神器！他疯了吗？我们必须修好它并把它送到安全的地方去！"
D.Strings[76527]="<这台机器里已经没有多少能量了，它已经报废了>"
D.Strings[76528]="<进一步调查>"
D.Strings[76529]="圣光闪耀得更加明亮了！"
D.Strings[76530]="为了我的祖父。"
D.Strings[76531]="我将赢得我应得的地位。"
D.Strings[76532]="你休想击败我。"
D.Strings[76533]="你休想战胜圣光！"
D.Strings[76534]="让我们并肩作战。"
D.Strings[76535]="我是不会被打垮的。"
D.Strings[76536]="你完蛋了。"
D.Strings[76537]="你再也别想威胁这个世界了。"
D.Strings[76538]="你休想战胜圣光。"
D.Strings[76539]="我干掉一个了！"
D.Strings[76540]="我们必胜！"
D.Strings[76541]="我们的防线固若金汤。"
D.Strings[76542]="我将看到明天的太阳。"
D.Strings[76543]="我与你同在，指挥官。"
D.Strings[76544]="愿圣光祝福你，指挥官。"
D.Strings[76545]="只要团结一致，我们就不会失败。"
D.Strings[76546]="我会为死者复仇的。"
D.Strings[76547]="死者的灵魂在看着我们。"
D.Strings[76548]="与你并肩作战是我的荣幸。"
D.Strings[76549]="我……完了。"
D.Strings[76550]="圣光……熄灭了。"
D.Strings[76551]="我的眼前……只有……黑暗……"
D.Strings[76552]="祖父……我让你失望了……"
D.Strings[76553]="万灵赐予我力量！"
D.Strings[76554]="我不怕你。"
D.Strings[76555]="我要用生命保卫我的家园。"
D.Strings[76556]="死于我的锤下吧，恶魔。"
D.Strings[76557]="我的信念绝不动摇。"
D.Strings[76558]="我不会落败。"
D.Strings[76559]="我要伸张正义！"
D.Strings[76560]="为了德拉诺！"
D.Strings[76561]="这下可没人能阻挡我了。"
D.Strings[76562]="我会让你跪地求饶的。"
D.Strings[76563]="我要将你的灵魂撕碎。"
D.Strings[76564]="这只是一个开始。"
D.Strings[76565]="混沌统治一切！"
D.Strings[76566]="我们的命运在召唤。"
D.Strings[76567]="让我们将恐惧种入敌人心脏吧！"
D.Strings[76568]="我们已经不在外域了。"
D.Strings[76569]="我会将地狱的烈焰倾泻到你的敌人头上。"
D.Strings[76570]="我们要击败燃烧军团。"
D.Strings[76571]="虚空……拥抱了我……"
D.Strings[76572]="指挥官……我……失败了。"
D.Strings[76573]="我的灵魂……太软弱了。"
D.Strings[76574]="我要将你放逐到扭曲虚空。"
D.Strings[76575]="你会学会害怕我的。"
D.Strings[76576]="我的力量无穷无尽。"
D.Strings[76577]="我要折磨你。"
D.Strings[76578]="哈！像你这种可怜虫也就这点本事了。"
D.Strings[76579]="你以为你能击败塔尔的宠物？可笑。"
D.Strings[76580]="我其实不太喜欢让宠物去战斗，但我喜欢在它们战斗结束之后照顾它们。"
D.Strings[76581]="你想挑战我吗？我的狼需要通过训练变得更强。"
D.Strings[76582]="我的狼会把你的宠物撕成碎片的！"
D.Strings[76583]="|TInterface\\Icons\\ACHIEVEMENT_PVP_A_A.BLP:##|t |cFF0000FF%s|r地精杀手正在追杀你。"
D.Strings[76584]="|TInterface\\Icons\\ACHIEVEMENT_PVP_A_A.BLP:##|t |cFF0000FF%s|r牛头人杀手正在追杀你。"
D.Strings[76585]="|TInterface\\Icons\\ACHIEVEMENT_PVP_A_A.BLP:##|t |cFF0000FF%s|r巨魔杀手正在追杀你。"
D.Strings[76586]="|TInterface\\Icons\\ACHIEVEMENT_PVP_A_A.BLP:##|t |cFF0000FF%s|r亡灵杀手正在追杀你。"
D.Strings[76587]="|TInterface\\Icons\\ACHIEVEMENT_PVP_A_A.BLP:##|t |cFF0000FF%s|r血精灵杀手正在追杀你。"
D.Strings[76588]="|TInterface\\Icons\\ACHIEVEMENT_PVP_A_A.BLP:##|t |cFF0000FF%s|r兽人杀手正在追杀你。"
D.Strings[76589]="我们的力量执掌天空，看呐：恐惧振翅翱翔！"
D.Strings[76590]="%s紧紧地盯着你。"
D.Strings[76591]="我太喜欢这外面的新鲜空气了！"
D.Strings[76592]="我曾自豪地行走在这些殿堂之间，像个黑石兽人那样将头扬得高高的。但这是一条错误的道路。我们的大锤应该锻造战斧，长剑……而不是根据陌生人的低语打造这些机器。"
D.Strings[76593]="我要砸烂你的脸！"
D.Strings[76594]="箭火高高跳起，开始施放|TInterface\\Icons\\inv_misc_missilelargecluster_red.blp:20|t |cFFFF0404|Hspell:162407|h[X21-01A导弹速射]|h|r！"
D.Strings[76595]="开始砍伐和切割。"
D.Strings[76596]="启动下肢调整协议……"
D.Strings[76597]="……协议。"
D.Strings[76598]="温度参数过高……启动Z型升华程序。"
D.Strings[76599]="如果我是你的话……早就逃之夭夭了！"
D.Strings[76600]="约翰尼五号……死了？"
D.Strings[76601]="托尔玛克让我陪他环游艾泽拉斯。我从没想过我们会在这里停下脚步。但我很高兴自己跟着他来了。"
D.Strings[76602]="你的同伙儿呢？"
D.Strings[76603]="别以为我会放过你。"
D.Strings[76604]="让我看看你的本事吧！"
D.Strings[76605]="你的血都溅到我的胡子上了。真美味。"
D.Strings[76606]="哈哈！你从没跟矮人死亡骑士战斗过吧？"
D.Strings[76607]="继续杀啊，指挥官，我都快赢了！"
D.Strings[76608]="我又干掉一个了！"
D.Strings[76609]="连我的胡子都干掉过比这更厉害的家伙！"
D.Strings[76610]="战斗什么时候开始？我都快睡着了！"
D.Strings[76611]="可以开始一场老式的杀戮盛宴了吗？"
D.Strings[76612]="你手下已经有了全德拉诺最强的矮人！"
D.Strings[76613]="话说，指挥官……嗝儿！你对工作时间喝点小酒是怎么看的？"
D.Strings[76614]="我支持你，指挥官。"
D.Strings[76615]="德尔瓦·铁拳前来报到。"
D.Strings[76616]="指挥官……我……完了……"
D.Strings[76617]="你自我感觉不错嘛，是吧？"
D.Strings[76618]="你还得再加把劲儿！"
D.Strings[76619]="我的祖父一定会喜欢的。"
D.Strings[76620]="我只说一次，别碰我的胡子。"
D.Strings[76621]="我来让你看看，他们为什么会叫我铁拳。"
D.Strings[76622]="来啊，再投入一点儿！"
D.Strings[76623]="我是联盟的战士。你毫无机会。"
D.Strings[76624]="以我的斧子发誓，你会付出代价的！"
D.Strings[76625]="你所熟悉的一切都将陷入火海！"
D.Strings[76626]="死亡是必然的结局。"
D.Strings[76627]="你知道玩火的后果吧？"
D.Strings[76628]="但愿你已经买好墓地了。"
D.Strings[76629]="你死掉之后对我会更有用。"
D.Strings[76630]="你无法阻止死亡。"
D.Strings[76631]="永远地安息吧。"
D.Strings[76632]="你的死期已经到了。"
D.Strings[76633]="接下来我们该去哪儿？"
D.Strings[76634]="你的命令就是我的愿望，指挥官。"
D.Strings[76635]="我的使命……完成了……"
D.Strings[76636]="黑暗女王……在注视着我……"
D.Strings[76637]="我的死期……到了……"
D.Strings[76638]="你要怎么杀死已死之人？"
D.Strings[76639]="清算的时候到了。"
D.Strings[76640]="我要让你在烈焰中化为灰烬。"
D.Strings[76641]="临死前，看一眼黑暗的深渊吧。"
D.Strings[76642]="在危急四伏的情况下，组队探索阿什兰才是最明智的选择。如果你已经在队伍中，我可以把你传送到队长身边。$b$b你需要我把你传送到队长身边吗？"
D.Strings[76643]="我的力量增长了。"
D.Strings[76644]="黑暗女王在庇佑着我们。"
D.Strings[76645]="是的，请把我传送到队长身边。"
D.Strings[76646]="像我这样的资深模特从不走没有准备的秀。\n\n我一辈子都在练习我的独创造型。"
D.Strings[76647]="让我看看“塔布羊”吧！"
D.Strings[76648]="好吧，让我看看“蔚蓝钢铁”如何？"
D.Strings[76649]="现在，让我看看“烈焰之舞”吧！"
D.Strings[76650]="那可是经典造型。退后点，让我来给你表演一下。"
D.Strings[76651]="塔布羊！"
D.Strings[76652]="这可是我最受欢迎的造型。看好了。"
D.Strings[76653]="蔚蓝钢铁！"
D.Strings[76654]="啊，烈焰之舞。我花了好几年时间来完善它呢。让我来给你表演一下。"
D.Strings[76655]="烈焰之舞！"
D.Strings[76656]="一头贪婪的鬣蜥人正在吞吃你的要塞物资！"
D.Strings[76657]="一个叛变的强盗正在抢劫你的建筑！"
D.Strings[76658]="这里可是步步杀机啊，组队探索阿什兰才是最明智的选择。如果你已经在队伍中，我可以把你传送到队长身边。$b$b要把你传送到队长身边吗？"
D.Strings[76659]="抱歉，$n。"
D.Strings[76660]="这么快就要逃跑了吗？"
D.Strings[76661]="阿祖卡跟你没完。"
D.Strings[76662]="你毫无胜算。"
D.Strings[76663]="可怜虫，完全不出我所料。"
D.Strings[76664]="传送到队长身边"
D.Strings[76665]="要传送到你的队长身边吗？"
D.Strings[76666]="我很乐意为钢铁部落献出生命！"
D.Strings[76667]="够了！是时候让你看看这把剑真正的力量了。"
D.Strings[76668]="我的剑变得更强大了！"
D.Strings[76669]="你要招募干活的人吗？我能帮你找两个来。"
D.Strings[76670]="有人要找工作吗？"
D.Strings[76671]="利爪之王的力量属于斯克提斯的子孙。$B$B瑞沙德不该和外人分享它……"
D.Strings[76672]="|TInterface\\Icons\\Spell_Fire_Fireball02:20|t你携带着|cFFFF0000|Hspell:160702|h[黑石迫击炮弹]|h|r。快跳上黑石炮台以使用它们！"
D.Strings[76673]="艾斯卡希望泰罗克能以实体形态归来。可利爪之王到底是会拯救我们，还是将我们引入更深的黑暗？$B$B我不想再重复过去的错误。$B$B在你身上，我看到了足以掌握利爪之王力量的可贵品质。伊沙尔也同意了，并帮我将你们的精魂结合在了一起。$B$B艾斯卡不会高兴的，但生米已经煮成熟饭了。"
D.Strings[76674]="在游侠队伍中服役的那段日子里，我学会了很多德拉诺野兽的剥皮方法。\n\n我现在在暴风之盾，却发现比起在荒野中摆弄剥皮小刀，将这些知识传授给别人会更有趣。\n\n你不这么认为吗？"
D.Strings[76675]="那个斯万虽然不是矮人，可她的血管中却流淌着炽热的熔炉之火。\n\n我不可能再奢求比她更好的学徒了。"
D.Strings[76676]="靠近点，英雄们，让我为你们治疗伤口。"
D.Strings[76677]="没有可以挑战的宠物？我没空搭理业余爱好者，等你有点实战经验后再回来找我吧。"
D.Strings[76678]="桑克苏！释放你的力量吧！"
D.Strings[76679]="快杀死火刃新兵，别让他们靠近阿祖卡！"
D.Strings[76680]="很高兴你能来阿什兰，$C。这里很快就会需要你了。\n\n这座岛屿上出土的神器来自古代食人魔王国，它们或许将成为我们对抗钢铁部落的决定性因素。不幸的是，部落想要罔顾停战协议，独占这些知识。\n\n我们决不能让部落妨碍我们在德拉诺的行动。如果有必要的话，你尽管与他们开战，从他们的死人手里夺取神器吧！\n\n为了联盟！"
D.Strings[76681]="我们的人民非常感谢你在我们抵抗鲁克玛信徒时伸出的援手。\n\n我们不会忘记你的慷慨的。"
D.Strings[76682]="觉醒教派的出现让许多流亡者感到迷茫。虽然他们称自己的目的很单纯，可他们过去已经误导过我们太多次了。\n\n希望他们说的都是真的，但目前我们还是先拭目以待吧。"
D.Strings[76683]="我并不是一个战士，但我觉得就算是最狂热的好战分子也该经常远离战场，享受一下宁静平和的生活。\n\n对我来说，再也没有比拿着鱼竿倾听大海温柔的海浪声更好的休闲方式了。\n\n你觉得呢，$C？"
D.Strings[76684]="我要学习钓鱼。"
D.Strings[76685]="那是$n吗？难以置信，$G他:她;居然来暴风之盾了！"
D.Strings[76686]="$n来暴风之盾了！我从没见过比$G他:她;更强的$c！"
D.Strings[76687]="看，$n来了！$G他:她;或许就是扭转战局的关键人物！"
D.Strings[76688]="你有什么命令吗？"
D.Strings[76689]="换回兽人步兵。"
D.Strings[76690]="部落占领了暴风之盾堡垒！"
D.Strings[76691]="联盟占领了战争之矛岗哨！"
D.Strings[76692]="如果你在幽暗城、雷霆崖、暗矛巨魔、银月城、锈水码头、火金派熊猫人，或者作为死亡骑士在黑锋骑士团达到崇拜声望，就可以与大厅内对应的征募官对话，从他们那里招募守卫了。"
D.Strings[76693]="暗影正躁动不安。"
D.Strings[76694]="凝视黑暗的深渊吧！"
D.Strings[76695]="呱！"
D.Strings[76696]="让黑暗吞噬你。"
D.Strings[76697]="靠近点……我的暗影魔饿了。"
D.Strings[76698]="你们将被连根拔起。"
D.Strings[76699]="暗影魔又能饱餐一顿了。"
D.Strings[76700]="生命逝去了。"
D.Strings[76701]="呱哈哈！蠢货！"
D.Strings[76702]="凋零陨落。"
D.Strings[76703]="呱！可怜虫。"
D.Strings[76704]="欢迎投入暗影的怀抱。"
D.Strings[76705]="我还以为你有多厉害呢。"
D.Strings[76706]="我们今天要去夷平哪儿？"
D.Strings[76707]="我看到我们要走运了。"
D.Strings[76708]="愿暗影护佑着你，指挥官。"
D.Strings[76709]="我终于……自由了。"
D.Strings[76710]="还有……许多……未竟的事业。"
D.Strings[76711]="我……已经——呱！……坚持不下去了……"
D.Strings[76712]="暗影在……欢迎我……"
D.Strings[76713]="我就是你的送葬者。"
D.Strings[76714]="你的未来……所剩无几了。"
D.Strings[76715]="和我一样……痛苦吧。"
D.Strings[76716]="你对痛苦一无所知。"
D.Strings[76717]="在痛苦中挣扎吧。"
D.Strings[76718]="这是我们的土地！"
D.Strings[76719]="利奥拉要让朋友们活下去。"
D.Strings[76720]="太阳之石保护着我们。"
D.Strings[76721]="战斗会让我们更加强大。"
D.Strings[76722]="利奥拉要为氏族带去荣耀。"
D.Strings[76723]="利奥拉什么都不怕。"
D.Strings[76724]="我们要并肩战斗。"
D.Strings[76725]="利奥拉的杀戮是正义的。"
D.Strings[76726]="我从这家伙身上学到不少东西。"
D.Strings[76727]="我们的氏族是最强大的！"
D.Strings[76728]="你休想伤害主人。"
D.Strings[76729]="太阳之石从不让我们失望。"
D.Strings[76730]="利奥拉现在能理解你了。"
D.Strings[76731]="今天有新东西可学吗？"
D.Strings[76732]="<卷轴详细记录了日泉岗哨内将举行一次秘密战争会议。为了召集成员，必须吹响战歌议事厅前的传信号角。>"
D.Strings[76733]="利奥拉用太阳之石帮助氏族。"
D.Strings[76734]="指挥官给我带来什么知识了？"
D.Strings[76735]="利奥拉做好学习的准备了。"
D.Strings[76736]="如果你有需要，我们牛头人愿意提供帮助。"
D.Strings[76737]="利奥拉做好了一切准备。"
D.Strings[76738]="你叫利奥拉吗？"
D.Strings[76739]="为了氏族的利益。"
D.Strings[76740]="我才刚开始……理解……"
D.Strings[76741]="利奥拉……疼……"
D.Strings[76742]="太阳之石……没有用……"
D.Strings[76743]="利奥拉……怎么……这么冷……？"
D.Strings[76744]="利奥拉来帮忙了！"
D.Strings[76745]="你休想伤害主人！"
D.Strings[76746]="你也不怎么厉害。"
D.Strings[76747]="利奥拉要让你痛死。"
D.Strings[76748]="别担心。利奥拉会治疗。"
D.Strings[76749]="利奥拉能够治好氏族。"
D.Strings[76750]="元素之怒，是在我们这边的。"
D.Strings[76751]="太阳之石在帮助我们！"
D.Strings[76752]="你感觉到了吗？快跑！那是奔腾的兽群！"
D.Strings[76753]="暗矛巨魔听凭你的调遣。"
D.Strings[76754]="大法师指了指熔炉，就等你将克罗斯尼斯的烈焰之心带回来了。"
D.Strings[76755]="我想将要塞的防务工作交给暗矛巨魔。"
D.Strings[76756]="我想让牛头人来保卫要塞。"
D.Strings[76757]="就像我说的，这个爪子对这里的坐骑有些奇怪的影响。如果你在训练坐骑时带上它，你的坐骑就会变得更加暴躁。$B$B如果你觉得训练不够刺激的话，那可以挑战一下自己。$B$B对于那些挑战成功的人，我会送出丰厚的奖励哟！"
D.Strings[76758]="我想让被遗忘者来保卫要塞。"
D.Strings[76759]="联盟守住了暴风之盾堡垒！"
D.Strings[76760]="我想让血精灵来保卫要塞。"
D.Strings[76761]="部落守住了战争之矛岗哨！"
D.Strings[76762]="你有什么需要吗，指挥官？我们一定能满足你的要求。"
D.Strings[76763]="我想让地精来保卫要塞。"
D.Strings[76764]="我们的战士从北门回来了！他们带回了刚刚获得的宝藏！"
D.Strings[76765]="至少我们已经打伤了它！它还能有多危险呢？"
D.Strings[76766]="我是绝对不会回去的，你看见它都做了些什么吗？"
D.Strings[76767]="|TInterface\\Icons\\Spell_Arcane_Blast.blp:20|t你受到了|cFFFF0404|Hspell:162186|h[魔能散射：奥术]|h|r！"
D.Strings[76768]="你好，指挥官。我能帮你什么忙吗？"
D.Strings[76769]="我想让火金派熊猫人来保卫要塞。"
D.Strings[76770]="我受伤了，别管我。保护好下面的村子。"
D.Strings[76771]="你根本不是我们的对手。"
D.Strings[76772]="不过是联盟的小麻烦而已。"
D.Strings[76773]="你休想再前进一步了！"
D.Strings[76774]="小心！部落召唤了一头冰霜巨龙！远离大路！"
D.Strings[76775]="我们的战士从南门回来了！他们带回了刚刚获得的宝藏！"
D.Strings[76776]="我能出售运用德拉诺水晶之力的技术设计图。\n\n如果你的技术够高，这些知识或许能让你受益匪浅。"
D.Strings[76777]="我这里出售超出你想象的神奇发明的结构图！\n\n想要看一看吗？"
D.Strings[76778]="你知道怎么应用德拉诺的金属吗？\n\n如果你知道的话，那我的设计图或许对你有用。"
D.Strings[76779]="准备好把那些破破烂烂的旧皮革变成有用的东西了吗？"
D.Strings[76780]="你应该也看出来了，我很忙。\n\n你要买什么东西吗？"
D.Strings[76781]="如果你的技术够高，我能向你展示最伟大的铭文秘诀。"
