D.Strings[77057]="噢，正中脖子！"
D.Strings[77058]="噢！一枪毙命。"
D.Strings[77059]="哇！爆头。"
D.Strings[77060]="倒了一个。"
D.Strings[77061]="我是你的超级粉丝，指挥官。"
D.Strings[77062]="我很高兴能来这里。我的上一支队伍……我想他们应该都死了。"
D.Strings[77063]="影月谷真是太美了！"
D.Strings[77064]="这座要塞比海军上将泰勒的漂亮多了。"
D.Strings[77065]="……救命！"
D.Strings[77066]="送我去战争之矛岗哨！"
D.Strings[77067]="快，$n。大元帅要你立刻回风暴之盾去见他！"
D.Strings[77068]="新鲜的面包！卖新鲜的面包啦！"
D.Strings[77069]="长面包，圆面包，各种各样的面包。新鲜出炉的面包！"
D.Strings[77070]="快来买新鲜出炉的面包啊！"
D.Strings[77071]="我听说哈里森·琼斯寻找那件神器的工作还没有任何进展。"
D.Strings[77072]="他打算花多少时间？部落正在我们眼皮底下虎视眈眈，我们不可能永远呆在这里。"
D.Strings[77073]="但愿不会太久吧。我已经好几个月没见过在暴风城的家人了。"
D.Strings[77074]="部落正日益猖獗。今天早上，他们又袭击了我们的一座岗哨。"
D.Strings[77075]="那些杂种忘了我们签过停战协议了吗？"
D.Strings[77076]="看来是的。我想他们是害怕万一让我们找到神器，我们会用它来对付他们。"
D.Strings[77077]="如果他们继续这样袭击我们的士兵，那只会逼得我们那样做。"
D.Strings[77078]="攻击侧翼，消灭敌人！"
D.Strings[77079]="为了奥格瑞玛，为了部落——为了我们父辈的荣耀！"
D.Strings[77080]="让我来了结他们。"
D.Strings[77081]="留他们的骨头去喂狼吧。"
D.Strings[77082]="%s对着尸体吐了口唾沫。"
D.Strings[77083]="胜利的滋味总是如此甜美。"
D.Strings[77084]="尸体归你们了，但把牙齿给我留下。"
D.Strings[77085]="再也没有比雪地里殷红的鲜血更美的画面了。"
D.Strings[77086]="荣耀属于强大的部落，指挥官！"
D.Strings[77087]="没人敢质疑你的力量。"
D.Strings[77088]="部落已经牢牢掌握了霜火岭。如果我们要再建一座新要塞，那我想报名加入先遣队。"
D.Strings[77089]="荣耀属于新酋长！虽然他并不是兽人。"
D.Strings[77090]="让我上前线吧。我随时能为您效力，指挥官。"
D.Strings[77091]="我们将看着敌人四散奔逃！我们将听着随便什么人为这些畜生唱出的挽歌。我等不及想听到他们的哭号了！哈哈！那些哭丧的家伙真搞笑。"
D.Strings[77092]="我为……部落……献出了生命！"
D.Strings[77093]="呃——抓住他们！"
D.Strings[77094]="噢！噢！我在战斗！"
D.Strings[77095]="他们进了营地！我所有的东西都被砸烂了！"
D.Strings[77096]="我在施法！"
D.Strings[77097]="对，这事儿以前也发生过。"
D.Strings[77098]="我都没注意。"
D.Strings[77099]="死得不能再死了。"
D.Strings[77100]="噢，我喜欢你的装备。"
D.Strings[77101]="我喜欢你为这个地方所做的一切。"
D.Strings[77102]="很抱歉我的恶魔们烧坏了你的东西。这是他们的本性。"
D.Strings[77103]="可……可是……不！"
D.Strings[77104]="我来分解他们。"
D.Strings[77105]="呵呵呵呵，哈哈。"
D.Strings[77106]="噢，真是甜美而荣耀的屠杀！"
D.Strings[77107]="看看是什么来了。零件！"
D.Strings[77108]="把最好的零件留给我！"
D.Strings[77109]="把四肢留下，我有用。"
D.Strings[77110]="面部：融化了。"
D.Strings[77111]="如果有脑子留下的话，麻烦留给我。"
D.Strings[77112]="我能用这些零件创造出了不起的生物。"
D.Strings[77113]="那些器官一定能卖个好价钱。"
D.Strings[77114]="我在德拉诺的工作进展顺利。这里没那么多需要担心的“法律”。"
D.Strings[77115]="我在想，你有没有可能允许我在一些守卫身上做做“实验”……？"
D.Strings[77116]="要来一杯防腐剂吗，指挥官？"
D.Strings[77117]="我这么跟你说吧：与其使用五个普通体格的守卫，不如把他们缝合成一个迟缓而巨大的守卫如何？想想这种可能性吧！"
D.Strings[77118]="我很喜欢霜火岭的严寒。它能防止尸体腐烂。"
D.Strings[77119]="最近还好吗，指挥官？你喜欢你的胳膊吗？要不要……再加一条？如果有这想法的话，你知道该找谁的吧。"
D.Strings[77120]="你大部分其他追随者都有一个多余的肾。你不介意我“借”几个来吧？浴缸已经准备好了。"
D.Strings[77121]="我做鬼也不会放过你的！"
D.Strings[77122]="*咳嗽*我们打仗了吗？"
D.Strings[77123]="*咳咳*呃？打仗了吗？"
D.Strings[77124]="嘿，伙计，我杀掉一个了！"
D.Strings[77125]="这就对了。"
D.Strings[77126]="这是格莱维杀的，噢耶。"
D.Strings[77127]="$n（联盟）拾取了|c00FFFF00|Hspell:168506|h[远古神器]|h|r！"
D.Strings[77128]="嗯——哼！"
D.Strings[77129]="我要把你做成晚餐。"
D.Strings[77130]="$n（部落）拾取了|c00FFFF00|Hspell:168506|h[远古神器]|h|r！"
D.Strings[77131]="看，指挥官来了！"
D.Strings[77132]="我保证不在这里惹麻烦。"
D.Strings[77133]="指挥官！你什么也没看见，对吧？没有吧？我很好，我们都很好。这里一切都很好。"
D.Strings[77134]="嘿，指挥官，你饿了吗？"
D.Strings[77135]="嘘，安静，指挥官来了。嘘！嘿，嗨！"
D.Strings[77136]="%s大声咳嗽起来。"
D.Strings[77137]="为了……联——呃——部落！"
D.Strings[77138]="随便为了谁！"
D.Strings[77139]="这些家伙在这儿干嘛？"
D.Strings[77140]="别杀我！我是个牧师！"
D.Strings[77141]="昨天真是吵得人头疼。影月谷什么时候开始下雪了？"
D.Strings[77142]="指挥官，我，呃——靠近点——嘘——我想我们营地里有一些部落的间谍。"
D.Strings[77143]="那些头骨和尖刺是怎么回事？这简直……国王陛下知道吗？"
D.Strings[77144]="指挥官，我不知道你用的是哪个建筑师。可在我看来，这里简直就像是部落的营地。"
D.Strings[77145]="欢迎，角斗士们！元首马尔高克亲自挑选了你们来参加这场角斗比赛！只有德拉诺最嗜血和狂野的战士才能获得这样的荣耀。愿你们今天能为自己赢得荣耀和胜利！"
D.Strings[77146]="今天，我遇到一支部落巡逻队。当时他们正企图扫荡我们的一座岗哨。"
D.Strings[77147]="真的？你被发现了吗？"
D.Strings[77148]="是的，他们中的一个人看见了我。为了避免暴露，我一刀戳瞎了他的眼睛。"
D.Strings[77149]="送我去暴风之盾堡垒。"
D.Strings[77150]="登上平台吧。它能送你们进入角斗场，荣耀在等待着你们！"
D.Strings[77151]="让我猜猜，你不是主修敏锐的吧？"
D.Strings[77152]="我今天出去侦察的时候，正好带了一把闪亮的新匕首。"
D.Strings[77153]="真的？你从哪儿弄来的？"
D.Strings[77154]="从一头鬣蜥人的肚子里。"
D.Strings[77155]="当电梯开始移动时，这个房间就将充满致命的毒气，杀死留在里面的所有人。我建议你们赶快登上平台。"
D.Strings[77156]="就这样，都站到平台上去吧。你们最好都别在这里逗留。这是不行的，因为我们会在这里释放毒气，清除那些懦夫。"
D.Strings[77157]="登上平台吧！电梯马上就要光荣地升入竞技场了！"
D.Strings[77158]="祝你们好运，勇士们！愿你们中的最强者今天能在角斗场中赢得荣耀！"
D.Strings[77159]="你在鬣蜥人的肚子里找到一把匕首？你怎么会想到剖开它的肚子的？"
D.Strings[77160]="否则你觉得它们还能把战利品藏在哪儿？"
D.Strings[77161]="我……看见了……"
D.Strings[77162]="我不明白为什么哈里森·琼斯让我们到这里来帮忙发掘。在有一头食人魔老想把我切成两半的情况下，我一件神器都找不到！"
D.Strings[77163]="如果你以为食人魔就够糟了，那你真该去看看祭坛那里的幽灵食人魔。那才是坏消息呢。"
D.Strings[77164]="幽灵食人魔？呃，这座岛连杀人都杀出花样来了。"
D.Strings[77165]="我听说他们在矿井里发现了一些有趣的东西。但哈里森对此保持了沉默。"
D.Strings[77166]="你觉得那会是什么？"
D.Strings[77167]="我跟一个工人谈过，他们认为那个地方闹鬼。他们说有人失踪了，然后又发生了事故。"
D.Strings[77168]="非常诡异的事故。什么坚固的洞穴塌下来埋住了挖掘者啦，什么出故障的机器吞掉了操作者啦。他们说越是往下挖，这类事故就越频繁。"
D.Strings[77169]="我不喜欢这些消息。我想我还是留在旅店里好了。"
D.Strings[77170]="我完全同意。"
D.Strings[77171]="事故？什么样的事故？"
D.Strings[77172]="你是怎么上来的？"
D.Strings[77173]="这里上面很安静，你不觉得吗？简直……太安静了。"
D.Strings[77174]="快，$n。沃拉斯命令你立刻返回战争之矛！"
D.Strings[77175]="克鲁努斯诞生了！干得好，$n。"
D.Strings[77176]="看看你周围吧，你没看到我们已经赢了吗？"
D.Strings[77177]="神器碎片所含的魔力足以让这头大地之怒恢复全部力量。$B$B你给我带来多少了？"
D.Strings[77178]="有前线的战报，长官！"
D.Strings[77179]="联盟休想占领阿什兰，$c。这里的食人魔神器的力量是属于我们的。"
D.Strings[77180]="联盟的士兵们，快拿上他们的补给，骑着狮鹫返回暴风之盾堡垒！"
D.Strings[77181]="联盟的士兵们，我们得走了！部落的援军已经在路上了。"
D.Strings[77182]="快撤退，联盟的援军马上就要到了！"
D.Strings[77183]="快拿上他们的补给品，骑上双头飞龙返回战争之矛岗哨！"
D.Strings[77184]="松开你们的腰带吧，女士们！我们今天要大吃一顿！"
D.Strings[77185]="看我一枪毙命。"
D.Strings[77186]="以邪恶的名义，那是什么东西？"
D.Strings[77187]="没人能骗得了我。"
D.Strings[77188]="愿黑暗女王可怜我们……这比我想象得还要糟糕。"
D.Strings[77189]="看来蛮兵高地的食人魔在驱使巨兽向我们的部队投掷巨石！"
D.Strings[77190]="看来那些食人魔很爱扔石头，是吧？"
D.Strings[77191]="我这就让斯波奇特开着坦克去拜访他们一下。让我们看看他们的石头在钢铁面前能有多厉害吧。"
D.Strings[77192]="感谢你的报告，士兵。你可以返回前线了。"
D.Strings[77193]="阿坎瑟斯的嘴里流出了一些类似树汁的液体。"
D.Strings[77194]="长官，我们的斥候报告说部落的军队正在为一头上古大地之怒充能！"
D.Strings[77195]="你是说一头大地之怒？这可麻烦了。"
D.Strings[77196]="我得去跟我们的德鲁伊盟友商量一下。他们唤醒的古树或许是我们打败这支部队的唯一希望了。"
D.Strings[77197]="$n摆下了一桌狂野大餐。"
D.Strings[77198]="报告上说，食人魔矿井里盘踞着一头巨型野兽。"
D.Strings[77199]="我们的斥候还没能仔细观察过它，但它的体型非常庞大，几乎塞满了整个洞穴！"
D.Strings[77200]="我们得警告那些在洞穴附近作战的人。干得好，士兵。"
D.Strings[77201]="指挥官，我建议我们离开这儿。这不是我们应该逗留的地方。"
D.Strings[77202]="真恶心，指挥官。你去拿剩下的……东西吧，我来掩护你。"
D.Strings[77203]="哈里森·琼斯报告说他虽然已经找到了一些碎片，但关于我们想找的那个神器的下落，他至今一无所获。"
D.Strings[77204]="他想要更多的人去帮他搜索。"
D.Strings[77205]="他说得好像有无穷无尽的冒险者可供我们调遣似的。我会把自愿报名的人给他派过去。由于部落的威胁，我们的兵力已经非常分散了。"
D.Strings[77206]="暗影赐予了我新的力量。"
D.Strings[77207]="利奥拉更强大了！"
D.Strings[77208]="是的……我离暗影又近了一步。"
D.Strings[77209]="利奥拉比以前更强大了！"
D.Strings[77210]="这就是我们要找的东西。她的法杖就是钥匙。"
D.Strings[77211]="对……非常好。呱！"
D.Strings[77212]="将念珠还给利奥拉！"
D.Strings[77213]="指挥官，我们成功了！"
D.Strings[77214]="谢谢，甜心。现在，回去战斗吧！"
D.Strings[77215]="我差点就死在这儿了！谢了！"
D.Strings[77216]="好了，崔克尼……让我们看看传说中的掠食者奥盖克松吧！"
D.Strings[77217]="不是只有我们才会抓俘虏的，$c。$B$B在联盟的营地里同样有监狱，它就在主建筑的下方。$B$B只要有暴风之盾监狱钥匙，就可以把那些囚犯放出来了。"
D.Strings[77218]="遵命，头儿！初始化全息投影D-092号！"
D.Strings[77219]="据说奥盖克松的獠牙能刺穿坚硬的钢铁！真厉害！"
D.Strings[77220]="我们一定要拿到奥盖克松的獠牙，崔克尼。它们总有一天会成为出色的化石！"
D.Strings[77221]="让我们切换到下一个标本吧！"
D.Strings[77222]="数据库的下一个标本是伯格鲁。初始化全息投影D-093……"
D.Strings[77223]="啊，对了！伯格鲁。北部平原的强大铁皮牛！据说伯格鲁的角是全世界最大的裂蹄牛角……"
D.Strings[77224]="有人靠近了精确测量过吗？"
D.Strings[77225]="还没有！但有些收藏家愿意花大价钱来收购它。"
D.Strings[77226]="让我们切换到德考汉，神秘而古老的纳格兰雷象！"
D.Strings[77227]="初始化全息投影D-095……"
D.Strings[77228]="雷象是德拉诺最古老的物种之一，德考汉曾见证过无数代兽人的兴衰……"
D.Strings[77229]="突击测试！崔克尼，你要怎么知道雷象的年龄？"
D.Strings[77230]="呃……根据它们象牙的尺寸？"
D.Strings[77231]="答对了！你是从我这儿学来的吗？"
D.Strings[77232]="那个尺寸的问题？呃……是啊，当然了！那还用说嘛！"
D.Strings[77233]="接下来，让我们看看神出鬼没的致命塔布羊，恐蹄吧……"
D.Strings[77234]="全息投影D-096初始化完毕，头儿！"
D.Strings[77235]="恐蹄是德拉诺这一地区最危险的塔布羊，稀有品质的标本……"
D.Strings[77236]="作为考古学家，我们有责任在这头强大的野兽的全盛时期将它保存下来！"
D.Strings[77237]="听了你的话，我都为自己身为考古学家而自豪了，长官！"
D.Strings[77238]="理应如此，崔克尼……理应如此。"
D.Strings[77239]="现在，换下一个标本吧！"
D.Strings[77240]="初始化全息投影D-097……野蛮的伽罗格！"
D.Strings[77241]="如此壮观而野蛮的生物！很少有戈隆能像野蛮的伽罗格这样恐怖！"
D.Strings[77242]="让妇女和儿童藏起来！所有人都藏起来！"
D.Strings[77243]="在某个地方的某间私人收藏室里，藏品架子上有个空位正等着用伽罗格的遗骸去填补呢。"
D.Strings[77244]="头儿，你说得我都要哭了！"
D.Strings[77245]="这是我们的地盘，小东西。"
D.Strings[77246]="对，揍他！"
D.Strings[77247]="见证燃烧军团的力量吧！"
D.Strings[77248]="现在，让我们看看穆格拉吧！全息投影D-098号，崔克尼……"
D.Strings[77249]="D-098号来了！"
D.Strings[77250]="穆格拉……我的老对头！"
D.Strings[77251]="老对头？你跟这头河马发生过什么故事吗？"
D.Strings[77252]="这么说吧，从活的河马嘴里拔牙是非常危险的事……"
D.Strings[77253]="这正是我们考古学家最近需要解决的问题！嘘！"
D.Strings[77254]="让我们来看下一个影像吧！"
D.Strings[77255]="遵命，老板！初始化全息投影D-099号……"
D.Strings[77256]="啊，是的！这就是泰克塔伦，一头超级巨大和凶猛的风鹏。"
D.Strings[77257]="它有大爪子吗？"
D.Strings[77258]="是的，崔克尼……而且非常锋利！可惜我们没时间等泰克塔伦自然死亡，并在漫长的岁月中慢慢变成化石了。"
D.Strings[77259]="……相反，我们的责任就是帮自然一把，加速这个过程！"
D.Strings[77260]="自然石化？谁有功夫等那个！"
D.Strings[77261]="崔克尼，现在请启动艾克加纳克的全息投影吧！"
D.Strings[77262]="好的，头儿！启动全息投影D-100号……"
D.Strings[77263]="艾克加纳克真是最奇怪的生物了！它的毒囊里的生物荧光剂具有极高的腐蚀性，并可以以极高的速度喷射出来。"
D.Strings[77264]="所以艾克加纳克可以把人的脸融化掉？"
D.Strings[77265]="不然你以为波兹尔是怎么回事？他以前可不长那样！"
D.Strings[77266]="<瑞秋礼貌地向你点点头。>$B$B你好。"
D.Strings[77267]="<瑞秋看着自己的工具。>$B$B还有很多工作要做呢。"
D.Strings[77268]="<瑞秋耸了耸肩。>$B$B我不太爱说话。"
D.Strings[77269]="我的专利火箭甩钩系统运行的非常完美。要是这些鱼不这么挑食就好了！"
D.Strings[77270]="妮娜，我们钓到的鱼还不够！我们需要更多的火箭！"
D.Strings[77271]="说抛长线需要高超技术的人肯定没试过用火箭！"
D.Strings[77272]="不想再像失败者那样甩钩了吗？试试我的专利火箭甩钩系统吧！"
D.Strings[77273]="有人会觉得这很奇怪，但我发现地精机械有节奏的隆隆声有助于放松精神。\n\n但没有那股味道就更好了。"
D.Strings[77274]="在邪火中燃烧吧！"
D.Strings[77275]="所有角斗士都被杀死了。今天没有冠军。"
D.Strings[77276]="我知道一些法术可以修复你的装备——但这是收费的。"
D.Strings[77277]="我需要材料。"
D.Strings[77278]="伙计，那些联盟士兵真是一群爱哭鬼！"
D.Strings[77279]="你是说那个被你砍掉了脚，一直在尖叫的家伙吗？"
D.Strings[77280]="对啊！我是说，拜托，那不过是一只脚而已！那种东西很容易就能缝回去了。"
D.Strings[77281]="呃，我不这么认为……"
D.Strings[77282]="那么，最近老往我耳朵里钻的那些神器到底是怎么回事？"
D.Strings[77283]="我只知道联盟在找这些东西，而精灵们认为它们很强大。所以我们不想让联盟得到它们。"
D.Strings[77284]="你是说强大？或许我也该去弄几件来。"
D.Strings[77285]="你们兽人就非得整天把磨利的斧子挥来挥去的吗？"
D.Strings[77286]="下次别再自己拔带倒钩的箭头了。找点别的东西去捅你的对手。"
D.Strings[77287]="让我看看那个伤口……"
D.Strings[77288]="别动，我来帮你包扎。"
D.Strings[77289]="答案就在外面，藏在黑暗的地方。$B$B我们必须鼓起勇气找到它们。"
D.Strings[77290]="我想查看一下邮件。"
D.Strings[77291]="我需要你帮我修一下装备。"
D.Strings[77292]="我拿金币赌这个大个子赢！"
D.Strings[77293]="喔唷！那肯定很疼！"
D.Strings[77294]="咬他！咬他！"
D.Strings[77295]="嘿！这场战斗不公平！"
D.Strings[77296]="上啊，蛮兵！"
D.Strings[77297]="我马上就能复制出埃匹希斯控制器了。"
D.Strings[77298]="入侵者！来人，去通知克里丹！"
D.Strings[77299]="我会好好享用你的灵魂的……"
D.Strings[77300]="<拉斯托克开心地咯咯笑了起来。>$B$B你看见那个炸弹的尺寸了吗？！真壮观！"
D.Strings[77301]="蠢货，竟敢来妨碍我！我要把那套漂亮的盔甲烧进你的皮肤里去！"
D.Strings[77302]="我想查看一下我的追随者任务。"
D.Strings[77303]="你们脚下是一片神圣的土地。在这里，在竞技场的地面上，洒满了德拉诺最伟大的角斗士们的热血。大部分人都为了这份荣耀献出了生命。今天，你们也将和他们一样。"
D.Strings[77304]="战斗！杀戮！欢呼！100条性命。是生是死就掌握在你们手中。"
D.Strings[77305]="最后一个活下来的角斗士将赢得荣耀和财富！"
D.Strings[77306]="$n倒下了！那个$r只在地上留下了一滩血！"
D.Strings[77307]="那是什么？！地上有东西爆炸了。我想那应该是$n！"
D.Strings[77308]="$n倒下了！这让我想起了上次那个兽人被一头巨型雷象碾压的情景。我在那个马戏团度过了愉快的一周。"
D.Strings[77309]="噢！那个小$r死得真难看！"
D.Strings[77310]="看来门卫要花上几天功夫来把$n的零碎捡齐了！"
D.Strings[77311]="那个$r到底是个孩子还是大人？死得也太快了！"
D.Strings[77312]="哈！嘿，乔恩，还记得我那坨很像$r的屎吗？$n现在就是那副模样！"
D.Strings[77313]="噢，这应该会很有趣的。你不介意我做个笔记吧？"
D.Strings[77314]="这就不难看出，为什么这些东西会如此受到其所属文化的推崇了！呃，我为你宠物感到很抱歉。"
D.Strings[77315]="非常有趣的结果。谢谢你帮我进行测试！"
D.Strings[77316]="呃，对于这些在地下埋了一千年的东西，你还能指望些什么呢？"
D.Strings[77317]="在其本土文化中，那个宠物可能会被当做殉道者崇拜。"
D.Strings[77318]="呼，我就知道会这样。"
D.Strings[77319]="幸好吉拉克斯什么都能修，包括他自己。"
D.Strings[77320]="那么，这是这台机器正常的反应吗，还是它只是爆炸了？"
D.Strings[77321]="一切以科学的名义。"
D.Strings[77322]="你将滋养我的根须。"
D.Strings[77323]="如果你需要的话，我的野外分析箱里有绷带……"
D.Strings[77324]="你必须尊重这些古代遗迹的精巧设计。"
D.Strings[77325]="你将成为食物的肥料。"
D.Strings[77326]="在我发表这个研究成果时，我会特别感谢你的宠物的。"
D.Strings[77327]="噢，你说的一定是我的父亲，贝洛克。他和神圣遗物学会的所作所为很难被称为是“考古”。那更像是盗墓。$b$b真正的考古学是搜寻真相，而不是宝藏。我希望了解历史，研究我们的起源，发掘失落的知识。"
D.Strings[77328]="我虽然倒下了……可永茂林地终将吞噬你们……"
D.Strings[77329]="辉刃？这名字有点耳熟……"
D.Strings[77330]="你看起来不太擅长宠物战斗。或许你可以等更熟练一些后再来找我。"
D.Strings[77331]="噢，我的宠物表现太出色了。我要好好抱抱它们。"
D.Strings[77332]="噢，我觉得这还不错。就是多多需要一只新眼睛了。"
D.Strings[77333]="别担心，我亲亲伤口就不疼了。"
D.Strings[77334]="热汤会让你们好起来的！"
D.Strings[77335]="她没死，她只是睡着了。"
D.Strings[77336]="我们要给她绑上彩色的绷带。"
D.Strings[77337]="你的宠物也睡着了吗？"
D.Strings[77338]="你会让你的宠物好起来的，对吧？"
D.Strings[77339]="举行召唤仪式吧。我想把盟友召唤到我的位置。"
D.Strings[77340]="和我想的一样，$r，你太弱了。"
D.Strings[77341]="算你走运，我的狼还没有完全长大，否则你就要变成它们的盘中餐了。"
D.Strings[77342]="只有失败才能暴露出我们的弱点。这场失利能提高它们的训练水平。"
D.Strings[77343]="它真是太蠢了。"
D.Strings[77344]="它并不缺乏勇气。"
D.Strings[77345]="它以后就不会再犯这种错误了。"
D.Strings[77346]="它速度太慢了。"
D.Strings[77347]="它需要一些治疗。"
D.Strings[77348]="你的宠物怎么这么弱？"
D.Strings[77349]="轻轻松松。我的狼都没学到什么。"
D.Strings[77350]="角斗士们，杀呀！"
D.Strings[77351]="我还是全纳格兰最强的督军！"
D.Strings[77352]="什么？这怎么可能？你肯定作弊了！"
D.Strings[77353]="这点损失不过是九牛一毛。"
D.Strings[77354]="我的角斗士们会战斗到最后一刻！"
D.Strings[77355]="你激怒塔尔了！"
D.Strings[77356]="我是让你杀敌，不是让你送死！"
D.Strings[77357]="哈哈，软弱的$r就用软弱的宠物。"
D.Strings[77358]="角斗士，砸死它！"
D.Strings[77359]="你不开心吗？"
D.Strings[77360]="塔尔要搞定你！"
D.Strings[77361]="所以说，塔尔才是全纳格兰最强的督军！"
D.Strings[77362]="嘿，$g先生:女士;，要看看我的宠物吗？"
D.Strings[77363]="那请下次再来吧。"
D.Strings[77364]="虽然我个子小，可你要敢伤害我的宠物，我就跟你拼命。"
D.Strings[77365]="谢谢，$g先生:女士;！我愿意出一百个铜板的赌注。"
D.Strings[77366]="此刻简直就像我的家乡被恶魔攻占时一样。"
D.Strings[77367]="没事，它们已经习惯死亡了。"
D.Strings[77368]="那家伙已经不是第一次被人追到天涯海角了。"
D.Strings[77369]="行行好吧！我可在它身上花了一大把铜板呢。"
D.Strings[77370]="如果你答应不再那么做，我可以卖给你一个乔丹之石。"
D.Strings[77371]="我们家族的人一向都这么倒霉。"
D.Strings[77372]="抱歉，$g先生:女士;。"
D.Strings[77373]="别把它扔了，它还有救。"
D.Strings[77374]="这就对了！我的宠物可是在卡尔蒂姆严酷的街头锻炼出来的。"
D.Strings[77375]="你只是运气不好，$g先生:女士;。"
D.Strings[77376]="$R，我一直致力于训练安苏的守护者们。你愿意协助我吗？"
D.Strings[77377]="很好。好好训练一下再来找我吧。"
D.Strings[77378]="我们的希望就在这些宠物身上。对我们来说，它们是神圣的。"
D.Strings[77379]="荣耀属于安苏！"
D.Strings[77380]="我们是鸦人。我们是不会被一次失败所打倒的。"
D.Strings[77381]="坏兆头。"
D.Strings[77382]="安苏，请庇护你的子孙吧！"
D.Strings[77383]="不！守护者绝不能倒下！"
D.Strings[77384]="前景不妙！前景不妙哇！"
D.Strings[77385]="我们被塞泰诅咒了。"
D.Strings[77386]="好兆头。"
D.Strings[77387]="鸦人的力量与我们同在。"
D.Strings[77388]="今天，我们受到了鸦神的祝福。"
D.Strings[77389]="守护者们屹立不倒。"
D.Strings[77390]="安苏庇佑着他的子孙。"
D.Strings[77391]="你好，$n。想跟我的飞蛾共舞吗？"
D.Strings[77392]="我理解。等你准备好了再来找我吧。"
D.Strings[77393]="注意了，$n。力量总是藏在你最意想不到的地方。"
D.Strings[77394]="希望你今天能有所收获。"
D.Strings[77395]="我为失败而难过，也为你的胜利感到高兴。"
D.Strings[77396]="别怕，一个简单的治疗法术就能治好它。"
D.Strings[77397]="圣光并没有带走她。她只是休眠了。"
D.Strings[77398]="看来飞蛾总是喜欢扑火。"
D.Strings[77399]="低估自然的力量是愚蠢的行为。"
D.Strings[77400]="飞蛾很柔弱，但并不是毫无防备。"
D.Strings[77401]="不要绝望，你和你的宠物会从中获得启迪。"
D.Strings[77402]="一个迟到的、温柔的教训。"
D.Strings[77403]="举行指引之光仪式吧。我想把盟友召唤到我的位置。"
D.Strings[77404]="抱歉，我得先把我的一只宠物训练到25级。"
D.Strings[77405]="我很欣赏你的品格。接着说。"
D.Strings[77406]="开启通往我要塞的传送门。"
D.Strings[77407]="你手中的|cFFE86B17|Hspell:175519|h[火焰精华]|h|r被撞灭了！"
D.Strings[77408]="黑暗……在我体内流淌，从每一条血管渗出。"
D.Strings[77409]="来吧，陌生人！进入暗影的领域！我要将你们送入坟墓。"
D.Strings[77410]="影月氏族不会失败——我们行走在死神的国度。"
D.Strings[77411]="我是末日的使者！"
D.Strings[77412]="枯骨残骸，暗影弥漫！来吧，亡者的大军！"
D.Strings[77413]="在深渊中沉沦吧！"
D.Strings[77414]="感受虚空的冰冷拥抱。"
D.Strings[77415]="我的力量……永垂……不朽。"
D.Strings[77416]="你的灵魂将听命于我！"
D.Strings[77417]="臣服于我吧！"
D.Strings[77418]="崛起吧，诅咒之河！以黑暗之名，以耐奥祖之名崛起吧！影月氏族在召唤……"
D.Strings[77419]="影月的先祖，在黑暗中闪耀吧！赐予我力量吧！"
D.Strings[77420]="为了耐奥祖……"
D.Strings[77421]="唔，没错。完美的祭品。"
D.Strings[77422]="你们的灵魂将属于我。"
D.Strings[77423]="躁动的灵魂啊，听从我的命令！"
D.Strings[77424]="我的大军又多了一条灵魂！"
D.Strings[77425]="拥抱永恒的黑暗吧……"
D.Strings[77426]="亡者……不死……"
D.Strings[77427]="在引火烈焰旁重新点燃|cFFE86B17|Hspell:175519|h[火焰精华]|h|r！"
D.Strings[77428]="谢谢你，$n。愿霜火之怒在你心中熊熊燃烧！"
D.Strings[77429]="感谢你的帮助，$n。虽然我受伤了，但没关系，带路吧！"
D.Strings[77430]="$n，我不会忘记你的帮助。这些伤口不影响我大战一场！"
D.Strings[77431]="这才像话嘛。虽然我受伤了，可你给了我一个自救的机会。"
D.Strings[77432]="沙塔尔在上，感谢你的帮助。虽然我受伤了，可你给了我一个战斗的机会！"
D.Strings[77433]="$n，我会记住你的名字的。比起我的怒火，这些伤口不算什么——让我们战斗吧！"
D.Strings[77434]="感谢你的帮助，$n。让我们并肩战斗，为了沙塔斯！"
D.Strings[77435]="谢谢，$r，可我不想和你并肩战斗。"
D.Strings[77436]="道不同不相为谋，$r。感谢你的帮助，但我得走了。"
D.Strings[77437]="我的伤太重了，朋友。我得走了，但愿我们后会有期。"
D.Strings[77438]="我还要一杯。"
D.Strings[77439]="烂水果才是最甜的。"
D.Strings[77440]="我伤得太重了，$n，必须马上接受治疗。谢谢你这段时间陪着我。"
D.Strings[77441]="你受到了朝圣者祭坛的祝福。一种祥和宁静的感受包裹着你。"
D.Strings[77442]="克乌雷的祝福"
D.Strings[77443]="你这儿的酒可真不错，指挥官。"
D.Strings[77444]="圣光与你同在，指挥官。"
D.Strings[77445]="这么多人死在了这片土地上……"
D.Strings[77446]="愿艾维娜保佑你。"
D.Strings[77447]="德拉诺发现的草药和菌类可以用来收集各种病菌。\n\n我相信，我们的下一次瘟疫会成为最强的瘟疫！"
D.Strings[77448]="你有没有真正在酸性沼泽软泥怪的肚子里呆过一段时间？我不建议你去尝试。"
D.Strings[77449]="有事吗，老爷？"
D.Strings[77450]="我一定会想办法解救伯瓦尔，哪怕为此花上一辈子的时间。"
D.Strings[77451]="我想一个人呆一会儿。"
D.Strings[77452]="赞吉吉喜欢猫咪睡觉的姿势。"
D.Strings[77453]="我受伤了，$n，我需要休息。Al diel shala！"
D.Strings[77454]="用了我的配方，你就能将德拉诺的材料随意转化成治病救人或者残害生命的药水了。\n\n当然，前提是你的技术能够掌握它们。"
D.Strings[77455]="啊，你好啊，指挥官！想听我说一个关于桥的故事吗？"
D.Strings[77456]="我需要休息，$n。Shorel'aran！"
D.Strings[77457]="教程很简单：躲好，否则你的脑袋就保不住了。它能让你的躲闪能力大大提升。"
D.Strings[77458]="我很好奇这个世界是否存在什么灭世神器？你知道，我们不能让它们落入敌人之手！"
D.Strings[77459]="不打架，坐到火堆边上来。火堆暖和，外面冷。你坐。"
D.Strings[77460]="我喜欢船！"
D.Strings[77461]="你只能从最远距离外观察我。"
D.Strings[77462]="我只懂战争。在这里，我是如鱼得水。"
D.Strings[77463]="五十！对！我正在跟他们讲我曾委托给冒险者的一个最“刺激”的任务呢。啊，那可真是一段好时光……"
D.Strings[77464]="许多德拉诺野兽的毛皮都非常坚韧，足以和最结实的科多兽媲美。\n\n如果你有足够的技术，我可以教你如何将这些皮革做成精良的护甲。"
D.Strings[77465]="如果你不介意的话，我正在跟尼布利进行跨位面通讯呢。"
D.Strings[77466]="嗨！这真是座一流的要塞。"
D.Strings[77467]="这座岩石雕像散发出祥和的光环。上面的一块铭牌写着：$B$B受阿达尔的光辉祝福的人将获得韧性和护甲值，能够对抗最具挑战性的敌人。$B$B德欧里的祝福能让你在需要时得到治疗。$B$B卡拉指引着受祝福者的武器，让他们能在战斗中获得额外的攻击机会。$B$B克乌雷则会嘉奖虔诚的信徒，让他们变得像风一样迅捷。"
D.Strings[77468]="德欧里的祝福"
D.Strings[77469]="卡拉的祝福"
D.Strings[77470]="阿达尔的祝福"
D.Strings[77471]="你好像应该翻新一下你的衣柜了。\n\n算你走运，我刚好可以教你裁剪全德拉诺最精美的服装。\n\n想要看看我的图样吗？"
D.Strings[77472]="德莱尼晶匠一直小心翼翼地保守着他们的秘密，不想让别人学会运用德拉诺宝石的强大潜力。\n\n但我设法搞到了这些秘诀，并愿意和有天赋的珠宝加工者分享它们。\n\n当然，这是要收费的。"
D.Strings[77473]="我看出来了，你想用巫术的力量强化你的装备。\n\n杰德卡可以为你效劳，伙计。"
D.Strings[77474]="某些文字含有最强大的巫术力量。\n\n掌握这些文字的人就掌握了真正的力量！"
D.Strings[77475]="这些钢铁部落的混蛋以为他们会造机器了。\n\n等着瞧吧，等弄到他们的技术，我们一定要让他们看看地精科技的力量！"
D.Strings[77476]="自从阿什兰的联盟对我们造成威胁之后，对高品质武器和护甲的需求就日益高涨！\n\n你嗅到利润的香气了吗？"
D.Strings[77477]="兹克老伙计，你能帮我从附魔师那里弄个卷轴来吗？"
D.Strings[77478]="这头迅猛龙真不错！"
D.Strings[77479]="我的羽毛笔该放在哪儿呢？"
D.Strings[77480]="铭文师总是有干不完的活儿，伙计。"
D.Strings[77481]="你尽管把你的动物和迅猛龙放在一起好了。我们会喂饱它们的。\n\n当然是喂饱你的动物了。你以为我是什么意思？"
D.Strings[77482]="嘘……我正在抓猎物呢！"
D.Strings[77483]="你想问我们为什么会在这儿？我们是老练的冒险者，正在追踪一头传奇海兽。"
D.Strings[77484]="这种生物一定是存在的！我愿意花一辈子来找到它！"
D.Strings[77485]="德拉诺出产的材料既神秘又神奇。\n\n只要一点钱，我就可以教你驾驭它们的力量。"
D.Strings[77486]="以鸦母的羽毛保证，你绝对找不到比这更划算的买卖了！"
D.Strings[77487]="啊——！吼——！"
D.Strings[77488]="你在这片水域见过什么巨型海洋生物吗？"
D.Strings[77489]="给，你看起来饿了。"
D.Strings[77490]="吃了它，它能让你变强壮。"
D.Strings[77491]="我都说了，它一定管用，尽管相信我！"
D.Strings[77492]="我在这玩意儿里都看不见外面了……如果我们连身处何方都不知道，那还怎么执行计划？"
D.Strings[77493]="只要跟着我们卖掉这些骨头之后，你所发出的金钱的声音走就行了！"
D.Strings[77494]="伪装起作用了！那些笨蛋戈隆完全没有发现我们！"
D.Strings[77495]="现在，我们只要等他们睡着，然后带着骨头溜走就行了？"
D.Strings[77496]="对……嘿，你有没有觉得有东西在你脑袋上爬？"
D.Strings[77497]="我真后悔听了你的话……"
D.Strings[77498]="不如你来跟我们说说，你和你的好朋友帮钢铁部落造的这些机器？"
D.Strings[77499]="我跟你没什么好说的！"
D.Strings[77500]="噢，好吧，那我们就来硬的吧。"
D.Strings[77501]="这能不能让你的口风松一些？或者你还需要我们继续劝说一下？"
D.Strings[77502]="我是不会说的！我才不当叛徒！"
D.Strings[77503]="好好劝劝他们，伙计们。"
D.Strings[77504]="好吧，好吧！我说！让那些恶棍退远点！"
D.Strings[77505]="伙计们，去休息一下。让我们私下谈谈。"
D.Strings[77506]="中空的颅骨"
D.Strings[77507]="在角斗场的混乱和厮杀中，你们中间出现了一位胜利者。$n！欢呼$g他:她;的名字吧！今天，荣耀属于$n！"
D.Strings[77508]="来！向你们的冠军致敬吧！看看你们中最强的勇士所获得的财富吧！"
D.Strings[77509]="经过烈火的锤炼，我的力量无穷无尽，我的盟友英勇无畏！"
D.Strings[77510]="战斗开始了！最后一个活下来的角斗士将赢得胜利！"
D.Strings[77511]="我的身躯虽然倒下，但我的灵魂不灭。我将永远与你们同在。"
D.Strings[77512]="类似哈里森·琼斯那种江湖骗子可能不赞同我的做法，可石化需要数千年的时间！$b$b保存稀有而神奇的生物的最佳方法就是自己动手！$b$b既然你自己就能做得更好，何必要等上几千年让大自然来完成演化呢？"
D.Strings[77513]="你帮助了热砂保护协会，所以我们也要回报你！但别忘了，分享固然令人感动，但买卖还是要用真金白银的！"
D.Strings[77514]="<见你靠近，波兹尔疯狂地挥舞起手臂来。>$b$b哇！嘿！谁在那儿？$b$b噢，抱歉……自从遇到那个该死的……艾克加纳克后，我的视力就不大行了。"
D.Strings[77515]="法师们将在阿什兰西部召唤出一座传送门，让你快速返回暴风之盾堡垒。"
D.Strings[77516]="$n真是势不可挡！关注一下$g他:她;吧，卡加斯。"
D.Strings[77517]="你问我这些双头飞龙是不是从钢铁部落那里偷来的？$b$b那得看是谁问了！"
D.Strings[77518]="你看起来是个爱冒险的家伙！$b$b如果你在外面找到什么遗物或神器，请把它们带回来给我。我们可以做笔买卖！"
D.Strings[77519]="传信号角已经吹响了，为什么其他人还没来？"
D.Strings[77520]="估计是喝得醉死过去了吧。"
D.Strings[77521]="情况不对劲。我们好像被监视了。"
D.Strings[77522]="别管我，我只负责操纵全息投影仪而已！如果你想找工作，就去找那边的G先生吧！"
D.Strings[77523]="北方部队的动向还没有消息。"
D.Strings[77524]="我们的骑兵发现海滩上有火炮在移动。"
D.Strings[77525]="我们的战士突袭岗哨并将它烧毁了。"
D.Strings[77526]="我们斥候还没有传回任何消息。"
D.Strings[77527]="我们的舰队很快就能抵达钢铁码头。"
D.Strings[77528]="南边报告说他们损失惨重。"
D.Strings[77529]="我们的斥候发现了一个可以劫掠的车队。"
D.Strings[77530]="其他氏族还没有传来消息。"
D.Strings[77531]="我们的骑兵烧毁了那座村庄，没有留下任何活口。"
D.Strings[77532]="敌人的军队向西穿过了纳格兰。"
D.Strings[77533]="有鱼咬钩了吗？我发现耐心（还有啤酒）有助于钓到大鱼！"
D.Strings[77534]="你带冰镇饮料来了吗？出去钓鱼怎能不带冰镇饮料？！"
D.Strings[77535]="*嗝儿！*那是海豚吗？！*嗝儿！*我爱海豚！"
D.Strings[77536]="真的？我想我刚刚才把它扔回海里去了。"
D.Strings[77537]="*哈欠*看来你们需要一些外援了！"
D.Strings[77538]="观众们开始厌倦这场战斗了！或许一点焰火能让他们兴奋起来！"
D.Strings[77539]="这种节奏不合我的胃口！这或许能有所帮助……"
D.Strings[77540]="我的耐心已经到头了！我要让你们战斗起来！"
D.Strings[77541]="我马上就回来，给我留一杯啤酒！"
D.Strings[77542]="祝你走运钓到大鱼！"
D.Strings[77543]="你好，$n！今天还走运吗？"
D.Strings[77544]="$n，找到你了！"
D.Strings[77545]="雪狂悲伤地扒着碎石。"
D.Strings[77546]="我胜利了，但却付出了高昂的代价。"
D.Strings[77547]="呸！谁敢打翻我的啤酒……去死吧！"
D.Strings[77548]="我的意志……是不会被……打……垮的……"
D.Strings[77549]="所有的生者，化为尘土吧。"
D.Strings[77550]="粉身碎骨。"
D.Strings[77551]="让大地吞噬你。"
D.Strings[77552]="我……是……不朽的！"
D.Strings[77553]="碎裂吧。"
D.Strings[77554]="群山，动起来吧！"
D.Strings[77555]="太……强了！"
D.Strings[77556]="这……是……什么……"
D.Strings[77557]="连群山都……倒下了……"
D.Strings[77558]="软弱的血肉之躯。"
D.Strings[77559]="他的牺牲将被人民世代传诵……直至永远。"
D.Strings[77560]="卡拉克……黑暗在低语……有个声音！"
D.Strings[77561]="黑夜！我的鲜血……星辰……"
D.Strings[77562]="对，泰克图斯。臣服于主人的意志吧！"
D.Strings[77563]="不！你不明白！我们不能停下……"
D.Strings[77564]="谁敢阻挠燃烧军团？"
D.Strings[77565]="你的灵魂归主人了。"
D.Strings[77566]="过来吧，仆从们！"
D.Strings[77567]="这下好多！别再让我们失望了！"
D.Strings[77568]="难道我这个主人不热情吗？难道你们不觉得愉快吗？"
D.Strings[77569]="再让观众流失的话，我就要你们好看！"
D.Strings[77570]="|TInterface\\Icons\\spell_druid_massentanglement.blp:20|t你被|cFFFF0404|Hspell:176001|h[野性藤蔓]|h|r缠住了！"
D.Strings[77571]="你们白长了那么多肌肉，连块石头都砸不碎吗？！没用的独眼魔！"
D.Strings[77572]="就连死掉的塔布羊都比这些笨蛋独眼魔有用！"
D.Strings[77573]="|TInterface\\Icons\\Ability_Druid_EmpoweredTouch:20|t塔尔纳开始引导|cFFFF0404|Hspell:175979|h[源生]|h|r。"
D.Strings[77574]="嘿，你知道什么比一头独眼魔还要笨吗？"
D.Strings[77575]="两头独眼魔！哈哈哈！"
D.Strings[77576]="快回去干活，你这懒鬼独眼魔！"
D.Strings[77577]="你最好马上开始给我砸石头，否则我就揍扁你！"
D.Strings[77578]="别再游手好闲了，快去砸石头，你这笨蛋独眼魔！"
D.Strings[77579]="快进入荣耀之路！"
D.Strings[77580]="塞林马上就出发了。"
D.Strings[77581]="让那些独眼魔回去干活！"
D.Strings[77582]="控制住那个独眼魔，快！"
D.Strings[77583]="快让那些独眼魔干活，否则就砸碎他们的脑袋！"
D.Strings[77584]="你喜欢吃肉？我们这儿有新鲜的肉！你要多少？"
D.Strings[77585]="指挥官，能给我一点时间吗？"
D.Strings[77586]="我理解你对这个神器的担忧，米沙尔，但我们不能去干涉那些努力争夺它们的盟友。"
D.Strings[77587]="可是，女祭司，如果这个神器真有他们说的那么强大，它的持有者可能会造成巨大的灾难。"
D.Strings[77588]="所以我们才要确保让我们的盟友得到它。一但将它弄到手，我们会提供指引，确保不让它被滥用。"
D.Strings[77589]="要是他们不听呢？要是我们这些盟友对力量的渴望将他们引上毁灭的歧途怎么办？"
D.Strings[77590]="我喜欢地精，但他们都是糟糕的听众。"
D.Strings[77591]="让我们祈祷那一天不会到来吧，米沙尔。"
D.Strings[77592]="你看起来很烦恼，米沙尔。你在担心什么？"
D.Strings[77593]="是部落的军队，女祭司。为了抢夺神器，他们对我们大打出手。"
D.Strings[77594]="你觉得他们会不会用它来对付联盟？"
D.Strings[77595]="或许他们如此拼命只是因为害怕我们会用它来对付他们。"
D.Strings[77596]="谢谢你，指挥官。我会去你的要塞等你的。"
D.Strings[77597]="你心中只是存有一点疯狂的小火星……如果失去了它，你就什么也不是了。"
D.Strings[77598]="无论人们是怎么跟你说的，语言和思想可以改变世界。"
D.Strings[77599]="如果说我在德拉诺学到了什么，那就是永远不要和食人魔战斗，因为他们已经破罐破摔了。"
D.Strings[77600]="如果哈里森在寻找的这个神器和他想的一样强大，我希望它永远都不要被找到。\n\n无论是出于什么目的，强大的力量往往会导致灾难性的后果。"
D.Strings[77601]="不过，联盟也不全是坏人。如果你想来一场口头的大冒险，就去跟矮人喝酒吧。"
D.Strings[77602]="地精“工程学”——对了。你们地精有手有脑子，但你们的鲜血却一次只够一个用的！"
D.Strings[77603]="那些德莱尼怎么样？或者就像他们说的，另一个蓝皮种族。你怎么能相信一支用粉色宝石做战锤的军队呢？！"
D.Strings[77604]="你知道酒吧斗殴和兽人婚礼的差别吗？我也不知道。"
D.Strings[77605]="你们在这儿干得不错。你们有权携带武器，也有权武装巨熊。想干什么都没问题！"
D.Strings[77606]="指挥官，能占用你一点时间吗？"
D.Strings[77607]="有人去过银月城吗？我只在那里游玩了一个晚上。那是一个可怕、恶俗的地方。"
D.Strings[77608]="你会角色扮演吗？"
D.Strings[77609]="谢谢你，指挥官。我在你的要塞等你。"
D.Strings[77610]="让我看看入侵发生前的诅咒之地。"
D.Strings[77611]="嘿，各位，约翰·斯威夫提来了！"
D.Strings[77612]="看看这个吧！"
D.Strings[77613]="惊人的宇宙力量！"
D.Strings[77614]="小小的生存空间。"
D.Strings[77615]="战争不是偶然拜访此地，而是长驻于此。无论过去、现在还是未来，暴力在此地生生不息……"
D.Strings[77616]="我只打了一下。"
D.Strings[77617]="宏大之力！"
D.Strings[77618]="<卡格看起来很无聊。>"
D.Strings[77619]="卡格能帮你什么忙吗，角斗士？"
D.Strings[77620]="我想参加角斗场的战斗。"
D.Strings[77621]="进入角斗场需要100块破碎骨骼。确定要继续吗？"
D.Strings[77622]="那是什么？我还得再弄点来！"
D.Strings[77623]="永远别把卡利鸟养在卧室里。它们的耳朵尖着呢。"
D.Strings[77624]="钟距，我们得修好那辆坦克。我们前线的部队需要一些支援！"
D.Strings[77625]="我们需要双倍的碎石清理机器人，迅火。你想让哈里森·琼斯用鹤嘴锄挖地雷吗？"
D.Strings[77626]="日常维护还要多少时间，弹泡？那辆坦克几个小时前就该上战场了！"
D.Strings[77627]="摆钳呢？她已经折腾了那辆蜘蛛坦克几百年了！"
D.Strings[77628]="这些协调工作真是太累人了。我需要一杯冰啤酒。"
D.Strings[77629]="抱歉，角斗士，但你这周已经在角斗场中赢得过胜利了。请下周再来。"
D.Strings[77630]="你好像是指挥官啊……嗝儿！我一直都在对付兽人！……嗝儿！"
D.Strings[77631]="都结束了，雅各布。老老实实过来，我们将把你送上第一头狮鹫，前往专门关押叛徒的监狱。"
D.Strings[77632]="你已经当过冠军了！所以你六……百年内不能再在角斗场战斗了。或者是一周？我不知道！"
D.Strings[77633]="等等，你会喜欢这个的。"
D.Strings[77634]="那是什么声音？让我想起了狂奔的科多兽……"
D.Strings[77635]="你休想活捉我……嗝儿！"
D.Strings[77636]="空气中有股臭味。恶魔……"
D.Strings[77637]="真走运！我们又可以让恶魔知道真正的部落是不可战胜的了！"
D.Strings[77638]="终于能战个痛快了……"
D.Strings[77639]="睁大眼睛。他们可能从任何地方冒出来。"
D.Strings[77640]="我能感觉到他们就在下面……"
D.Strings[77641]="影月氏族是兽人之耻。我们每杀掉一个影月兽人，都是对其他人的一个教训。"
D.Strings[77642]="嘿，小鬼！"
D.Strings[77643]="噢！只当了两秒钟的女人，我就进入更年期了。"
D.Strings[77644]="严寒显然干扰了你……"
D.Strings[77645]="最近，有许多冒险者来到阿什兰。有些人是在赚钱的，其他人则是来帮助联盟对抗部落的。\n\n你想在这里得到些什么呢，朋友？"
D.Strings[77646]="从远处看，你的个子很矮。"
D.Strings[77647]="指挥官，我们会按你的吩咐集结部队的。"
D.Strings[77648]="我的力量只比我的身高略差一点！"
D.Strings[77649]="希望这最后一个能比其他的大一些。"
D.Strings[77650]="我是不会让你死的！"
D.Strings[77651]="他们的首领就在这里。为了部落！"
D.Strings[77652]="失败了？不！查尔斯，你在哪儿？！"
D.Strings[77653]="无论是生前还是死后，你都得仰视我！"
D.Strings[77654]="让我们把这些食人魔打回悬槌堡去！"
D.Strings[77655]="现在，让我们好好教训一下这些魔崽子吧！"
D.Strings[77656]="日与月的力量在我体内奔流，发出震耳欲聋的轰鸣！"
D.Strings[77657]="以艾露恩的名义，我会带着更强的力量回来的！"
D.Strings[77658]="我从没想过自己会厌倦砸人脑袋。"
D.Strings[77659]="他们都脑子发热了，根本不知道自己已经失败了！"
D.Strings[77660]="轰隆隆！"
D.Strings[77661]="所有人，向$n致敬吧！角斗场的冠军！角斗士的王者！"
D.Strings[77662]="既然戈隆来了，那鬣蜥人也不远了。快让农夫们都躲到安全的地方去！"
D.Strings[77663]="小心那些鲜花和藤蔓。任何植物都有可能是我们的敌人……"
D.Strings[77664]="你好像是指挥官啊……嗝儿！我一直都在对付联盟！……嗝儿！"
D.Strings[77665]="都结束了，洛卡。老老实实过来，我们将把你送上第一头双足飞龙，前往专门关押叛徒的监狱。"
D.Strings[77666]="臣服于钢铁部落的力量吧！"
D.Strings[77667]="我要把你的脑袋挂在斧子上！"
D.Strings[77668]="看来我得亲自对付这个家伙了！"
D.Strings[77669]="你以为你是要去哪儿？"
D.Strings[77670]="这个……部落杂碎……很厉害。"
D.Strings[77671]="这里的战斗白热化了……"
D.Strings[77672]="你以为我像巴琳达那么好对付吗？哈！"
D.Strings[77673]="冻死一个。"
D.Strings[77674]="下次穿暖和点。"
D.Strings[77675]="我在燃烧！"
D.Strings[77676]="就是它了，士兵们。集中精神，我们得搞定它。"
D.Strings[77677]="敌军指挥官来了！这就和过去一样。"
D.Strings[77678]="啊，我的脚趾又恢复知觉了。谢谢你$G兄弟:姐妹;。我不会忘记你的帮助的。"
D.Strings[77679]="如火如荼的战斗！"
D.Strings[77680]="我还会……再站起来的。"
D.Strings[77681]="我在燃烧。"
D.Strings[77682]="对你的治疗者说声“呸”吧！"
D.Strings[77683]="到处都不见戈达乌的身影！这肯定是卡拉迪奥斯的仆从干的！用泥土埋住空气……挡住狂风！"
D.Strings[77684]="大地之怒离开了王座！戈达乌的仆从必须得到惩罚……将泥土像碎石一样抛洒在风中吧！"
D.Strings[77685]="大地之怒失踪了，埃布留斯的仆从对王座毫无帮助！如果水拒绝流动……就让我们煮沸他们！"
D.Strings[77686]="戈达乌的仆从失控了！伊森拉图斯的追随者在肆无忌惮地熊熊燃烧！净化高原……淹死低级元素，冲走它们！"
D.Strings[77687]="啊……一股美妙的凉风。"
D.Strings[77688]="|cFFFF0000|Hspell:155187|h[炸弹]|h|r将在倒计时结束或被携带它的玩家触发后对影响范围内的所有玩家造成伤害。"
D.Strings[77689]="|TInterface\\Icons\\ability_foundryraid_traindeath:20|t你被一辆|cFFFF0000|Hspell:156554|h[进站的火车]|h|r压死了。当轨道门开启时，不要站在轨道上。"
D.Strings[77690]="我都几百年没来过这儿了。"
D.Strings[77691]="你被|TInterface\\Icons\\ability_whirlwind:20|t |cFFFF0000|Hspell:157943|h[旋风斩]|h|r砍死了。在|cFFFF0000|Hspell:157943|h[旋风斩]|h|r发动期间，请不要靠近费莫斯。"
D.Strings[77692]="|cFFFF0000|Hspell:176123|h[不稳定的火焰]|h|r效果结束，对不稳定的火焰的携带者及其附近的所有玩家造成了伤害。"
D.Strings[77693]="每当山脉之心的能量达到100时，将使用|cFFFF0000|Hspell:155209|h[冲击]|h|r对所有玩家造成伤害。"
D.Strings[77694]="|cFFFF0000|Hspell:155223|h[熔化]|h|r存在于场上时，将每秒对其影响范围内的所有玩家造成一次伤害。"
D.Strings[77695]="当你身上的|cFFFF0000|Hspell:155240|h[淬火]|h|r叠加得越多，|cFFFF0000|Hspell:155242|h[高热]|h|r对你造成的伤害就越高。"
D.Strings[77696]="一旦山脉之心离开爆裂熔炉，就将激活|cFFFF0000|Hspell:155743|h[熔渣池]|h|r并持续烧灼滞留在其影响范围内的所有玩家。"
D.Strings[77697]="你被|cFFFF0000|Hspell:175104|h[熔化护甲]|h|r集中的次数越多，它对你造成的伤害就越高。与其他玩家轮流吸引监工长石的注意可以让你消去熔化护甲效果。"
D.Strings[77698]="熔渣元素的生命值耗尽后，将转化为|cFFFF0000|Hspell:176133|h[炉渣炸弹]|h|r。"
D.Strings[77699]="在你吸引屠夫的注意力期间，|cFFFF0000|Hspell:156147|h[切肉刀]|h|r效果会逐渐叠加。"
D.Strings[77700]="在你吸引屠夫的注意力期间，|cFFFF0000|Hspell:156143|h[捶肉槌]|h|r造成的伤害会越来越高。"
D.Strings[77701]="|cFFFF0000|Hspell:156153|h[龟裂创伤]|h|r会立即击杀所有拥有9层以上龟裂创伤效果的玩家。"
D.Strings[77702]="|cFFFF0000|Hspell:156157|h[顺劈斩]|h|r将由所有目标分摊，并始终选择近战范围内数量最多的一群人为目标。"
D.Strings[77703]="啊， 船长！我的船长！"
D.Strings[77704]="|cFFFF0000|Hspell:156138|h[势大力沉]|h|r会攻击距离屠夫的当前坦克目标最近的目标， 如果范围内没有其他坦克则攻击其当前坦克目标两次。"
D.Strings[77705]="大地会碾碎你这凡人的骨头！"
D.Strings[77706]="你竟敢面对风暴的怒火？！"
D.Strings[77707]="%s准备发射|cFFFF0404|Hspell:168148|h[火炮弹幕]|h|r！快躲到掩体后面去！"
D.Strings[77708]="我死了！"
D.Strings[77709]="我的水流将净化你可悲的肉体凡胎！"
D.Strings[77710]="我为什么不能参加战斗？"
D.Strings[77711]="我的烈焰将把你的骨头烧成灰烬！"
D.Strings[77712]="%s开始引导|cFFFF0404|Hspell:157059|h[纠缠之地符文]|h|r，快用符文保护自己！"
D.Strings[77713]="|cFFFF0404|Hspell:163590|h[滑溜溜的苔藓]|h|r正在扩散！快使用火焰喷射器控制其蔓延速度！"
D.Strings[77714]="%s的|cFFFF0404|Hspell:155539|h[毁灭之怒]|h|r状态结束。"
D.Strings[77715]="你已经获得过胜利了，角斗士。在本周内，你不能再次参加战斗。"
D.Strings[77716]="大主教的职责就是领导德莱尼人民。我们代表并维护着德莱尼社会的价值观。"
D.Strings[77717]="它本身并不是世界末日，可你显然能从中看到末日的景象！"
D.Strings[77718]="最近，阿什兰的局势变得非常危险了。今天早上，我差点被一颗狂怒的古树削掉脑袋！"
D.Strings[77719]="联盟肯定是急于夺取神器并用它的力量来对付我们。"
D.Strings[77720]="自然之怒怎能如此滥用。他们最后一定会为此付出代价的。"
D.Strings[77721]="德拉诺的原始之力狂野不羁。它们似乎不愿受任何控制。"
D.Strings[77722]="这一定会让你在战场上很难受吧。"
D.Strings[77723]="还行。我还有牙齿和爪子呢。"
D.Strings[77724]="你听说了吗？血精灵说他们在矿井里有大发现。"
D.Strings[77725]="什么，一把巨型斧子吗？"
D.Strings[77726]="傻瓜，才不是斧子呢！他们说那就是联盟在找的那个巨型神器的一部分。"
D.Strings[77727]="呸！谁关心那些老掉牙的出土文物。我是来砸联盟的脑袋的。"
D.Strings[77728]="你明白我们为什么要来阿什兰吗？"
D.Strings[77729]="我只在乎我们又能和人类开战了。我正手痒呢，我要打个痛快！"
D.Strings[77730]="我已经好几年没来过这样的野外了。$B$B<威严的大法师深吸了一口气。>$B$B再也没有比清新的空气和危险更迷人的味道了。"
D.Strings[77731]="如果要我说，这个任务应该交给我来负责。可大法师卡德加坚持说你会带来惊喜。"
D.Strings[77732]="我身上还有恶魔第一次入侵艾泽拉斯时造成的伤口。我还记得那种笼罩在被毁灭的城市上空的恐怖、疯狂和寂静。$B$B我会尽我所能防止这种惨剧重演。"
D.Strings[77733]="我不明白为什么会有人投靠燃烧军团。$B$B那都是些渴望力量，又不懂得如何运用它的家伙。"
D.Strings[77734]="萨格雷的村庄就像一个蜂窝。$B$B要是我们惊动了里面的居民，一定会被叮得满头包。可如果烧掉它，又会损失宝贵的蜂蜜。$B$B唯一的办法就是通过潜入来获取我们需要的信息。"
D.Strings[77735]="我今天和督军沃拉斯谈了谈。他担心我们的部队会拒绝进入墓地。"
D.Strings[77736]="拿起武器！各就各位！雷神氏族来找茬了。"
D.Strings[77737]="噢，是吗？你为什么会这么想？"
D.Strings[77738]="我已经耍够你们了！"
D.Strings[77739]="从那儿回来的步兵报告说看到了奇怪的幽灵。他们说有死灵法师在驱使古代食人魔的鬼魂。"
D.Strings[77740]="食人魔鬼魂？难怪他们都不肯过去了。我不怕任何东西，可我还是喜欢能用斧子实实在在劈死的敌人。"
D.Strings[77741]="大主教奥萨尔的背叛非常突然。一位德莱尼的领袖怎么会就此背弃圣光，投靠了曾迫害过他整个民族的敌人呢？"
D.Strings[77742]="我已经看够了。你自己慢慢地打吧，伟大而强大的“陛下”。"
D.Strings[77743]="我们的任务无比艰巨，但却是必要的。"
D.Strings[77744]="他的新盟友给了他新的名字，和新的身份——“索克雷萨”。他是个强大的敌人，我很担心他能做到哪一步。"
D.Strings[77745]="你好，指挥官。你想看看最近发生的重大事件吗？"
D.Strings[77746]="让我看看沙塔斯之战的情景。"
D.Strings[77747]="你听说过我吗，$n？我是隶属于六人议会的大法师茉德拉，肯瑞托和达拉然的统治者之一。$B$B如果我愿意，我可以彻底夷平这座村庄。$B$B可那不是我们来这里的原因。根据我多年来学到的经验，有时你只需要一点蜂蜜就能引来苍蝇。"
D.Strings[77748]="Lok'tar，指挥官。你想看看最近发生的重大事件吗？"
D.Strings[77749]="快看！那是$n！"
D.Strings[77750]="那是$n吗？据说$G他:她;是有史以来最强大的$c！"
D.Strings[77751]="看来$n来帮我们砸联盟的脑袋了！"
D.Strings[77752]="你能为我做点食物吗？"
D.Strings[77753]="今天外面有点热，你觉得呢？"
D.Strings[77754]="联盟自以为聪明，一边拿停战协议做挡箭牌，一边在这座岛上大肆搜索超级武器，还不要我们的帮助。\n\n当然，他们会说这件武器是拿来对付钢铁部落的。可谁能保证等我们在这个世界的任务完成后，他们不会用它来对付我们呢？\n\n我觉得我们应该把那件武器弄到手，让他们知道谁才是老大——不管是在这个世界还是我们的世界。\n\n为了部落！"
D.Strings[77755]="我们收到了前线发来的报告，伙计！"
D.Strings[77756]="你做的很好。现在，回战场上去吧。"
D.Strings[77757]="我们的报告显示岗哨外面有一群充满敌意的鸦人流亡者。"
D.Strings[77758]="你说鸦人流亡者？我以为我们已经跟他们结盟了。"
D.Strings[77759]="我得去跟我们的鸦语者朋友聊聊，搞清这群鸦人的真实身份。"
D.Strings[77760]="头儿，我们的斥候说联盟正在强化一棵巨型古树，并准备将它派到战场上来！"
D.Strings[77761]="哈！如果他们以为一棵大树就能吓倒部落的话，那就让我们给他们一个惊喜吧！"
D.Strings[77762]="等他们脚下的大地都站在我们一边时，不知道他们会是什么表情？！"
D.Strings[77763]="那个精灵，贝洛克说他需要更多人手来帮他找那件神器。"
D.Strings[77764]="我没对那个贝洛克失去耐心都算他走运了！我不会再让我的士兵们去帮他挖古董了。"
D.Strings[77765]="你告诉那个精灵，我会让自愿报名的人去帮他。他最好在我看腻他那张脸之前把事情都搞定！"
D.Strings[77766]="我们从外面的斥候那里收到了一些奇怪的报告，都是有关一座巨型食人魔矿井的。"
D.Strings[77767]="他们说矿井里有一只巨大的生物，能秒杀所有多看了它两眼的步兵。"
D.Strings[77768]="我是个大师级的说客，可萨格雷似乎更看重实力，而非语言。$B$B赢得他们信任的最快办法就是战斗。我相信这就是茉德拉派你来帮我的原因。"
D.Strings[77769]="我们的步兵确实很厉害，可他们没本事对付这样的怪物。我会派暗影猎手过去，看看这家伙到底有多厉害。"
D.Strings[77770]="雷神兽人想让我们尝尝复仇的厉害。但事实正相反，我们要让他们学会谦卑。"
D.Strings[77771]="第一波冲锋被击溃了。"
D.Strings[77772]="散开！别让他们攻击我们的侧翼！"
D.Strings[77773]="我们就快胜利了！"
D.Strings[77774]="真固执。就是这样，士兵们。为了联盟！"
D.Strings[77775]="接住时间炸弹，将其送回空中！"
D.Strings[77776]="记住，闭紧你的嘴巴。这样万一你被闪电击中，也不会咬断自己的舌头了。"
D.Strings[77777]="前方有人在哭"
D.Strings[77778]="里面有死人"
D.Strings[77779]="前方需要盟友"
D.Strings[77780]="死亡幻像"
D.Strings[77781]="保持冷静"
D.Strings[77782]="前方有战利品"
D.Strings[77783]="数千年前，燃烧军团的恶魔来到我们的家园，为我们的领袖送上一份大礼。$B$B其中的两位，基尔加丹和阿克蒙德看出了他们的提议中所蕴含的智慧，可最后一位领袖，先知维伦却拒绝了。$B$B他和他的追随者逃出了那个世界，被那些曾向他们伸出友谊之手的人永世追杀。$B$B维伦是个蠢货！而作为这些蠢货的后裔，我们仍旧拒绝天堂的召唤！$B$B但一切到此为止了，我的兄弟们！今天，我们将臣服于恶魔领主。他们又给了我们一次分享力量的机会。$B$B我的兄弟姐妹们，这，才是我们真正的命运。今天，我们要踏上艾瑞达的先驱们走过的道路，未来将属于我们！"
D.Strings[77784]="燃烧军团的行动决不能再受干扰。德拉诺有一些人想要阻挠他们的计划，尤其是那些无信者——那些依然追随圣光的德拉尼。$B$B去消灭我们的同胞，确保我们的主人免受干扰。击败那些德莱尼人，向燃烧军团表明我们的忠诚。只要毁灭沙塔斯，恶魔就将赐予我们不朽的荣耀！"
D.Strings[77785]="我们德莱尼是天选的民族……文明、优雅，具有高度的智慧。$B$B世间没有我们的头脑无法理解的技术，也没有我们的法师无法掌握的魔法。$B$B我们在阿古斯建立了辉煌灿烂的文明。$B$B我们的人民从不沉迷也不畏惧自己的潜力。$B$B我们的人民注定要征服星辰大海！$B$B团结起来吧，兄弟姐妹们，让我们夺取理应属于我们的一切！"
D.Strings[77786]="爸爸什么时候回来？"
D.Strings[77787]="%s开始施放|cFFFF0404|Hspell:176464|h[时光涟漪]|h|r！快寻找掩护！"
D.Strings[77788]="爸爸还在打猎吗？"
D.Strings[77789]="我想造一座新建筑。"
D.Strings[77790]="我能为您提供最好的服务，指挥官。"
D.Strings[77791]="你可以在绘图桌上作出选择，指挥官。"
D.Strings[77792]="强化我的护甲和武器，不让它们变钝。"
D.Strings[77793]="兰吉特在|cFFFF0000$n|r附近制造了一堵|cFFFF0000|Hspell:153759|h[风墙]|h|r！"
D.Strings[77794]="兰吉特运用了他的秘术，|cFFFF0000|Hspell:156793|h[四风呼啸]|h|r！"
D.Strings[77795]="|TInterface\\Icons\\ability_fixated_state_red:20|t一颗太阳耀斑|cFFFF0000|Hspell:176544|h[锁定]|h|r了你！它将在接触你之后 |cFFFF0000|Hspell:153828|h[爆炸]|h|r！"
D.Strings[77796]="一颗太阳耀斑|cFFFF0000|Hspell:176544|h[锁定]|h|r了|cFFFF0000$n|r！"
D.Strings[77797]="|cFFFF0000$n|r成为了鸦人|cFFFF0000|Hspell:154043|h[超级武器]|h|r的目标！"
D.Strings[77798]="|cFFFF0000$n|r将被|cFFFF0000|Hspell:153954|h[扔下]|h|r平台！"
D.Strings[77799]="在被遗忘者的力量面前颤栗吧！"
D.Strings[77800]="我来无影去无踪。"
D.Strings[77801]="你可能会有一点疼。"
D.Strings[77802]="你已经死了。"
D.Strings[77803]="让我们一起跳舞吧。"
D.Strings[77804]="别让我觉得无聊。"
D.Strings[77805]="正中眉心。"
D.Strings[77806]="你将臣服于死亡。"
D.Strings[77807]="根本不费吹灰之力。"
D.Strings[77808]="你连变成食尸鬼的资格都没有。"
D.Strings[77809]="我就知道你坚持不了多久。"
D.Strings[77810]="你不配得到我的怜悯。"
D.Strings[77811]="你有什么打算，指挥官？"
D.Strings[77812]="愿黑暗女王保佑你。"
D.Strings[77813]="我会代你向黑暗女王问好的。"
D.Strings[77814]="我的弓已经准备好了。"
D.Strings[77815]="你的意志必将实现。"
D.Strings[77816]="有何吩咐，指挥官？"
D.Strings[77817]="你会为此……付出代价的……"
D.Strings[77818]="别担心，我马上就好。"
D.Strings[77819]="你想让我先干掉你？就在这儿……怎么样？"
D.Strings[77820]="让我给你演示一下真正的战斗。"
D.Strings[77821]="我会慢慢干掉你，好好品味你的尖叫声的。"
D.Strings[77822]="你想跟我打架，对吧？"
D.Strings[77823]="让我看看你的本事吧，杂种。"
D.Strings[77824]="你肯定反应不过来。"
D.Strings[77825]="很好。我就先杀了你。"
D.Strings[77826]="喔唷。那是我干的吗？"
D.Strings[77827]="叫大声点，好吗？我都听不清了！"
D.Strings[77828]="这就是黑铁矮人的行事方法。"
D.Strings[77829]="我好像捅了你太多下了。"
D.Strings[77830]="难以置信，你居然这么弱。"
D.Strings[77831]="其实这根本算不上是战斗。"
D.Strings[77832]="好吧，你死了，这是你自找的。"
D.Strings[77833]="我能为你做点什么吗？"
D.Strings[77834]="很荣幸见到你。"
D.Strings[77835]="我的剑为你所用，指挥官。"
D.Strings[77836]="需要我帮你“料理”什么人吗，指挥官？"
D.Strings[77837]="我不会让你失望的。"
D.Strings[77838]="只要你指出方向，我立刻出发。"
D.Strings[77839]="啊……他们杀了我……"
D.Strings[77840]="跪下，奴隶！"
D.Strings[77841]="哪个食人魔能把这个渣滓的脑袋带来给我，就奖100个金币！"
D.Strings[77842]="我正在施放一个冷却时间极长的法术。"
D.Strings[77843]="再甩一次杆……"
D.Strings[77844]="糟糕的钓鱼日也比最好的工作日强。"
D.Strings[77845]="在钓鱼上花了太多的时间？能有这种问题是好事。"
D.Strings[77846]="$N是受我们保护的。"
D.Strings[77847]="你别想伤害这个$c。"
D.Strings[77848]="这个$r是受熔炉守卫保护的。"
D.Strings[77849]="我要把你们烤熟了，宝贝儿们！"
D.Strings[77850]="那么是哪个蠢货准备好好挨一顿打？！"
D.Strings[77851]="你先上吧。我来做点魔法水。"
D.Strings[77852]="我很乐意和你一起痛打这个傲慢的废物！"
D.Strings[77853]="我这里有些你会喜欢的东西！"
D.Strings[77854]="见识米尔豪斯·法力风暴的全部力量吧！"
D.Strings[77855]="祝你下次好运，哇哈哈哈哈哈！"
D.Strings[77856]="你好，指挥官！我是你忠实的仆人米尔豪斯·法力风暴！"
D.Strings[77857]="你不会刚好弄到什么大杀器了吧？"
D.Strings[77858]="让我去对付他们吧！"
D.Strings[77859]="等等，就一秒，我给自己上个Buff。"
D.Strings[77860]="我们什么时候去毁灭世界？马上？我真希望马上就去。"
D.Strings[77861]="你们都将成为我的奴隶！呃，我是说，嗨！"
D.Strings[77862]="如果你有什么多余的、遗失在时间长河中的宝贝神器，我很乐意接手。"
D.Strings[77863]="你有没有被石头做的虫子打过脸？那种感觉就和它发出的声音是一样的。"
D.Strings[77864]="克鲁德来了！所有自以为能打倒克鲁德的白痴最好准备好供品。只有足够的供品才能避免克鲁德觉得无聊，并为自己赢得被克鲁德开膛破肚的荣幸。"
D.Strings[77865]="哈！你一定想让克鲁德把你劈成两半。克鲁德非常乐意给你这个荣幸！"
D.Strings[77866]="哈！克鲁德就知道没人敢面对克鲁德的。你连克鲁德的一半都及不上。"
D.Strings[77867]="等这场战斗结束后，掘墓人估计得花上几天时间才能辨认出哪块残肢是属于哪具尸体的。"
D.Strings[77868]="可悲……克鲁德只要一半的时间就能杀了……"
D.Strings[77869]="谢谢你饶了利奥拉。"
D.Strings[77870]="利奥拉和太阳石会好好为你效劳了。为氏族争光！"
D.Strings[77871]="嘀……嗒……嘀……嗒。"
D.Strings[77872]="是谁放的炸弹？是我。"
D.Strings[77873]="该去砸碎几个脑袋了。"
D.Strings[77874]="你别想进入鲜血竞技场。"
D.Strings[77875]="什么时候连恶棍都能进入试炼场了？"
D.Strings[77876]="让我们速战速决吧。"
D.Strings[77877]="我整天都在砍杀你这种废物。"
D.Strings[77878]="哈！你以为自己能过得了我这关？"
D.Strings[77879]="小心那头野兽，你们这些蠢货！我可是花了九牛二虎之力才把它弄到这儿来的！"
D.Strings[77880]="别发呆了，快把那头野兽关进笼子里去！"
D.Strings[77881]="快干活，白痴！这野兽比你们的性命加起来还要值钱！"
D.Strings[77882]="如果联盟想挑战沃拉斯，那他们得先过了我这关。"
D.Strings[77883]="万灵与你同在，指挥官。"
D.Strings[77884]="小心阴影，指挥官。"
D.Strings[77885]="很久以前，当刃牙虎人还没有在此横行的时候，它曾是个宁静的村庄。刃牙虎人趁着夜色入侵，在睡梦中谋害了我们。$b$b如今，我的同胞只剩下了地下的骸骨。"
D.Strings[77886]="抱歉，$G小伙子:小丫头;，我不能让你进入仓库。\n\n这里是琼斯博士保存神器的地方。虽然探险者协会允许冒险者将自己的装备存入空余的仓库，但这座仓库依然不对外开放。"
D.Strings[77887]="翻开了他的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cFFFFFFFF[普通炉石卡牌]|r！"
D.Strings[77888]="翻开了她的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cFFFFFFFF[普通炉石卡牌]|r！"
D.Strings[77889]="剁碎了酿酒。"
D.Strings[77890]="好了，姑娘小伙们，黄金时间到了！"
D.Strings[77891]="我不在乎你们有多少人，只要我挥挥手，你们全得趴下。"
D.Strings[77892]="翻开了他的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cFF0070dd[稀有炉石卡牌]|r！"
D.Strings[77893]="翻开了她的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cFF0070dd[稀有炉石卡牌]|r！"
D.Strings[77894]="翻开了他的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cFFa335ee[史诗炉石卡牌]|r！"
D.Strings[77895]="翻开了她的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cFFa335ee[史诗炉石卡牌]|r！"
D.Strings[77896]="死老鼠！"
D.Strings[77897]="这真是笔亏本的买卖。"
D.Strings[77898]="翻开了他的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cffff8000[传奇炉石卡牌]|r！"
D.Strings[77899]="翻开了她的|Hitem:118427|h|cFFFFFFFF[亲笔签名的炉石卡牌]|r|h，露出了一张|cffff8000[传说炉石卡牌]|r！"
D.Strings[77900]="我的呕吐物都比你强。"
D.Strings[77901]="我不知道应该吻你……还是揍你。"
D.Strings[77902]="我想打个痛快！"
D.Strings[77903]="非胜即死。我们别无选择。"
D.Strings[77904]="我经过长期艰苦的努力才获得为你效力的机会，指挥官。$B$B这真是我的荣幸。"
D.Strings[77905]="遵命，指挥官。"
D.Strings[77906]="好的，指挥官。"
D.Strings[77907]="幸运饼干说……"
D.Strings[77908]="噢，天呐……"
D.Strings[77909]="可怕，太可怕了。"
D.Strings[77910]="拜托，得了吧。"
D.Strings[77911]="什么？！拜托，那可是黄金啊，伙计。"
D.Strings[77912]="你看到他脸上的表情了吗？"
D.Strings[77913]="那是无价之宝！"
D.Strings[77914]="凯米尔！是你吗？"
D.Strings[77915]="你好啊。我们收到风声说，在这个名为阿什兰的地方藏着一些神器，是由一些残余的悬槌食人魔留下的。$B$B你能想象它们会具有怎样的威力吗？$B$B"
D.Strings[77916]="我们得尽快返回那里。"
D.Strings[77917]="对，我知道，但那些发疯的鸟真是吓着我了。"
D.Strings[77918]="欢迎，我的朋友，快来送死吧。"
D.Strings[77919]="继续！给我一个治疗自己的理由吧。"
D.Strings[77920]="……唉……"
D.Strings[77921]="试试用这个来治疗吧。"
D.Strings[77922]="你该带个好点的治疗来的，我的朋友。"
D.Strings[77923]="我期待能为你治疗，指挥官。"
D.Strings[77924]="让我为你送上最温暖的祝福。"
D.Strings[77925]="我的坦克呢……？"
D.Strings[77926]="你好啊，指挥官$n。"
D.Strings[77927]="Lok-tar ogar！非胜即死！"
D.Strings[77928]="为了岩牙！"
D.Strings[77929]="死得好。"
D.Strings[77930]="和你的尊严一起去死吧。"
D.Strings[77931]="对！一场精彩的战斗！"
D.Strings[77932]="霜狼时刻准备着。"
D.Strings[77933]="我的斧子已经准备好了。"
D.Strings[77934]="奈鲁克渴望战斗。"
D.Strings[77935]="钢铁部落将为我死去的兄弟姐妹们付出代价。"
D.Strings[77936]="洛卡拉……原谅我……"
D.Strings[77937]="|cFFFF0000警告!|r! 你已经进入了极其危险的区域! |cFFFF0000快离开|r!"
D.Strings[77938]="等你死后，我要把你的鞋据为己有。"
D.Strings[77939]="是时候让你好好吃点苦头了！"
D.Strings[77940]="又多了一颗脑袋。"
D.Strings[77941]="我要它的腰带。"
D.Strings[77942]="我要留下它的鼻子。"
D.Strings[77943]="这颗脑袋太小了，没法用。再给我来一个！"
D.Strings[77944]="等你死后，我能拿走你的脑袋吗？"
D.Strings[77945]="我可以用你敌人的尸体做一个图腾。"
D.Strings[77946]="哈哈哈哈……呃……你好。"
D.Strings[77947]="不！我的护身符不见了。"
D.Strings[77948]="啊，英雄……我就知道你会来的。看清楚你们的送葬者吧！"
D.Strings[77949]="现在，我就让你尝尝钢铁部落的新力量！"
D.Strings[77950]="我们一直在研究这个“高格里克之心”。它和我们在艾泽拉斯发现的某些泰坦神器有很多相似之处。"
D.Strings[77951]="在确定这件神器的来源和作用之前，我们得寻求专家的帮助。事实上，我们可能需要将这个装置运回艾泽拉斯做进一步的研究。"
D.Strings[77952]="我们在戈尔隆德发现的神器上似乎有一个跟它很相似的签名。$B$B我们几乎可以确定那个东西就是这个完整的大装置上的一个小碎片。$B$B如果那个小碎片可以召唤出一头巨型生物来协助你，那这个装置能召唤出什么？"
D.Strings[77953]="我们为什么非要去影月谷？罗明知道我最讨厌黑暗了……"
D.Strings[77954]="我改进了我们的地图，用不同颜色标示出了每个目的地的危险等级！"
D.Strings[77955]="你有没有尝过当地的美食？这些德莱尼很会做菜。"
D.Strings[77956]="你去过新月之炉吗？那里的馅饼非常美味。安波里村呢？那里有每天从艾洛多尔运来的新鲜食材！"
D.Strings[77957]="我喜欢影月谷。它是如此宁静祥和……不像那个满地骨头的鬼地方。"
D.Strings[77958]="当我们改进了这艘船，我要用半价换掉所有的零件！"
D.Strings[77959]="这艘船相当正点！"
D.Strings[77960]="扎格喜欢小猫咪。扎格把他的小猫咪都训练成了可爱的小战士。\n\n怎么了？干嘛那么看我？\n\n你对猫咪有意见吗？"
D.Strings[77961]="你应该去奥格瑞玛找瓦佐克聊聊！城里的任何卫兵都能为你指路。\n\n萨满小屋里有通往奥格瑞玛的传送门。祝你好运！"
D.Strings[77962]="$n引爆了毁灭共鸣！"
D.Strings[77963]="我见过刃牙虎人残害无辜。我见过它们将我剩下的族人扔进那口可怕的大锅里烹煮。现在……该轮到这些刃牙虎人下地狱，进油锅了！"
D.Strings[77964]="你的行为纪念了我的族人，$c。带着这份祝福踏上旅途吧，让它指引你的双手，并让你的脚步更加轻快。"
D.Strings[77965]="伙计，我以为跟着族人一起来到这里会是一趟美妙的旅行。我真是大错特错！"
D.Strings[77966]="这地方怎么了？挖掘工作也没那么糟吧。"
D.Strings[77967]="我担心的不是挖掘工作。只是不管你走到哪里，不是遇上想砸烂你脑袋的食人魔，就是遇上想一剑捅死你的联盟杂碎！"
D.Strings[77968]="我记得你跟我说过你只会嘲笑危险？听起来你好像在害怕这个地方。"
D.Strings[77969]="噢，我不是害怕，小鬼。只是死亡让利润急剧减少了。"
D.Strings[77970]="这些兽人就只喝啤酒吗？作为地精，要想在这里喝一杯美妙的鸡尾酒该怎么办呢？"
D.Strings[77971]="啤酒也不错。它让我想起了故乡。"
D.Strings[77972]="故乡？那种泔水是怎么引发你的思乡之情的？"
D.Strings[77973]="呃，它的味道让我想起了老家那儿冷却机器用的径流水。在我小时候，我们只能喝那种水。"
D.Strings[77974]="哇，这真是……说的太精辟了。"
D.Strings[77975]="不如让我们来看看，这些诡异的恶作剧背后究竟是谁在捣鬼吧？"
D.Strings[77976]="经历过突袭黑暗之门的惨重伤亡之后，我们大部分残余的部队都在阿什兰重新集结了起来。可惜没过多久就又爆发了与联盟的战争。\n\n你也是来避难的吗？还是想来进一步挑起战火的？"
D.Strings[77977]="时空对接开始了！"
D.Strings[77978]="这些巨魔还不赖。虽然他们都瘦得皮包骨头，而且口音也很滑稽，但他们真的很会玩长矛！\n\n我已经等不及想用这玩意儿串几个矮人来玩儿了！"
D.Strings[77979]="哇！它成功了。我们的时空也没有发生逆转。"
D.Strings[77980]="广告牌上写着：\n\n“我是指挥官$n，这里是我在战争之矛最喜欢光顾的商店。”"
D.Strings[77981]="别在意那个牌子，伙计。只是一个小“广告”，不会伤害任何人的。"
D.Strings[77982]="这没必要诉诸武力。"
D.Strings[77983]="让圣光将你烧成灰烬。"
D.Strings[77984]="为了沙塔尔。"
D.Strings[77985]="为了联盟，为了国王！"
D.Strings[77986]="你站错队了。"
D.Strings[77987]="你的任务失败了。"
D.Strings[77988]="指挥官，我觉得建一座旅店一定能大大提升士气。"
D.Strings[77989]="指挥官，我计算了你的防御力量，觉得如果重新平衡一下兵力一定会大有益处。"
D.Strings[77990]="指挥官！……王子殿下什么时候来？"
D.Strings[77991]="如果我写一封信，你能帮我把它送到暴风城吗？"
D.Strings[77992]="我听说你们有一位追寻圣光之道的王子。他最近会来这里访问吗？"
D.Strings[77993]="为了……圣光。"
D.Strings[77994]="大主教哈塔鲁的灵魂开始施放|cFFFF0000|Hspell:176784|h[痛苦力场]|h|r！"
D.Strings[77995]="让我们看看你的骨头长什么样。"
D.Strings[77996]="愿意帮忙做个实验吗？"
D.Strings[77997]="噢，别动。我想试验一个新法术。"
D.Strings[77998]="你是动物、植物、矿物还是别的什么东西？"
D.Strings[77999]="我主要跟化石打交道，所以，这或许会有点疼。"
D.Strings[78000]="噢，这只是个巧合。"
D.Strings[78001]="有趣的结果。"
D.Strings[78002]="下次得记住了，$n对火非常敏感。"
D.Strings[78003]="这片土地下埋着各种闪闪发光的小玩意儿。"
D.Strings[78004]="嘿，指挥官。等你死后，我能按惯例接手这个地方吗？"
D.Strings[78005]="为化石而生，死后归于化石。"
D.Strings[78006]="膝——盖——！"
D.Strings[78007]="死！去死去死去死去死！"
D.Strings[78008]="唔。肉的味道！"
D.Strings[78009]="晚餐时间？晚餐时间！！！"
D.Strings[78010]="看起来很好吃！"
D.Strings[78011]="呵呵呵！血！"
D.Strings[78012]="我们杀！杀杀杀！"
D.Strings[78013]="没杀掉？"
D.Strings[78014]="你为什么不死？"
D.Strings[78015]="为了觉醒教派！"
D.Strings[78016]="噢噢噢——！"
D.Strings[78017]="鲁克玛，指引我的双手。"
D.Strings[78018]="你……你不好。"
D.Strings[78019]="我们的未来里没有你的位置。"
D.Strings[78020]="不不不不……"
D.Strings[78021]="这就是前进的代价。"
D.Strings[78022]="我绝不容忍野蛮的行为。"
D.Strings[78023]="盲目的蠢货。"
D.Strings[78024]="光辉的未来在等着我们。"
D.Strings[78025]="你好，指挥官。一切应该都还井井有条吧？"
D.Strings[78026]="觉醒者之光听候你的吩咐。"
D.Strings[78027]="你今天真是容光焕发。"
D.Strings[78028]="我很高兴能加入这些新盟友。"
D.Strings[78029]="抱歉，指挥官，可我感觉有点……压抑。你有什么外出的任务能交给我吗？"
D.Strings[78030]="我将回归……鲁克玛的怀抱。"
D.Strings[78031]="这些双头飞龙是钢铁部落的财产！"
D.Strings[78032]="我的兄弟们会为我复仇的。"
D.Strings[78033]="啊哈！又有肥料送上门了！"
D.Strings[78034]="谁都休想打扰林中的神祇！"
D.Strings[78035]="将这棵……荆棘从我们的花园中铲除。"
D.Strings[78036]="你将滋养我们的神祇！"
D.Strings[78037]="我要割去你这根杂草！"
D.Strings[78038]="伟大的原祖荆兽，请享用我的身躯。"
D.Strings[78039]="我为主人献出了生命。"
D.Strings[78040]="轮回……永续……"
D.Strings[78041]="美味的杀戮！"
D.Strings[78042]="瞄准它的心脏！"
D.Strings[78043]="你的故事已经流传甚广了，$c。请允许我为你复述一下你最了不起的一些事迹。"
D.Strings[78044]="%s放下了炉石游戏盘！谁想来玩？"
D.Strings[78045]="%s打开了一包新的炉石卡牌。唔，新牌的味道真好闻！"
D.Strings[78046]="%s赢下了一局炉石比赛！"
D.Strings[78047]="|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t你被|cFFFF0404|Hspell:154938|h[熔岩激流]|h|r杀死了。与其他盟友抱团可以将伤害降到最低。"
D.Strings[78048]="|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t你被|cFFFF0404|Hspell:154938|h[熔岩激流]|h|r杀死了。与其他盟友抱团可以降低所有人受到的伤害！"
D.Strings[78049]="|TInterface\\Icons\\spell_burningbladeshaman_molten_torrent.blp:20|t你被|cFFFF0404|Hspell:154938|h[熔岩激流]|h|r杀死了。"
D.Strings[78050]="你想要尖刺？我这儿有很多尖刺。尖刺配什么都好看！让它变得更加寒光闪闪吧。"
D.Strings[78051]="祭坛上密密麻麻地分布着许多壁龛，先知的追随者们在里面放满了记忆水晶，向牺牲的伟大领袖表达哀思。这里面有数百段祈祷和缅怀之辞，从农夫到大主教，它们的主人包含了各种身份和地位的人。"
D.Strings[78052]="从熔炉来的货一直没到，所以小伙子们就提前下班了。"
D.Strings[78053]="收听先知的临终遗言。"
D.Strings[78054]="从熔炉来的武器一直没到，那里出什么事了？"
D.Strings[78055]="这些武器没有灌魔！是卡格拉兹休假了还是怎么回事？"
D.Strings[78056]="这地方需要更多的尖刺。"
D.Strings[78057]="天呐，是谁把热气关了，这里都快冻死了！"
D.Strings[78058]="克罗莫格出什么事了？我已经有段时间没听到他说话了。"
D.Strings[78059]="别来烦我！这些人类带来了让你流口水的肉！看看吧！想象一下，一口咬上去，用牙撕裂纤维，吞下去时，肉汁从骨头里涌出…… \n\n<这头狼人的眼神迷离了……>\n\n你想要什么来着？"
D.Strings[78060]="德鲁伊以树形态战斗——树边卫国。"
D.Strings[78061]="塔拉多：沙塔斯之战"
D.Strings[78062]="霜火岭：雷霆小径"
D.Strings[78063]="这些矿石箱都堆积如山了，爆裂熔炉的家伙肯定偷懒了！"
D.Strings[78064]="当侏儒钟表匠饿了，他就会饥不择时。"
D.Strings[78065]="影月谷：黑暗降临"
D.Strings[78066]="我联络了长石，可他没有反应。我敢打赌，他又撬班去跟工头乔吉聊天了。"
D.Strings[78067]="牛头人最合适监视别人，因为他们的肉上都长着眼。"
D.Strings[78068]="潜行者最爱菊花茶。"
D.Strings[78069]="在黑暗中做饭的熊猫人肯定是在做影踪“派”。"
D.Strings[78070]="你干嘛要点火！你没看见这里堆满了弹药吗？"
D.Strings[78071]="因为太冷了！！！"
D.Strings[78072]="猎人拍不出好照片，因为他们总是缺乏集中值。"
D.Strings[78073]="诅咒之地：进入黑暗之门"
D.Strings[78074]="永远不要跟牛头人吵架，因为这是真正的对牛弹琴。"
D.Strings[78075]="不会钓鱼的法师不是好厨子。"
D.Strings[78076]="我要加入斗兽场队列！"
D.Strings[78077]="塔纳安丛林：钢铁的味道"
D.Strings[78078]="饰品爆发之后，就需要冷却。"
D.Strings[78079]="当圣骑士对工资不满意时，就会发动十字军打击。"
D.Strings[78080]="纳格兰：为萨尔伸张正义"
D.Strings[78081]="杀了闯入者！吸收的过程决不能被打扰！（我们正在创造虚空之神！）"
D.Strings[78082]="开启通往生者国度的传送门！我们很快就将畅享他们的灵魂！"
D.Strings[78083]="我等不到长大以后了，我现在就要带上这颗颅骨！"
D.Strings[78084]="沃舒古内的圣光已经奄奄一息……很快我们就能扫清一切障碍，入侵生者的国度！"
D.Strings[78085]="噢，嗨！卡兹跟我说你可能会回来的。她有时会来查看我的情况并焚烧尸体。"
D.Strings[78086]="虚空的大军无穷无尽！没人能阻挡我们！"
D.Strings[78087]="你说原祖荆兽有没有颅骨？我不知道，要把它身上的藤蔓全部割断都要好长时间。"
D.Strings[78088]="沃舒古内的虚空正在增长……我们通向凡人国度的道路正在打开！灵魂的盛宴在等待着我们！"
D.Strings[78089]="你好，$r。$B$B我能从你的举手投足中看出你不是普通的冒险者。$B$B德拉诺是一个严酷的世界，许多宫殿和墓穴中都潜伏着危险的敌人。它们想要用可怕的武器和魔法毁灭这片土地。如果能占领这些地方和它们的宝藏，你和你的同伴一定能获得不菲的收益。$B$B但是，在这些地方容不得半点懈怠，因为其他冒险者也会紧随而至，只有和时间赛跑才能证明你无与伦比的实力！$B$B你准备好迎接德拉诺的新挑战了吗？"
D.Strings[78090]="请赐予我铁砧和熔炉的祝福。"
D.Strings[78091]="我们要拿你的骨头去喂狼，外来者。"
D.Strings[78092]="你休想击败战歌之魂！"
D.Strings[78093]="臣服于无可阻挡的元素之力吧！"
D.Strings[78094]="你来得正是时候。我的上一个玩具刚好坏了。"
D.Strings[78095]="我已回归大地，但我必将浴火重生！"
D.Strings[78096]="闯入我们的营地还只能算是莽撞，但来挑战我就无异于自杀了。"
D.Strings[78097]="我要享受你被我生剥血肉的惨叫声！"
D.Strings[78098]="我想看你流血。"
D.Strings[78099]="鲜血与痛苦！"
D.Strings[78100]="我要慢慢割碎你。"
D.Strings[78101]="多么出色的皮肤，等你死后，我要留下这张皮。"
D.Strings[78102]="为了战歌的荣耀！"
D.Strings[78103]="战歌之力将碾碎你！"
D.Strings[78104]="你是怎么到这的？！"
D.Strings[78105]="你竟敢跟战歌氏族作对？！"
D.Strings[78106]="你不该来这儿！"
D.Strings[78107]="就让我们继续痛苦吧！"
D.Strings[78108]="试着攻击他们的侧面……"
D.Strings[78109]="守住高地！"
D.Strings[78110]="大主教奈丽向你问好。"
D.Strings[78111]="解决了。"
D.Strings[78112]="好痛……快住手！"
D.Strings[78113]="滚出影月谷！"
D.Strings[78114]="游侠随时为你效劳。"
D.Strings[78115]="我能提议在要塞周围的树上建一些狙击手的掩体吗？"
D.Strings[78116]="我要剥掉你的皮！"
D.Strings[78117]="我会在夜班的时候巡视边界。"
D.Strings[78118]="这些树木提供了很好的掩护，但也可能会掩盖敌人的攻击。我们要保持警惕。"
D.Strings[78119]="你会为闯入这里付出代价的！"
D.Strings[78120]="我的鲜血……流尽了……"
D.Strings[78121]="停下那些声音！"
D.Strings[78122]="保卫议政厅！"
D.Strings[78123]="不能再让他们继续前进了！"
D.Strings[78124]="快进入防御工事，发起反击！"
D.Strings[78125]="目标已消灭。"
D.Strings[78126]="我的装备可好了。"
D.Strings[78127]="你战斗经验很丰富，萨尔。你还没有成家吗？"
D.Strings[78128]="指挥官！我提交了一份加固城墙的计划书。"
D.Strings[78129]="为了钢铁部落的荣耀！"
D.Strings[78130]="你需要修理什么东西吗？"
D.Strings[78131]="我们的力量将碾碎你！"
D.Strings[78132]="你……把她扔下了？这是战争！这种时候，家人更应该在你身边！"
D.Strings[78133]="你的追随者们需要更好的装备。我会尽力提供的。"
D.Strings[78134]="你竟敢挑战我们的力量？！"
D.Strings[78135]="你们绿皮兽人真是古怪。"
D.Strings[78136]="你的死亡就是我的荣耀！"
D.Strings[78137]="我跟艾泽拉斯的工程师们交流了一些设计图。侏儒工程学很……独特。"
D.Strings[78138]="有太多房子要造了，时间紧迫啊！"
D.Strings[78139]="他们杀了我……"
D.Strings[78140]="钢铁部落会碾碎你！"
D.Strings[78141]="快去死吧！"
D.Strings[78142]="圣光保佑着我们。"
D.Strings[78143]="虔诚的人绝不会失败！"
D.Strings[78144]="圣光指引着我的双手……"
D.Strings[78145]="我们绝不动摇！"
D.Strings[78146]="跟紧了。"
D.Strings[78147]="我要榨干你的生命！"
D.Strings[78148]="正义得到了伸张。"
D.Strings[78149]="我的妻子……我让她留在家里照顾孩子们了。"
D.Strings[78150]="我们得继续战斗。"
D.Strings[78151]="今天就是你的死期！"
D.Strings[78152]="圣光绝不会抛弃我们。"
D.Strings[78153]="我……从没这么想过。"
D.Strings[78154]="从上次进攻之后，我一直在帮忙照料伤员。"
D.Strings[78155]="我们必须保护德莱尼的核心地带。"
D.Strings[78156]="你在纷飞的战火中建立了一片净土。谢谢你，指挥官。"
D.Strings[78157]="我为圣光献出了生命！"
D.Strings[78158]="我们虽然失去了高格里克之心，但却赢得了这场战斗。要塞……暂时安全了。"
D.Strings[78159]="我的助手死了？噢，伙计……这可不妙。这已经有点超出我的职责范围了。你或许该去跟佐格谈谈。"
D.Strings[78160]="我把戒指弄丢了，该去找谁换个新的，或是再领一个呢？"
D.Strings[78161]="虽然非常混乱，但这里的落日十分温馨。"
D.Strings[78162]="这不可能！你的戒指是精妙的魔法工艺的最高杰作，是无可替代的无价之宝！$b$b不过，我的法师塔外面的佐提·轮怒就是化不可能为可能的专家。或许你可以用一些金币换取他的援手。$b$b但我不能保证。"
D.Strings[78163]="你好，$g先生:女士;。我能帮你找回失散的伙伴。"
D.Strings[78164]="虚空在召唤我……"
D.Strings[78165]="回到大地中去吧，杂种！"
D.Strings[78166]="回归圣光吧！"
D.Strings[78167]="这是对你的审判，废物。"
D.Strings[78168]="为了银月城！"
D.Strings[78169]="我好像看见了永恒……"
D.Strings[78170]="<只是站在纳鲁面前，你的心中就充满了宁静祥和的感觉。你还感受到了别的东西——那是一双警惕、关切的眼睛。或许先知维伦将永远活在纯净的纳鲁之光中。>"
D.Strings[78171]="我从小就是听着霜火岭的故事长大的，这里是霜狼的故乡。$b$b我从没想过我还能亲眼目睹全盛时期的霜狼氏族，以及他们的酋长杜隆坦。$b$b他……比我想象中……要矮一点。他的肩头压着名为领袖的重担。"
D.Strings[78172]="转身看看吧，$c。这里除了痛苦，什么都没有。"
D.Strings[78173]="黑暗在召唤……我无法抵抗。"
D.Strings[78174]="沃舒古在等待……"
D.Strings[78175]="虚空的呼唤……我听到了……"
D.Strings[78176]="虚空……在召唤……"
D.Strings[78177]="我停不下来了，也不想停！"
D.Strings[78178]="我能送你飞去任何地方……当然是要收费的！"
D.Strings[78179]="流星拳！"
D.Strings[78180]="你的纪律性太差了！"
D.Strings[78181]="你被|cFFFF0000|Hspell:177150|h[轰鸣咆哮]|h|r杀死了。离开考洛克的视线，离他的距离越远，轰鸣咆哮的伤害就越低。"
D.Strings[78182]="别碰我的辫子……"
D.Strings[78183]="在侏儒的力量面前战栗吧！"
D.Strings[78184]="侏儒的力量！"
D.Strings[78185]="小快灵！"
D.Strings[78186]="这些热砂港的地精真是该死。他们简直不放过任何一个赚黑心钱的机会！"
D.Strings[78187]="这回他们又做什么了？"
D.Strings[78188]="不留活口。"
D.Strings[78189]="痛苦会让你长长记性！"
D.Strings[78190]="快跑吧！这样会更有趣……"
D.Strings[78191]="他们开始卖纪念品了！"
D.Strings[78192]="|TInterface\\Icons\\warrior_disruptingshout.blp:20|t%s开始施放|cFFFF0000|Hspell:177155|h[瓦解怒吼]|h|r！"
D.Strings[78193]="让我看看你的鲜血！"
D.Strings[78194]="我们才勉强从黑暗之门一战中恢复过来，他们就开始开发旅游项目了？你一定是在开玩笑吧。"
D.Strings[78195]="我是在自由中死去的！"
D.Strings[78196]="我不畏惧死亡！"
D.Strings[78197]="自由……只是个谎言。"
D.Strings[78198]="我也希望这只是个玩笑。他们还将神器碎片串起来当珠宝卖。这就是他们对待无价之宝的态度！"
D.Strings[78199]="绝不……投降……"
D.Strings[78200]="贝洛克正在寻找这个神秘神器的下落，他有什么进展吗？"
D.Strings[78201]="|TInterface\\Icons\\ability_warrior_savageblow.blp:20|t%s开始施放|cFFFF0000|Hspell:177147|h[致死顺劈]|h|r！"
D.Strings[78202]="钢铁与鲜血！"
D.Strings[78203]="你不是钢铁的对手！"
D.Strings[78204]="霜火岭属于我们！"
D.Strings[78205]="他有一些线索，但目前还没有大的发现。"
D.Strings[78206]="要是我们想抢在琼斯博士之前把它弄到手，就得加快步伐了。"
D.Strings[78207]="没错，谁知道联盟会拿这么强大的武器做什么。我们必须请求更多援助，以防落得一败涂地的下场。"
D.Strings[78208]="去死吧，下等种族！"
D.Strings[78209]="为了鲁克玛的荣耀！"
D.Strings[78210]="为了通天峰！"
D.Strings[78211]="你觉得这件传说中的神器到底是什么东西？"
D.Strings[78212]="向优等种族下跪吧！"
D.Strings[78213]="你逃不出我的掌心！"
D.Strings[78214]="如果它和琼斯博士的推断一样强大，那很有可能是源自泰坦的造物。"
D.Strings[78215]="这似乎有点牵强了吧。我至今还没有发现任何证据表明泰坦和这个世界有关。"
D.Strings[78216]="不能死在……你这种……"
D.Strings[78217]="或许是这样吧，但如果能发现泰坦到过这里，那岂不是一个大发现？想想这种可能性吧！"
D.Strings[78218]="我的墙上又多了一件战利品。"
D.Strings[78219]="黑暗之门的那场大战真是可怕。你是怎么活下来的？"
D.Strings[78220]="我受了重伤，但这已经不是我第一次受伤了。我只是很激动，没想到我们的新岗哨里会有如此重大的历史发现！"
D.Strings[78221]="说的没错。但前提是历史没有拿着板斧在后头追着你砍！"
D.Strings[78222]="我的航程……结束了……"
D.Strings[78223]="我为通天峰献出了生命。"
D.Strings[78224]="我的宠物饿了。"
D.Strings[78225]="发射完毕。"
D.Strings[78226]="麦斯领主饿了。"
D.Strings[78227]="考里格！你还好吗？"
D.Strings[78228]="死亡是不可阻挡的。"
D.Strings[78229]="伦祖尔！站起来，士兵！"
D.Strings[78230]="你真是个废物。"
D.Strings[78231]="你将在我眼前融化。"
D.Strings[78232]="你竟敢反抗鲁克玛的信徒？"
D.Strings[78233]="见证鲁克玛的怒火吧！"
D.Strings[78234]="肮脏的贱种！"
D.Strings[78235]="鲁克玛……宽恕我……"
D.Strings[78236]="鲁克玛……我失败了……"
D.Strings[78237]="信徒会记住你的……"
D.Strings[78238]="干掉这些混进来的入侵者！"
D.Strings[78239]="你会像流亡者一样卑贱地死去！"
D.Strings[78240]="不要对这些贱民手软。"
D.Strings[78241]="这场战斗不属于你，陌生人。"
D.Strings[78242]="你是这个世界的祸害。"
D.Strings[78243]="可悲的爬虫！"
D.Strings[78244]="你将和流亡者一起葬身火海！"
D.Strings[78245]="烧死你们……"
D.Strings[78246]="不要相信流亡者……"
D.Strings[78247]="他们的诅咒会腐蚀你……"
D.Strings[78248]="这不是……鲁克玛的意志……"
D.Strings[78249]="这是食人魔的地盘！你不是食人魔！"
D.Strings[78250]="向莫库克臣服吧！"
D.Strings[78251]="哈！真弱！"
D.Strings[78252]="你的脑袋将成为我的收藏品！"
D.Strings[78253]="享受虚空的拥抱吧。"
D.Strings[78254]="你的脑袋很漂亮，会是个不错的战利品！"
D.Strings[78255]="你是从哪个洞里钻出来的？"
D.Strings[78256]="对于你这样的小东西来说……你很强……"
D.Strings[78257]="你是怎么做到的？"
D.Strings[78258]="莫库克马上就会干掉你！"
D.Strings[78259]="啊……新鲜的灵魂！"
D.Strings[78260]="又一条献给塔隆戈尔的灵魂！"
D.Strings[78261]="看看古尔丹的力量吧！"
D.Strings[78262]="塔隆戈尔的意志不可违背！"
D.Strings[78263]="塔隆戈尔……我的灵魂属于你……"
D.Strings[78264]="这……改变不了……什么……"
D.Strings[78265]="你很快就会跟我一样的。"
D.Strings[78266]="你已经失败了……"
D.Strings[78267]="美味的灵魂……"
D.Strings[78268]="莫格索德饿了！"
D.Strings[78269]="我们是毁灭的使者。"
D.Strings[78270]="你是有多想送死啊……"
D.Strings[78271]="凡人的血……好喝……"
D.Strings[78272]="我会再度……复活的……"
D.Strings[78273]="你迟早会……屈服的……"
D.Strings[78274]="入侵开始了！"
D.Strings[78275]="燃烧军团将吞噬一切！"
D.Strings[78276]="用鲜血淹没这座城市！"
D.Strings[78277]="奥金顿将化为瓦砾！"
D.Strings[78278]="这座城市属于燃烧军团！"
D.Strings[78279]="我看到……黑暗永存……"
D.Strings[78280]="你什么都得不到。"
D.Strings[78281]="古尔丹将剥夺你的灵魂……"
D.Strings[78282]="别来多管闲事！"
D.Strings[78283]="索克雷萨需要你的灵魂！"
D.Strings[78284]="燃烧军团指引着我们！"
D.Strings[78285]="萨格雷……必胜……"
D.Strings[78286]="我们做了……必须做的事……"
D.Strings[78287]="事情不该是这样的……"
D.Strings[78288]="征服这个世界的时机到了！"
D.Strings[78289]="它将和其他世界一样化为火海。"
D.Strings[78290]="在翠绿的火焰中燃烧吧！"
D.Strings[78291]="让这个世界血流成河！"
